\section{The Proof of the uniqueness}\label{sec:Proof of the uniqueness}
\begin{theorem}[The Uniqueness of the Limited Fourier Transform] 
    Suppose that $f_1(x),f_2(x) \in L^2(x_{\mathrm{min}},x_{\mathrm{max}})$, with $-\infty<x_{\mathrm{min}}<x_{\mathrm{max}}<\infty$. If $\int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} e^{ix\lambda} f_1(x) dx=\int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} e^{ix\lambda} f_2(x) dx=g(\lambda),\lambda\in [\lambda_{\mathrm{min}},\lambda_{\mathrm{max}}]$ (or a sequence of points converging to this interval), with $-\infty<\lambda_{\mathrm{min}}<\lambda_{\mathrm {max}}<\infty$, then we have $f_{1}(x)=f_{2}(x)$, a. e. $x\in [x_{\mathrm{min}},x_{\mathrm{max}}]$.
\label{thm:The Proof of the uniqueness}
\end{theorem}

\begin{proof} 
Since the integral equation is linear, we know that 
\begin{align}
    \int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} e^{ix\lambda} \left(f_1(x)-f_2(x)\right) dx=0.
\end{align} 
Setting $f(x)=f_1(x)-f_2(x)$, we just need to prove that 
\begin{align}\label{eqq}
   \int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} e^{ix\lambda} f(x) dx=0, ~\lambda\in [\lambda_{\mathrm{min}},\lambda_{\mathrm{max}}] 
\end{align}
implies $f(x)=0$, a. e. $x\in [x_{\mathrm{min}},x_{\mathrm{max}}]$.

First, we prove the analyticity of the complex function 
\begin{align}
    \phi(z)=\int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} e^{ix z} f(x) dx,z\in \mathbb{C}.
\end{align}

It is known that $e^{ixz}$ is analytic for $z\in \mathbb C$ to $x\in \mathbb R$, and $e^{ixz}=\sum_{n=0}^\infty \frac{i^n}{n!}z^n x^n$. Then we have 
\begin{align}\label{ser}
     \phi(z)= \int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} e^{ixz}  f(x) dx=\sum_{n=0}^\infty \frac{i^n}{n!}z^n \int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} x^n f(x) dx, 
\end{align}
For $f\in L^1(x_{\mathrm{min}},x_{\mathrm{max}})$, we have 
\begin{align}
    \left|\int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} x^n f(x) dx\right| \le \left(\max\{|x_\mathrm{min}|,|x_\mathrm{max}|\}\right)^n \int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}}|f(x)|dx.
\end{align}
The coefficients in the series $\phi(z)$ satisfy
\begin{align}
    \lim_{n\rightarrow \infty} \left(\frac{1}{n!}\right)^{1/n} \left|\int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} x^n f(x) dx\right|^{1/n}\le 
    \lim_{n\rightarrow \infty} \left(\frac{1}{n!}\right)^{1/n} \left(\int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}}|f(x)|dx\right)^{1/n}(\max\{|x_\mathrm{min}|,|x_\mathrm{max}|\})
\rightarrow 0,
\end{align}
by $\lim_{n\rightarrow\infty}  ( n!)^{1/n}=\infty$. Therefore 
the convergence radius of the series $\phi(z)$ is $\infty$, that means 
the complex function $\phi(z)$ is analytic in the complex plane. By the property of analytic function, from Eq.~(\ref{eqq}), we have 
 $\phi(z)=0, ~z\in \mathbb{C}$, namely
    \begin{align}
\int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}}f(x) dx + i z \int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} x f(x) dx + \frac{z^2}{2} i^2 \int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} x^2 f(x) dx  + \cdots + \frac{z^n}{n!} i^n\int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} x^n f(x) dx + \cdots =0, ~z\in \mathbb{C}. \label{eq:Taylor and unique I}
    \end{align}

From Eq.~(\ref{eq:Taylor and unique I}) we obtain for $z=0$
\begin{align}
\int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}}f(x) dx=0    
\end{align}
and 
\begin{align}\label{eq:Taylor and unique II}
        & iz \int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} x f(x) dx + i^2\frac{z^2}{2} \int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}}  x^2 f(x) dx  + \cdots + i^n \frac{z^n}{n!} \int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} x^n f(x) dx + \cdots =0, ~z\in \mathbb{C}.
\end{align}

Dividing both sides of Eq.~(\ref{eq:Taylor and unique II}) by $iz$, and then set $z=0$, one obtain 
\begin{align}
    \int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}}xf(x) dx=0.
\end{align} 
Repeating above process, one can obtain that
\begin{align}\label{The moment problem}
    \int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}}x^n f(x) dx=0, ~~n=0,1,2,\cdots
\end{align}

Since $C[x_{\mathrm{min}},x_{\mathrm{max}}]$ is dense in $L^{2}(x_{\mathrm{min}},x_{\mathrm{max}})$, then for $f(x)\in L^{2}(x_{\mathrm{min}},x_{\mathrm{max}})$ and any $\epsilon>0$, there exists $\tilde{f}(x) \in C[x_{\mathrm{min}},x_{\mathrm{max}}]$, such that 
\begin{align}
||f-\tilde{f}||_{L^{2}(x_{\mathrm{min}},x_{\mathrm{max}})}<\epsilon.    
\end{align} 
On the other hand, for $\tilde{f}(x) \in C[x_{\mathrm{min}},x_{\mathrm{max}}]$, there exists a polynomial $Q_{n}(x)$ of degree $n\in \mathbb{N}$, such that
\begin{align}
||\tilde{f}-Q_{n}||_{C[x_{\mathrm{min}},x_{\mathrm{max}}]}<\epsilon,
\end{align}
by the Weierstrass theorem. Therefore, one have
\begin{align}\label{Weierstrass}
\left\|f-Q_n\right\|_{L^2(x_{\mathrm{min}},x_{\mathrm{max}})} & \leq\|f-\tilde{f}\|_{L^2(x_{\mathrm{min}},x_{\mathrm{max}})}+\left\|\tilde{f}-Q_n\right\|_{L^2(x_{\mathrm{min}},x_{\mathrm{max}})}
\nonumber\\ 
& \leq \epsilon+\sqrt{x_{\mathrm{max}}-x_{\mathrm{min}}}\left\|\tilde{f}-Q_n\right\|_{C[x_{\mathrm{min}},x_{\mathrm{max}}]} \nonumber\\
& <\epsilon+\epsilon \sqrt{x_{\mathrm{max}}-x_{\mathrm{min}}}.
\end{align}

By using Eq.~(\ref{The moment problem}), we know that 
\begin{align}
\int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}}f(x)Q_{n}(x)dx=0.    
\end{align} 
Combined with the Cauchy inequality, we have
\begin{align}
\|f\|_{L^2(x_{\mathrm{min}},x_{\mathrm{max}})}^2 & =\int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} f^2(x) d x=\int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} \left(f^2(x)-f(x) Q_n(x)\right) d x \nonumber\\
& \leq \int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} |f(x)| \cdot\left|f(x)-Q_n(x)\right| d x \nonumber\\
& \leq\left(\int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} f^2(x) d x\right)^{\frac{1}{2}}\left(\int_{x_{\mathrm{min}}}^{x_{\mathrm{max}}} \left|f(x)-Q_n(x)\right|^2 d x\right)^{\frac{1}{2}} \nonumber\\
& =\|f\|_{L^2(x_{\mathrm{min}},x_{\mathrm{max}})}\left\|f-Q_n\right\|_{L^2(x_{\mathrm{min}},x_{\mathrm{max}})} \nonumber\\
& \leq(\epsilon+\epsilon \sqrt{x_{\mathrm{max}}-x_{\mathrm{min}}})\|f\|_{L^2(x_{\mathrm{min}},x_{\mathrm{max}})},
\end{align}
which implies that 
\begin{align}
    \|f\|_{L^{2}(x_{\mathrm{min}},x_{\mathrm{max}})}\leq \epsilon+\epsilon\sqrt{x_{\mathrm{max}}-x_{\mathrm{min}}}.
\end{align}

Letting $\epsilon\rightarrow 0$, we finally have
\begin{align}
    \|f\|_{L^{2}(x_{\mathrm{min}},x_{\mathrm{max}})}=0,
\end{align}
i. e. $f(x)=0$, a. e. $x\in [x_{\mathrm{min}},x_{\mathrm{max}}]$. The proof is completed.

\end{proof}
