\subsubsection{Cell proliferation}
\label{sec:proliferation}

Following previous work~\cite{tarle2015modeling}, we implement a model of cell density-dependent cell proliferation in which the probability that a cell divides in the time step $[t,t+\Delta{t})$ is given by
\begin{align}
\label{eq:cell_prolif}
    P_{\rm p}(\mathbf{X}^i(t);\Delta_0,\Delta t,\sigma)= 
    \begin{cases}
        \displaystyle \frac{\Delta t}{\Delta_0}\left(1-\frac{\beta\left(\mathbf{X}^i(t); \sigma\right)}{6}\right), &\quad \beta \leq 6,\\
         0, &\quad \text{otherwise,}
    \end{cases}
\end{align}
where $\Delta_0>0$ is the mean cell cycle length in the absence of crowding, $\beta\left(\mathbf{X}^i(t), \sigma\right)$ is the number of cells in the region in which the pairwise interaction force is repulsive, and six is assumed to be the maximum packing number~\cite{hales2017formal}. 

% -------------------------------------------------------------------------

\subsubsection{Collagen fibre dynamics}
\label{Subsection:Fibre dynamics}

We assume that cells evolve the collagen fibres through degradation and secretion. The equation of motion for collagen fibres is given by Equation (\ref{eq:FibreFynamics}), where $\mathbf{g}$ is as follows:
\begin{equation}
    \label{eq:FibreDynamicsEq}
    \mathbf{g}\left(\mathbf{X}^1, \mathbf{X}^2, \ldots, \mathbf{X}^{N(t)}, \mathbf{\Omega};\mathbf{\Theta}\right) = \sum_{i = 1}^{N(t)}\omega\left(\mathbf{X}^i, \mathbf{x};\sigma\right) \left[s\left(1 - \lambda_1 - \lambda_2\right)\hat{\mathbf{u}}_{\rm ave}^i \left(\hat{\mathbf{u}}_{\rm ave}^i\right)^\mathrm{T} - d\,\mathbf{\Omega}\right],
\end{equation}
where $s>0$ and $d>0$ are the collagen secretion and degradation rates per cell, respectively. The term $\left(1 - \lambda_1 - \lambda_2\right)$ ensures no fibre secretion when the space is fully occupied by collagen fibres. The secretion of collagen fibres by cell $i$ is in the direction of cell $i$'s average velocity, $\mathbf{u}_{\rm ave}^i$, over $[t-m,t]$, where\footnote{We set $\mathbf{X}^i(t-m)=\mathbf{X}^i(0)$ if $t<m$, where $\mathbf{X}^i(0)$ is the initial position for cell $i = 1$.}
\begin{align}
\label{ave tau previous vel}
    \mathbf{u}_{\rm ave}^i(\mathbf{X}^i, t; m)=\frac{1}{m}\int_{t-m}^{t}\frac{\mathrm{d}\mathbf{X}^i}{\mathrm{d}t'}\mathrm{d}t'=\frac{1}{m}\left(\mathbf{X}^i(t)-\mathbf{X}^i(t-m)\right).
\end{align}
In writing Equation~\eqref{eq:FibreDynamicsEq}, we assume a cell impacts the distribution of collagen fibres within a distance $\sigma/2$ from its centre, recalling $\sigma$ captures the cell diameter. To reflect this, we take
\begin{equation}
    \label{eq:cell-fibreWeightFunction}
    \omega\left(\mathbf{X}^i, \mathbf{x},\sigma, \omega_0\right) = 
    \begin{cases}
    1-\frac{|\mathbf{X}^i-\mathbf{x}|}{\sigma/2}, & \quad |\mathbf{X}^i-\mathbf{x}|\leq \sigma/2,\\
    0, & \quad |\mathbf{X}^i-\mathbf{x}|> \sigma/2.
    \end{cases}
\end{equation}

