\section{Computational implementation of the model}\label{Subsection:Pseudocodes}

In this paper, we use two distinct two-dimensional rectangular domains, $G$, and final time, $T$, to illustrate the results presented in later Section~\ref{sec:results}:
\begin{enumerate}[label={}, leftmargin=\parindent]
\item \textbf{Setup 1.}  $G = [0, 540] \times [0, 540] \, \mu\mathrm{m}^2$ and $T = 96$ hours, used to showcase the main features of the model.\label{setup1}
\item \textbf{Setup 2.}  $G = [0, 360] \times [0, 360] \, \mu\mathrm{m}^2$ and $T = 60$ hours, used to investigate the effects of different collagen fibre initial conditions and cell properties on dynamics.\label{setup2}
\end{enumerate}
We impose periodic boundary conditions for the cells, and the domain $G$ is discretised as $G_\delta$ with a grid size of $\delta = 2 \, \mu\mathrm{m}$, and the numerical time step is set to $\Delta{t}=1$ minute. The initial conditions are listed in Supplementary Information Section \ref{Sec:ICS}. The collagen fibre field, $\mathbf{\Omega}$, is discretised on $G_\delta$ as $\mathbf{\Omega}_\delta$. At each time step we
\begin{enumerate}
    \item \sloppy calculate cell $i$'s random motility force $\boldsymbol{\xi}^i$ and cell--cell interaction forces $\sum_{j = 1, j \neq i}^{N(t)}\mathbf{F}\left(\mathbf{X}^i-\mathbf{X}^j\right)$ (see Section~\ref{sec:CellDynamics});
    \item extract $\mathbf{\Omega}_\delta$ at cell $i$'s centre using linear interpolation to obtain the matrix $\hat{\mathbf{M}}$ for contact guidance (see Equation~\eqref{eq:M_rm}).
\end{enumerate}
We then update all cell positions according to Equation~\eqref{cellDynamics}, and update the discretised collagen fibre field $\mathbf{\Omega}_\delta$ according to Equations (\ref{eq:FibreDynamicsEq})--(\ref{ave tau previous vel}).
Finally, we iterate over the $N(t)$ cells to let each cell proliferate with probability $P_{\rm p}$ defined in Equation~\eqref{eq:cell_prolif}. The daughter cell is placed a distance $\sigma/2$ away at an angle sampled from the uniform distribution $U[0, 2\pi]$.

Algorithm~\ref{pseudocode} provides the pseudocode for the numerical simulation of the model. The differential equations are solved using the forward Euler method~\cite{hairer1987solving} with time step $\Delta t$, and the integrals are approximated using the midpoint rule~\cite{zorn2002calculus}. Initial conditions for each simulation in Section~\ref{sec:results} are stated and visualised in Supplementary Information (Section~\ref{Sec:ICS}). Python codes to simulate the model are available at \url{https://github.com/YuanYIN99/ECMcell_ContactGuidance_HybridModel.git}

\bigskip

% -------------------------------------------------------------------------

\begin{algorithm}[h]
  \caption{Collective cell migration in a fibrous environment.}

  \begin{algorithmic}[1]
    \medskip
    \State \textbf{Input}: \\
    Initialisation: discretised rectangular domain $G_\delta$; current time $t=0$, time step $\Delta t$, and final time $T$; $N(t)$ cell locations $\mathbf{X}^1(t), \mathbf{X}^2(t), \ldots, \mathbf{X}^{N(t)}(t)$; discretised collagen fibre field $\mathbf{\Omega}_{\delta}$; parameters $\mathbf{\Theta}$ listed in Table~\ref{tab:ParamAndVar}.

    \State

    \While{$t + \Delta t \leq T$} \\

    \For{cell $i$ in $N(t)$ cells, sequentially}
      \If{cell $i$ at position $\mathbf{X}^i(t)$ has fewer than six repulsive neighbours}
        \State Let cell $i$ proliferate with probability $P_{\rm p}$ given by Equation~\eqref{eq:cell_prolif}).
        \EndIf
      \EndFor\\

      \For{all cells \( i =1, 2, \ldots, N(t) \), in parallel}
      \State Sample $\boldsymbol{\xi}^i$ 
      (see Section~\ref{sec:CellDynamics}).

      \State \parbox[t]{\dimexpr\linewidth-\algorithmicindent}{Loop through cells $j \neq i$ and calculate $\sum_{j = 1, j \neq i}^{N(t)}\mathbf{F}\left(\mathbf{X}^i-\mathbf{X}^j\right)$ (see Section~\ref{sec:CellDynamics}).\strut}

       \State \parbox[t]{\dimexpr\linewidth-\algorithmicindent}{Extract $\mathbf{\Omega}_\delta$ at $\mathbf{X}^i$ and calculate the contact guidance matrix $\hat{\mathbf{M}}$ by Equation~\eqref{eq:M_rm}.\strut}

       \State \parbox[t]{\dimexpr\linewidth-\algorithmicindent}{Migrate cell $i$ based on Equation~\eqref{cellDynamics} to obtain $\mathbf{X}^i( t+\Delta t)$. Record its average velocity according to Equation~\eqref{ave tau previous vel}.\strut}

      \EndFor\\

      \For{cell $i$ in $N(t)$ cells, sequentially}

        \State \parbox[t]{\dimexpr\linewidth-\algorithmicindent}{Find the grid points that are impacted by cell $i$ at $\mathbf{X}^i(t)$ through secretion and degradation. Update the collagen fibre distribution dynamics on those grid points based on Equation~\eqref{eq:FibreDynamicsEq} to obtain $\mathbf{\Omega}_{\delta}(\mathbf{x}, t+\Delta t)$.\strut}

      \EndFor\\

      \State Step in time: $t = t + \Delta t$.
    \EndWhile\\
    \State \textbf{Return} $\mathbf{X}^i$ and $\mathbf{\Omega}_{\delta}$ at times $t=0, \Delta t, 2\Delta t, \ldots, T$.
  \end{algorithmic}
  \medskip
  \label{pseudocode}
\end{algorithm}

