\centering
\includegraphics[width=1.0\textwidth]{Fig4.png} \\
\vspace{0.8cm}
\caption{\textbf{Dynamics of collagen degrading and secreting phenotypes.} (a) collagen degrading phenotypes display enhanced invasion. Here, the initial conditions have $\lambda_1+\lambda_2=0.9$, $a=1-\lambda_2/\lambda_1=0.9$, vertical $\hat{\mathbf{v}}_1$ and horizontal $\hat{\mathbf{v}}_2$. (b): collagen-secreting phenotypes promote anisotropic cell invasion and collagen patterns. Here the initial conditions have $\lambda_1+\lambda_2=0.1$, $a=1-\lambda_2/\lambda_1=0.9$, vertical $\hat{\mathbf{v}}_1$ and horizontal $\hat{\mathbf{v}}_2$. Simulation setup: Setup2 in Section~\ref{Subsection:Pseudocodes}. The initial conditions are visualised in Figure~\ref{fig:ICs} in Supplementary Information (Section~\ref{Sec:ICS}), with $100$ cells, and results are displayed at $t=36$ hours. The pale yellow shading denotes a region devoid of collagen fibres.} 
\label{Fig4}
\end{figure}

