\title[] {Average Nikolskii factors for random diffusion polynomials on closed Riemannian manifolds}

\author[]{Yun Ling} \address{School of Mathematical Sciences, Capital Normal
University, Beijing 10004,
China}
\email{lingyun0503@yeah.net}

\author[]{Heping Wang} \address{School of Mathematical Sciences, Capital Normal
University, Beijing 100048,
China}
\email{wanghp@cnu.edu.cn}

\keywords{Random diffusion polynomials; Average Nikolskii factors}
\subjclass[2020]{26D05, 42A05}
\begin{abstract}
For $1\le p,q\le \infty$, the Nikolskii factor for a diffusion
polynomial $P_{\a}$ of degree at most $n$ is defined by
$$N_{p,q}(P_{\a})=\frac{\|P_{\a}\|_{q}}{\|P_{\a}\|_{p}},\ \ P_{\a}(\x)=\sum_{k:\lambda_{k}\leq n}a_{k}\phi_{k}(\x),$$
where $\a=\{a_k\}_{\lz_k\le n}$,  and
$\{(\phi_k,-\lambda_k^2)\}_{k=0}^\infty$ are the eigenpairs of the
Laplace-Beltrami operator $ \Delta_{\mathbb M}$ on a closed smooth
Riemannian manifold $\mathbb M$ with normalized Riemannian measure.
 We study this average
Nikolskii factor for random diffusion polynomials with independent
$N(0,\sigma^{2})$ coefficients and obtain  the exact orders. For
$1\leq p<q<\infty$, the average Nikolskii factor is of order
$n^{0}$ (i.e., constant), as compared to the worst case bound of
order $n^{d(1/p-1/q)}$,  and for $1\leq p<q=\infty$,  the average
Nikolskii factor is of order $(\ln n)^{1/2}$ as compared to the
worst case bound of order $n^{d/p}$.
\end{abstract}
