 Algebraically, in case (I),  twisting parameter $t$ is the following function of the intersection numbers:
 \begin{equation}\label{eq:t-equation}
 t=\begin{cases}
n- (n''+A-C)/2 &\tn{if}\quad  n'\leq n''\\
(n'-A-C)/2& \tn{if}\quad  n'\geq n''\;.
 \end{cases}
 \end{equation}
 In case (II), we get the simpler equations
$$
 t=\begin{cases}
n- (n''-C) &\tn{if}\quad  n'\leq n''\\
n'-C& \tn{if}\quad  n'\geq n''\;.
\end{cases}
$$


In the special case of $n=0$, the formulas for $n'(t)$ and $n''(t)$ in cases (I) and (II) simplify to 
 $$
 \aligned
 &n'(t)=n''(t)=|2t|+C,\\
 &n'(t)=n''(t)= |t|+C,
 \endaligned
 $$
 respectively.  Therefore, the standard convention (see Convention~\ref{stdConvn=0}) requires taking $t=\frac{n'-C}{2}\geq 0$ in case (I) and $t=n'-C\geq 0$ in case II as the twist coordinate; see more about this in the remark below. \\

In conclusion, having parametrized the multicurves with DT coordinates, the embedding  $\iota_\cC$ comes from the piecewise linear embedding
\begin{equation}\label{iotaC}
\aligned
&\mc{D}=\lrc{(n,t)\in \R^2\colon n\geq 0, ~~t\geq 0~\tn{if}~n=0}^{3g-3} \lra \R_{\geq 0}^{9g-9},\\
&(n_1,\ldots,n_{3g-3},t_1,\ldots,t_{3g-3})\lra \big(n_1,\ldots,n_{3g-3}, n'_1(n,t), \ldots , n'_{3g-3}(n,t),n''_1(n,t), \ldots , n''_{3g-3}(n,t)\big)
\endaligned
\end{equation}
defined by explicit equations in Theorem~\ref{ThmA}.\\

Each linear piece $\La_\ell$ of the image $\La=\iota_\cC\big(\mathcal{F}\big)$, and thus the corresponding subdomain of $\cD$ on which $\iota_\cC$ is linear, is determined by a set of linear inequalities $I_{\ell,1}\geq 0, \ldots, I_{\ell,k_\ell}\geq 0$ coming from different possibilities of the $\tn{max}$ functions in Theorem~\ref{ThmA} and the absolute value function. More precisely, these inequalities are 
$$
n_i\geq n_j+n_k~~~\tn{or}~~~n_i\leq n_j+n_k
$$
in each pair of pants $F(a_i,a_j,a_k)$,
$$
\wt{n}_1+\wt{n}_3-n \geq 0 ~\tn{or}\leq 0\quad \tn{and}\quad  \wt{n}_2+\wt{n}_4-n\geq 0~\tn{or}\leq 0
$$
in every adjacent pair of shrunken pairs of pants as in Theorem~\ref{ThmA}, and 
$$
n'_i\geq n_i''~\tn{or}~n_i''\geq n'_i\qquad \forall~i=1,\ldots,3g-3,
$$
which determine the value/sign of $t$.\\

Therefore, each cone $\La_\ell$ is a convex rational polyhedral cone obtained by intersecting the image of a linear embedding $L_\ell \colon \R^{6g-6}\lra \R^{9g-9}$ with $\R_{\geq 0}^{9g-9}$ and the positive half-spaces defined by rational linear inequalities $I_{\ell,1}\geq 0, \ldots, I_{\ell,k_\ell}\geq 0$.\\

Furthermore, since $\La$ is a cone over $S^{6g-5}$, each (maximal) $\La_\ell$ is a cone over one of the $(6g-7)$-dimensional polygons $P_\ell$ in a polyhedral decomposition $P=\bigcup_\ell P_\ell$ of piece-wise linearly embedded $S^{6g-5}\subset \De_{9g-10}$. \\

It is clear from the formulas in Theorem~\ref{ThmA}, \eqref{Pants-coordinates_e}, and \eqref{eq:t-equation} that $\iota_\cC(\cS')$ contains $\La \cap 4 \N^{9g-9}$. Therefore, the image of $\cS'$ in each $\Lambda_\ell$ is a finite-index submonoid of $\Lambda_\ell\cap \N^{9g-9}$.\qed

\begin{remark}\label{t-issue}
The cone $\La$ is a closed cone, while the domain $\mc{D}$ of $\iota_\cC$ is a half-open subcone of $\R^{6g-6}$. One can identify $\mc{D}$ with the closed singular flat manifold
$$
(\R^2/\pm)^{3g-3}
$$ 
by identifying the (included in $\mc{D}$) positive $t$-axis (i.e. $n=0$ and $t\geq 0$) and the (excluded in $\mc{D}$) negative $t$-axis in $\R_{\geq 0}\times \R$ of the closed cone 
$$
\ov{\mc{D}}=(\R_{\geq 0} \times \R)^{3g-3}.
$$
The map \eqref{iotaC} continuously extends to a piecewise linear map
$$
\ov{\mc{D}}\lra  \R_{\geq 0}^{9g-9}
$$
that identifies the equivalent points in $\partial \ov{\mc{D}}$ above in the image; i.e. $\iota_\cC$ can be seen as a piecewise linear map
$$
(\R^2/\pm)^{3g-3}\lra \R_{\geq 0}^{9g-9}
$$
between the two closed cones.\\

Since $n=0$ belongs to the intersection of two different $\La_\ell$s corresponding to inequalities $n'\geq n''$ and $n''\geq n'$ (intersecting along $n'=n''$), the preimage of each $\La_\ell$ can be identified with a closed cone $\wt\La_\ell$ in $\ov{\mc{D}}$ restricted to which $\iota_\cC$ is a linear function into $\R_{\geq 0}^{9g-9}$. If we approach $n'=n''$ from the side where $n'\geq n''$, we get the non-negative value $t=\frac{n'-C}{2}$ in the limit. If we approach $n'=n''$ from the side where $n''\geq n'$, we get the negative value $t=-\frac{n'-C}{2}$ in the limit. These two possibilities are identified in 
$$
(\R^2/\pm)^{3g-3}=\ov{\mc{D}}/\sim,\quad (n,t)\sim (n',t') \Leftrightarrow  \forall~i=1,\ldots,3g-3 : \begin{cases}
(n_i,t_i)=(n'_i,t'_i)&\tn{if}\quad n_i\neq 0\\
t_i=\pm t'_i&\tn{if}\quad n_i=n'_i= 0.
\end{cases}
$$
\end{remark}

\begin{corollary}
Thinking of DT coordinates as points in 
$$
(\R^2/\pm)^{3g-3},
$$ 
there is a decomposition 
$$
(\R^2/\pm)^{3g-3}=\bigcup_{\ell} \wt{\La}_\ell,
$$
where each $\wt\La_\ell$ can be identified with a convex rational polyhedral cone in $\ov{\mc{D}}=(\R_{\geq 0} \times \R)^{3g-3}$, and 
$$
L_\ell=\iota_\cC|_{\wt\La_\ell}\colon \wt\La_\ell\lra \La_\ell\subset \R_{\geq 0}^{9g-9}
$$ 
is a linear identification.
\end{corollary}

\begin{convention}\label{new-convention}
The discussion above shows that for every $\ell$ and each pants curve $a\in\cP$, depending on whether $n'\geq n''$ or $n''\geq n'$ on $\La_\ell$, Convention~\ref{stdConvn=0} for the twist coordinate along $a$ when $n=0$ must be modified to $t\geq 0$ or $t\leq 0$ so that $L_\ell$ can be continuously extended to a linear identification $\wt\La_\ell\lra \La_\ell$ between two closed cones; i.e., the convention will depend on the cone in which $\mf{m}$ is considered as an element.
\end{convention}



\section{Proof of Theorems~\ref{ThmC} and~\ref{ThmD}}

\subsection{Modified DT coordinates}\label{sec:modDT}
For every multicurve $\mf{m}$, let 
$$
\nu(\mf{m})=(n_1,\ldots,n_{3g-3},t_1,\ldots,t_{3g-3}) \in \N^{3g-3}\times \Z^{3g-3}
$$
denote its DT coordinates, and let
$$
\iota_{\cC}(\mf{m})=(n_1,\ldots,n_{3g-3},n'_1,\ldots,n'_{3g-3}, n''_1,\ldots,n''_{3g-3})\in \N^{9g-9}
$$
denote its intersection coordinates with the curves in the collection $\cC=(\cP,\cQ,\cQ_+)$. \\

For every pair of multicurves $\mf{m}$ and $\mf{m}'$, let 
\bEq{decomposition2}
\mf{m}\ast\mf{m}'=\sum_{s} \la_s \mf{m}_s,
\eEq
where $s$ runs over all possible smoothings of $\mf{m}\cup \mf{m}'$ (in general position), and the coefficient $\la_s$ collects the contributions of trivial components (a trivial curve contributes $-2$) appearing in a smoothing. \\ 

It is clear that for every curve $c$ and every smoothing $\mf{m}_s$ in \eqref{decomposition2}, we have 
$$
i(\mf{m}_s,c)\leq i(\mf{m},c)+ i(\mf{m}',c),
$$
with equality if and only if the smoothing $\mf{m}_s$ does not form any bigon with $c$ (assuming $\mf{m}$ and $\mf{m}'$ were originally positioned to avoid any bigons with $c$). \\

With the degree of each multicurve defined as 
$$
 |\mf{m}|=\sum_{c\in \cC} i(\mf{m},c),
$$
we conclude that  
\begin{equation}\label{norm-inequality}
|\mf{m}_s|\leq |\mf{m}|+|\mf{m}'|\qquad \forall~s,
\end{equation}
with equality if and only if 
$$
\iota_{\cC}(\mf{m}_s)= \iota_{\cC}(\mf{m})+\iota_{\cC}(\mf{m}')\in \N^{9g-9}.
$$
Theorem~\ref{ThmC} states that this equality holds if and only if $\mf{m}$ and $\mf{m}'$ lie in the same cone $\La_\ell$ for some $\ell$.\\

On the other hand, the map $\mf{m} \mapsto \nu(\mf{m})$ does not behave well under the product in the sense above. The vectors $\nu(\mf{m}_s)$ on the right-hand side of \eqref{decomposition} can behave somewhat erratically if there are $U$-arcs in the standard presentations of $\mf{m}$ and $\mf{m}'$. For instance, in the local Figure~\ref{curve-mult}, the $(n,t)$-coordinates of $\mf{m}$ and $\mf{m'}$ are 
$$
\nu(\mf{m})=\big((2,0,0),(0,0,0)\big)\quad \tn{and}\quad \nu(\mf{m}')=\big((0,1,1),(0,0,0)\big)
$$ 
while the $(n,t)$-coordinates of neither of their two smoothings is equal to the sum of these vectors. More precisely, we have 
$$
\nu(\mf{m}_{s_1})=\big((2,1,1),(0,1,0)\big)\quad \tn{and}\quad \nu(\mf{m}_{s_2})=\big((2,1,1),(1,0,-1)\big)
$$
and both have non-trivial twist coordinates.\\
