\section{Implementation with the lattice Boltzmann method} \label{sec:algorithm}

In this section, we describe the full algorithm for moving boundary problems implemented with the lattice Boltzmann method (LBM) based on Ref.~\cite{Suzuki2011, Inamuro2021}.
We use the D2Q9 lattice for two-dimensional (2D) simulations and the D3Q15 lattice for three-dimensional (3D) simulations.
In the following, we describe the algorithm for a 2D rigid body moving in a 2D flow field, and we use the non-dimensional variables defined in \ref{sec:nondim}.
Note that the same notation as in section~\ref{sec:method} is used for the non-dimensional variables.
We can simply extend the 2D algorithm to the 3D one, except for the description of the body motion. 
If the body is a 3D rigid body, we must apply a 3D coordinate transformation using Euler angles or quaternions. 
The description is complicated so is omitted here. 
For more details about the equations of motion of a 3D rigid body, please see Ref.~\cite{Suzuki2011}.

We use a weak coupling scheme which alternately solves for the body and fluid dynamics, both with the same time step $\Delta{t}$.
In addition, we use the diffusive time scale for the LBM, i.e., $\Delta{t} = {\rm Sh} \Delta{x}$, where ${\rm Sh}$ is the Strouhal number and $\Delta{x}$ is the lattice spacing.
Thus, even in the equation of body motion, the time derivative terms are accompanied by ${\rm Sh}$.
See also \ref{sec:nondim}.

In the present study, we use the forcing scheme which is consistent with the fractional-step approach given in Eq.~(\ref{eq:uast}) and (\ref{eq:frac2}).
Note that the forcing scheme proposed by Guo et al.~\cite{Guo2002} is not exactly consistent with Eq.~(\ref{eq:uast}) and (\ref{eq:frac2}) because it includes two forcing steps where not only the distribution functions but also the flow velocity itself are corrected by the volume force~\cite{Kang2011}.

\subsection{Full algorithm for moving boundary problems} \label{sec:fullalgorithm}

\begin{enumerate}
 \item Starting from the data at time $t$, update the velocity $\bm{U}_{\rm c}$ and angular velocity ${\Omega}_{\rm c}$ of the center of mass (COM) of the body by
 \begin{align}
  M {\rm Sh}\frac{\bm{U}_{\rm c}(t+\Delta{t}) - \bm{U}_{\rm c}(t)}{\Delta{t}} &=  \bm{F}_{\rm tot}(t) + \bm{F}_{\rm in}(t) + M \left( 1- \frac{1}{\gamma} \right)\bm{G}, \label{eq:Euler1}\\
  {I} {\rm Sh}\frac{{\Omega}_{\rm c}(t+\Delta{t}) - {\Omega}_{\rm c}(t)}{\Delta{t}} &= {T}_{\rm tot}(t) + {T}_{\rm in}(t),\label{eq:Euler2}
 \end{align}
 where $M$ and $I$ are the mass and inertial moment of the body, respectively, and $\bm{G}$ is the gravitational acceleration. 
 The fluid force $\bm{F}_{\rm tot} + \bm{F}_{\rm in}$ and torque ${T}_{\rm tot} + {T}_{\rm in}$ are given by
 \begin{align}
  \bm{F}_\text{tot}(t)&= -\sum_{\bm{x}}\bm{g}(\bm{x},t) (\Delta{x})^2, \label{eq:fex_sabun} \\
  {T}_\text{tot}(t)&= -\sum_{\bm{x}}\left[ (x-{X}_\text{c}(t)) {g}_y(\bm{x},t) - (y-{Y}_\text{c}(t)) {g}_x(\bm{x},t) \right] (\Delta{x})^2 \label{eq:tex_sabun} 
 \end{align}
 and 
 \begin{align}
  \bm{F}_\text{in}(t) &= {\rm Sh}\frac{\bm{P}_\text{in}(t)-\bm{P}_\text{in}(t-\Delta{t})}{\Delta t}, \\
  {T}_\text{in}(t) &= {\rm Sh}\frac{{L}_\text{in}(t)-{L}_\text{in}(t-\Delta{t})}{\Delta t}, \label{eq:fin_Lp}
 \end{align}
 where $\bm{P}_{\rm in}$ and $L_{\rm in}$ are the linear and angular momentum of the fluid inside the body.
 The Lagrangian point approximation is used for the internal mass effects $\bm{F}_{\rm in}$ and $T_{\rm in}$ (see Ref.~\cite{Suzuki2011} for more detail).

 \item Update the COM position $\bm{X}_{\rm c}$ and angle $\Theta_{\rm c}$ of the body by
 \begin{align}
  {\rm Sh} \frac{\bm{X}_{\rm c}(t+\Delta{t}) - \bm{X}_{\rm c}(t)}{\Delta t} &= \bm{U}_\text{c}(t), \label{eq:Euler3} \\
  {\rm Sh} \frac{\Theta_{\rm c}(t+\Delta{t}) - \Theta_{\rm c}(t)}{\Delta t} &= \Omega_{\rm c}(t). \label{eq:Euler4} 
 \end{align}

 \item Update the position $\bm{X}_k$ and velocity $\bm{U}_k$ of the boundary points by
 \begin{align}
  \bm{X}_{k}(t+{\Delta t}) &= \bm{X}_{\rm c}(t+\Delta t) + \mathcal{R}(t+ \Delta t) \cdot \left[ \bm{X}_{k}(0)-\bm{X}_{\rm c}(0) \right], \label{eq:update_Xk} \\
  \bm{U}_{k}(t+{\Delta t}) &= \bm{U}_{\rm c}(t+\Delta t) + {\rm Sh}\frac{\text{d} \mathcal{R}}{\text{d}t}(t+ \Delta t) \cdot\left[ \bm{X}_{k}(0)-\bm{X}_{\rm c}(0) \right], \label{eq:update_Uk}
 \end{align}
 where $\mathcal{R}$ is the two-dimensional rotational matrix given by
 \begin{align}
  \mathcal{R}(t) = \left[
  \begin{array}{rr}
   \cos\Theta_{\rm c}(t) & -\sin\Theta_{\rm c}(t)  \\
   \sin\Theta_{\rm c}(t) &  \cos\Theta_{\rm c}(t)  
  \end{array}
  \right].
 \end{align}
 The time derivative $\text{d} \mathcal{R}/\text{d}t$ of this matrix is given by
 \begin{align}
  {\rm Sh}\frac{\text{d} \mathcal{R}}{\text{d}t}(t) = \Omega_{\rm c}(t) \left[
  \begin{array}{rr}
   - \sin\Theta_{\rm c}(t) & -\cos\Theta_{\rm c}(t)  \\
   \cos\Theta_{\rm c}(t) &  - \sin\Theta_{\rm c}(t)  
  \end{array}
  \right].
 \end{align}

 \item Compute the temporary distribution functions $f^*_i$ ($i=1,\ldots, 9$) by
 \begin{equation}
  f^*_i(\bm{x}+\bm{c}_i \Delta{x},t+\Delta{t}) = f_i(\bm{x},t) - \frac{1}{\tau}\left[ f_i(\bm{x},t) - f^{\rm eq}_i(p(\bm{x},t),\bm{u}(\bm{x},t))\right], 
 \end{equation}
 where $\bm{c}_i$ is the lattice velocity, 
 and $f^{\rm eq}_i$ is the local equilibrium distribution function given as
 \begin{equation}
  f^{\rm eq}_i (p,\bm{u}) = E_i \left[ 3p + 3\bm{c}_i \cdot \bm{u} + \frac{9}{2}(\bm{c}_i \cdot \bm{u})^2 - \frac{3}{2}\bm{u} \cdot \bm{u}\right],
 \end{equation}
 where $p$ and $\bm{u}$ are the pressure and flow velocity, respectively, and $E_i$ is the weight coefficient depending on the lattice model.

 \item Compute the temporary velocity $\bm{u}^*$ by
 \begin{equation}
  \bm{u}^*(\bm{x},t+\Delta{t}) = \sum_{i=1}^9 \bm{c}_i f^*_i(\bm{x},t+\Delta{t}).
 \end{equation}

 \item Compute the volume force $\bm{g}$ through the accelerated multi-direct-forcing IBM as follows:
 \begin{description}
  \setlength{\leftskip}{10mm}
  %
  \item[Step 0.]
  Compute the initial volume force at the boundary points of the body: 
  \begin{equation}
   \bm{g}_1(\bm{X}_k,t+\Delta{t})= \omega \rho_{\rm f} {\rm Sh}\frac{\bm{U}_k-\bm{u}^*(\bm{X}_k,t+\Delta{t})}{\Delta{t}}. \label{eq:step0}
  \end{equation}
  %
  \item[Step 1.]
  Compute the volume force at the lattice points during the $\ell $th iteration:
  \begin{equation}
   \bm{g}_{\ell }(\bm{x},t+\Delta{t})=\sum_{k=1}^{N}\bm{g}_{\ell }(\bm{X}_k,t+\Delta{t})\ W(\bm{x}-\bm{X}_k)\ \Delta{V}_k. \label{eq:distri}
  \end{equation}
  %
  \item[Step 2.]
  Correct the flow velocity at the lattice points:
  \begin{equation}
   \bm{u}_{\ell}(\bm{x},t+\Delta{t})=\bm{u}^*(\bm{x},t+\Delta{t})+ \frac{1}{\rho_{\rm f}} \frac{\Delta{t}}{{\rm Sh}}\bm{g}_{\ell }(\bm{x},t+\Delta{t}).
  \end{equation}
  %
  \item[Step 3.]
  Interpolate the flow velocity at the boundary {points} of the body:
  \begin{equation}
   \bm{u}_{\ell}(\bm{X}_k,t+\Delta{t})=\sum_{\bm{x}}\bm{u}_{\ell}(\bm{x},t+\Delta{t})\ W(\bm{x}-\bm{X}_k)\ (\Delta{x})^2.
  \end{equation}
  %
  \item[Step 4.]
  If the error in $\bm{u}_{\ell}(\bm{X}_k,t+\Delta{t})$ from the no-slip condition is not sufficiently small, 
  then correct the volume force at the boundary points of the body and return to {\bf Step 1}:
  \begin{equation}
   \bm{g}_{\ell +1}(\bm{X}_k,t+\Delta{t})=\bm{g}_{\ell }(\bm{X}_k,t+\Delta{t})+ \omega \rho_{\rm f} {\rm Sh}\frac{\bm{U}_k-\bm{u}_{\ell}(\bm{X}_k,t+\Delta{t})}{\Delta{t}}. \label{eq:step4}
  \end{equation}
  If the error from the no-slip boundary condition is sufficiently small, then go to {\bf{Step 5}}. 
  %
  \item[Step 5.]
  Determine the volume force at the lattice points at time $(t+\Delta{t})$:
  \begin{equation}
   \bm{g}(\bm{x},t+\Delta{t})=\bm{g}_{\ell}(\bm{x},t+\Delta{t}). \label{eq:step5}
  \end{equation}
 \end{description}

 \item Update the distribution functions $f_i$ by
 \begin{equation}
  f_i(\bm{x},t+\Delta{t})=f^*_i(\bm{x},t+\Delta{t}) + 3\Delta{x}E_i\bm{c}_i \cdot \bm{g}(\bm{x},t+\Delta{t}). \label{eq:kousin}
 \end{equation}

 \item Update the pressure $p$ and flow velocity $\bm{u}$ by
 \begin{align}
  p(\bm{x},t+\Delta{t}) &= \frac{1}{3}\sum_{i=1}^{9} f_i(\bm{x},t+\Delta{t}), \\
  \bm{u}(\bm{x},t+\Delta{t}) &= \sum_{i=1}^9 \bm{c}_i f_i(\bm{x},t+\Delta{t}).
 \end{align}
\end{enumerate}

\subsection{Non-dimensional variables} \label{sec:nondim}

In \ref{sec:fullalgorithm}, we use the following non-dimensional variables defined by a characteristic length $\hat{L}$, 
a characteristic particle speed $\hat{c}$, a characteristic time scale $\hat{t}_0 = \hat{L}/\hat{U}$ where $\hat{U}$ is a characteristic flow speed, 
and a fluid density $\hat{\rho}_\text{f}$: 
\begin{align}
 \left. \begin{array}{lll}
  \bm{c}_i = \hat{\bm{c}}_i/\hat{c}, & \bm{x} = \hat{\bm{x}}/\hat{L}, & t=\hat{t}/\hat{t}_0, \\
  \Delta{x} = \Delta{\hat{x}}/\hat{L}, & \Delta{t} = \Delta{\hat{t}}/\hat{t}_0, &\\
  f_i=\hat{f}_i/\hat{\rho}_\text{f}, & \bm{u} = \hat{\bm{u}}/\hat{c}, & p = \hat{p}/(\hat{\rho}_\text{f}\hat{c}^2), \\
  \nu = \hat{\nu }/(\hat{c}\hat{L}), & \bm{g} = \hat{\bm{g}}\hat{L}/(\hat{\rho}_\text{f}\hat{c}^2), &  \\
  \bm{X}_k= \hat{\bm{X}}_k/\hat{L} & \bm{U}_k= \hat{\bm{U}}_k/\hat{c}, & \\ 
  \bm{X}_\text{c}= \hat{\bm{X}}_\text{c}/\hat{L} & \bm{U}_\text{c}= \hat{\bm{U}}_\text{c}/\hat{c}, & {\Omega}_\text{c} = \hat{{\Omega}}_\text{c}\hat{L}/\hat{c},  \\ 
  M=\hat{M}/(\hat{\rho}_\text{f}\hat{L}^d), & {I}=\hat{{I}}/(\hat{\rho}_\text{f} \hat{L}^{d+2}), &  \\
  \bm{F} = \hat{\bm{F}}/(\hat{\rho}_\text{f}\hat{c}^2\hat{L}^{d-1}), & {T} = \hat{{T}}/(\hat{\rho}_\text{f}\hat{c}^2\hat{L}^{d}), & \\
  \bm{F}_\text{tot} = \hat{\bm{F}}_\text{tot}/(\hat{\rho}_\text{f}\hat{c}^2\hat{L}^{d-1}), & {T}_\text{tot} = \hat{{T}}_\text{tot}/(\hat{\rho}_\text{f}\hat{c}^2\hat{L}^{d}), & \\
  \bm{F}_\text{in} = \hat{\bm{F}}_\text{in}/(\hat{\rho}_\text{f}\hat{c}^2\hat{L}^{d-1}), & {T}_\text{in} = \hat{{T}}_\text{in}/(\hat{\rho}_\text{f}\hat{c}^2\hat{L}^{d}), & \\
  \bm{P}_\text{in} = \hat{\bm{P}}_\text{in}/(\hat{\rho}_\text{f}\hat{c}\hat{L}^{d}), & {L}_\text{in} = {{L}}_\text{in}/(\hat{\rho}_\text{f}\hat{c}\hat{L}^{d+1}), &
 \end{array}
 \right\} \label{eq:dim1}
\end{align}
where the circumflex represents `dimensional,' and $d$ represents the spatial dimension ($d=2$ and $3$ in the two- and three-dimensional cases, respectively).

In the LBM, the time step $\Delta{\hat{t}}$ is equal to the time span during which the fluid particles travel one lattice spacing, 
that is, $\Delta{\hat{x}}/\Delta{\hat{t}}=\hat{c}$.
The non-dimensional lattice spacing is $\Delta{x} = \Delta{\hat{x}}/\hat{L}$,
and the non-dimensional time step is $\Delta{t}=\Delta{\hat{t}}/(\hat{L}/\hat{c})$ in the diffusive time scale. 
Thus, we have $\Delta t = {\rm Sh} \Delta x$ (where ${\rm Sh} = \hat{L}/(\hat{t}_0 \hat{c}) = \hat{U}/\hat{c}$ is the Strouhal number) in the diffusive time scale.
We can easily obtain $\Delta{t}={\rm Sh} \Delta{x}$ from the above relation.

\section{Volume force with iteration} \label{sec:iteration}

When we iterate the procedure of the accelerated multi-direct-forcing IBM, the volume force is given by the following recurrence relation:
\begin{equation}
\bm{g}^n_{\ell +1}(\bm{X}_k) = \bm{g}^{n}_{\ell}(\bm{X}_k) + \omega \rho_{\rm f} \frac{\bm{U}_k^n - \bm{u}_{\ell} (\bm{X}_k)}{{\Delta{t}}}, \label{eq:giterate}
\end{equation}
where 
\begin{align}
&\bm{g}^{n}_{0}(\bm{X}_k) = \bm{0}, \\
&\bm{u}_0(\bm{X}_k) = \bm{u}^*(\bm{X}_k), \\
&\bm{u}_{\ell }(\bm{X}_k) = \bm{u}^*(\bm{X}_k) + \frac{1}{\rho_{\rm f}}\tilde{\bm{g}}^n_{\ell}(\bm{X}_k) {\Delta{t}} \label{eq:ul}, 
\end{align}
and $\tilde{\bm{g}}^n_{\ell}(\bm{X}_k)$ is given by
\begin{align}
&\tilde{\bm{g}}^n_{\ell}(\bm{X}_k) = \sum_{\bm{x}}{\bm{g}}^n_{\ell}(\bm{x})W(\bm{x}-\bm{X}_k) (\Delta{x})^d, \label{eq:gtilde}\\
&{\bm{g}}^n_{\ell}(\bm{x}) = \sum_{k=1}^N {\bm{g}}^n_{\ell}(\bm{X}_k)W(\bm{x}-\bm{X}_k) \Delta{V}_k. \label{eq:gx}
\end{align}
Note that $\tilde{\bm{g}}^n_{\ell}(\bm{X}_k)$ is not generally equal to ${\bm{g}}^n_{\ell}(\bm{X}_k)$
duo to the interpolation and spreading procedures.

From Eqs.~(\ref{eq:giterate})--(\ref{eq:ul}), we have the recurrence relation of $\bm{F}^n$ as follows:
\begin{align}
&\underbrace{\sum_{k=1}^N \bm{g}^n_{\ell +1}(\bm{X}_k)\Delta{V}_k}_{- \bm{F}^n_{\ell +1}} 
= \underbrace{\sum_{k=1}^N\bm{g}^{n}_{\ell}(\bm{X}_k)\Delta{V}_k}_{-\bm{F}^n_{\ell}} + \omega \rho_{\rm f} \sum_{k=1}^N \frac{\bm{U}_k^n - \bm{u}_{\ell} (\bm{X}_k)}{{\Delta{t}}} \Delta{V}_k, \notag \\
\Longrightarrow~~&\bm{F}_{\ell+1}^n  = \bm{F}^n_{\ell}  - \underbrace{ \omega \rho_{\rm f} \sum_{k=1}^N  \frac{\bm{U}_k^n - \bm{u}^{*} (\bm{X}_k)}{{\Delta{t}}} \Delta{V}_k}_{- \bm{F}_1^n} + \omega \underbrace{\sum_{k=1}^N  \tilde{\bm{g}}^n_{\ell}(\bm{X}_k) \Delta{V}_k}_{- \tilde{\bm{F}}^n_\ell}, \notag \\
\Longrightarrow~~&\bm{F}_{\ell+1}^n  = \bm{F}^n_{\ell} + \bm{F}_1^n - \omega \tilde{\bm{F}}^n_\ell. \label{eq:fell}
\end{align}
Note that $\tilde{\bm{F}}^n_\ell$ is not generally equal to $\bm{F}^n_{\ell}$.

Now consider the relationship between $\tilde{\bm{F}}^n_\ell$ and $\bm{F}^n_{\ell}$.
By using Eq.~(\ref{eq:gtilde}) and (\ref{eq:gx}), we develop
\begin{align}
 \tilde{\bm{F}}^n_\ell &= - \sum_{k=1}^N\tilde{\bm{g}}^{n}_{\ell}(\bm{X}_k)\Delta{V}_k, \notag \\
 &=- \sum_{k=1}^N \left[ \sum_{\bm{x}}{\bm{g}}^n_{\ell}(\bm{x})W(\bm{x}-\bm{X}_k) (\Delta{x})^d \right]\Delta{V}_k, \notag \\
 &=- \sum_{k=1}^N  \sum_{\bm{x}} \left[ \sum_{j=1}^N {\bm{g}}^n_{\ell}(\bm{X}_j)W(\bm{x}-\bm{X}_j) \Delta{V}_j \right] W(\bm{x}-\bm{X}_k) (\Delta{x})^d \Delta{V}_k, \notag \\
 &=- \sum_{k=1}^N \sum_{j=1}^N {\bm{g}}^n_{\ell}(\bm{X}_j) \Delta{V}_j \underbrace{\sum_{\bm{x}}W(\bm{x}-\bm{X}_j) W(\bm{x}-\bm{X}_k) (\Delta{x})^d \Delta{V}_k}_{A_{jk}}, \notag \\
 &= - \sum_{j=1}^N {\bm{g}}^n_{\ell}(\bm{X}_j) \Delta{V}_j \underbrace{\sum_{k=1}^N A_{jk}}_{a_j}, \notag \\
 &= - \sum_{j=1}^N a_j {\bm{g}}^n_{\ell}(\bm{X}_j) \Delta{V}_j. \label{eq:mid}
\end{align}
As shown in section~\ref{sec:matrix}, the coefficient $a_j$ can be well approximated by $\lambda_{\max}$.
Thus, Eq.~(\ref{eq:mid}) can be approximated by
\begin{align}
 \tilde{\bm{F}}^n_\ell \simeq - \sum_{j=1}^N \lambda_{\rm max} {\bm{g}}^n_{\ell}(\bm{X}_j) \Delta{V}_j = - \lambda_{\max} \bm{F}^n_{\ell}. \label{eq:approx}
\end{align}

By substituting Eq.~(\ref{eq:approx}) to Eq.~(\ref{eq:fell}), we have
\begin{align}
 \bm{F}_{\ell+1}^n  \simeq  (1- \lambda_{\max} \omega ) \bm{F}^n_{\ell} + \bm{F}_1^n, 
\end{align}
This simple recurrence relation can be readily solved, and the solution is 
\begin{align}
 \bm{F}_{\ell}^n \simeq {\frac{1-(1-\lambda_{\max} \omega )^{\ell+1}}{\lambda_{\max} \omega }} \bm{F}_1^n. \label{eq:eta}
\end{align}
Thus, the effect of the iteration is confined to the coefficient of $\bm{F}_1^n$ in Eq.~(\ref{eq:eta}) given by
\begin{equation}
 \eta = \frac{1-(1-\lambda_{\max} \omega )^{\ell+1}}{\lambda_{\max} \omega }.
\end{equation}
Fig.~\ref{fig:eta} shows $\eta$ as a function of $\lambda_{\rm max} \omega$ for various iteration counts $\ell$.
Evidently, $\eta$ is constant at $1$ for $\ell=1$ and monotonically decreases with increasing $\lambda_{\rm max} \omega$ for $\ell >1$, 
and $\eta=1$ when $\lambda_{\rm max} \omega = 1$ for any value of $\ell$.
Thus, $\eta \ge 1$ for $\lambda_{\rm max} \omega \le 1$.
%If $\omega =1$ (i.e., the conventional multi-direct forcing IBM) for example, $\lambda_{\max} \omega \simeq 0.375$, and therefore $\eta \simeq 2.5$ at $\ell = 6$.

\setcounter{figure}{0}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%figB1
\begin{figure}[!tb]
 \centering
 \includegraphics[width=8cm,clip]{figB1.eps} 
 \caption{Relationship between $\eta$ and $\lambda_{\rm max} \omega$ for various iteration counts $\ell$.}
 \label{fig:eta}
\end{figure}
