\section{Preliminaries}
\label{Pre}

{\it Notation and Terminology.}
We use 
the language of $(\infty,1)$-categories.
We use the theory of {\it quasi-categories} as a model of $(\infty,1)$-categories.
Our main references are \cite{HTT}
 and \cite{HA} as well as subsequent works \cite{Kero} and \cite{RV}.
Following \cite{HTT}, we shall refer to quasi-categories
as {\it $\infty$-categories}.
To an ordinary category, we can assign an $\infty$-category by taking
its nerve, and therefore
when we treat ordinary categories we often omit the nerve $\NNNN(-)$
and directly regard them as $\infty$-categories.
Here is a list of some of the notation and conventions we frequently use:


\begin{itemize}

\item $\simeq$: categorical equivalence or homotopy equivalence.  The symbol $\simeq$ is used to indicate isomorphisms and equivalences in categories and
$\infty$-categories.

\item $\CCC^{op}$: the opposite $\infty$-category of an $\infty$-category.

\item $\Map_{\mathcal{C}}(C,C')$: the mapping space from an object $C\in\mathcal{C}$ to $C'\in \mathcal{C}$ where $\mathcal{C}$ is an $\infty$-category.


\item $\Fun(A,B)$: the function complex for simplicial sets $A$ and $B$. If $A$ and $B$ are $\infty$-categories, we regard $\Fun(A,B)$ as the functor category. 

\item $\SSS$: the $\infty$-category of small spaces ($\infty$-groupoids). We write $\wSSS$ for the $\infty$-category of spaces in an enlarged universe. 

\item $\Cat$: the $\infty$-category of small $\infty$-categories. We write $\wCat$ for the $\infty$-category of $\infty$-categories in an enlarged universe. 

\item $\Ind(\CCC)$: the Ind-category of $\CCC$.

\end{itemize}


We will use the theory of higher algebras.
We refer the reader to \cite{HA}.
Here is a list of (some) of the notation about $\infty$-operads and algebras over them that we will use:


\begin{itemize}
\label{notation2}




\item $\mathbf{E}^\otimes_n$: the $\infty$-operad of little $n$-cubes (cf. \cite[5.1]{HA}).

\item $\Alg_n(\MMM)$:
For a symmetric monoidal $\infty$-category $\MMM^\otimes$,
we write $\Alg_{n}(\MMM)$ for
the $\infty$-category of algebra objects over $\mathbf{E}^\otimes_n$ in $\MMM^\otimes$.
We refer to an object of $\Alg_{n}(\MMM)$ as an $\eenu$-algebra in $\MMM$.
If we denote by $\assoc^\otimes$ the associative operad (\cite[4.1.1]{HA}),
there is the standard equivalence $\assoc^\otimes\simeq \eone^\otimes$
of $\infty$-operads. We usually identify $\Alg_{1}(\MMM)$
with the $\infty$-category $\Alg_{\assoc}(\MMM)$, that is, the 
$\infty$-category of associative algebras in $\MMM$.




\item $\CAlg(\mathcal{M})$: the $\infty$-category of commutative
algebra objects in a symmetric
monoidal $\infty$-category $\mathcal{M}^\otimes$.
Instead of $\Alg_{\einf}(\MMM)$ or $\Alg_{\textup{comm}}(\MMM^\otimes)$
we write $\CAlg(\mathcal{M})$ for the $\infty$-category of algebra objects over the $\einf$-operad or the commutative operad in $\MMM^\otimes$. 


\item $\CAlg_k$: $\CAlg_k=\CAlg(\Mod_k)$.


\item $\Mod_R(\mathcal{M})$: 
the $\infty$-category of
$R$-module objects,
where $\mathcal{M}^\otimes$
is a symmetric monoidal $\infty$-category and $R\in \CAlg(\MMM)$.

\item $\Mod_R$: When $\MMM^\otimes$ is the symmetric monoidal $\infty$-category $\SP^\otimes$
of spectra, 
we write $\Mod_R^\otimes$
for
$\Mod_R^\otimes(\SP)$.
We denote by $\Mod_R$ the underlying category, that is, $\Mod_R(\SP)$.

\item 
$\LMod(\MMM)$:
the $\infty$-category $\Alg_{\LM}(\MMM)$ of $\LM^\otimes$-algebras
over $\LM^\otimes$: the $\infty$-operad defined in \cite[4.2.1.7]{HA}.
We may consider an object of  $\LMod(\MMM)$ to be a pair 
of $(A,M)$ such that $A$ is an associative algebra object in $\MMM$
and a left $A$-module $M$.
There is a Cartesian fibration $\LMod(\MMM)\to \Alg_{\assoc}(\MMM)\simeq \Alg_1(\MMM)$
which sends $(A,M)$ to $A$.
Another canonical morphism is the forgetful functor $\LMod(\MMM)\to \MMM$
which is informally given by $(A,M)\mapsto M$.


\item $\LMod_A(\MMM)$: the $\infty$-category of left $A$-module objects in $\MMM$.
For $A\in \Alg_1(\MMM)$, we define $\LMod_A(\CCC)$
to be the fiber of $\LMod(\CCC)\to \Alg_1(\CCC)$ over $A$ in $\Cat$.


\item $\RMod(\MMM)$: the right module version of $\LMod(\MMM)$

\item $\RMod_B(\MMM)$: the $\infty$-category of right $B$-module objects in $\MMM$.



\end{itemize}










Let $k$ denote a fixed field, which serves as the base field.
Unless otherwise stated, we adopt the cohomological index.





\subsection{Generalities on $t$-structures}








Let us recall the notion of $t$-structures on stable $\infty$-categories.
Let $\CCC$ be a stable $\infty$-category.
Recall that the homotopy category $\hhh(\CCC)$ has the structure of a triangulated category.
A $t$-structure on $\CCC$ is a pair of full subcategories $(\CCC^{\le0},\CCC^{\ge0})$ of $\CCC$
such that $(\hhh(\CCC^{\le0}), \hhh(\CCC^{\ge0}))$ is a $t$-structure on the triangulated category $\hhh(\CCC)$. The pair
is required to satisfy the following conditions:
If we write $\CCC^{\le n}$ and $\CCC^{\ge n}$ for $\CCC^{\le 0}[-n]$ and $\CCC^{\ge 0}[-n]$, respectively, then
\begin{enumerate}
\item $\CCC^{\le-1}\subset \CCC^{\le0}$ and $\CCC^{\ge1}\subset \CCC^{\ge0}$.

\item $\Hom_{\hhh(\CCC)}(C,C')=0$ for $C\in \CCC^{\le0}$ and $C'\in \CCC^{\ge1}$.

\item For any $C\in \CCC$, there exists a cofiber square 
\[
\xymatrix{
D \ar[r] \ar[d] & C \ar[d] \\
0 \ar[r] &  E
}
\]
such that $D\in \CCC^{\le0}$ and $E\in \CCC^{\ge1}$.
\end{enumerate}


Suppose that $(\CCC^{\le0},\CCC^{\ge0})$ is a $t$-structure.
The inclusion $\CCC^{\le n}\hookrightarrow\CCC$ has a right adjoint 
\[
\tau^{\le n}:\CCC\longrightarrow \CCC^{\le n},
\]
and the inclusion $\CCC^{\ge n}\hookrightarrow\CCC$
has a left adjoint 
\[
\tau^{\ge n}:\CCC\longrightarrow \CCC^{\ge n}.
\]

There exists a canonical equivalence $\tau^{\ge 0}\circ \tau^{\le0}\simeq \tau^{\le 0}\circ \tau^{\ge0}$.
We define
\[
H^0:\CCC\longrightarrow \CCC^{\le0}\cap \CCC^{\ge0}
\]
to be $\tau^{\ge 0}\circ \tau^{\le0}$ (equivalently, $\tau^{\le 0}\circ \tau^{\ge0}$).
The intersection $\CCC^{\le0}\cap \CCC^{\ge0}$ is called the heart.
The heart $\CCC^{\le0}\cap \CCC^{\ge0}$ is an abelian category (see \cite{BBD}).
We write $\CCC^{\heartsuit}=\CCC^{\le0}\cap \CCC^{\ge0}$.
We define $H^n=H^0\circ [n]:\CCC\to \CCC^{\le0}\cap \CCC^{\ge0}$ where 
$[n]$ is the $n$-fold shift (suspension) functor.







\begin{Remark}
Given a cofiber sequence $C\to C'\to C''$ in $\CCC$, there exists a canonical long exact sequence
\[
\cdots \to H^n(C)\to H^{n}(C')\to H^n(C'')\to H^{n+1}(C)\to \cdots
\]
in $\CCC^\heartsuit$ (see \cite{BBD}).
\end{Remark}




We often use the notation $(\CCC^{\le0}, \CCC^{\ge0})$ to denote a $t$-structure on $\CCC$.
Note that $\CCC^{\ge0}$ is uniquely determined by $\CCC^{\le0}$: the full subcategory $\CCC^{\ge0}$ is spanned by those objects $C'$ such that $\Map_{\CCC}(C,C')$ is contractible for any $C\in \CCC^{\le -1}$. Dually, $\CCC^{\le0}$ is uniquely determined by $\CCC^{\ge0}$.
By $(\CCC,\CCC^{\le0})$ we mean a stable $\infty$-category endowed with the $t$-structure determined by a full subcategory $\CCC^{\le0}$.











\begin{Definition}
Let $(\CCC^{\le 0}, \CCC^{\ge 0})$ be a $t$-structure on a stable $\infty$-category $\CCC$.
\begin{enumerate}
\item For any $n \in \ZZ$, the left adjoint functor $\tau^{\ge n}: \CCC \to \CCC^{\ge n}$ to the inclusion
$\CCC^{\ge n} \subset \CCC$ induces a morphism $C \to \tau^{\ge n}(C)$, determined by the unit map. For all $n \in \ZZ$, this yields the sequence
\[
C \to \cdots \to \tau^{\ge n-1}(C) \to \tau^{\ge n}(C) \to \tau^{\ge n+1}(C) \to \cdots
\]
in $\CCC$.
The $t$-structure is left complete if, for any $C \in \CCC$, the induced morphism $C \to \varprojlim_{n \in \ZZ} \tau^{\ge n}(C)$ is an equivalence.
\item The right adjoint functor $\tau^{\le n}: \CCC \to \CCC^{\le n}$ to the inclusion
$\CCC^{\le n} \subset \CCC$ induces a morphism $\tau^{\le n}(C) \to C$, determined by the counit map. For all $n \in \ZZ$, this yields the sequence
\[
\cdots \to \tau^{\le n-1}(C) \to \tau^{\le n}(C) \to \tau^{\le n+1}(C) \to \cdots \to C
\]
in $\CCC$.
The $t$-structure is right complete if, for any $C \in \CCC$, the induced morphism $\varinjlim_{n \in \ZZ} \tau^{\le n}(C) \to C$ is an equivalence.
\item The $t$-structure is left separated if $\bigcap_{n \in \ZZ} \CCC^{\le n} = 0$.
Dually, it is right separated if $\bigcap_{n \in \ZZ} \CCC^{\ge n} = 0$.
\item If $\CCC$ admits filtered colimits and the full subcategory $\CCC^{\ge 0}$ is closed under filtered colimits in $\CCC$, we say that the $t$-structure is compatible with filtered colimits.
\item The $t$-structure $(\CCC^{\le 0}, \CCC^{\ge 0})$ is accessible if the full subcategory $\CCC^{\le 0}$ is presentable.
\item Suppose that $\CCC$ has a monoidal structure. If the tensor product functor $\CCC \times \CCC \to \CCC$ sends $\CCC^{\le 0} \times \CCC^{\le 0}$ to $\CCC^{\le 0}$ and the unit object lies in $\CCC^{\le 0}$, we say that the $t$-structure is compatible with the monoidal structure.
\end{enumerate}
\end{Definition}




\begin{Remark}
If $C\in \cap_{n\in \ZZ}\CCC^{\le n}$, then $\tau^{\ge n}C\simeq0$ for all $n\in \ZZ$.
It follows that if a $t$-structure $(\CCC^{\le0}, \CCC^{\ge0})$ is left complete,
then it is left separated.
Dually, if a $t$-structure is right complete,
then it is right separated.
\end{Remark}



\begin{Example}
\label{connectivetstr}
Let $A$ be a connective associative ring spectrum, and let $\LMod_A$ be the stable $\infty$-category of left $A$-module spectra.
Define $\LMod_A^{\ge 0}$ as the full subcategory of $\LMod_A$ spanned by objects $M$ such that $\pi_n(M) = 0$ for all $n < 0$, and $\LMod_A^{\le 0}$ as the full subcategory spanned by objects $M$ such that $\pi_n(M) = 0$ for all $n > 0$.
Then $(\LMod_A^{\le 0}, \LMod_A^{\ge 0})$ defines an accessible, left complete, and right complete $t$-structure (see \cite[7.1.1.13]{HA}).
The full subcategory $\LMod_A^{\le 0}$ is also characterized as the smallest full subcategory which contains $A$ and is closed under small colimits.
Moreover, the $t$-structure is compatible with filtered colimits, as $\LMod_A^{\ge 0} \subset \LMod_A$ is closed under filtered colimits.
This $t$-structure is compatible with the monoidal structure when $A$ is an $\etwo$-algebra.
The heart $\LMod_A^{\heartsuit}$ is equivalent to the abelian category of left $\pi_0(A)$-modules.
\end{Example}

\begin{Definition}
Let $A$ be an $\eenu$-algebra in $\Mod_k$.
By convention, an $\mathbf{E}_{0}$-algebra means an object of $\Mod_k$.
We say that $A$ is $m$-coconnective if
$H^i(A)=0$ for any $i<0$ and $0<i<m$, and the canonical map $k\to H^0(A)$ is an isomorphism.
When $A$ is $1$-coconnective, we say simply that $A$ is coconnective.
We say that $A$ is locally finite if $H^i(A)$ is finite dimensional for any $i\in \ZZ$.
\end{Definition}



\begin{Proposition}
\label{tstrcoconnective}
Let $D$ be an $\eone$-algebra in $\Mod_k$.
Assume that $D$ is coconnective.
Let $\LMod_D^{\le 0}$ be the smallest full subcategory of $\LMod_D$ containing $D$ and closed under small colimits and extensions.
Let $\LMod_D^{\ge 0}$ be the full subcategory spanned by objects $M$ such that their image under the forgetful functor to $\Mod_k$ lies in $\Mod_k^{\ge 0}$, i.e., $H^i(M) = 0$ for all $i < 0$.
Then $(\LMod_D^{\le 0}, \LMod_D^{\ge 0})$ defines an accessible and right complete $t$-structure.
Moreover, it is compatible with filtered colimits.
\end{Proposition}


\Proof
When $D$ is commutative, the assertion is proved in \cite[VIII, 4.5.4]{DAG}.
The proof also works for associative algebras.
\QED



\begin{Remark}
The $t$-structure $(\LMod_D^{\le0}, \LMod_D^{\ge0})$
is not left complete in general (cf. \cite[VIII, 4.5.5]{DAG})
\end{Remark}



\begin{Remark}
When $D$ is (promoted to) an $\etwo$-algebra, then $\LMod_D$ has the canonical
monoidal structure. From the definition of 
$\LMod_D^{\le0}$ we see that $\LMod_D^{\le0}$ is closed under tensor products.
\end{Remark}


\begin{Remark}
\label{unifiedtstr}
Example~\ref{connectivetstr} and Proposition~\ref{tstrcoconnective} are unified as follows.
For $A\in \Alg_1(\SP)$ we define $\LMod_A^{\le0}$ to be the smallest full subcategory
which contains $A$ and is closed under small colimits and extensions. By \cite[1.4.4.11]{HA},
$\LMod_A^{\le0}$ determines an accessible $t$-structure on $\LMod_A$ such that $\LMod_A^{\ge0}$
consists of those objects $M$ such that $\pi_0(\Map_{\LMod_A}(A[n],M))=\pi_n(M)=H^{-n}(M)=0$ for $n>0$.
The full subcategory $\LMod_A^{\ge0}$ is closed under filtered colimits, and the $t$-structure is right complete.
When $A$ is an $\etwo$-algebra, the $t$-structure is compatible with the monoidal structure on $\LMod_A$.
As seen in Example~\ref{connectivetstr} and Proposition~\ref{tstrcoconnective}, the property of the resulting $t$-structure
depends on $A$.
\end{Remark}




\begin{Example}
Let $\CCC$ be a small stable $\infty$-category.
Let $(\CCC^{\le0}, \CCC^{\ge0})$ be a $t$-structure on $\CCC$.
Then $(\Ind(\CCC^{\le0}),\Ind(\CCC^{\ge0}))$ defines a $t$-structure on $\Ind(\CCC)$.
By the construction, the $t$-structure is compatible with filtered colimits.
If the $t$-structure on $\CCC$ is right bounded, then 
$(\Ind(\CCC^{\le0}),\Ind(\CCC^{\ge0}))$ is right complete (see \cite[VIII, Lemma 5.4.1]{DAG}).
\end{Example}



\begin{Example}
Let $X$ be a derived/spectral scheme (or more generally, derived/spectral Deligne-Mumford stack that satisfies a mild condition).
Then the stable $\infty$-category $\textup{QCoh}(X)$ of quasi-coherent sheaves on $X$ has a $t$-structure
which is accessible, left complete, and right complete. It is also compatible with filtered colimits and the monoidal structure (see \cite[VIII, 2.3.18]{DAG}).
\end{Example}


\begin{Definition}
Let $(\CCC,\CCC^{\le0})$ and $(\DDD,\DDD^{\le0})$ be stable $\infty$-categories endowed with $t$-structure.
\begin{enumerate}
\item An exact functor $F:\CCC\to \DDD$ is said to be right $t$-exact if the essential image of $\CCC^{\le0}$ is contained in $\DDD^{\le0}$.

\item An exact functor $F:\CCC\to \DDD$ is said to be left $t$-exact if the essential image of $\CCC^{\ge0}$ is contained in $\DDD^{\ge0}$.

\item An exact functor $F:\CCC\to \DDD$ is said to be $t$-exact if $F$ is right $t$-exact and left $t$-exact.

\end{enumerate}
\end{Definition}


Let $\PR_{\mathbb{S}}$ be the $\infty$-category of presentable stable $\infty$-categories (cf. \cite[Definition 5.5.3.1]{HTT}, \cite{HA}). A morphism $\CCC\to \DDD$ in $\PR_{\mathbb{S}}$ is a functor that preserves small colimits.
Let $\PRT$ be the $\infty$-category of presentable stable $\infty$-categories equipped with accessible $t$-structures.
An object of $\PRT$ is a pair $(\CCC,\CCC^{\le0})$ where $\CCC$ is a presentable stable $\infty$-category, and $\CCC^{\le0}$ is a  full subcategory
inducing a $t$-structure,
such that $\CCC^{\le0}$ itself is presentable.
A morphism $(\CCC, \CCC^{\le0})\to (\DDD,\DDD^{\le0})$ is a right $t$-exact functor which preserves small colimits.

Let $\PRTT$ be the full subcategory of $\PRT$, spanned by presentable stable $\infty$-categories equipped with accessible right complete $t$-structures.
Let $\PRTTT$ be the full subcategory of $\PRT$, spanned by presentable stable $\infty$-categories equipped with accessible left complete and right complete $t$-structures.
There exists an adjoint pair
\[
\xymatrix{
I^+: \PRTT \ar@<0.5ex>[r] &  \PRT:\widehat{R}  \ar@<0.5ex>[l]  
}
\]
such that $I^+$ is the inclusion, and the right adjoint $\widehat{R}$ carries $(\CCC,\CCC^{\le0})$
to the right completion 
\[
\widehat{R}(\CCC,\CCC^{\le0})=(\colim_{n\to \infty} \CCC^{\le n},\CCC^{\le0}) 
\]
where $\colim_{n\to \infty} \CCC^{\le n}$ is the colimit of the sequence of inclusions
$\CCC^{\le 0}\to \CCC^{\le 1}\to \CCC^{\le 2}\to \cdots\to \CCC^{\le n}\to \cdots$ in $\PR_{\mathbb{S}}$
(cf. \cite[5.5.3.4, 5.5.3.18]{HTT}). 

The left completion $\HL((\CCC,\CCC^{\le0}))$ of $(\CCC,\CCC^{\le0})$
is defined as
$\lim_{n\to -\infty}\CCC^{\ge n}$ in $\PR_{\mathbb{S}}$
of the sequence 
\[
\cdots \to \CCC^{\ge n-1}\to \CCC^{\ge n}\to \CCC^{\ge n+1} \to \cdots
\]
induced by truncations.
We usually write $\HL(\CCC)$ for $\HL((\CCC,\CCC^{\le0}))$.
If $(\CCC,\CCC^{\le0})\in \PRTT$, then the left completion $\HL(\CCC)$ is also accessible and right complete (see \cite[VIII, 4.6.13]{DAG}).
There exists an adjoint pair
\[
\xymatrix{
\HL :\PRTT \ar@<0.5ex>[r] &  \PRTTT:I^{\pm}  \ar@<0.5ex>[l]  
}
\]
such that $I^\pm$ is the inclusion, and $\HL$ is the left adjoint given by the left completion.

{\it Symmetric monoidal structures.}
We recall the symmetric monoidal structure on $\PR_{\mathbb{S}}$ (see \cite[4.8]{HA}).
Let $\mathcal{B}$ and $\CCC$ be presentable $\infty$-categories. 
The tensor product of $\mathcal{B}$ and $\CCC$
is defined as an object
$\mathcal{B}\otimes \CCC$ in $\PR_{\mathbb{S}}$ endowed with a functor  
$\mathcal{B}\times \CCC\to \mathcal{B}\otimes \CCC$
which preserves small colimits separately in each variable such that for any $\DDD\in \PR_{\mathbb{S}}$ the composition gives the fully faithful functor
\[
\Fun^\textup{L}(\mathcal{B}\otimes \CCC,\DDD)\to \Fun(\mathcal{B}\times \CCC,\DDD)
\]
whose essential image $\Fun'(\mathcal{B}\times \CCC,\DDD)$ consists of functors 
which preserves small colimits separately in each variable.
Indeed, $\mathcal{B}\otimes \CCC$ is equivalent to the full subcategory $\Fun^{\textup{R}}(\mathcal{B}^{op}, \CCC)$
of $\Fun(\mathcal{B}^{op}, \CCC)$ spanned by limit-preserving functors. This $\infty$-category
$\Fun^{\textup{R}}(\mathcal{B}^{op}, \CCC)$ is presentable (\cite[4.8.1.16]{HA}).


Next, we recall the symmetric monoidal structure on $\PRT$ (see \cite[VIII, 4.6.1]{DAG}).
Let $(\mathcal{B},\mathcal{B}^{\le0})$ and $(\CCC,\CCC^{\le0})$ be presentable $\infty$-categories endowed with accessible $t$-structures. 
The tensor product of $(\mathcal{B},\mathcal{B}^{\le0})$ and $(\CCC,\CCC^{\le0})$
is defined as
$\mathcal{B}\otimes \CCC$ (in $\PR_{\mathbb{S}}$) 
together with the smallest full subcategory $(\mathcal{B}\otimes \CCC)^{\le0}$
which contains the essential image of $\mathcal{B}^{\le0}\times \CCC^{\le0}\to \mathcal{B}\otimes \CCC$
and is closed under small colimits and extensions.
By \cite[1.4.5.11]{HA}, $(\mathcal{B}\otimes \CCC)^{\le0}$ defines an accessible $t$-structure.
The universal property of $(\mathcal{B}\otimes \CCC, (\mathcal{B}\otimes \CCC)^{\le0})$ is described as follows: For any $(\DDD, \DDD^{\le0})\in \PRT$
the composition with the canonical functor $\mathcal{B}\times \CCC\to \mathcal{B}\otimes \CCC$ gives an equivalence
\[
\Fun_{\PRT}((\mathcal{B}\otimes \CCC, (\mathcal{B}\otimes \CCC)^{\le0}),(\DDD,\DDD^{\le0}))\to \Fun^{\le}(\mathcal{B}\times \CCC,\DDD)
\]
where $\Fun^{\le}(\mathcal{B}\times \CCC,\DDD)$ is the full subcategory of $\Fun'(\mathcal{B}\times \CCC,\DDD)$,
which consists of those functors $F$ such that the essential image of $\mathcal{B}^{\le0}\times \CCC^{\le0}$ 
is contained in $\DDD^{\le0}$.

If $(\mathcal{B},\mathcal{B}^{\le0})$ and $(\CCC,\CCC^{\le0})$ are right complete,
then the tensor product $(\mathcal{B}\otimes \CCC, (\mathcal{B}\otimes \CCC)^{\le0})$ in $\PRT$
is also right complete (see \cite[VIII, 4.6.11]{DAG}).
Thus, $\PRTT$ inherits a symmetric monoidal structure from that of $\PRT$.
The left adjoint $I^+$ is promoted
to a symmetric monoidal functor.

\begin{Example}
Let $A$ and $B$ be associative ring spectra, that is, $\eone$-algebras in $\SP$.
The stable $\infty$-catgories $\LMod_A$ and $\LMod_B$ are equipped with $t$-structures described in Remark~\ref{unifiedtstr}.
Then $\LMod_A\otimes \LMod_B$ has the $t$-structure determined by the full subcategory
$(\LMod_A\otimes \LMod_B)^{\le0}$ corresponding to the smallest full subcategory of $\LMod_{A\otimes B}$ which contains $A\otimes B$
and is closed under small colimits and extensions through the canonical equivalence $\LMod_A\otimes \LMod_B\simeq \LMod_{A\otimes B}$ (cf. Section~\ref{MOA}).

Let $C\to k$ be an augmented $\etwo$-algebra in $\Mod_k$.
The stable $\infty$-catgories $\Mod_k$ and $\LMod_C$ are equipped with $t$-structures described in Remark~\ref{unifiedtstr}.
Then the relative tensor product $\Mod_k\otimes_{\LMod_A}\Mod_k$ has the $t$-structure determined by
the smallest full subcategory $(\Mod_k\otimes_{\LMod_A}\Mod_k)^{\le0}$, which contains the essential image of the functor 
$\Mod_k^{\le0}\times\Mod_k^{\le0}\to \Mod_k\otimes_{\LMod_A}\Mod_k$ (arising from the bar construction)
and is closed under small colimits and extensions.
Observe that through the canonical equivalence $\Mod_k\otimes_{\LMod_A}\Mod_k\simeq \LMod_{k\otimes_A k}$ (cf. Lemma~\ref{moduleproduct}),
$(\Mod_k\otimes_{\LMod_A}\Mod_k)^{\le0}$ corresponds to the smallest full subcategory of $\LMod_{k\otimes_A k}$,
which contains $k\otimes_Ak$ and is closed under small colimits and extensions.
\end{Example}




The $\infty$-category $\PRTTT$ also has a symmetric monoidal structure.
Let $(\mathcal{B},\mathcal{B}^{\le0})$ and $(\CCC,\CCC^{\le0})$ be objects of $\PRTTT$.
Explicitly, the tensor product of $(\mathcal{B},\mathcal{B}^{\le0})$ and $(\CCC,\CCC^{\le0})$ in $\PRTTT$
is given by 
\[
\HL((\mathcal{B}\otimes\CCC,  (\mathcal{B}\otimes \CCC)^{\le0})).
\]
We usually write $\HL(\mathcal{B}\otimes\CCC)$ or $\mathcal{B}\widehat{\otimes}\CCC$ for it.
The functor $\HL:\PRTT\to \PRTTT$ is promoted to a symmetric monoidal functor. 
Since $\HL$ is a left adjoint functor, $\HL$ commutes with the relative tensor products.
The inclusion $I^{\pm}$
is not a symmetric monoidal functor but a lax symmetric monoidal functor.







\subsection{Modules over algebras.}
\label{MOA}
Let $A$ be a commutative ring spectrum.
We write $\PR_A=\Mod_{\Mod_A}(\PR_{\mathbb{S}})$.
For $B\in \Alg_{1}(\Mod_A)$, we denote by $\LMod_B(\Mod_A)$ (resp. $\RMod_A(\Mod_A)$)
(or simply $\LMod_B$ and (resp. $\RMod_B$)) the $\infty$-category of left $B$-modules
(resp. right $B$-module spectra) (there is a canonical equivalence $\LMod_B(\Mod_A)\simeq \LMod_B(\SP)$ induced by the forgetful functor $\Mod_A\to \SP$).
As constructed \cite[4.8.5]{HA}, there is a symmetric monoidal functor
\[
\Theta_A:\Alg_{1}(\Mod_A)\longrightarrow (\PR_A)_{\Mod_A/}
\]
which carries $B$ to $\alpha:\Mod_A\to \LMod_{B}(\Mod_A)$
such that $\alpha$ is determined by $\SP\stackrel{\otimes A}{\to} \Mod_A\to \LMod_{B}(\Mod_A)$ which carries the sphere spectrum
to $B$. The homomorphism $f:B\to C$ maps to the base change functor $f^*:\LMod_B\to \LMod_C$.
Here the subscript in $(\PR_A)_{\Mod_A/}$ means the undercategory.
The functor $\Theta_A$ is a fully faithful left adjoint functor, see \cite[4.8.5.11]{HA}.
The right adjoint $E_A:(\PR_A)_{\Mod_A/}\to \Alg_{1}(\Mod_A)$
sends $\alpha:\Mod_A\to \CCC$ to the opposite algebra of the endomorphism algebra of $\alpha(A)\in \CCC$, defined as an algebra object of $\Mod_A$. 
Let $\iota_A:\Alg_1(\Mod_A)\to \Alg_1(\Mod_A)$
be the equivalence which carries $B$ to the opposite algebra $B^{op}$.
This equivalence is induced by the automorphism of the $\eone$-operad $\eone^\otimes\to \eone^\otimes$
given by the reflection of lines ($x\mapsto -x$).
We have
$\Theta_A\circ \iota_A:\Alg_{1}(\Mod_A)\longrightarrow (\PR_A)_{\Mod_A/}$
which carries $B$ to $\alpha:\Mod_A\to \RMod_{B}(\Mod_A)=\LMod_{B^{op}}(\Mod_A)$.

Since $\Theta_A$ is a symmetric monoidal functor, 
by Dunn additivity theorem \cite[5.1.2]{HA}, it determines the fully faithful symmetric monoidal left adjoint functor 
\[
\Alg_1(\Theta_A):\Alg_{2}(\Mod_A)\simeq \Alg_{1}(\Alg_{1}(\Mod_A))\to  \Alg_{1}((\PR_A)_{\Mod_A/})\simeq \Alg_{1}(\PR_A).
\]
The right adjoint of $\Alg_1(\Theta_A)$ is $\Alg_1(E_A)$ induced by the lax symmetric monoidal functor $E_A$.
The induced right adjoint functor $\Alg_1(E_A):\Alg_{1}(\PR_A)\to \Alg_{2}(\Mod_A)$ carries $\MMM^\otimes\in \Alg_{1}(\PR_A)$ to (the opposite algebra of) the endomorphism algebra $\End(\mathsf{1}_{\MMM})$
of the unit object $\mathsf{1}_{\MMM}$, defined as an $\etwo$-algebra object in $\Mod_A$.
By abuse of notation, we often write $\Theta_A$ and $E_A$ for $\Alg_1(\Theta_A)$ and $\Alg_1(E_A)$, respectively.

For $B\in \Alg_2(\Mod_A)$, since the underlying $A$-linear presentable $\infty$-category
of $\Theta_A(B)$ is $\LMod_B$, $\LMod_B$ is promoted to an object of $\Alg_1(\PR_A)$.
In particular, $\LMod_B$ is equipped with the structure of an (associative) monoidal $\infty$-category.
The underlying $A$-linear $\infty$-category $\LMod_B$
is equivalent to $\RMod_B=\LMod_{B^{op}}$ as an object of $\PR_A$.
Note that the underlying $\eone$-algebra is given by the restriction
along the map of $\infty$-operads $\eone^\otimes\to \etwo^\otimes$ determined by a linear injecitve map $\RR\to \RR^2$.
Any linear inclusion $\RR\to \RR^2$ is homotopy equivalent to one another via rotations.
Thus, we have a (non-canonical) equivalence $\LMod_B\simeq \RMod_B$ in $\PR_A$.

We regard $\LMod_B^\otimes$ as an object of $\Alg_1(\PR_A)$
and consider the opposite algebra $\LMod_B^{\otimes op}\in \Alg_1(\PR_A)$.
Namely, $\LMod_B^{\otimes op}$ has the ``opposite monoidal structure".
Let $\RMod_B^{\otimes}$ denote the monoidal $A$-linear presentable $\infty$-category
defined as $\Alg_1(\Theta_A)\circ\Alg_1(\iota_A)(B)\in \Alg_1(\PR_A)$.

\begin{Proposition}
\label{oppositemonoidal}
There exists an equivalence
\[
\LMod_B^{\otimes op}\simeq \RMod_B^\otimes
\]
in $\Alg_1(\PR_A)$.
\end{Proposition}


\Proof
We consider the diagram
\[
\xymatrix{
\Alg_1(\Alg_1(\Mod_A))  \ar[r]^(0.6){\Alg_1(\Theta_A)} \ar@<0.3ex>[d]_{\iota^{\textup{out}}}  \ar@<-0.3ex>[d]^{\iota^{\textup{in}}}  &  \Alg_1(\PR_A) \ar[d]^{\iota_{\PR_A}} \\
\Alg_1(\Alg_1(\Mod_A))   \ar[r]^(0.6){\Alg_1(\Theta_A)}   &  \Alg_1(\PR_A)
}
\]
where $\iota_{\PR_A}$ is the equvalence determined by the opposite algebras in $\Alg_1(\PR_A)$.
The arrow $\iota^{\textup{in}}$ is the equivalence given
by taking the opposite algebras with respect to the inner $\Alg_1$.
The arrow $\iota^{\textup{out}}$ is the equivalence given
by taking the opposite algebras with respect to the outer $\Alg_1$.
The equivalence $\iota^{\textup{in}}$ is induced by an automorphism $a:\etwo^\otimes\to \etwo^\otimes$
determined by reflecting across a line on the disc.
Also, $\iota^{\textup{out}}$ is induced by an automorphism $b:\etwo^\otimes\to \etwo^\otimes$
determined by reflecting across a line on the disc. The difference is the choice of a line on the disc.
Thus, such reflections are homotopy equivalent to each other. 
Thus,  $\iota^{\textup{in}}$ is equivalent to  $\iota^{\textup{out}}$.
Since $\Theta_A$ is a symmetric monoidal functor, there exists a canonical equivalence 
$\Alg_1(\Theta_A)\circ \iota^{\textup{out}}\simeq \iota_{\PR_A} \circ \Alg_1(\Theta_A)$.
By definition, $\RMod_B^\otimes=\Alg_1(\Theta_A)\circ\iota^{\textup{in}}(B)$
and $\LMod_B^{\otimes op}=\iota_{\PR_A}\circ \Alg_1(\Theta_A)(B)$.
It follows that $\RMod_B^\otimes\simeq \LMod_B^{\otimes op}$.
\QED

\begin{Construction}
\label{thetaTTT}
For a later use, we will construct
$\Theta_k^{+}:\Alg_{2}(\Mod_k)\to  \Alg_{1}(\Mod_{\Mod_k}(\PRTT))$.
which carries $B$ to $(\LMod_B^\otimes, \LMod_B^{\le0})$,
where $\LMod_B^{\le0}$ is the smallest full subcategory which contains $B$ and is closed under small colimits and extensions (see Remark~\ref{unifiedtstr}).
Recall that
$\Theta_k:\Alg_{2}(\Mod_k)\to  \Alg_{1}(\Mod_{\Mod_k}(\PR))$
is fully faithful (cf. Section~ref{MOA}). We denote the essential image by $T$. Let $S$ be the full subcategory of $\Alg_{1}(\Mod_{\Mod_k}(\PRTT))$
spanned by objects of the form $(\LMod_B^\otimes, \LMod_B^{\le0})$ with $B\in\Alg_{2}(\Mod_k)$.
The forgetful functor $\Alg_{1}(\Mod_{\Mod_k}(\PRTT))\to \Alg_1(\PR_k)$ induces $f:S\to T$.
We claim that $f$ is an equivalence. 
We define $\Theta_k^{+}$ to be the composition $g\circ \Theta_k|_{\Alg_{2}(\Mod_k^{\le0})}$
where $g$ is an inverse functor of $f$.
Clearly, $f$ is essentially surjective.
Note that every colimit-preserving monoidal functor $F:\LMod_A\to \LMod_B$
sends $A$ to $B$. Since $\LMod_A^{\le0}$ (resp. $\LMod_B^{\le0}$)
is the smallest full subcategory of $\LMod_A$ (resp. $\LMod_B$)
which contains $A$ (resp. $B$) and is closed under small colimits and extensions,
it follows that $F$ is right $t$-exact. Thus, $f$ is fully faithful.



We define
$\Theta_k^{\pm}:\Alg_{2}(\Mod_k^{\le0})\to  \Alg_{1}(\Mod_{\Mod_k}(\PRTTT))$
to be the restriction of $\Theta_k^+$.
If $B$ is connective, the $t$-strucutre on $\LMod_B$ is left complete
(Example~\ref{connectivetstr}) so that the target is $\Alg_{1}(\Mod_{\Mod_k}(\PRTTT))$.
\end{Construction}




{\it Endomorphism algebras.}
Let $\mathcal{M}$ be an $\infty$-category.
Let $\mathcal{A}^\otimes$ be a monoidal $\infty$-category.
Suppose that $\MMM$ is a left $\mathcal{A}^\otimes$-module, that is,
it has a left $\mathcal{A}^\otimes$-module action in the symmetric monoidal $\infty$-category $\wCat$ where the monoidal $\infty$-category $\mathcal{A}^\otimes$ is regarded as an associative algebra
object in $\wCat$.
Let $M$ be an object of $\MMM$.
The endomorphism algebra object of $M$ in $\mathcal{A}$ is defined as an associative
algebra $\End^{\mathcal{A}}(M)$ in $\mathcal{A}$ (i.e., an object of $\Alg_1(\mathcal{A})$)
together with a left module action of $\End^{\mathcal{A}}(M)$ on $M$, 
which has the universal property described informally as follows:
For any associative algebra $R$ in $\mathcal{A}$ and a left module action $R\otimes M\to M$
on $M$, there exists an essentially unique morphism $f:R\to \End^{\mathcal{A}}(M)$
such that the left module action of $R$ is induced by the restriction of the action of $\End^{\mathcal{A}}(M)$ along $f$ (this is a rough account, see \cite[4.7.1]{HA} for the precise formulation).




















\subsection{Linear stable $\infty$-categories.}
\begin{Notation}
Write $(\PRTT)_k=\Mod_{\Mod_k}(\PRTT)$ and  $(\PRTTT)_k=\Mod_{\Mod_k}(\PRTTT)$.
\end{Notation}


Let $B\in \Alg_2(\Mod_k)$.
We define several versions of $B$-linear stable $\infty$-categories.

\begin{Definition}
\begin{enumerate}
\item
Let $\LMod^\otimes_B\in \Alg_1(\PR_k)$ be the associative monoidal $\infty$-category of left $B$-modules in $\Mod_k$.
Let $\RMod_{\LMod_B^\otimes}(\PR_k)$ be
the $\infty$-category of right $\LMod_B^\otimes$-modules in $\PR_k$.
We refer to an object of $\RMod_{\LMod_B^\otimes}(\PR_k)$
as a right $B$-linear stable $\infty$-category.


\item 
Suppose that $B$ is coconnective.
We consider the $t$-structure $(\LMod_B^{\le0}, \LMod_B^{\ge0})$ given in Proposition~\ref{tstrcoconnective}.
Note that $\LMod_B^{\le0}$ is closed under tensor products, and the unit object $B$ belongs to $\LMod_B^{\le0}$.
Consequently, $(\LMod_B,\LMod_B^{\le0})$ is naturally promoted to an object of $\Alg_1(\PRTT)$.
Let $\LMod_{\LMod_B^\otimes}((\PRTT)_k)$ denote
the $\infty$-category of right  $(\LMod_B,\LMod_B^{\le0})$-modules in $(\PRTT)_k$.
We refer to an object of $\LMod_{\LMod_B^\otimes}((\PRTT)_k)$
as a left $B$-linear stable $\infty$-category with $t$-stucture.

\item 
Suppose that $B$ is connective.
We consider the $t$-structure $(\LMod_B^{\le0}, \LMod_B^{\ge0})$ given in Example~\ref{connectivetstr}.
Note that $\LMod_B^{\le0}$ is closed under tensor products, and the unit object $B$ belongs to $\LMod_B^{\le0}$.
Consequently, $(\LMod_B,\LMod_B^{\le0})$ is naturally promoted to an object of $\Alg_1(\PRTTT)$.
Let $\RMod_{\LMod_B^\otimes}((\PRTTT)_k)$ denote
the $\infty$-category of right $(\LMod_B,\LMod_B^{\le0})$-modules in $(\PRTTT)_k$.
We refer to an object of $\RMod_{\LMod_B^\otimes}((\PRTTT)_k)$
as a complete right $B$-linear stable $\infty$-category.

\end{enumerate}

\end{Definition}


\begin{Remark} 
The left completion functor $\HL$ induces
\[
\HL_B:\RMod_{\LMod_B^\otimes}((\PRTT)_k) \to \RMod_{\HL(\LMod_B^\otimes)}((\PRTTT)_k)
\]
If $B$ is connective and $\LMod_B$ is
endowed with the left complete right complete $t$-structure in Example~\ref{connectivetstr},
then $\HL(\LMod_B^\otimes)\simeq \LMod_B^\otimes$.
\end{Remark}

\subsection{Koszul duals of algebras}
\label{koszulsec}
Let $\MMM^\otimes$ be a monoidal $\infty$-category. We write $\uni$ for a unit object.
We review the Koszul duality of algebras in $\MMM^\otimes$ (see \cite{HA}, \cite[X]{DAG} for more details).
Let $\Alg^+_{1}(\MMM)=\Alg_1(\MMM)_{/\uni}$ be the $\infty$-category of augmented $\eone$-algebra objects (associative algebra objects) in $\MMM^\otimes$.
For a pair $(\epsilon_A:A\to \uni,\epsilon_B:B \to \uni)\in \Alg^+_{1}(\MMM)\times \Alg^+_{1}(\MMM)$ we put
\[
\textup{Pair}(\epsilon_A,\epsilon_B):= \Map_{\Alg_{1}(\MMM)}(A\otimes B,\uni)\times_{\Map(A,\uni)\times\Map(B,\uni)}\{(\epsilon_A,\epsilon_B)\}.
\]
Fix $\epsilon_B:B \to \uni$ and consider the functor
$u_{\epsilon_B}:\Alg_1^+(\MMM)^{op}\to \wSSS$ given informally by $[\epsilon_A:A\to \uni]\mapsto \textup{Pair}(\epsilon_A,\epsilon_B)$. 
The Koszul dual $\DD_{\MMM^\otimes}(B)\in \Alg_1^+(\MMM)$ of $B$ (we abuse notation since $\DD_{\MMM^\otimes}(B)$ depends on the augmentation $\epsilon_B:B \to \uni$)
is defined by the universal property that $\DD_{\MMM^\otimes}(B)$ represents the functor $u_{\epsilon_B}$.
Under a mild condition on $\MMM^\otimes$, there exist $\DD_{\MMM^\otimes}(B)$ and functorial equivalences
\[
\Map_{\Alg_1^+(\MMM)}(A,\DD_{\MMM^\otimes}(B))\simeq \textup{Pair}(\epsilon_A,\epsilon_B)
\]
for $\epsilon_A:A\to \uni$.



Let $n\ge1$ be a natural number and  let $\Alg_{n}(\Mod_k)$ be the $\infty$-category of $\eenu$-algebras in $\Mod_k$.
We write $\Alg^+_{n}(\Mod_k)=\Alg_n(\Mod_k)_{/k}$ for the $\infty$-category
$\Alg_{n}(\Mod_k)_{/k}$ of augmented $\eenu$-algebras.
We consider the Koszul duals of augmented $\eenu$-algebras.
We take $\MMM^\otimes$ to be $\Alg_{n-1}^\otimes(\Mod_k)$. There exists the Koszul duality functor
\[
\DD_n:\Alg_{n}^+(\Mod_k)\simeq \Alg_1^+(\Alg_{n-1}(\Mod_k))\longrightarrow\Alg_1^+(\Alg_{n-1}(\Mod_k))\simeq  \Alg_{n}^+(\Mod_k)^{op}
\]
(see e.g. \cite[X, 4.4]{DAG}).
Let $\epsilon_{B}:B\to k$ be an augmented $\eenu$-algebra.
As mentioned above,
$\DD_n(B)$ is determined by the universal property.
For an augmented $\eenu$-algebra $\epsilon_C:C\to k$, we write
\[
\textup{Pair}(\epsilon_B,\epsilon_C)= \Map_{\Alg_{n}(\Mod_k)}(B\otimes_k C,k)\times_{\Map(B,k)\times\Map(C,k)}\{(\epsilon_B,\epsilon_C)\}.
\]
Then the functor $\Alg^+_{n}(\Mod_k)^{op}\to \wSSS$ given by $[\epsilon_C:C\to k]\mapsto \textup{Pair}(\epsilon_B,\epsilon_C)$
is representable by $\DD_{n}(B)$.
There is a universal ``Koszul dual pairing'' $B\otimes_k\DD_{n}(B)\to k$ corresponding to
the identity map $\textup{id}\in \Map_{\Alg^+_{n}(\Mod_k)}(\DD_{n}(B),\DD_{n}(B))$.
The Koszul dual $\DD_{n}(B)$ can also be interpreted as a centralizer of $B\to k$, see \cite[5.3.1]{HA}.
We refer to a comprehensive account \cite{Gin} for centralizers and  Koszul duals.
We refer to $\DD_{n}(B)$ as the $\eenu$-Koszul dual of $B$. 


The Koszul duals can be described in terms of bar constructions.
Let $\textup{Bar}:\Alg_{1}^+(\Mod_k)\to \Mod_{k}$ be the functor
given by $[B\to k] \mapsto k\otimes_Bk$, which we refer to as the bar construction of augmented algebras.
Then $k\otimes_Bk$ admits a structure of a coaugmented coalgebra in a suitable way, and $\textup{Bar}$
is promoted to $\textup{Bar}:\Alg_{1}^+(\Mod_k)\to \Alg^+_{1}((\Mod_k)^{op})^{op}$
(notice that the target is the $\infty$-category of coaugmented coalgebras).
Interating bar construction we have
induces $\textup{Bar}^n:\Alg_{n}^+(\Mod_k)\to \Alg_{n}^+((\Mod_k)^{op})^{op}$.
According to \cite[X, 4.4.20]{DAG}, for $B\in \Alg^+_{n}(\Mod_k)$, the $\eenu$-Koszul dual $\DD_{n}(B)$
is equivalent to
the $k$-linear dual $\mathcal{H}om_{k}(\textup{Bar}^n(B),k)$.
In particular, $\eone$-Koszul dual of $B\to k$ is given by the endomorphism algebra $\End_B(k)$ with the canonical
augmentation $\End_B(k)\to \End_k(k)\simeq k$ (here $k$ is regarded as a left $B$-module).




















\section{Koszul duality and left completion}

\label{adjointsec}






\subsection{}





Let
$A$ be an augmented $\etwo$-algebra in $\Mod_k$. Suppose that $A$ is connective.
Note that $\LMod_A^{\le0}$ is the smallest full subcategory which contains $A$ and is closed under small colimits (see Exmaple~\ref{connectivetstr}, \cite[7.1.1.13]{HA}).
Thus, $\LMod_A^{\le0}$ contains an unit object $R$ and is closed under tensor products
so that the monoidal $\infty$-category $\LMod_A^\otimes$
can be regarded as an algebra object in $\PRTTT$.
Let $\DDD$ be a complete $A$-linear stable $\infty$-category endowed with $(\DDD^{\le0},\DDD^{\ge0})$,
that is, $\DDD\in \RMod_{\LMod_A}(\PRTTT)$.
In particular, the $t$-structure is accessible, left complete, and right complete.
The tensor product of $\PRTT$ induces the right complete accessible $t$-structure on $\DDD\otimes_{\LMod_{A}}\Mod_k$.
This $t$-structure is determined by
$(\DDD\otimes_{\LMod_A}\Mod_k)^{\le0}$ defined as
the smallest full subcategory which contains a collection of objects $\{D\otimes_Ak\}_{D\in \DDD^{\le0}}$
and is closed under small colimits and extensions.
Here $D\otimes_Ak$ is the image of $(D,k)\in \DDD\times \Mod_k$ under the canonical functor $\DDD\times \Mod_k\to \DDD\otimes_{\LMod_A}\Mod_k$.

From \cite[4.8.4.6]{HA} there exists a canonical equivalence $\DDD\otimes_{\LMod_A}\Mod_k\simeq\RMod_k(\DDD)$. 
We consider the forgetful functor 
\[
u:\DDD\otimes_{\LMod_A}\Mod_k\simeq\RMod_k(\DDD) \to \DDD.
\]


\begin{Lemma}
\label{texactforget}
The functor $u:\DDD\otimes_{\LMod_A}\Mod_k\simeq\RMod_k(\DDD) \to \DDD$
is $t$-exact.
Moreover, $M$ lies in $(\DDD\otimes_{\LMod_A}\Mod_k)^{\le0}$
if and only if its image in $\DDD$ lies in $\DDD^{\le0}$.
\end{Lemma}


\Proof
Note that the forgetful functor $u$ preserves small colimits.
Note also that $D\otimes_Ak\in \DDD^{\le0}$ for any $D\in \DDD^{\le0}$
since $k$ lies in $\LMod_A^{\le0}$ and by definition the tensor product induces $\DDD^{\le 0}\times \LMod_A^{\le0} \to \DDD^{\le0}$.
Taking account of the definition of $(\DDD\otimes_{\LMod_A}\Mod_k)^{\le0}$
we conclude that $u$ is right $t$-exact.

Next, we will prove that $u$ is left $t$-exact.
Let $v:\DDD\to \DDD\otimes_{\LMod_A}\Mod_k$
be the left adjoint induced by the base change functor $\LMod_A\to \Mod_k$.
This left adjoint carries $D$ to $D\otimes_Rk$.
In particular, $\DDD^{\le0}$ maps to $(\DDD\otimes_{\LMod_A}\Mod_k)^{\le0}$.
It follows that $v$ is right $t$-exact and $u$ is left $t$-exact.
Moreover, $E\in\DDD\otimes_{\LMod_A}\Mod_k $
 lies in $(\DDD\otimes_{\LMod_A}\Mod_k)^{\ge0}$
if and only if $\Hom_{\hhh(\DDD\otimes_{\LMod_A}\Mod_k)}(D\otimes_Ak[1],E)$
for any $D\in \DDD^{\le0}$.
Thus, $(\DDD\otimes_{\LMod_A}\Mod_k)^{\ge0}=u^{-1}(\DDD^{\ge0})$.
\QED






Strictly speaking, the following is not necessary for Theorem~\ref{intromain1}, but useful.

\begin{Proposition}
\label{already}
Let $\DDD$ be an object of $\RMod_{\LMod_A}(\PRTTT)$ as above.
Let $\DDD\otimes_{\LMod_A}\Mod_k\in (\PRTT)_k$
denote the relative tensor product in $\PRTT$.
Equivalently, $\DDD\otimes_{\LMod_A}\Mod_k$
is the relative tensor product in $\PR_{\mathbb{S}}$
endowed with the $t$-structure determined by $(\DDD\otimes_{\LMod_A}\Mod_k)^{\le0}$
defined above.
Then the $t$-structure $(\DDD\otimes_{\LMod_A}\Mod_k, (\DDD\otimes_{\LMod_A}\Mod_k)^{\le0})$
is left complete.
\end{Proposition}

\Proof
For $M\in \DDD\otimes_{\LMod_A}\Mod_k$ we consider the natural morphism
$\theta:M\to \lim_{n\to -\infty}(\tau^{\ge n}M)$.
It suffices to prove that $\theta$ is an equivalence.
Note that $u:\DDD\otimes_{\LMod_R}\Mod_k\to \DDD$ is $t$-exact and preserves small colimits (see Lemma~\ref{texactforget}),
and $\DDD$ and $\DDD\otimes_{\LMod_A}\Mod_k$ are right complete.
Thus we have
\begin{eqnarray*}
u(M) &\to& u(\lim_{n\to -\infty}(\tau^{\ge n}M)) \\
&\simeq& \lim_{n\to -\infty}u((\tau^{\ge n}M)) \\
&\simeq& \lim_{n\to -\infty}\tau^{\ge n}u(M).
\end{eqnarray*}
By the left completeness of $(\DDD,\DDD^{\le0})$,
the composite is an equivalence.
Thus, $u(M) \to u(\lim_{n\to -\infty}(\tau^{\ge n}M))$
is an equivalence.
The forgetful functor $u$ is conservative so that $\theta$
is an equivalence.
\QED



\begin{Remark}
\label{alreadyrem}
In Lemma~\ref{texactforget}, $M$ lies in $(\DDD\otimes_{\LMod_A}\Mod_k)^{\ge0}$
if and only if its image in $\DDD^{\ge0}$.
To see this,
we write the canonical morphism $p:\tau^{\le0}M\to M$
from the truncation (the connective cover).
The morphism $p$ is an equivalence if and only if $M\in (\DDD\otimes_{\LMod_A}\Mod_k)^{\le0}$.
By the $t$-exactness of $u$ and the left completeness of the $t$-structures on $\DDD$ and $\DDD\otimes_{\LMod_A}\Mod_k$ (Proposition~\ref{already}),
we have $u(p):u(\tau^{\le0}M)\simeq\tau^{\le0}u(M)\to u(M)$.
The morphism $u(p)$ is an equivalence if and only if $u(M)\in \DDD^{\le0}$.
Since $u$ is conservative, $M$ lies in $(\DDD\otimes_{\LMod_R}\Mod_k)^{\le0}$ exactly when $u(M)\in \DDD^{\le0}$.
Consequently, $M$ lies in $(\DDD\otimes_{\LMod_R}\Mod_k)^{\le0}$ (resp. $(\DDD\otimes_{\LMod_R}\Mod_k)^{\ge0}$)
if and only if its image in $\DDD$ lies in $\DDD^{\le0}$ (resp. $\DDD^{\ge0}$).
\end{Remark}


\begin{Lemma}
\label{tensorvshom}
Let $\DDD$ be a right $\LMod_A$-module in $\PR_{\mathbb{S}}$, that is an object of $\RMod_{\LMod_A}(\PR)$.
There exists a canonical equivalence
\[
\DDD\otimes_{\LMod_{A}}\Mod_k\simeq \Fun_{\LMod_A}^r(\Mod_k, \DDD)
\]
in $\PR_{\mathbb{S}}$. Here the right-hand side is the functor category from $\Mod_k$ to $\DDD$ in  $\RMod_{\LMod_A}(\PR)$.
\begin{comment}
If we write $D\otimes_Ak$ for the image of $(D,k)\in \DDD\times \Mod_k$ under the canonical functor $\DDD\times \Mod_k\to \DDD\otimes_{\LMod_A}\Mod_k$,
the equivalence carries $D\otimes_Ak\in \DDD\otimes_{\LMod_{A}}\Mod_k$
to a functor $\Mod_k\to \DDD$ which carries $k$ to $D\otimes_Ak$ (more precisely, action of $k$ should be specified).
\end{comment}
\end{Lemma}

\Proof
According to \cite[4.8.4.1, 4.8.4.6]{HA}, we have equivalences $\DDD\otimes_{\LMod_{A}}\Mod_k\simeq \RMod_k(\DDD)\simeq \Fun_{\LMod_A}^r(\Mod_k, \DDD)$.
\QED


