\subsection{}
Let $A$ be an augmented $\etwo$-algebra in $\Mod_k$. 
We write $\epsilon_A:A\to k$ for the augmentation.
We think of $\LMod_A$ as a monoidal $\infty$-category (cf. Section~\ref{MOA}).
Consider $\Mod_k$ to be the left $\LMod_A$-module object via the monoidal functor $\LMod_A^\otimes\to \LMod_k^\otimes=\Mod_k^\otimes$.
Let $\End^l_{A}(\Mod_k)$ be the endomorphism algebra object of $\Mod_k$ in $\LMod_{\LMod_A}(\PR)$.
This is defined as an object of $\Alg_1(\PR_k)$, which has a universal left module action on $\Mod_k$.
When we emphasize the monoidal structure, we write $\End^l_{A}(\Mod_k)^\otimes$ for it.
There exists a $\eone$-Koszul dual pairing
\[
\kappa:\LMod_A^\otimes\otimes_k\End^l_{A}(\Mod_k)^\otimes\longrightarrow \Mod_k^\otimes
\]
which is a morphism of $\Alg_1(\PR_k)$.

\begin{Lemma}
\label{dualcatalg}
The $\etwo$-Koszul dual $\DD_2(A)$ can be identified with $E_k(\End^l_{A}(\Mod_k))\in \Alg_2(\Mod_k)$ (see Section~\ref{MOA} for $E_k$).
The universal $\etwo$-Koszul pairing $A\otimes_k\DD_2(A) \to k$
is equivalent to the composition of $E_k(\kappa)$ and the canonical 
morphism $E_k(\LMod_A)\otimes_k E_k(\End^l_{A}(\Mod_k))\to E_k(\LMod_A\otimes_k\End^l_{A}(\Mod_k))$.
\end{Lemma}


\Proof
We first recall the universal property of $\DD_2(A)$. 
For $\epsilon_A:A\to k$ and $\epsilon_B:B\to k$ we consider the space
\[
\textup{Pair}(\epsilon_A,\epsilon_B):= \Map(A\otimes_k B,k)\times_{\Map(A,k)\times\Map(B,k)}\{(\epsilon_A,\epsilon_B)\}.
\]
Here $\Map$ means the mapping space in $\Alg_{2}(\Mod_k)$.
Consider the functor
$u_{\epsilon_A}:\Alg_2^+(\Mod_k)^{op}\to \wSSS$ given informally by $[\epsilon_B:B\to k]\mapsto \textup{Pair}(\epsilon_A,\epsilon_B)$. 
The Koszul dual $\DD_{2}(A)\in \Alg_2^+(\Mod_k)$ of $A$
is defined by the universal property that $\DD_{2}(A)$ represents the functor $u_{\epsilon_A}$.
Consider $\LMod(\epsilon_A):\LMod_A\to \Mod_k$ 
and $\LMod(\epsilon_B):\LMod_B\to \Mod_k$.
Let $\epsilon_{\MMM^\otimes}:\MMM^\otimes\to \Mod_k^\otimes$ be an object of $\Alg_1^+(\PR_k)=\Alg_1(\PR_k)_{/\Mod^\otimes_k}$.
We define $\textup{Pair}(\LMod(\epsilon_A),\epsilon_{\MMM^\otimes})$ to be
\[
 \Map(\LMod_A^\otimes\otimes \MMM^\otimes,\Mod_k^\otimes)\times_{\Map(\LMod_A^\otimes,\Mod_k^\otimes)\times\Map(\MMM^\otimes,\Mod_k^\otimes)}\{(\LMod(\epsilon_A),\epsilon_{\MMM^\otimes})\}.
\]
Here $\Map$ means the mapping space in $\Alg_{1}(\PR_k)$.
Let 
$u_{\LMod(\epsilon_A)}:\Alg_1^+(\PR_k)^{op}\to \wSSS$
be the functor given informally by $[\epsilon_{\MMM^\otimes}:\MMM^\otimes\to \Mod_k^\otimes]\mapsto \textup{Pair}(\LMod(\epsilon_A),\epsilon_{\MMM^\otimes})$.
This functor
is represented by the $\eone$-Koszul dual
$\End^l_{A}(\Mod_k)$ with the canonical augmentation $\End^l_{A}(\Mod_k)\to\Mod_k$.

Since $\Theta_k:\Alg_2(\Mod_k)\to \Alg_1(\PR_k)$ is the fully faithful symmetric monoidal functor,
we have a canonical equivalence
$\textup{Pair}(\epsilon_A,\epsilon_B)\simeq \textup{Pair}(\LMod(\epsilon_A),\LMod(\epsilon_B))$.
Namely, $u_{\epsilon_A}$ is naturally equivalent to
the composite $u_{\LMod(\epsilon_A)}\circ \Theta_k^{op}:\Alg_2^+(\Mod_k)^{op}\to \Alg_1^+(\PR_k)^{op}\to \wSSS$.
Take $D=E_k(\End^l_{A}(\Mod_k))$ and the composite
\[
P:E_k(\LMod_A)\otimes_k E_k(\End^l_{A}(\Mod_k))\to E_k(\LMod_A\otimes_k\End^l_{A}(\Mod_k))\to E_k(\Mod_k)\simeq \Mod_k
\]
where the left arrow is induced by the lax symmetric monoidal functor $E_k$,
and the right arrow is induced by the universal pairing $\kappa$.
Note also that $E_k(\LMod_A)\simeq \LMod_A$.
Let $p:A\otimes_kD\to k$ be the morphism in $\Alg_2(\Mod_k)$
that corresponds to $P$ through $\Theta_k$.
Then taking account of the adjunction $\Theta_k:\Alg_2(\Mod_k)\rightleftarrows \Alg_1(\PR_k):E_k$, we see that $D$ together with $p$ defines a $\etwo$-Koszul dual of $A\to k$.
\QED


Using the counit of the adjunction we have:

\begin{Corollary}
\label{monoidal}
There exists a morphism $\xi:\LMod_{\DD_2(A)}^\otimes\to \End_{A}^{l}(\Mod_k)^\otimes$ in $\Alg_1(\PR_k)$.
\end{Corollary}







\begin{Lemma}
\label{moduleproduct}
Let $A$ be an augmented $\etwo$-algebra in $\Mod_k$.
There exists an equivalence
