\subsection{}
Let $R$ be an augmented $\etwo$-algebra in $\Mod_k$, that is, an object of $\Alg_2^+(\Mod_k)$.
Suppose that $R$ is Artin.
Let $\lambda:R\otimes_k\DD_2(R)\to k$ be the Koszul dual pairing (cf. Section~\ref{koszulsec}).
Taking module categories, we have a monoidal functor  
\[
\LMod_R\otimes_k\LMod_{\DD_2(R)}\to \LMod_k=\Mod_k.
\]
Moreover, it preserves small colimits and carries $R\otimes_k\DD_2(R)$ to $k$.
Thus, it can be regarded as a morphism in $\Alg_1((\PRTT)_k)$.
In particular, $\Mod_k$ is a $\LMod_R^\otimes$-$\LMod_{\DD_2(R)}^{\otimes op}$ bimodule in $(\PRTT)_k$.
Recall that the superscript $\otimes op$ means the opposite algebra of $\LMod_{\DD_2(R)}^{\otimes}$
in $\Alg_1((\PRTT)_k)$.
This bimodule induces
\[
\xymatrix{
(-)\otimes_{R}k :\RMod_{\LMod_{R}}(\PRTT) \ar[r] &  \LMod_{\LMod_{\DD_2(R)}}(\PRTT) %: \Fun_{\LMod_{\DD_2(R)}}(\Mod_k,-)  \ar@<0.5ex>[l]  
}
\]
where $(-)\otimes_{R}k$ indicates the functor induced by 
the relative tensor product over $\LMod_R$.
We write $\Phi_R$ for $(-)\otimes_{R}k$.
Let 
\[
\Psi_R :\LMod_{\LMod_{\DD_2(R)}}(\PRTT)  \to \RMod_{\LMod_{R}}(\PRTT)
\]
be the functor which sends $\EE$ to $\Mod_k\otimes_{\LMod_{\DD_2(R)}} \EE$, where $\Mod_k$ is regarded as a right $\LMod_R\otimes_k\LMod_{\DD_2(R)}$-module object.




\begin{Lemma}
\label{moritaleft}
The functor $\Psi_R$ is a left adjoint of $\Phi_R$. 
\end{Lemma}

\Proof
We define
\[
U_{\EE}:\EE\to (\LMod_k\otimes_{\LMod_{\DD_2(R)}}\EE)\otimes_{\LMod_R}\RMod_k \simeq (\RMod_k\otimes_{\LMod_R^{\otimes op}}\LMod_k)\otimes_{\LMod_{\DD_2(R)}}\EE
\]
to be the morphism obtained from $\xi:\LMod_{\DD_2(R)}\to \Mod_k\otimes_{\RMod_R}\Mod_k\simeq \RMod_k\otimes_{\LMod_R^{\otimes op}}\LMod_k$
(see Lemma~\ref{leftcomplemmma} and Remark~\ref{moduleproduct2})
by taking the tensor product over $\LMod_{\DD_2(R)}$.
We define
\[
V_{\DDD}:\LMod_k\otimes_{\LMod_{\DD_2(R)}}(\DDD\otimes_{\LMod_{R}}\RMod_k) \simeq  \DDD\otimes_{\LMod_{R}}(\RMod_k\otimes_{\LMod_{\DD_2(R)}^{\otimes op}}\LMod_k)\to \DDD
\]
to be the morphism obtained from $\eta:\RMod_k\otimes_{\LMod_{\DD_2(R)}^{\otimes op}}\LMod_k\simeq \Mod_k\otimes_{\RMod_{\DD_2(R)}}\Mod_k\to \LMod_R$ (see Lemma~\ref{leftcomp2})
by taking the tensor product over $\LMod_{R}$.
We set $\Phi=\Phi_R$ and $\Psi=\Psi_R$.
They determine the natural transformations $U:\textup{id}\to \Phi\circ \Psi$ and $V:\Psi \circ \Phi\to \textup{id}$.
We show that $U$ and $V$ are compatible up to homotopy (\cite[2.1]{RV}, \cite[6.2.1]{Kero}).
To this end, it suffices to prove:
\begin{enumerate}
\item The identity functor $\textup{id}_{\Psi}$ is equivalent to the composition
\[
\Psi=\Psi\circ \textup{id} \stackrel{\textup{id}_{\Psi}\circ U}{\longrightarrow}  \Psi\circ \Phi\circ \Psi \stackrel{V\circ \textup{id}_\Psi}{\longrightarrow} \textup{id} \circ \Psi
\]

\item
The identity functor $\textup{id}_{\Phi}$ is equivalent to the composition
\[
\Phi=\Phi\circ \textup{id} \stackrel{U\circ \textup{id}_{\Phi}}{\longrightarrow}  \Phi\circ \Psi\circ \Phi \stackrel{\textup{id}_\Phi \circ V}{\longrightarrow} \textup{id} \circ \Phi.
\]

\end{enumerate}
The proof of (2) is similar to (1) so that we will concentrate (1).
Unwinding the composition in (1) it is enough to prove the identity functor $\Mod_k\to \Mod_k$ is equivalent to the composition  
\begin{eqnarray*}
c:\Mod_k\simeq\Mod_k\otimes_{\LMod_{\DD_2(R)}}\LMod_{\DD_2(R)}&\stackrel{s}{\to}& \Mod_k\otimes_{\LMod_{\DD_2(R)}}\Mod_k\otimes_{\RMod_R}\Mod_k \\
&\stackrel{t}{\to}&  \RMod_R \otimes_{\RMod_R}\Mod_k \simeq \Mod_k
\end{eqnarray*}
Here the functor $s$ is induced by $\xi$, and $t$
is induced by $\eta:\Mod_k\otimes_{\LMod_{\DD_2(R)}}\Mod_k\simeq \Mod_k\otimes_{\RMod_{\DD_2(R)}}\Mod_k\to \RMod_R$.
After passing to the left completion, $s$ can be identified with the equivalence
\[
\Mod_k\otimes_{\HL(\LMod_{\DD_2(R)})}\HL(\LMod_{\DD_2(R)})\to \Mod_k\otimes_{\HL(\LMod_{\DD_2})}\Mod_k\otimes_{\RMod_R}\Mod_k
\]
induced by $\HL(\LMod_{\DD_2(R)})\simeq \Mod_k\otimes_{\RMod_R}\Mod_k$.
After passing to the left completion, $t$ can be identified with the equivalence
\[
\HL(\Mod_k\otimes_{\LMod_{\DD_2(R)}}\Mod_k)\otimes_{\RMod_R}\Mod_k \to  \RMod_R \otimes_{\RMod_R}\Mod_k
\]
induced by $\HL(\Mod_k\otimes_{\LMod_{\DD_2(R)}}\Mod_k)\simeq \RMod_R$ (see Lemma~\ref{leftcomp2}).
We also observe that the $k$-linear composite $c$ carries $k\in \Mod_k$ in the domain maps to $k\in \Mod_k$ in the target
(it is enough to verify this after the left completion).
Note that the $t$-structure on $\Mod_k$ is left complete.
We conclude that the composition $c$ is equivalent to the identity. 
\QED




\begin{Proposition}
\label{unit}
Let $\EE$ be a left $\LMod_{\DD_2(R)}$-module in $\PRTT$.
Let $U_{\EE}:\EE\to \Phi_R\circ \Psi_R(\EE)$ be the morphism in $\LMod_{\LMod_{\DD_2(R)}}(\PRTT)$
which is induced by the unit map of the adjunction.
Then $U$ is an equivalence after a left completion.
\end{Proposition}





\Proof
By Lemma~\ref{moritaleft}, 
\[
\Phi_R\circ \Psi_R(\EE)\simeq (\LMod_k\otimes_{\LMod_{\DD_2(R)}}\EE)\otimes_{\LMod_R}\RMod_k.
\]
We have equivalences
\[
(\LMod_k\otimes_{\LMod_{\DD_2(R)}}\EE)\otimes_{\LMod_R}\RMod_k\simeq \RMod_k\otimes_{\LMod_R^{\otimes op}}\LMod_k\otimes_{\LMod_{\DD_2(R)}}\EE
\]
and
\begin{eqnarray*}
  (\RMod_k\otimes_{\LMod_R^{\otimes op}}\LMod_k)\otimes_{\LMod_{\DD_2(R)}}\EE &\simeq& (\RMod_k\otimes_{\RMod_R}\LMod_k)\otimes_{\LMod_{\DD_2(R)}}\EE 
%&\simeq&  \RMod_{k\otimes_Rk}\otimes_{\LMod_{\DD_2(R)}}\EE.
\end{eqnarray*}
(cf. Proposition~\ref{oppositemonoidal}).
Let $\End_{\RMod_R}^l(\Mod_k)^\otimes\in \Alg_1(\PR_k)$ be the endomorphism algebra of $\Mod_k\in \LMod_{\RMod_A}(\PR_k)$.
The right action of $\LMod_{\DD_2(R)}$ on $\RMod_k\otimes_{\RMod_R}\LMod_k$ in the last relative tensor product
is obtained from the universal right module action of $\End_{\RMod_A}^l(\Mod_k)^{\otimes op}$ on $\Mod_k=\LMod_k$
and the monoidal left completion functor
\[
\LMod_{\DD_2(R)}^\otimes\simeq \RMod_{\DD_2(R)}^{\otimes op}\to \End_{\RMod_R}^l(\Mod_k)^{\otimes op}
\]
(cf. the proof of Lemma~\ref{dualcatalg}).
See Proposition~\ref{oppositemonoidal} for the equivalence on the left-hand side.
The right-hand side is induced by $\RMod_{\DD_2(R)}^{\otimes}\to \End_{\RMod_R}^l(\Mod_k)^{\otimes}$
(the right version of $\xi$ in Corollary~\ref{monoidal}, see also  Lemma~\ref{leftcomplemmma})
so that we can identify $\End_{\RMod_R}^l(\Mod_k)^{\otimes op}$ with $\End_{R}^l(\Mod_k)^{\otimes}=\End_{\LMod_R}^l(\Mod_k)^{\otimes}$.


Note that the left module action of $\End_{\RMod_R}^l(\Mod_k)^\otimes$ exhibits
$\Mod_k\otimes_{\RMod_R}\Mod_k$ as a free module of rank one.
To see this, it is enough to prove that
there exists an object $m\in \Mod_k\otimes_{\RMod_R}\Mod_k$
such that the module action functor $\End_{\RMod_R}^l(\Mod_k)\times \Mod_k\otimes_{\RMod_R}\Mod_k\to \Mod_k\otimes_{\RMod_R}\Mod_k$
induces an equivalence $\End_{\RMod_R}^l(\Mod_k)\times \{m\}\to \Mod_k\otimes_{\RMod_R}\Mod_k$.
There exists an equivalence 
$\End_{\RMod_R}^l(\Mod_k)\simeq \Mod_k\otimes_{\RMod_R}\Mod_k$
and the module action functor is induced by the restriction functor
\begin{eqnarray*}
(\Mod_k\otimes_{\RMod_R}\Mod_k)\otimes_k (\Mod_k\otimes_{\RMod_R}\Mod_k) &\simeq& \RMod_{(k\otimes_Rk) \otimes_k (k\otimes_Rk)} \\
&\to&  \RMod_{(k\otimes_Rk)} \\
&\simeq&  \Mod_k\otimes_{\RMod_R}\Mod_k 
\end{eqnarray*}
along the comultiplication morphism $k\otimes_Rk \to  (k\otimes_Rk) \otimes_k (k\otimes_Rk)$ in $\Alg_1(\Mod_k)$
given by the bar construction of $R$.
When we regard $k$ as a $(k\otimes_Rk)$-module, the restriction
\[
(\Mod_k\otimes_{\RMod_R}\Mod_k)\simeq (\Mod_k\otimes_{\RMod_R}\Mod_k)\times \{k\}\to (\Mod_k\otimes_{\RMod_R}\Mod_k)
\]
is equivalent to the identity functor because the composition
$(k\otimes_Rk) \to  (k\otimes_Rk) \otimes_k (k\otimes_Rk)\to (k\otimes_Rk)\otimes_k k$
is the identity where the second morphism is induced by the counit $(k\otimes_Rk)\to k$.
We conclude that $\Mod_k\otimes_{\RMod_R}\Mod_k$ is a free $\End_{\RMod_A}^l(\Mod_k)^\otimes$-module 
of rank one.
The left completion functor $\HL$ is a symmetric monoidal functor which preserves small colimits so that we have
\[
\HL(\RMod_{k\otimes_Rk}\otimes_{\LMod_{\DD_2(R)}}\EE)\simeq \HL(\HL(\RMod_{k\otimes_Rk})\otimes_{\HL(\LMod_{\DD_2(R)})}\EE)\simeq \HL(\RMod_{k\otimes_Rk}\otimes_{\End_{R}^l(\Mod_k)}\EE)\simeq \EE.
\]
By the construction (cf. the proof of Lemma~\ref{moritaleft}), $U$ is induced by the left completion functor $\LMod_{\DD_2(R)}\to \Mod_{k}\otimes_{\RMod_k}\Mod_k$ regarded as the left $\LMod_{\DD_2(R)}$-module map
(namely, it is given by $\LMod_{\DD_2(R)}\otimes_{\LMod_{\DD_2(R)}}(-)\to (\Mod_{k}\otimes_{\RMod_k}\Mod_k)\otimes_{\LMod_{\DD_2(R)}}(-)$).
This proves our assertion.
\QED


Here is an application to the deformation theory of stable $\infty$-categories without $t$-structures.


\begin{Corollary}
\label{without}
Let $\CCC$ be a $k$-linear stable presentable $\infty$-category, that is, an object of $\PR_k$.
Suppose that $\CCC$ has a left and right complete, accessible $t$-structure $(\CCC^{\le0},\CCC^{\ge0})$.
Let $A$ be an augmented $\etwo$-algebra in $\Mod_k$.
Suppose that $\CCC$ is a promoted to $\CCC'\in \LMod_{\LMod_{\DD_2(A)}}(\PR)$ (this amounts to giving a map $f:\DD_2(R)\to \HH^\bullet(\CCC/k)$, see Proposition~\ref{tomapping}).
Then the left completion 
\[
\widehat{L}(\Mod_k\otimes_{\LMod_{\DD_2(A)}}\CCC')\in \RMod_{\LMod_{R}}(\PR)
\]
gives a deformation of $\CCC$ to $R$ (without $t$-structures).
Namely, there exists a canonical equivalence $\widehat{L}(\Mod_k\otimes_{\LMod_{\DD_2(A)}}\CCC')\otimes_{\LMod_R}\Mod_k\simeq \CCC$ in $\PR_k$.
If we regard  $\widehat{L}(\Mod_k\otimes_{\LMod_{\DD_2(A)}}\CCC')\otimes_{\LMod_R}\Mod_k$ 
as the induced left $\LMod_{\DD_2(A)}$-module, it is naturally equivalent to $\CCC'$ corresponding to $f$.
\end{Corollary}


\Proof
Use Lemma~\ref{already}, Proposition~\ref{unit}, and the natural transformation $U_{\CCC'}$.
\QED














\begin{Proposition}
\label{counit}
Let $\DDD$ be a left $\LMod_R$-module in $\PRTT$.
Let $V_{\DDD}:\Psi_R\circ \Phi_R(\DDD)\to \DDD$ be the morphism in $\RMod_{\LMod_{R}}(\PRTT)$
which is induced by the counit map of the adjunction.
Then $V_{\DDD}$ is an equivalence after a left completion.
\end{Proposition}

\Proof
By definition, 
\[
\Psi_R\circ \Phi_R(\DDD)\simeq \LMod_k\otimes_{\LMod_{\DD_2(R)}}(\DDD\otimes_{\LMod_{R}}\RMod_k).
\]
Moreover, there exist canonical equivalences
\begin{eqnarray*}
\LMod_k\otimes_{\LMod_{\DD_2(R)}}(\DDD\otimes_{\LMod_{R}}\RMod_k) &\simeq&  \DDD\otimes_{\LMod_{R}}(\RMod_k\otimes_{\LMod_{\DD_2(R)}^{\otimes op}}\LMod_k) \\
&\simeq& \DDD\otimes_{\LMod_{R}}(\RMod_k\otimes_{\RMod_{\DD_2(R)}}\LMod_k) \\
&\simeq& \DDD\otimes_{\LMod_{R}}  \RMod_{k\otimes_{\DD_2(R)}k}.
\end{eqnarray*}
By Lemma~\ref{leftcomp2}, there exists
a left completion functor $\RMod_{k\otimes_{\DD_2(R)}k}\to \LMod_R$.
It follows that
\begin{eqnarray*}
\HL(\DDD\otimes_{\LMod_{R}}  \RMod_{k\otimes_{\DD_2(R)}k}) &\simeq& \HL(\HL(\DDD)\otimes_{\HL(\LMod_{R})}\HL(\RMod_{k\otimes_{\DD_2(R)}k}))) \\
&\simeq& \HL(\HL(\DDD)\otimes_{\LMod_R}\LMod_R) \\
&\simeq& \HL(\DDD).
\end{eqnarray*}
By the construction (cf. Lemma~\ref{moritaleft}), the counit map is induced by $\RMod_{k\otimes_{\DD_2(R)}k}\to \LMod_R$.
Thus, our assertion follows.
\QED



\section{Main results}
\label{mainsec}

We prove main results of this paper.


\subsection{}
Let $(\EE,\EE^{\le0})\in (\PRTT)_k$ be a $k$-linear stable presentable $\infty$-category $\EE$
equipped with a right complete, accessible $t$-structure $(\EE^{\le0},\EE^{\ge0})$.
Let $\End_k(\EE)^\otimes\in \Alg_1(\PR_k)$ denote the endomorphism monoidal $\infty$-category
which has a universal left module action on $\EE$.

\begin{Definition}
\label{Hochdef}
We define the Hochschild cohomology $\etwo$-algebra $\HH^\bullet(\EE/k)$
to be $E_k(\End_k(\EE)^\otimes)\in \Alg_2(\Mod_k)$ (see Section~\ref{MOA} for $E_k:\Alg_1(\PR_k)\to \Alg_2(\Mod_k)$).
The underlying $\eone$-algebra is the endomorphism algebra of the identity functor in $\End_k(\EE)^\otimes$.
\end{Definition}




\begin{Remark}
One may consider an accessible $t$-structure on $\End_k(\EE)$ determined by the presentable full subcategory $\End_k(\EE)^{\le0}$
spanned by those $k$-linear functors $F$ such that $F(\EE^{\le0})\subset \EE^{\le0}$.
Namely,
$(\End_k(\EE),\End_k(\EE)^{\le0})$ is an endomorphism algebra object defined in $\Alg_1(\PRT)$.
Moreover, by \cite[VIII, Corollary 4.6.7]{DAG}, $\End_k(\EE)^{\le0}$ can be identified with the $\infty$-category of right $t$-exact functors $\EE\to \EE$.
The identity functor $\EE\to \EE$ lies in $\End_k(\EE)^{\le0}$. The endomorphism algebra of the identity functor
is the ordinary Hochschild cohomology $\HH^\bullet(\EE/k)$ (defined above),
and the canonical monoidal functor 
$\LMod_{\HH^\bullet(\EE/k)}^\otimes\to \End_k(\EE)^\otimes$
is right $t$-exact when $\LMod_{\HH^\bullet(\EE/k)}$ is equipped with the $t$-structure given in Remark~\ref{unifiedtstr}.
If one regards the Hochschild cohomology as the endomorphism algebra object of the identity,
it does not depend on the $t$-structure on $\EE$ (thus we do not use the $t$-structure on $\EE$ in Definition~\ref{Hochdef}).
\end{Remark}


Let 
$\LMod_{\LMod_{\DD_2(R)}}(\PRTT)^{\simeq}\times_{(\PRTT)_k^{\simeq}}\{\EE\}$ be the fiber product in $\wCat$
where $q:\LMod_{\LMod_{\DD_2(R)}}(\PRTT)\to (\PRTT)_k$ is the restriction functor 
along the monoidal functor $\Mod_k\to \LMod_{\DD_2(R)}$. As usual, by abuse of notation we write $\EE$ for $(\EE,\EE^{\le0})$.


\begin{Proposition}
\label{tomapping}
There exists a canonical equivalence
\[
\LMod_{\LMod_{\DD_2(R)}}(\PRTT)^{\simeq}\times_{(\PRTT)_k^{\simeq}}\{\EE\}\simeq \Map_{\Alg_2(\Mod_k)}(\DD_2(R), \HH^\bullet(\EE/k)).
\]
\end{Proposition}


\Proof
We first observe that any left $\LMod_{\DD_2(R)}$-module action on $\EE$ in $\PR_k$
is a left $\LMod_{\DD_2(R)}$-module action on $\EE$ in $(\PRTT)_k$ with respect to 
the $t$-structures on $\LMod_{\DD_2(R)}$ and $\EE$.
To see this, it is enough to show that 
the action functor $f:\LMod_{\DD_2(R)}\times \EE\to \EE$
sends $\LMod_{\DD_2(R)}^{\le0}\times \EE^{\le0}$
to $\EE^{\le0}$.
Let $\End_k(\EE)\in \Alg_1(\PR_k)$ be the endomorphism monoidal $\infty$-category
which has a universal left module action on $\EE$.
The left $\LMod_{\DD_2(R)}$-module action on $\EE$
factors through an essentially unique morphism $\LMod_{\DD_2(R)}\to \End_k(\EE)$ in $\Alg_1(\PR_k)$.
We note that $\LMod_{\DD_2(R)}\to \End_k(\EE)$ sends $\DD_2(R)$ to the identity functor of $\EE$.
Note that $f$ preserves small colimits in each variable, and
$\EE^{\le0}$ is closed under small colimits and extensions.
Taking into account  the definition of $\LMod_{\DD_2(R)}^{\le0}$, 
we see that $\LMod_{\DD_2(R)}^{\le0}\times \EE^{\le0}$
maps to $\EE^{\le0}$.
Consequently, 
we are reduced to showing that there exists a canonical equivalence
\[
\LMod_{\LMod_{\DD_2(R)}}(\PR_k)^{\simeq}\times_{(\PR_k)^{\simeq}}\{\EE\}\simeq \Map_{\Alg_2(\Mod_k)}(\DD_2(R), \HH^\bullet(\EE/k)).
\]
By the universality of $\End_k(\EE)$, we have an equivalence
\[
\LMod_{\LMod_{\DD_2(R)}}(\PR_k)^{\simeq}\times_{(\PR_k)^{\simeq}}\{\EE\}\simeq \Map_{\Alg_1(\PR_k)}(\LMod_{\DD_2(R)},\End_k(\EE)).
\]
Using the fully faithful functor $\Theta_k:\Alg_2(\Mod_k)\to \Alg_1(\PR_k)$ (that is, the left adjoit of $E_k$), we have the equivalence
\[
\Map_{\Alg_2(\Mod_k)}(\DD_2(R),\HH^\bullet(\EE/k))\simeq \Map_{\Alg_1(\PR_k)}(\LMod_{\DD_2(R)},\End_k(\EE)).
\]
This completes the proof.
\QED

We consider the sequence of the functors
\[
\RMod_{\LMod_{R}}(\PRTT) \stackrel{\Phi_{R}}{\longrightarrow}  \LMod_{\LMod_{\DD_2(R)}}(\PRTT) \stackrel{q}{\longrightarrow} (\PRTT)_k
\]
where $q$ is the forgetful functor (i.e. the restriction along $\Mod_k\to \LMod_{\DD_2(R)}$).
We shall write $\beta_{R\to k}^{+}:\RMod_{\LMod_{R}}(\PRTT) \to (\PRTT)_k$ for the base change functor along $\LMod_R\to \Mod_k$
in $\PRTT$, which is given by the base change in $\PR_{\mathbb{S}}$ at the level of underlying presentable $\infty$-categories.
Let $\beta_{R\to k}^{\pm}:\RMod_{\LMod_{R}}(\PRTTT) \to (\PRTTT)_k$ be the base change functor along $\LMod_R\to \Mod_k$
in $\PRTTT$. By Proposition~\ref{already}, it can be identified with the restriction of $\beta_{R\to k}^+$.  
We put
\[
\textup{Deform}_{\EE}(R)=\RMod_{\LMod_{R}}(\PRTTT)^\simeq \times_{\beta_{r\to k}^{+},(\PRTTT)^{\simeq}_k}\{\EE\}
\]
where the superscript $\simeq$ indicates the largest Kan subcomplex of the $\infty$-category: $\RMod_{\LMod_{R}}(\PRTTT)^\simeq$ is the largest $\infty$-groupoid contained in the whole $\infty$-category.
An object of $\textup{Deform}_{\EE}(R)$ can be regarded as a pair $(\DDD, \beta_{R\to k}^+(\DDD)\simeq \EE)$
such that $\DDD$ is a complete $R$-linear stable $\infty$-category, and an equivalence
$\DDD\otimes_{\LMod_R}\Mod_k=\beta_{R\to k}^+(\DDD)\simeq \EE$ in $\PRTT$.
We shall refer to  an object of $\textup{Deform}_{\EE}(R)$
is a complete deformation of $\EE$ to $R$.


\begin{Example}
Let
$X$ be a quasi-compact and separated derived (spectral) scheme over $k$. Let $R\to k$ be an argumented commutative connective algebra in $\Mod_k$.
Suppose that $X'\to \Spec R$ is a deformation of $X$ to $R$: There exists an equivalence $f:X'\times_{\Spec R}\Spec k\simeq X$ over $k$.
For a derived scheme $Y$, we let $(\textup{QCoh}(Y), \textup{QCoh}(Y))^{\le0})$ denote the stable $\infty$-category of quasi-coherent sheaves on $Y$ equipped with the left and right complete, accessible $t$-structure (see \cite[VIII]{DAG}). 
Then 
\[
\big{(}(\textup{QCoh}(X'), \textup{QCoh}(X')^{\le0}), f^*:\textup{QCoh}(X')\otimes_{\LMod_R}\Mod_k\simeq \textup{QCoh}(X)\big{)}
\]
provides a complete deformation of $(\textup{QCoh}(X),\textup{QCoh}(X)^{\le0})$ to $R$.
\end{Example}

Let $\EE\in (\PRTTT)_k$.
By Proposition~\ref{already}, $\Phi_R$ induces the functor 
\[
\rho:\RMod_{\LMod_{R}}(\PRTTT)\times_{\beta_{R\to k}^+,(\PRTT)_k}\{\EE\} \longrightarrow \LMod_{\LMod_{\DD_2(R)}}(\PRTTT)\times_{q,(\PRTTT)_k}\{\EE\}.
\]
According to Proposition~\ref{tomapping}, $\rho$ induces
\[
P_R:\textup{Deform}_{\EE}(R)\to \Map_{\Alg_2(\Mod_k)}(\DD_2(R), \HH^\bullet(\EE/k)).
\]




\begin{Theorem}
\label{mainthm}
The functor $P_R:\textup{Deform}_{\EE}(R)\to \Map_{\Alg_2(\Mod_k)}(\DD_2(R), \HH^\bullet(\EE/k))$
is an equivalence of spaces.
\end{Theorem}


\begin{Example}
\label{exsqzero}
Let $k\oplus k[n]\in \Alg_2^+(\Mod_k)$ denote the trivial square zero extension of $k$ by $k[n]$, which is endowed with the augmentation $k\oplus k[n]\to k$ (cf. \cite[X]{DAG}).
Then $\DD_2(k\oplus k[n])\in \Alg_2(\Mod_k)$ is a free $\etwo$-algebra generated by $k[-n-2]$ (see \cite[X, Proposition 4.5.6]{DAG}).
Thus, $\pi_0(\Map_{\Alg_2(\Mod_k)}(\DD_2(k\oplus k), \HH^\bullet(\EE/k))\simeq \HH^{n+2}(\EE/k))$.
The set $\pi_0(\textup{Deform}_{\EE}(k\oplus k[n]))$ of isomorphism classes of deformations to $k\oplus k[n]$ is naturally isomorphic to $\HH^{n+2}(\EE/k)=H^{n+2}(\HH^\bullet(\EE/k))$.
\end{Example}

{\it Proof of Theorem~\ref{mainthm}.}
The symmetric monoidal left completion functor $\HL:\PRTT\to \PRTTT$
induces
$\RMod_{\LMod_R}(\PRTT)\to \RMod_{\LMod_R}(\PRTTT)$
since the $t$-structure on $\LMod_R$ is left complete.
Consider 
\[
\RMod_{\LMod_R}(\PRTTT)\to \RMod_{\LMod_R}(\PRTT) \stackrel{\beta_{R\to k}^+}{\longrightarrow} (\PRTT)_k
\]
where the functor on the left-hand side is induced by the lax symmetric monoidal inclusion
$\PRTTT\to \PRTT$, and the right-hand side is defined by $\beta_{R\to k}^+=\otimes_{\LMod_R}\Mod_k$.
We abuse notation by writing $\beta_{R\to k}^+$ for the composite.
By Proposition~\ref{already}, this composite $\beta_{R\to k}^+$ is equivalent to
\[
\RMod_{\LMod_R}(\PRTTT)\stackrel{\beta_{R\to k}^{\pm}}{\longrightarrow} (\PRTTT)_k\hookrightarrow (\PRTT)_k.
\]
Thus, we have
\[
\xymatrix{
\RMod_{\LMod_R}(\PRTT)\ar[r]^{\HL_R} \ar[d]_{\beta^+_{R\to k}} &  \RMod_{\LMod_R}(\PRTTT) \ar[d]^{\beta^{+}_{R\to k}} \\ 
(\PRTT)_k \ar[r]^{\HL_k}  &  (\PRTTT)_k 
}
\]
which commutes up to canonical homotopy,
where
horizontal arrows are induced by completion functors.
We consider the composition
\[
 \HL_k \circ \beta_{R\to k}^+ \circ \Psi_R  :\LMod_{\LMod_{\DD_2(R)}}(\PRTT)  \to (\PRTTT)_k.
\]
The composite
$\beta_{R\to k}^+ \circ \Psi_R$
is equivalent to $\Phi_R\circ \Psi_R$ after composing the forgetful functor $q$.
Thus, Proposition~\ref{unit} shows that  
$\HL_k \circ \beta_{R\to k}^+ \circ \Psi_R$
and $\beta_{R\to k}^+\circ  \HL_R\circ \Psi_R$
are equivalent to $\HL_k\circ q$.
We then obtain the diagram
\[
\xymatrix{
\RMod_{\LMod_R}(\PRTTT) \ar[r]^{\Phi_R} \ar[d]^{\beta_{R\to k}^+} & \LMod_{\LMod_{\DD_2(R)}}(\PRTTT) \ar[r]^{\HL_R \circ \Psi_R} \ar[d]^{ q}  &  \RMod_{\LMod_R}(\PRTTT) \ar[d]^{\beta^+_{R\to k}}   \\
(\PRTTT)_k  \ar[r]^{\textup{id}} &    (\PRTTT)_k  \ar[r]^{\textup{id}} &  (\PRTTT)_k
}
\]
which commutes up to homotopy. 
Here $\HL_R \circ \Psi_R$ in the diagram means the restricted functor $\HL_R \circ \Psi_R|_{\LMod_{\LMod_{\DD_2(R)}}(\PRTTT)}$.
By Proposition~\ref{counit}, the upper horizontal composite $\HL_R \circ \Psi_R\circ \Phi_R$ is naturally equivalent to the identity functor.
It gives rise to the sequence
\begin{eqnarray*}
\RMod_{\LMod_R}(\PRTTT)\times_{\beta_{R\to k}^+,(\PRTTT)_k}\{\EE\} &\stackrel{\rho}{\longrightarrow}& \LMod_{\LMod_{\DD_2(R)}}(\PRTTT)\times_{q,(\PRTTT)_k}\{\EE\} \\
&\longrightarrow& \RMod_{\LMod_R}(\PRTTT) \times_{(\PRTTT)_k}\{\EE\}
\end{eqnarray*}
whose composition is naturally equivalent to the identity functor,
where the second functor is 
induced by
$\beta_{R\to k}^+\circ  \HL_R\circ \Psi_R$ and $\HL_R\circ \Psi_R$.
%\[
%\LMod_{\LMod_{\DD_2(R)}}(\PRTTT) \times_{q, (\PRTTT)_k}\{\EE\} \to \RMod_{\LMod_{R}}(\PRTTT) \times_{\beta_{R\to k}^+, (\PRTTT)_k}\{\EE\}.
%\]


Next, we consider 
\begin{eqnarray*}
\LMod_{\LMod_{\DD_2(R)}}(\PRTTT)\times_{q,(\PRTTT)_k}\{\EE\} &\longrightarrow& \RMod_{\LMod_R}(\PRTTT) \times_{\beta_{R\to k}^+,(\PRTTT)_k}\{\EE\} \\
&\stackrel{\rho}{\longrightarrow}& \LMod_{\LMod_{\DD_2(R)}}(\PRTTT)\times_{q,(\PRTTT)_k}\{\EE\}.
\end{eqnarray*}
It will suffice to prove that the composite is naturally equivalent to the identity functor.
It is enough to show that $\Phi_R\circ \HL_R \circ \Psi_R:\LMod_{\LMod_{\DD_2(R)}}(\PRTT)\to \LMod_{\LMod_{\DD_2(R)}}(\PRTTT)$ is naturally equivalent to the functor $\HL_{\LMod_{\DD_2(R)}}:\LMod_{\LMod_{\DD_2(R)}}(\PRTT)\to \LMod_{\LMod_{\DD_2(R)}}(\PRTTT)$ induced by 
$\HL_k$ and the restriction along $\LMod_{\DD_2(R)}\to \HL_k(\LMod_{\DD_2(R)})$.
According to Proposition~\ref{already} and the fact that $\HL$ is a symmetric monoidal colimit-preserving functor, we see that the diagram
\[
\xymatrix{
\RMod_{\LMod_R}(\PRTT) \ar[r]^{\HL_R} \ar[d]^{\Phi_R}  &  \RMod_{\LMod_R}(\PRTTT) \ar[d]^{\Phi_R} \\
\LMod_{\LMod_{\DD_2(R)}}(\PRTT) \ar[r]_{\HL_{\LMod_{\DD_2(R)}}} & \LMod_{\LMod_{\DD_2(R)}}(\PRTTT)
}
\]
commutes up to canonical homotopy. It follows from Proposition~\ref{unit} that $\Phi_R\circ \HL_R \circ \Psi_R\simeq \HL_k\circ \Phi_R\circ \Psi_R\simeq \HL_{\LMod_{\DD_2(R)}}$.
This completes the proof.
\QED



\begin{Remark}
For a morphism $f:\DD_2(R)\to \HH^{\bullet}(\EE/k)$ of $\etwo$-algebras,
the corresponding deformation is defined as $\widehat{L}(\Mod_k\otimes_{\LMod_{\DD_2(R)}}\EE)$.
Here the left module action of $\LMod_{\DD_2(R)}^\otimes$ on $\EE$ is induced by $f$, the canonical monoidal functor
$\LMod_{\HH^{\bullet}(\EE/k)}^\otimes\to \mathcal{E}nd_{k}(\EE)^\otimes$, and the canonical action of $\mathcal{E}nd_{k}(\EE)^\otimes$ on $\EE$.
\end{Remark}





















\subsection{}
We interpret Theorem~\ref{mainthm} in terms of formal moduli problems, that is, pointed formal stacks.
We first define a functor which describes the deformation problem of $\EE\in (\PRTTT)_k$.

\begin{Definition}
\label{deffunctorcomplete}
Let 
$\Theta_k^\pm:\Alg_2(\Mod_k^{\le0})\to \Alg_1((\PRTTT)_k)$ be the functor given by $B\mapsto (\LMod_B^\otimes,\LMod_B^{\le0})$ (see Construction~\ref{thetaTTT}). We set
\[
\textup{RLin}^{\wedge}(k):=\RMod((\PRTTT)_k)\times_{\Alg_1((\PRTTT)_k),\Theta_k^\pm}\Alg_2(\Mod_k^{\le0}).
\]
where $\RMod((\PRTTT)_k)\to \Alg_1((\PRTTT)_k)$ is the forgetful functor.
Let
 $\textup{RLin}^\wedge(k)^\dagger$ be the subcategory spanned by coCartesian morphisms over $\Alg_2(\Mod_k^{\le0})$.
Let
$\textup{RLin}^\wedge(k)_{/(\EE,k)}^\dagger$
be the overcategory where $(\EE,k)$ means $\EE\in (\PRTTT)_k$ lying over $k\in \Alg_2(\Mod_k^{\le0})$.
We then have a left fibration $r:\textup{RLin}^\wedge(k)_{/(\EE,k)}^\dagger\to \Alg_2^+(\Mod_k^{\le0})$.
Given $R\in \Alg_2^+(\Mod_k^{\le0})$ we refer to an object of the fiber $r^{-1}(R)$ over $R$ as a complete deformation of $\EE$ to $R$. 

We define 
\[
\overline{\textup{Deform}}_{\EE}:\Alg_2^+(\Mod_k^{\le0})\to \wSSS
\]
to be the functor which corresponds to the left fibration $r$. 
Let $\textup{Deform}_{\EE}:\textup{Art}_2\to \wSSS$ be the restriction of $\overline{\textup{Deform}}_{\EE}$ to $\textup{Art}_2$.
\end{Definition}



Next, we recall formal $\eenu$-moduli problems from \cite[Section 4]{DAG}.
Let $n$ be a natural number or $\infty$.
A functor $F:\textup{Art}_n\to \SSS$ from $\infty$-category of Artin $\eenu$-algebras is a formal $\eenu$-moduli problem if
\begin{itemize}
  \item $F(k)$ is a contractible space,
\item for any pullback square \[
\xymatrix{
R \ar[r] \ar[d] &  R_0 \ar[d] \\
R_1 \ar[r] & R_{01}
}
\]
in $\textup{Art}_n$
such that $H^0(R_0)\to H^0(R_{01})$ and $H^0(R_1)\to H^0(R_{01})$ are surjective, the square
 \[
\xymatrix{
F(R) \ar[r] \ar[d] &  F(R_0) \ar[d] \\
F(R_1) \ar[r] & F(R_{01})
}
\]
is a pullback diagram.
\end{itemize}
Let $\widehat{\mathsf{Stack}}_n^\ast$ be the full subcategory of $\Fun(\textup{Art}_n, \SSS)$, which consists of formal $\eenu$-moduli problems.
When $n$ is a natural number, thanks to a theorem of Lurie \cite[X, Theorem 4.0.8]{DAG} there exists an equivalence of $\infty$-categories
\[
\widehat{\mathsf{Stack}}_n^\ast \simeq \Alg_n^+(\Mod_k).
\]
Through the equivalence,
an augmented algebra $B\in \Alg_n^+(\Mod_k)$ corresponds to the formal $\eenu$-moduli problem $\mathcal{F}_{B}^{(n)}: \textup{Art}_n\to  \SSS$
defined informally by $R \mapsto \Map_{\Alg_n^+(\Mod_k)}(\DD_n(R),B)$.



\begin{Theorem}
\label{mainthm2}
The deformation functor $\textup{Deform}_{\EE}:\textup{Art}_2\to \wSSS$
is a formal $\etwo$-moduli problem $\mathcal{F}_{k\oplus \HH^\bullet(\EE/k)}^{(2)}$ corresponding to the augmented $\etwo$-algebra $k\oplus \HH^\bullet(\EE/k)\to k$.
\end{Theorem}


\Proof
Consider the adjoint pair $U:\Alg_2^+(\Mod_k)\rightleftarrows \Alg_2(\Mod_k):T$ where $U$ is the forgetful functor, and $T$ is its right adjoint given by $A\mapsto [\textup{pr}_1:k\oplus A\to k]$
where $k\oplus A$ means the product of $\etwo$-algebras.
This adjoint pair induces a canonical equivalence of mapping spaces
$\eta_R:\Map_{\Alg_2(\Mod_k)}(\DD_2(R), \HH^\bullet(\EE/k))\simeq \Map_{\Alg_2^+(\Mod_k)}(\DD_2(R), k\oplus \HH^\bullet(\EE/k))$.
In view of Theorem~\ref{mainthm}, it is enough to construct 
the functor
\[
\textup{Deform}_{\EE}(R)\to  \Map_{\Alg_2^+(\Mod_k)}(\DD_2(R), k\oplus \HH^\bullet(\EE/k))
\]
functorially on $R\in \Alg_2^+(\Mod_k^{\le0})$, which is equivalent to $P_R$ through $\eta_R$.
Namely, it will suffice to construct a natural transformation $\textup{Deform}_{\EE}\to \mathcal{F}_{k\oplus \HH^\bullet(\EE/k)}^{(2)}$ having the required property.
The construction is done in \cite[X, Construction 5.3.18]{DAG} up to a small modification: One uses $(\PRTT)_k$ instead of  $\textup{LinCat}_k$ in {\it loc.cit.}
(strictly speaking, the convention on left and right modules is reversed with ours). 
Besides, we can also apply the axiomatic formulation in \cite[Section 4.4]{IM}.
\QED


\subsection{Commutative bases}
We consider the restriction to deformations to commutative bases. We assume that the base field $k$ is of characteristic zero.
Let $\CAlg(\Mod_k)\to \Alg_2(\Mod_k)$ be the canonical forgetful functor obtained from
the canonical map of $\infty$-operads $\mathbf{E}_2^\otimes\to \mathbf{E}_\infty^\otimes$.
It induces $\textup{Art}=\textup{Art}_{\infty}\to \textup{Art}_2$ so that the composition gives the functor
\[
\Fun(\textup{Art}_2,\SSS)\longrightarrow  \Fun(\textup{Art},\SSS).
\]
According to \cite[Lemma 7.5]{IM} it preserves formal moduli problems so that we have the restriction $res_{2/\infty}:\widehat{\mathsf{Stack}}_2^*\rightarrow \widehat{\mathsf{Stack}}_\infty^*$.
Let $\textup{Lie}_k$ be the $\infty$-category of dg Lie algebras over $k$.
The $\infty$-category is obtained from the category of dg Lie algebras by inverting quasi-isomorphisms.
Through the categorical equivalence $\textup{Lie}_k\simeq \widehat{\mathsf{Stack}}_\infty^*$ (see \cite[X, 2.0.2]{DAG}) and $\Alg_2^+(\Mod_k)\simeq \widehat{\mathsf{Stack}}_\infty^*$
the functor $res_{s/\infty}$ corresponds to 
\[
\Alg_2^+(\Mod_k)\to \textup{Lie}_k.
\]
The underlying complex of  $res_{2/\infty}(\epsilon:B\to k)$ is $\Ker(\epsilon)[1]$ where $\Ker$ denotes the fiber (see \cite[Proposition 7.7]{IM}).
By abuse of notation we write $\HH^\bullet(\EE/k)[1]$ for the underlying dg Lie algebra $res_{2/\infty}(k\oplus \HH^\bullet(\EE/k) \to k)$.
We set $\textup{Deform}_{\EE}^{\infty}=res_{2/\infty}(\textup{Deform}_{\EE})$.


\begin{Corollary} 
\label{mainthm3}
The deformation functor
$\textup{Deform}_{\EE}^{\infty}$ is a formal $\mathbf{E}_\infty$-moduli problem $\mathcal{F}_{\HH^\bullet(\EE/k)[1]}^{(\infty)}$ corresponding to $\HH^\bullet(\EE/k)[1]$.
\end{Corollary}


\subsection{Obstruction theory}
From a formal moduli problem, one can obtain the obstruction theory of deformations. We will explain this consequence for the reader's convenience.
We refer the reader to \cite[Section 3.3]{BT} for a comprehensive account.
Let $p:R'\to R$ be a morphism in $\textup{Art}_2$, which fits in the pullback square
\[
\xymatrix{
R' \ar[r]^p \ar[d] & R \ar[d] \\
k \ar[r] & k\oplus V[i] 
}
\]
in $\textup{Art}_2$, where $V$ is a finite dimensional vector space, $i$ is a positive integer,
and $k\oplus V[i]$ is the trivial square zero extension by $V[i]$



\begin{Example}
Let $p:R'\to R$ be a surjective map of ordinary (discrete) Artin local algebras in $\textup{Art}$.
Let $I=\Ker(p)$ and let $\mathfrak{m}_{R'}$ be the maximal ideal of $R'$.
We assume that  $\mathfrak{m}_{R'}\cdot I=0$, that is, $p$ is an elementary extension of Artin local algebras.
There exists a pullback square
\[
\xymatrix{
R' \ar[r]^p \ar[d] & R \ar[d] \\
k \ar[r] & k\oplus I[1] 
}
\]
in $\textup{Art}$, where $k\oplus I[1]$ is the trivial square zero extension by $I[1]$ (see e.g. \cite[Lemma 3.3]{BT}). 
We remark that every surjective map of ordinary Artin local algebras in $\textup{Art}$
decomposes as a sequence of elementary extensions.
\end{Example}

Suppose that  $\DDD\in \pi_0(\textup{Deform}_{\EE}(R))$.
We consider the problem of whether or not $\DDD$ is promoted to $R'$ along $p:R'\to R$.


\begin{Theorem}
\label{mainthm4}
There exists an element $\textup{Obs}(\DDD,p)\in \HH^{i+2}(\EE/k)\otimes_kV$ 
such that $\textup{Obs}(\DDD,p)=0$ if and only if there exists $\DDD'\in \pi_0(\textup{Deform}_{\EE}(R'))$ lying over $\DDD$ along  the map $p$.
\end{Theorem}

\Proof
By Theorem~\ref{mainthm2}, we have the canonical equivalence 
\[
\alpha:\textup{Deform}_{\EE}(R')\simeq \textup{Deform}_{\EE}(R)\times_{\textup{Deform}_{\EE}(k\oplus V[i])}\textup{Deform}_{\EE}(k).
\]
Note that $\textup{Deform}_{\EE}(k)$ is a contractible space.
Since $\DD_2(k\oplus V[i])$ is a free $\etwo$-algebra generated by $V^{\vee}[-i-2]$ (\cite[X, Proposition 4.5.6]{DAG}),
it follows that $\phi:\textup{Deform}_{\EE}(k\oplus V[i])\simeq \HH^{i+2}(\EE/k)\otimes_kV$.
Here, $V^\vee$ is the dual vector space.
Moreover, by the construction,
$0\in \HH^{i+2}(\EE/k)\otimes_kV$ corresponds to the trivial deformation, that is, the image of $\textup{Deform}_{\EE}(k)\to \textup{Deform}_{\EE}(k\oplus V[i])$.
We define $\textup{Obs}(\DDD,p)$ to be the image of $\DDD\in \pi_0(\textup{Deform}_{\EE}(R))$
in $\HH^{i+2}(\EE/k)\otimes_kV$ (through $\phi$).
Taking into account the equivalence $\alpha$, we see that 
there exists $\DDD'\in \pi_0(\textup{Deform}_{\EE}(R'))$ lying over $\DDD$ if and only if
$\textup{Obs}(\DDD,p)$ is equivalent to the trivial deformation.
The latter condition amounts to the condition that $\textup{Obs}(\DDD,p)=0$.
\QED




