The following theorem is the completely regular analogue of Theorem \ref{theorem mult inverse}.

\begin{theorem}\label{theorem 1}
   Let $S$ be a seminearring. Then the following statements are equivalent:
  \begin{itemize}
    \item [(1)] $S$ is generalized left completely regular (GLCR) as well as multiplicatively completely regular;
    \item [(2)] Every $\mathcal{H}^+$ -class is a completely regular near-ring;
    \item [(3)] $S$ is a union (disjoint) of completely regular near-rings.
  \end{itemize}
\end{theorem}
\begin{proof}
  $(1)\Rightarrow (2)$:
  Suppose $(1)$ holds.
  Then by Theorem 2.19 of \cite{Tuhin2} every $\mathcal{H}^+$ -class is a near-ring. Let $a\in S$ and $y \in \mathcal{H}_{a}^+$. Then by Lemma 2.22 of \cite{Tuhin2} there exists a unique element $y^* \in \mathcal{H}_{a}^+$ such that $y + y^* + y$ $=$ $y$, $y + y^*$ $=$ $y^* + y$ and $(y + y^*)y$ $=$ $y + y^*$. Since $S$ is multiplicatively completely regular, there exists a unique $c_{y}\in S$ such that $yc_{y}y$ $=$ $y$, $c_{y}yc_{y}$ $=$ $c_{y}$ and $c_{y}y$ $=$ $yc_{y}$.
  Hence $(y + y^* + y)c_{y}y$ = $yc_{y}y$, {\it i.e.},
  %$yc_{y}y + y^*c_{y}y + yc_{y}y = yc_{y}y$ whence
  $y + y^*c_{y}y + y = y.$
  %\begin{eqnarray*}
%  % \nonumber % Remove numbering (before each equation)
%                  && y + y^* + y = y \\
%                   \Rightarrow && (y + y^* + y)c_{y}y = yc_{y}y\\
%                   \Rightarrow && yc_{y}y + y^*c_{y}y + yc_{y}y = yc_{y}y\\
%                   \Rightarrow && y + y^*c_{y}y + y = y.
%  \end{eqnarray*}
  Also,
  %\begin{eqnarray*}
                    % \nonumber % Remove numbering (before each equation)
                      %&&            y^* + y + y^* = y^* \\
$(y^* + y + y^*)c_{y}y$ = $y^*c_{y}y$
%{\it i.e.}, $y^*c_{y}y + yc_{y}y + y^*c_{y}y = y^*c_{y}y$
 implies that $y^*c_{y}y + y + y^*c_{y}y = y^*c_{y}y$.
                    %\end{eqnarray*}
   Now $y \mathcal{H^+} y^*$. Since $\mathcal{H}^+$ is a right congruence ({\it cf.} Lemma 2.20 of \cite{Tuhin2}), $yc_{y}y\mathcal{H^+}y^*c_{y}y$. So $y\mathcal{H^+}y^*c_{y}y$. %Therefore  $y^*c_{y}y\in \mathcal{H}_{a}^+$. Since $y^*c_{y}y$ $+$ $y$ $=$ $y^*c_{y}y$ $+$ $yc_{y}y$ $=$ $(y+y^*)c_{y}y\in \mathcal{H}_{a}^{+}\cap E^{+}(S)$, $y^*$ $=$ $y^*c_{y}y$.
  As $y^*$, $y\in \mathcal{H}_{a}^+$ and $(\mathcal{H}_{a}^+,+,\cdot)$ is a near-ring, so $y^*y\in \mathcal{H}_{a}^+$.
  Now $y^*y$ $\mathcal{H}^+$ $y$ implies that $y^*yc_{y}$ $\mathcal{H}^+$ $yc_{y}$ ($\because\mathcal{H^+}$ is a right congruence).
Hence $y^*c_{y}y$ $\mathcal{H}^+$ $yc_{y}$ ($\because yc_{y}=c_{y}y$).
Thus $y$ $\mathcal{H}^+$ $yc_{y}$ ($\because$ $y\mathcal{H^+}y^*c_{y}y$).
Therefore, $y$ $\mathcal{H}^+$ $c_{y}y$
whence $yc_{y}$ $\mathcal{H}^+$ $c_{y}yc_{y}$.
So $y$ $\mathcal{H}^+$ $yc_{y}$ and $yc_y$ $\mathcal{H}^+$ $c_{y}$.
        %\end{eqnarray*}
 Therefore $c_{y}\in \mathcal{H}_{a}^+$. Hence $(\mathcal{H}_{a}^+, +, \cdot)$ is a completely regular near-ring.
$(2)\Rightarrow (3)$ is obvious.
$(3)\Rightarrow (1)$ holds in view of Theorem 2.19 of \cite{Tuhin2}.
\end{proof}
The following result is the zero-symmetric counterpart of Theorem \ref{theorem 1} whose proof follows from Theorem 2.25 \cite{Tuhin2} and Theorem \ref{theorem 1}.
\begin{theorem}\label{theorem 2}
   Let $S$ be a seminearring. Then the following statements are equivalent:
  \begin{itemize}
    \item [(1)] $S$ is both generalized left completely regular (GLCR) and generalized right completely regular (GRCR) as well as multiplicatively completely regular;
    \item [(2)] Every $\mathcal{H}^+$ -class is a completely regular, zero-symmetric near-ring;
    \item [(3)] $S$ is a union (disjoint) of completely regular, zero-symmetric near-rings.
  \end{itemize}
\end{theorem}
To conclude the paper we obtain the following result, the Clifford analogue of Theorem \ref{theorem mult inverse}, by combining Theorems \ref{theorem mult inverse}, \ref{theorem mult inverse zero symm version}, \ref{theorem 1}, \ref{theorem 2} together with the fact that every Clifford near-ring is zero-symmetric.
\begin{theorem}\label{theorem Clifford}
Let $S$ be a seminearring. Then the following statements are equivalent:
  \begin{itemize}
   \item [(1)] $S$ is GLCR as well as multiplicatively Clifford seminearring;
    \item [(2)] $S$ is both GLCR , GRCR as well as multiplicatively Clifford seminearring;
    \item [(3)] Every $\mathcal{H}^+$ -class is a Clifford near-ring;
    \item [(4)] $S$ is a union (disjoint) of Clifford near-rings.
  \end{itemize}
\end{theorem}
