% Our work provides the natural counterpart of the Fusco and Julin result for the capillarity functional, FAREI UN RIFERIMENTO AD UNA FIGURA PER FAR CAPIRE CHE È NATURALE. Even if our main goal is to provide the suitable adaptation of that result, our technique allows to strenghten it, yielding to the second part of the following theorem as a byproduct:

The next theorem contains our main results about the capillarity isoperimetric problem, that is the natural analogue of the previously known quantitative isoperimetric inequalities in strong form (see \cref{fig:asymmetry}).

\begin{theorem}[{Strong and barycentric quantitative inequalities in capillarity problems -- cf. \cref{thm:capillarityStrongQuantitative}, \cref{cor:bar-quantitative}, \cref{cor:barycentric-Fraenkel}}]\label{thm:MAINcapillarity}
%
Let $n \in \N$ with $n\ge 2$, $\lambda \in (-1,1)$. There exists $C_{\ref{thm:MAINcapillarity}}>0$ depending on $n,\lambda$ such that for any set of finite perimeter $E \subset \{x_n\ge 0\}\subset \R^n$ with $|E|=|B^\lambda|$ there holds
\begin{equation*}
    \inf\left\{\int_{\partial^* E \cap \{x_n>0\}} \left| \nu_E(x) - \frac{x-(x',-\lambda)}{|x-(x',-\lambda)|} \right|^2 \de \hausdorff^{n-1} (x) \st x' \in\{x_n=0\}
\right\} \le 
    C_{\ref{thm:MAINcapillarity}} \big[P_\lambda(E)- P_\lambda(B^\lambda)\big].
\end{equation*}
Moreover, for any $d>\diam_H B^{\lambda}$ there exists a constant $C_{\ref{thm:MAINcapillarity}}'>0$ depending on $n$, $\lambda$ and $d$ such that for every set of finite perimeter $E\subset \{x_n\ge 0\}\subset \R^n$ with $|E|=|B^\lambda|$ and $\diam_H E\leq d$ there holds
    \begin{equation*}
        |E\symmdiff (B^{\lambda}+\barycenter_H E)|^2 + \int_{\partial^*E\cap \{x_n>0\}} \left|\nu_E(x)-\frac{x-(\barycenter_H E,-\lambda)}{|x-(\barycenter_H E,-\lambda)|}\right|^2\de\hausdorff^{n-1}(x) \leq C_{\ref{thm:MAINcapillarity}}' \big[P_\lambda(E)- P_\lambda(B^\lambda)\big],
    \end{equation*}
where $\diam_H E$ is the diameter of the projection of $E$ onto $\{x_n=0\}$, and $\barycenter_H E:= \tfrac{1}{|E|} \int_E (x_1,\ldots, x_{n-1}) $.
\end{theorem}

Inequalities in \cref{thm:MAINcapillarity} are stated here for sets having fixed volume $|E|=|B^\lambda|$, but there clearly hold scaling invariant counterparts of such inequalities by normalizing the quantities involved in terms of the suitable power of $|E|$ (see \cref{thm:capillarityStrongQuantitative}, \cref{cor:bar-quantitative}, \cref{cor:barycentric-Fraenkel}).\\
In fact, we will also prove a barycentric version of the strong quantitative inequality for capillarity problems for possibly \emph{unbounded} sets, replacing $\barycenter_H E$ (whose definition could be ill posed in this case) with a nonlinear notion of barycenter, well-defined for any set of finite measure, thus getting an inequality with a constant independent of the diameter of the competitor. Such a quantitative inequality is stated in \cref{cor:tilde-bar-quantitative}. See also \cref{rem:MoreBarycentricInequlities} for additional comments.\\
Finally, we remark that the exponents in the inequalities in \cref{thm:MAINcapillarity} are sharp, as we show in \cref{subsec:sharp}.

