\noindent\textbf{Organization.}
In \cref{sec:SetsFinitePerimeter} we collect the basic definitions and facts on sets of finite perimeter, while in \cref{sec:capillarity} we provide the first tools specific for the capillarity problem. In \cref{subsec:fuglede-capillarity} we obtain Fuglede-type results for the capillarity functional.
In \cref{sec:proof-capillarity} and \cref{sec:BarycentricCapillarity} we prove the strong and barycentric quantitative inequalities in capillarity problems. In \cref{subsec:sharp} we show that the exponents in our results are sharp.
In \cref{sec:cones} we prove the strong and barycentric quantitative inequalities in cones.
In \cref{AppendixA} we recall some results in regularity theory for sets satisfying certain weak notions of perimeter minimality and a version of Ekeland's variational principle. 
In \cref{AppendixB} we recall some technical identities and estimates.




\section{Strong quantitative isoperimetric inequalities for capillarity problems}


\begin{center}
\emph{Throughout the whole paper it is assumed that $n\in \N$ with $n\ge 2$, and $\lambda \in (-1,1)$ are fixed.}    
\end{center}


\noindent\textbf{List of symbols.}

\begin{itemize}
    \item $B_r(x)$ = open ball of radius $r$ and center $x$ in $\R^n$. We denote $B_r:= B_r(0)$.

    \item $|E|$ = Lebesgue measure of a set $E\subset \R^n$.

    \item $\Braket{v,w}$ denotes Euclidean scalar product, for $v,w \in \R^n$.

    \item $d_{\hausdorff}$ denotes Hausdorff distance in $\R^n$, $\hausdorff^s$ denotes $s$-dimensional Hausdorff measure in $\R^n$.

    \item $\partial^*E$ = reduced boundary of a set $E\subset \R^n$, $P(E,\cdot):= \hausdorff^{n-1}\mres \partial^*E$ denotes the perimeter measure, $P(E):=P(E,\R^n)$.

    %\item $x_{\lambda} = -\lambda e_n$.

    \item $B^\lambda = \{x \in B : \Braket{x, e_n} > \lambda\} - \lambda e_n$.

    \item $B^\lambda(v) := \frac{v^{\frac{1}{n}}}{|B^\lambda|^{\frac1n}} B^\lambda$, for any $v>0$.

    \item $B^\lambda(v,x) := B^\lambda(v)  +x$, for any $x \in \{x_n=0\}$. In particular $B^\lambda(v)=B^\lambda(v,0)$.

    \item $H^+:=\{ x_n >0\}$, $H:=\{x_n\ge0\} = \overline{H^+}$.

    \item $\S^{n-1} := \partial B_1$, $\S^{n-1}_+:=\partial B_1 \cap \{x_n\ge 0\}$.

    \item $P_\lambda(E) := P(E,H^+) -\lambda \hausdorff^{n-1}(\partial^* E \cap \partial H)$.

    \item $\alpha_\lambda, D_\lambda$ denote capillarity Fraenkel asymmetry and deficit, respectively, defined in \cref{def:Asymmetry}.

    \item $w_\lambda$ denotes the function that parametrizes the boundary of $B^\lambda$ as a graph over $\S^{n-1}_+$, defined in \cref{def:DistanzaC1}.

    \item $\mu_{\lambda}, \mu_{\lambda,0}$ denote capillarity oscillation asymmetries, defined in \cref{def:capillarity-oscillation}.

    %\item $P_\lambda(B^\lambda):= P_\lambda(B^\lambda(|B^\lambda|, x)) =  P(B, \{x_n>\lambda\}) -\lambda {\hausdorff}^{n-1}(B\cap \{x_n=\lambda\})$.

    \item $C_{n,\lambda}$ denotes a positive constant depending on $n,\lambda$ only, that may change from line to line.

    \item $O(A)$ denotes a real quantity such that $O(A) \le C_{n,\lambda} A$ for some $C_{n,\lambda}>0$.

    \item ${\rm bar}_H F := \tfrac{1}{|F|} \int_F (x-\Braket{x, e_n}e_n) \de x$, for any set $E\subset H$ with $\int_E |x| <+\infty$.

    \item $\psi(t) := \max\{ -100 , \min\{ t, 100\}\}$, defined in \eqref{eq:DefPSI}.

    \item $\widetilde{b}(F) := \int_F \left( \psi(x_1), \ldots, \psi(x_{n-1}) \right) \de x$ for any $F \subset H$ with $|F|<+\infty$, defined in \eqref{eq:AlternativeBarycenter}.

    \item $k_\lambda \in \N$ is the least integer such that $k_\lambda\ge \max\{10, 16/(1-|\lambda|)^2)\}$, defined in \eqref{eq:DefKlambda}.
\end{itemize}



\subsection{Sets of finite perimeter}\label{sec:SetsFinitePerimeter}

We refer to \cite{AmbrosioFuscoPallara, MaggiBook} for a complete account on the theory of sets of finite perimeter.
The perimeter of a measurable set $E\subset\R^n$ in an open set $A\subset \R^n$ is defined by
\begin{equation*}
P(E,A):=\sup\left\{\int_E {\rm div}\, T \st T \in C_c^1(A;\R^n), \,\, \|T\|_\infty \le1\right\}.
\end{equation*}
Denoting $P(E):=P(E,\R^n)$, we say that $E$ is a set of finite perimeter if $P(E)<+\infty$.
If $E$ is a set of finite perimeter, the characteristic function $\chi_E$ has a distributional gradient $D\chi_E$ that is a vector-valued Radon measure on $\R^n$ such that
\begin{equation*}
\int_E {\rm div}\, T  = - \int_{\R^n} T  \de D\chi_E ,
\end{equation*} 
for any field $T \in C_c^1(\R^n;\R^n)$.
The set function $P(E,\cdot)$ defined above can be extended as a positive Borel measure on $\R^n$. Moreover, the measure $P(E,\cdot)$ coincides with the total variation $|D\chi_E|$ of the distributional gradient, and it is concentrated on the reduced boundary
\begin{equation*}
\partial^*E : = \left\{ x \in {\rm spt} |D\chi_E| \st \exists\, \nu^E(x):=-\lim_{r\to0} \frac{D\chi_E(B_r(x))}{|D\chi_E(B_r(x))|} \text{ and } |\nu^E(x)|=1 \right\}.
\end{equation*}
The vector $\nu^E$ is called the generalized outer normal of $E$.
Moreover $P(E,\cdot) = \hausdorff^{n-1}\mres \partial^*E$, and the distributional gradient can be written as $D\chi_E = - \nu^E \hausdorff^{n-1}\mres \partial^*E$.




\subsection{Capillarity problem in the half-space and related asymmetry indexes}\label{sec:capillarity}

We begin with the basic definitions and properties about the quantities involved with the capillarity problem.

\begin{remark}[Alternative expression for $P_{\lambda}$]\label{rem:PlambdaConDivergenza}
Let $E \subset H$ be a measurable set. We observe that
\[
P_\lambda(E) = \int_{\partial^*E\cap H^+}1 - \lambda \Braket{e_n, \nu_E} \de \hausdorff^{n-1},
\]
where $\nu_E$ is the generalized outer normal to $E$. In particular, since $|\lambda|<1$, we have that $P_\lambda(E)\ge0$. The previous identity follows from the divergence theorem, indeed
\begin{equation*} 0 = \int_E \divergence\, e_n \de x = - \hausdorff^{n - 1}(\partial^*E \cap \partial H) + \int_{\partial^*E \cap H^+} \Braket{e_n, \nu_E}  \de \hausdorff^{n-1}.
\end{equation*}
\end{remark}

\begin{definition}[Capillarity Fraenkel asymmetry and isoperimetric deficit]\label{def:Asymmetry}
Let $E \subset H$ be a Borel set with measure $|E|=v\in(0,+\infty)$. Denoting $B^\lambda(v) := \frac{v^{\frac{1}{n}}}{|B^\lambda|^{\frac1n}} B^\lambda$, and $B^\lambda(v,x) := B^\lambda(v)  +x$, for any $x \in \{x_n=0\}$, we define the capillarity Fraenkel asymmetry by
\begin{equation*}
\alpha_\lambda(E) := \inf\left\{\frac{|E \Delta B^\lambda(v,x)|}{v} \st  x \in \partial H\right\}. \end{equation*}
It is readily checked that the Fraenkel asymmetry of $E$ is a minimum. We further define the capillarity isoperimetric deficit by
\begin{equation*}
D_\lambda(E) := \frac{P_\lambda(E) - P_\lambda(B^\lambda(v))}{P_\lambda(B^\lambda(v))}. \end{equation*}
\end{definition}


We recall here the quantitative isoperimetric inequality for the Fraenkel asymmetry in capillarity problems.

\begin{theorem}[{\cite{PascalePozzettaQuantitative, KreutzSchmidt24}}]\label{thm:PPquantitativaFraenkelCapillare}
There exists $C_{\ref{thm:PPquantitativaFraenkelCapillare}} = C_{\ref{thm:PPquantitativaFraenkelCapillare}}(n,\lambda)>0$ such that for any set of finite perimeter $E \subset H$ with $|E|<+\infty$ there holds
\begin{equation}\label{eq:PPquantitativaFraenkelCapillare}
\alpha_\lambda^2(E) \le C_{\ref{thm:PPquantitativaFraenkelCapillare}} D_\lambda
(E).
\end{equation}
\end{theorem}


\begin{definition}\label{def:DistanzaC1}
Denote $\S^{n-1}_+:=\partial B_1 \cap \{x_n\ge 0\}$.
We denote by $w_\lambda : \S^{n-1}_+\to \R$ the function such that
\[
 \overline{\partial B^\lambda \cap H^+}= \{ w_\lambda(x) \, x \st x \in \S^{n-1}_+\}.
\]
Let $k \in \N$ with $k\ge 1$, $\beta \in (0,1)$.
Let $E \subset H$ be a bounded open set. We say that the boundary of $E$ is a $C^{k,\beta}$-graph over $\S^{n-1}_+$ (or, more precisely, that $\overline{\partial E\cap H^+}$ is a $C^{k,\beta}$-graph over $\S^{n-1}_+$) if $\partial E$ is Lipschitz and if there exists a $C^{k,\beta}$-function $f:\S^{n-1}_+\to (0,+\infty)$ such that
\[
 \overline{\partial E\cap H^+}= \{ f(x) \, x \st x \in \S^{n-1}_+\}.
\]
If the boundaries of two sets $E,F$ are $C^{k,\beta}$-graphs over $\S^{n-1}_+$ with respect to some functions $f,g$, we define
\[
\d_{C^{k,\beta}}(E,F):=\|f-g\|_{C^{k,\beta}(\S^{n-1}_+)}.
\]
If $\{E_i\}_{i \in \N}, E$ have boundary given by $C^{k,\beta}$-graphs over $\S^{n-1}_+$, we say that $\overline{\partial E_i \cap H^+}$ converges $\overline{\partial E \cap H^+}$ in $C^{k,\beta}$ (or, simply, that $E_i$ converges to a $E$ in $C^{k,\beta}$) if $\d_{C^{k,\beta}}(E_i,E)\to 0$ as $i\to\infty$.
\end{definition}

\begin{definition}[Capillarity oscillation asymmetry]\label{def:capillarity-oscillation}
    Let $E \subset H$ be a Borel set with measure $|E|=|B^\lambda|$. We define the capillarity oscillation asymmetry by
\[
    \mu_\lambda^2(E) \coloneqq \inf\left\{ \frac{1}{2} \int_{\partial^* E \cap H^+} \left| \nu_E(x) - \frac{x-(x',-\lambda)}{|x-(x',-\lambda)|} \right|^2 \de \hausdorff^{n-1} (x) \st x' \in\partial H
\right\}.
\]
For a generic Borel set $E \subset H$ with finite perimeter and finite measure, setting $r_E:=(|E|/|B^\lambda|)^{\frac1n}$, we define
\[
    \mu_\lambda^2(E) \coloneqq \mu_\lambda^2\left( r_E^{-1} E \right) = \inf\left\{
    \frac{1}{2 r_E^{n-1}} \int_{\partial^* E \cap H^+} \left| \nu_E(x) - \frac{x-r_E(x',-\lambda)}{|x-r_E(x',-\lambda)|} \right|^2 \de \hausdorff^{n-1} (x) \st x' \in\partial H
\right\}.
\]
For technical reasons, it will be convenient to also consider an oscillation asymmetry that is not translation or scaling invariant. For any Borel set $E\subset H$ with finite measure and finite perimeter, we define
\[
    \mu_{\lambda,0}^2(E) = \frac{1}{2}\int_{\partial^* E\cap H^+}\left|\nu_E(x)-\frac{x+\lambda e_n}{|x+\lambda e_n|}\right|^2\de \hausdorff^{n-1}(x).
\]
\end{definition}


\begin{lemma}\label{lem:RiscritturaDiMuLambdaZero}
Let $E\subset H$ be a set of finite perimeter with finite volume. Then
\[
 \mu_{\lambda,0}^2(E) = \int_{\partial^*E \cap H^+} 1 - \left\langle \nu_E , \frac{\lambda e_n}{|x- \Braket{x,e_n}e_n +\lambda e_n|} \right\rangle\de\hausdorff^{n-1}_x
 - \int_E \frac{n-1}{|x+\lambda e_n|}\de x.
\]
\end{lemma}

\begin{proof}
The claim directly follows form the divergence theorem since
\[
\begin{split}
\mu_{\lambda,0}^2(E) 
& = \int_{\partial^*E \cap H^+} 1 - \left\langle\nu_E , \frac{x+ \lambda e_n}{|x+\lambda e_n |}\right\rangle 
\\&=
P(E,H^+) - 
\int_E {\rm div} \left( \frac{x+ \lambda e_n}{|x+\lambda e_n |}\right) 
+ \int_{\partial^*E \cap \partial H} \left\langle - e_n, \frac{x+ \lambda e_n}{|x+\lambda e_n |}\right\rangle \\
&=
P(E,H^+) - 
\int_E \frac{n-1}{|x+\lambda e_n|}
+ \int_{\partial^*E \cap \partial H} \left\langle - e_n, \frac{x+ \lambda e_n}{|x+\lambda e_n |}\right\rangle,
\end{split}
\]
and
\[
\begin{split}
    \int_{\partial^*E \cap \partial H} \left\langle - e_n, \frac{x+ \lambda e_n}{|x+\lambda e_n |}\right\rangle
    &= \int_{\partial^*E \cap \partial H} \left\langle
    -e_n, \frac{\lambda e_n}{|x -\Braket{x,e_n}e_n +\lambda e_n|}
    \right\rangle 
    \\
    &= 
    \int_E {\rm div}\left(  \frac{\lambda e_n}{|x - \Braket{x,e_n}e_n +\lambda e_n|}\right)
    - \int_{\partial^* E \cap H^+} \left\langle
    \nu_E,   \frac{\lambda e_n}{|x - \Braket{x,e_n}e_n +\lambda e_n|}
    \right\rangle,
\end{split}
\]
and ${\rm div}\left(  \frac{\lambda e_n}{|x - \Braket{x,e_n}e_n +\lambda e_n|}\right)=0$.
\end{proof}

