\subsection{Fuglede-type computations for the capillarity problem}\label{subsec:fuglede-capillarity}
The following three technical results, namely \cref{lem:OScillationBoundedByH1Norm}, \cref{prop:EspansionePlambda} and \cref{prop:FugledeCapillarity}, proceed along the lines of \cite[Section 4]{Neumayer16}. However, an additional complication here is that we need to parametrize the boundaries of both $B^{\lambda}$ and a of generic competitor as graphs over $\S^{n-1}_+$. Hence, both of the parametrizing graphs are non-constant, leading to a more involved computation. Moreover, in \cref{prop:FugledeCapillarity} we will derive a Fuglede-type inequality for the capillarity perimeter keeping track of a possible barycentric displacement.

\begin{lemma}\label{lem:OScillationBoundedByH1Norm}
There exist $\eps_{\ref{lem:OScillationBoundedByH1Norm}}, C_{\ref{lem:OScillationBoundedByH1Norm}}>0$ depending on $n,\lambda$ such that the following bounds hold.\\
Let $E \subset H$ be an open set such that $\overline{\partial E \cap H^+} = \{ (w_\lambda(x) + u(x))x \st x \in \S^{n-1}_+\}$ for some $C^1$ function $ u : \S^{n-1}_+ \to \R$ with $\|u\|_{C^1(\S^{n-1}_+)}\le \eps_{\ref{lem:OScillationBoundedByH1Norm}}$. Then
\[
\mu_{\lambda,0}^2(E)\leq C_{\ref{lem:OScillationBoundedByH1Norm}} \| u \|^2_{H^1(\S^{n-1}_+)} .
\]
In particular, if also $|E|=|B^\lambda|$, then 
\[
\mu_\lambda^2(E) \le \mu_{\lambda,0}^2(E)\leq C_{\ref{lem:OScillationBoundedByH1Norm}} \| u \|^2_{H^1(\S^{n-1}_+)} .
\]
\end{lemma}

\begin{proof}
We take $\eps_{\ref{lem:OScillationBoundedByH1Norm}}\in(0,1)$ sufficiently small so that $|w_\lambda + u| \ge c=c(n,\lambda)>0$ on $\S^{n-1}_+$.
We will exploit identities from \cref{lemma:formulas}.
We can rewrite
\begin{equation}\label{eq:zzz0}
\begin{split}
     &\mu_{\lambda,0}^2(E)
     = \frac12 \int_{\partial E \cap H^+} 
     \left| \nu_E(y) - \frac{y+\lambda e_n}{|y+\lambda e_n|} \right|^2 \de \hausdorff^{n-1}(y) \\
     &= \frac12 \int_{\S^{n-1}_+} 
     \left| \nu_E((w_\lambda+u)x) - \frac{(w_\lambda+u)x+\lambda e_n}{|(w_\lambda+u)x+\lambda e_n|} \right|^2
     (w_\lambda+u)^{n-2}[ (w_\lambda+u)^2 + |\nabla w_\lambda+ \nabla u|^2]^{\frac12} \de \hausdorff^{n-1}(x) \\
     &\le C \int_{\S^{n-1}_+} 
     \left| \nu_E((w_\lambda+u)x) - \frac{(w_\lambda+u)x+\lambda e_n}{|(w_\lambda+u)x+\lambda e_n|} \right|^2 \de \hausdorff^{n-1}(x).
\end{split}
\end{equation}
Moreover
\begin{equation}\label{eq:Normali}
    \begin{split}
        \nu_E((w_\lambda+u)x) = \frac{(w_\lambda+u)x - \nabla w_\lambda - \nabla u}{[(w_\lambda+u)^2 + |\nabla w_\lambda + \nabla u|^2]^{\frac12}},\\
        \nu_{B^\lambda}(w_\lambda x) = w_\lambda x +\lambda e_n = \frac{w_\lambda x - \nabla w_\lambda}{[w_\lambda^2+ |\nabla w_\lambda|^2]^{\frac12}},
    \end{split}
\end{equation}
for any $x \in \S^{n-1} \cap H^+$. Hence, for $x \in \S^{n-1} \cap H^+$, we have
\begin{equation}\label{eq:zzz1}
    \begin{split}
        \nu_E((w_\lambda+u)x) &- \frac{(w_\lambda+u)x+\lambda e_n}{|(w_\lambda+u)x+\lambda e_n|} 
        \\&\qquad\qquad=
        \underbrace{
        \frac{(w_\lambda+u)x - \nabla w_\lambda - \nabla u}{[(w_\lambda+u)^2 + |\nabla w_\lambda + \nabla u|^2]^{\frac12}} - \nu_{B^\lambda}(w_\lambda x)}_{A}
        + 
        \underbrace{
        w_\lambda x +\lambda e_n - \frac{(w_\lambda+u)x+\lambda e_n}{| u x + \nu_{B^\lambda}(w_\lambda x)|}}_{B}.
    \end{split}
\end{equation}
We study the summands in \eqref{eq:zzz1} separately. First, since $|w_\lambda + u| \ge c>0$, we have
\begin{equation}\label{eq:zzz2}
    \begin{split}
        |A&| 
        = 
        \left|
        \frac{w_\lambda x - \nabla w_\lambda }{[(w_\lambda+u)^2 + |\nabla w_\lambda + \nabla u|^2]^{\frac12}} - \nu_{B^\lambda}(w_\lambda x)
        +
        \frac{u x - \nabla u}{[(w_\lambda+u)^2 + |\nabla w_\lambda + \nabla u|^2]^{\frac12}} \right| \\
        &\overset{\eqref{eq:Normali}}{\le}
        |w_\lambda x - \nabla w_\lambda| \left( \frac{1}{[(w_\lambda+u)^2 + |\nabla w_\lambda + \nabla u|^2]^{\frac12}}
        -
        \frac{1}{[w_\lambda^2 + |\nabla w_\lambda|^2]^{\frac12}} 
        \right) + O(|u| + |\nabla u|) 
        \\
        &= \frac{|w_\lambda x - \nabla w_\lambda|}{[(w_\lambda+u)^2 + |\nabla w_\lambda + \nabla u|^2]^{\frac12}[w_\lambda^2 + |\nabla w_\lambda|^2]^{\frac12}} 
        \left( 
        [w_\lambda^2 + |\nabla w_\lambda|^2]^{\frac12}
        -
        [(w_\lambda+u)^2 + |\nabla w_\lambda + \nabla u|^2]^{\frac12}
        \right) \\
        &\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad\qquad
        + O(|u| + |\nabla u|) 
        %
        \\
        &=\frac{|w_\lambda x - \nabla w_\lambda|}{[(w_\lambda+u)^2 + |\nabla w_\lambda + \nabla u|^2]^{\frac12}[w_\lambda^2 + |\nabla w_\lambda|^2]^{\frac12}} 
        \left( 
        -\frac{2uw_{\lambda}+u^2+|\grad u|^2+2\grad u\cdot\grad w_{\lambda}}{2[w_{\lambda}^2+|\grad w_{\lambda}|^2]^{1/2}}+O(|u|+|\grad u|)
        \right)\\
    & = O(|u|+|\grad u|)
    \end{split}
\end{equation}
where $O(\cdot)$ may change from line to line.


Moreover
\begin{equation}\label{eq:zzz3}
    \begin{split}
        |B|
        &= \left| w_\lambda x +\lambda e_n - \frac{(w_\lambda+u)x+\lambda e_n}{[1+ u^2 + 2u \Braket{\nu_{B^\lambda}, x}]^{\frac12}} \right|
        %
        = \left|  w_\lambda x +\lambda e_n - \frac{(w_\lambda+u)x+\lambda e_n}{1 + u \Braket{\nu_{B^\lambda}, x} + \tfrac12 u^2 + O(|u|)} \right|
        \\
        &= \left| w_\lambda x +\lambda e_n - (w_\lambda x+u x+\lambda e_n) \left( 1 - u \Braket{\nu_{B^\lambda}, x} - \frac12 u^2 + O(|u|) \right) \right| =O(|u|).
    \end{split}
\end{equation}
Inserting \eqref{eq:zzz1}, \eqref{eq:zzz2}, \eqref{eq:zzz3} into \eqref{eq:zzz0} we find
\begin{equation*}
    \begin{split}
    \mu_{\lambda,0}^2(E)
    &\le C \int_{\S^{n-1}_+} 
     \left|A + B\right|^2 \de \hausdorff^{n-1}(x) 
     \le C \int_{\S^{n-1}_+} |A|^2 + |B|^2 \le C \| u \|^2_{H^1(\S^{n-1}_+)}.
    \end{split}
\end{equation*}
\end{proof}

