\begin{proposition}\label{prop:EspansionePlambda}
There exist $c_{\ref{prop:EspansionePlambda}}, C_{\ref{prop:EspansionePlambda}}, \epsilon_{\ref{prop:EspansionePlambda}}>0$ depending on $n,\lambda$ such that the following holds.
Let $E \subset H$ be an open bounded set with measure $|E|=|B^\lambda|$. Suppose that the boundary of $E$ is a $C^1$-graph over $\S^{n-1}_+$, see \cref{def:DistanzaC1}, with respect to a function $f= w_\lambda + u$, with $\|u \|_{C^1(\S^{n-1}_+)} \le\epsilon\le \epsilon_{\ref{prop:EspansionePlambda}}$. Then
\begin{equation*}
    P_\lambda(E) = P_\lambda(B^\lambda) + B(u) + \epsilon \, O \left( \|u \|^2_{H^1(\S^{n-1}_+)} \right),
\end{equation*}
where $B(u)$ satisfies
\[
B(u) \ge c_{\ref{prop:EspansionePlambda}} \int_{\S^{n-1}_+} |\grad u|^2 - C_{\ref{prop:EspansionePlambda}} \int_{\S^{n-1}_+} u^2.
\]
\end{proposition}

\begin{proof}
Recalling \cref{rem:PlambdaConDivergenza}, letting $\phi(v) := |v|-\lambda\Braket{v,e_n}$ for any $v \in \R^n$, there holds
    \[
        P_{\lambda}(E) = \int_{\partial^* E\cap H^+}\phi(\nu_E) \de \hausdorff^{n-1}.
    \]
We compute
    \[
        \grad\phi(v) = \frac{v}{|v|}-\lambda e_n,\qquad \grad^2 \phi(v) = \frac{1}{|v|}\left(\Id - \frac{v}{|v|}\otimes\frac{v}{|v|}\right).
    \]
    By \cref{lemma:formulas}, the outer unit normals to $E$ and $B^\lambda$ are given by
    \begin{equation}\label{eq:normal-to-graph}
        \nu_E(f(x)\,x)=\frac{f(x)\,x-\grad f(x)}{\sqrt{f(x)^2+|\grad f(x)|^2}} ,
        \qquad
        \nu_{B^\lambda}( w_\lambda(x) \, x ) =
        \frac{w_\lambda(x)\,x-\grad w_\lambda(x)}{\sqrt{w_\lambda(x)^2+|\grad w_\lambda(x)|^2}} ,
    \end{equation}
for any $x\in \S^{n-1}_+ \cap H^+$.
% To prove the formula above, it is sufficient to take an orthonormal basis $\{\tau_1,\ldots,\tau_{n-1}\}$ of $T_x\S^{n-1}_+$, so that $\{\partial_{\tau_1}(f(x)x),\ldots,\partial_{\tau_{n-1}}(f(x)x)\}$ is a basis of $T_{f(x)x}E$, and thus we just need to check that $\nu_E$ is orthogonal to them. Indeed, it is simple to obtain this:
%     \[
%         \Braket{f(x)x-\grad f(x),f(x)\tau_i+\partial_{\tau_i}f(x) x}=-f(x)\partial_{\tau_i}f(x)+f(x)\partial_{\tau_i}f(x)=0.
%     \]

To simplify the computations, in this proof we will adopt Einstein's sum convention (i.e., summation is understood over the repeated indexes). We will denote by $\{\tau_1,\ldots,\tau_{n-1}\}$ an orthonormal basis of $T_x\S^{n-1}_+$, for generic $x \in \S^{n-1}_+$, and we will denote by $\partial_i:= \partial_{\tau_i}$ the tangential derivative along $\S^{n-1}_+$ in direction $\tau_i$.

We consider the basis $\{g_i^B\}_{i=1}^{n-1}$ for the tangent space $T_{w_{\lambda}(x)x}B^{\lambda}$ given by
    \[
        g_i^B = \partial_i(w_{\lambda}\, x)=w_{\lambda}\tau_i+\partial_iw_{\lambda} \, x,
        % \qquad 
        % g_i=\partial_i((w_{\lambda}+u ) \, x) = g_i^B+u\, \tau_i+\partial_iu \, x,
    \]
for $x \in \S^{n-1}_+$. 

%{\color{red}
%We use the bases $\{g_i^B\}_{i=1}^{n-1}$ and $\{g_i\}_{i=1}^{n-1}$ for the tangent spaces $T_{w_{\lambda}(x)x}B^{\lambda}$ and $T_{f(x)x}E$ respectively given by
%    \[
%        g_i^B = \partial_i(w_{\lambda}\, x)=w_{\lambda}\tau_i+\partial_iw_{\lambda} \, x,
%        \qquad 
%        g_i=\partial_i((w_{\lambda}+u ) \, x) = g_i^B+u\, \tau_i+\partial_iu \, x,
%    \]
%for $x \in \S^{n-1}_+$. }

Define the vectors
\[
\omega^B(x)  = w_{\lambda}^{n-1}x-w_{\lambda}^{n-2}\partial_i w_{\lambda}\tau_i,
\qquad
\omega(x)  = (w_{\lambda}+u)^{n-1}x-(w_{\lambda}+u)^{n-2}\partial_i (w_{\lambda}+u)\tau_i,
\]
for $x \in \S^{n-1}_+$. Notice that $\Braket{\omega^B, g_j^B}= w_\lambda^{n-2} \Braket{w_\lambda x - \partial_i w_\lambda \tau_i, w_\lambda \tau_j + \partial_j w_\lambda x} = w_\lambda^{n-2} ( w_\lambda \partial_j w_\lambda - w_\lambda \partial_j w_\lambda) =0$ for any $x \in \S^{n-1}_+$, hence we can write $\nu_{B^\lambda}( w_\lambda \, x) = \omega^B/|\omega^B|$.

By 1-homogeneity of $\varphi$ and by \cref{lemma:formulas} we have
\[
\begin{split}
 P_{\lambda}(B^{\lambda}) &= \int_{\partial B^{\lambda}\cap H^+} \phi(\nu_{B^{\lambda}}) = \int_{\S_+^{n-1}}\phi\left( \nu_{B^\lambda}(w_\lambda(x) \, x)\right) w_\lambda^{n-2} \sqrt{w_\lambda^2 + |\nabla w_\lambda|^2}  
 \de\hausdorff^{n-1}(x)
 \\ &
 = \int_{\S_+^{n-1}}\phi( w_\lambda \, x - \partial_i w_\lambda \, \tau_i ) w_\lambda^{n-2} \de \hausdorff^{n-1}(x) =
 \int_{\S_+^{n-1}}\phi(\omega^B),
\end{split}
\]
where we used that $\sqrt{w_\lambda^2 + |\nabla w_\lambda|^2}  \nu_{B^\lambda}(w_\lambda(x) \, x) = w_\lambda \, x - \nabla w_\lambda  = w_\lambda \, x - \partial_i w_\lambda \, \tau_i $.


%{\color{red}
%The notation of differential forms is convenient in this case, as we see that $\nu_{B^{\lambda}}=\frac{\omega^B}{|\omega^B|}$ and $\nu_{E}=\frac{\omega}{|\omega|}$, where
%    \[
    % \begin{split}
    %     \omega^B &= g_1^B\wedge \ldots \wedge g_{n-1}^B = w_{\lambda}^{n-1}x-\sum_{i=1}^{n-1}w_{\lambda}^{n-2}\partial_i w_{\lambda}\tau_i,\\
    %     \omega &= g_1\wedge\ldots\wedge g_{n-1} = (w_{\lambda}+u)^{n-1}x-\sum_{i=1}^{n-1}(w_{\lambda}+u)^{n-2}\partial_i (w_{\lambda}+u)\tau_i.
    % \end{split}
 %   \begin{split}
  %      \omega^B &= g_1^B\wedge \ldots \wedge g_{n-1}^B = w_{\lambda}^{n-1}x-w_{\lambda}^{n-2}\partial_i w_{\lambda}\tau_i,\\
   %     \omega &= g_1\wedge\ldots\wedge g_{n-1} = (w_{\lambda}+u)^{n-1}x-(w_{\lambda}+u)^{n-2}\partial_i (w_{\lambda}+u)\tau_i.
    %\end{split}
    %\]
    %They appear when we write the capillarity perimeter as an integral on $\S^{n-1}_+$:
    %\[
     %   P_{\lambda}(B^{\lambda}) = \int_{\partial B^{\lambda}\cap H^+} \phi(\nu_{B^{\lambda}})\de \hausdorff^{n-1} = \int_{\S_+^{n-1}}\phi\left(\frac{\omega^B}{|\omega^B|}\right)|\omega^B|\de\hausdorff^{n-1} = \int_{\S_+^{n-1}}\phi(\omega^B)\de\hausdorff^{n-1}.
    %\]
%}
Analogously one gets
    \begin{equation}\label{eq:expansion-perimeter}
    \begin{split}
        P_{\lambda}(E) &= \int_{\S_+^{n-1}}\phi(\omega)\de\hausdorff^{n-1}\\
        &= \int_{\S_+^{n-1}}\phi(\omega^B) + \Braket{\grad\phi(\omega^B),\omega-\omega^B} + \frac12\Braket{\grad^2\phi(\omega^B)(\omega-\omega^B),(\omega-\omega^B)}+O(|\omega-\omega^B|^3)\de\hausdorff^{n-1}.
    \end{split}
    \end{equation}
A direct computation gives
    \begin{equation}\label{eq:ExpansionOmegaOmegaB}
    \begin{split}
        % \omega &= \omega^B + w_{\lambda}^{n-2}\left[(n-1)ux-\sum_{i=1}^{n-1}\left((n-2)w_{\lambda}^{-1}\partial_iw_{\lambda}u+\partial_i u\right)\tau_i\right]\\
        % &\quad+\frac{(n-1)(n-2)}{2}w_{\lambda}^{n-3}u^2x-\sum_{i=1}^{n-1}\left(\frac{(n-2)(n-3)}{2}w_{\lambda}^{n-4}\partial_iw_{\lambda}u^2+(n-2)w_{\lambda}^{n-3}u\partial_iu\right)\tau_i\\
        % &\quad +\epsilon O\left(u^2+|\grad u|^2\right).
        \omega &= \omega^B + w_{\lambda}^{n-2}\left[(n-1)ux-\left((n-2)w_{\lambda}^{-1}\partial_iw_{\lambda}u+\partial_i u\right)\tau_i\right]\\
        &\quad+\frac{(n-1)(n-2)}{2}w_{\lambda}^{n-3}u^2x-\left(\frac{(n-2)(n-3)}{2}w_{\lambda}^{n-4}\partial_iw_{\lambda}u^2+(n-2)w_{\lambda}^{n-3}u\partial_iu\right)\tau_i\\
        &\quad +\epsilon O\left(u^2+|\grad u|^2\right).
    \end{split}
    \end{equation}
    It is straightforward to see that $\nu_{B^{\lambda}}(w_{\lambda} \, x)=w_{\lambda}\, x+\lambda e_n$ for every $x\in \S^{n-1}_+$. 
    Moreover we observed above that $\nu_{B^\lambda}( w_\lambda \, x) = \omega^B/|\omega^B|$. 
    Hence
    \[
    \begin{split}
        \grad \phi(\omega^B)&=\frac{\omega^B}{|\omega^B|}-\lambda e_n=\nu_{B^{\lambda}}(w_{\lambda}\, x)-\lambda e_n=w_{\lambda}\, x,\\
        \grad^2\phi(\omega^B) &=\frac{1}{|\omega^B|}\left(\Id - \nu_{B^{\lambda}}(w_{\lambda}\,x)\otimes \nu_{B^{\lambda}}(w_{\lambda}\, x)\right),
    \end{split}
    \]
    for $x \in \S^{n-1}_+$.
    So the gradient term in the expansion for $P_{\lambda}(E)$ in~\eqref{eq:expansion-perimeter} becomes
    \begin{equation}\label{eq:zzExpansionGradient}
        \Braket{\grad\phi(\omega^B),\omega-\omega^B}=\Braket{w_{\lambda}\,x,\omega-\omega^B} \overset{\eqref{eq:ExpansionOmegaOmegaB}}{=} (n-1)w_{\lambda}^{n-1}u+\frac{(n-1)(n-2)}{2}w_{\lambda}^{n-2}u^2+\epsilon O\left(u^2+|\grad u|^2\right).
    \end{equation}
    To expand the Hessian term in \eqref{eq:expansion-perimeter} it is sufficient to consider the first order expansion of $\omega-\omega^B$, and we single out a multiple of $\nu_{B^{\lambda}}$ since it belongs to the kernel of $\grad^2 \phi(\omega^{B})$. We have that
    \[
    \begin{split}
        % \omega-\omega^B&=w_{\lambda}^{n-2}\left[(n-1)ux-\sum_{i=1}^{n-1}((n-2)w_{\lambda}^{-1}\partial_iw_{\lambda} u+\partial_i u)\tau_i\right]\\
        % &=w_{\lambda}^{n-2}\left[(n-1)ux-\grad u-(n-2)u\left(\frac{\grad w_{\lambda}}{w_{\lambda}}-x\right)-(n-2)ux\right]\\
        % &=w_{\lambda}^{n-2}\left[ux-\grad u+(n-2)u\left(1+\frac{|\grad w_{\lambda}|^2}{w_{\lambda}^2}\right)\nu_{B^{\lambda}}\right],
        \omega-\omega^B&=w_{\lambda}^{n-2}\left[(n-1)ux-((n-2)w_{\lambda}^{-1}\partial_iw_{\lambda} u+\partial_i u)\tau_i\right] + O(u^2+|\grad u|^2)\\
        &=w_{\lambda}^{n-2}\left[(n-1)ux-\grad u-(n-2)u\left(\frac{\grad w_{\lambda}}{w_{\lambda}}-x\right)-(n-2)ux\right] + O(u^2+|\grad u|^2)\\
        & \overset{\eqref{eq:normal-to-graph}}{=}
        w_{\lambda}^{n-2}\left[ux-\grad u+(n-2)u\left(1+\frac{|\grad w_{\lambda}|^2}{w_{\lambda}^2}\right)^{1/2}\nu_{B^{\lambda}}\right] + O(u^2+|\grad u|^2),
    \end{split}
    \]
Exploiting \eqref{eq:normal-to-graph} once more, we compute the value of $\grad^2 \phi(\nu_{B^{\lambda}}) = \Id-\nu_{B^{\lambda}}\otimes\nu_{B^{\lambda}}$ on the orthonormal basis $\{x,\tau_1,\ldots,\tau_{n-1}\}$ of $\R^n$:
    \[
    \begin{split}
        \Braket{(\Id-\nu_{B^{\lambda}}\otimes \nu_{B^{\lambda}})x,x} &= 1-\frac{w_{\lambda}^2}{w_{\lambda}^2+|\grad w_{\lambda}|^2} = \frac{|\grad w_{\lambda}|^2}{w_{\lambda}^2+|\grad w_{\lambda}|^2},\\
        \Braket{(\Id-\nu_{B^{\lambda}}\otimes \nu_{B^{\lambda}})\tau_i,\tau_j} &= \delta_{ij}-\frac{\partial_iw_{\lambda}\partial_jw_{\lambda}}{w_{\lambda}^2+|\grad w_{\lambda}|^2},\\
        \Braket{(\Id-\nu_{B^{\lambda}}\otimes \nu_{B^{\lambda}})x,\tau_i} &= \frac{w_{\lambda}\partial_iw_{\lambda}}{w_{\lambda}^2+|\grad w_{\lambda}|^2}.
    \end{split}
    \]
    Since $\nu_{B^\lambda}\in \ker \grad^2 \phi(\omega^B)$, we deduce that
    \begin{equation}\label{eq:zzExpansionHessian}
    \begin{split}
        &\Braket{\grad^2\phi(\omega^B)(\omega-\omega^B),\omega-\omega^B}=
        \frac{w_{\lambda}^{2n-4}}{|\omega^B|}
        \Braket{(\Id-\nu_{B^{\lambda}}\otimes\nu_{B^{\lambda}})(ux-\grad u),ux-\grad u} +\epsilon O\left(u^2+|\grad u|^2\right)
        \\
        &\quad=
        \frac{w_{\lambda}^{2n-4}}{|\omega^B|} \left[\frac{|\grad w_{\lambda}|^2}{w_{\lambda}^2+|\grad w_{\lambda}|^2} u^2-2\frac{w_{\lambda}\partial_iw_{\lambda}}{w_{\lambda}^2+|\grad w_{\lambda}|^2}u\partial_i u + |\grad u|^2-\frac{\partial_iw_{\lambda}\partial_jw_{\lambda}}{w_{\lambda}^2+|\grad w_{\lambda}|^2}\partial_i u\partial_j u\right]+\epsilon O\left(u^2+|\grad u|^2\right).
    \end{split}
    \end{equation}

    %{\color{red}
    %\[
    %\begin{split}
        %&\Braket{\grad^2\phi(\omega^B)(\omega-\omega^B),\omega-\omega^B}=w_{\lambda}^{2n-5}\Braket{(\Id-\nu_{B^{\lambda}}\otimes\nu_{B^{\lambda}})(ux-\grad u),ux-\grad u}\\
        %&\qquad=w_{\lambda}^{2n-5} \left[\frac{|\grad w_{\lambda}|^2}{w_{\lambda}^2+|\grad w_{\lambda}|^2} u^2-2\frac{w_{\lambda}\partial_iw_{\lambda}}{w_{\lambda}^2+|\grad w_{\lambda}|^2}u\partial_i u + |\grad u|^2-\frac{\partial_iw_{\lambda}\partial_jw_{\lambda}}{w_{\lambda}^2+|\grad w_{\lambda}|^2}\partial_i u\partial_j u\right]+\epsilon O\left(u^2+|\grad u|^2\right).
    %\end{split}
    %\]
    %}
Plugging \eqref{eq:zzExpansionGradient} and \eqref{eq:zzExpansionHessian} into \eqref{eq:expansion-perimeter}, we find
\begin{equation}\label{eq:zzExpansion1}
    \begin{split}
        P_{\lambda}(E)-P_{\lambda}(B^{\lambda}) &= \int_{\S^{n-1}_+} (n-1)w_{\lambda}^{n-1}u+\frac{(n-1)(n-2)}{2}w_{\lambda}^{n-2}u^2\\
        &\qquad\qquad
        +\frac{1}{2}
        \frac{w_{\lambda}^{2n-4}}{|\omega^B|}
         \,\,
        \left[\frac{|\grad w_{\lambda}|^2}{w_{\lambda}^2+|\grad w_{\lambda}|^2} u^2-2\frac{\Braket{w_{\lambda}\grad w_{\lambda},u\grad u}}{w_{\lambda}^2+|\grad w_{\lambda}|^2} + |\grad u|^2 - \frac{\Braket{\grad w_{\lambda},\grad u}^2}{w_{\lambda}^2+|\grad w_{\lambda}|^2}\right]\\
        &\qquad\qquad +\epsilon O\left(u^2+|\grad u|^2\right).
    \end{split}
\end{equation}
We can turn the first order term in the previous expansion into a second order term by exploiting the volume constraint. Indeed, by \cref{lemma:formulas} and by assumptions we get
\begin{equation}\label{eq:zzExpansion2}
    \int_{\S^{n-1}_+} \frac1n w_\lambda^n = |B^\lambda| = |E| = \int_{\S^{n-1}_+} \frac1n (w_\lambda + u)^n
    = \int_{\S^{n-1}_+} \frac1n w_\lambda^n + w_\lambda^{n-1} u + \frac{n-1}{2}w_\lambda^{n-2} u^2 + O(u^3).
\end{equation}
Moreover, since $\min w_\lambda>0$, then there is $c=c(n,\lambda)\in(0,1)$ such that $|\grad w_{\lambda}|^2 /(w_{\lambda}^2+|\grad w_{\lambda}|^2) \le c$, and thus
\begin{equation}\label{eq:zzExpansion3}
        |\grad u|^2-\frac{\Braket{\grad w_{\lambda},\grad u}^2}{w_{\lambda}^2+|\grad w_{\lambda}|^2}\geq (1-c^2)|\grad u|^2.
\end{equation}
On the other hand, by applying the standard inequality $ab\leq \frac{\delta a^2}{2}+\frac{b^2}{2\delta}$ with $a=|\nabla w_\lambda| \,|\grad u|$ and $b= w_\lambda\,|u|$ and $\delta= \delta(n,\lambda)>0$ small enough, we see that
\begin{equation}\label{eq:zzExpansion4}
        \left|2\frac{\Braket{w_{\lambda}\grad w_{\lambda},u\grad u}}{w_{\lambda}^2+|\grad w_{\lambda}|^2}\right|
        \le \frac{2}{w_{\lambda}^2+|\grad w_{\lambda}|^2} \left( \frac\delta2 |\nabla w_\lambda|^2 |\grad u|^2 + \frac{w_\lambda^2 u^2}{2 \delta}\right) 
        \leq \frac{1-c^2}{2}|\grad u|^2 + Cu^2,
\end{equation}
where $C>0$ depends only on $n, \lambda$. Applying \eqref{eq:zzExpansion2}, \eqref{eq:zzExpansion3}, \eqref{eq:zzExpansion4} in \eqref{eq:zzExpansion1}, the statement follows with
\[
    \begin{split}
        B(u)=\int_{\S^{n-1}_+}
        \frac{1-n}{2} w_\lambda^{n-2} u^2
        + 
        \frac{1}{2}
         \frac{w_{\lambda}^{2n-4}}{|\omega^B|}
         \,\,
        \Bigg\{|\grad u|^2- \frac{\Braket{\grad w_{\lambda},\grad u}^2}{w_{\lambda}^2+|\grad w_{\lambda}|^2} &- 2\frac{\Braket{w_{\lambda}\grad w_{\lambda},u\grad u}}{w_{\lambda}^2+|\grad w_{\lambda}|^2}\\
        &\quad+\frac{|\grad w_{\lambda}|^2}{w_{\lambda}^2+|\grad w_{\lambda}|^2}  u^2\Bigg\}\de\hausdorff^{n-1}.
    \end{split}
    \]
\end{proof}


\begin{proposition}[Fuglede-type estimate for capillarity problems]\label{prop:FugledeCapillarity}
There exist $C_{\ref{prop:FugledeCapillarity}}, \epsilon_{\ref{prop:FugledeCapillarity}}>0$ depending on $n,\lambda$ such that the following holds.
Let $E \subset H$ be an open bounded set with measure $|E|=|B^\lambda|$. Suppose that the boundary of $E$ is a $C^1$-graph over $\S^{n-1}_+$, see \cref{def:DistanzaC1}, with respect to a function $f= w_\lambda + u$, with $\|u \|_{C^1(\S^{n-1}_+)} \le\epsilon\le \epsilon_{\ref{prop:FugledeCapillarity}}$. Then, denoting $\barycenter_H E := \frac{1}{|E|}\int_E (x-\Braket{x,e_n}e_n)\de x$, there holds
\begin{equation*}
    \| u \|^2_{H^1(\S^{n-1}_+)} \le C_{\ref{prop:FugledeCapillarity}} (D_\lambda(E)+|\barycenter_H E|^2).
\end{equation*}
\end{proposition}

\begin{proof}
    The proof is inspired by \cite[Proposition~1.9]{Neumayer16}. To simplify the notation, let $b=\barycenter_H E\in\partial H$. We first claim that there exists a constant $C>0$, depending on $n,\lambda$, such that if $\epsilon_{\ref{prop:FugledeCapillarity}}$ is small enough then
    \begin{equation}\label{eq:L1-IsoperimetricDeficit}
        \|u\|_{L^1(\S^{n-1}_+)}^2\leq C (D_{\lambda}(E)+|b|^2).
    \end{equation}
    To prove this, we start by showing that $|E\symmdiff B^{\lambda}|\leq C (D_{\lambda}(E)^{1/2}+|b|)$. The quantitative inequality from \cref{thm:PPquantitativaFraenkelCapillare} guarantees that there exists a point $z\in\partial H$ such that $|E\symmdiff (z+B^{\lambda})|\leq C D_{\lambda}(E)^{1/2}$. Applying the triangle inequality and \cite[Lemma~17.9]{MaggiBook} we obtain the estimate
    \begin{equation}\label{eq:asymmetry+translation}
        |E\symmdiff B^{\lambda}| \leq C D_{\lambda}(E)^{1/2}+|B^{\lambda}\symmdiff(z+B^{\lambda})|\leq C D_{\lambda}(E)^{1/2} + 2|z|P(B^{\lambda}),
    \end{equation}
    where $C$ depends on $n,\lambda$ only and may change from line to line.
    By definition of $\barycenter_H E$, writing $x=(x',x_n) \in \R^n$, since $\int_{B^\lambda}x'\de x=0$, we get that
    \begin{equation*}\label{eq:translation-bound}
        \begin{split}
            z-b&= \frac{1}{|B^{\lambda}|}\int_{B^{\lambda}}(z-b)\de x 
            = \frac{1}{|B^{\lambda}|}\int_{B^{\lambda}}(x'+z-b)\de x - \frac{1}{|E|}\int_E (x'-b)\de x\\
        &= \frac{1}{|B^{\lambda}|}\int_{B^{\lambda}+z-b}x'\de x-\frac{1}{|E|}\int_{E-b}x'\de x.
        \end{split}
    \end{equation*}
    We observe that $|z|\leq 2\diam E$, and since that set is bounded by a unversal constant (as soon as $\epsilon_{\ref{prop:FugledeCapillarity}}<1$), then there exists a constant $C$ depending only on $n$ and $\lambda$ such that, for any $x\in B^{\lambda}+z-b$ and any $x\in E$, we have that $|x|\leq C$. Hence, using again \cref{thm:PPquantitativaFraenkelCapillare}, we estimate
    \[
        |z| \leq 
        \frac{1}{|B^\lambda|} \int_{(B^{\lambda}+z-b) \Delta (E-b)} |x'| \de x  + |b|
        \le
        C|E\symmdiff (z+B^{\lambda})|+|b| \leq CD_{\lambda}(E)^{1/2}+|b|.
    \]
    Plugging the latter estimate in~\eqref{eq:asymmetry+translation} we obtain that $|E\symmdiff B^{\lambda}|\leq C(D_{\lambda}(E)^{1/2}+|b|)$. In order to obtain~\eqref{eq:L1-IsoperimetricDeficit}, we may bound $\|u\|_{L^1}$ from above in terms of $|E\symmdiff B^{\lambda}|$. We perform an expansion as in~\eqref{eq:VolumeExpansion} to get
    \[
    \begin{split}
        |E\setminus B^{\lambda}| &= 
        \int_{\S^{n-1}_+} 
        \int_{w_\lambda}^{w_\lambda + u_+} r^{n-1} \de r \de \hausdorff^{n-1}
        =
        \int_{\{u>0\}} \frac{1}{n}(w_\lambda + u)^n - \frac{w_\lambda^n}{n} \de \hausdorff^{n-1}
        \\
        &=
        \int_{\{u>0\}}
        w_{\lambda}^{n-1}u+O(u^2)\de \hausdorff^{n-1} \geq C\int_{\{u>0\}}u\de \hausdorff^{n-1},
    \end{split}
    \]
    where the last estimate follows by choosing $\epsilon_{\ref{prop:FugledeCapillarity}}$ small enough, since $\inf w_\lambda >0$ on $\S^{n-1}_+$.
    An analogous computation shows $|B^{\lambda}\setminus E| \geq C\int_{\{u<0\}}(-u)\de\hausdorff^{n-1}$. Hence $|E\symmdiff B^{\lambda}|\geq C\|u\|_{L^1}$. Combining this with the upper bound for $|E\symmdiff B^{\lambda}|$ obtained before we readily get~\eqref{eq:L1-IsoperimetricDeficit}.

    Taking now $\epsilon_{\ref{prop:FugledeCapillarity}}<\epsilon_{\ref{prop:EspansionePlambda}}$ and applying \cref{prop:EspansionePlambda} we obtain that
    \[
    \begin{split}
        \|u\|_{H^1(\S_+^{n-1})}^2 =\|u\|_{L^2(\S_+^{n-1})}^2+\|\grad u\|_{L^2(\S_+^{n-1})}^2 \leq C\left[D_{\lambda}(E) + \|u\|_{L^2(\S_+^{n-1})}^2\right]+\epsilon O \left( \|u \|^2_{H^1(\S^{n-1}_+)} \right).
    \end{split}
    \]
    Let $\delta>0$ to be chosen. Applying \cref{lemma:NashIneq} with $\Sigma=\S^{n-1}_+$ we get
    \[
    \begin{split}
        \|u\|_{H^1(\S_+^{n-1})}^2&\leq C\left[D_{\lambda}(E)+
        \frac{C_{\ref{lemma:NashIneq}}}{\delta^{\alpha_n}}
        \|u\|_{L^1(\S_+^{n-1})}^2 \right] + (\epsilon+\delta)O \left( \|u \|^2_{H^1(\S^{n-1}_+)} \right)\\
        &\overset{\eqref{eq:L1-IsoperimetricDeficit}}{\leq} C\left( 1 +  \frac{C_{\ref{lemma:NashIneq}}}{\delta^{\alpha_n}}\right)(D_{\lambda}(E)+|b|^2)+(\epsilon+\delta)O \left( \|u \|^2_{H^1(\S^{n-1}_+)} \right).
    \end{split}
    \]
    To conclude the proof, it is sufficient to take $\delta=\epsilon_{\ref{prop:FugledeCapillarity}}$ small enough to absorb the last term on the right hand side in the last inequality.
\end{proof}

\subsection{Proof of the strong quantitative isoperimetric inequality for capillarity problems}\label{sec:proof-capillarity}

We recall the following basic lemma, which readily follows by the isoperimetric inequality \eqref{eq:zzIsoperimetricaCapillare} and by testing the functional with any rescaling of the isoperimetric bubble.

\begin{lemma}\label{lem:ProblemPlambda+LambdaVolumi}
For any $\bar\Lambda>n$, there holds
\begin{equation*}\label{eq:ProblemPlambda+LambdaVolumi}
    \inf\left\{
        P_\lambda(E) + \bar \Lambda \left| |E| - |B^\lambda| \right| \st E \subset H, \,\, |E|<+\infty
    \right\} = P_\lambda(B^\lambda),
\end{equation*}
and the infimum is only achieved by translations $B^\lambda + y$ of the standard bubble $B^\lambda$, for $y \in \partial H$.
\end{lemma}

We now get prepared for our formulation of the selection principle. From now on we let $\psi:\R\to \R$ be the function
\begin{equation}\label{eq:DefPSI}
    \psi(t) := \max\{ -100 , \min\{ t, 100\}\}.
\end{equation}
%an odd bounded smooth Lipschitz function such that $\psi(t)=t$ for $|t|\le 100$, and $\psi(t)\to 0$ as $|t|\to\infty$.
We define
\begin{equation}\label{eq:AlternativeBarycenter}
    \widetilde{b}(F) := \int_F \left( \psi(x_1), \ldots, \psi(x_{n-1}) \right) \de x,
\end{equation}
for any set $F\subset H$ with $|F|<+\infty$. 
Observe that if $F \subset B_{100}(0) \cap H$ then
\begin{equation*}\label{eq:RelationBarycenterBtilde}
    \widetilde{b}(F) = |F| \, {\rm bar}_H F.
\end{equation*}
Moreover
\begin{equation}\label{eq:LipschitzianitaDiBtilde}
\begin{split}
    \left| |\widetilde{b}(F)|^2 - |\widetilde{b}(G)|^2 \right| 
    &= \left||\widetilde{b}(F)| + |\widetilde{b}(G)| \right| \, \left| |\widetilde{b}(F)| - |\widetilde{b}(G)| \right| 
    \\&
    \le C(|F|+|G|) \left| \int_{F\Delta G} \left( \chi_F - \chi_G\right) (\psi(x_1),\ldots,\psi(x_{n-1}) ) \right|
    \\&
    \le C(|F|+|G|) |F\Delta G|,    
\end{split}
\end{equation}
for any $F,G\subset H$ with $|F|, |G| <+\infty$, for a universal constant $C>0$.\\
We recall that in \cref{def:capillarity-oscillation} we defined
\begin{equation*}
    \mu_{\lambda,0}^2(F) = \frac{1}{2} \int_{\partial^* F\cap H^+} \left|\nu_F(x)-\frac{x+\lambda e_n}{|x+\lambda e_n|}\right|^2\de \hausdorff^{n-1},
\end{equation*}
for any set of finite perimeter $F\subset H$ with $|F|<+\infty$.

We can fix $k_\lambda \in \N$ the least integer such that
\begin{equation}\label{eq:DefKlambda}
    k_\lambda\ge \max\{10, 4/(1-|\lambda|)\}.
\end{equation}
Hence for any set of finite perimeter $F\subset H$ with $|F|<+\infty$ and for any $k \in \N$ with $k\ge k_\lambda$, there holds
\begin{equation}\label{eq:PreConvention}
    P_\lambda(F) - \frac{1}{k}\mu_{\lambda,0}^2(F) \ge (1-|\lambda|) P(F,H^+) - \frac{2}{k} P(F,H^+) 
    \ge \frac{1-|\lambda|}{2} P(F,H^+) .
\end{equation}
Hence it is natural to define
\begin{equation}\label{eq:Convention}
    P_\lambda(F) - \frac{1}{k}\mu_{\lambda,0}^2(F) := + \infty,
\end{equation}
for any set $F\subset H$ with $|F|<+\infty$ and $P(F)=+\infty$, for any $k\ge k_\lambda$.

\begin{proposition}\label{prop:MinimizationProblemSelection}
    There exist $\Lambda_{\ref{prop:MinimizationProblemSelection}} >2n$, $k_{\ref{prop:MinimizationProblemSelection}} \ge k_\lambda, R_{\ref{prop:MinimizationProblemSelection}} \ge 10$,
    depending on $n,\lambda$ such that the following holds. For any $k \ge k_{\ref{prop:MinimizationProblemSelection}}$, $k \in \N$, adopting convention \eqref{eq:Convention}, the minimization problem
    \begin{equation}\label{eq:MinimizationProblemSelection}
        \inf \left\{
        \mathcal{F}_k(F) :=
            P_{\lambda}(F)+\Lambda_{\ref{prop:MinimizationProblemSelection}} \left||F|-|B^{\lambda}|\right|-\frac{1}{k}\mu_{\lambda,0}^2(F)+|\widetilde{b}(F)|^2
            \st 
            F\subset H, \,\, |F|<+\infty
        \right\}
    \end{equation}
    has an open minimizer $F_k$ such that
    \begin{itemize}
        \item $F_k \subset B_{R_{\ref{prop:MinimizationProblemSelection}}}(0)$,

         \item $|F_k|= |B^\lambda|$ for any $k\ge k_{\ref{prop:MinimizationProblemSelection}}$ sufficiently large,

         \item $\overline{\partial F_k \cap H^+}$ is a $C^{1,1/2}$-graph over $\S^{n-1}_+$ for any $k\ge k_{\ref{prop:MinimizationProblemSelection}}$ sufficiently large, and $\overline{\partial F_k \cap H^+} \to \overline{\partial B^\lambda \cap H^+}$ in $C^{1,\beta}$, for any $\beta \in (0,1/2)$, as $k\to \infty$, in the sense of \cref{def:DistanzaC1}.     
    \end{itemize}
\end{proposition}

\begin{proof}
Let $\Lambda> 2n$ and let $k \in \N$ with $k\ge k_\lambda$. We will fix $\Lambda=\Lambda_{\ref{prop:MinimizationProblemSelection}}$, depending on $n,\lambda$ only, at the end of the proof.
If $B^\lambda$ is a minimizer for \eqref{eq:MinimizationProblemSelection} for some $k\ge k_\lambda$, we can take $F_k= B^\lambda$, and any choice of $k_{\ref{prop:MinimizationProblemSelection}} \ge k_\lambda, R_{\ref{prop:MinimizationProblemSelection}} \ge 10$ satisfies the claim for such $k$'s. Hence, without loss of generality, we can assume that
\begin{equation*}
    \inf \left\{
    \mathcal{F}_k(F) 
        \st 
        F\subset H, \,\, |F|<+\infty
    \right\}
    < \mathcal{F}_k(B^\lambda) = P_\lambda(B^\lambda),
\end{equation*}
for any $k\ge k_\lambda$.

For any $k\ge k_\lambda$, let $\{\tilde E_j^k \st j \in \N, \, j\ge 1\}$ be a minimizing sequence for the $k$-th problem \eqref{eq:MinimizationProblemSelection} such that
\begin{equation*}
%\label{eq:zzMinimizingSeq}
    \mathcal{F}_k(\tilde E_j^k) \le \min\left\{ \inf \left\{
    \mathcal{F}_k(F) 
        \st 
        F\subset H, \,\, |F|<+\infty
    \right\} 
    + \frac1j
    , \mathcal{F}_k(B^\lambda) \right\}
\end{equation*}

We claim that there exist $\tilde{k}_{\ref{prop:MinimizationProblemSelection}}= \tilde{k}_{\ref{prop:MinimizationProblemSelection}}(n,\lambda)\ge k_\lambda$,
$K_{\ref{prop:MinimizationProblemSelection}} = K_{\ref{prop:MinimizationProblemSelection}}(n,\lambda,\Lambda)\ge 1$, $r_{\ref{prop:MinimizationProblemSelection}} = r_{\ref{prop:MinimizationProblemSelection}}(n,\Lambda, \lambda)  \in (0,1)$ such that there exists a new minimizing sequence $\{E_j^k \st j \in \N,\, j \ge 1\}$ for the $k$-th problem \eqref{eq:MinimizationProblemSelection} such that $E_j^k$ is a $(K_{\ref{prop:MinimizationProblemSelection}}, r_{\ref{prop:MinimizationProblemSelection}})$-quasi-minimizer for any $k \ge \tilde{k}_{\ref{prop:MinimizationProblemSelection}}$ and any $j \ge 1$.\\
To obtain the new sequence $\{E_j^k \st j \ge 1\}$, we apply Ekeland's variational principle, recalled in \cref{thm:Ekeland}, on the complete metric space
\[
    (\mathbb X,\d) := \Big( \{ F\subset H \st |F|<+\infty \}, \,\,\, \d(F,G):= \|\chi_F - \chi_G\|_{L^1(H)} =  |F \Delta G| \} \Big),
\]
and on the function $\mathcal{F}_k:\mathbb X \to [0,+\infty]$ for $k \ge k_\lambda$. In fact, the function $\mathcal{F}_k$ is lower semicontinuous on $(\mathbb X,\d)$ for any $k\ge k_\lambda$. Indeed, the summand $F \mapsto\Lambda\left| |F| - |B^\lambda| \right| + |\widetilde{b}(F)|^2$ is continuous with respect to $L^1(H)$ convergence. 
While, by \cref{lem:RiscritturaDiMuLambdaZero}, we can rewrite the other terms in $\mathcal{F}_k$ as
    \begin{equation}\label{eq:RewritingAsAnisotropicPerimeter}
    \begin{split}
        P_{\lambda}(F)&-\frac{1}{k}\mu_{\lambda,0}^2(F) =\\
        &= \int_{\partial^* F\cap H^+}1-\lambda\Braket{\nu_F(x),e_n}-\frac{1}{k}\left(1-\Braket{\nu_F(x),\frac{\lambda e_n}{\left|x-\Braket{x,e_n}e_n+\lambda e_n\right|}}\right)\de\hausdorff^{n-1}
         \\
        &\qquad\qquad\qquad\qquad\qquad\,\,\,\qquad
        -\frac{1}{k}\int_F\frac{n-1}{|x+\lambda e_n|}\de x\\
        &=
        P_{\Phi_k}(F) -\frac{1}{k}\int_F\frac{n-1}{|x+\lambda e_n|}\de x,
    \end{split}
    \end{equation}
    where $P_{\Phi_k}(F) := \int_{\partial^*F \cap H^+}\Phi_k(x, \nu_F) \de \hausdorff^{n-1}$ is the anisotropic perimeter with density $\Phi_k:H^+ \times \R^n \to \R$ defined by
    \begin{equation}\label{eq:DefPhik}
        \Phi_k(x, \nu) := \left( 1- \frac{1}{k}\right) |\nu| + \Braket{\nu, \left( \frac{1}{k}  \, \frac{1}{\left|x-\Braket{x, e_n}e_n + \lambda e_n\right|} -1\right) \lambda e_n }.
    \end{equation}
    The volume term $\int_F\frac{n-1}{|x+\lambda e_n|}\de x$ appearing in \eqref{eq:RewritingAsAnisotropicPerimeter} is clearly continuous with respect to $L^1(H)$ convergence of sets. On the other hand, for any $|\nu|=1$ there holds
    \[
    \begin{split}
        |\Phi_k(x,\nu)|
        &\ge 1- \frac{1}{k} - |\lambda|\left( 1 + 
        \frac{1}{k}  \, \frac{1}{|x-\Braket{x, e_n}e_n + \lambda e_n|} \right) 
        \ge 1- \frac{1}{k} - |\lambda|\left( 1 + 
        \frac{1}{k|\lambda|} \right) >0,
    \end{split}
    \]
for any $x\in H^+$ for any $k \ge k_\lambda$. Hence, by Reshetnyak lower semicontinuity theorem (see \cite[Theorem 2.38]{AmbrosioFuscoPallara} or \cite[Theorem~1.2]{Spector2011}), it follows that $P_{\Phi_k}$ is lower semicontinuous with respect to $L^1(H)$ convergence of sets.

Therefore, we can apply Ekeland's variational principle \cref{thm:Ekeland} with $x_0= \tilde{E}_j^k$, $\eps=1/j$ and $s=1$, for any $k \ge k_\lambda$, $j\ge 1$. We obtain sets $E_j^k \subset H$ with finite measure such that
\begin{equation}\label{eq:EkelandApplied}
\begin{split}
    \mathcal{F}_k(E_j^k) &\le \min\left\{ \inf \left\{
    \mathcal{F}_k(F) 
        \st 
        F\subset H, \,\, |F|<+\infty
    \right\} 
    + \frac1j
    , \mathcal{F}_k(B^\lambda) \right\}, \\
    \mathcal{F}_k(E_j^k)  &\le \mathcal{F}_k(G) + \frac1j |G \Delta E_j^k|, 
\end{split}
\end{equation}
for any $G\subset H$ with finite measure, for any $k \ge k_\lambda$, $j\ge 1$. We are left to check that $E_j^k$ is a quasi-minimizer, uniformly for large $k$ and $j\ge 1$ as claimed above. 

We first notice that
\begin{equation}\label{eq:MassMinimizingSeqCloseToBlambda}
   \frac12 \le \frac{|E_j^k|}{|B^\lambda|} \le \frac32,
\end{equation}
for any $k \ge k_\lambda$ and any $j\ge 1$. Indeed 
\begin{equation*}
    2n \left||E_j^k| - |B^\lambda| \right| < \Lambda  \left||E_j^k| - |B^\lambda| \right|
    \overset{\eqref{eq:PreConvention}}{\le} \mathcal{F}_k(E_j^k)
    \overset{\eqref{eq:EkelandApplied}}{\le} \mathcal{F}_k(B^\lambda) = P_\lambda(B^\lambda) = n |B^\lambda|.
\end{equation*}
Now let $G\subset H$ be a set of finite perimeter such that $G \Delta E_j^k \Subset B_r(x_0)$ for some $r\in(0,1), x_0 \in H$. 
Then
\begin{equation}\label{eq:zzmainstima}
    \begin{split}
        P_\lambda(E_j^k) &
        \overset{\eqref{eq:EkelandApplied}}{\le} \mathcal{F}_k(G) +  \frac1j |G \Delta E_j^k| -\Lambda \left| |E_j^k| - |B^\lambda| \right| + \frac{1}{k} \mu^2_{\lambda, 0}(E_j^k) - |\widetilde{b}(E_j^k)|^2 \\
        &\le \frac1j |G \Delta E_j^k|+ P_\lambda(G) +\Lambda \left| |G|-|E_j^k| \right| + \frac{1}{k} \left( \mu^2_{\lambda, 0}(E_j^k) - \mu^2_{\lambda, 0}(G) \right) 
        + |\widetilde{b}(G) |^2 - |\widetilde{b}(E_j^k)|^2
        \\
        & \overset{\eqref{eq:LipschitzianitaDiBtilde}}{\le} P_\lambda(G) + \left(\Lambda + \frac{1}{j}\right) |G \Delta E_j^k| 
        +\frac{1}{2k}\bigg(\int_{\partial^* E_j^k\cap H^+\cap B_r(x_0)}\left|\nu_{E_j^k}(x)-\frac{x+\lambda e_n}{|x+\lambda e_n|}\right|^2\de\hausdorff^{n-1}
         \\ 
         &\qquad -\int_{\partial^* G\cap H^+\cap B_r(x_0)}\left|\nu_{G}(x)-\frac{x+\lambda e_n}{|x+\lambda e_n|}\right|^2\de\hausdorff^{n-1} \bigg) 
        +C( n, \lambda) |G \Delta E_j^k|
        \\
        &\le 
         P_\lambda(G) + \left(\Lambda + \frac{1}{j}+ C( n, \lambda) \right) C_n r P(G \Delta E_j^k , H^+) \\
         &\qquad +\frac{2}{k} \left( P(E_j^k, B_r(x_0)\cap H^+)+P(G, B_r(x_0)\cap H^+) \right) \\
        &\le P_\lambda(G) + \left(\left( \Lambda + \frac{1}{j}+ C( n, \lambda) \right) C_n r 
        +\frac{2}{k}\right)\cdot
        \left( P(E_j^k;B_r(x_0)\cap H^+)+P(G;B_r(x_0)\cap H^+) \right) 
    \end{split} 
\end{equation}
where we estimated
\[
\begin{split}
    |G \Delta E_j^k | &= |G \Delta E_j^k |^{\frac1n}|G \Delta E_j^k |^{\frac{n-1}{n}} \le |B_r(x_0)|^{\frac1n} |G \Delta E_j^k |^{\frac{n-1}{n}} \le C_n r P(G \Delta E_j^k, H^+)\\
    &\le
    C_nr\left( P(E_j^k;B_r(x_0)\cap H^+)+P(G;B_r(x_0)\cap H^+) \right) ,
\end{split}
\]
for a dimensional constant $C_n$ obtained using the isoperimetric inequality in a half-space. Now recalling that
\[
P_\lambda(G) = \int_{\partial^* G} 1-\lambda\Braket{\nu_G, e_n}
= P_\lambda(E_j^k)
+
\int_{\partial^* G \cap B_r(x_0) \cap H^+} 1-\lambda\Braket{\nu_G, e_n}
- \int_{\partial^* E_j^k \cap B_r(x_0) \cap H^+} 1-\lambda\Braket{\nu_{E_j^k}, e_n},
\]
we conclude that
\begin{equation*}
\begin{split}
    (1-|\lambda|)& P(E_j^k, B_r(x_0)\cap H^+)
    \le (1+|\lambda|) P(G,B_r(x_0)\cap H^+) +\\
    &\qquad+\left(\left( \Lambda +\frac{1}{j}+ C( n, \lambda) \right) C_n r 
        +\frac{2}{k}\right)
        \left( P(E_j^k;B_r(x_0)\cap H^+)+P(G;B_r(x_0)\cap H^+) \right) 
\end{split}
\end{equation*}
It follows that there exist $\tilde{k}_{\ref{prop:MinimizationProblemSelection}}\ge k_\lambda$ depending on $n,\lambda$, and $r_{\ref{prop:MinimizationProblemSelection}} >0$ depending on $\Lambda, n,\lambda$ such that, as long as $r \le r_{\ref{prop:MinimizationProblemSelection}}$, there holds
\begin{equation*}
%\label{eq:MinSequenceISquasiminimizer}
    P(E_j^k,B_r(x_0)\cap H^+) \le K_{\ref{prop:MinimizationProblemSelection}} P(G,B_r(x_0)\cap H^+),
\end{equation*}
for a computable constant $K_{\ref{prop:MinimizationProblemSelection}} >0$ depending on $n,\lambda,\Lambda$, for any $k \ge \tilde{k}_{\ref{prop:MinimizationProblemSelection}}$ and any $j\ge 1$.

It follows from the regularity theory for quasi-minimizers, see \cref{thm:quasi-regularity}, that $E_j^k$ has an open representative and there exist $D_{\ref{prop:MinimizationProblemSelection}}, \rho_{\ref{prop:MinimizationProblemSelection}}\in(0,1)$ depending on $n,\lambda,\Lambda$ such that
\begin{equation}\label{eq:DensityMinimizingSeq}
    |E_j^k \cap B_\rho(x) | \ge D_{\ref{prop:MinimizationProblemSelection}} \rho^n,
\end{equation}
for any $\rho \le \rho_{\ref{prop:MinimizationProblemSelection}}$, $x \in \overline{E_j^k}$, $k \ge \tilde{k}_{\ref{prop:MinimizationProblemSelection}}$ and any $j\ge 1$.

\medskip

Up to enlarging the value of $\tilde{k}_{\ref{prop:MinimizationProblemSelection}}$, depending only on $n,\lambda$, we now want to prove the following crucial claim. Let $k_i\nearrow\infty$ be a subsequence, with $k_i\ge \tilde{k}_{\ref{prop:MinimizationProblemSelection}}$ for any $i$, and let $j_i \ge k_i$ be another subsequence. Let $A_i:= E_{j_i}^{k_i}$. We claim that 
\begin{equation}\label{eq:ClaimKEY}
|A_i\symmdiff B^{\lambda}|\leq \frac{\bar C_{n,\lambda}}{\sqrt{k_i}} \quad \forall i, \qquad
    \text{$\overline{\partial A_i \cap H^+} \to \overline{\partial B^\lambda \cap H^+}$ in Hausdorff distance, as $i\to \infty$.}
\end{equation}

    By definition of $A_i$, we have that $\mathcal{F}_{k_i}(A_i)\leq\mathcal{F}_{k_i}(B^{\lambda})$, and thus
    \begin{equation}\label{eq:subsub-Plambda}
        P_{\lambda}(A_i)+\Lambda||A_i|-|B^{\lambda}||-\frac{1}{k_i}\mu_{\lambda,0}^2(A_i)+|\widetilde b(A_i)|^2 \leq P_{\lambda}(B^{\lambda}),
    \end{equation}
    for any $i$.
    Since $k_i\geq k_{\lambda}$, by~\eqref{eq:PreConvention} we deduce that $P(A_i, H^+)\leq \frac{2}{1-|\lambda|}P_{\lambda}(B^{\lambda})$. Hence $\mu_{\lambda,0}^2(A_i) \le 2 P(A_i, H^+)\leq \frac{4}{1-|\lambda|}P_{\lambda}(B^{\lambda})$. Since $\Lambda>2n$, using the parameter $\bar\Lambda=\Lambda-n>n$ in \cref{lem:ProblemPlambda+LambdaVolumi}, we deduce from~\eqref{eq:subsub-Plambda} that
    \begin{equation}\label{eq:difference-measure-Plambda}
        n||A_i|-|B^{\lambda}||\leq \frac{1}{k_i}\mu_{\lambda,0}^2(A_i)\leq \frac{1}{k_i}\frac{4P_{\lambda}(B^{\lambda})}{1-|\lambda|} = \frac{1}{k_i}\frac{4n|B^{\lambda}|}{1-|\lambda|},
    \end{equation}
    for any $i$.
    Using \cref{thm:PPquantitativaFraenkelCapillare}, rearranging terms in~\eqref{eq:subsub-Plambda} and introducing the parameter $t_i:=\frac{|A_i|}{|B^{\lambda}|}$, we get
    \begin{equation}\label{eq:alpha-bar-Plambda}
        C_{n,\lambda}t_i^{\frac{n-1}{n}}P_{\lambda}(B^{\lambda})\alpha_{\lambda}^2(A_i)+|\widetilde b(A_i)|^2\leq P_{\lambda}(B^{\lambda})\left(1-t_i^{\frac{n-1}{n}}\right)+\frac{4P_{\lambda}(B^{\lambda})}{k_i(1-|\lambda|)},
    \end{equation}
    for some $C_{n,\lambda}>0$ and for any $i$, where we also used the bound $\mu_{\lambda,0}^2(A_i)\leq \frac{4}{1-|\lambda|}P_{\lambda}(B^{\lambda})$.\\
    Notice that $|t_i-1|\leq \frac{4}{k_i(1-|\lambda|)}$ for any $i$ thanks to~\eqref{eq:difference-measure-Plambda}. Therefore, we obtain $C_{n,\lambda}\alpha_{\lambda}^2(A_i)+|\widetilde b(A_i)|^2\leq \frac{C_{n,\lambda}'}{k_i}$ for any $i$, for some constants $C_{n,\lambda}, C'_{n,\lambda}>0$ that may change from line to line. This shows that, denoting by $x_i\in\partial H$ a point realizing the asymmetry $\alpha_{\lambda}(A_i)$, we get
    \begin{equation}\label{eq:zaqs}
        |A_i\symmdiff (x_i+B^{\lambda})| \leq \left|A_i\symmdiff (x_i+t_i^{1/n}B^{\lambda})\right|+\left|t_i^{1/n}B^{\lambda}\symmdiff B^{\lambda}\right|\overset{\eqref{eq:alpha-bar-Plambda}}{\leq} \frac{C_{n,\lambda}}{\sqrt{k_i}}+||A_i|-|B^{\lambda}|| \overset{\eqref{eq:difference-measure-Plambda}}{\leq} \frac{C_{n,\lambda}}{\sqrt{k_i}},
    \end{equation}
    for any $i$.\\
    Now it can be readily checked that $|\widetilde{b}(x_i + B^\lambda)| \ge c_{n,\lambda} \min\{1, |x_i|\}$ for any $i$. Moreover from~\eqref{eq:alpha-bar-Plambda} we also deduce that $|\widetilde b(A_i)|^2\leq \frac{C_{n,\lambda}}{k_i}$ for any $i$. Hence, arguing as in \eqref{eq:LipschitzianitaDiBtilde}, we estimate
    \begin{equation*}
        c_{n,\lambda} \min\{1, |x_i|\} \le |\widetilde b(A_i)| + \left| |\widetilde b(x_i+B^\lambda)| -  |\widetilde b(A_i)|\right|
        \le \frac{C_{n,\lambda}}{\sqrt{k_i}} + C_{n,\lambda} |A_i\symmdiff (x_i+B^{\lambda})|
        \overset{\eqref{eq:zaqs}}{\le} \frac{C_{n,\lambda}}{\sqrt{k_i}},
    \end{equation*}
    for any $i$. So there is $\bar{k}_{\ref{prop:MinimizationProblemSelection}}$ depending on $n,\lambda$ such that $\min\{1, |x_i|\} =|x_i|$ whenever $k_i \ge \bar{k}_{\ref{prop:MinimizationProblemSelection}}$, and the previous estimate yields an upper bound on $|x_i|$.
    Recalling \eqref{eq:zaqs}, this immediately implies that $|A_i\symmdiff B^{\lambda}|\leq \frac{\bar C_{n,\lambda}}{\sqrt{k_i}}$ for any $i$ such that $k_i \ge \bar{k}_{\ref{prop:MinimizationProblemSelection}}$. Up to updating $\tilde{k}_{\ref{prop:MinimizationProblemSelection}}$ with $\max\{ \tilde{k}_{\ref{prop:MinimizationProblemSelection}}, \bar{k}_{\ref{prop:MinimizationProblemSelection}}\}$, we can assume that $\tilde{k}_{\ref{prop:MinimizationProblemSelection}}\ge  \bar{k}_{\ref{prop:MinimizationProblemSelection}}$, whence $|A_i\symmdiff B^{\lambda}|\leq \frac{\bar C_{n,\lambda}}{\sqrt{k_i}}$ holds for any $i$.\\
    We already know that the sets $A_i$ satisfy the density estimates~\eqref{eq:DensityMinimizingSeq}. Up to decreasing $D_{\ref{prop:MinimizationProblemSelection}}, \rho_{\ref{prop:MinimizationProblemSelection}}$, we can assume that the same density estimates hold for $B^\lambda$.
    It is then standard to prove that whenever $\sqrt{k_i}>\tfrac{\bar C_{n,\lambda}}{D_{\ref{prop:MinimizationProblemSelection}}\rho_{\ref{prop:MinimizationProblemSelection}}^n}$, then $d_{\hausdorff}(\overline{\partial A_i\cap H^+}, \overline{\partial B^{\lambda}\cap H^+})\leq \rho_{\ref{prop:MinimizationProblemSelection}}$, hence    
    $|A_i\symmdiff B^{\lambda}|\geq D_{\ref{prop:MinimizationProblemSelection}}d_{\hausdorff}(\overline{\partial A_i\cap H^+}, \overline{\partial B^{\lambda}\cap H^+})^n$. Therefore
    \[
        d_{\hausdorff}(\overline{\partial A_i\cap H^+}, \overline{\partial B^{\lambda}\cap H^+})\leq C_{n,\lambda} k_i^{-1/2n}\qquad \text{when }\sqrt{k_i}>\frac{C_{n,\lambda}}{D_{\ref{prop:MinimizationProblemSelection}}\rho_{\ref{prop:MinimizationProblemSelection}}^n},
    \]
This completes the proof of claim \eqref{eq:ClaimKEY}.

\medskip

The key claim \eqref{eq:ClaimKEY} immediately implies
\begin{equation}\label{eq:FinalClaim}
    \exists\, \hat{k}_{\ref{prop:MinimizationProblemSelection}}(n,\lambda, \Lambda) \ge \tilde{k}_{\ref{prop:MinimizationProblemSelection}}, \, \hat{R}_{\ref{prop:MinimizationProblemSelection}}(n,\lambda, \Lambda)>0 \st \forall\, k \ge \hat{k}_{\ref{prop:MinimizationProblemSelection}}, \,\, j \ge k
    \implies
    E_j^k \subset B_{R_{\ref{prop:MinimizationProblemSelection}}}(0).
\end{equation}
Indeed, negating \eqref{eq:FinalClaim} means that for any $i \in \N$, $i \ge \tilde{k}_{\ref{prop:MinimizationProblemSelection}}$, there is $k_i\ge i$ and $j_i\ge k_i$ such that $|B_i(0) \setminus E_{j_i}^{k_i}| >0$. But \eqref{eq:DensityMinimizingSeq} together with \eqref{eq:ClaimKEY} give a contradiction.

For $k \ge \hat{k}_{\ref{prop:MinimizationProblemSelection}}$, letting $j\to \infty$ in the sequence $E_j^k$, by \eqref{eq:FinalClaim} we find a minimizer $F_k \subset B_{\hat{R}_{\ref{prop:MinimizationProblemSelection}}}$ for the minimization problem \eqref{eq:MinimizationProblemSelection}. Arguing as we did before with $F_k$ in place of $E_j^k$, it clearly follows that $F_k$ is a $(K_{\ref{prop:MinimizationProblemSelection}}, r_{\ref{prop:MinimizationProblemSelection}})$-quasi-minimizer, hence it has an open representative. Moreover, repeating the arguments of Step 2 above applied on the sequence $F_k$, we obtain that for every $k>\max\left\{\hat{k}_{\ref{prop:MinimizationProblemSelection}}, \left(\frac{C_{n,\lambda}}{D_{\ref{prop:MinimizationProblemSelection}}\rho_{\ref{prop:MinimizationProblemSelection}}^n}\right)^2\right\}$
\begin{equation}\label{eq:zzConvergenzaHausFk}
    %\text{$F_k \to B^\lambda$ in $L^1(H)$ and $\overline{\partial F_k \cap H^+} \to \overline{\partial B^\lambda \cap H^+}$ in Hausdorff distance, as $k\to \infty$.}
    |F_k\symmdiff B^{\lambda}|\leq \frac{\bar C_{n,\lambda}}{\sqrt{k}},\qquad d_{\hausdorff}(\overline{\partial F_k\cap H^+}, \overline{\partial B^{\lambda}\cap H^+})\leq C_{n,\lambda} k^{-1/2n}.%\qquad \text{when }\sqrt{k}>\frac{C_{n,\lambda}}{D_{\ref{prop:MinimizationProblemSelection}}\rho_{\ref{prop:MinimizationProblemSelection}}^n}.
\end{equation}

\medskip

In order to improve convergence of boundaries to $C^{1,\beta}$-convergence, we wish to apply \cref{thm:almost-regularity}. We first show that there exist $\Lambda'_{\ref{prop:MinimizationProblemSelection}}, r'_{\ref{prop:MinimizationProblemSelection}}>0$, depending on $n,\lambda, \Lambda$, such that $F_k$ is a $(\Lambda'_{\ref{prop:MinimizationProblemSelection}}, r'_{\ref{prop:MinimizationProblemSelection}})$-almost minimizer of $P_{\Phi_k}$ in $H$, for any large $k$. 
So let $G\subset H$ be a set of finite perimeter such that $G \Delta F^k \Subset B_r(x_0)$ for some $r\in(0,\tfrac14)$. Assume first that $x_0 \in H \setminus B_{\frac12}(-\lambda e_n)$. By \eqref{eq:RewritingAsAnisotropicPerimeter}, by minimality of $F_k$, estimating $|\widetilde{b}(G)|^2-|\widetilde{b}(F_k)|^2$ as done in \eqref{eq:zzmainstima}, we find
\begin{equation*}
    \begin{split}
        P_{\Phi_k}(F_k) 
        &\le 
               P_{\Phi_k}(G) + (C(n,\lambda)+ \Lambda) |G \Delta F_k|
               + \frac{n-1}{k} \left(
               \int_{F_k} \frac{1}{|x+\lambda e_n|}
                - \int_{G} \frac{1}{|x+\lambda e_n|}
               \right)
        \\
        &
        \le 
            P_{\Phi_k}(G) + (C(n,\lambda)+ \Lambda) |G \Delta F_k|
               + \frac{n-1}{k} \left(
               \int_{G\Delta F_k} \frac{1}{|x+\lambda e_n|}
               \right).
    \end{split}
\end{equation*}
Since  $r\in(0,\tfrac14)$ and $x_0 \in H \setminus B_{\frac12}(-\lambda e_n)$, then $\frac{1}{|x+\lambda e_n|} \le 4$ almost everywhere on $G\Delta F_k$, hence
\begin{equation*}
    \begin{split}
        P_{\Phi_k}(F_k, B_r(x_0)) 
        &\le
            P_{\Phi_k}(G, B_r(x_0)) + \left( C(n,\lambda)+ \Lambda + \frac{4(n-1)}{k} \right) |G \Delta F_k|\\&
            \le 
             P_{\Phi_k}(G, B_r(x_0)) + \Lambda'_{\ref{prop:MinimizationProblemSelection}} |G \Delta F_k|.
    \end{split}
\end{equation*}
On the other hand, if $x_0 \in B_{\frac12}(-\lambda e_n)$ instead, by \eqref{eq:zzConvergenzaHausFk} for $k$ large we simply have $P_{\Phi_k}(F_k, B_r(x_0)) =0 \le P_{\Phi_k}(G, B_r(x_0)) + \Lambda'_{\ref{prop:MinimizationProblemSelection}} |G \Delta F_k|.$ 
Hence the claimed almost minimality of $F_k$ for $P_{\Phi_k}$ follows. Moreover, recalling the definition \eqref{eq:DefPhik} of $\Phi_k$, it can be readily checked that $\Phi_k$ is a regular elliptic integrand with $\Phi_k \in \mathcal{E}(H^+,l_1,l_2)$ for some constants $l_1\ge1, l_2 >0$, for any $k$ large, in the sense of \cref{def:unif-elliptic-perimeter}. Therefore, recalling \eqref{eq:zzConvergenzaHausFk}, we can apply \cref{thm:almost-regularity}, which implies that $\overline{\partial F_k \cap H^+}$ is a $C^{1,1/2}$-graph over $\S^{n-1}_+$ for large $k$ and that $\overline{\partial F_k \cap H^+} \to \overline{\partial B^\lambda \cap H^+}$ in $C^{1,\beta}$ for any $\beta \in (0,1/2)$, as $k\to \infty$.% If necessary, we enlarge $\hat k_{\ref{prop:MinimizationProblemSelection}}$ so that $\overline{\partial F_k\cap H^+}$ is a $C^{1,1/2}$ graph over $\S^{n-1}_+$ for any $k\geq \hat k_{\ref{prop:MinimizationProblemSelection}}$. DA SISTEMARE

\medskip

Finally we want to prove that there is a choice of $\Lambda = \Lambda_{\ref{prop:MinimizationProblemSelection}}(n,\lambda)$ such that, taking $R_{\ref{prop:MinimizationProblemSelection}}:=\hat{R}_{\ref{prop:MinimizationProblemSelection}}(n,\lambda,$ $\Lambda_{\ref{prop:MinimizationProblemSelection}})$ and $k_{\ref{prop:MinimizationProblemSelection}} = \hat{k}_{\ref{prop:MinimizationProblemSelection}}(n,\lambda,\Lambda_{\ref{prop:MinimizationProblemSelection}})$, then the statement follows. So we are left to prove that there is such a choice of $\Lambda$ so that $|F_k|=|B^\lambda|$ for any $k \ge k_{\ref{prop:MinimizationProblemSelection}}$ large enough.\\
Similarly to \cite[Step 3 in the proof of Theorem~1.1]{Neumayer16}, we test the minimality of $F_k$ with the competitor $s_kF_k$, where $s_k = (|B^{\lambda}|/|F_k|)^{1/n}$. We get
    \[
    \begin{split}
        P_{\lambda}(F_k)&+\Lambda||F_k|-|B^{\lambda}||-\frac{1}{k}\mu_{\lambda,0}^2(F_k)+
        \left| 
        \int_{F_k} \psi(x') \de x
        \right|^2
        \\ &
        \leq s_k^{n-1}P_{\lambda}(F_k)-\frac{1}{k}\mu_{\lambda,0}^2(s_kF_k)+s_k^{2n}
        \left| 
        \int_{F_k} \psi(s_k x') \de x
        \right|^2
        ,
    \end{split}
    \]
where $\psi(z'):=(\psi(z_1), \ldots, \psi(z_{n-1}))$ for $z = (z',z_n) \in \R^n$. Since $\psi$ is $1$-Lipschitz, then $|\psi(s_k x') - \psi(x')| \le |s_k-1||x'| \le 10 |s_k-1|$ for any $x \in F_k$ and $k \ge \hat{k}_{\ref{prop:MinimizationProblemSelection}}$ large enough by \eqref{eq:zzConvergenzaHausFk}. Hence
\begin{equation*}
\begin{split}
    \Lambda||F_k|-|B^{\lambda}|| & \leq |s_k^{n-1}-1| P_{\lambda}(F_k)
        +\frac{1}{k} \left( \mu_{\lambda,0}^2(F_k) -\mu_{\lambda,0}^2(s_kF_k) \right)
        +|s_k^{2n} -1|\, |\widetilde{b}(F_k)|^2
        \\
        &\qquad + s_k^{2n}(|\widetilde b(s_kF_k)|+|\widetilde{b}(F_k)|)(|\widetilde b(s_kF_k)|-|\widetilde{b}(F_k)|)\\
        &\leq |s_k^{n-1}-1| P_{\lambda}(F_k)
        +\frac{1}{k} \left( \mu_{\lambda,0}^2(F_k) -\mu_{\lambda,0}^2(s_kF_k) \right)
        +|s_k^{2n} -1|\, |\widetilde{b}(F_k)|^2
        \\
        &\qquad+ 10 s_k^{2n}(|\widetilde b(s_kF_k)|+|\widetilde{b}(F_k)|)|s_k-1|\, |F_k|
\end{split}
\end{equation*}
We already know that $F_k\to B^{\lambda}$ in $L^1(H)$, and thus $s_k\to1$. Moreover, there exists a geometric constant $C>0$ such that
    \begin{equation}\label{eq:GeometricEstimate}
        \left|v-\frac{w+z}{|w+z|}\right|^2\geq \left|v-\frac{w}{|w|}\right|^2-C|z|,
    \end{equation}
    for any $v,w,z\in\R^n$ with $|v|=1$, $|w|\geq 1/2$ and $|z|\leq 1/4$.    
    Recalling that $\partial F_k\cap H^+\subset B_{2}(-\lambda e_n)\setminus B_{1/2}(-\lambda e_n)$ for $k$ large, we can apply \eqref{eq:GeometricEstimate} with $v=\nu_{F_k}(x)$, $w=x+\lambda e_n$ and $z=(s_k-1)x$, for $x\in\partial F_k\cap H^+$.
    In particular, as also $P_{\lambda}(F_k), |\widetilde{b}(F_k)|, \mu_{\lambda,0}(F_k), P(F_k) \le C(n,\lambda)$ for any $k$ large, we obtain
    \[
    \begin{split}
        \Lambda &\left||F_k|-|B^{\lambda}|\right|\leq 
        C(|s_k^{n-1}-1| + |s_k^{2n} -1 | +  |s_k-1|)
        +\\
        & + \frac{1}{2k}\left(\int_{\partial^* F_k \cap H^+}\left|\nu_{F_k}(x)-\frac{x+\lambda e_n}{|x+\lambda e_n|}\right|^2\de\hausdorff^{n-1}
        -
        s_k^{n-1}\int_{\partial^* F_k \cap H^+}\left|\nu_{F_k}(x)-\frac{s_kx+\lambda e_n}{|s_kx+\lambda e_n|}\right|^2\de\hausdorff^{n-1}\right)\\
        &\overset{\eqref{eq:GeometricEstimate}}{\leq} 
        C(|s_k^{n-1}-1| + |s_k^{2n} -1 | +  |s_k-1|)
        + \frac{1}{2k} |s_k^{n-1}-1|\int_{\partial^* F_k \cap H^+}\left|\nu_{F_k}(x)-\frac{x+\lambda e_n}{|x+\lambda e_n|}\right|^2\de\hausdorff^{n-1}\\
        &\qquad + \frac{s_k^{n-1}}{2k}\int_{\partial^* F_k \cap H^+} C|s_k-1||x|\de\hausdorff^{n-1}\\
        &\leq C|s_k-1|,
    \end{split}
    \]
    where we used that the power functions $t\to |t^{n-1}-1|$ and $t\to|t^{2n}-1|$ are locally Lipschitz. On the other hand
    \[
    \left||F_k|-|B^{\lambda}|\right| = |F_k| |s_k^n -1| = |F_k| |s_k-1| (1+s_k+\ldots+s_k^{n-1}) \overset{\eqref{eq:MassMinimizingSeqCloseToBlambda}}{\ge} \frac 12 |B^\lambda| |s_k-1|.
    \]
    Therefore, if by contradiction $s_k\neq 1$ for some $k$ large, the last two estimates imply $\Lambda \le C=C(n,\lambda)$, which is impossible for a choice of $\Lambda$ sufficiently large depending on $n,\lambda$ only.
\end{proof}



\begin{theorem}[Strong quantitative inequality in capillarity problems]\label{thm:capillarityStrongQuantitative}
There exists $C_{\ref{thm:capillarityStrongQuantitative}}>0$ depending on $n,\lambda$ such that for any set of finite perimeter $E \subset H$ with $|E|<+\infty$ there holds
\begin{equation*}\label{eq:strong-quantitative-capillarity}
    \mu_\lambda^2(E) \le C_{\ref{thm:capillarityStrongQuantitative}} D_\lambda(E).
\end{equation*}
\end{theorem}

\begin{proof}
By scale invariance of the oscillation asymmetry and of the deficit, we can prove the claim for sets having volume equal to $|B^\lambda|$. Suppose by contradiction that there exists a sequence of sets of finite perimeter $E_k\subset H$ such that $|E_k|=|B^{\lambda}|$ but $k^2D_{\lambda}(E_k)< \mu_{\lambda}^2(E_k)$, for any $k \in \N$ with $k\ge 1$. In particular, $E_k$ does not coincide with the translation of a truncated ball $B^{\lambda}$ for every $k\in\N$, and thus $D_{\lambda}(E_k)>0$. Without loss of generality, up to translation along $\partial H$ we can assume that $\widetilde{b}( E_k)=0$. Since $\mu_{\lambda}^2(E_k)\leq 2P(E_k;H^+)\leq \frac{2}{1-|\lambda|}P_{\lambda}(E_k)$, it follows that $E_k$ satisfies $(k^2-C)P_{\lambda}(E_k)\leq k^2P_{\lambda}(B^{\lambda})$ for some constant $C$ depending on $n$ and $\lambda$, so in particular $D_{\lambda}(E_k)\to0$ as $k\to\infty$. Moreover, by definition of $\mu_{\lambda}^2(E_k)$ and by the contradiction assumption, we have
\begin{equation}\label{eq:zzMuZeroEk}
    0< D_{\lambda}(E_k)< \frac{1}{k^2}\mu_{\lambda}^2(E_k)\leq\frac{1}{k^2}\mu_{\lambda,0}^2(E_k).
\end{equation}

We apply \cref{prop:MinimizationProblemSelection}. There exist constants $\Lambda_{\ref{prop:MinimizationProblemSelection}} >2n$, $k_{\ref{prop:MinimizationProblemSelection}} \ge k_\lambda, R_{\ref{prop:MinimizationProblemSelection}} \ge 10$,
depending on $n,\lambda$ such that, for any $k \ge k_{\ref{prop:MinimizationProblemSelection}}$, the minimization problem
\begin{equation*}
    \inf \left\{
    \mathcal{F}_k(F) :=
        P_{\lambda}(F)+\Lambda_{\ref{prop:MinimizationProblemSelection}} \left||F|-|B^{\lambda}|\right|-\frac{1}{k}\mu_{\lambda,0}^2(F)+|\widetilde{b}(F)|^2
        \st 
        F\subset H, \,\, |F|<+\infty
    \right\}
\end{equation*}
has an open minimizer $F_k$ such that 
\begin{itemize}
    \item $F_k \subset B_{R_{\ref{prop:MinimizationProblemSelection}}}(0)$, 

     \item $|F_k|= |B^\lambda|$ for any $k\ge k_{\ref{prop:MinimizationProblemSelection}}$ sufficiently large,

     \item for any $k\ge k_{\ref{prop:MinimizationProblemSelection}}$ sufficiently large, there exists $u_k\in C^{1,1/2}(\S^{n-1}_+)$ such that $\overline{\partial F_k \cap H}= \{(w_{\lambda}(x)+u_k(x))x:x\in\S^{n-1}_+\}$, where $w_\lambda$ was defined in \cref{def:DistanzaC1}, and $u_k\to 0$ in $C^{1, \beta}(\S^{n-1}_+)$ for any $\beta \in (0,1/2)$.   
\end{itemize}

Testing minimality of $F_k$ with the competitor $E_k$, which satisfies $\widetilde{b} (E_k)=0$ and $|E_k|=|B^{\lambda}|$, and exploiting \cref{lem:ProblemPlambda+LambdaVolumi}, we get the chain of estimates
    \begin{equation}\label{eq:energy-comparison-FE}
    \begin{split}
    P_{\lambda}(F_k)-\frac{1}{k}\mu_{\lambda,0}^2(F_k)+|\widetilde{b} (F_k)|^2
        &=P_{\lambda}(F_k)+\Lambda_{\ref{prop:MinimizationProblemSelection}} \left||F_k|-|B^{\lambda}|\right|-\frac{1}{k}\mu_{\lambda,0}^2(F_k)+|\widetilde{b} (F_k)|^2\\
        &\leq P_{\lambda}(E_k)-\frac{1}{k} \mu_{\lambda,0}^2(E_k)\\
        &\overset{\eqref{eq:zzMuZeroEk}}{\leq} P_{\lambda}(B^{\lambda})+\frac{P_{\lambda} (B^{\lambda})}{k^2}  \mu_{\lambda,0}^2(E_k) -\frac{1}{k}\mu_{\lambda,0}^2(E_k)\\
        &\leq P_{\lambda}(F_k)+\Lambda_{\ref{prop:MinimizationProblemSelection}} \left||F_k|-|B^{\lambda}|\right|+\frac{P_{\lambda} (B^{\lambda})}{k^2}  \mu_{\lambda,0}^2(E_k)-\frac{1}{k} \mu_{\lambda,0}^2(E_k)
        \\
        &=  P_{\lambda}(F_k)+\frac{P_{\lambda} (B^{\lambda})}{k^2}  \mu_{\lambda,0}^2(E_k)-\frac{1}{k} \mu_{\lambda,0}^2(E_k)
    \end{split}
    \end{equation}
    for any $k\ge k_{\ref{prop:MinimizationProblemSelection}}$ sufficiently large. Observe that
    \begin{equation}\label{eq:zwq}
        \frac{P_{\lambda} (B^{\lambda})}{k^2}  \mu_{\lambda,0}^2(E_k)-\frac{1}{k} \mu_{\lambda,0}^2(E_k) 
        \le -\frac{1}{2k} \mu_{\lambda,0}^2(E_k),
    \end{equation}
    for any $k$ large enough. Hence \eqref{eq:energy-comparison-FE} implies that for every $k$ large enough
    \begin{equation}\label{eq:mu-bar-estimate}
        0<  \mu_{\lambda,0}^2(E_k) \leq 2\mu_{\lambda,0}^2(F_k),
        \qquad\qquad
        |\widetilde{b} (F_k)|^2\leq \frac{1}{k}\mu_{\lambda,0}^2(F_k).
    \end{equation}
Since we know that $|F_k|=|B^{\lambda}|$ for $k\ge k_{\ref{prop:MinimizationProblemSelection}}$ large enough, using \eqref{eq:zwq} we may rearrange the terms in the first and third lines of~\eqref{eq:energy-comparison-FE} to get
    \[
    D_{\lambda}(F_k)\leq \frac{\mu_{\lambda,0}^2(F_k)}{k\cdot P_{\lambda}(B^{\lambda})} .
        % D_{\lambda}(F_k)\leq \frac{1}{k} \mu_{\lambda,0}^2(E_k) +\frac{\mu_{\lambda,0}^2(F_k)}{P_{\lambda}(B^{\lambda})\sqrt{k}} \overset{\eqref{eq:mu-bar-estimate}}{\le}  C\frac{\mu_{\lambda,0}^2(F_k)}{\sqrt k},
    \]
For $k$ large enough, we have $\|u_k\|_{C^1(\S^{n-1}_+)}<\min\{\eps_{\ref{lem:OScillationBoundedByH1Norm}},\epsilon_{\ref{prop:FugledeCapillarity}}\}$, thus we can apply \cref{lem:OScillationBoundedByH1Norm} and \cref{prop:FugledeCapillarity} to continue the previous estimate as
    \begin{equation}\label{eq:final-quantitative}
    \begin{split}
        D_{\lambda}(F_k)&\leq \frac{\mu_{\lambda,0}^2(F_k)}{k P_{\lambda}(B^{\lambda})} 
        \le \frac{1}{k P_{\lambda}(B^{\lambda})} C_{\ref{lem:OScillationBoundedByH1Norm}} \|u_k \|^2_{H^1(\S^{n-1}_+)}
        \leq \frac{1}{k P_{\lambda}(B^{\lambda})}
        C_{\ref{lem:OScillationBoundedByH1Norm}}
        C_{\ref{prop:FugledeCapillarity}}
        \left(D_{\lambda}(F_k)+|\barycenter_H F_k|^2\right).
        % \\
        % &
        % = \frac{C}{\sqrt k}
        % C_{\ref{lem:OScillationBoundedByH1Norm}}
        % C_{\ref{prop:FugledeCapillarity}}
        % \left(D_{\lambda}(F_k)+ |F_k|^{-2} |\widetilde{b} (F_k)|^2\right). 
    \end{split}
    \end{equation}
    Since $|F_k|=|B^\lambda|$ and $\barycenter_H F_k = |B^\lambda|^{-1}\widetilde{b}(F_k)$ by \eqref{eq:AlternativeBarycenter}, then \eqref{eq:mu-bar-estimate} implies $|\barycenter_H F_k|^2 \le \tfrac{1}{k|B^\lambda|^2} \mu^2_{\lambda,0}(F_k)$. Hence, using \cref{lem:OScillationBoundedByH1Norm} and \cref{prop:FugledeCapillarity} again as above, we find
    \[
        |\barycenter_H F_k|^2 \le \frac{\mu_{\lambda,0}^2(F_k)}{k|B^\lambda|^2}
        \leq \frac{1}{k|B^\lambda|^2}C_{\ref{lem:OScillationBoundedByH1Norm}}
        C_{\ref{prop:FugledeCapillarity}} \left(D_{\lambda}(F_k)+|\barycenter_H F_k|^2\right).
    \]
    Hence, for $k$ large enough, there holds $|\barycenter_H F_k|^2\leq D_{\lambda}(F_k)$. Plugging this estimate in \eqref{eq:final-quantitative} we deduce
    \[
    D_\lambda(F_k) \le \frac12 D_\lambda(F_k),
    \]
    for any $k$ large enough. Hence $D_\lambda(F_k)=0$ for $k$ large, which, recalling that $|F_k|=|B^\lambda|$ and that $|\barycenter_H F_k|^2\leq D_{\lambda}(F_k)$, implies that $F_k$ exactly coincides with the standard bubble $B^\lambda$ with zero barycenter. In particular, $\mu^2_{\lambda,0}(F_k)=0$ for large $k$. This contradicts \eqref{eq:mu-bar-estimate}, which guarantees that $\mu_{\lambda,0}^2(F_k)>0$ for every $k$ large enough.
\end{proof}



\subsection{Strong quantitative inequalities with barycentric asymmetry in capillarity problems}\label{sec:BarycentricCapillarity}

As pointed out in the introduction, the proof of \cref{thm:capillarityStrongQuantitative} provides, in fact, the following more explicit and stronger inequality.

\begin{corollary}[Barycentric strong quantitative inequality in capillarity problems 1]\label{cor:tilde-bar-quantitative}
    There exists a constant $C_{\ref{cor:tilde-bar-quantitative}}>0$ depending only on $n$ and $\lambda$ such that, for every $E\subset H$ of finite perimeter with $|E|=|B^{\lambda}|$, and for any point $x^*\in\partial H$ such that $\widetilde b(E-x^*)=0$ there holds
    \[
        \int_{\partial^*E\cap H^+} \left|\nu_E(x)-\frac{x-(x^*,-\lambda)}{|x-(x^*,-\lambda)|}\right|^2\de\hausdorff^{n-1}_x\leq C_{\ref{cor:tilde-bar-quantitative}} D_{\lambda}(E).
    \]
\end{corollary}

\cref{cor:tilde-bar-quantitative} follows by arguing by contradiction exactly as in the proof of \cref{thm:capillarityStrongQuantitative}. Indeed, one starts by assuming by contradiction that there is a sequence of sets $U_k\subset H$ with $|U_k|=|B^{\lambda}|$, such that $k^2 D_{\lambda}(U_k)<\int_{\partial^*U_k\cap H^+} \left|\nu_{U_k}(x)-\frac{x-(x^*_k,-\lambda)}{|x-(x^*_k,-\lambda)|}\right|^2$ for some $x^*_k$ such that $\widetilde{b}(U_k- x^*_k)=0$. Taking the translated sets $E_k:=U_k- x^*_k$, then $k^2 D_\lambda(E_k)=k^2 D_{\lambda}(U_k) <\mu^2_{\lambda,0}(E_k)$, and $E_k$ is the starting contradicting sequence in the proof of \cref{thm:capillarityStrongQuantitative}.\\
However, $x^*$ in \cref{cor:tilde-bar-quantitative} might differ from $\frac{1}{|E|}\widetilde b(E)$ since the function $\psi$ in the definition of $\widetilde b$ is not linear.
%Moreover, points $x^*\in\partial H$ such that $\widetilde b(E-x^*)=0$ might be non-unique in general.

Notice that we can take $x^*=\barycenter_H E$ in \cref{cor:tilde-bar-quantitative} for every set $E$ with $\diam_H E\leq 100$ thanks to~\eqref{eq:AlternativeBarycenter}, where $\diam_H E$ is the diameter of the orthogonal projection of $E$ onto $\partial H$. More generally, given $d>\diam_H B^{\lambda}$ an upper bound of the diameter of the considered sets, taking the function $\psi_d \coloneqq d\psi(\cdot/d)$ in place of $\psi$, and running the same proof presented above, one obtains the following barycentric quantitative inequality for the oscillation asymmetry.

\begin{corollary}[Barycentric strong quantitative inequality in capillarity problems 2]\label{cor:bar-quantitative}
    Let $d>\diam_H B^{\lambda}$ be given. Then there exists a constant $C_{\ref{cor:bar-quantitative}}>0$ depending only on $n$, $\lambda$ and $d$ such that, for every $E\subset H$ of finite perimeter with $|E|=|B^{\lambda}|$ and $\diam_H E\leq d$ there holds
    \begin{equation}\label{eq:bar-quantitative}
        \int_{\partial^*E\cap H^+} \left|\nu_E(x)-\frac{x-(\barycenter_H E,-\lambda)}{|x-(\barycenter_H E,-\lambda)|}\right|^2\de\hausdorff^{n-1}_x\leq C_{\ref{cor:bar-quantitative}} D_{\lambda}(E).
    \end{equation}
\end{corollary}
Our approach does not provide an explicit control of the constant $C_{\ref{cor:bar-quantitative}}$ in terms of the diameter of the sets. However, we remark that the dependence of the constant $C_{\ref{cor:bar-quantitative}}$ on the diameter is necessary in dimension $n\geq3$. Indeed, as analogously pointed out in \cite{GambicchiaPratelli2025}, one can take a sequence of sets $E_j = B^\lambda(|B^\lambda|-\eps_j, x_j) \cup B^\lambda(\eps_j, y_j)$, with $\eps_j\to0$ and suitable mutually diverging points $x_j, y_j \in \partial H$ so that $\barycenter_H E_j =0$, $D_\lambda(E_j) \to 0$, but the left hand side of \eqref{eq:bar-quantitative} with $E=E_j$ tends to a positive constant as $j\to\infty$. 

\medskip

Additionally, we remark that our method can be applied to obtain the quantitative isoperimetric inequality with barycentric Fraenkel asymmetry as follows.

\begin{corollary}[Barycentric quantitative inequality in capillarity problems]\label{cor:barycentric-Fraenkel}
    There exists a constant $C_{\ref{cor:barycentric-Fraenkel}}>0$ depending only on $n$ and $\lambda$ such that, for every $E\subset H$ of finite perimeter with $|E|=|B^{\lambda}|$, and for any point $x^*\in\partial H$ such that $\widetilde b(E-x^*)=0$, we have the following inequality:
    \[
        |E\symmdiff (B^{\lambda}+x^*)|^2\leq C_{\ref{cor:barycentric-Fraenkel}} D_{\lambda}(E).
    \]
    If $\diam_H E\le d <+\infty$, there exists a constant $C_{\ref{cor:barycentric-Fraenkel}}'>0$ depending only on $n$, $\lambda$ and $d$ such that
    \[
        |E\symmdiff (B^{\lambda}+\barycenter_H E)|^2\leq C_{\ref{cor:barycentric-Fraenkel}}' D_{\lambda}(E).
    \]
\end{corollary}

\begin{proof}
    We provide some details about the necessary adaptations to obtain the first inequality since here we use a different notion of asymmetry. 
    For a set $E\subset H$ with $\overline{\partial E\cap H^+} = \{(w_{\lambda}(x)+u(x))x: x\in\S^{n-1}_+\}$, and $\|u\|_{C^1}\ll1$, as in the proof of \cref{prop:FugledeCapillarity} one estimates $|E\symmdiff B^{\lambda}|\lesssim \|u\|_{L^1}\lesssim \|u\|_{L^2}\leq \|u\|_{H^1}$. This replaces \cref{lem:OScillationBoundedByH1Norm}. Then, we can run the selection principle in \cref{prop:MinimizationProblemSelection} and \cref{thm:capillarityStrongQuantitative} replacing $\mu_{\lambda,0}(F)$ with
    \[
        A_{\lambda,0}(F) := |F\symmdiff B^{\lambda}|.
    \]
    Since the Fraenkel asymmetry corresponds to a ``volume term'',  the application of the regularity theory is just simpler, and the proof follows.
\end{proof}




