    \\&
    \overset{\eqref{eq:ElementarySharpness}}{\le}
     \int_{\partial^* E_t \cap H^+} \bigg| \nu_{E_t} - \frac{x-(x',-\lambda)}{|x-(x',-\lambda)|} \bigg|^2 
    + \bigg| 
    \frac{x-(-x',-\lambda)}{|x-(-x',-\lambda)|} - \frac{x-(x',-\lambda)}{|x-(x',-\lambda)|} \bigg|^2 
    \\&
    \le 
