\section{Strong quantitative isoperimetric inequalities in convex cones}\label{sec:cones}


\noindent\textbf{List of new symbols related to this section.}


\begin{itemize}

\item A closed convex cone $\mathcal{C}\subset \R^n$ with non-empty interior will be always written as $\mathcal{C}= \R^m \times \widetilde{\mathcal{C}}$, where $\widetilde{\mathcal{C}}$ does not contain lines. We will always assume that $0$ is a tip of $\mathcal{C}$.

\item $\interior{\mathcal{C}}$ denotes the interior of a cone $\mathcal{C}$.

\item $P_\mathcal{C}(E):= \hausdorff^{n-1}(\partial^*E \setminus \partial \mathcal{C}) = P(E,\interior{\mathcal{C}})$ denotes the relative perimeter in a cone $\mathcal{C}$.

\item $K_{\mathcal{C}}:= B_1(0) \cap \mathcal{C}$.

\item $\alpha_{\mathcal{C}}(E)$, $D_{\mathcal{C}}(E)$, $\mu_{\mathcal{C}}(E)$, $\mu_{\mathcal{C},0}(E)$ denote Fraenkel asymmetry, deficit, and oscillation asymmetries of a set $E$ in a cone $\mathcal{C}$, defined in \cref{def:AsymmetriesDeficitInCones}.

\item $\Sigma_{\mathcal{C}} := \mathcal{C} \cap \S^{n-1}$ denotes the cross section of a cone $\mathcal{C}$.

\item $\barycenter_{\R^m} E$ denotes the barycenter of a set $E$ with respect to the factor $\R^m$ in a cone $\mathcal{C}= \R^m \times \widetilde{\mathcal{C}}$, defined in \eqref{eq:DefBaricentroConi}. 

\item $ \widetilde b_{\R^m}(F) = \int_F (\psi(x_1),\ldots,\psi(x_m))\de x$, for any measurable set $F$ in a cone $\mathcal{C}=\R^m\times \widetilde{\mathcal{C}}$ with $|F|<+\infty$, defined in \eqref{eq:DefBaricentroTILDEconi}.

\item For $m \in\{0,\ldots, n-1\}$ fixed, spaces $\R^m, \R^{n-m}$ are identified with subspaces of $\R^n$ by $\R^n= \R^m \times \R^{n-m}$. Vectors $x' \in \R^m$, $\widetilde{x} \in \R^{n-m}$ are thus identified with $(x',0)\in \R^n$, $(0,\widetilde{x})\in \R^n$, respectively.

\end{itemize}


% As mentioned in the introduction, it is well-known that if $\mathcal{C}=\R^m\times \widetilde{\mathcal{C}} \subset  \R^n$ is a closed convex cone with non-empty interior, where $\widetilde{\mathcal{C}}$ does not contain lines, then isoperimetric sets in $\mathcal{C}$ are given by relative balls $B_r(p,0)\cap \mathcal{C}$ for any $r>0$ and $p \in \R^m$ \cite{BaerFigalli17, LionsPacella1990}. The same conclusion can be proved for a large class of weighted convex cones \cite{CabreRosOtonSerra}, meaning that perimeter and volume are weighted by a function satisfying a suitable concavity property. Sharp isoperimetric inequalities for the Fraenkel asymmetry for these problems in cones have been provided in \cite{FigalliIndrei} and in \cite{CintiGlaudoPratelliRosOtonSerra2022} for the weighted case.

We aim to obtain a sharp quantitative isoperimetric inequality in convex cones in the strong form, similarly to what we did in the previous section. We first collect the notions of asymmetry and deficit that we are going to use.

\begin{definition}\label{def:AsymmetriesDeficitInCones}
    Let $\mathcal{C}\subset \R^n$ be a closed convex cone with non-empty interior $\interior{\mathcal{C}}$. Write $\mathcal{C}=\R^m\times \widetilde{\mathcal{C}}$ where $\widetilde{\mathcal{C}}$ does not contain lines. Let $K_{\mathcal{C}}:= B_1(0) \cap \mathcal{C}$ and let $E \subset \mathcal{C}$ be a measurable set with $|E|\in(0,+\infty)$. For $s>0$ such that $|E|=|sK_{\mathcal{C}}|$, we define the Fraenkel asymmetry
    \[
    \alpha_{\mathcal{C}}(E) := \inf \left\{
    \frac{|E \Delta ((x',0)+sK_{\mathcal{C}})|}{|E|} \st x' \in \R^m,
    \right\}
    \]
    and the isoperimetric deficit
    \[
    D_{\mathcal{C}}(E) := \frac{P_{\mathcal{C}}(E) - P_{\mathcal{C}}(sK_{\mathcal{C}})}{P_{\mathcal{C}}(sK_{\mathcal{C}})} = \frac{P_{\mathcal{C}}(E)}{n|K_{\mathcal{C}}|^{\frac1n} |E|^{\frac{n-1}{n}}} -1,
    \]
    where $P_{\mathcal{C}}(E):= P(E,\interior{\mathcal{C}})= \hausdorff^{n-1}(\partial^*E \setminus\partial \mathcal{C})$ denotes the relative perimeter in $\mathcal{C}$.

    The strong isoperimetric inequality in convex cones will bound from above the following the natural notion of oscillation asymmetry
    \[
        \mu_{\mathcal{C}}^2(E) := \inf\left\{
        \frac{1}{2 s_E^{n-1}} \int_{\partial^* E \cap\interior{\mathcal{C}}} \left| \nu_E(x) - \frac{x-(x',0)}{|x-(x',0)|} \right|^2 \de \hausdorff^{n-1} (x) \st x' \in \R^m \right\},
    \]
    where $\nu_E$ as usual denotes the generalized outer unit normal to $E$, and $s_E=(|E|/|K_{\mathcal{C}}|)^{1/n}$.
    Similarly to what we did in \cref{sec:capillarity}, for technical reasons it will be convenient to introduce an asymmetry index that is not translation, nor it is scaling invariant:
    \[
        \mu_{\mathcal{C},0}^2(E) := \frac{1}{2} \int_{\partial^* E \cap\interior{\mathcal{C}}} \left| \nu_E(x) - \frac{x}{|x|} \right|^2 \de \hausdorff^{n-1} (x).
    \]
\end{definition}


\begin{lemma}\label{lemma:mu-C-alternative}
    Let $\mathcal{C}\subset \R^n$ be a closed cone with non-empty interior. Then, for any measurable set $E\subset \mathcal{C}$ with finite volume there holds
    \[
        \mu_{\mathcal{C},0}^2(E) = P_{\mathcal{C}}(E)-\int_E\frac{n-1}{|x|}\de x.
    \]
\end{lemma}

\begin{proof}
    The proof is a simplified version of \cref{lem:RiscritturaDiMuLambdaZero}. It is sufficient to apply the divergence theorem to the vector field $X=\frac{x}{|x|}$, observing that $\Braket{X ,\nu_E}=0$ on $\partial^*E \cap \partial^* \mathcal{C}$.
\end{proof}

    As mentioned in the introduction, in \cite{FigalliIndrei} the authors proved the following sharp quantitative isoperimetric inequality for the isoperimetric problem in convex cones.    
    \begin{theorem}[{\cite[Theorem 1.2]{FigalliIndrei}}]\label{thm:QuantitativeConesFraenkel}
    Let $\mathcal{C}\subset \R^n$ be a closed convex cone with non-empty interior. Then there exists $C_{\ref{thm:QuantitativeConesFraenkel}}=C_{\ref{thm:QuantitativeConesFraenkel}}(\mathcal{C})>0$ such that the following holds.\\
    Let $E\subset \mathcal{C}$ be a measurable set with $|E| \in (0,+\infty)$. Then
    \begin{equation*}
    %\label{eq:QuantitativeConesFraenkel}
        \alpha^2_{\mathcal{C}}(E) \le C_{\ref{thm:QuantitativeConesFraenkel}} D_{\mathcal{C}}(E).
    \end{equation*}
    \end{theorem}
    It is known from \cite{FigalliIndrei} that $C_{\ref{thm:QuantitativeConesFraenkel}}=C_{\ref{thm:QuantitativeConesFraenkel}}(\mathcal{C})$ is a constant depending on the geometry of $\mathcal{C}$, and a careful reading of \cite{FigalliIndrei} allows to detect such a dependence. For this reason, in the rest of the work we will keep track of the dependence of newly defined constants on $C_{\ref{thm:QuantitativeConesFraenkel}}(\mathcal{C})$, in place of stating generic dependencies on $\mathcal{C}$.


\begin{definition}\label{def:DistanzaC1-cone}
    Let $\mathcal{C}\subset\R^n$ be a closed convex cone with non-empty interior. Let $k \in \N$ with $k\ge 1$, $\beta \in (0,1)$.
    Let $E \subset \mathcal{C}$ be a bounded open set. We say that the boundary of $E$ is a $C^{k,\beta}$-graph over $\Sigma_{\mathcal{C}}$ (or, more precisely, that $\overline{\partial E\cap \interior{\mathcal{C}}}$ is a $C^{k,\beta}$-graph over $\Sigma_{\mathcal{C}}$) if $\partial E$ is Lipschitz and if there exists a $C^{k,\beta}$-function $f:\Sigma_{\mathcal{C}}\to (0,+\infty)$ such that
    \[
     \overline{\partial E\cap \interior{\mathcal{C}}}= \{ f(x) \, x \st x \in \Sigma_{\mathcal{C}}\}.
    \]
    If the boundaries of two sets $E,F$ are $C^{k,\beta}$-graphs over $\Sigma_{\mathcal{C}}$ with respect to some functions $f,g$, we define
    \[
        \d_{C^{k,\beta}}(E,F):=\|f-g\|_{C^{k,\beta}(\Sigma_{\mathcal{C}})}.
    \]
    If $\{E_i\}_{i \in \N}, E$ have boundary given by $C^{k,\beta}$-graphs over $\Sigma_{\mathcal{C}}$, we say that $\overline{\partial E_i \cap \interior{\mathcal{C}}}$ converge to $\overline{\partial E \cap \interior{\mathcal{C}}}$ in $C^{k,\beta}$ (or, simply, that $E_i$ converge to a $E$ in $C^{k,\beta}$) if $\d_{C^{k,\beta}}(E_i,E)\to 0$ as $i\to\infty$.
\end{definition}

\begin{definition}\label{def:piecewise-C2}
    Let $\mathcal{C}\subset \R^n$ be a closed convex cone. We say that it is piecewise $C^2$ if $\partial B_1\cap \mathcal{C}$ is a piecewise $C^2$ domain in $\S^{n-1}$.
\end{definition}



\subsection{Proof of the strong quantitative isoperimetric inequality in convex cones}

Let $\mathcal{C}=\R^m\times \widetilde{\mathcal{C}} \subset  \R^n$, where $\widetilde{\mathcal{C}}$ does not contain lines, be a closed convex cone with non-empty interior. Denoting any point $x \in \R^n$ as $x=(x',\widetilde{x})$ with $x' \in \R^m$ and $\widetilde{x} \in \R^{n-m}$, for any bounded measurable set $E\subset \mathcal{C}$ we define
\begin{equation}\label{eq:DefBaricentroConi}
    \barycenter_{\R^m} E := \frac{1}{|E|}\int_E x' \de x.
\end{equation}


\begin{proposition}[Fuglede-type estimate in cones]\label{prop:FugledeConi}
%Let $v_0, d_0>0$, $n\ge 2$, and $m \in\{0,\ldots,n-1\}$. 
%
Let $\mathcal{C}=\R^m\times \widetilde{\mathcal{C}} \subset  \R^n$ be a closed convex cone with non-empty interior, where $\widetilde{\mathcal{C}}$ does not contain lines. Suppose that $ |B_1 \cap \mathcal{C}|\ge v_0$. 
Then there exist $c_{\ref{prop:FugledeConi}}, C_{\ref{prop:FugledeConi}}, \epsilon_{\ref{prop:FugledeConi}}>0$ depending on $v_0, n, C_{\ref{thm:QuantitativeConesFraenkel}}(\mathcal{C})$ such that the following holds.

Let $E\subset \mathcal{C}$ be a bounded open set with Lipschitz boundary and volume $|E|=|K_{\mathcal{C}}|$ such that
\[
\overline{\partial E \setminus \partial \mathcal{C}} = \left\{ (1+u(x)) x \st x \in \Sigma_{\mathcal{C}}\right\},
\]
for a function $u :\Sigma_{\mathcal{C}}\to \R$ with $\|u\|_{C^1} \le \epsilon_{\ref{prop:FugledeConi}}$, where $\Sigma_{\mathcal{C}}:=  \S^{n-1} \cap \mathcal{C}$.
Then
\begin{equation*}
%\label{eq:FugledeConi}
    \mu_{\mathcal{C}}^2(E) \le
    \mu_{\mathcal{C},0}^2(E) \le
    c_{\ref{prop:FugledeConi}} \| u\|^2_{H^1(\Sigma_{\mathcal{C}})} \le C_{\ref{prop:FugledeConi}} \left( D_{\mathcal{C}}(E) + |\barycenter_{\R^m}E|^2\right).
\end{equation*}
\end{proposition}

\begin{proof}
Inequality $\mu_{\mathcal{C}}^2(E) \le \mu_{\mathcal{C},0}^2(E)$ follows by definition.
Moreover, the computations contained in the proof \cref{lem:OScillationBoundedByH1Norm} can be readily adapted to the present case. Indeed, here the domain of integration is $\Sigma_{\mathcal{C}}$ (instead of $\S^{n-1}_+$), and $w_{\lambda}$ is replaced by the constant function $1$. Hence, for $\epsilon_{\ref{prop:FugledeConi}}$ small enough, one gets the constant $c_{\ref{prop:FugledeConi}}$ such that $\mu_{\mathcal{C},0}^2(E) \le c_{\ref{prop:FugledeConi}} \| u\|^2_{H^1(\Sigma_{\mathcal{C}})}$.\\
So, it remains to prove the bound of $\|u\|_{H^1}^2$ from above in terms of $D_{\mathcal{C}}(E)+|\barycenter_{\R^m} E|^2$. One can go through the expansion of the perimeter performed in \cref{prop:EspansionePlambda}, observing that all the computations leading to \eqref{eq:zzExpansion1} hold pointwise. Also, here the identity \eqref{eq:zzExpansion2}, which imposes the volume constraint, is replaced with
    \begin{equation}\label{eq:volumeCone}
        \int_{\Sigma_{\mathcal{C}}}\frac{1}{n}=|K_{\mathcal{C}}|=|E|=\int_{\Sigma_{\mathcal{C}}}\frac{(1+u)^n}{n} = \int_{\Sigma_{\mathcal{C}}}\frac{1}{n}+u+\frac{n-1}{2}u^2+O(u^3).
    \end{equation}
Thus $\int_{\Sigma_{\mathcal{C}}}u = -\frac{n-1}{2}\int_{\Sigma_{\mathcal{C}}}u^2+O(u^3)$. Hence using the (significantly easier) computations with $w_{\lambda}$ replaced by $1$ leading to \eqref{eq:zzExpansion1} we obtain that
    \[
        P_{\mathcal{C}}(E)-P_{\mathcal{C}}(K_{\mathcal{C}})\geq \frac{1}{2}\int_{\Sigma_{\mathcal{C}}}|\grad u|^2-(n-1)u^2+\|u\|_{C^1}\cdot O(\|u\|_{H^1}^2).
    \]
We point out that a similar expansion was obtained in \cite[Lemma~3.1]{BaerFigalli17} in a suitable different class of cones. In fact, the proof of \cite[Lemma~3.1]{BaerFigalli17} might be carried out in our setting as well.

We can now proceed as we did in \cref{prop:FugledeCapillarity}. First, using the quantitative isoperimetric inequality recalled in \cref{thm:QuantitativeConesFraenkel}, one obtains that $|E\symmdiff K_{\mathcal{C}}|\leq C(D_{\mathcal{C}}(E)^{\frac12}+|\barycenter_{\R^m}E|)$. Moreover, using a volume expansion similar to~\eqref{eq:volumeCone}, the previous estimate can be turned into $\|u\|_{L^1(\Sigma_{\mathcal{C}})}^2\leq C(D_{\mathcal{C}}(E)+|\barycenter_{\R^m}E|^2)$, which is analogous to \eqref{eq:L1-IsoperimetricDeficit}. Notice that, having applied \cref{thm:QuantitativeConesFraenkel}, the constants appearing in the last inequality only depends on $n, C_{\ref{thm:QuantitativeConesFraenkel}}(\mathcal{C})$. Finally, the conclusion is again obtained as in \cref{prop:FugledeCapillarity}, using the Nash-type inequality in \cref{lemma:NashIneq} with a parameter $\delta$ small enough. The resulting constant will depend on $v_0, n, C_{\ref{thm:QuantitativeConesFraenkel}}(\mathcal{C})$. Indeed the constant in the Nash-type inequality depends only on the dimension and on a lower bound on $\hausdorff^{n-1}(\Sigma_{\mathcal{C}})$, which is uniformly bounded from below away from zero in terms of $n,v_0$; also, the choice of the parameter $\delta$ to plug into the Nash-type inequality depends only on the constants appearing in the proof.
\end{proof}

The next lemma is an easy exercise and it is analogous to \cref{lem:ProblemPlambda+LambdaVolumi}.

\begin{lemma}\label{lem:ProblemCone+LambdaVolumi}
Let $\mathcal{C}=\R^m\times \widetilde {\mathcal C}\subset \R^n$ be a closed convex cone with non-empty interior and such that $\widetilde{\mathcal{C}}\subset \R^{n-m}$ does not contain lines. Then for any $\bar\Lambda>n$ there holds
\begin{equation*}\label{eq:ProblemCone+LambdaVolumi}
    \inf\left\{
        P_{\mathcal{C}}(E) + \bar\Lambda \left| |E| - |K_{\mathcal{C}}| \right| \st E \subset \mathcal{C}, \,\, |E|<+\infty
    \right\} = P_{\mathcal{C}}(K_{\mathcal{C}}),
\end{equation*}
and the infimum is only achieved by  $K_{\mathcal{C}} + x'$ for any $x'\in\R^m$.
\end{lemma}

% \begin{proof}
%     By the isoperimetric inequality in convex cones we can restrict ourselves to consider rescalings of $K_\mathcal{C}$.
%     Hence we need to minimize the function \begin{equation*} [0, +\infty) \ni r \mapsto P_\mathcal{C}(rK_{\mathcal{C}}) + \bar\Lambda ||rK_\mathcal{C}| - |K_\mathcal{C}|| = |K_\mathcal{C}|(nr^{n - 1} + \bar\Lambda |r^n - 1|). \end{equation*}
%     To show that $r = 1$ uniquely minimizes the above function, it is sufficient to consider $r \in [0, 1)$.
%     Since $\bar\Lambda > n$, we have \begin{equation*} nr^{n - 1} + \bar\Lambda|r^n - 1| = n r^{n - 1} + \bar\Lambda(1 - r^n) > n(r^{n - 1} + 1 - r^n) > n. \end{equation*}
% \end{proof}

We now collect some considerations analogous to those in \eqref{eq:PreConvention}--\eqref{eq:Convention}. For any $k\geq4$ and for any set of finite perimeter $F\subset \mathcal{C}$ with $|F|<+\infty$ we have that
\begin{equation}\label{eq:cone-PreConvention}
    P_{\mathcal{C}}(F)-\frac{1}{k}\mu_{\mathcal{C},0}^2(F)\geq P_{\mathcal{C}}(F)-\frac{2}{k}P_{\mathcal{C}}(F)\geq \frac{1}{2}P_{\mathcal{C}}(F),
\end{equation}
and thus we set $P_{\mathcal{C}}(F)-\frac{1}{k}\mu_{\mathcal{C},0}^2(F)=+\infty$ whenever $P_{\mathcal{C}}(F)=+\infty$ and $k\geq 4$.

Moreover, similarly to what we did in~\eqref{eq:AlternativeBarycenter}, it is convenient to also introduce the following related quantity that is well-defined for any set $F\subset \mathcal{C}$ with finite measure:
\begin{equation}\label{eq:DefBaricentroTILDEconi}
    \widetilde b_{\R^m}(F) = \int_F (\psi(x_1),\ldots,\psi(x_m))\de x,
\end{equation}
where $\psi$ was defined in \eqref{eq:DefPSI}.

\begin{proposition}\label{prop:selection-cones}
    Let $\mathcal{C}=\R^m\times\widetilde{\mathcal{C}}\subset\{x_n\geq0\}$ be a piecewise $C^2$ closed convex  cone, where $\tilde{\mathcal{C}}$ does not contain lines. Suppose $|B_1 \cap \mathcal{C}| \ge v_0$, for some $v_0>0$. 
    Then there exist $\Lambda_{\ref{prop:selection-cones}}>2n$, $R_{\ref{prop:selection-cones}}\geq 10$, $\Lambda_{\ref{prop:selection-cones}}'>0$, $ r'_{\ref{prop:selection-cones}}\in(0,1)$,
    depending on $n, v_0, C_{\ref{thm:QuantitativeConesFraenkel}}(\mathcal{C})$,
    and
    $k_{\ref{prop:selection-cones}}>4$, depending on $n, v_0, C_{\ref{thm:QuantitativeConesFraenkel}}(\mathcal{C}), \delta_{\ref{thm:almost-regularity-cones}}(\mathcal{C}, \Lambda_{\ref{prop:selection-cones}}', r'_{\ref{prop:selection-cones}} , \epsilon_{\ref{prop:FugledeConi}})$,
    such that the following holds. For any $k\geq k_{\ref{prop:selection-cones}}$, $k\in\N$, the minimization problem
    \begin{equation*}
    %\label{eq:auxiliary-problem-cone}
        \inf \left\{
    \mathcal{G}_k(F) :=
        P_{\mathcal{C}}(F)+\Lambda_{\ref{prop:selection-cones}} \left||F|-|K_{\mathcal{C}}|\right|-\frac{1}{k}\mu_{\mathcal{C},0}^2(F)+|\widetilde{b}_{\R^m}(F)|^2
        \st 
        F\subset \mathcal{C}, \,\, |F|<+\infty
    \right\}
    \end{equation*}
    has an open minimizer $F_k$ such that
    \begin{itemize}
    \item $F_k$ is a $(\Lambda_{\ref{prop:selection-cones}}', r'_{\ref{prop:selection-cones}})$-almost minimizer of the perimeter in $\mathcal{C}$,

    \item $F_k \subset B_{R_{\ref{prop:selection-cones}}}(0)\cap \mathcal{C}$,

     \item $|F_k|= |K_{\mathcal{C}}|$ for any $k\ge k_{\ref{prop:selection-cones}}$,

     \item $\overline{\partial F_k \cap \interior{\mathcal{C}}}$ is a $C^{1, \beta_{\ref{thm:almost-regularity-cones}}(\mathcal{C})}$-graph over $\Sigma_{\mathcal{C}}$ for any $k\ge k_{\ref{prop:selection-cones}}$, and $\overline{\partial F_k \cap \interior{\mathcal{C}}} \to \overline{\partial K_{\mathcal{C}} \cap \interior{\mathcal{C}}}$ in $C^{1,\beta}$, for any $\beta \in (0,\beta_{\ref{thm:almost-regularity-cones}}(\mathcal{C}))$, as $k\to \infty$, in the sense of \cref{def:DistanzaC1-cone}.\\
     Additionally, we have that $\|u_k\|_{C^{1, \beta_{\ref{thm:almost-regularity-cones}}(\mathcal{C})}(\Sigma_{\mathcal{C}})}<\epsilon_{\ref{prop:FugledeConi}}$ for every $k\geq k_{\ref{prop:selection-cones}}$.    
\end{itemize}
\end{proposition}

\begin{proof}
    The proof is very similar to that of \cref{prop:MinimizationProblemSelection} (which actually presents further complications), thus we only emphasize here the main differences.
    %Analogously to that situation, we identify the conditions that we need on the parameters along the proof, but one should think about them as fixed quantities for our purposes. 
    Let $\Lambda> 2n$ and let $k \in \N$ with $k>4$. We will fix $\Lambda=\Lambda_{\ref{prop:selection-cones}}$ at the end of the proof.
    As in \cref{prop:MinimizationProblemSelection}, we can use Ekeland's variational principle (recalled in \cref{thm:Ekeland}) in the metric space $\mathbb X = \{F\subset \mathcal{C}:|F|<+\infty\}$ endowed with the $L^1$ distance. Therefore, one finds a sequence of sets $E_j^k\subset\mathcal{C}$ such that
    \begin{equation}\label{eq:ekeland-set-cone}
    \begin{split}
        \mathcal{G}_k(E_j^k)&\le \min\left\{ \inf \left\{
    \mathcal{G}_k(F) 
        \st 
        F\subset \mathcal{C}, \,\, |F|<+\infty
    \right\} 
    + \frac1j
    , \mathcal{G}_k(K_{\mathcal{C}}) \right\}, \\
    \mathcal{G}_k(E_j^k)  &\le \mathcal{G}_k(G) + \frac1j |G \Delta E_j^k|, 
    \end{split}
    \end{equation}
    for any $G\subset\mathcal{C}$ with finite measure. 
    First we show that $E_j^k$ is a $(K_{\ref{prop:selection-cones}},r_{\ref{prop:selection-cones}})$-quasi-minimizer of the perimeter in $\mathcal{C}$, where $K_{\ref{prop:selection-cones}}>0, r_{\ref{prop:selection-cones}} \in(0,1)$ depend only on $n$ and $v_0$.
    Exactly as in \eqref{eq:MassMinimizingSeqCloseToBlambda}, one can see that $\tfrac{|E_j^k|}{|K_{\mathcal{C}}|}\in\left(\frac{1}{2}, \frac{3}{2}\right)$. 
    Let now $x_0\in\mathcal{C}$, and $G\subset\mathcal{C}$ be a set of finite perimeter such that $G\symmdiff E_j^k\Subset B_r(x_0)$ for some $r\le r_{\ref{prop:selection-cones}}$ which we should take small enough. 
    Condition~\eqref{eq:ekeland-set-cone} gives the following estimate for any $j\geq 1$
    \begin{equation*}
    %\label{eq:quasi-min-cone}
    \begin{split}
        P_{\mathcal{C}}(E_j^k)&\leq P_{\mathcal{C}}(G)+\left(\Lambda+1\right)|G\symmdiff E_j^k|+\frac{1}{k}\left(\mu_{\mathcal{C},0}^2(E_j^k)-\mu_{\mathcal{C},0}^2(G)\right)+|\widetilde b_{\R^m}(G)|^2-|\widetilde b_{\R^m}(E_j^k)|^2\\
        &\leq P_{\mathcal{C}}(G)+\left(\Lambda+1\right)|G\symmdiff E_j^k|+\frac{1}{2k}\bigg(\int_{\partial^*E_j^k \cap \interior{\mathcal{C}}\cap B_r(x_0)}\left|\nu_{E_j^k}(x)-\frac{x}{|x|}\right|^2\de \hausdorff^{n-1}\\
        &\qquad -\int_{\partial^*G \cap \interior{\mathcal{C}}\cap B_r(x_0)}\left|\nu_{G}(x)-\frac{x}{|x|}\right|^2\de \hausdorff^{n-1}\bigg)+ C(n)|G\symmdiff E_j^k|\\
        &\leq P_{\mathcal{C}}(G)+\left(\Lambda+1+C(n)\right)\tilde C(n,v_0)rP_{\mathcal{C}}(E_j^k\symmdiff G)+\frac{2}{k}\left(P_{\mathcal{C}}(E_j^k;B_r(x_0))+P_{\mathcal{C}}(G;B_r(x_0))\right)\\
        &\leq P_{\mathcal{C}}(G)+\left(\left(\Lambda+1+C(n)\right)\tilde C(n,v_0)r+\frac{2}{k}\right)\left(P_{\mathcal{C}}(E_j^k;B_r(x_0))+P_{\mathcal{C}}(G;B_r(x_0))\right),
    \end{split}
    \end{equation*}
    where we used the following rough estimate coming from the isoperimetric inequality in $\mathcal{C}$:
    \[
    \begin{split}
        |G\symmdiff E_j^k|\leq |B_1|^{\frac1n}r|G\symmdiff E_j^k|^{\frac{n-1}{n}}\leq |B_1|^{\frac1n}r\cdot \frac{1}{n|K_{\mathcal{C}}|^{1/n}}\left(P_{\mathcal{C}}(E_j^k;B_r(x_0))+P_{\mathcal{C}}(G;B_r(x_0))\right).
    \end{split}
    \]
    Since $k>4$, choosing $r_{\ref{prop:selection-cones}}=\min\{1,(4\tilde C(n,|K_{\mathcal{C}}|)(\Lambda+1+C(n)))^{-1}\}$ we deduce that $E_j^k$ is a $(K_{\ref{prop:selection-cones}},r_{\ref{prop:selection-cones}})$-quasi-minimizer of the perimeter in $\mathcal{C}$ with $K_{\ref{prop:selection-cones}}=7$. Therefore, we apply \cref{thm:quasi-regularity} to get the density estimates: there exist $D_{\ref{prop:selection-cones}},\rho_{\ref{prop:selection-cones}}\in(0,1)$, depending on $n, v_0$, such that for every $k>4$, every $j\geq 1$, every radius $\rho\in(0,\rho_{\ref{prop:selection-cones}})$ and every point $x\in\partial E_j^k$
    \begin{equation}\label{eq:density-estimates-cone}
        |\mathcal{C}\cap E_j^k\cap B_{\rho}(x)|\geq D_{\ref{prop:selection-cones}}\rho^n, \qquad |\mathcal{C}\cap B_{\rho}(x)\setminus E_j^k|\geq D_{\ref{prop:selection-cones}}\rho^n.
    \end{equation}


    Analogously to the proof of \cref{prop:MinimizationProblemSelection}, we claim that there is $\tilde k_{\ref{prop:selection-cones}}>4$ depending on $n,v_0, C_{\ref{thm:QuantitativeConesFraenkel}}$ such that the following holds. For every subsequence $k_i\to+\infty$, with $k_i\ge \tilde k_{\ref{prop:selection-cones}}$, and any subsequence $j_i\geq k_i$, denoting by $A_i=E_{j_i}^{k_i}$, there holds
    \begin{equation}\label{eq:KeyClaimCones}
        |A_i\symmdiff K_{\mathcal{C}}|\leq \frac{ \bar  C(n,v_0, C_{\ref{thm:QuantitativeConesFraenkel}})}{\sqrt{k_i}} \quad \forall i, \qquad d_{\hausdorff}\left(\overline{\partial A_i\cap \interior{\mathcal{C}}} , \overline{\partial K_{\mathcal{C}}\cap \interior{\mathcal{C}}} \right) \le 
        \frac{C(n,v_0, C_{\ref{thm:QuantitativeConesFraenkel}}) }{k_i^{\frac{1}{2n}}}
        \quad \forall i.
    \end{equation}
    By definition of $A_i$, we have that $\mathcal{G}_{k_i}(A_i)\leq\mathcal{G}_{k_i}(K_{\mathcal{C}})$ for any $i$, and thus
    \begin{equation}\label{eq:subsub-coni}
        P_{\mathcal{C}}(A_i)+\Lambda||A_i|-|K_{\mathcal{C}}||-\frac{1}{k_i}\mu_{\mathcal{C},0}^2(A_i)+|\widetilde b_{\R^m} (A_i)|^2 \leq P_{\mathcal{C}}(K_{\mathcal{C}}),
    \end{equation}
    for any $i$.
    As $k_i> 4$, we use~\eqref{eq:cone-PreConvention} and we deduce that $P_{\mathcal{C}}(A_i)\leq 2P_{\mathcal{C}}(K_{\mathcal{C}})$. Hence, we also control the asymmetry as $\mu_{\mathcal{C},0}^2(A_i)\leq 4P_{\mathcal{C}}(K_{\mathcal{C}})$. Since $\Lambda>2n$, using the parameter $\bar\Lambda=\Lambda-n>n$ in \cref{lem:ProblemCone+LambdaVolumi}, we deduce from~\eqref{eq:subsub-coni} that
    \begin{equation}\label{eq:difference-measure}
        n||A_i|-|K_{\mathcal{C}}||\leq \frac{1}{k_i}\mu_{\mathcal{C},0}^2(A_i)\leq \frac{4P_{\mathcal{C}}(K_{\mathcal{C}})}{k_i} = \frac{4n|K_{\mathcal{C}}|}{k_i},
    \end{equation}
    for any $i$.
    Using \cref{thm:QuantitativeConesFraenkel}, rearranging the terms in~\eqref{eq:subsub-coni} and introducing the parameter $t_i=\frac{|A_i|}{|K_{\mathcal{C}}|}$, we get
    \begin{equation}\label{eq:alpha-bar}
        \frac{t_i^{\frac{n-1}{n}}P_{\mathcal{C}}(K_{\mathcal{C}})}{C_{\ref{thm:QuantitativeConesFraenkel}}}\alpha_{\mathcal{C}}^2(A_i)+|\widetilde b_{\R^m}(A_i)|^2\leq P_{\mathcal{C}}(K_{\mathcal{C}})\left(1-t_i^{\frac{n-1}{n}}\right)+\frac{4P_{\mathcal{C}}(K_{\mathcal{C}})}{k_i},
    \end{equation}
    for any $i$, where we also used the bound $\mu_{\mathcal{C},0}^2(A_i)\leq 4P_{\mathcal{C}}(K_{\mathcal{C}})$.\\
    Notice that $|t_i-1|\leq \frac{4}{k_i}$ for any $i$ thanks to~\eqref{eq:difference-measure}. Therefore, we obtain $\frac{P_{\mathcal{C}}(K_{\mathcal{C}})}{C_{\ref{thm:QuantitativeConesFraenkel}}}\alpha_{\mathcal{C}}^2(A_i)+|\widetilde b_{\R^m}(A_i)|^2\leq \frac{C(n)P_{\mathcal{C}}(K_{\mathcal{C}})}{k_i}$ for any $i$. This shows that, denoting by $x_i\in\R^m$ a point realizing $\alpha_{\mathcal{C}}(A_i)$, we get
    \[
        |A_i\symmdiff (x_i+K_{\mathcal{C}})| \leq \left|A_i\symmdiff (x_i+t_i^{1/n}K_{\mathcal{C}})\right|+\left|t_i^{1/n}K_{\mathcal{C}}\symmdiff K_{\mathcal{C}}\right|\leq \frac{C(n,C_{\ref{thm:QuantitativeConesFraenkel}})}{\sqrt{k_i}}+||A_i|-|K_{\mathcal{C}}||\leq \frac{C(n,C_{\ref{thm:QuantitativeConesFraenkel}})}{\sqrt{k_i}},
    \]
    for any $i$, where $C =C(n,C_{\ref{thm:QuantitativeConesFraenkel}})$ may change from one expression to the other.\\    
Now it can be readily checked that $|\widetilde{b}_{\R^m}(x_i + K_{\mathcal{C}})| \ge c(n,v_0) \min\{1, |x_i|\}$ for any $i$. Moreover from~\eqref{eq:alpha-bar} we also deduce that $|\widetilde b_{\R^m}(A_i)|^2\leq \frac{C(n)}{k_i}$ for any $i$. Hence
    \begin{equation*} \begin{split}
        c(n,v_0) \min\{1, |x_i|\} \le |\widetilde b_{\R^m}(A_i)| + \left| |\widetilde b_{\R^m}(x_i+K_{\mathcal{C}})| -  |\widetilde b_{\R^m}(A_i)|\right|
         &\le \frac{C(n)}{\sqrt{k_i}} + C(n) |A_i\symmdiff (x_i+K_{\mathcal{C}})|
         \\&\le \frac{C(n,C_{\ref{thm:QuantitativeConesFraenkel}})}{\sqrt{k_i}}, \end{split}
    \end{equation*}
for any $i$. 
Hence there is $\tilde k_{\ref{prop:selection-cones}}>4$ depending on $n,v_0, C_{\ref{thm:QuantitativeConesFraenkel}}$ such that the previous estimate yields an upper bound on $|x_i|$ for any $k_i \ge \tilde k_{\ref{prop:selection-cones}}$. This immediately implies that $|A_i\symmdiff K_{\mathcal{C}}|\leq \frac{ \bar C(n,v_0, C_{\ref{thm:QuantitativeConesFraenkel}})}{\sqrt{k_i}}$ for any $i$ with $k_i \ge \tilde k_{\ref{prop:selection-cones}}$.\\
We already know that the sets $A_i$ satisfy the density estimates~\eqref{eq:density-estimates-cone}. Up to decreasing $D_{\ref{prop:selection-cones}}$, depending on $n,v_0$ only, we can assume that the same density estimates hold for $K_{\mathcal{C}}$ as well.
It is then standard to prove that whenever $\sqrt{k_i}>\tfrac{ \bar C(n,v_0, C_{\ref{thm:QuantitativeConesFraenkel}})}{D_{\ref{prop:selection-cones}}\rho_{\ref{prop:selection-cones}}^n}$, then $d_{\hausdorff}(\overline{\partial A_i\cap \interior{\mathcal{C}}}, \overline{\partial K_{\mathcal{C}}\cap \interior{\mathcal{C}}} )\leq \rho_{\ref{prop:selection-cones}}$, hence    $|A_i\symmdiff K_{\mathcal{C}}|\geq D_{\ref{prop:selection-cones}}d_{\hausdorff}(\overline{\partial A_i\cap \interior{\mathcal{C}}}, \overline{\partial K_{\mathcal{C}}\cap \interior{\mathcal{C}}})^n$. Therefore
    \[
        d_{\hausdorff}(\overline{\partial A_i\cap \interior{\mathcal{C}}}, \overline{\partial K_{\mathcal{C}}\cap \interior{\mathcal{C}}})
        \leq 
        C(n,v_0, C_{\ref{thm:QuantitativeConesFraenkel}}) k_i^{-1/2n}
        \qquad 
        \text{when } \sqrt{k_i}>\tfrac{ \bar C(n,v_0, C_{\ref{thm:QuantitativeConesFraenkel}})}{D_{\ref{prop:selection-cones}}\rho_{\ref{prop:selection-cones}}^n}.
    \]
Up to updating $\tilde k_{\ref{prop:selection-cones}}$ with $\max\Big\{ \tilde k_{\ref{prop:selection-cones}}, \Big( \tfrac{ \bar C(n,v_0, C_{\ref{thm:QuantitativeConesFraenkel}})}{D_{\ref{prop:selection-cones}}\rho_{\ref{prop:selection-cones}}^n} \Big)^2 \Big\} $, the claim \eqref{eq:KeyClaimCones} follows.

\medskip


Similarly to the proof of \cref{prop:MinimizationProblemSelection}, the main claim \eqref{eq:KeyClaimCones} together with density estimates imply the existence of a radius $R_{\ref{prop:selection-cones}}=R_{\ref{prop:selection-cones}}(n,v_0, C_{\ref{thm:QuantitativeConesFraenkel}}) \ge 10$ and of an open $(K_{\ref{prop:selection-cones}}, r_{\ref{prop:selection-cones}})$-quasi-minimizer $F_k$ which solves the minimization problem for $\mathcal{G}_k$, such that $F_k \subset B_{R_{\ref{prop:selection-cones}}} (0) \cap \mathcal{C}$, for any $k \ge \tilde k_{\ref{prop:selection-cones}}$. Also, the same arguments presented above for the sets $A_i$ can be repeated for the minimizers $F_k$, leading to the estimates
\begin{equation}\label{eq:StimeQuantitativeFkConi}
        |F_k\symmdiff K_{\mathcal{C}}|\leq \frac{ \bar  C(n,v_0, C_{\ref{thm:QuantitativeConesFraenkel}})}{\sqrt{k}} , \qquad d_{\hausdorff}\left(\overline{\partial F_k\cap \interior{\mathcal{C}}} , \overline{\partial K_{\mathcal{C}}\cap \interior{\mathcal{C}}} \right) \le 
        \frac{C(n,v_0, C_{\ref{thm:QuantitativeConesFraenkel}}) }{k^{\frac{1}{2n}}},
    \end{equation}
for every $k \ge \tilde k_{\ref{prop:selection-cones}}$.

\medskip

In order to improve the estimates in \eqref{eq:StimeQuantitativeFkConi} into $C^1$-bounds, we claim that there exist $\Lambda_{\ref{prop:selection-cones}}'>0, r'_{\ref{prop:selection-cones}}\in(0,1)$ depending on  $n, v_0, C_{\ref{thm:QuantitativeConesFraenkel}}(\mathcal{C})$ such that $F_k$ is a $(\Lambda_{\ref{prop:selection-cones}}', r'_{\ref{prop:selection-cones}} )$-almost minimizer of the perimeter in $\mathcal{C}$ for any $k \ge \tilde k_{\ref{prop:selection-cones}}$.\\
This claim follows at once by combining the minimality of $F_k$, the second estimate in \eqref{eq:StimeQuantitativeFkConi}, and \cref{lemma:mu-C-alternative} (see also the proof of the analogous claim in the proof of \cref{prop:MinimizationProblemSelection}).

\medskip

Consider now the parameter $\epsilon_{\ref{prop:FugledeConi}} = \epsilon_{\ref{prop:FugledeConi}}(n, v_0, C_{\ref{thm:QuantitativeConesFraenkel}})$ given by \cref{prop:FugledeConi}. We can apply the $\eps$-regularity \cref{thm:almost-regularity-cones} on the piecewise $C^2$ cone $\mathcal{C}$, getting constants $\delta_{\ref{thm:almost-regularity-cones}}=\delta_{\ref{thm:almost-regularity-cones}}(\mathcal{C}, \Lambda_{\ref{prop:selection-cones}}', r'_{\ref{prop:selection-cones}} , \epsilon_{\ref{prop:FugledeConi}}) \in(0,1)$ and $\beta_{\ref{thm:almost-regularity-cones}}(\mathcal{C}) \in (0,1/2)$. Now for $k \ge \hat k_{\ref{prop:selection-cones}} := \max\{ \tilde k_{\ref{prop:selection-cones}} , \bar C( n,v_0, C_{\ref{thm:QuantitativeConesFraenkel}})^2 / \delta_{\ref{thm:almost-regularity-cones}}^2 \} $, the first inequality in \eqref{eq:StimeQuantitativeFkConi} implies that $|F_k \Delta K_{\mathcal{C}} |\le \delta_{\ref{thm:almost-regularity-cones}}$. Hence \cref{thm:almost-regularity-cones} implies that $\overline{\partial F_k \cap \interior{\mathcal{C}}}$ is parametrized over $\S^{n-1} \cap \mathcal{C}$ by a $C^{1, \beta_{\ref{thm:almost-regularity-cones}}}$ function $u_k$ with $\|u_k\|_{C^{1, \beta_{\ref{thm:almost-regularity-cones}}}} \le \epsilon_{\ref{prop:FugledeConi}}$.

\medskip

It only remains to prove that, up to enlarging $\hat k_{\ref{prop:selection-cones}} $ into a final number $ k_{\ref{prop:selection-cones}} $ (possibly adding further dependence on $n,v_0, C_{\ref{thm:QuantitativeConesFraenkel}} $), then $|F_k|=|K_{\mathcal{C}}|$. This claim follows exactly as in the proof of \cref{prop:MinimizationProblemSelection} by testing the minimality of $F_k$ with the rescaled set $s_kF_k$ such that $|s_kF_k|= |K_{\mathcal{C}}|$. It is also in this final passage that one fixes $\Lambda= \Lambda_{\ref{prop:selection-cones}}$ depending on  $n,v_0, C_{\ref{thm:QuantitativeConesFraenkel}} $ (see the proof of \cref{prop:MinimizationProblemSelection}).
\end{proof}


