\begin{theorem}[Strong quantitative inequality in cones]\label{thm:ConesStrongQuantitative}
Let $\mathcal{C}=\R^m\times\widetilde{\mathcal{C}}\subset\{x_n\geq0\}$ be a piecewise $C^2$ closed convex  cone, where $\tilde{\mathcal{C}}$ does not contain lines. Suppose $|B_1 \cap \mathcal{C}| \ge v_0$, for some $v_0>0$. Then there exists $ C_{\ref{thm:ConesStrongQuantitative}}>0$ depending on $n, v_0, C_{\ref{thm:QuantitativeConesFraenkel}}(\mathcal{C}), \delta_{\ref{thm:almost-regularity-cones}}(\mathcal{C}, \Lambda_{\ref{prop:selection-cones}}', r'_{\ref{prop:selection-cones}} , \epsilon_{\ref{prop:FugledeConi}})$ such that the following holds.

Let $E\subset \mathcal{C}$ be a set of finite perimeter with $|E| \in (0,+\infty)$. Then
\begin{equation*}
%\label{eq:strong-quantitative-cones}
    \mu_{\mathcal{C}}^2(E) \le C_{\ref{thm:ConesStrongQuantitative}} D_{\mathcal{C}}(E).
\end{equation*}
\end{theorem}

\begin{proof}
We claim it is possible to take 
\begin{equation*}
    C_{\ref{thm:ConesStrongQuantitative}}
    := 
    \left( 1 + \max\left\{
    k_{\ref{prop:selection-cones}} , \bar k ,
    \frac{2C_{\ref{prop:FugledeConi}}}{v_0^2},
    \frac{4C_{\ref{prop:FugledeConi}}}{n v_0}
    \right\} \right)^2
    \ge \left( 1 + \max\left\{
    k_{\ref{prop:selection-cones}} , \bar k ,
    \frac{2C_{\ref{prop:FugledeConi}}}{|K_{\mathcal{C}}|^2},
    \frac{4C_{\ref{prop:FugledeConi}}}{P_{\mathcal{C}}(K_{\mathcal{C}})}
    \right\} \right)^2,
\end{equation*}
where $\bar k = \bar k (n)>0$ is the least integer such that $\tfrac{n\omega_n}{k^2} - \tfrac1k \le - \tfrac{1}{2k}$ for any $k\ge \bar k$. 
Let $k\in\N$ be the least integer such that
\[
k \ge \max\left\{
    k_{\ref{prop:selection-cones}} , \bar k ,
    \frac{2C_{\ref{prop:FugledeConi}}}{v_0^2},
    \frac{4C_{\ref{prop:FugledeConi}}}{n\omega_n v_0}
    \right\}.
\]
We stress that $k$ will be a fixed parameter in this proof. Since the inequality is scaling invariant, it is sufficient to prove the claim for sets $E\subset\mathcal{C}$ such that  $|E|=|K_{\mathcal{C}}|$. 
Let us suppose by contradiction that there exists a set $E\subset \mathcal{C}$ with $|E| = |K_{\mathcal{C}}|$ and $k^2D_{\mathcal{C}}(E) <  C_{\ref{thm:ConesStrongQuantitative}} D_{\mathcal{C}}(E)<\mu_{\mathcal{C}}^2(E)$.
%for any $k\in\N$. 
In particular, $E\neq x'+K_{\mathcal{C}}$ for any $x'\in\R^m$.
%and for any $k\in\N$. 
Without loss of generality, we can suppose that $\tilde b_{\R^m}(E)=0$.
%for every $k\in\N$.
Similarly to the proof of \cref{thm:capillarityStrongQuantitative}, we have that 
%$D_{\mathcal{C}}(F_k)\to0$ and
    \begin{equation}\label{eq:DMuZero-cone}
        D_{\mathcal{C}}(E)<\frac{1}{k^2}\mu_{\mathcal{C}}^2(E)\leq \frac{1}{k^2}\mu_{\mathcal{C},0}^2(E).
    \end{equation}
We now apply \cref{prop:selection-cones}. We stress that in this proof we do not need the whole sequence of sets generated by \cref{prop:selection-cones}, since $k$ is fixed in this proof. Since $k\ge k_{\ref{prop:selection-cones}}$, by \cref{prop:selection-cones} there exist constants $\Lambda_{\ref{prop:selection-cones}}>2n$, $R_{\ref{prop:selection-cones}}\ge 10$ such that the auxiliary minimization problem
    \begin{equation*}
        \inf \left\{
    \mathcal{G}_k(F) :=
        P_{\mathcal{C}}(F)+\Lambda_{\ref{prop:selection-cones}} \left||F|-|K_{\mathcal{C}}|\right|-\frac{1}{k}\mu_{\mathcal{C},0}^2(F)+|\widetilde{b}_{\R^m}(F)|^2
        \st 
        F\subset \mathcal{C}, \,\, |F|<+\infty
    \right\}
    \end{equation*}
    admits an open minimizer $F \subset B_{R_{\ref{prop:selection-cones}}}(0)\cap \mathcal{C}$. Additionally $|F|=|K_{\mathcal{C}}|$ and there exists $u\in C^1(\Sigma_{\mathcal{C}})$ parametrizing $\overline{\partial F\cap \interior{\mathcal{C}}}$, with $\|u\|_{C^1}<\epsilon_{\ref{prop:FugledeConi}}$. Testing the minimality of $F$ with $E$, which satisfies $\widetilde b_{\R^m}(E)=0$ and $|E|=|K_{\mathcal{C}}|$, and using \cref{lem:ProblemCone+LambdaVolumi}, we get
     \begin{equation}\label{eq:energy-comparison-FE-cone}
    \begin{split}
        P_{\mathcal{C}}(F)-\frac{1}{k}\mu_{\mathcal{C},0}^2(F)+|\widetilde{b}_{\R^m} (F)|^2
        &=P_{\mathcal{C}}(F)+\Lambda_{\ref{prop:selection-cones}} \left||F|-|K_{\mathcal{C}}|\right|-\frac{1}{k}\mu_{\mathcal{C},0}^2(F)+|\widetilde{b}_{\R^m} (F)|^2
        \\&\leq P_{\mathcal{C}}(E)-\frac{1}{k} \mu_{\mathcal{C},0}^2(E)\\
        &\overset{\eqref{eq:DMuZero-cone}}{\leq} P_{\mathcal{C}}(K_{\mathcal{C}})+\frac{P_{\mathcal{C}} (K_{\mathcal{C}})}{k^2}  \mu_{\mathcal{C},0}^2(E) -\frac{1}{k}\mu_{\mathcal{C},0}^2(E)\\
        &\leq P_{\mathcal{C}}(F)+\Lambda_{\ref{prop:selection-cones}} \left||F|-|K_{\mathcal{C}}|\right|+\frac{P_{\mathcal{C}} (K_{\mathcal{C}})}{k^2}  \mu_{\mathcal{C},0}^2(E)-\frac{1}{k} \mu_{\mathcal{C},0}^2(E)
        \\
        &=  P_{\mathcal{C}}(F)+\frac{P_{\mathcal{C}} (K_{\mathcal{C}})}{k^2}  \mu_{\mathcal{C},0}^2(E)-\frac{1}{k} \mu_{\mathcal{C},0}^2(E),
    \end{split}
    \end{equation}
    Since $k\geq \bar k(n)$, then
    \begin{equation*}
        \frac{P_{\mathcal{C}}(K_{\mathcal{C}})}{k^2}\mu_{\mathcal{C},0}^2(E)-\frac{1}{k}\mu_{\mathcal{C},0}^2(E) \leq -\frac{1}{2k}\mu_{\mathcal{C},0}^2(E).
    \end{equation*}
    Hence, from~\eqref{eq:energy-comparison-FE-cone} we deduce that 
    %for any $k\geq \max\{ k_{\ref{prop:selection-cones}},\bar k(n)\}$ there holds
    \begin{equation}\label{eq:mu-btilde-cone}
        0<\mu_{\mathcal{C},0}^2(E)\leq 2\mu_{\mathcal{C},0}^2(F),\qquad |\widetilde b_{\R^m}(F)|^2\leq \frac{1}{k}\mu_{\mathcal{C},0}^2(F).
    \end{equation}
    Since $|F|=|K_{\mathcal{C}}|$, using the first and third lines in~\eqref{eq:energy-comparison-FE-cone} we obtain
    \[
        D_{\mathcal{C}}(F)\leq \frac{\mu_{\mathcal{C},0}^2(F)}{k\cdot P_{\mathcal{C}}(K_{\mathcal{C}})}.
    \]
    Since $\|u\|_{C^1}<\epsilon_{\ref{prop:FugledeConi}}$, we can apply \cref{prop:FugledeConi} to continue this estimate as
    \begin{equation}\label{eq:arew}
        D_{\mathcal{C}}(F)\leq \frac{\mu_{\mathcal{C},0}^2(F)}{k\cdot P_{\mathcal{C}}(K_{\mathcal{C}})}\leq \frac{1}{k\cdot P_{\mathcal{C}}(K_{\mathcal{C}})}C_{\ref{prop:FugledeConi}}\left(D_{\mathcal{C}}(F)+|\barycenter_{\R^m} F|^2\right).
    \end{equation}
    Moreover, since $|F|=|K_{\mathcal{C}}|$ and $F\subset B_{10}(0)$, hence $\barycenter_{\R^m} F=|K_{\mathcal{C}}|^{-1}\widetilde b_{\R^m}(F)$. Therefore, using~\eqref{eq:mu-btilde-cone} and \cref{prop:FugledeConi} again we get that
    \[
        |\barycenter_{\R^m}F|^2\leq \frac{1}{k|K_{\mathcal{C}}|^2}\mu_{\mathcal{C},0}^2(F)\leq \frac{C_{\ref{prop:FugledeConi}}}{k|K_{\mathcal{C}}|^2}\left(D_{\mathcal{C}}(F)+|\barycenter_{\R^m}F|^2\right).
    \]
    Since $k\geq \frac{2C_{\ref{prop:FugledeConi}}}{|K_{\mathcal{C}}|^2}$ we see that $|\barycenter_{\R^m}F|^2\leq D_{\mathcal{C}}(F)$. Plugging this inequality in~\eqref{eq:arew}, since $k\geq \frac{4C_{\ref{prop:FugledeConi}}}{P_{\mathcal{C}}(K_{\mathcal{C}})}$, we deduce that $D_{\mathcal{C}}(F)\leq \frac{1}{2}D_{\mathcal{C}}(F)$. Hence, $D_{\mathcal{C}}(F) = 0$. Recalling that $|F|=|K_{\mathcal{C}}|$ and $|\barycenter_{\R^m}F|^2\leq D_{\mathcal{C}}(F)$, then $F=K_{\mathcal{C}}$, contradicting the first estimate in~\eqref{eq:mu-btilde-cone}.
\end{proof}

