\subsection{Strong quantitative inequalities with barycentric asymmetry in cones}

As discussed in \cref{sec:BarycentricCapillarity} in the case of capillarity problems, and by the very same reasons, our approach also allows to derive barycentric versions of quantitative isoperimetric inequalities in convex cones. Here, splitting $\R^n=\R^m\times \R^{n-m}$ as usual, we introduce the $\R^m$-diameter of a set, defined as the diameter of the orthogonal projection of a set on $\R^m$, and denoted by $\diam_{\R^m}E:=\diam(\pi_{\R^m}(E))$. We thus obtain the following result.

\begin{corollary}[Barycentric strong quantitative inequalities in cones]\label{cor:barycentric-ineq-cones}
    Let $\mathcal{C}=\R^m\times\widetilde{\mathcal{C}}\subset\{x_n\geq0\}$ be a piecewise $C^2$ closed convex  cone, where $\tilde{\mathcal{C}}$ does not contain lines. Suppose $|B_1 \cap \mathcal{C}| \ge v_0$, for some $v_0>0$. Then there exists $ C_{\ref{cor:barycentric-ineq-cones}}>0$ depending on $n, v_0, C_{\ref{thm:QuantitativeConesFraenkel}}(\mathcal{C}), \delta_{\ref{thm:almost-regularity-cones}}(\mathcal{C}, \Lambda_{\ref{prop:selection-cones}}', r'_{\ref{prop:selection-cones}} , \epsilon_{\ref{prop:FugledeConi}})$ such that the following holds.

    Let $E\subset \mathcal{C}$ be a set of finite perimeter with $|E|=|K_{\mathcal{C}}|$, and let $x^*\in\R^m$ be any point such that $\widetilde{b}_{\R^m}(E-x^*)=0$. Then
    \begin{equation}\label{eq:BaricentricaConiConBtilde}
        |E\symmdiff(K_{\mathcal{C}}+x^*)|^2+\int_{\partial^*E\cap \interior{\mathcal{C}}}\left|\nu_E(x)-\frac{x-x^*}{|x-x^*|}\right|^2d\hausdorff^{n-1}_x \le C_{\ref{cor:barycentric-ineq-cones}} D_{\mathcal{C}}(E).
    \end{equation}
    If $d=\diam_{\R^m}E<+\infty$, then there exists a constant $C_{\ref{cor:barycentric-ineq-cones}}'>0$     
    depending on $n$, $v_0$, $C_{\ref{thm:QuantitativeConesFraenkel}}(\mathcal{C})$, $\delta_{\ref{thm:almost-regularity-cones}}(\mathcal{C}, \Lambda_{\ref{prop:selection-cones}}',$ $r'_{\ref{prop:selection-cones}},$ $\epsilon_{\ref{prop:FugledeConi}})$, $d$
    such that
    \[
        |E\symmdiff(K_{\mathcal{C}}+\barycenter_{\R^m}E)|^2+\int_{\partial^*E\cap \interior{\mathcal{C}}}\left|\nu_E(x)-\frac{x-\barycenter_{\R^m}E}{|x-\barycenter_{\R^m}E|}\right|^2d\hausdorff^{n-1}_x\leq C_{\ref{cor:barycentric-ineq-cones}}'D_{\mathcal{C}}(E).
    \]
\end{corollary}



