\section{Cornerstones in Calculus of Variations}\label{AppendixA}

\subsection{Regularity theory}

In this work, we exploit results in regularity theory for sets satisfying two possible weak notions of perimeter minimality. The first and weaker one is the notion of $(K,r_0)$-quasi-minimaly.

\begin{definition}\label{def:quasiminimizer}
Let $\mathcal{C}\subset \R^n$ be a closed convex cone with non-empty interior ${\rm int}(\mathcal{C})$. Let $K\ge 1, r_0>0$. A set $E\subset \mathcal{C}$ of locally finite perimeter is a $(K,r_0)$-quasi-minimizer in $\mathcal{C}$ if
    \[
        P(E, B_r(x)\cap {\rm int}(\mathcal{C}))\leq K P(G, B_r(x)\cap {\rm int}(\mathcal{C})),
    \]
for any set $G \subset \mathcal{C}$ such that $G\Delta E \Subset B_r(x)$ for some $r \le r_0$ and some $x \in \mathcal{C}$.
\end{definition}

It is well-known that $(K,r_0)$-quasi-minimizers satisfy density estimates.

\begin{theorem}\label{thm:quasi-regularity}
Let $\mathcal{C}\subset \R^n$ be a closed convex cone with non-empty interior, and let $E\subset \mathcal{C}$ be a $(K,r_0)$-quasi-minimizer in $\mathcal{C}$. Denote $v_0:= \inf_{x \in \mathcal{C}} |\mathcal{C} \cap B_1(x)| $.

Then $E$ has an open representative. Moreover, there exist $\rho_{\ref{thm:quasi-regularity}}>0$, $D_{\ref{thm:quasi-regularity}} \in(0,1)$ depending on $n, K, r_0, v_0$ such that, identifying $E$ with its open representative, there holds
\[
|\mathcal{C}\cap E \cap B_\rho(x)| \ge D_{\ref{thm:quasi-regularity}} \rho^n 
\qquad
\forall\, \rho \le \rho_{\ref{thm:quasi-regularity}}, \, x \in \overline{E}
\]
and
\[
|\mathcal{C}\cap B_\rho(x) \setminus E| \ge D_{\ref{thm:quasi-regularity}} \rho^n
\qquad
\forall\, \rho \le \rho_{\ref{thm:quasi-regularity}}, \, x \in \partial E.
\]
\end{theorem}

A proof of \cref{thm:quasi-regularity} holding in the higher generality of PI spaces can be found in \cite[Theorem 4.2]{ShanmugalingamQuasiminimizers}. Observe that in \cite{ShanmugalingamQuasiminimizers}, the perimeter functional automatically coincides with the relative perimeter in ${\rm int}(\mathcal{C})$, hence the definition of quasiminimal set in \cite[Definition 3.1]{ShanmugalingamQuasiminimizers} coincides with our \cref{def:quasiminimizer}. Alternatively, a proof of \cref{thm:quasi-regularity} follows by adapting the proof of \cite[Theorem 21.11]{MaggiBook} working with $(K,r_0)$-quasi-minimal sets.

\bigskip

The second and stronger notion of generalized perimeter minimizer is that of $(\Lambda, r_0)$-almost minimizer, that we introduce here in the context of weighted anisotropic perimeter functionals. We first recall the definition of elliptic integrands as given in \cite[Definition~1.1]{DePhilippisMaggi2015}.

\begin{definition}\label{def:unif-elliptic-perimeter}
    Given an open set $\Omega\subset \R^n$, we say that $\Phi:\overline \Omega\times \R^n\to[0,+\infty]$ is an elliptic integrand on $\Omega$ if it is lower semicontinuous, $\Phi(x,\cdot)$ is convex, and $\Phi(x,t\nu) = t\Phi(x,\nu)$ for every $x\in \overline \Omega$, $\nu\in\R^n$, $t\geq 0$.

    If $\Phi$ is an elliptic integrand and $E\subset \Omega$ is a set of locally finite perimeter in $\Omega$, then we define the associated perimeter
    \[
        P_{\Phi}(E,A)\coloneqq\int_{A\cap \partial^*E}\Phi(x,\nu_E(x))\de\hausdorff^{n-1}(x), 
    \]
    for any open set $A\subset \Omega$.
    Given $\kappa_1\geq 1$ and $\kappa_2\geq 0$, we say that $\Phi$ is a regular elliptic integrand on $\Omega$ with ellipticity constant $k_1$ and Lipschitz constant $k_2$, denoted by
    \[
    \Phi \in \mathcal{E}(\Omega, k_1, k_2),
    \]
    if $\Phi(x,\cdot)\in C^{2,1}(\S^{n-1})$ for every $x\in\overline \Omega$, and for every $x,y\in\overline \Omega$ and $\nu_1,\nu_2\in\S^{n-1}$ there holds
    \begin{equation*}
    \begin{split}
        &\frac{1}{\kappa_1}\leq \Phi(x,\nu_1)\leq \kappa_1,\\
        &|\Phi(x,\nu_1)-\Phi(y,\nu_1)|+|\grad \Phi(x,\nu_1)-\grad\Phi(y,\nu_1)|\leq \kappa_2|x-y|,\\
        &|\grad\Phi(x,\nu_1)|+\|\grad^2\Phi(x,\nu_1)\|+\frac{\|\grad^2\Phi(x,\nu_1)-\grad^2\Phi(x,\nu_2)\|}{|\nu_1-\nu_2|}\leq \kappa_1,\\
        &\Braket{\grad^2\Phi(x,\nu_1)\nu_2, \nu_2 } \geq\frac{1}{\kappa_1}|\nu_2-(\nu_2\cdot\nu_1)\nu_1|^2,
    \end{split}
    \end{equation*}
    where $\nabla\Phi$, $\nabla^2 \Phi$ here denote gradient and Hessian with respect to the $\nu$-variable.
\end{definition}

We can thus define a $(\Lambda,r_0)$-almost minimizer for a perimeter $P_\Phi$ as above.

\begin{definition}\label{def:almostminimizer}
    Let $\Omega\subset\R^n$ be an open set. Let $\Phi: \overline{\Omega}\times \R^n\to[0,+\infty]$ be an elliptic integrand on $\Omega$. 
    Let $\Lambda,r_0>0$. We say that a set $E\subset \Omega$ of locally finite perimeter is a $(\Lambda,r_0)$-almost minimizer of $P_{\Phi}$ in $\Omega$ if
    \[
        %\int_{\partial^*E\cap H^+\cap B_{r_0}(x)}1-\Braket{\nu_E,e_n}\de\hausdorff^{n-1}\leq \int_{\partial^*G\cap H^+\cap B_{r_0}(x)}1-\Braket{\nu_G,e_n}\de\hausdorff^{n-1} + \Lambda|E\symmdiff G|,
        P_{\Phi}(E, B_r(x)\cap \Omega) \leq P_{\Phi}(G , B_r (x)\cap \Omega)+\Lambda|E\symmdiff G|
    \]
    whenever $E\symmdiff G\Subset B_r(x)\cap \overline{\Omega}$ for some $r\le r_0$ and $x \in \overline{\Omega}$.

    If $\Phi(x,\nu) = |\nu|$, i.e., $P_\Phi$ coincides with the usual (relative) perimeter in $\Omega$, we will just say that $E$ is a $(\Lambda,r_0)$-almost minimizer of the perimeter in $\Omega$.
\end{definition}

It is well-understood that given a sequence of $(\Lambda,r_0)$-almost minimizers of the perimeter in $\R^n$, if such a sequence converges in $L^1$ to a smooth set, then the convergence can be improved to $C^{1,\beta}$ convergence of the topological boundaries (see \cite{MaggiBook} and references therein). The theory has been generalized  to $(\Lambda,r_0)$-almost minimizers for perimeters defined by elliptic integrands in a half-space in \cite{DePhilippisMaggi2015}. In particular, combining Theorem~3.1 and Remark~3.6 in \cite{DePhilippisMaggi2015}, one gets the following theorem, which yields convergence in $C^{1,\beta}$ up to the boundary for sequences of $(\Lambda,r_0)$-almost minimizers corresponding to a sequence of elliptic integrands with uniform ellipticity bounds.

\begin{theorem}\label{thm:almost-regularity}
Let $\Phi_k:H\times \R^n\to[0,+\infty)$ be a sequence of elliptic integrands such that there exist $l_1\ge1, l_2>0$ such that $\Phi_k \in \mathcal{E}(H^+, l_1, l_2)$ for any $k$. Suppose also that $\Phi_k$ converges to an elliptic integrand $\Phi$ in $C^3_{\rm loc}(H \times \S^{n-1})$ as $k\to\infty$.

Let $\Lambda, r_0>0$. For any $k\in\N$, let $E_k\subset H$ be a $(\Lambda,r_0)$-almost minimizer of $P_{\Phi_k}$ in $H^+$, and assume that $E_k\to B^\lambda$ in $L^1_{\rm loc}(H)$.

Then $\overline{\partial E_k \cap H^+}$ is a hypersurface with boundary of class $C^{1,1/2}$ for $k$ large enough, and $\overline{\partial E_k \cap H^+}\to \overline{\partial B^\lambda \cap H^+}$ in $C^{1,\beta}$ for any $\beta \in(0,1/2)$, in the sense of \cref{def:DistanzaC1}.
\end{theorem}

In the second part of the work, we also need to apply an analogous $\eps$-regularity theorem for $(\Lambda, r_0)$-almost minimizers of the perimeter in convex cones. Assuming that the boundary of a convex cone is piecewise $C^2$, one can apply the theory developed in \cite{EdelenLi22} to derive the following result (see also \cite{GruterJost86} for earlier $\eps$-regularity results in the free boundary context).

\begin{theorem}\label{thm:almost-regularity-cones}
Let $\mathcal{C}\subset\R^n$ be a closed convex cone with non-empty interior, and suppose that $ \S^{n-1} \cap \mathcal{C}$ has piecewise $C^2$ boundary. Let $\Lambda\geq0$, $r_0, \eps>0$. Then there exist $\delta_{\ref{thm:almost-regularity-cones}}= \delta_{\ref{thm:almost-regularity-cones}}(\mathcal{C}, \Lambda, r_0, \eps)\in(0,1)$ and $\beta_{\ref{thm:almost-regularity-cones}}=\beta_{\ref{thm:almost-regularity-cones}}(\mathcal{C})\in(0,1/2)$ such that the following holds.

Let $E\subset \mathcal{C}$ be a $(\Lambda,r_0)$-almost minimizer of the perimeter in 
$\interior{\mathcal{C}}$ such that $|E\Delta (B_1 \cap \mathcal{C})| \le \delta_{\ref{thm:almost-regularity-cones}}$. Then there exists $u:\S^{n-1}\cap \mathcal{C}\to(-1,1)$ such that
    \[
        \overline{\partial E\cap \interior{\mathcal{C}}}=\{(1+u(x))x:x\in\S^{n-1}\cap \mathcal{C}\},
    \]
with $\|u\|_{C^{1,\beta_{\ref{thm:almost-regularity-cones}}}}\le \eps$.
%
% Let $E_k\subset \mathcal{C}$ be a sequence of $(\Lambda,r_0)$-almost minimizers of the perimeter in $\mathcal{C}^+$ such that $E_k\to K_{\mathcal{C}}:=B_1\cap \mathcal{C}$ in $L^1$.

% Then, for any $k$ large enough there exists $u_k:\S^{n-1}\cap \mathcal{C}\to(-1,1)$ such that
%     \[
%         \overline{\partial E_k\cap \interior{\mathcal{C}}}=\{(1+u_k(x))x:x\in\S^{n-1}\cap \mathcal{C}\}.
%     \]
% Moreover, there exists $\beta_{\ref{thm:almost-regularity-cones}}=\beta_{\ref{thm:almost-regularity-cones}}(\mathcal{C})\in(0,1)$ such that for any $\eps>0$ there exists $k_{\ref{thm:almost-regularity-cones}}=k_{\ref{thm:almost-regularity-cones}}(\mathcal{C},\Lambda, r_0,\eps, \{E_k\}) >0$ such that $\|u_k\|_{C^{1,\beta_{\ref{thm:almost-regularity-cones}}}}<\eps$ for any $k\ge k_{\ref{thm:almost-regularity-cones}}$.
\end{theorem}

We just give a sketch of the proof, commenting on the main observations leading to the application of the main regularity result from \cite{EdelenLi22}.

\begin{proof}
By compactness and by a covering argument, it is sufficient to prove the claimed $C^{1,\beta}$ bound just in some neighborhood of a point $p_0 \in \partial \mathcal{C} \cap \S^{n-1}$ with $|p_0|=1$. Let $\mathcal{C}_0:= \mathcal{C}-p_0$.

By the density estimates in \cref{thm:quasi-regularity}, it is standard to prove that the Hausdorff distances $d_{\hausdorff}(E, B_1\cap \mathcal{C})$, $d_{\hausdorff}(\overline{\partial E\cap \interior{\mathcal{C}}}, \S^{n-1} \cap \mathcal{C})$ are bounded from above by a dimensional power of $|E\Delta (B_1 \cap \mathcal{C})|$, up to multiplicative constant depending on $\Lambda, r_0, n, |B_1\cap \mathcal{C}|$.

By assumption, there exists $r_1>0$ such that for any $\rho \in(0,r_1]$ the set $B_2(0) \cap \partial \left( \tfrac{1}{\rho}\mathcal{C}_0 \right)$ is the boundary of a curved polyhedral cone domain modeled on some polyhedral cone domain $\Omega^{(0)}$ (independent of $\rho$) and belonging to the class $\mathcal{D}_{\frac12 \delta({\Omega^{(0)}})}(\Omega^{(0)})$, where $ \delta({\Omega^{(0)}})$ is given by \cite[Theorem 3.1]{EdelenLi22} and the terminology is as in \cite[Definition 2.1, Definition 2.5]{EdelenLi22}.

Moreover, notice that $M:= \partial^*E \cap \interior{\mathcal{C}}$ defines an integral varifold in $B_2$ with free boundary in $\interior{\mathcal{C}}$, such that furthermore $\|H_{M}^{\rm tan}\|_\infty \le \Lambda$, where notation and terminology is as in \cite[Section 2.4]{EdelenLi22}. In fact, such a claim is well-known and it follows, e.g., by an adaptation of \cite[Lemma A.2]{PascalePozzettaQuantitative}.
Hence, there is $r_2$, depending on $\Lambda$, such that for any $\rho\in(0,r_2]$, calling $M_\rho:= \tfrac{1}{\rho}(M - p_0)$, then $\|H_{M_{\rho}}^{\rm tan}\|_\infty \le \rho\Lambda \le \tfrac12 \delta({\Omega^{(0)}})$.

Taking into account all the previous observations and since $\S^{n-1} \cap \mathcal{C}$ is smooth (with piecewise $C^2$ boundary), it follows that for any $\eta$ we can fix $\delta_{\ref{thm:almost-regularity-cones}}= \delta_{\ref{thm:almost-regularity-cones}}(\mathcal{C}, \Lambda, r_0, \eta)$ and $\rho\le \min\{r_0,r_1,r_2\}$ such that the excess $E$ of the varifold $M_\rho$ considered in the Allard-type regularity theorem \cite[Theorem 3.1]{EdelenLi22} satisfies
\[
E \le \eta \le \delta({\Omega^{(0)}})^2,
\]
which yields assumption (3.1) in \cite[Theorem 3.1]{EdelenLi22}.\\
On the other hand, it follows by an easy contradiction argument that, if $\delta_{\ref{thm:almost-regularity-cones}}, \rho$ are possibly chosen smaller enough depending on $\mathcal{C}$, then $M_\rho$ also satisfies assumption (3.2) in \cite[Theorem 3.1]{EdelenLi22}. Hence we can apply \cite[Theorem 3.1]{EdelenLi22}, which implies the existence of a $C^{1, \beta_{\ref{thm:almost-regularity-cones}}}$ function $u_{p_0}$ defined in a neighborhood of $p_0$ in $\S^{n-1} \cap \mathcal{C}$ that parametrizes $\overline{\partial E \cap \interior{\mathcal{C}}}$ in a neighborhood of $p_0$. Moreover, by \cite[Theorem 3.1]{EdelenLi22}, there is $\beta_{\ref{thm:almost-regularity-cones}}\in(0,1)$ such that
\[
\|u_{p_0}\|_{C^{1,\beta_{\ref{thm:almost-regularity-cones}}}}\le C(n, c(\Omega^{(0)})) E^{\frac12} \le C(n, c(\Omega^{(0)})) \eta^{\frac12},
\]
where $c(\Omega^{(0)})$ is given by \cite[Theorem 3.1]{EdelenLi22}. Choosing $\eta = \eps^2/C(n, c(\Omega^{(0)}))^2$, the statement follows.
\end{proof}




\subsection{Ekeland's variational principle}

In the work, we also exploit the following version of the Ekeland's variational principle.

\begin{theorem}[{Ekeland's variational principle \cite[Corollary 1.4.2]{ZalinescuBOOK}}]\label{thm:Ekeland}
Let $(\mathbb{X},\d)$ be a complete metric space and let $f:\mathbb{X}\to (-\infty,+\infty]$ be a lower semicontinuous function bounded from below. Let $\eps>0$ and let $x_0\in \mathbb{X}$ be such that $f(x_0) \le  \eps + \inf_{\mathbb{X}} f$. Then, for any $s>0$ there exists $v \in \mathbb{X}$ such that
\begin{equation*}
    f(v) \le f(x_0) ,
    \qquad
    f(v) \le f(x) + \frac{\eps}{s} \d(x,v) \quad  \forall\, x \in \mathbb{X}.
\end{equation*}
\end{theorem}


