\section{Technical toolbox}\label{AppendixB}

In this appendix, we collect some elementary technical identities and estimates.

\begin{lemma}\label{lemma:formulas}
    Let $f:\S_+^{n-1}\to (0,+\infty)$ be a $C^1$ function, and let $F:\S_+^{n-1}\to\R^n$ be the embedding $F(x) = f(x)x$. 
    Denote $E := \{ x \in H \st |x| < f(x)\}$.\\    
    Then the tangential Jacobian of $F$ is given by
    \[
        J^T F = f^{n-1} \sqrt{1+\frac{|\grad f|^2
        }{f^2}}.
    \]
    In particular
    \[
    \int_{\partial E \cap H^+} g \de \hausdorff^{n-1} = \int_{\S^{n-1}_+} g(f(x) x) \,  f^{n-1} \sqrt{1+\frac{|\grad f|^2
        }{f^2}} \de \hausdorff^{n-1}(x),
    \]
    for any continuous function $g:\R^n\to\R^n$.\\
    The outer unit normal $\nu_E$ of $E$ is given by
    \[
    \nu_E(f(x)x) = \frac{f(x)x - \nabla f (x)}{( f^2(x) + |\nabla f (x)|^2)^{\frac12}},
    \]
    where $\nabla f$ is the tangential gradient of $f$ on $\S^{n-1}_+$, for any $x \in \S^{n-1}_+$.\\
    Moreover
    \[
    \int_E g = \int_{\S_+^{n-1}}\int_0^{f(x)} g(r x) \, r^{n-1}\de r \de \hausdorff^{n-1}(x) ,
    \]
    for any continuous function $g:\R^n\to\R^n$. In particular
    \[
    |E| = \int_{\S_+^{n-1}}\frac{f^n}{n}\de \hausdorff^{n-1}.
    \]
    %
    If also $f=w_{\lambda}+u$, with $u:\S_+^{n-1}\to\R$ of class $C^1$ such that $f>0$ on $\S^{n-1}_+$, then
    \[
    \begin{split}
        P_{\lambda}(E) &= \int_{\S_+^{n-1}} (1-\lambda\Braket{\nu_E,e_n})f^{n-1}\sqrt{1+\frac{|\grad f|^2}{f^2}}\de \hausdorff^{n-1}\\
        &=\int_{\S_+^{n-1}}(1-\lambda\Braket{\nu_E,e_n})(w_{\lambda}+u)^{n-1}\sqrt{1+\frac{|\grad w_{\lambda}+\grad u|^2}{|w_{\lambda}+u|^2}}\de \hausdorff^{n-1},
    \end{split}
    \]
    and
    \begin{equation}\label{eq:VolumeExpansion}
    \begin{split}
        |E| &= \int_{\S_+^{n-1}}\left[\frac{w_{\lambda}^n}{n}+w_{\lambda}^{n-1}u + \frac{n-1}{2}w_{\lambda}^{n-2}u^2+O(u^3)\right]\de \hausdorff^{n-1}(x),
    \end{split}
    \end{equation}
    as $u\to0$.
\end{lemma}

\begin{proof}
We just need to prove formulas for the tangential Jacobian of $F$ and for the unit normal $\nu_E$.
Denote $\Sigma = F(\S^{n-1}_+) = \overline{\partial E \cap H^+}$.
The differential $\d F_x: T_x\S^{n-1}_+ \to T_{F(x)}\Sigma$ of $F$ is given by
\[
\d F_x(v) = f(x) v + \Braket{\nabla f(x), v}x = \left( f(x) \iota + x \otimes \nabla f(x)
\right) v,
\]
where $\iota:T_x\S^{n-1}_+\hookrightarrow\R^n$ is the natural injection. Hence
\[
\begin{split}
    J^TF
    &= |\det ( (\d F_x)^* \circ \d F_x )|^{\frac12}
    = \left| \det \left( 
    ( f(x) \iota^* + \nabla f(x) \otimes x )
    (f(x) \iota + x \otimes \nabla f(x) )
    \right) \right|^{\frac12}.
\end{split} 
\]
The adjoint $\iota^*: \R^n \to T_x\S^{n-1}_+$ is the projection onto $T_x\S^{n-1}_+$, indeed
\[
\Braket{\iota^* w, v} = \Braket{w, \iota v} = \Braket{w, v}
=\begin{cases}
    \Braket{w,v} & w \in T_x\S^{n-1}_+, \\
    0 & w \in (T_x\S^{n-1}_+)^\perp,
\end{cases}
\]
for any $w \in \R^n$, $v \in T_x\S^{n-1}_+$. Therefore
\begin{equation*}
    \begin{split}
        J^TF
    &=\left| \det \left( 
    f^2(x)  \iota^* \iota + f(x) \, \iota^* \, x\otimes\nabla f(x) + f(x) \nabla f(x) \otimes x \, \iota + \Braket{x,x} \nabla f(x) \otimes \nabla f(x)
    \right) \right|^{\frac12}\\
    &= \left| \det \left( 
    f^2(x) \, \Id_{T_x\S^{n-1}_+} +  \nabla f(x) \otimes \nabla f(x)
    \right) \right|^{\frac12}\\
    & = \left| (f^2(x) + |\nabla f(x)|^2 ) (f^2(x))^{n-2}) \right|^{\frac12}.
    \end{split}
\end{equation*}

We now prove the formula for $\nu_E$. It is sufficient to prove that $f(x)x- \nabla f(x)$ is orthogonal to $T_{F(x)}\Sigma$ for any $x \in \S^{n
-1}_+$. Indeed, for any $v \in T_x\S^{n-1}_+$ we have
\[
\begin{split}
\Braket{\d F_x(v), f(x)x- \nabla f(x)}
&= \Braket{f(x) v + \Braket{\nabla f(x), v}x, f(x)x- \nabla f(x)} =0.
\end{split}
\]
Also, $\nu_E$ points outwards because $\Braket{\nu_E(F(x)), x}>0$ since $f(x)>0$ for any $x \in \S^{n-1}_+$.
\end{proof}

