\subsection{Relative Orbital Dynamics of Spacecraft Formation Flying Under $J_2$ Gravity Effects \cite{fehse2003automated,schweighart2002high,morgan2012swarm}}
\label{Averaged_J_2_Relative_Orbital_Parameters}
This subsection describes the orbital and relative dynamics of the satellite formation flight. For the coordinate system, we mainly used the Earth-centered inertial (ECI) system $\mathcal{I}$, an orbitally fixed coordinate system, and the Local-Vertical-Local-Horizontal frame (LVLH), a $\mathcal{O}$ system. Here, $\mathcal{O}$ is spanned by the unit vectors
$$
{\mathbf{o}_x}=\mathrm{nor}(\mathbf{r}), \quad {\mathbf{o}_y}={\mathbf{o}_z} \times {\mathbf{o}_x}, \quad {\mathbf{o}_z}=\mathrm{nor}(\mathbf{h})=\mathrm{nor}(\mathbf{r} \times \dot{\mathbf{r}})
$$
where the position vectors from the Earth's center are $\mathbf{r}$, the angular momentum vector per unit mass is $\mathbf{h}$, and the normalized function is $\mathrm{nor}(x)=x/\|x\|$.

First, we introduce a reference orbit to compensate for the time-varying $J_2$ geopotential gravity effects. A previous study introduced an artificially adjusted reference orbit such that the radius $r_{\mathrm{ref}}$ is constant, and the orbital angular vector $\omega_{\mathrm{ref}}$ coincides with the average of the satellites \cite{schweighart2002high}. Let us define the $j$-th satellite position from Earth's center as $P_j=[r_{\mathrm{ref}}+x_j;y_j;z_j]$ in the $\mathcal{O}$ frame and its orbital dynamics with a gravity gradient $\nabla U_{J 2}(P_j,i,\theta)\in\mathbb{R}^3$ \cite{schweighart2002high,morgan2012swarm} as $\ddot{P}_j=\nabla U_{J 2}(P_j,i,\theta)+d_e$ where
\begin{equation}
    \label{J2 orbital dynamics}
%\begin{aligned}
\nabla U_{J 2}=-
\begin{bmatrix}
\frac{\mu}{\|P_j\|^2}\\0\\0
\end{bmatrix}-\frac{k_{J 2}}{\|P_j\|^4}
\begin{bmatrix}
1-3 \sin ^2 i \sin ^2 \theta\\
 \sin ^2 i \sin 2 \theta\\
 \sin 2 i \sin \theta
\end{bmatrix}
%\end{aligned}
\end{equation}
where the unmodeled disturbances are $d_{e}\in\mathbb{R}^3$, such as high-order gravitational effects and unmodeled differential drag. Then, $\omega_{\mathrm{ref}}$ is computed as $\omega_{\mathrm{ref}}=
[0;0;c_+ \omega_o]$ such that
\begin{equation*}
    %\label{J2_constant}
    %\begin{aligned}
%\omega_{\mathrm{ref}}=\begin{bmatrix}0\\0\\ c_+ \omega_o\end{bmatrix}\quad\mathrm{s.t.}\quad
\omega_{\mathrm{ref}}\times \omega_{\mathrm{ref}}\times r_{\mathrm{ref}}=\int_0^{2\pi}\nabla U_{J_2(\theta)}\frac{\mathrm{d}\theta}{2\pi}
%s_{J_2}&=\frac{k_{J_2}(1+3 \cos 2 i_{\text {ref }})}{4 \mu_g r_{\mathrm{ref}}^2},\quad c_{\pm}=\sqrt{1\pm s_{J_2}}.
%=
%\begin{bmatrix}
%\frac{c_+^2\mu}{\|r_{\mathrm{ref}}\|^2} \\0\\0
%\end{bmatrix}
%\end{aligned}
\end{equation*}
where $\omega_0^2={{\mu}/{r_{\mathrm{ref}}^3}}$. Although this angular velocity adjusts the orbital period, its orbital plane is separated because of the time-varying longitudes of the ascending nodes $\Omega(t)$: $\dot{\Omega}(\theta(t))=-{2 k_{J 2} \cos i \sin ^2 \theta}/({\|\mathbf{h}\| r_{\mathrm{ref}}^3})$. To compensate for this, $\theta(t)$ is set to $\theta(t)={\omega}_{z\mathrm{ref}}t$ by using $\dot{\Omega}_{\mathrm{avg}}=\int_0^{2\pi}\dot{\Omega}(\theta)\frac{\mathrm{d}\theta}{2\pi}$ where
%\begin{equation*}
%\begin{aligned}
%{\omega}_z=c_+\omega - \int_0^{2\pi}\dot{\Omega}(\theta)\cos i\frac{\mathrm{d}\theta}{2\pi}=
%=\omega_o c_{+}-f(\delta \Omega_{jk0})-\dot{\Omega}_j \cos i \approx 
%\omega_o \left(c_{+} + \frac{k_{J_2}\cos^2i}{\mu r_{\mathrm{ref}}^{2}}\right)\\
%\end{aligned}
%\end{equation*}
\begin{equation}
\label{omega_zref}
{\omega}_{z\mathrm{ref}}=c_+\omega_o -\dot{\Omega}_{\mathrm{avg}j} \cos i_j=
%=\omega_o c_{+}-f(\delta \Omega_{jk0})-\dot{\Omega}_j \cos i \approx 
\omega_o \left(c_{+} + \frac{k_{J_2}\cos^2i}{\mu r_{\mathrm{ref}}^{2}}\right).
%\end{aligned}
\end{equation}

Next, we introduce the approximate relative orbital dynamics of the two orbiting satellites, which are useful for deriving a closed-form solution. We define the relative position of the $j$-th satellite from the $k$th satellite as ${r_{jk}}={r}_j-{r}_k=[x_{jk};y_{jk};z_{jk}]$. Then, linearization around the reference orbit yields the dynamics of the relative motion in $\{\mathcal{O}\}$ \cite{fehse2003automated,schweighart2002high}:
\begin{equation}
\label{Hill_dynamics}
\begin{aligned}
&\begin{aligned}
&\ddot{\overline{x}}-2\omega_{xy}\dot{\overline{y}}-3\omega_{xy}^2 \overline{x}-\frac{4 \omega_{xy}^2}{c_-^2/s_{J_2}}\left(2 \overline{x}+\frac{\dot{ \overline{y}}}{ \omega_{xy}}\right)=c_+(u_x+d_x) \\
& \ddot{\overline{y}}+2\omega_{xy}\dot{\overline{x}}={c_-}(u_y+d_y)\\
&\ddot{z}+\omega_z^2  z=2 l_z \omega_z \cos (\omega_z t+\theta_z)+(u_z+d_z) \\
\end{aligned}
\end{aligned}
\end{equation}
\begin{equation*}
\left\{
\begin{aligned}
&\overline{x} =c_{+} x,\quad \overline{y} = c_- y,\quad{\omega}_{xy}=c_-\sqrt{{\mu}/{r_{\mathrm{ref}}^3}},\\
&\omega_z =\omega_{z\mathrm{ref}}+f_1(\delta \dot{\Omega}_{\mathrm{avg}jk}),\ r_z \sin \theta_z=z, \\
&l_z \sin \theta_z+\omega_z r_z \cos \theta_z=\dot{z}\\
&l_z(\delta \dot{\Omega}_{\mathrm{avg}jk})=-r_{\text {ref }}\sin i_{j} \sin i_{k}f_2(\delta \dot{\Omega}_{\mathrm{avg}jk})
%&l=-r_{\text {ref }} \frac{\sin i_{j} \sin i_{k} \sin \delta \Omega_{jk0}}{\sin \Phi_{jk0}} {\delta \dot{\Omega}_{\mathrm{avg}jk}}\approx 0\\
