\subsection{Escape, Connectable, and Relaxed Connectable Time} 
\label{Escape_Connectable_Time_Relaxation}
We derived the representative times for a deputy satellite to exit from a controllable region for controller design. Based on the analytical solutions in subsection \ref{Averaged_J_2_Relative_Orbital_Parameters}, we provide the escape time $T_{\mathrm{out}}\in\mathbb{R}$, connectable time $T_{\mathrm{conn}}$, and “relaxed” connectable time $\hat{T}_{\mathrm{conn}}(C_{1,4})$. We first denote the strict definition of "escape time" and "connectable time" under the distance-based constraint.
\begin{definition}
For parameters $C_{1-6}(t_0)$ of a given relative orbit at initial time $t_0$, time $t_s=t_0+{T}_{\mathrm{out}}(C_{1-6})$ corresponds to the time when the distance between two satellites coincides with $r_s$, where
$$
{T}_{\mathrm{out}}(C_{1-6})=\left\{t_s \geq t_0\ |\ \|r(t_s)\|^2 = r_s^2 \right\}-t_0
$$
and $r(t)=[x(t),y(t),z(t)]^\top$ of the closed-form solutions in Eq.~(\ref{CWsol}). Here, the initial escape time $\underline{T}_{\mathrm{out}}(C_{1-6})=\min({T}_{\mathrm{out}})$ and final escape time $\overline{T}_{\mathrm{out}}(C_{1-6})=\max({T}_{\mathrm{out}})$ are estimated at initial time $t_0$ through the closed-form solutions as follows:
$$
\begin{aligned}
\underline{T}_{\mathrm{out}}(C_{1-6})&=\mathrm{min}\left\{t \geq t_0\ |\ \|r(t)\|^2 = r_s^2 \right\}-t_0\\
\overline{T}_{\mathrm{out}}(C_{1-6})&=\mathrm{max}\left\{t \geq t_0\ |\ \|r(t)\|^2 = r_s^2 \right\}-t_0
\end{aligned}
$$
\end{definition}
\begin{definition}
Connectable time $T_{\mathrm{conn}}(C_{1-6})$ is determined as follows:
$$
T_{\mathrm{conn}}(C_{1-6})=\sum\left\{t_0\leq t \leq \overline{T}_{\mathrm{out}}(C_{1-6})\ |\ \|r(t)\|^2 \leq r_s^2 \right\}.\\
$$
which satisfies $\underline{T}_{\mathrm{out}}\leq T_{\mathrm{conn}}\leq \overline{T}_{\mathrm{out}}$ since $\overline{T}_{\mathrm{out}}$ includes the duration for the deputy satellite to escape from the controllable region.
\end{definition} 

One drawback of these strict estimations is the computational cost associated with some numerical techniques, which can be prohibitive for online execution by small satellites. Therefore, we derive the lower bound $\hat{\underline{T}}_{\mathrm{out}}(C_{1,4},r_{xy,z})$, such that $\hat{\underline{T}}_{\mathrm{out}}(C_{1,4},r_{xy,z})\leq {\underline{T}}_{\mathrm{out}}(C_{1-6})$. We consider the following ellipse as a virtual relative trajectory $r_v(C_{1-6},t_k,\theta)$:
$$
r_v(C_{1-6},t_k,\theta)=r_{\mathrm{o}}(t_k)+
\begin{bmatrix}
   r_{xy}\sin{(\theta + \theta_{xy})}/c_+\\
    2r_{xy}\cos{(\theta + \theta_{xy})}/c_-\\
    r_z \sin{(\theta+\theta_z)}
\end{bmatrix}
$$
where the fixed time is $t_k$, arbitrary phase is $\theta \in[0,2\pi)$, and origin of the ellipse is $r_{\mathrm{o}}(t)$ in Eq.~(\ref{CWsol}). We define the coordinate transformation $C^{E/O}$ such that the ellipse lies on the $X-Y$ plane, with its minor axis aligned along the $X$-axis and the origin of the ellipse $[X_o;Y_o;Z_o]=C^{E/O}r_{\mathrm{o}}(t_k)$ as introduced in \cite{chang2011novel}. Here, to derive $\hat{\underline{T}}_{\mathrm{out}}(C_{1,4},r_{xy,z})$, we consider that the inter-satellite distance takes the maximum value. This occurs when $[1,{dY}/{dX}]^\top$ and $[1,{dY_o}/{dX_o}]^\top$ intersect orthogonally, where ${dY}/{dX}$ is the gradient of the tangent at $[X;Y]$ on the ellipse and ${dY_o}/{dX_o}$ is the vectors that joins the origin and the arbitrary point on the ellipse:
$$
\frac{dY}{dX}=-\frac{X-X_o(t_k)}{Y-Y_o(t_k)} \frac{l_\mathrm{max}^2}{l_\mathrm{min}^2},\quad\frac{dY_o}{dX_o}=\frac{Y}{X}.
$$
Therefore, we can derive the constraint of $\hat{\underline{T}}_{\mathrm{out}}$:
\begin{equation*}
\label{T_out}
%\begin{aligned}
\hat{\underline{T}}_{\mathrm{out}}(C_{1,4},r_{xy,z})=\mathrm{min}\left\{t \geq t_0\ \left|\
\begin{aligned}
&X^2+Y^2 = r_s^2\\
&1+\frac{dY}{dX}\frac{dY_o}{dX_o}=0
\end{aligned}
\right\}\right.
%\end{aligned}
\end{equation*}
This can be simplified to a cubic equation whose solutions are up to four actual points and could be provided analytically. Since this $\hat{\underline{T}}_{\mathrm{out}}(C_{1,4},r_{xy,z})$ still presents high computational costs, we define a relaxed time function in Eq.~(\ref{T_conn}).
\begin{lemma}
For a given $C_{1,4}$, consider an arbitrary $r_{s0}\in\mathbb{R}_+$ such that $r_{s0}^2\geq (2C_1)^2$ and an associated $\hat{T}_{0}(r_{s0})\geq0$. Then, the following is satisfied for $\delta C_{4}=(C_4-3\omega C_1\hat{T}_{0})$:
\begin{equation*}
\label{bound_Tconn2}
\begin{aligned}
\hat{T}_{\mathrm{conn}}(C_{1,4})
&=\hat{T}_0(r_{s0})+\frac{-|\delta C_4|+\sqrt{r_s^2-(2C_1)^2}}{\epsilon_2|C_1|}\\
\end{aligned}
\end{equation*}
\end{lemma}
\begin{proof}
Substituting Eq.~(\ref{T_conn}) into $\mathrm{sgn}(C_1\delta C_4(\hat{T}_0- \hat{T}_{\mathrm{conn}}))$ yields $-\mathrm{sgn}( \hat{T}_{0}- \hat{T}_{\mathrm{conn}})$; thus, $\mathrm{sgn}(C_1\delta C_4)\leq 0$. Applying this and $\delta C_4$ for Eq.~(\ref{T_conn}) results in Eq.~(\ref{bound_Tconn2}). 
\end{proof}
\subsection{Centralized Grouping on a Normalized Swarm Frame}
\label{two_networking_alg}
We present the criteria for the satellite grouping method based on the Normalized Swarm Frame and derive a multi-leader network $\mathcal{D}^{\mathfrak{ml}}\left(\mathcal{V}, \mathcal{E}^{\mathfrak{ml}}\right)$. To reduce computational costs, we assume that the neighboring satellites $\mathcal{N}_j$ are updated mainly by the closeness of the relative distance and remove overlapping interactions. Then, we limit $\mathcal{N}_j$ to inclusion in the Delaunay triangulation (DT) graph \cite{lee1980two,schwab2021distributed,guinaldo2024distributed}, where the edges form triangles, and the circumcircle contains no points in $\mathcal{V}$ in its interior. Here, updating DT based on the Euclid distance leads to the non-constant $\mathcal{N}_j$ since even the stable state $p_d(t)$ is periodic, as shown in Eq.~(\ref{desired_position}). Then, DT is derived by $p_d(t)$ in the $\{\hat{\mathcal{S}}\}$ frame to obtain the time-invariant $\mathcal{N}$, which leads to the convergence of the distance-based formation. In this study, we calculate DT in a centralized manner. For comparison, please refer to the decentralized DT estimation \cite{schwab2021distributed} and 3D surfaces \cite{guinaldo2024distributed} based on a given initial DT. Since the number of neighbor candidates can be larger than $\Delta$, we sort them by $\hat{T}_{\mathrm{conn}}$ and pair them with candidates presenting a small $\hat{T}_{\mathrm{conn}}$. These candidates are considered unsafe to ensure a certain amount of communication time.   

The specific centralized groping algorithm \ref{alg:Centralized_Multi_Leader_Grouping} is used to derive a multi-leader network $\mathcal{D}^{\mathfrak{ml}}\left(\mathcal{V}, \mathcal{E}^{\mathfrak{ml}}\right)$, which includes leader agent set $\mathcal{V}_l$ and edges for $j$th group $\mathcal{E}_j^{\mathfrak{ml}}$. Again, this will be replaced by an arbitrary method. We can achieve multi-leader selection through the optimization problem, such as \cite{clark2012leader}. Certain crucial points of the grouping algorithm are noted, which can ensure the stability of the distance-based control. First, multiple groups do not share a common edge for stable control allocation, i.e., the control of each edge should be realized within a single group. Second, $\overline{n}_f$ should be greater than three because the edge number of a DT is $[3(|\mathcal{V}|-1)-e(t)]$ \cite{lee1980two}, where $e(t)$ is the number of vertices on the boundary $e(t)\in[3, N]$. Third, the outer edges of the distance between neighboring satellites become non-uniform. Then, removing these connections at the outer edges of the DT under certain conditions may result in a uniform overall formation. Fourth, the edges of $\mathcal{N}$ should not cross each other to guarantee graph rigidity for convergence stability.

To ensure that the maximum value of the neighbor number remains less than or equal to $\Delta$, we define multi-leader digraph $\mathcal{D}^{\mathfrak{ml}}(\mathcal{V}, \mathcal{E}^{\mathfrak{ml}})$ to derive $\mathfrak{g}_{l}$ and edge $(j, k)\in\mathcal{E}^{\mathfrak{ml}}$ describes the hierarchical relationships of $k\in\mathcal{V}_l$ and $j\in\mathcal{V}/k$, i.e., the $j$-th satellite follows $k$-th satellite.
\begin{definition}[Multi-Leader Digraph]
\label{multi_leader_graph}
For given $\mathfrak{g}_{l}$, we define the multi-leader digraph $\mathcal{D}^{\mathfrak{ml}}(\mathcal{V}, \mathcal{E}^{\mathfrak{ml}})$ and edge $(j, k)\in\mathcal{E}^{\mathfrak{ml}}$ describes the hierarchical relationships of $k\in\mathcal{V}_l$ and $j\in\mathcal{V}/k$, i.e., the $j$-th satellite follows $k$-th one.
$$
%\begin{aligned}
\mathfrak{g}_{l}=\{l, f\in \mathcal{V}\  |\ (f, l)\in\mathcal{E}_l^{\mathfrak{ml}} \},\quad\ \mathcal{E}^{\mathfrak{ml}}=\mathcal{E}_1^{\mathfrak{ml}} \cap
\ldots \cap \mathcal{E}_{N}^{\mathfrak{ml}}
%\end{aligned}
$$
where $\mathfrak{g}_{l}=l$ and $\mathcal{E}_{l}^{\mathfrak{ml}}=\{\}$ means that the $l$th leader does not have followers. Its non-weighted, non-symmetric adjacency matrix $A(\mathcal{D}^{\mathfrak{ml}})$ is defined as follows:
$$
[A(\mathcal{D}^{\mathfrak{ml}})]_{j k}=\begin{cases}1
& \text { if }(k, j) \in \mathcal{E}^{\mathfrak{ml}} \\ 0 & \text { otherwise }\end{cases}
$$
Here, the sum of each $j$th row $\sum_{k=1}^{n} [A(\mathcal{D}^{\mathfrak{ml}})]_{jk}$ and $k$th column $\sum_{j=1}^{n} [A(\mathcal{D}^{\mathfrak{ml}})]_{jk}$ indicate the number of $j$th followers and $k$-th following, respectively:
$$
\sum_{k=1}^{n} [A(\mathcal{D}^{\mathfrak{ml}})]_{jk}\leq \overline{n}_{f\leftarrow l},\quad \sum_{j=1}^{n} [A(\mathcal{D}^{\mathfrak{ml}})]_{jk}\leq  \overline{n}_{l\leftarrow f}
$$
These bounds include $\Delta$ as a function of $\overline{n}_{l\leftarrow f},\overline{n}_{f\leftarrow l}$ %the maximum number of other satellites' interactions for arbitrary satellites:
%$$\Delta(\overline{n}_{l\leftarrow f},\overline{n}_{f\leftarrow l})\geq\max_{j\in\mathcal{V}}\sum_{(k,j)\in\mathcal{E}}1,\sum_{l\in\mathcal{V}_{l}}\sum_{(k,j)\in\mathcal{E}_l^{\mathfrak{ml}}}1,$$
e.g. $\Delta(\overline{n}_{l\leftarrow f},\overline{n}_{f\leftarrow l})=(\overline{n}_{l\leftarrow f}+1)\overline{n}_{f\leftarrow l}\ $ if $\ \overline{n}_{l\leftarrow f}=\overline{n}_{f\leftarrow l}=2$.
\end{definition}
\begin{algorithm}[tb!]
\caption{Centralized Multi-Leader Grouping for Connected Graphs or Each Connected Subgraph}
\label{alg:Centralized_Multi_Leader_Grouping}
\begin{algorithmic}[1] 
\State \textbf{Inputs: }1) $\mathcal{V}=\{1,\ldots ,N\}$, 2) ${r}_j^{\hat{s}}\in\mathbb{R}^3$ by Eq.~(\ref{conversion_for_grouping}), 3) $r_s\in\mathbb{R}$, 4) $\overline{n}_f\in\mathbb{R}$, 5) $\mathcal{V}_l=\{\}$, $\mathcal{E}_j^{\mathfrak{ml}}=\{\}$
\State \textbf{Outputs: }$\mathcal{D}^{\mathfrak{ml}}\left(\mathcal{V}, \mathcal{E}^{\mathfrak{ml}}\right)$, $\mathcal{V}_l$, $\mathcal{E}_l^{\mathfrak{ml}}$
\State Extract $\Phi(\Theta_{P},\Theta_{z-xy})$ component, ${r}_{j\mathrm{yz}}^{\hat{s}}={r}_j^{\hat{s}}(2:3)$
\State Use ${r}_{j\mathrm{yz}}^{\hat{s}}$ to make adjacency matrix $A_{\mathcal{DT}}$ and its degree matrix $D_{\mathcal{DT}}$ from Delaunay triangulation 
\State Derive index $k_{\mathrm{deg}}$ in order of degree of $D_{\mathcal{DT}}$ 
\For{$k_l=k_{\mathrm{deg}}(m_1\in[1\dots N])$}
\State Set $\mathfrak{g}_{k_l}=k_l$, add $k_l$ into $\mathcal{V}_l$, and derive index $k_{\hat{T}_{\mathrm{conn}}}$ in order of $\hat{T}_{\mathrm{conn}}^{-1}$ for $k_l$th agent
\For{$k_f=k_{\hat{T}_{\mathrm{conn}}}(m_2\in[1\dots N])$}
\If{$A_{\mathcal{DT}}(k_l,k_f)$ $\&\&$ $\|\bm{r}_{k_l}-\bm{r}_{k_f}\|\leq r_s$}
\State Add $k_f$ into $\mathrm{g}_{k_l}$
\If{size of $\mathfrak{g}_{k_l}$ is $\overline{n}_f\in\mathbb{R}$} break
\EndIf
\EndIf
\EndFor
\For{$(k_1\in g_{k_l},k_2\in g_{k_l})$}
\If{$A_{\mathcal{DT}}(k_1,k_2)$}
\State Add $(k_{1,2},k_{2,1})$ into $\mathcal{E}_{k_l}^{\mathfrak{ml}}$
\EndIf
\EndFor
\EndFor
\end{algorithmic}
\end{algorithm}
\subsection{Proof of Theorem~\ref{theorem_networked_controller}: Baseline Distance-based Orbital Stabilizer}
\begin{proof}
\label{proof_theorem_networked_controller}
We compute a smooth collective potential function $\mathcal{V}_{\mathrm{all}}\in\mathbb{R}$ as a candidate of the Lyapunov function:
\begin{equation}
\label{potential_function}
\begin{aligned}
&V_{\mathrm{all}}(t,\varrho)=
\frac{k_A}{2}
\left\|
\begin{bmatrix}
\hat{E}^\top[2C_1]\\
\sqrt{\gamma_A} E^\top [C_4-\psi C_1]
\end{bmatrix}
\right\|^2+V_{\delta}\\
&V_{\delta}=\sum_{i}\sum_{j\in\mathcal{N}_i}{k_{Bij}}\int_{\|r_{xyd}\|_\sigma}^{\|\overline{r}_{xyij}\|_\sigma}s(\mathsf{r}) \sqrt{1+\epsilon\|\mathsf{r}\|^2}\mathrm{d}\mathsf{r}
\end{aligned}
\end{equation}
where the $\sigma$-norm $\|z\|_\sigma=(\sqrt{1+\epsilon\|z\|^2}-1)/\epsilon$ with a fixed parameter $\epsilon \in(0,1)$. 
\begin{equation}
\label{drdt_2}
\begin{aligned}
\frac{\mathrm{d}\overline{r}_{xyjk}^2}{\mathrm{d}t}
=&2k_0
\begin{bmatrix}
\tau(-\varsigma +\frac{c_-}{2})C_{42}\\
(\frac{\varrho}{2}-c_+ )C_{13}+\frac{-\varsigma \psi\tau}{2}C_{42}
\end{bmatrix}
\begin{bmatrix}
U_x\\
U_y
\end{bmatrix}\\
&-2\omega_{xy}\tau\left(\frac{\epsilon_2 \varsigma}{\omega_{xy}}-\varrho\right)C_{42}^\top C_1\\
&-2\omega_{xy}C_{13}\left\{\varsigma (C_4-\psi C_1)+(\tau-1) C_{42}\right\}\\
\end{aligned}
\end{equation}
where $C_{42}=(\varsigma (C_4-\psi C_1)+C_2)$, $C_{13}=(\varrho C_1+C_3)$. Let $L_s(t)\in\mathbb{R}^{N\times N}$ be defined as a weighted Laplacian matrix: 
$$
L_{s(ij)}=\left\{
\begin{aligned}
&-k_{Bij}s(\overline{r}_{xyij}),\ &&\mathrm{if}\ j \in \mathcal{N}_i \\
&\sum_{j \in N_i}k_{Bij}s(\overline{r}_{xyij}),\ &&\mathrm{if}\ i=j \\
&0,\ &&\mathrm{else}
\end{aligned}.
\right.
$$
Then, the time derivative of $V_{\mathrm{all}}$ is
$$
\begin{aligned}
\dot{V}_{\mathrm{all}}
=&2
\begin{bmatrix}
\mathfrak{e}_4+k_1\tau \mathfrak{e}_2\\
\frac{k_A}{2}\hat{E}\hat{E}^\top[2C_1]+\frac{\psi}{2} E \mathfrak{e}_4\\
{(\frac{\varrho}{2}-c_+ )}\mathfrak{e}_3+\frac{k_1(-\varsigma \psi\tau)/{2}}{(-\varsigma +\frac{c_-}{2})}\mathfrak{e}_2
\end{bmatrix}^\top
\begin{bmatrix}
k_0 E^\top U_x\\
k_0 U_y\\
k_0 E^\top U_y
\end{bmatrix}\\
&+\frac{2\epsilon_2}{k_A}
\begin{bmatrix}
\mathfrak{e}_4\\
\mathfrak{e}_2
\end{bmatrix}^\top
\begin{bmatrix}
    1&\frac{2\omega_{xy}\varsigma}{\gamma_A \epsilon_2}\\
    \frac{c_-}{2c_+}\frac{(\frac{\varrho}{2}-\frac{\epsilon_2 \varsigma}{2\omega_{xy}})}{(-\varsigma +\frac{c_-}{2})}&O\\
\end{bmatrix}
\begin{bmatrix}
\mathfrak{e}_1\\
\mathfrak{e}_3
\end{bmatrix}\\
&+\frac{k_A}{2}
[2C_1] \left\{\frac{\mathrm{d}}{\mathrm{d}t}\left(\hat{E}\hat{E}^\top\right)\right\}[2C_1]\\
\end{aligned}
$$
where we use $\frac{\mathrm{d}\|r_{xyij}\|_\sigma}{\mathrm{d}t}=r_{xyij}\dot{r}_{xyij}/\sqrt{1+\epsilon\|\mathsf{r}_{xyij}\|^2}$, $k_1=(c_-\epsilon_2)/(4c_+\omega_{xy})$, and $\mathfrak{e}_{1,2,3,4}$ are defined as the following edge vectors:
$$
\begin{bmatrix}
    \mathfrak{e}_1\\\mathfrak{e}_3
\end{bmatrix}
=
\begin{bmatrix}
\frac{k_A}{2}E^\top [2C_1]\\    
W_sE^\top C_{13}
\end{bmatrix}
,\ 
\begin{bmatrix}
\mathfrak{e}_4\\\mathfrak{e}_2
\end{bmatrix}
=
\begin{bmatrix}   
-\frac{k_A\gamma_A }{2} E^\top[C_4-\psi C_1]\\
\frac{(-\varsigma +\frac{c_-}{2})}{k_1}W_s E^\top  C_{42}
\end{bmatrix}.
$$

We first consider our main controller $u_j$ in~(\ref{networked_input_i}) for $k_B\neq0$ and $k_B=0$. The matrix formulation of $u_j$ in~(\ref{networked_input_i}) is as follows:
$$
%\begin{aligned}
