&=2
\begin{bmatrix}
\mathfrak{e}_4+k_1\mathfrak{e}_2\\
\mathfrak{e}_1+\frac{\psi}{2}\mathfrak{e}_4\\
\left(\mathfrak{e}_4 +\mathfrak{e}_2\right)
\end{bmatrix}^\top
\begin{bmatrix}
k_0E^\top U_x\\
k_0E^\top U_y\\
\frac{\epsilon_2}{k_A}\mathfrak{e}_1
\end{bmatrix}
=-2
x^\top
\begin{bmatrix}
\gamma_B^2 L_e &
\gamma_BK_0\\
\gamma_BK_0& \gamma_B^2 L_e 
\end{bmatrix}
x
\end{aligned}
$$
where $K_0=(\frac{\lambda_0}{2} L_e-\frac{\epsilon_2}{2k_A}I)$, $x=[\mathfrak{e}_1/\gamma_B;\mathfrak{e}_4+\mathfrak{e}_2]$. Moreover, the definition of $\psi$ in Eq.~(\ref{coefficient_condition}) is the solution of 
$$
\frac{\psi}{2}\left((1-k_1)f_{0}-\frac{\psi}{2}\right)=\gamma_B \left(k_1+\frac{1}{k_1}-2\right)=\gamma_B \frac{(k_1-1)^2}{k_1}
$$ where $c\triangleq(k_1+1/k_1-2)=\frac{(k_1-1)^2}{k_1}$. The following relationship for arbitrary vectors $\mathsf{a}\in\mathbb{R}^{|\mathcal{E}|}$ and $\mathsf{b}\in\mathbb{R}^{|\mathcal{N}|}$ is then derived:  
$$
\begin{aligned}
\mathsf{a}^\top   E^\top \mathsf{b}&
%=\mathsf{a}^\top    (V\Sigma^\top U^\top )\mathsf{b}
%= \mathsf{a}^\top    (V_+\Sigma_+^\top U_+^\top) \mathsf{b}\\
= \mathsf{a}^\top    V_+(V_+^\top V_+)\Sigma_+^\top U_+^\top \mathsf{b}
= \mathsf{a}^\top V_+V_+^\top E^\top \mathsf{b}\\
\end{aligned}
$$
where $V_+\in\mathbb{R}^{\smash{|\mathcal{E}|\times |\mathcal{V}|-1}}$ in subsection~\ref{Algebraic_Graph_Theory}. By applying $\mathsf{a}=\mathfrak{e}_4 +\mathfrak{e}_2$ and $E^\top \mathsf{b}=\mathfrak{e}_1$ for the above relationship into $\dot{V}_{\mathrm{all}}$, we obtained the following:
$$
\begin{aligned}
\dot{V}_{\mathrm{all}}
&=-2\gamma_B
\hat{x}^\top
\begin{bmatrix}
\gamma_B D_+ &
\frac{\lambda_0}{2} D_+ -\frac{\epsilon_2}{2k_A}I\\
*& \gamma_B D_+ 
\end{bmatrix}\hat{x}\\
&=-\gamma_B\|V_+^\top[\mathfrak{e}_1/\gamma_B\pm (\mathfrak{e}_4+\mathfrak{e}_2)]\|^2_{P_{\pm}}
\end{aligned}
$$
where $\hat{x}=(I_2\otimes V_+^\top)x$ and $P_{\pm}\triangleq \gamma_B D_+\pm(\frac{\lambda_0}{2} D_+-\frac{\epsilon_2}{2k_A}I)$. Since the definition in Eqs.~(\ref{coefficient_condition}) and (\ref{definition_d}) guarantees $P_{\pm}\succeq 0$, we obtain $\|V_+^\top[\mathfrak{e}_1/\gamma_B\pm (\mathfrak{e}_4+\mathfrak{e}_2)]\|\rightarrow 0$ as $t\rightarrow 0$; thus, $\|V_+^\top[\mathfrak{e}_1/\gamma_B]\|\rightarrow 0$ and $\|V_+^\top[ (\mathfrak{e}_4+\mathfrak{e}_2)]\|\rightarrow 0$. 
Then, $\|V_+^\top \mathfrak{e}_1\|\rightarrow 0$ shows $ that 
\|U_+^\top [C_1]\|\rightarrow 0$, which indicates that $[C_1]$ asymptotically converges to the eigenspace associated with the zero eigenvalue, i.e., $[C_1] \rightarrow \frac{\mathbf{1}^\top C_1}{|\mathcal{V}|}\mathbf{1}$ or $E^\top[C_1] \rightarrow 0$ by the definition in subsection~\ref{Algebraic_Graph_Theory}. The equation of $E^\top\dot{C}_{1}$ with $  
\|U_+^\top [C_1]\|\rightarrow 0$ implies that $E^\top U_y\rightarrow 0$ and $\mathfrak{e}_2,W_s E^\top  C_{2}\rightarrow 0$. Finally, $\|V_+^\top[ (\mathfrak{e}_4+\mathfrak{e}_2)]\|\rightarrow 0$ shows that
$$
U_+^\top [C_4]\rightarrow \frac{c_-}{k_1 k_A\gamma_A}V_+^\top W_s E^\top  C_{2}\rightarrow 0
$$
where $U_+^\top [C_4]$ is the eigenspace associated with the zero eigenvalue and $E^\top [C_4]\rightarrow 0$ and $E^\top U_x\rightarrow 0$. For the case of $k_B=0$, we obtain globally asymptotically stable results for $E^\top[C_{1,4}]$ for arbitrary gains. Integrating $[\dot{C}_1]=-\frac{k_A}{2}L[C_1]$ yields an exponentially stable result: 
%: $[{C}_1]=e^{(-\frac{k_A}{2}Lt)}[C_1(0)]$. Thus, 
$\|\mathfrak{e}_1\|\leq \|\mathfrak{e}_{1(0)}\|e^{-(k_A\lambda_2/2)t}$. We define $\hat{E}\hat{E}^\top = \alpha(t)L$, where $\alpha(t)>0$ is as follows:
$$
\alpha(t)\triangleq\alpha_0e^{\frac{k_A\lambda_2 t}{2}}>0\quad\text{s.t.}\quad\alpha_0\geq \frac{2|-\lambda_0|\|L\|_2 +{2\epsilon_2}/{k_A}}{\lambda_2\|\mathfrak{e}_{1(0)}\|/\sup_t \|\mathfrak{e}_{4(t)}\|}
$$
This provides $\dot{V}_{\mathrm{all}}\leq -2\gamma_B^2\mathfrak{e}_4^\top L \mathfrak{e}_4+\dot{V}_{14}$ where
$$
\begin{aligned}
&\dot{V}_{14}=\left(\left(2(-\lambda_0) L+\frac{2\epsilon_2}{k_A}I
\right)\mathfrak{e}_4-\left(2\alpha L- \frac{2\dot{\alpha}}{k_A}I\right)\mathfrak{e}_1\right)^\top\mathfrak{e}_1\\
&\leq\left(\left(2|-\lambda_0|\|L\|_2 +\frac{2\epsilon_2}{k_A}\right)
\sup_t \|\mathfrak{e}_4(t)\|-\lambda_2\|\mathfrak{e}_{1(0)}\|
\alpha_0\right)\|\mathfrak{e}_1\|.
\end{aligned}
$$
Based on the inequality of $\alpha_0$, we obtain $\dot{V}_{14}\leq 0$ and $\dot{V}_{\mathrm{all}}\leq -2\gamma_B^2\mathfrak{e}_4^\top L \mathfrak{e}_4\leq 0$. This guarantees that $\mathfrak{e}_4\rightarrow 0$ as $t\rightarrow\infty$, and thus, $E^\top C_4\rightarrow 0$ along with the exponentially stable results of $E^\top C_1$.

We next consider the subcontroller $\hat{u}_j$ in Eq.~(\ref{sub_networked_input_i}), and its matrix formulation is given as follows:
\begin{equation*}
%\label{networked_input_i_C4_C14}    
\begin{bmatrix}
{U}_x(\hat{u}_j)\\
{U}_y(\hat{u}_j)
\end{bmatrix}
=
\begin{bmatrix}
\frac{k_A\gamma_A}{2k_0}L[C_4] -\frac{c_-}{2k_0} L_s [C_2]\\
-\frac{k_A}{2k_0}L[2C_1]
+\frac{\gamma_A \epsilon_2}{2k_0}L[C_4]
-\frac{\epsilon_2}{k_A k_0}\frac{c_-}{2k_1}L_sC_{2}
\end{bmatrix}.
\end{equation*}
Then, by applying $(\varrho,\varsigma,\tau,\psi)=(2c_+,0,1,0)$, $\hat{E}=I$, and ${U}_{x,y}(\hat{u}_j)$, we obtained the following:
$$
\begin{aligned}
\dot{V}_{\mathrm{all}}
&=2k_0^2
\begin{bmatrix}
-\frac{k_A\gamma_A }{2k_0} L[C_4]+\frac{c_-}{2k_0}L_s  C_{2}\\
U_y-\frac{\gamma_A\epsilon_2}{2k_0} L[C_4]+\frac{\epsilon_2}{k_Ak_0}\frac{c_-}{2k_1}L_s  C_{2}
\end{bmatrix}^\top
\begin{bmatrix}
 U_x\\
\frac{k_A}{2k_0}[2C_1] 
\end{bmatrix}\\
&=-\frac{k_A^2}{2}\|E^\top [2C_1]\|^2-2k_0^2 \|{U}_x\|^2\\
\end{aligned}
$$
which indicates that both $\|E^\top [C_1]\|$ and ${U}_x(\hat{u}_j)$ converge to 0 as $t \rightarrow \infty$. Consequently, the equation for $E^\top\dot{C}_{1,4}$ implies that $E^\top U_y\rightarrow 0$ and $E^\top [C_4]\rightarrow\mathrm{const}$. The definitions of $U_x$ and $U_y$ reveal that $E^\top [C_4]\rightarrow 0$ and $W_s E^\top C_2\rightarrow 0$. For the case of $k_B=0$, it is evident that the $E^\top [C_4]\rightarrow 0$ and $E^\top [C_4]\rightarrow 0$ as $t\rightarrow\infty$.

We finally mention the convergence results of $\overline{r}_{xyjk}$ for arbitrary $jk$-th satellites. When we achieve $U_{xy}\rightarrow 0$ and $E^\top [C_{1,4}]\rightarrow 0$, we obtained $\dot{\overline{r}}_{xyjk}=0$ in Eq.~(\ref{drdt_2}). This indicates that $\overline{r}_{xyjk}$ takes a constant value and $[C_{2,3}]$ takes a periodic value. These satisfy $W_sE^\top[C_2]=0$ for $k_B\neq 0$. 

Finally, we show the stability proof for the $z$-motion for two satellites, which can be extended to the $N$ satellite case. For the $z$-axis controller, consider the Lyapunov candidate function $V_{56}=(C_5-C_{5r})^2/2$, which satisfies $\dot{C}_{5r}=-\omega_{xy}C_{6d}+\cos\theta_0\hat{d}_y$, where $\hat{d}_y=-k_1\frac{c_-}{2}\frac{\epsilon_2}{k_A}\frac{k_0}{2}d_b$, the constant gains $k_z\in\mathbb{R}_+$, $C_{5d}$ are defined in Eq.~(\ref{r_xy_and_r_z}), and $C_{5r}={C}_{5d}+{c_-k_1\cos\theta_0}\delta{C}_4/2-2c_+k_1\sin\theta_0{C}_1$. Substituting $u_{\mathrm{safe}}$ into this time derivative yields $\dot{V}_{56}=-2k_{z} \delta C_5^2\leq 0$ for $\hat{d}_y=d_z=0$. Then, $(C_5,C_6)$ asymptotically converges to $(C_{5d},C_{6d})$, driving the satellites to the desired orbital plane as $C_{1,4}\rightarrow 0$.
\end{proof}
