\section{Equivalence of Edge Term In \texorpdfstring{
    \cite[Theorem 1.1]{SteklovCuboids}}{
        [The Steklov Spectrum of Cuboids, Theorem 1.1]}}
\label{section:edge-equivalence}
\CorollaryEdgeConstantRecurrence
\begin{proof}
    This follows immediately from \Cref{prop:edge-integral}.
\end{proof}

\CorollaryEdgeConstantCuboidEquivalence
\begin{proof}
    \begin{align*}
        G_{n, 1} 
            & = \int_{[0, \half[\pi]]^{n - 1}} \fcall{\arccot}{\prod_{i = 1}^{n - 1}\csc(\theta_i)} \prod_{i = 1}^{n - 1} \sin^i(\theta_i) \dl{\mu} \\
            & = \int_{[0, \half[\pi]]^{n - 1}} \fcall{\arctan}{\prod_{i = 1}^{n - 1}\sin(\theta_i)} \prod_{i = 1}^{n - 1} \sin^i(\theta_i) \dl{\mu} \\
            & = \int_{[0, \half[\pi]]^{n}} \frac{\prod_{i = 1}^{n} \sin^i(\theta_i)}{\left(1 + \prod_{i = 1}^n \sin^2(\theta_i)\right)^{\half}} \dl{\mu} \\
            & = \frac{1}{2^n} \int_{[0, 1]^{n}} \left(1 + \prod_{i = 1}^{n} x_i\right)^{-\half}\prod_{i = 1}^n \frac{x_i^{\half[i - 1]}}{(1 - x^i)^{\half}} \dl{\mu} \\
            & = \frac{\Gamma(\thalf)^n}{2^n \Gamma(\thalf[n])} \int_{0}^{1} (1 + x)^{-\half}(1 - x)^{\half[n] - 1} \dl{x} \,.
    \end{align*}
\end{proof}

\section{Proof of \crtCref{prop:BetaDimensionalReduction}}
For completeness, a proof of \Cref{prop:BetaDimensionalReduction} is given.
\begin{proof}
    First consider \((x, y) \in [0, 1]^2\) with the standard Lebesgue measure. The following is a bijection outside a set of measure zero, \(x' = xy, y'(1 - x') = y(1 - x)\). The corresponding change in measure is
    \begin{align*}
        y \dl{\mu} = (1 - x') \dl{\mu'} \,.
    \end{align*}
    Hence, given \(a, b > 0\) and \(f\) such that \(f(x)(1 - x)^{a + b - 1} \in L^1([0, 1])\) then
    \begin{align*}
        & \int_{[0, 1]^2} f(x y) (1 - x)^{a - 1} y^{a} (1 - y)^{b - 1} \dl{\mu} \\
        & \qquad \begin{aligned}[t]
            & = \int_{[0, 1]^2} f(x') (1 - x')^{a + b - 1} y'^{a - 1} (1 - y')^{b - 1} \dl{\mu'} \\
            & = B(a, b) \int_{0}^{1} f(x') (1 - x')^{a + b - 1} \dl{x'} \, .
        \end{aligned}
    \end{align*}
    The result then follows by induction.
\end{proof}
