%         \mathrm{s.t.}\qquad &\bar h(Ax+Bu)-\bar h(x) \geq -\Delta {\bar h}(x)
%     \end{align*}
%     \end{subequations}
%     with $\Delta {\bar h}(x) \leq \max_{u\in\mathcal U} \bar h(Ax+Bu)-\bar h(x)$. It follows that \cref{eq:approximate_cbf_filter} is feasible for all $x\in\mathcal D$ and that there exists a sufficiently small $\epsilon>0$ and corresponding $R>0$ such that the closed-loop system~\cref{eq:linear_system} under $u(k)=\bar{\kappa}_{\mathrm{cbf}}(x(k))$ converges to $\{x\in\mathbb R^{n_x}~|~|x|_{\Omega}\leq R\}$. Furthermore, if $\epsilon=0$, the guarantees of \cref{prop:cbf_properties} are recovered.
