\subsection{Stochastic Disturbances and Indirect Feedback}\label{sec:stochastic}
%
While set-based CBF safety filters guarantee asymptotic stability of the safe set under nominal conditions, practical systems are often subject to significant stochastic disturbances. To address this, we extend the set-based CBF framework to handle linear systems with additive stochastic disturbances,
\begin{align}\label{eq:stochastic_linear_system}
    x(k+1) = A x(k) + B u(k) + G w_s(k),
\end{align}
where $w_s(k)$ is a random process with known distribution $\mathcal Q_W$. The objective is to ensure probabilistic satisfaction of state and input constraints, i.e.,
\begin{align}\label{eq:chance_constraints}
    \mathbb P\{x(k)\in\mathcal X^j\}\geq p^j_x, \quad \mathbb P\{u(k)\in\mathcal U^j\}\geq p^j_u,
\end{align}
for prescribed probability levels $p^j_x, p^j_u \in (0,1]$.

Following the stochastic MPC literature~\cite{hewing2019scenario}, we decompose the system into nominal and error dynamics, $x(k) = z(k) + e(k)$, with $z(k+1) = Az(k) + Bv(k)$ and $e(k+1) = Ae(k) + B\pi(e(k)) + G w_s(k)$. The controller $\pi(e(k))$ is designed to keep the error $e(k)$ small, and probabilistic reachable sets $\mathcal R^{j,x}_k$, $\mathcal R^{j,u}_k$ satisfying $\Pr\{e(k)\in\mathcal R^{j,x}_k\}\geq p_x^j$, $\Pr\{\pi(e(k))\in\mathcal R^{j,u}_k\}\geq p_u^j$ are used to tighten the constraints~\cite{hewing2019scenario}:
%\begin{align}\label{eq:tightened_constraints}
    $\bar{\mathcal X} \triangleq \bigcap_{j,k} \mathcal X_j \ominus \mathcal R_k^{j,x},
    \bar{\mathcal U} \triangleq \bigcap_{j,k} \mathcal U_j \ominus \pi(\mathcal R_k^{j,u})$.
%\end{align}
%
\par
%
A set-based CBF is then constructed for the nominal dynamics using the tightened constraints, and the safety filter optimization is formulated as
\begin{subequations}
    \label{eq:cbf_robust_filter}
    \begin{align}
        \min_{v} \quad & G(v+\pi(x-z(k)), u_{\mathrm{des}}) \\
        \mathrm{s.t.} \quad & v \in \bar{\mathcal U}, \\
        & h(Az(k) + Bv) - h(z(k)) \geq -\Delta h(z(k)),
    \end{align}
\end{subequations}
with $z(0) = x(0)$. The resulting control law $u(k) = v^* + \pi(x(k) - z(k))$ ensures chance constraint satisfaction using standard arguments from stochastic control and this concept can be tailored to various disturbance models and feedback structures~\cite{hewing2019scenario}.
%
