\section{Proof of \cref{thm:nominal_set_cbf}}
    Parts a), b), and c) show basic properties of the set-based CBF, leading to invariance in part d):
    \paragraph*{a) Safe set $\mathcal S$ and $h(x)$} We first show that $\Omega=\mathcal S$ is a safe set according to \cref{def:barrier_function}, i.e., $x\in\Omega \Leftrightarrow h(x) \geq 0$ on the domain $\R^{n_x}$.
    %
    Case $x\in\Omega \Rightarrow h(x)\geq 0$: For all $x \in\Omega$ we note that $\bar \gamma=1$ is a feasible but suboptimal solution to~\cref{eq:set_based_gamma} implying $\gamma_{\Omega}(x)\leq 1$ and therefore $h(x)=1-\gamma_{\Omega}(x)\geq 0$.
    %
    Case $x\in\Omega \Leftarrow h(x)\geq 0$: From $h(x)\geq 0$ and \cref{eq:set_based_gamma} it follows that $0 \leq \gamma_{\Omega}(x) \leq 1$ and $x\in\gamma_{\Omega}(x) \Omega$. \cref{lem:scaled_convex_set_in_set} implies $\gamma_{\Omega}(x)\Omega\subseteq \Omega$ and therefore $x\in\Omega$. To establish that $\gamma_{\Omega}(x)$ is defined for all $x\in\R^{n_x}$, i.e., there exists a solution to~\cref{eq:set_based_gamma}, consider the case $x\notin \Omega$. Since $0\in\mathrm{int}(\Omega)$, there exists a ball of radius $c>0$ with respect to some norm $\Vert . \Vert$ around $0$ that is contained in $\Omega$. Selecting $\gamma=\Vert x \Vert c^{-1}$ implies $x\in\gamma\Omega$ providing a candidate solution to~\cref{eq:set_based_gamma} for all $x\in\R^n$, which implies feasibility for any domain $\mathcal D\subseteq\R^{n_x}$.
    %
    \paragraph*{b) Continuity of $h(x)$}\label{par:proof_implicit_cbf_continuity}
    Define $\bar r \triangleq 2\max_{x\in\mathcal D} \Vert x \Vert$, which exists due to continuity of $\Vert . \Vert$ and compactness of $\mathcal D$. There exists a corresponding $\bar \gamma >0$ such that $\mathcal B_n(\bar r)\subseteq \bar \gamma \Omega$ since $0\in \mathrm{int}(\Omega)$. It holds for all $x\in\mathcal D$ that $x\in\mathcal B_n(\Vert x \Vert)=\Vert x \Vert \bar r^{-1}\mathcal B(\bar r)$ and due to \cref{lem:scaling_containment} it follows that
    \begin{align*}
        x\in \Vert x \Vert \bar r^{-1} \bar \gamma\Omega.
    \end{align*}
    This allows us to derive a continuous upper bound on $\gamma_{\Omega}(x)$ around any $x_0\in\mathcal D$ by constructing a suboptimal solution $\gamma_c(x, x_0)$ to~\cref{eq:set_based_gamma} as follows. Let $\gamma_c(x,x_0) = \gamma_c^{(1)}(x,x_0) + \gamma_c^{(2)}(x_0)$ resulting due to convexity of $\Omega$ in $\gamma_c(x,x_0)\Omega=\gamma_c^{(1)}(x,x_0)\Omega + \gamma_c^{(2)}(x_0)\Omega$. Select $\gamma_c^{(1)}(x,x_0)\triangleq \bar \gamma \bar r^{-1}\Vert x - x_0 \Vert$ and $\gamma_c^{(2)}(x_0)\triangleq \gamma_{\Omega}(x_0)$. For any $x,x_0 \in \mathcal D$ we verify that $\gamma_c(x, x_0)$ is a feasible solution to~\cref{eq:set_based_gamma} as follows:
    \begin{align*}
        x = \underbrace{x - x_0}_{\in \gamma_c^{(1)}(x,x_0)\Omega} + \underbrace{x_0}_{\in \gamma_c^{(2)}(x_0)\Omega}\in \gamma_c(x,x_0)\Omega.
    \end{align*}
    Finally, given a $x_0\in\mathcal D$, it follows for all $x\in\mathcal D$ that
    \begin{align*}    
        \Vert \gamma_{\Omega}(x) - \gamma_{\Omega}(\bar x) \Vert &\underbrace{\leq}_{\text{suboptimality}} \Vert \gamma_c(x,\bar x) - \gamma_{\Omega}(\bar x)\Vert \\
        &= \bar \gamma r^{-1} \Vert x - \bar x \Vert
    \end{align*}
    showing local Lipschitz continuity of $\gamma_{\Omega}(x)$ in $\mathcal D$.
    %
    \paragraph*{c) For all $x\in \mathcal S$ the bound \cref{eq:cbf_decrease_bound} holds}
    Since $\mathcal S=\Omega$ is control invariant, for any $x\in\Omega$ we have $x\in\gamma_{\Omega}(x)\Omega$. From \cref{lem:control_invariant_set_scaling} it follows that there exists an input $u\in\mathcal U$ such that $Ax+Bu\in\gamma_{\Omega}(x)\Omega$, implying $\gamma_{\Omega}(Ax+Bu)\leq \gamma_{\Omega}(x)$ and therefore $h(Ax+Bu)\geq h(x)$. Since $-\Delta h(x)\leq 0$ for all $x\in\Omega$, it follows that \cref{eq:cbf_condition} holds.
    %
    \paragraph*{d) Forward invariance of $\Omega$} Follows directly from \cite[Appendix B]{wabersich22}.
% \end{proof}
\section{Technicalities}
\begin{lemma}\label{lem:scaling_containment}
    Consider a set $\Omega \subseteq \mathbb R^n$ and a ball $\mathcal B_n(r)$ of radius $r>0$ such that $\mathcal B_n(r)\subseteq\Omega$. It holds that $\lambda \mathcal B_n(r) \subseteq \lambda\Omega$ for all $\lambda \geq 0$.
\end{lemma}
\begin{proof}
    For every $y\in \lambda \mathcal B_n(r)$ we have by definition $y = \lambda x$, $x\in \mathcal B_n(r)$ and $x\in\Omega$. Since $x\in\Omega$ it holds $\lambda x\in \lambda \Omega$ by definition, i.e., $\lambda \Omega=\{\lambda z|z\in\Omega\}$, completing the proof.
\end{proof}
\begin{lemma}\label{lem:scaled_convex_set_in_set}
    Consider a compact and convex set $\mathcal C\subset\R^n$ with $0 \in\mathcal C$. For all $\gamma\in[0,1]$ it holds that $\gamma \mathcal C\subseteq \mathcal C$.
\end{lemma}
\begin{proof}
    For every $x\in\mathcal C$ we can verify $\gamma x \in \mathcal C$ using convexity, i.e., $\gamma x = \gamma \cdot x + (1-\gamma)\cdot 0$, since $0\in\mathcal C$.
\end{proof}

\begin{lemma}\label{lem:control_invariant_set_scaling}
    Let $\Omega \subset \R^n$ be a convex control invariant set with $0\in\Omega$ satisfying \cref{def:control_invariant_set}. For all $\gamma\in[0,1]$ it follows that $\gamma \Omega$ is a control invariant set according to \cref{def:control_invariant_set}.
\end{lemma}
\begin{proof}
    For every $x\in\gamma \Omega$ there exists an input $u$ such that $Ax+Bu\in\Omega$. For every $y=\gamma x$ select the input $v=\gamma u$, yielding $\gamma (Ax+Bu) \in \gamma \Omega$, showing control invariance of $\gamma\Omega$.
\end{proof}
\begin{lemma}\label{lem:scaling_of_feasible_set}
    For all $\gamma\geq 0$ it holds that $\gamma\mathcal X_N^1=\mathcal X_N^\gamma$.
\end{lemma}
\begin{proof}
    In the case that $\gamma=0$ it follows from \cref{eq:psf_nominal_initial_condition} and \cref{eq:psf_nominal_state_constraints} that $\mathcal X^0_N=\{0\}$, which equals $0\mathcal X^1_N$ by definition.
    For $\gamma>0$ we have
    %\begin{align*}
        $\gamma \mathcal Z_N^1  = \{ (\gamma z, \{\gamma v_{i}\}) ~|~ (z, \{v_{i}\}) \in\mathcal Z_N^1\}$,
    %\end{align*}
    where we substitute $(\gamma z, \{\gamma v_{i}\})\triangleq (x, \{u_{i}\})$ to obtain
    \begin{align}
        \gamma \mathcal Z_N^1 & = \{ (x, u_{i}\}) ~|~ (\gamma^{-1}x, \gamma^{-1}\{u_{i}\}) \in\mathcal Z_N^1\}.
        \label{eq:lem_scaling_inverse_relation}
    \end{align}
    Next, we rewrite~\cref{eq:lem_scaling_inverse_relation} as
    \normalsize
    \begin{align*}
        & \left\{ (x, \{u_{i}\}) \middle|
        \begin{matrix*}[l]
            & (A^N \gamma^{-1}x + \Sigma_{l=0}^{N-1}A^{N-l-1}B \gamma^{-1}u_{l}) \in \mathcal X_f, \\
            & \forall i\in\{0,..N-1\}:\\
            & \quad (A^i \gamma^{-1}x + \Sigma_{l=0}^{i-1}A^{i-l-1}B \gamma^{-1}u_{l}) \in \mathcal X_i,\\
            & \quad  \gamma^{-1}u_{i} \in \mathcal U_i
        \end{matrix*}
        \right\}                             \\
        & =\mathcal Z^\gamma_N
    \end{align*}
    \normalsize
    using $x_{0} = x$ and by inserting the dynamics~\cref{eq:psf_nominal_dynamics}.
    Through the relation $\mathcal Z^\gamma_N= \gamma\mathcal Z^1_N$ we finally obtain
    \begin{align*}
        \mathcal X^\gamma_N & = \{x ~|~ (x, \{u_{i}\}) \in\gamma \mathcal Z_N^1\}                      \\ 
                            & = \{x ~|~ (\gamma^{-1}x, \{\gamma^{-1}u_{i}\}) \in \mathcal Z_N^1\}       \\
                            & = \{\gamma z ~|~ (z, v_{i}\}) \in \mathcal Z_N^1\}=\gamma \mathcal X^1_N,
    \end{align*}
    showing the desired result.
\end{proof}
\end{appendices}


