\title{B-splines approximate the Gaussian density and Hermite functions in Schwartz seminorms}
\author{Maciej Rzeszut$^1$, Michał Wojciechowski$^2$}
\date{%
    $^1$Jan Kochanowski University\\%
    $^2$Institute of Mathematics, Polish Academy of Sciences\\[2ex]%
