		\includegraphics[scale=.8]{figures/Final3_compat_L_sigma.pdf}
		\caption{An exact Lagrangian filling $L_\sigma$ of $\Lambda$ compatible with the standard Lefschetz fibration $f$.}
		\label{fig:std_chek_fibr}
	\end{figure}
