		\includegraphics[scale=.8]{figures/Final3_Cl_Ch.pdf}
		\caption{(Left) A choice of $\sigma_{Cl}$, a curve with extended winding number 1, and (Right) a choice of $\sigma_{Ch}$, a curve with extended winding number $0$. These yield two embedded exact Lagrangian fillings of the standard Legendrian Hopf link $\La_h$.}
		\label{fig:Cl_and_Ch_curves}
	\end{figure}
