	\begin{figure}[h!]
		\centering
		\includegraphics[scale=.8]{figures/Final3_Lbar_compat.pdf}
		\caption{A completion of an embedded, exact Lagrangian filling $L$ into a Lagrangian torus $\overline{L}$ such that the component added is compatible with the standard Lefchetz fibration.}
		\label{fig:L_bar_fibr}
