Clearly, if the objective $J$ is unbiased under empirical evaluation, the mini-batch gradient descent simply optimizes the objective under the measure  $\hat\bbP$. This implies that the standard mini-batch approach inherently accounts for model uncertainty, albeit implicitly, by using the expectation operator as the underlying measure of uncertainty.}

To explicitly incorporate model risk into the optimization process, we propose an adaptation of the gradient descent procedure, replacing the expectation operator with the $\cvar$ as the uncertainty measure. This results in an alternative stochastic gradient descent method (\Cref{alg:cvar_sgd}) that prioritizes performance under adverse scenarios, thereby enhancing robustness in uncertain environments.

\begin{algorithm}[t]
\small
\caption{$\cvar$ Stochastic Gradient Descent}
\label{alg:cvar_sgd}
\SetAlgoLined
\DontPrintSemicolon
\KwIn{Initialize $a^{(0)}$ with parameters $\phi^{(0)}$, learning rate $\eta$, batch size $m$, $\cvar$ level $\alpha$}
\KwOut{Optimized parameter $\phi^*$}
$t \gets 0$ \;
\While{not converged}{
    \oldchange{Initialize ``worst objective'' and ``worst gradient'' sets $\mathcal{J} \gets \emptyset$, $\mathcal{G} \gets \emptyset$} \;
    Independently sample integer $k$ such that $\mathbb{E}[k/m] = 1-\alpha$ \;
    \For{$i \gets 1$ \KwTo $m$}{
        Sample a measure $\mathbb{P}_i \sim \ModelDist$ \;
        Compute objective $J \gets  \Objective\big(X(a^{(t)}); \mathbb{P}_i\big)$ 
        \oldchange{
        \If{$\mathcal{J}$ has less than $k$ entries}{
            Insert $J$ to $\mathcal{J}$, \change{compute gradient $g \gets \nabla_\phi J_i$ and add to} $\mathcal{G}$ \;
        }
        \If{$\mathcal{J}$ has $k$ entries \textbf{and} $J$ is smaller than the maximum of $\mathcal{J}$}{
            Replace $J$ with the maximum of $\mathcal{J}$, \change{compute gradient $g \gets \nabla_\phi J_i$} and replace the corresponding element in $\mathcal{G}$ with $g$\;
        }}
    }
    % Compute objective values $\{J_i\}_{i=1}^{m}$ corresponding to each $\mathbb{P}_i$ \;
    % Sort $\{J_i\}$ such that $J_{(1)} \geq J_{(2)} \geq \cdots \geq J_{(m)}$ \;
    Update $a^{(t)}$ to $a^{(t+1)}$ with parameters $\phi^{(t+1)}$:
    \[
        \phi^{(t+1)} \gets \phi^{(t)} - \eta\, \frac{1}{k} \sum_{g \in \mathcal{G}} g
    \]
    $t \gets t + 1$ \;
}
\end{algorithm}

% - note that the algorithm does not require simultaneous objective / gradient computations, which reduces the memory requirements (almost) to the naive application

% - the gradients, as their computation is completely independent can be however carried out in parallel (on different machines if necessary) to achive additional speedups for large models

% - since we -- in expectation -- discard the $1-\alpha$ gradients of the best objectives, we can show that the computed gradient is actually a non-biased estimate of the uncertainty-aware $\cvar$ objective, therefore we obtain the following result:

Notably, the proposed algorithm does not require the simultaneous computation of multiple objectives and gradients, thereby maintaining memory requirements comparable to a $(1-\alpha)$-fraction of the naive stochastic gradient descent, as at most $(1-\alpha)\cdot m$ gradients need to be saved simultaneously in memory. This reduction can be crucial, especially for a high-parametric class of strategies $\StrategySpace$.

Despite this reduced memory footprint, the algorithm remains computationally efficient. Since the gradient computations for different sampled measures \(\mathbb{P}_i\) are entirely independent, they can be executed in parallel across multiple processors or even distributed across different machines. This parallelism enables significant speedups, especially for large-scale models.

From a theoretical perspective, the key property of the \(\cvar\)-SGD algorithm is that, in expectation, it discards the gradients corresponding to the best-performing \(\alpha\)-fraction of objectives. Consequently, the computed update direction serves as an unbiased estimator of the gradient of the uncertainty-aware \(\cvar\) objective. This leads to the following result:

% \begin{ithm}\label{thm:CVaRStochGrad}
%     Under suitable regularity conditions,
%     the $\cvar$-stochastic gradient descent applied to $\Objective(X( a),\bbP)$, with $\bbP \sim \ModelDist$ for a distribution $\ModelDist$ on $\ModelSpace$ optimizes the learning objective 
%     \begin{align*}
%         \cvar_\alpha\left({\Objective(X( a),\bbP)}\middle| \bbP \sim \ModelDist\right).
%     \end{align*}
% \end{ithm}
% \begin{proof}
%     The proof is relegated to \Cref{app:ProofCVaRSG}.
% \end{proof}
\begin{restatable}{thm}{CVARSDGTHM}[$\cvar$-SGD]\label{thm:CVARSGD-randomk}
Let $\Phi = \{ \phi \in \mathbb{R}^d : \|\phi\| \leq B \}$ for some $B > 0$, and assume that for every $\bbP \sim \ModelDist$, the function $\phi \mapsto J(X(a_\phi), \bbP)$ is convex and $\rho$-Lipschitz, i.e.,
$
\left\| \nabla_\phi J(X(a_\phi), \bbP) \right\| \leq \rho 
$ $\ModelDist$-almost surely.
Let $\alpha \in (0,1)$ and define the objective
$
\mathcal{L}(\phi) := \cvar_{\alpha}\left( J(X(a_\phi), \bbP) \,\middle|\, \bbP \sim \ModelDist \right).
$
Let $(\phi_t)_{t \geq 0}$ be the sequence generated by \Cref{alg:cvar_sgd}, using step size $\eta_t = {B}({\rho \sqrt{t}})^{-1}$, and define the average iterate
$
\bar{\phi}_t := \sum_{s=1}^{t} \phi_s /t.
$
Then, for all $t \geq 1$,
\[
\mathbb{E}[\mathcal{L}(\bar{\phi}_t)] - \min_{\phi \in \Phi} \mathcal{L}(\phi) \leq \frac{B \rho}{\sqrt{t}}.
\]
\end{restatable}

\subsection{Improved precision in high-dimensional investing}\label{sec:HighDim}

Firstly, we want to show the reduction of the memory constraints by $\cvar$-SGD in a controlled environment. For this, we consider a high-dimensional version of the standard investing example, \Cref{exa:Plug-inNormal}. By increasing the dimensionality, not only the simulations become more expensive, but it also makes the strategy space $\StrategySpace$ richer and therefore the problem harder. The idea is to first derive an analytic baseline, which we then approximate in a realisitc setting with and without $\cvar$-SGD for varying $\alpha \in [0,1]$ and analyze the algorithms effect on precision.

% In this section, we show that in the standard investing example, when extended to the high-dimensional regime, limited memory may lead to inaccuracies in the uncertainty-aware strategy and we demonstrate how our CVaR‐SGD approach restores precision.

Formally speaking, we work in a multi‐dimensional version of the Gaussian setup introduced in \Cref{sec:ComparingAnalyticallyIIDNormal}.  Let $d \in \N$,
%% New changes from Thorsten 
and $(\Delta S_t)$ be i.i.d.\ with
\[
\Delta S_t \;\sim\;\mathcal N_d(\mu,\Sigma),
\qquad t=-N+1,\dots,0,
\]
where $\mu\in \R^d$ is the true mean vector and $\Sigma \in \R^{d\times d}$ is the true covariance matrix
%% New changes from Thorsten
(both unknown). 
Then,  the sample mean
\[
\dest \;=\;\frac{1}{N}\sum_{t=-N+1}^0\Delta S_t,
\]
has distribution \(\hat\mu\sim\mathcal N_d(\mu,\Sigma/N)\). With similar arguments as in \Cref{sec:ComparingAnalyticallyIIDNormal}, we neglect the estimation error of \(\Sigma\) and focus on the estimation error in \(\dest\).

The agent's actions are now multi-dimensional, i.e. $a \in \R^d =: \StrategySpace$. Analoguously to \Cref{exa:Plug-inNormal}, the payoff of 
{the considered} contingent claim will be the return scaled by the corresponding action, i.e. $X(a) := a^\intercal \Delta S_1$. Again, we choose the agent has an entropic risk objective with risk aversion $\lambda > 0$. For completeness, we can show (\Cref{lem:HighDimObjective}) that the plug-in objective results into the following mean-variance objective
\[
J(X(a), \hat\bbP)\;=\;a^\intercal\dest \;-\;\frac{\lambda}{2}\,a^\intercal\Sigma\,a.
\]
which is optimized by (see \Cref{lem:plug-in_hd}) $\bfan =\,\Sigma^{-1}\, \dest / {\lambda}$.


\paragraph{Analytic solutions.} We now want to robustify this strategy using $\cvar_\alpha$ for some $\alpha \in [0,1]$. As mentioned above, we will start with some analytic considerations, along the line of \Cref{sec:ComparingAnalyticallyIIDNormal}, to compare the later approximations against.

\begin{restatable}{lemma}{MDCVARStrategy}
\label{lem:MDCVARStrategy}
The $\cvar$ uncertainty-aware strategy, which is analogue to \eqref{id:UACvarEntr}, and defined by
    \begin{align*}
    \argmax_{\Strategy \in \R} 
    \cvar_{\alpha}\Big(
    \entr_\lambda
    \big(
        a \Delta S_1
        ~ \big| ~
        \Delta S_1 \sim \calN(\mu, \sigma)
    \big)
    ~ \Big| ~
    \mu \sim \calN(\hat{\mu}, \Sigma/N)
    \Big),
\end{align*}
is uniquely attained by
\[
\bfarr
=\frac{1}{\lambda}\,
\Bigl(1-\frac{\kappa_\alpha}{\sqrt{N}\,\|\Sigma^{-1/2}\hat\mu\|}\Bigr)_+\,
\Sigma^{-1}\,\hat\mu,
\]
where  \(\displaystyle \kappa_\alpha={\varphi(\Phi^{-1}(\alpha))}/{\alpha}\). 
Note that there is a ``zero-investment region''
\(\;\bfarr=0\) whenever
\(\|\Sigma^{-1/2}\hat\mu\|\le \kappa_\alpha/\sqrt{N}\),
and otherwise \(\bfarr\) points along \(\Sigma^{-1}\hat\mu\) with shrinkage factor \(\bigl(1-\kappa_\alpha/(\sqrt{N}\|\Sigma^{-1/2}\hat\mu\|)\bigr)/\lambda\).
\end{restatable}

