\section{Basics on Risk Measures}

%\begin{defn}[Entropy]
Consider the probability space $(\Omega, \calF, \bbP)$ and let $X \in L^0(\Omega, \calF, \bbP)$. Then, the entropy \cite{FoellmerSchied04} for risk aversion $\lambda>0$ is defined as follows
	\begin{align}\label{def:Entropy}
		\entr_\lambda(X) := - \frac{1}{\lambda} \log\left( \myE{\bbP}{\exp \left( - \lambda X \right)} \right).
	\end{align}
%\end{defn}

For normal random variables, it is useful to exchange the entropic risk-measure with the mean-variance operator \cite{de1940problema}, since it offers higher numerical stability.
	 The mean-variance for risk-aversion $\lambda>0$ is defined by 
	\begin{align}\label{def:MV}
		\mv_\lambda(X) := \myE{\bbP}{X} - \frac{1}{2}\lambda \myV{\bbP}{X}.
	\end{align}

If $X$ is normally distributed, the Laplace transform equals \begin{align}
    \myE{\bbP}{\exp \left( - \lambda X \right)}=\exp \left( - \lambda \myE{\bbP}{X} + \nicefrac{\lambda}2 \myV{\bbP}{X}\right), \label{id:MVisENT}
\end{align} 
such that mean-variance and negative entropy coincide.




% \begin{lem}\label{lem:MVisENT}
% 	Mean-variance and negative entropy coincide if $X$ is normal.
% \end{lem}
% \begin{proof}
% 	This is a straightforward consequence of the definition of the moment generating function for normally distributed random variables.
% \end{proof}

% While entropy, and respectively mean-variance, is intuitively easy to interpret, since high values of $\lambda$ result in high regularity requirements and vice versa, the actual choice of $\lambda$ is to some extend problematic. While one may argue, that the choice of this parameter should resemble the agent's uncertainty aversion, there is neither a clear indicator how this preference translates to this parameter, nor a consistency over different tasks -- since the operator is used to interpret utility values, which behave differently than payoffs. We suggest to relieve this shortcoming by using uncertainty measures as for instance the CVaR:

% \begin{defn}[CVaR]\label{def:CVaR}
	In the above setting, the conditional value at risk (CVaR) \cite{FoellmerSchied04} is defined for a risk-aversion parameter $\alpha \in [0,1]$ as 
	\begin{align}
            - \cvar_\alpha(X) := \myCond{\bbP}{X}{X \leq \mathrm{VaR}_\alpha(X)}, \label{id:CVaR}
	\end{align}
	where for $\gamma \in [0,1]$
	\begin{align*}
		\mathrm{VaR}_{\gamma}(X)= - \inf \left\lbrace x \in \mathbb{R} : F_{X}(x) > \gamma \right\rbrace.
	\end{align*}
% \end{defn}


% The CVaR operator also depends on a parameter $\alpha$, however, comes with two benefits. First, it is interpretable: For every strategy, the objective results as the average from the $\alpha$-fraction worst drift estimation errors $\peps$. Second, the parameter $\alpha$ is bound to the interval $[0,1]$. We finish this section by stating the following simple result that is useful for  the implementation of the CVaR.

\begin{rem}
	Note we can rewrite 
	$$
	\cvar(X) = \frac{1}{\alpha} \left(  \mathbb E[{X} 1_{\lbrace X \leq x_\alpha \rbrace}]+ x_\alpha(\alpha-\mathbb P(X<x_\alpha)) \right),
	$$
	where $x_\alpha$ is the lower $\alpha$-quantile. This particularly simplifies for continuous distribution functions, since the term $x_\alpha(\alpha-\mathbb P(X<x_\alpha)) = 0$ vanishes.
\end{rem}


