\begin{lem}\label{lem:SolveEntr}
    For $X \sim \calN(\nu, \tau^2)$ with $\tau, \nu, \lambda \in \R$, 
    \begin{align*}
        \argmax_{a \in \R}\entr_\lambda(aX) = \frac{\nu}{\lambda \tau^2}
    \end{align*}
\end{lem}
\begin{proof}
    As remarked above, under normality, the entropy coincides with mean-variance, such that, the left-hand side reduces to $a\nu - \lambda a^2\tau^2/2$ which is optimized by the right-hand side.
\end{proof}


\begin{lem}\label{lem:OOSPScaledPlug-inReduction}
Assume that $\Delta S_1 \sim \calN(\mu,\sigma^2)$ and $\hat \mu \sim \calN(\mu,\sigma^2N^{-1})$. Then,
\begin{align*}
    \entr_\lambda\left( x \dest \Delta \pS_{1}\right) 
    & =
    \entr_\lambda\left( x \mu \Delta \pS_{1}\right) 
    -
    \frac{\lambda}{2}
    \myV{\bbP}{x(\dest - \mu) \Delta \pS_{1}} \\
    &=
    x \mu^2
    \left(1-  \frac{\lambda}{2}x\sigma^2\right)
    -
    \frac{\lambda }{2N} x^2\sigma^2(\mu^2 + \sigma^2).
\end{align*}
\end{lem}

\begin{proof}
We start with the first equation:
due to equivalence of $\entr$ and $\mv$ for normal random variables,   
\begin{align*}
	\entr_\lambda\left( x \dest \Delta \pS_{1}\right)
	&= \mv_\lambda\left(  x \dest \Delta \pS_{1}\right) \\
        &= \myE{\bbP}{ x \dest \Delta \pS_1} - \frac{\lambda}{2} \myV{\bbP}{ x \dest \Delta \pS_1} \\
        &= x\myE{\bbP}{\mu \Delta \pS_{1}} 
        - \frac{x^2\lambda}{2} \myV{\bbP}{ \mu \Delta \pS_{1} +  (\dest - \mu) \Delta \pS_{1}}.
\end{align*}
% Note 
