% and, on the other hand, 
Next, observe that
\begin{align}
        &\myV{\bbP}{ \mu \Delta \pS_{1} + (\dest - \mu) \Delta \pS_{1}} \notag \\
        &\quad = 
        \myE{\bbP}{ (\mu \Delta \pS_{1})^2 + 2 \mu  (\dest - \mu) \Delta \pS_{1}^2 + (\dest - \mu)^2 \Delta \pS_{1}^2}
        -
        \myE{\bbP}{ \mu \Delta \pS_{1} + (\dest - \mu) \Delta \pS_{1}}^2
        \notag \\
        &\quad = 
        \myE{\bbP}{ (\mu \Delta \pS_{1})^2}  + 
        \myE{\bbP}{(\dest - \mu)^2 \Delta \pS_{1}^2}
        -
        \myE{\bbP}{ \mu \Delta \pS_{1}}^2
        -
        \myE{\bbP}{(\dest - \mu) \Delta \pS_{1}}^2
        \notag \\
    &\quad = \myV{\bbP}{ \mu \Delta \pS_{1}} + 
    \myV{\bbP}{(\dest - \mu) \Delta \pS_{1}}. \label{id:OospPlug-inPlug-in_V}
\end{align}
The second equation follows by observing that
by iterated conditional expectations,
 \begin{align} 
         \mu \myE{\bbP}{  \Delta \pS_{1}} =  \myE{\bbP}{ \Delta \pS_1} = 
         \mu^2, 
         \label{id:OospPlug-inPlug-in_E}
 \end{align}
together with
    \begin{align*}
        \myV{\bbP}{(\dest - \mu) \Delta \pS_{1}} 
        = 
        \myE{\bbP}{(\dest - \mu)^2} 
        \myE{\bbP}{\Delta \pS_{1}^2} 
        = 
        \frac{\sigma^2}{N}
        (\mu^2 + \sigma^2).
    \end{align*}
\end{proof}

