\OospUAIidEntrEntr*

\begin{proof}
By the same arguments as in \Cref{lem:OospUAIidEntrEntr} and $\bfa \in \calA$,
\begin{align*}
\mv^\frakP_{\lambda'} \left( \hat{\mv}_\lambda \left( \lbrace \bfa (\Delta S_t + \peps) \rbrace_{t \in \timesteps} \right) \right)
    &= \mv^\frakP_{\lambda'}\left( \bfa( \dest + \peps) - \frac{\lambda}{2}\bfa^2 \sest \right)
\end{align*}
and thus
\begin{align*}
    \mv^\frakP_{\lambda'}\left( \bfa( \dest + \peps) - \frac{\lambda}{2}\bfa^2 \sest \right) &= \myE{\frakP}{\bfa( \dest + \peps) - \frac{\lambda}{2} \bfa^2 \sest } - \frac{\lambda'}{2} \myV{\frakP}{\bfa( \dest + \peps) - \frac{\lambda}{2} \bfa^2 \sest} \\
    &= \bfa \dest - \frac{\lambda}{2} \bfa^2 \sest  - \frac{\lambda'}{2} \bfa^2\myV{\frakP}{ \peps} \\
    &= \bfa \dest - \frac{\lambda}{2} \bfa^2 \sest \left( 1 + \frac{\lambda'}{\lambda N}\right).
\end{align*}
Hence, the strategy $\bfar$ maximizing the objective can be expressed as
\begin{align*}
    \bfar :=  \frac{\dest}{\lambda  \sest(1 + \frac{\lambda'}{\lambda N})}.
\end{align*}
A straightforward computation shows that
\begin{align*}
    \bfar = \frac{\lambda N}{\lambda N + \lambda'} \bfan.
\end{align*}

By employing results \eqref{id:OospPlug-inPlug-in_E} and \eqref{id:OospPlug-inPlug-in_V}, we receive for $x \in \R$
\begin{align*}
	\mv^\bbP_\lambda\left(x \, \bfan \Delta \pS_{1}\right)
        &=\mv^\bbP_\lambda\left(x \frac{\dest}{\lambda \sigma^2} \Delta \pS_{1}\right)\\
        &=x \myE{\bbP}{  \frac{\dest}{\lambda \sigma^2} \Delta \pS_{1}} - \frac{\lambda}{2} x^2 \myV{\bbP}{ \frac{\dest}{\lambda \sigma^2} \Delta \pS_{1}} \\
        &=x \myE{\bbP}{ \frac{\mu}{\lambda \sigma^2} \Delta \pS_{1}}
        - \frac{\lambda}{2} x^2\left(\myV{\bbP}{ \frac{\mu}{\lambda \sigma^2} \Delta \pS_{1}} +   \frac{\mu^2 + \sigma^2}{N \lambda^2 \sigma^2}\right) \\
        &=x \frac{\mu^2}{\lambda \sigma^2}
        - x^2 \frac{2N\mu^2 + \mu^2 + \sigma^2}{2N \lambda \sigma^2} \\
        &= \frac{x}{\lambda \sigma^2} \left(\mu^2 \left( 1 - \frac{x}{2} \right) - \frac{x(\mu^2 + \sigma^2)}{2N} \right)
\end{align*}
and hence for $x_N := \lambda N / (\lambda N + \lambda')$,
\begin{align*}
    \mv^\bbP_\lambda\left( \bfar \Delta \pS_{1}\right) 
    &= \frac{x_N}{\lambda \sigma^2} \left(\mu^2 \left( 1 - \frac{x_N}{2} \right) - \frac{x_N(\mu^2 + \sigma^2)}{2N} \right).
\end{align*}
\end{proof}

\begin{lem}
\label{lem:UaIsBetter}
    The uncertainty-aware out-performs the plug-in policy if and only if 
    \begin{align*}
         \mu^2 \frac{(N-1)\lambda'  - 2N \lambda }{2N\lambda  + \lambda'} < \sigma^2, 
    \end{align*}
    implying that the robustification is necessarily successful, whenever 
    \begin{align*}
        \lambda' < \frac{2N}{N-1}\lambda.
    \end{align*}
\end{lem}
\begin{proof}
Set 
\[
x_N = \frac{\lambda N}{\lambda N + \lambda'}.
\]
The out‐of‐sample value of the uncertainty‐aware policy is
\[
\frac{x_N}{\lambda\sigma^2}\Bigl[\mu^2\Bigl(1-\tfrac{x_N}{2}\Bigr) - \frac{x_N(\mu^2+\sigma^2)}{2N}\Bigr],
\]
while the plug‐in policy yields
\[
\frac{\mu^2}{2\lambda\sigma^2} - \frac{\mu^2+\sigma^2}{2N\lambda\sigma^2}.
\]
Thus the former exceeds the latter exactly when
\[
\frac{x_N}{\lambda\sigma^2}\Bigl[\mu^2(1-\tfrac{x_N}{2}) - \tfrac{x_N(\mu^2+\sigma^2)}{2N}\Bigr]
>
\frac{\mu^2}{2\lambda\sigma^2} - \frac{\mu^2+\sigma^2}{2N\lambda\sigma^2}.
\]
Multiply both sides by $2N\lambda\sigma^2>0$:
\[
2N x_N\mu^2\Bigl(1-\tfrac{x_N}{2}\Bigr)
- x_N^2(\mu^2+\sigma^2)
>
N\mu^2 - (\mu^2+\sigma^2).
\]
Expand and collect terms:
\[
2N x_N\mu^2 - N x_N^2\mu^2 - x_N^2\mu^2 - x_N^2\sigma^2
>
N\mu^2 - \mu^2 - \sigma^2,
\]
\[
\mu^2\bigl(2N x_N - N x_N^2 - x_N^2 - N + 1\bigr)
>
-\,\sigma^2(1 - x_N^2).
\]
Note that
\[
2N x_N - N x_N^2 - x_N^2 - N + 1
= -\,N(x_N^2 - 2x_N + 1) - (x_N^2 - 1)
= -\,(1 - x_N)\bigl(N(1 - x_N) - (1 + x_N)\bigr).
\]
Hence
\[
-\,\mu^2(1 - x_N)\bigl(N(1 - x_N) - (1 + x_N)\bigr)
>
-\,\sigma^2(1 - x_N^2),
\]
\[
\mu^2(1 - x_N)\bigl(N(1 - x_N) - (1 + x_N)\bigr)
<
\sigma^2(1 - x_N^2).
\]
Since $0 < x_N < 1$, divide by $(1 - x_N)(1 + x_N)$ to get
\[
\mu^2\frac{N(1 - x_N) - (1 + x_N)}{\,1 + x_N\,} < \sigma^2.
\]
Finally, substitute 
\[
1 - x_N = \frac{\lambda'}{\lambda N + \lambda'}, 
\quad
1 + x_N = \frac{2\lambda N + \lambda'}{\lambda N + \lambda'}.
\]
Then
\[
N(1 - x_N) - (1 + x_N)
= \frac{N\lambda' - (2\lambda N + \lambda')}{\lambda N + \lambda'}
= \frac{(N-1)\lambda' - 2N\lambda}{\lambda N + \lambda'},
\quad
1 + x_N = \frac{2\lambda N + \lambda'}{\lambda N + \lambda'}.
\]
Thus
\[
\frac{N(1 - x_N) - (1 + x_N)}{\,1 + x_N\,}
= \frac{(N-1)\lambda' - 2N\lambda}{2N\lambda + \lambda'},
\]
and the inequality becomes
\[
\mu^2 \frac{(N-1)\lambda' - 2N\lambda}{2N\lambda + \lambda'} < \sigma^2,
\]
as claimed. Finally, since $2N\lambda + \lambda'>0$, this holds in particular whenever $(N-1)\lambda' - 2N\lambda < 0$, i.e.\ $$\lambda' < \frac{2N}{N-1}\lambda.$$
\end{proof}

\OospUAIidEntrCVaR*

\begin{proof}
Since we have chosen $\peps \sim \calN(0, \sest/N)$, we can compute for every $\bfa \in \calA$
\begin{align*}
    \cvar^\frakP_{\alpha} \left( \hat{\mv}_\lambda \left( \lbrace \bfa (\Delta S_t + \peps) \rbrace_{t \in \timesteps} \right) \right) &= \cvar^\frakP_{\alpha}\left( \bfa (\dest + \peps) - \frac{\lambda}{2}\bfa^2\sest \right) \\
    &= \left( \bfa \dest - \frac{\lambda}{2}\bfa^2 \sest \right) - A \vert \bfa \vert \sqrt{\frac{\sest}{N}} 
\end{align*}
where $A := \phi(\Phi^{-1}(\alpha))/\alpha$. Here, $\phi(\cdot)$ denotes the probability density function and $\Phi^{-1}(\cdot)$ the quantile function of the standard normal distribution. Note that we have to use the absolute value of $\bfa$ to apply that formula, since negative factorized random variables have their worst scenarios at the other tail. 

Point-wise maximization of the above expression results in 
\begin{align}
    \bfarr = \sign(\dest)\frac{\Big(\vert \dest \vert -   A \sqrt{\frac{\sest}{N}}\Big)_+}{\lambda \sest}
\end{align}
where $\sign(\cdot)$ is the sign operator and $(\cdot)_+$ is the restriction to the positive orthant.


Eventually, we calculate again the out-of-sample performance
\begin{align}
	\mv^\bbP_\lambda\left( \bfarr \Delta \pS_{1}\right) &=
	\mv^\bbP_\lambda\left(\sign(\dest)\frac{\Big(\vert \dest \vert -   A \sqrt{\frac{\sest}{N}}\Big)_+}{\lambda \sest} \Delta \pS_{1}\right). \label{id:OOSPcvar}
\end{align}
Using the assumption $\sest \equiv \sigma^2$, we see that
\begin{align*}
    & \mv^\bbP_\lambda\left(\sign(\dest)\frac{\Big(\vert \dest \vert -   A \sqrt{\frac{\sest}{N}}\Big)_+}{\lambda \sest} \Delta \pS_{1}\right) \\
     = & \mu \myE{\bbP}{\sign(\dest)\frac{\Big(\vert \dest \vert - A \sqrt{\frac{\sest}{N}}\Big)_+}{\lambda \sest}} 
    - \frac{\lambda \sigma^2}{2}\myE{\bbP}{\left(\frac{\Big(\vert \dest \vert - A \sqrt{\frac{\sest}{N}}\Big)_+}{\lambda \sest}\right)^2} 
    - \frac{\lambda \mu^2}{2}\myE{\bbP}{\sign(\dest)\frac{\Big(\vert \dest \vert - A \sqrt{\frac{\sest}{N}}\Big)_+}{\lambda \sest}}
\end{align*}

We compute 
\begin{align*}
    &2\myE{\bbP}{\sign(\dest)\Big(\vert \dest \vert - A \sqrt{\frac{\sest}{N}}\Big)_+}\\
    &=\frac{\mu ^2 \sqrt{N} \erf\left(\frac{\sqrt{\left(A \sigma +\mu  \sqrt{N}\right)^2}}{\sqrt{2} \sigma }\right)}{\sqrt{\left(A \sigma +\mu  \sqrt{N}\right)^2}}
    +\mu  \erf\left(\frac{\mu  \sqrt{N}-A \sigma }{\sqrt{2} \sigma }\right)
    - \frac{A \mu  \sqrt{N} \sigma  \erf\left(\frac{\sqrt{\left(A \sigma +\mu  \sqrt{N}\right)^2}}{\sqrt{2} \sigma }\right)}{\sqrt{N \left(A \sigma +\mu  \sqrt{N}\right)^2}} \\
    &-\frac{A \sigma  \erf\left(\frac{\mu  \sqrt{N}-A \sigma }{\sqrt{2} \sigma }\right)}{\sqrt{N}}
    +\frac{A \sigma  \erfc\left(\frac{A \sigma +\mu  \sqrt{N}}{\sqrt{2} \sigma }\right)}{\sqrt{N}}
    - \frac{\sqrt{\frac{2}{\pi }} \sigma  e^{-\frac{\left(A \sigma +\mu  \sqrt{N}\right)^2}{2 \sigma ^2}}}{\sqrt{N}}
    + \frac{\sqrt{\frac{2}{\pi }} \sigma  e^{-\frac{\left(\mu  \sqrt{N}-A \sigma \right)^2}{2 \sigma ^2}}}{\sqrt{N}}
    - \frac{A \sigma }{\sqrt{N}}\\
    &+\frac{\sqrt{\mu ^2 N} \erf\left(\frac{\sqrt{\mu ^2 N}}{\sqrt{2} \sigma }\right)}{\sqrt{N}}
    - \mu  \erf\left(\frac{\mu  \sqrt{N}}{\sqrt{2} \sigma }\right)
    + 2 \mu \Bigg)
\end{align*}
where $\erf(\cdot) := 2/\sqrt{\pi} \int_0^\cdot \exp(-x^2) dx$  and $\erfc(\cdot) = 1 - \erf(\cdot)$. Furthermore,
\begin{align*}
    2N\myE{\bbP}{\left(\Big(\vert \dest \vert - A \sqrt{\frac{\sest}{N}}\Big)_+\right)^2} &= \left(\left(A^2+1\right) \sigma ^2-2 A \mu  \sqrt{N} \sigma +\mu ^2 N\right) \erfc\left(\frac{A \sigma -\mu  \sqrt{N}}{\sqrt{2} \sigma }\right) \\
    & + \left(\left(A^2+1\right) \sigma ^2+2 A \mu  \sqrt{N} \sigma +\mu ^2 N\right) \erfc\left(\frac{A \sigma +\mu  \sqrt{N}}{\sqrt{2} \sigma }\right) \\
    & - \sqrt{\frac{2}{\pi }} \sigma  e^{-\frac{\left(A \sigma +\mu  \sqrt{N}\right)^2}{2 \sigma ^2}} \left(A \sigma  \left(e^{\frac{2 A \mu  \sqrt{N}}{\sigma }}+1\right)-\mu  \sqrt{N} \left(e^{\frac{2 A \mu  \sqrt{N}}{\sigma }}-1\right)\right).
\end{align*}
Thus, we obtain a closed form expression of \eqref{id:OOSPcvar}.
\end{proof}


\UAStratLimits*
\begin{proof}[Proof of Corollary~\ref{cor:UAStratLimits}]
We begin with the entropic uncertainty-aware strategy from Lemma~\ref{lem:OospUAIidEntrEntr}, which has the analytic form
\[
\bfar = \frac{\lambda N}{\lambda N + \lambda'} \bfan =: x_N \bfan,
\]
where $x_N := \frac{\lambda N}{\lambda N + \lambda'}$.

\begin{itemize}
    \item As $\lambda' \to 0$, we have $x_N \to 1$, hence $\bfar \to \bfan$.
    \item As $\lambda' \to \infty$, we have $x_N \to 0$, hence $\bfar \to 0$.
    \item As $N \to \infty$, we have $x_N \to 1$, so again $\bfar \to \bfan$.

    But since $\bfan = \dest  / (\lambda \sest)$ and $\dest \to \mu$, $\sest \to \sigma^2$ as $N \to \infty$, we conclude $\bfan \to \bfao := \mu / (\lambda \sigma^2)$.
    Therefore, $\bfar \to \bfao$ as $N \to \infty$.
\end{itemize}

Next, for the CVaR-based uncertainty-aware strategy from Lemma~\ref{lem:OospUAIidEntrCVaR}, we have
\[
\bfarr = \left( \bfan - \sign(\dest)\frac{A \sqrt{\frac{\sest}{N}}}{\lambda \sest} \right)\myind{\dest^2 \geq A^2 \frac{\sest}{N}},
\]
where $A := \phi(\Phi^{-1}(\alpha)) / \alpha$.

\begin{itemize}
    \item As $\alpha \to 1$, we have $A \to 0$, so the indicator condition $\dest^2 \geq A^2 \sest / N$ is always satisfied and the correction term vanishes. Therefore, $\bfarr \to \bfan$.
    \item As $\alpha \to 0$, we have $A \to \infty$, so the indicator becomes zero with probability one, hence $\bfarr \equiv 0$.
    \item As $N \to \infty$, the term $A \sqrt{\sest / N} \to 0$ and $\dest \to \mu$, $\sest \to \sigma^2$, thus the indicator becomes 1 for large $N$ and the correction vanishes. Therefore, $\bfarr \to \bfao := \mu / (\lambda \sigma^2)$.
\end{itemize}
\end{proof}



\section{Results for Section \texorpdfstring{\Cref{sec:CVaRGradientDescent}}{Section 5}}
\subsection{Details of \texorpdfstring{\Cref{thm:CVARSGD-randomk}}{Theorem 5.2}}\label{app:ProofCVaRSG}

\CVARSDGTHM*

\begin{proof}
\textbf{Convexity and Lipschitz continuity.} Using the Rockafellar--Uryasev representation of $\cvar$ \cite{RockafellarUryasev00},
\[
\cvar_\alpha(Z) = \min_{\zeta \in \mathbb{R}} \left\{ \zeta + \frac{1}{\alpha} \mathbb{E}\left[ (Z - \zeta)_+ \right] \right\},
\]
we write
\[
\mathcal{L}(\phi) = \min_{\zeta \in \mathbb{R}} \left\{ \zeta + \frac{1}{\alpha} \mathbb{E}_{\bbP \sim \ModelDist} \left[ (J(X(a_\phi), \bbP) - \zeta)_+ \right] \right\}.
\]
Because $J(X(a_\phi), \bbP)$ is convex in $\phi$ and the hinge function $(\cdot - \zeta)_+$ is jointly convex, the full objective is convex in $\phi$. The bound on $\|\nabla_\phi J\|$ implies that $\mathcal{L}$ is $\rho$-Lipschitz.

\textbf{Unbiased sub-gradient via random $k$.} Let $J_\phi(\bbP) := J(X(a_\phi), \bbP)$ and let $\zeta_\phi := \mathrm{VaR}_\alpha(J_\phi)$. Then,
\[
\nabla_\phi \mathcal{L}(\phi) = \frac{1}{\alpha} \mathbb{E}_{\bbP \sim \ModelDist} \left[ \nabla_\phi J(X(a_\phi), \bbP) \cdot \mathbf{1}_{J_\phi(\bbP) \leq \zeta_\phi} \right].
\]
We now draw $m$ i.i.d. samples $\bbP_1, \dots, \bbP_m \sim \ModelDist$, compute $J_i := J(X(a_\phi), \bbP_i)$ and $g_i := \nabla_\phi J(X(a_\phi), \bbP_i)$, and recall that $k$ is a random integer with $\mathbb{E}[k] = \alpha m$.
Let $I(\phi)$ be the indices of the $k$ smallest $J_i$. Define the stochastic gradient estimator
\[
\widehat{g}(\phi) := \frac{1}{k} \sum_{i \in I(\phi)} g_i.
\]
By symmetry and independence, the distribution of the $k$ smallest elements ensures
\[
\mathbb{E}[\widehat{g}(\phi)] = \frac{1}{\alpha} \mathbb{E}_{\bbP \sim \ModelDist} \left[ \nabla_\phi J(X(a_\phi), \bbP) \cdot \mathbf{1}_{J_\phi(\bbP) \leq \zeta_\phi} \right] = \nabla_\phi \mathcal{L}(\phi).
\]
Hence, $\widehat{g}(\phi)$ is an unbiased stochastic sub-gradient. Its norm is bounded by $\rho$ by assumption.

\textbf{Apply SGD convergence.} All conditions of \cite[Theorem 14.8]{ShalevBen14} are satisfied: convex domain, unbiased sub-gradient with norm $\leq \rho$, Lipschitz objective, and learning rate $\eta_t = {B}/({\rho \sqrt{t}})$. The theorem then yields the expected bound
\[
\mathbb{E}[\mathcal{L}(\bar{\phi}_t)] - \min_{\phi \in \Phi} \mathcal{L}(\phi) \leq \frac{B \rho}{\sqrt{t}}.
\]
\end{proof}

