\MDCVARStrategy*
\begin{proof}
We compute
    \begin{align*}
    \bfarr 
    & = \argmax_{\Strategy \in \R} 
    \cvar_{\alpha}\Big(
    \entr_\lambda
    \big(
        a \Delta S_1
        ~ \big| ~
        S_1 \sim \calN(\mu, \sigma)
    \big)
    ~ \Big| ~
    \mu \sim \calN(\hat{\mu}, \Sigma/N)
    \Big)\\
    & = \argmax_{\Strategy \in \R} 
    \cvar_{\alpha}\Big(
    a^\intercal\mu \;-\;\frac{\lambda}{2}\,a^\intercal\Sigma\,a
    ~ \Big| ~
    \mu \sim \calN(\hat{\mu}, \Sigma/N)
    \Big)\\
    & = \argmax_{\Strategy \in \R} 
    \cvar_{\alpha}\Big(
    a^\intercal\mu 
    ~ \Big| ~
    \mu \sim \calN(\hat{\mu}, \Sigma/N)
    \Big)\;-\;\frac{\lambda}{2}\,a^\intercal\Sigma\,a\\
    & = \argmax_{\Strategy \in \R} 
    \underbrace{
    a^\top\hat\mu
    -\kappa_\alpha\sqrt{\tfrac{a^\top\Sigma a}{N}}
    -\frac{\lambda}{2}\,a^\top\Sigma\,a}_{:= \widetilde J(a)},
\end{align*}
where the last line follows from $\cvar_\alpha$ on normal random variables.

\textbf{(i) Zero‐investment region at \(a=0\).}  The subgradient of \(\widetilde J\) at \(0\) is
\[
\partial\widetilde J(0)
=\Bigl\{\hat\mu-\kappa_\alpha\tfrac{\Sigma^{1/2}u}{\sqrt N}\;\Big|\;\|u\|=1\Bigr\}.
\]
Hence \(0\) is optimal iff 
\(\max_{\|u\|=1}\langle\hat\mu,u\rangle\le \kappa_\alpha/\sqrt N\max_{\|u\|=1}\|\Sigma^{1/2}u\|\),
i.e.\ \(\|\Sigma^{-1/2}\hat\mu\|\le \kappa_\alpha/\sqrt N\).

\textbf{(ii) Outside the zero-investment region.}  For \(\|\Sigma^{-1/2}\hat\mu\|>\kappa_\alpha/\sqrt N\), symmetry implies the maximizer lies on the ray
\(\;a=c\,\Sigma^{-1}\hat\mu,\;c>0.\)
Set \(m=\|\Sigma^{-1/2}\hat\mu\|\), so
\[
a^\top\hat\mu=c\,m^2,
\qquad
\sqrt{a^\top\Sigma a}=c\,m.
\]
Then
\[
\widetilde J(c)
= c\,m^2
-\kappa_\alpha\frac{c\,m}{\sqrt N}
-\frac{\lambda}{2}\,c^2\,m^2.
\]
Differentiating w.r.t.\ \(c\) and setting to zero yields
\[
m^2-\kappa_\alpha\frac{m}{\sqrt N}-\lambda\,c\,m^2=0
\quad\Longrightarrow\quad
c^*
=\frac{1}{\lambda}\Bigl(1-\frac{\kappa_\alpha}{\sqrt{N}\,m}\Bigr).
\]
Since \(c^*>0\) precisely when \(m>\kappa_\alpha/\sqrt N\), we conclude
\[
\bfarr
=c^*\,\Sigma^{-1}\hat\mu
=\frac{1}{\lambda}
\Bigl(1-\frac{\kappa_\alpha}{\sqrt{N}\,\|\Sigma^{-1/2}\hat\mu\|}\Bigr)_+
\Sigma^{-1}\hat\mu,
\]
as claimed.
\end{proof}
