    \centering
    \includegraphics[width = \columnwidth]{EMFig1.pdf}
    \caption{Contributions to the dipolar vortex velocity. Panels show the gradient of the corresponding terms appearing in Eq.~\eqref{eqn:analytic_phase} with $\lambda=2$.}
