\noindent equation are given by 
\begin{equation}
    \frac{\partial}{\partial \vartheta'} \left[ \frac{n\left(\rho'\right)}{\rho'} \sqrt{\frac{\cos^2\vartheta' + \lambda^{-2}\sin^2\vartheta'}{\sin^2\vartheta' + \lambda^{-2}\cos^2\vartheta'}} \frac{\partial S}{\partial \vartheta'} \right] = 0.
\end{equation}
 It is clear that $n(\rho')/\rho'$ can be removed, and so the remaining terms in the square brackets must be a constant. Rearranging this, and dropping the partial derivative, we have 
\begin{equation}
    \frac{dS}{d\vartheta'} = c_1 \sqrt{\frac{\lambda^2\tan^2\vartheta'+1}{\lambda^2+\tan^2\vartheta'}},
\end{equation}
where $c_1$ is a constant. We integrate this to recover
\begin{equation}
    S(x,y) = c_1 \left\{F\left( z\big| \lambda^{-4}\right) + (\lambda^{-2}-1)\Pi\left(\lambda^{-2}; z\big|\lambda^{-4}\right)\right\} +c_2,
    \label{eqn:analytic_phase}
\end{equation}
where $z(x,y) = i\text{arcsinh}(\lambda^2y/x)$ and $c_2$ is a constant. Here, $F(z|n)$ is the incomplete elliptic integral of the first kind, and $\Pi(m;z|n)$ is the incomplete elliptic integral of the third kind \cite{Abramowitz1988Handbook}. In this form, it is instructive to visualize each individual contribution, as shown in Fig.~\ref{fig:speeds}. The  incomplete elliptic integrals of the first and third kind have derivatives
\begin{eqnarray}
    \frac{\partial F(z|n)}{\partial z} &=& \frac{1}{\sqrt{1-n\sin^2 z}}, \\
    \frac{\partial \Pi(m;z|n)}{\partial z} &=& \frac{1}{\left(1-m\sin^2 z\right)\sqrt{1-n\sin^2z}},
\end{eqnarray}
respectively. The constant $c_2$ is a phase shift, which can be set to zero. Transforming to Cartesian coordinates, we have 
\begin{widetext}
\begin{equation*}
    S(x,y) = q\Lambda\,\Bigg[\text{arcsc}\left(\frac{\lambda^2y}{x}\Bigg|1-\lambda^{-4}\right) + F\left(\text{arctan}\left(\frac{\lambda^2y}{x}\right)\Bigg|1-\lambda^{-4}\right) - \lambda^{-2}\Pi\left(1-\lambda^{-2};\text{arctan}\left(\frac{\lambda^2y}{x}\right)\Bigg|1-\lambda^{-4}\right)\Bigg]\,,\nonumber
\end{equation*}
\end{widetext}
where $\mathrm{arcsc}(z,n)$ is an inverse Jacobi Elliptic function. When transforming from shear polar  to Cartesian coordinates the second term in Eq.~\eqref{eqn:analytic_phase} changes sign.  The constant $\Lambda$ needs to be fixed such that $S(x,y)=\pm\pi$ when $\arctan(\lambda y/x)=\pm\pi$. This leads to 
\begin{equation}
   \Lambda = \pi \left[ 4 K\left(1-\lambda^{-4}\right)-2\lambda^{-2}\Pi\left(1-\lambda^{-2}\big|1-\lambda^{-4}\right)\right]^{-1},
\end{equation}
where $q$ is the charge of the vortex, and $K(n)=F(\pi/2,n)$ is the complete elliptic integral of the first kind. When evaluating Eq.~\eqref{eqn:elliptic_phase} numerically, one needs to be careful of the position of the branch-cut. In analogy to the $\texttt{atan2}$ function, we compute $S'(x,y)$, where \begin{align}
    S'(x,y) = \begin{cases}
    S(x,y) & \text{if } x > 0, \\
S(x,y) - \pi & \text{if } x < 0 \text{ and } y \geq 0, \\
S(x,y) + \pi & \text{if } x < 0 \text{ and } y < 0, \\
-\frac{\pi}{2} & \text{if } x = 0 \text{ and } y > 0, \\
+\frac{\pi}{2} & \text{if } x = 0 \text{ and } y < 0, \\
\text{undefined} & \text{if } x = 0 \text{ and } y = 0.
    \end{cases}
\end{align}

We observe that in the limit where $\lambda=1$, the Jacobi Elliptic function $\text{arcsc}(y/x\, | 0)=\arctan(y/x)$, the incomplete elliptic integrals $F\left[\arctan(y/x)\, | \,0\right]=\arctan(y/x)$ and $\Pi\left[0\, ; \arctan\left(y/x\right)\, |\, 0\right]=\arctan(y/x)$, while the complete elliptic integrals reduce to $  K(0)=\Pi(0,0)=\pi/2$. This means that Eq.~\eqref{eqn:elliptic_phase} reduces to the non-dipolar case, $S(x,y)=q\arctan(y/x)$ \cite{Fetter1966a}. 

