	\subsection{Stationary distribution}
	Consider a complete filtered probability space $(\Omega, \mathscr{F}, \mathbb{F}=\{\mathscr{F}_t\}_{t\geq0}, \mathbb{P})$ which supports an $\mathbb{F}$-adapted standard Brownian Motion $B$.
	\cite{difonzo2022stochastic} considered Langevin-type stochastic differential inclusions in the following form
	\begin{equation}
		\label{eqn:LSDI}
		d \widetilde{X}_t \in -\partialc U(\widetilde{X}_t)dt + \sqrt{2}d B_t,
	\end{equation}
	where $\partialc U$ is the Clarke subgradient defined in  \eqref{eqn:Clarke}.
	They showed some foundational results regarding the flow and asymptotic properties of \eqref{eqn:LSDI}. Specificially, in this continuous-time setting, they proved that there exists a strong solution to \eqref{eqn:LSDI} and the correspondence of a Fokker-Planck type equation to modeling the probability law associated with \eqref{eqn:LSDI}. Given that $\partialc U$ is the $\nabla U$ when the gradient exists, there is no doubt that although the Markov chain $\widetilde{X}$ possesses a unique stationary distribution, the distribution of its discrete discretization could differ from the target distribution \citep{Roberts1996Exponential}. We consider a further generalized setting using conservative field $D_U$ as follows:
	\begin{equation}
		\label{eqn:GLSDI}
		d X_t \in -D_U(X_t)dt + \sqrt{2}d B_t.
	\end{equation}	
	By Corollary 1 of \cite{bolte2021conservative}, restated as Proposition \ref{bolte2021conservative_prop}, the Clarke subgradient is a minimal convex conservative field, ensuring that the existence of a strong solution to \eqref{eqn:LSDI} implies the existence of a strong solution to \eqref{eqn:GLSDI}. 

	The MASLA is based on the Euler-Maruyama discretization of \eqref{eqn:GLSDI}, accepting or rejecting the proposal $\breve{Y}_{n+1}$ defined in \eqref{eqn:SELD}, using the MH scheme. Recall that $\cD_f$ denotes the set of points $x\in
	\RR^d$ where $f$ is differentiable.
	Then \eqref{eqn:SELD} can be rewritten as
	\begin{equation}
		\label{eqn:proposal_0}
		\breve{Y}_{n+1} = X_n - \gamma \beta(X_n)+ (2 \gamma)^{1/2} Z_{n+1}, 
	\end{equation}	
	where 
	\begin{equation}
		\begin{cases}
			\beta(x) = \nabla U(x)\quad&x\in \cD_U,  \\
			\beta(x) \in D_U(x)& \text{otherwise.}
		\end{cases}
		%\label{eq:clarkeSGD}
	\end{equation}
	\begin{theorem}
		\label{thm:stationary}
		Assume that at $\lambda$-almost every point of $x$ in the domain of function $U$, 
		there exists an open neighborhood $V_x$ of $x$, where $U$ is twice continuously differentiable (i.e., $ U \in C^2 $).  If the distribution of the initial random variable $X_0$ is absolutely
		continuous w.r.t. the Lebesgue measure, the MASLA chain $\{X_n\}$ has $\pi$ as a stationary distribution and is reversible w.r.t. $\pi$ for almost every $\gamma \in \mathbb{R}_+$.
	\end{theorem}

	\begin{proof}

		If the proposal transition density of $\breve{Y}_{n+1}$ exists, denoted by $q_{\gamma}$, 
		%i.e., for any $x,y \in \RR^d$,
		%\begin{equation}
		%	\label{eq:def_r_gamma_ULA}
		%	q_{\gamma}(x,y) = (4\pi \gamma)^{-d/2} \exp \Big\{-(4 \gamma)^{-1}\|y-x+ \gamma \beta(x)\|^2\Big\}.
		%\end{equation}
		the transition probability density of the MASLA chain can be written as
		\begin{equation}
			\label{eqn:p_gamma}
			p_{\gamma}(x,y)=q_{\gamma}(x,y)\alpha_{\gamma}(x,y),
		\end{equation}
		where 	
		\begin{equation}
			\label{eqn:acceptance_prob_gamma}
			\alpha_{\gamma}(x,y) = 1 \wedge \frac{\pi(y) q_{\gamma}(y,x)}{\pi(x) q_{\gamma}(x,y)}.
		\end{equation}
		Without loss of generality, suppose that
		$$\pi(y) q_{\gamma}(y,x)>\pi(x) q_{\gamma}(x,y).$$ In this case, on one hand
		$$\pi(x) p_{\gamma}(x,y)=\pi(x) q_{\gamma}(x,y)\cdot 1,$$
		and on the other hand by \eqref{eqn:p_gamma}
		$$\pi(y) p_{\gamma}(y,x)=\pi(y) q_{\gamma}(y,x)\cdot \frac{\pi(x) q_{\gamma}(x,y)}{\pi(y) q_{\gamma}(y,x)}=\pi(x) q_{\gamma}(x,y).$$
		The above two equations yield the detailed balance condition 
		$$\pi(x)p_{\gamma}(x,y)=\pi(y)p_{\gamma}(y,x),$$
		which implies that $\pi$ is a stationary distribution of the MASLA chain $X_n$ and this chain is reversible w.r.t. $\pi$.  Hence, it suffices to show that the proposal transition density of $\breve{Y}_{n+1}$ indeed exists.

		We define a simplified version 
		\begin{equation}
			\label{eqn:proposal_s}
			\widetilde{Y}_{n+1} = X_n - \gamma \nabla U(X_n)\mathbbm{1}_{\cD_U}(X_n)+ (2 \gamma)^{1/2} Z_{n+1}.
		\end{equation}	
		The Markov transition kernel of \eqref{eqn:proposal_s} is a function $\widetilde{Q}_{\gamma}:\RR^d\times \mathcal{B}(\RR^d)\rightarrow [0,1]$ defined as 
		\begin{equation*}
			%	\label{eqn:proposal_s}
			\widetilde{Q}_{\gamma}(x,dy)= \widetilde{q}_{\gamma}(x,\widetilde{y}) d\widetilde{y},
		\end{equation*}	
		where $\widetilde{q}_{\gamma}$ is defined as
		\begin{equation}
			\label{eq:widetilde_q}
			\widetilde{q}_{\gamma}(x,\widetilde{y}) = (4\pi \gamma)^{-d/2} \exp \Big\{-(4 \gamma)^{-1}\|\widetilde{y}-x+ \gamma \nabla U(x)\mathbbm{1}_{\cD_U}(x)\|^2\Big\}.
		\end{equation}
		Note that $\widetilde{Q}_{\gamma}$ as a Markov transition kernel satifies that $\widetilde{Q}_{\gamma}(\,\cdot\,,A)$ is measurable for any $A$ and $\widetilde{Q}_{\gamma}(x,\,\cdot\,)$ is a probability measure for any $x$. 
		%If $g:\mathbb R^d\to\mathbb R$ is a measurable function, $\widetilde{Q}_{\gamma}g$ represents the function on
		%$\mathbb R^d\to\mathbb R$ given by 
		%\begin{align*}
		%	\widetilde{Q}_{\gamma}g(x) = \int g(y)\widetilde{Q}_{\gamma}(x, d y),
		%\end{align*}
		%whenever the integral is well-defined. 
		For every measure $\rho\in {\mathcal P}(\mathbb R^d)$, we denote by $\rho \widetilde{Q}$ the measure given by 
		$$\rho \widetilde{Q}_{\gamma} = \int \rho(d x) \widetilde{Q}_{\gamma}(x, \cdot).$$  
		%We use the notation $\rho(g) = \int g d \rho$ whenever the integral is well-defined. 



		Let $\nu$ and $\nu'$ be two measures defined on the measurable space $(\Omega, \mathcal{F}, \mathbb{P})$. We write $\nu \ll \nu'$ to indicate that $\nu$ is absolutely continuous w.r.t. $\nu'$, meaning that $\nu'(A) = 0$ implies $\nu(A) = 0$ for all $A \in \mathcal{F}$. For any subset $K \subseteq \mathbb{R}^d$, define
		\begin{align}
			\label{eqn:def_CK}
			\mathcal{M}(K) =\Big\{ \nu \in \mathcal{M}(\mathbb{R}^d) : \nu \ll \lambda \text{ and } \operatorname{supp}(\nu) \subset K \Big\},
		\end{align}
		where $\operatorname{supp}(\nu)$ denotes the support of the measure $\nu$.
		Define $\Gamma$ as the set of all steps $\gamma>0$ such that $\widetilde{Q}_{\gamma}$ maps $\cM(\RR^d)$ into itself, i.e.,
		\begin{align}
			\label{eqn:def_Gamma}
			\Gamma = \Big\{\gamma\in \mathbb{R}_+\,:\, \forall \rho\in
			\cM(\RR^d),\ \rho\widetilde{Q}_{\gamma}\ll\lambda\Big\}.
		\end{align}
		Then, for any $\gamma\in \Gamma$, if the distribution of $X_n$ is Lebesgue-absolutely
		continuous (i.e. $\mu(X_n)\in\cM(\RR^d)$), then $\mu(\widetilde{Y}_{n+1} )\in\cM(\RR^d)$. 
		Next, by Proposition \ref{bolte2021conservative_prop}\ref{bolte2021conservative_prop_i} we have $\mathbb{P}(X_n\notin \cD_U)=0$, which yields that for any $n\in \mathbb{N}_+$,
		\begin{align}
			\label{eqn:as_equ_proposal}
			\mathbb{P}\big(\widetilde{Y}_{n+1}\neq \breve{Y}_{n+1}\mid X_n, Z_{n+1}\big)=0,
		\end{align}
		where $\breve{Y}_{n+1}$ is generated by \eqref{eqn:proposal_0}.
		Hence, $\mu(X_n)\in\cM(\RR^d)$ would also imply that $\mu(\breve{Y}_{n+1} )\in\cM(\RR^d)$, which further yields the existence of the proposal transition density 
		$q_{\gamma}(x,y)$ needed in \eqref{eqn:p_gamma}.

		So far we have established the existence for any $\gamma \in \Gamma$. The remaining question is how large the set $\Gamma$ is. Under the mild conditions assumed in this theorem ,we aim to show that the set $\Gamma^c \subset \mathbb{R}_+$ is Lebesgue negligible, i.e., it has Lebesgue measure zero. It suffices to show that for almost every $\gamma$,  
		we have that $g_{\gamma,z}$ defined as
		$$g_{\gamma,z}(x) = (x - \gamma \nabla U(x)) \1_{\cD_U}(x)+(2 \gamma)^{1/2}z$$
		is almost everywhere a local diffeomorphism.
		We define for each $x \in \RR^d$ the pseudo-hessian  $\cH(x) \in \RR^{d \times d}$ as
		\begin{equation*}
			\cH(x)_{i, j} = \limsup_{t \rightarrow 0} \frac{\scalarp{\nabla U(x + t e_j)\1_{\cD_U}(x+ te_j) - \nabla U(x)}{e_i}}{t} \1_{\cD_U}(x).
		\end{equation*}
		Since it is a limit of measurable functions, $\cH$ is $\cB(\RR^d) $ measurable, and if $U(\cdot)$ is twice differentiable at $x$ then $\cH(x)$ is just the ordinary hessian. Define
		\[
		l(x, \gamma) =
		\begin{cases}
			\det (\gamma \cH(x) - I), & \text{if every entry in } \cH(x) \text{ is finite}, \\
			1, & \text{otherwise},
		\end{cases}
		\]
		which is a $\cB(\RR^d)  \otimes \cB(\RR_{+})$ measurable function. By the inverse function theorem, we have that if $U(\cdot)$ is $C^2$ at $x$ and if $l(x, \gamma) \neq 0$, then $g_{\gamma,z}(\cdot)$ is a local diffeomorphism at $x$. Therefore $l(x, \gamma) \neq 0$ implies either $g_{\gamma,z}(\cdot)$ is a local diffeomorphism at $x$ or $U(\cdot)$ is not $C^2$ at $x$.
		Let $\lambda_{+}$ denote the usual measure on $\RR_{+}$. We  have by Fubini's theorem:
		\begin{equation*}
			\begin{split}
				\int \1_{l(x, \gamma) = 0}  \lambda(\dif x) \otimes \lambda_{+}(\dif \gamma) &= \int \lambda(\{ x: l(x,\gamma) = 0\}) \lambda_{+}(\dif \gamma)\\
				&=\int \int \1_{l(x, \gamma) = 0}  \lambda_{+}(\dif \gamma) \lambda(\dif x) \\
				&= 0,
			\end{split}
		\end{equation*}
		where the last equality comes from the fact that for $x$ fixed $l(x, \gamma) = 0$ only if $1/ \gamma$ is in the spectrum of $\cH(x)$ which is finite. Therefore, $\Gamma$ is a set of full measure and for $\gamma\in \Gamma$,
		$$\lambda(\{ x: l(x,\gamma) = 0\}) = 0.$$ 
		At last, for $A\subset \RR^d$, $\gamma \in \Gamma$ and $\rho \in \cM(\RR^d)$, by the definition of $\cM(\RR^d)$ in \eqref{eqn:def_CK}, 
		we have
		\begin{equation*}
			\rho \widetilde{Q}_{\gamma}(A) = \rho  \otimes\Phi(\{ (x, z) : g_{\gamma,z}(x) \in A\})  \leq \lambda \otimes \Phi(\{ (x, z) : g_{\gamma,z}(x) \in A\}),
		\end{equation*}
		where $\Phi$ is the cumulative distribution function (CDF) of the standard normal distribution.
		Then by Fubini's theorem,
		\begin{equation*}
			\begin{split}
				&\lambda \otimes \Phi(\{ (x, z) : g_{\gamma,z}(x) \in A\})\\
				&= \int \lambda\big(\{ (x, z) : g_{\gamma,z}(x) \in A\}\big) \Phi(\dif z) \\
				&= \int \lambda\Big(\big\{ (x, z) : g_{\gamma,z}(x) \in A \text{ and } g_{ \gamma,z}(\cdot) \text{ is a local diffeomorphism at } x\big\}\Big) \Phi(\dif z).
			\end{split}
		\end{equation*}
		By the separability of $\RR^d$, there is a countable family of open neighborhoods $(V_i)_{i \in \bbN}$ such that for any open set $O$ we have $O = \bigcup_{j \in J}V_j$. The set of $x$ where $g_{\gamma,z}(\cdot)$ is a local diffeomorphism is an open set, hence
		\begin{align*}
			&\Big\{ x: g_{\gamma,z}(x) \in A \text{ and } g_{\gamma,z}(\cdot) \text{ is a local diffeomorphism at } x\Big\}\\
			& = \bigcup_{i \in I} V_i \cap \{ x: g_{\gamma,z}(x) \in A \} \, .
		\end{align*}
		Since an image of a null set by a diffeomorphism is a null set we have
		\begin{equation*}
			\lambda\big(\{ x: g_{\gamma,z}(x) \in A \} \cap V_i\big) = 0,
		\end{equation*}
		which yields $\rho \widetilde{Q}_{\gamma}(A) = 0$ as desired. The proof is complete.
	\end{proof}	


