		\centering
		{\includegraphics[width = 4.5in]{pic/usla_vs_masla_histogram_h0.1}}
		\caption{Comparison the performance of USLA and MASLA chains with true density. Both chains were started with the same initial value, ran for 100,000 iterations with step size $\tau=0.1$, and then discarded $20\%$ as burn-in. }
		\label{fig:usla_vs_masla}
	\end{figure*}


