\end{figure*}
   Now we conduct the linear stability analysis of Eq.~(\ref{eqn13}). In the steady state, $\dot{r}_{1}=\dot{r}_{2}=0$ results in
   \begin{equation}\label{eqn14}
   \scalebox{0.93}{$
   \begin{aligned}
       G_{1}=\dot{r}_{1}=&-\Delta_{1} r_{1} + \frac{r_{1}(1 - r^{2}_{1}) \cos\beta_{1}}{2} \bigl[ K_{1}(A + Br_{2})^{p_{1}} \\
       &+ K_{2}(A + Br_{2})^{h_{1}} r^{2}_{1} \bigr]=0,\\
       G_{2}=\dot{r}_{2}=&-\Delta_{2} r_{2} + \frac{r_{2}(1 - r^{2}_{2}) \cos\beta_{2}}{2} \bigl[ K_{1}(A + Br_{1})^{p_{2}} \\
       &+ K_{2}(A + Br_{1})^{h_{2}} r^{2}_{2} \bigr]=0.
   \end{aligned}
   $}
   \end{equation}
   From Eq.~(\ref{eqn14}), it follows that $(r_{1},r_{2})=(0,0),(r^{*}_{1},0)$, and $(0,r^{*}_{2})$ constitute three trivial steady-state solutions of the two-dimensional reduced system (\ref{eqn13}), where $r^{*}_{l}$ is given by,
   \begin{equation}\label{eqn15}
   \scalebox{0.7}{$
   \begin{aligned}
       r^{*}_{l}=\sqrt{\frac{\bigl[ (K_{2}A^{h_{l}}-K_{1}A^{p_{l}})\cos\beta_l \bigr]\pm \sqrt{\cos^{2}\beta_l(K_{2}A^{h_{l}}+K_{1}A^{p_{l}})^2-8\Delta_lK_{2}A^{h_{l}}\cos\beta_l}}{2K_{2}A^{h_{l}}\cos\beta_{l}}},\\ l=1,2.
   \end{aligned}
   $}
   \end{equation}

   Beyond the aforementioned trivial steady states, one can also identify steady states of the form $(r^{*}_{1},r^{*}_{2})\neq(0,0)$. These non-trivial steady states, which depend on all system parameters, are generally not amenable to analytical solutions. Consequently, we determine them by numerically solving the coupled equations $G_{1}=0$ and $G_{2}=0$, as given in Eq.~(\ref{eqn14}).
   \par Now, to examine the stability of all steady-state solutions, we compute the Jacobian matrix associated with the dynamical system described in Eq.~(\ref{eqn13}) and check the eigen values of it in each case of the steady states. The elements of the Jacobian are given by the partial derivatives of $G_{l}$ with respect to $r_{j}$, where
   \begin{equation}\label{eqn16}
   \scalebox{0.75}{$
   \begin{aligned}
       \frac{\partial G_1}{\partial r_1}&=-\Delta_1+\frac{\cos\beta_1}{2}\bigl[ K_{1}(A+Br_{2})^{p_{1}}(1-3r^2_{1})+K_2(A+Br_{2})^{h_{1}}(3r^2_{1}-5r^4_{1}) \bigr], \\
       \frac{\partial G_1}{\partial r_2}&=\frac{r_1(1-r^2_{1})\cos\beta_{1}}{2}\bigl[ K_1 p_1 B(A+Br_2)^{p_1-1}+K_2 h_1 B(A+Br_2)^{h_1-1} \bigr], \\
       \frac{\partial G_2}{\partial r_1}&=\frac{r_2(1-r^2_{2})\cos\beta_{2}}{2}\bigl[ K_1 p_2 B(A+Br_1)^{p_2-1}+K_2 h_2 B(A+Br_1)^{h_2-1} \bigr], \\
       \frac{\partial G_2}{\partial r_2}&=-\Delta_2+\frac{\cos\beta_2}{2}\bigl[ K_{1}(A+Br_{1})^{p_{2}}(1-3r^2_{2})+K_2(A+Br_{1})^{h_{2}}(3r^2_{2}-5r^4_{2}) \bigr].
   \end{aligned}
   $}
   \end{equation}
   For the trivial steady state $(0,0)$,  the Jacobian matrix becomes diagonal, and hence, its eigenvalues are given directly by the diagonal elements, $\lambda_l=-\Delta_l+\frac{K_1A^{p_l}\cos\beta_l}{2}$ for $l=1,2$. The incoherent state remains stable as long as both eigenvalues are negative. However, when one of the eigenvalues becomes non-negative for certain parameter values, the incoherent state loses stability and becomes a saddle point. The corresponding parameter value then marks the onset of synchronization. Hence, the incoherent state $(0,0)$ remains stable as long as
   \begin{equation}
       K_1<\mathrm{min}\left\{\frac{2\Delta_l}{A^{p_l}\cos\beta_l}\right\},~\mathrm{for}~l=1,2. \label{eqn17}
   \end{equation}
   Otherwise, the state becomes unstable. The forward critical coupling threshold, denoted by $K_1^*=\mathrm{min}\left\{\frac{2\Delta_l}{A^{p_l}\cos\beta_l}\right\}$, is independent of the influence of higher-order interactions and their associated adaptation mechanisms. Furthermore, the stability properties of the other non-trivial steady states are determined numerically using the conditions derived from Eq.~(\ref{eqn16}).





