Provided the proposition above and the relation of $\mathbf{p}_{\ell;L}$ with the inverse binomial transformation of the sequence $(\mathbf{b}_{n,L})_{n\leq L}$ (see \eqref{p-inv}), it is clear that the $\text{PMM}_L(\ell)$ is a gradient model as-well. The precise expressions for the quantities involved in the gradient property, for the reduced PMM, can be identified from a decomposition of the ones associated with the Bernstein model. This is performed in Lemma \ref{lem:p-grad}. 

In subsection \ref{subsec:further} we prove other properties of the main models, both dynamic and algebraic. Concretely, we prove Propositions \ref{prop:B-prop} and \ref{prop:P-prop} below, summarizing also all the other more elementary properties of these models.

\begin{Prop}\label{prop:B-prop}
For each $n,L\in\mathbb{N}$ with $L\geq n$, the B($n$,$L$) enjoys the following properties:
    \begin{enumerate}[label=(\roman*)]

    \item \textit{Partition of the unity}: for any integer $ 0<L<N/2 $ it holds that
    \begin{align}
    \mathcal{L}_N^{\text{SSEP}}
    =\sum_{n=0}^L\mathcal{L}_N^{n,L};
    \end{align}

    \item \textit{Symmetry}: for any $\eta\in \Omega_N$ it holds that $\mathbf{b}_{n,L}(\eta)=\mathbf{b}_{L-n,L}(\overline{\eta})$, with $\eta\mapsto\overline{\eta}$ the map that exchanges the particles by vacant sites and vice-versa;

    \item \textit{Interpolation}: for each $n\in\mathbb{N}_+$ it holds that \textnormal{B($n$,$n$)$=$PMM($n$)};

    \item \textit{Range}: For each $\eta\in\Omega_N$ it holds that $\mathbf{b}_{n,L}(\eta)\in [0,1]$. 

    \item \textit{Blocked configurations}: there is $\eta\in\Omega_N$ such that $\mathbf{b}_{n,\ell}(\tau^x\eta)=0$ for any $x\in\mathbb{T}$;

    \item \textit{Mobile Clusters}: any box of length $L+2$ with exactly $n+1$ particles constitutes a mobile cluster. 
\end{enumerate}
\end{Prop}

\begin{Prop}\label{prop:P-prop}
    For each natural number $L<N$ fixed and any $0\leq \ell\leq L$, it holds that 
\begin{enumerate}[label=(\roman*)]
        \item \textit{Mobile Clusters}: any box of length $L+2$ with \textit{at least} $\ell+1$ particles and at least one vacant site is a mobile cluster;

        \item There are blocked configurations; 

        \item Interpolation: $\text{PMM}_L(L)=\text{PMM}(L)$;

        \item \textit{Range}: For each $\eta\in\Omega_N$ it holds that $\mathbf{p}_{\ell;L}(\eta)\in [0,1]$. 

        \item Monotony: the sequence $(\mathbf{p}_{\ell;L})_{0\leq \ell\leq L}$ is non-increasing;

        \item Equilibrium expected value: for any $\rho\in[0,1]$, it holds that  $\int_{\Omega_N}
            \mathbf{p}_{\ell;L}\rmd\nu_\rho^N=\alpha^\ell$.
    \end{enumerate}
\end{Prop}



\section{Characterization of the collection of models}\label{sec:char}

\subsection{Binomial Transformation}\label{subsec:bin}

We start by showing Proposition \ref{prop:identity}, relating the Bernstein and reduced PMM via the binomial transformation.
