\begin{Lemma}[Inversion formula]\label{lem:inverse}
For each $n,L\in\mathbb{N}$ with $L>n$, it holds that
    \begin{align}\label{p-inverse}
    \mathbf{p}_{\ell;L}(\eta)
    &=\sum_{n=\ell}^L
    \frac{\binom{n}{\ell}}{\binom{L}{\ell}}
    \mathbf{b}_{n,L}.
\end{align}
\end{Lemma}
\begin{proof}
    It is enough to express, for each $0\leq j\leq L$,
\begin{align}
    \mathbf{p}_{\ell;L}^j(\eta)
    =    
    \frac{\binom{m_j^L(\eta)}{\ell}}{\binom{L}{\ell}}
    \mathbf{1}_{
    \{
    m_j^L(\eta)\geq \ell
    \}
    }
    =\sum_{n=\ell}^L
    \frac{\binom{n}{\ell}}{\binom{L}{\ell}}
    \mathbf{1}_{
    \{
    m_j^L(\eta)=n
    \}
    }
    % =
    % \sum_{n=\ell}^L
    % \frac{\binom{n}{\ell}}{\binom{L}{\ell}}
    % \mathbf{b}_{n,L}(\eta).
\end{align}
and identify $\mathbf{1}_{
    \{
    m_j^L(\eta)=n
    \}
    }
    =\mathbf{b}_{n,L}^j(\eta)$. 
\end{proof}

In order to prove the next lemma it will be convenient to introduce some notation.
\begin{Def}\label{def:sets}
    Let $A,P\subseteq\mathbb{T}_N$ , $a\in\mathbb{T}_N$ and $L\in\mathbb{N}$ be arbitrarily fixed. We write ${\eta^P(a)}:=\mathbf{1}_{a\notin P}\eta(a)+\mathbf{1}_{a\in P}(1-\eta(a))$ and ${\eta(A)}:=\prod_{a\in A}\eta(a)$. Consequently, $\eta^P(A)=\prod_{a\in A}\eta^P(a)$. Moreover, let {$\mathcal{P}_L(A)$} denote all the subsets of $A$ with exactly $L$ elements. For $L>|A|$ and $L=0$ by convention $\mathcal{P}_L(A)=\emptyset$;

    % \begin{itemize}
    %     \item We write ${\eta^P(a)}:=\mathbf{1}_{a\notin P}\eta(a)+\mathbf{1}_{a\in P}(1-\eta(a))$ and ${\eta(A)}:=\prod_{a\in A}\eta(a)$. Consequently, $\eta^P(A)=\prod_{a\in A}\eta^P(a)$;

    %     \item Let {$\mathcal{P}_L(A)$} denote all the subsets of $A$ with exactly $L$ elements. For $L>|A|$ and $L=0$ by convention $\mathcal{P}_L(A)=\emptyset$;
    % \end{itemize}
\end{Def}


\begin{Lemma}[Transformation to monomials]\label{lem:decomp}
For each $n,L\in\mathbb{N}$ with $L>n$, it holds that
    \begin{align}\label{b-p_base}
%         \mathbf{b}_{n,L}=
% \sum_{\ell=0}^{L-n}
% (-1)^\ell
% \binom{L}{n}\binom{L-n}{\ell}
% \mathbf{p}_{n+\ell;L}
% .
\mathbf{b}_{n,L}=
\sum_{\ell=n}^{L}
(-1)^{\ell-n}
\binom{L}{\ell}\binom{\ell}{n}
\mathbf{p}_{\ell;L}
.
\end{align}
\end{Lemma}

\begin{proof}
Recalling \eqref{rate:b}, for each $0\leq j\leq L$, from the distributive rule one can express 
% \begin{align}\label{cons:pmm-gen2}	
%     \mathbf{b}_{n,L}^j
%     =\frac{1}{\binom{L}{n}}
%     \sum_{i=1}^{\binom{L}{n}}
%     \eta^{-j+P_{ij}}(-j+M_j)
%     .
% \end{align} 
\begin{align}\label{cons:monomial}	
    \mathbf{b}_{n,L}^j
    &=
    \sum_{P\in \mathcal{P}_{L-n}(W_j^L)}
    \eta^{P}(W_j^L)
    \\
    &=
    \sum_{P\in \mathcal{P}_{L-n}(W_j^L)}
    \sum_{\ell=0}^{L-n}(-1)^\ell
    \sum_{Q\in\mathcal{P}_{\ell}(P)}
    \eta([W_j^L\backslash P]\cup Q )
    \\
    &=
    \sum_{\ell=0}^{L-n}
    (-1)^\ell
    \binom{n+\ell}{\ell}
    \sum_{P\in\mathcal{P}_{n+\ell}(W_j)}\eta(P).
\end{align} 
The third equality is consequence of, fixed $\ell\leq L, P\in\mathcal{P}_{L-n}(W_j^L)$ and $Q\in\mathcal{P}_{\ell}(P)$, clearly $[W_j^L\backslash P]\cup Q\in \mathcal{P}_{n+\ell}(W_j^L)$; and for each $P_\ell\in\mathcal{P}_{n+\ell}(W_j^L)$ there are $\binom{n+\ell}{\ell}$ pairs $(P,Q_P)$ such that $P\in P_{L-n}(W_j^L)$ and $Q_P\in\mathcal{P}_{\ell}(P)$, where $P_\ell=[W_j^L\backslash P]\cup Q_P$.


One sees that for each $0\leq\ell\leq L-n$,
    \begin{align}
        \sum_{P\in\mathcal{P}_{n+\ell}(W_j^L)}
	\eta(P)
        =
        \binom{m_j^L(\eta)}{n+\ell}
        \mathbf{1}_{
        \{
        m_j^L(\eta)
        \geq
        n+\ell 
        \}
        },    
    \end{align}
leading to
\begin{align}\label{bj-mono}
    \mathbf{b}_{n,L}^j(\eta)
=    \sum_{\ell=0}^{L-n}(-1)^\ell
%    \binom{L}{n}\binom{L-n}{\ell}
\binom{n+\ell}{\ell}\binom{L}{n+\ell}
    \frac{\binom{m_j^L(\eta)}{n+\ell}}{\binom{L}{n+\ell}}
        \mathbf{1}_{
        \{
        m_j^L(\eta)
        \geq
        n+\ell 
        \}
        }
        .
\end{align}
Summing the above over $0\leq j\leq L$ and performing a change of variables we identify the collection of maps $(\mathbf{p}_{\ell;L})_{0\leq \ell\leq L-n}$ as in \eqref{new-base}
\end{proof}


\subsection{Gradient condition}\label{subsec:grad}
We now verify the gradient property for the B($n$,$L$).
\begin{proof}[Proof of Proposition \ref{prop:grad-B} ]


We recall Definition \ref{def:sets} and the constraint as in \eqref{rate:b}. Let us introduce the set $M_L=\llbracket0,L+1\rrbracket$, and note that  
    \begin{align}
        \mathbf{b}_{n,L}(\eta)
        =\frac{1}{L+1}
        \sum_{j=0}^{L}
        \mathbf{s}_{n,L}^j(\tau^{-j}\eta)
        \quad\text{where}\quad
        \mathbf{s}_{n,L}^j(\eta)
        =\sum_{\substack{P\in \mathcal{P}_{L-n}(M_L)\\j,j+1\notin P}}
        \eta^{P}(M_L\backslash\{j,j+1\}).
    \end{align}
    Expressing $\mathbf{1}-\tau^{-j}=\sum_{i=1}^{j}\nabla\tau^{-i}$, we can rewrite
    \begin{align}\label{grad:step1}
        \mathbf{b}_{n,L}(\eta)(\mathbf{e}_{1,0}(\eta)-\mathbf{e}_{0,1}(\eta))
        % &=\mathbf{c}^{n,k}(\eta)\eta(0)\overline{\eta}(1)
        % -\mathbf{c}^{n,k}(\eta)\overline{\eta}(0)\eta(1)
        % \\
        % &=\sum_{j=0}^{L}
        % \sum_{P\in\mathcal{P}_n(M_L\backslash\{j,j+1\}
        % )}
        % \tau^{-j}
        % \eta^{P\cup\{j+1\}}(
        % M_L
        % )
        % -
        % \\&
        % -\sum_{j=0}^{L}
        % \sum_{P\in\mathcal{P}_n(M_L\backslash\{j,j+1\}
        % )}
        % \tau^{-j}
        % \eta^{P\cup\{j\}}(
        % M_L
        % )
        % \\&
        &=
        \frac{1}{L+1}\sum_{j=0}^{L}
    \sum_{\substack{P\in \mathcal{P}_{L-n}(M_L)\\j,j+1\notin P}}
\big\{
    \eta^{P\cup\{j+1\}}(
        M_L
        )
        -
        \eta^{P\cup\{j\}}(
        M_L
        )
\big\}
    \\&+\frac{1}{L+1}\nabla\mathbf{g}^{n,L}(\eta),
    \end{align}
with $\mathbf{g}^{n,L}$ as in \eqref{grad:c}. Let us introduce the auxiliary sets
\begin{align}
    \mathcal{W}_P
    &=\{x:x\notin P, x+1\in P,\;x,x+1\in M_L\}
    ,\\
    \Tilde{\mathcal{W}}_P
    &=\{x:\;x\in P,x+1\notin P,\;x,x+1\in M_L\}.
\end{align}
We claim that the first term in the right-hand side of \eqref{grad:step1} can be further expressed as 
\begin{multline}\label{grad:step2}
    \frac{1}{L+1}
    \sum_{\substack{P\in \mathcal{P}_{L-n+1}(M_L)\\P\neq \{0,\dots,L-n\}}}
    |\mathcal{W}_P|\eta^{P}(M_L)
    -\sum_{\substack{P\in \mathcal{P}_{L-n+1}(M_L)\\P\neq \{L+1-(L-n),\dots,L+1\}}}
    |\Tilde{\mathcal{W}}_P|\eta^{P}(M_L)
\\=    
    \frac{1}{L+1}
    \sum_{P\in \mathcal{P}_{L-n+1}(M_L)}
    |\mathcal{W}_P|\eta^{P}(M_L)
    -\sum_{P\in \mathcal{P}_{L-n+1}(M_L)}
    |\Tilde{\mathcal{W}}_P|\eta^{P}(M_L).
\end{multline}
In order to show this, first note that 
\begin{align}
    \bigcup_{j=0}^L 
    \big\{
    P\cup \{j\}
    \big\}_{P\in \mathcal{P}_{L-n}(M_L\backslash\{j,j+1\})}
    &=\mathcal{P}_{L-n+1}(M_L)\backslash\big\{0,\dots,L-n \big\},
    \\
    \bigcup_{j=0}^L 
    \big\{
    P\cup \{j+1\}
    \big\}_{P\in \mathcal{P}_{L-n}(M_L\backslash\{j,j+1\})}
    &=\mathcal{P}_{L-n+1}(M_L)\backslash\big\{L+1-(L-n),\dots,L+1 \big\}
    .
\end{align}
Next, note that fixed $Q\in \mathcal{P}_{L-n+1}(M_L)\backslash\{0,\dots,n\}$, for each $j'\in W_Q$ there is a unique $P_{j'}\in \mathcal{P}_{L-n}(M_L\backslash\{j',j'+1\})$ such that we can express 
\begin{align}
    Q=P_{j'}\backslash\{j',j'+1\}\cup\{j'+1\}.
\end{align}
In particular, there is a total of $|\mathcal{W}_Q|$ pairs $(j',P_{j'})$ as above. This proves the first summation in \eqref{grad:step2}. For the second summation, the reasoning is analogous and one should consider the set $\Tilde{W}_Q$ instead. This proves the claim.

Established \eqref{grad:step2}, it is straightforward to see that for any $P\in \mathcal{P}_{L-n+1}(M_L)$, 
\begin{align}\label{grad:step3}
    |\mathcal{W}_P|-|\Tilde{\mathcal{W}}_P|
    =
    \begin{cases}
    1, &0\notin P,\;L+1\in P,\\
    -1, &0\in P,\;L+1\notin P,\\
    0, &\text{otherwise}.
    \end{cases}
\end{align}
Indeed, let us map $P\in \mathcal{P}_{L-n+1}(M_L)\mapsto \Omega_L=\{0,1\}^{M_L}$ with the identification $\xi(p)=1\Leftrightarrow p\in P$ and $\xi(p)=0\Leftrightarrow p\notin P$. Then $|\mathcal{W}_P|=\{\{x,x+1\}\subset M_L:\; \xi(x)=1,\;\xi(x+1)=0\}$ and, analogously, $|\Tilde{M}_p|=\{\{x,x+1\}\subset M_L:\; \xi(x)=0,\;\xi(x+1)=1\}$. Each local configuration of the form $(1,0,\dots,0,1)$ within $\xi$, with (say) $h>0$ successive vacant sites contributes to $+1$ for both $|\mathcal{W}_P|$ and $|\Tilde{\mathcal{W}}_P|$. If $h=0$, the local configuration does not contribute. The same observation is valid for $(0,1,\dots,1,0)$ with $q>0$ or $q=0$ consecutive particles. In this manner, the values of $|\mathcal{W}_P|$ and $|\Tilde{\mathcal{W}}_P|$ may differ depending on the occupations at the boundary sites $0$ and $L+1$. From here one notes that if $\xi(0)=1$ then $|\mathcal{W}_P|=|\Tilde{\mathcal{W}}_P|$ if $\xi(L+1)=1$; or $|\mathcal{W}_P|=|\Tilde{\mathcal{W}}_P|+1$ if $\xi(L+1)=0$. Likewise, if $\xi(0)=0$ then $|\Tilde{\mathcal{W}}_P|=|\mathcal{W}_P|$ if $\xi(L+1)=0$; or $|\Tilde{\mathcal{W}}_P|=|\mathcal{W}_P|+1$ if $\xi(L+1)=1$.    

In this way, from \eqref{grad:step3} we can express further \eqref{grad:step2} as 
\begin{align}
    \sum_{\substack{
    P\in \mathcal{P}_{L-n+1}(M_L)
%    \\P\neq \{0,1,\dots,n+1\}
%    \\P\neq \{L+1-(n+1),L+1-n,\dots,L+1\}
    }}
    (
    \mathcal{W}_P-\Tilde{\mathcal{W}}_P
    )
    \eta^{P}(M_L)
    &=
    \sum_{\substack{
    P\in \mathcal{P}_{L-n+1}(M_L)
    \\0\notin P, L+1\in P 
    }}
    \eta^{P}(M_L)
    \\&-
    \sum_{\substack{
    P\in \mathcal{P}_{L-n+1}(M_L)
    \\0\in P, L+1\notin P 
    }}
    \eta^{P}(M_L)
\end{align}

Let us write the right-hand side above as $\alpha_{L-n+1}(\eta)$. The next step is to  identify the relation
\begin{align}\label{rec:rel}
    \begin{cases}
        \alpha_{i+1}=\alpha_{i}-\nabla\beta_{i}
        ,& 1\leq i \leq L-n\\
    \alpha_{1}(\eta)=-\nabla\eta(M_{L-n}),&
    \end{cases}
\quad\text{with}\quad
    \beta_{i}
    =\sum_{
    P\in\mathcal{P}_{i}(M_{n+i-2})
    }
    \eta^{P}(M_{n+i-1})
    .
\end{align}
Indeed, shortening $k\equiv L-n$,
\begin{align}
    \alpha_{k+1}(\eta)
    &=\sum_{\substack{
    P\in\mathcal{P}_{k}(M_{L-1})\\0\notin P
    }}
    \eta^P(M_{L-1})(1-\eta(L+1))
    -
    \sum_{\substack{
    P\in\mathcal{P}_{k}(M_{L-1})\\0\notin P
    }}
    (1-\eta(0))\eta^P(M_{L}\backslash\{0\})
    \\&
    =\sum_{\substack{
    P\in\mathcal{P}_{k}(M_{L-1})\\0\notin P
    }}
    \left\{
    \eta^P(M_{L-1})-\eta^P(M_L\backslash\{0\})
    \right\}
    % \\&
    % -
    % \sum_{\substack{
    % P\in\mathcal{P}_{k}(M_{L-1})\\0\notin P
    % }}
    % \eta^P(M_{L})
    % +
    % \sum_{\substack{
    % P\in\mathcal{P}_{k}(M_{L-1})\\0\notin P
    % }}
    % \eta^P(M_{L})
    ,
\end{align}
and because
\begin{align}
    \sum_{\substack{
    P\in\mathcal{P}_{k}(M_{L-1})
    \\0\notin P
    }}
    \eta^P(M_L\backslash\{0\})
    =
    \sum_{
    P\in\mathcal{P}_{k}(M_{L-2})
    }
    \eta^{1+P}(1+M_{L-1})
    =\beta_{k}(\tau^1\eta)
    ,
\end{align}
summing and subtracting $\beta_{k}(\eta)$, one obtains
\begin{align}
    \alpha_{k+1}(\eta)
    &=
    \sum_{\substack{
    P\in\mathcal{P}_{k}(M_{L-1})
    \\0\notin P
    }}
    \eta^P(M_{L-1})
    -
    \sum_{
    \substack{
    P\in\mathcal{P}_{k}(M_{L-2})\\L\notin P
    }
    }
    \eta^{P}(M_{L-1})
    -\nabla\beta_{k}(\eta)
    \\&
    =\alpha_{k}(\eta)-\nabla\beta_{k}(\eta)
    ,
\end{align}
with the last equality justified from the terms in the first summation where $L\in P$ cancelling with the terms in the second summation where $0\in P$. 


Up to this point, from \eqref{rec:rel} we have that $\mathbf{b}_{n,L}(\eta)(\mathbf{e}_{1,0}(\eta)-\mathbf{e}_{0,1}(\eta))=\nabla\mathbf{H}_{n,L}(\eta)$, with $\mathbf{H}_{n,L}=\mathbf{h}_{n,L}+\mathbf{g}_{n,L}$ and  
    \begin{align}\label{h:decomp}
    \mathbf{h}_{n,L}(\eta)
    =
    \frac{1}{L+1}\sum_{i=0}^{L-n}    
    \sum_{
    P\in\mathcal{P}_{i}(\llbracket0,n+i-1\rrbracket)
    }
    \eta^{P}(\llbracket0,n+i\rrbracket)
    .
    \end{align}
We then see that
    \begin{align}
    \sum_{i=0}^{L-n}    
    \sum_{
    P\in\mathcal{P}_{i}(\llbracket0,n+i-1\rrbracket)
    }
    \eta^{P}(\llbracket0,n+i\rrbracket)
    &=
    \sum_{i=0}^{L-n}
    \eta(n+i)
    \sum_{
    P\in\mathcal{P}_{i}(\llbracket0,n+i-1\rrbracket)
    }
    \eta^{P}(\llbracket0,n+i-1\rrbracket)
    \\
    &=
    \sum_{i=0}^{L-n}
    \mathbf{1}{
    \big\{
    \inner{\eta}_{n+i-1}=\tfrac{n}{n+i}
    \big\}
    }
    \eta(n+i)
    \\
    &=
    \mathbf{1}{
    \big\{
    \inner{\eta}_{L}\geq \tfrac{n+1}{L+1}
    \big\}
    }
    ,
\end{align}
concluding the proof. 
\end{proof}
