The gradient property for the $\text{PMM}_L$ is consequence of the decomposition \eqref{b-p_base} and the gradient property of B($n$,$L$). However, these relations do not provide a simple explicit expression for the related quantities. This is the content of the next lemma. 
\begin{Lemma}\label{lem:p-grad}
For each $n,L\in\mathbb{N}$ with $L\geq n$ it holds that
\begin{align}
    \mathbf{p}_{\ell;L}(\eta)
    (\mathbf{e}_{0,1}(\eta)-\mathbf{e}_{1,0}(\eta))
    =-\nabla\mathbf{H}_{\ell;L}(\eta)
\end{align}
with $\mathbf{H}_{\ell;L}=\mathbf{h}_{\ell;L}+\mathbf{g}_{\ell;L}$ and
\begin{align}
    \mathbf{h}_{\ell;L}(\eta)
    &
    =
    \frac{1}{L+1}\frac{1}{\binom{L}{\ell}}
    \mathbf{1}_{
    \{
    \inner{\eta}_{L}\geq \tfrac{\ell+1}{L+1}
    \}
    }    ,
    \\
    \mathbf{g}_{\ell;L}(\eta)
    &=\frac{1}{L+1}\sum_{j=1}^{L}
    \sum_{i=1}^{j}
    \mathbf{p}_{\ell;L}^j(\tau^{-i}\eta)
    (\mathbf{e}_{0,1}(\tau^{-i}\eta)
    -\mathbf{e}_{1,0}(\tau^{-i}\eta)
    )
    .
\end{align}
\end{Lemma}
\begin{proof}
Recalling Proposition \ref{prop:grad-B} and the decomposition \eqref{bj-mono}, we have that 
\begin{align}
    \mathbf{g}_{n,L}(\eta)
    &=\sum_{\ell=n}^L(-1)^{\ell-n}\binom{L}{n}\binom{L-n}{\ell-n}
    \frac{1}{L+1}\sum_{j=1}^{L}
    \sum_{i=1}^{j}
    \mathbf{p}_{\ell;L}^j(\tau^{-i}\eta)
    (\mathbf{e}_{0,1}(\tau^{-i}\eta)
    -\mathbf{e}_{1,0}(\tau^{-i}\eta)
    )
    ,
\end{align}
being then enough to decompose $\mathbf{h}_{n,L}$. Precisely, because $\binom{L}{n}\binom{L-n}{\ell-n}=\binom{L}{\ell}\binom{\ell}{n}$, this corresponds to showing the identity 
\begin{align}\label{connect}
    % \mathbf{h}_{n,L}(\eta)
    % =
    % \sum_{\ell=n}^L
    % (-1)^{\ell-n}
    % \binom{L}{n}\binom{L-n}{\ell-n}
    % \frac{1}{L+1}\frac{1}{\binom{L}{\ell}}
    % \mathbf{1}_{
    % \{
    % \inner{\eta}_{L-1}\geq \tfrac{\ell+1}{L}
    % \}
    % }.
    \mathbf{1}_{
    \big\{
    \inner{\eta}_{L}\geq\tfrac{n+1}{L+1}
    \big\}
    }
    =
    \sum_{\ell=n}^L
    (-1)^{\ell-n}
    \binom{\ell}{n}
    \mathbf{1}_{
    \{
    \inner{\eta}_{L}\geq \tfrac{\ell+1}{L+1}
    \}
    },
\end{align}
where we note that the left-hand side above equals $(L+1)\mathbf{h}_{n,L}(\eta)$. This can be seen as a direct application of the principle of inclusion-exclusion, or equivalently, the quantity in the left-hand side above equals
    \begin{align}\label{decomp-h}
\sum_{i=n}^{L}    
    \sum_{
    P\in\mathcal{P}_{i-n}(\llbracket0,i-1\rrbracket)
    }
    \eta^{P}(\llbracket0,i\rrbracket)
    &=
    \sum_{i=n}^{L}    
    \eta(i)
    \sum_{\ell=0}^{i-n}
    (-1)^{\ell}
    \sum_{
    \substack{
    P\in\mathcal{P}_{i-n}(\llbracket0,i-1\rrbracket)
    \\
    Q\in\mathcal{P}_{\ell}(P)
    }}
    \eta([\llbracket0,i\rrbracket\backslash P]\cup Q)
    \\
    &=
    \sum_{i=n}^{L}    
    \sum_{\ell=n}^{i}
    (-1)^{\ell-n}
    \binom{\ell}{n}
    \sum_{
    P\in\mathcal{P}_{\ell}(\llbracket0,i-1\rrbracket)
    }
    \eta(P)\eta(i)
    .
    \end{align}
Inverting the summations over $i$ and $\ell$ above and identifying 
\begin{align}
    \sum_{i=\ell}^L
    \sum_{
    P\in\mathcal{P}_{\ell}(\llbracket0,i-1\rrbracket)
    }
    \eta(P)\eta(i)
    =
    \mathbf{1}_{
    \{
    \inner{\eta}_{L}\geq \tfrac{\ell+1}{L+1}
    \}
    }
\end{align}
concludes the proof.
\end{proof}

\subsection{Further properties}\label{subsec:further}

In this subsection we prove Propositions \ref{prop:B-prop} and \ref{prop:P-prop}. The former is related to the Bernstein model, while the latter with the reduced PMM. In order to do so, let us recall the notion of mobile cluster \cite{GLT} used here. 
\begin{Def}\label{def:mc}
Let $\blacksquare$ represent a fixed finite box, composed by particles and vacant sites. Representing a particle by $\bullet$ and a hole by $\circ$, we say that $\blacksquare$ constitutes a mobile cluster if it enjoys the following.
\begin{itemize}[label=$\triangleright$]
\item \textit{Mobility}: the transitions $\blacksquare\bullet \leftrightarrow \bullet\blacksquare$ and $\blacksquare\circ\leftrightarrow\circ\blacksquare$ are possible with a finite number of jumps, and independent of the rest of the configuration; 
    \item \textit{Mass transport}: it is always possible for a jump to occur in a node, if there exists a cluster in the vicinity of the respective node, that is, $\blacksquare\circ\bullet\leftrightarrow\blacksquare\bullet\circ$ and $\circ\bullet\blacksquare\leftrightarrow\bullet\circ\blacksquare$.
\end{itemize}	    
\end{Def}
