\end{defi}
In the previous definition, we used the fact that $\Sigma$ is orientable; however, if the surface is non-orientable, it is still possible to define a rectangle of type $\theta$ with respect to a Riemannian metric.
\begin{defi}
For a non-orientable Riemannian surface $(\Sigma, g)$, we say $p_1,\dots, p_4$ are four vertices of a type $\theta$ rectangle if there exist $x\in \Sigma$ and non-zero vectors $v_1, v_2\in T_x\Sigma$ with $\Vert v_1\Vert = \Vert v_2\Vert$ such that
\begin{equation*}
    p_1 = \exp_g(x, v_1), p_2=\exp(x, v_2), p_3=\exp(x, -v_1), p_4=\exp(x, -v_2),
\end{equation*}
and the angle between $v_1, v_2$ is $\theta$.
\end{defi}

\begin{defi}
    We say a closed embedded curve $\gamma$ in $(\Sigma, g)$ inscribes a cyclic quadrilateral of type $(\theta, \varphi_1, \varphi_2)$ if there are four points $p_1,\dots, p_4$ on $\gamma$ so that they are vertices of a cyclic quadrilateral of type $(\theta, \varphi_1, \varphi_2)$.
\end{defi}

\begin{thm}
\label{main hyperbolic}
    Suppose $\gamma$ is a smooth closed embedded curve in $\mathbb{H}$, and choose three angles $\theta, \varphi_1, \varphi_2$ according to Definition \ref{cyclic def}. Then $\gamma$ inscribes a cyclic quadrilateral of type $(\theta, \varphi_1, \varphi_2)$.
\end{thm}
\begin{thm}
\label{main spherical}
    Consider a smooth Jordan curve $\gamma$ in $S^2$. Let $A\colon S^2\to S^2$ denote the antipodal map, and assume $A(\gamma)\cap \gamma = \emptyset$. Then $\gamma$ inscribes a rectangle of type $\theta$ with respect to the round metric \break for every $\theta\in (0, \pi)$.
\end{thm}
\begin{cor}
\label{rect and const curvature}
    Let $(\Sigma, g)$ be a complete Riemannian surface with constant curvature other than $S^2$, and consider a smooth embedded null-homotopic curve $\gamma$ in $\Sigma$. Then $\gamma$ inscribes a rectangle of type $\theta$ for every $\theta\in(0, \pi)$.
\end{cor}
\begin{proof}
    Lift $\gamma$ to a closed curve $\tilde{\gamma}$ in the universal cover of $\Sigma$. If this universal cover is the plane, then we know $\tilde{\gamma}$ inscribes every rectangle by Greene and Lobb's result; if the universal cover is $\mathbb{H}$, then we know $\tilde{\gamma}$ inscribes every rectangle by Theorem \ref{main hyperbolic}. Finally, if the universal cover is $S^2$, then $\Sigma$ has to be $\mathbb{RP}^2$, and since $\gamma$ is an embedded curve, we must have $A(\tilde{\gamma})\cap \tilde{\gamma}=\emptyset$. Hence, we can apply Theorem \ref{main spherical} to $\tilde{\gamma}$. Now notice that a rectangle of type $\theta$ in $\tilde{\gamma}$ descends to one with the same type in $\gamma$. 
\end{proof}

If we consider the isometric embedding of $S^2$ into $\mathbb{R}^3$ as the unit sphere, then it is straightforward to check that a rectangle of type $\theta$ in $S^2$ is the same as a rectangle in $\mathbb{R}^3$ with angle $\theta$ between its two diagonals. Hence, we get the following.
\begin{cor}
    Assume $\gamma\colon S^1\to \mathbb{R}^3$ is a smooth embedding with $\Vert\gamma(t)\Vert=r$ for every $t$ and $\diam(\gamma)<2r$. Then $\gamma$ inscribes a rectangle with angle $\theta$ between its diagonals for every $\theta\in (0, \pi)$. 
\end{cor}
\begin{proof}
    This follows by scaling $\gamma$ and applying Theorem \ref{main spherical} to the unit sphere in $\mathbb{R}^3$.
\end{proof}

The outline of the paper is as follows. First, we handle the hyperbolic case and prove Theorem \ref{main hyperbolic} in Section $1$. Then we prove Theorem \ref{main spherical} in Section $2$. We conclude the paper with some remarks and questions in Section 3.
