\subsection{Geometric preliminaries}

% % % % % % % % % % % % % % % % % % % % % % % % % % % % % % % % % % % % % %

In the following $\G$ will denote a four-dimensional Lie group, no necessarily compact or simply connected. We denote by:
\begin{equation*}
	L\colon \G\times \G\to \G\, , \qquad (a,b)\to L_a(b)
\end{equation*}

\noindent
the left-action of $\G$ in itself.
\begin{definition}
	Let $(\G,g)$ be a Lorentzian four-manifold. An irreducible real spinor $\varepsilon\in\Gamma(S)$ in $\G$ is left-invariant if its associated parabolic pair $(u,[l]_u)$ is left-invariant, that is, if:
	\begin{equation*}
		L_a^{\ast} u = u\, , \qquad L_a^{\ast}[l]_u =   [L_a^{\ast} l]_u = [l]_u
	\end{equation*}

	\noindent
	holds for every $a\in \G$.
\end{definition}

\begin{definition}
	Let $(\G,g)$ be a Lorentzian four-manifold. A torsion parallel spinor with contorsion $\mA$ is \emph{left-invariant} if both its associated parabolic pair and $\mA$ are left-invariant.
\end{definition}

\noindent
The definition of left-invariant irreducible real spinor can be unravelled as requiring that $u$ is left-invariant and every representative $l\in[l]_u$ satisfies:
\begin{equation}
	\label{eq:linvariance}
	L_a^{\ast}l = l + c_a u
\end{equation}

\noindent
for a function $c_a\in C^{\infty}(\G)$ on $\G$ that may depend on $a\in \G$. From this condition it follows that:
\begin{equation*}
	L_b^{\ast}L_a^{\ast}l = L_b^{\ast}l + c_a\circ L_b u = l + (c_b + c_a\circ L_b) u = L_{ab}^{\ast}l = l + c_{ab} u
\end{equation*}

\noindent
for every $a, b \in \G$. Hence:
\begin{equation*}
	c_{ab} = c_b + c_a\circ L_b\, , \qquad \forall\, \, a , b\in\G
\end{equation*}

\begin{lemma}
	\label{lemma:leftinvariantparabolicpair}
	Let $(u,[l]_u)$ be a left-invariant parabolic pair on $(M,g)$. Then, there exists a left-invariant representative in $[l]_u$.
\end{lemma}  

\begin{proof}
	Since $(u,[l]_u)$ is left-invariant, $u\in \Omega^1(\G)$ is in particular left-invariant and we can complete it to a left-invariant coframe $(u,w_1,w_2,w_3)$ on $\G$. Then, there exists a representative $l\in [l]_u$ that can be written as follows:
	\begin{equation*}
		l = \sum_{i=1}^3 k_i w_i
	\end{equation*}

	\noindent
	in terms of functions $k_1,k_2,k_3\in C^{\infty}(\G)$. By equation \eqref{eq:linvariance} we must have:
	\begin{equation*}
		\sum_{i=1}^3 (k_i\circ L_a) w_i = \sum_{i=1}^3 k_i w_i + c_a u
	\end{equation*}

	\noindent
	for every $a\in \cG$. Hence $c_a = 0$ for every $a\in \G$ whence $l$ is left-invariant. 
\end{proof}

\noindent
Let $(g,u,[l]_u)$ be a left-invariant parabolic pair with left-invariant representative $(u,l)$. Since we can always find a left-invariant one-form $v\in \Omega^1(\G)$ that is orthogonal to $l$ and satisfies $g(u,v) = 1$, it follows that we can always find a left-invariant isotropic coframe. More precisely, we obtain the following result.

\begin{lemma}
	Let $(g,u,[l]_u)$ be left-invariant. Then, $[u,v,l,n]\in \mathbb{E}^{-1}(u,[l]_u)$ contains a left-invariant representative.
\end{lemma}  

\noindent
Hence, by the previous lemma the study of left-invariant torsion parallel spinors can be reduced to the study of left-invariant coframes satisfying the differential system for left-invariant data. Before discussing left-invariant torsion isotropic parallelisms, it is convenient to revisit the classification of simply connected four-dimensional Lorentzian Lie groups.  


