\begin{table}[h!]
    \begin{center}
      \renewcommand{\arraystretch}{1.3}
  \setlength{\tabcolsep}{12pt}
     \begin{tabular}{c||c|c|c|c||c|c}
       \toprule
        \text{Fields}  &$L_{1}\quad L_{2}\quad L_{3}$&$e_{R}\quad\mu_{R}\quad\tau_{R}$&$N_1$\quad $N_2$\quad $N_3$&$S$&$H$&$\Phi$\\
        \hline  
        $SU(2)_{L}$&$\mathbf{2}$&$\mathbf{1}$&$\mathbf{1}$&$\mathbf{1}$&$\mathbf{2}$&$\mathbf{1}$\\
        $U(1)_{Y}$&$-\frac{1}{2}$&-1&0&0&$\frac{1}{2}$& $0$\\
        $A_4$&$\mathbf{1\quad1^\prime\quad1^{\prime\prime}}$ &$\mathbf{1\quad1^{\prime\prime}\quad1^{\prime}}$&$\mathbf{1\quad1^{\prime\prime}\quad1^{\prime}}$ &$\mathbf{3}$&$\mathbf{1}$&$\mathbf{1}$\\
        $k$&$\frac{1}{2}$&$-\frac{1}{2}$&$-\frac{1}{2}$&$0$&$0$&$ \frac{1}{2} $\\ \bottomrule
        \end{tabular}
     \caption{Field assignments to  $A_4$ irreducible representation and their weights in model 1. The $A_4$ representations are specified as singlets ($\mathbf{1}$, $\mathbf{1}^\prime$, $1^{\prime\prime}$) or triplet ($\mathbf{3}$), with fractional modular weights chosen to ensure invariant Lagrangian terms.}
   \label{tab:fieldcont1}  
     \end{center}   
\end{table}
%====================================================================

The Lagrangians for charged leptons and neutrinos are given by
\begin{align}
-\mathscr{L}_{\rm CL}=& \alpha_{\rm CL}\bar{L}_{1}He_RY_{\mathbf{1}}^{(0)}+\beta_{\rm CL}\bar{L}_{2}H\mu_{R}Y_{\mathbf{1}}^{(0)}+\gamma_{\rm CL}\bar{L}_{3}H\tau_{R}Y_{\mathbf{1}}^{(0)}+\mathrm{h.c.},\\
\mathscr{L}_{\nu}=& \mathscr{L}_{M_{D}}+\mathscr{L}_{M_{NS}}+\mathscr{L}_{M_{S}}.
\end{align}
where the modular form $Y_{\mathbf{1}}^{(0)}$ reduces to unity ($Y_{\mathbf{1}}^{(0)} = 1$) as required by its vanishing weight. The neutrino sector contains three distinct contributions, $\mathscr{L}_{M_D}$ generating the Dirac mass term,  $\mathscr{L}_{M_{NS}}$ mediating $N$-$S$ mixing, and $\mathscr{L}_{M_S}$ producing the Majorana mass term,
\begin{align}
-\mathscr{L}_{M_{D}}=& \alpha_{{D}}\bar{L}_{1}\tilde{H}N_{{1}}Y_{\mathbf{1}}^{(0)}+\beta_{{D}}\bar{L}_{2}\tilde{H}N_{{2}}Y_{\mathbf{1}}^{(0)}+\gamma_{{D}}\bar{L}_{3}\tilde{H}N_{{3}}Y_{\mathbf{1}}^{(0)}+\mathrm{h.c.},\\
-\mathscr{L}_{M_{NS}}=& \alpha_{{NS}}\left(\bar{S}Y_{\mathbf{3}}^{(0)}\right)_{\mathbf{1}}N_1\Phi+\beta_{{NS}}\left(\bar{S}Y_{\mathbf{3}}^{(0)}\right)_{\mathbf{1^\prime}}N_2\Phi+\gamma_{{NS}}\left(\bar{S}Y_{\mathbf{3}}^{(0)}\right)_{\mathbf{1^{\prime\prime}}}N_3\Phi+\mathrm{h.c.}, \\
-\mathscr{L}_{M_{S}}=& \alpha_{{S}}\left(\bar{S}S\right)_{\mathbf{3}_S}Y_{\mathbf{3}}^{(0)}+\beta_{{S}}\left(\bar{S}S\right)_{\mathbf{1}}Y_{\mathbf{1}}^{(0)}+\mathrm{h.c.}.
\end{align}
The boldface subscripts in the Lagrangian terms (enclosed in brackets) indicate the decomposition of $A_4$ group products into specified irreducible representations. Flavor structure of the neutrino sector originates entirely from the weight-0 modular forms $Y_{\mathbf{1}}^{(0)}$ and $Y_{\mathbf{3}}^{(0)}=\left(Y_1, Y_2, Y_3 \right)$. After electroweak symmetry breaking, the scalar fields acquire VEVs $ \langle H \rangle = v_H $ and $ \langle \Phi \rangle = v_\Phi $, leading to the following mass matrices: 
\begin{align}
	M_{\rm CL}= & v_H\left(\begin{array}{ccc}
		\alpha_{{\rm CL}}& 0& 0 \\
		0  & \beta_{{\rm CL}}& 0 \\
		0 & 0 & \gamma_{{\rm CL}} \\
	\end{array}\right),\\
	M_{D}=& v_H\left(\begin{array}{ccc}
		\alpha_{{D}}& 0& 0 \\
		0  & \beta_{{D}}& 0 \\
		0 & 0 & \gamma_{{D}} \\
	\end{array}\right),
\end{align}
\begin{align}
M_{NS}=& v_\Phi\left(\begin{array}{ccc}
\alpha_{{NS}}Y_{\mathbf{3}, 1}^{(0)} & \beta_{{NS}}Y_{\mathbf{3}, 2}^{(0)} & \gamma_{{NS}}Y_{\mathbf{3}, 3}^{(0)} \\
\alpha_{{NS}}Y_{\mathbf{3}, 3}^{(0)}  & \beta_{{NS}}Y_{\mathbf{3}, 1}^{(0)} & \gamma_{{NS}}Y_{\mathbf{3}, 2}^{(0)}  \\
\alpha_{{NS}}Y_{\mathbf{3}, 2}^{(0)}  & \beta_{{NS}} Y_{\mathbf{3}, 3}^{(0)} & \gamma_{{NS}}Y_{\mathbf{3}, 1}^{(0)} \\
\end{array}\right),\\
M_{S}=& \left(\begin{array}{ccc}
2\alpha_{{S}}Y_{\mathbf{3}, 1}^{(0)}+\beta_{{S}}& -\alpha_{{S}}Y_{\mathbf{3}, 3}^{(0)} & -\alpha_{{S}}Y_{\mathbf{3}, 2}^{(0)}\\
-\alpha_{{S}}Y_{\mathbf{3}, 3}^{(0)}  & 2\alpha_{{S}}Y_{\mathbf{3}, 2}^{(0)}& -\alpha_{{S}}Y_{\mathbf{3}, 1}^{(0)}+\beta_{{S}}  \\
-\alpha_{{S}}Y_{\mathbf{3}, 2}^{(0)} & -\alpha_{{S}} Y_{\mathbf{3}, 1}^{(0)}+\beta_{{S}} & 2\alpha_{{S}}Y_{\mathbf{3}, 3}^{(0)} \\
\end{array}\right).
\end{align}
The charged lepton mass matrix $M_{\rm CL}$ naturally emerges as diagonal in this construction due to the $A_4$ singlet assignments of the relevant fields. This diagonal structure allows the charged lepton masses to be directly identified with the corresponding Yukawa couplings. While this feature imposes no constraints on the charged lepton sector, it enables unambiguous predictions for the neutrino sector through the modular symmetry framework. Under the inverse seesaw condition $ M_S \ll M_D \ll M_{NS} $, the light neutrino mass matrix is given by eq.~\eqref{eq:numasmatinvss}. For numerical analysis, we express $M_{\nu}=k m_{\nu}$, where $m_{\nu}=m_{D}m_{NS}^{-1}m_{S}\left(m_{NS}^{T}\right)^{-1}m_{D}^{T}$, in terms of dimensionless parameters $ m_D $, $ m_{NS} $, and $ m_S $, with rescaling factor $ k = (v_H \alpha_{D} / v_\Phi \alpha_{{NS}})^2 \alpha_{M_S} $,
\begin{align}
m_{D}=& \left(\begin{array}{ccc}
1& 0& 0 \\
0  & \frac{\beta_{{D}}}{\alpha_{{D}}}& 0 \\
0 & 0 & \frac{\gamma_{{D}}}{\alpha_{{D}}} \\
\end{array}\right),\\
m_{NS}=& \left(\begin{array}{ccc}
Y_{\mathbf{3}, 1}^{(0)} & \frac{\beta_{{NS}}}{\alpha_{{NS}}}Y_{\mathbf{3}, 2}^{(0)} & \frac{\gamma_{{NS}}}{\alpha_{{NS}}}Y_{\mathbf{3}, 3}^{(0)} \\
Y_{\mathbf{3}, 3}^{(0)}  & \frac{\beta_{{NS}}}{\alpha_{{NS}}}Y_{\mathbf{3}, 1}^{(0)} & \frac{\gamma_{{NS}}}{\alpha_{{NS}}}Y_{\mathbf{3}, 2}^{(0)}  \\
Y_{\mathbf{3}, 2}^{(0)}  & \frac{\beta_{{NS}}}{\alpha_{{NS}}} Y_{\mathbf{3}, 3}^{(0)} & \frac{\gamma_{{NS}}}{\alpha_{{NS}}}Y_{\mathbf{3}, 1}^{(0)} \\
\end{array}\right),\\
m_{S}=& \left(\begin{array}{ccc}
2Y_{\mathbf{3}, 1}^{(0)}+\frac{\beta_{{S}}}{\alpha_{{S}}}& -Y_{\mathbf{3}, 3}^{(0)} & -Y_{\mathbf{3}, 2}^{(0)}\\
-Y_{\mathbf{3}, 3}^{(0)}  & 2Y_{\mathbf{3}, 2}^{(0)}& -Y_{\mathbf{3}, 1}^{(0)}+\frac{\beta_{{S}}}{\alpha_{{S}}}  \\
-Y_{\mathbf{3}, 2}^{(0)} & -Y_{\mathbf{3}, 1}^{(0)}+\frac{\beta_{{S}}}{\alpha_{{S}}} & 2Y_{\mathbf{3}, 3}^{(0)} \\
\end{array}\right).
\end{align}
These matrices are described by a total of six dimensionless parameters, which are generally complex. To increase the predictive power of the model, we impose generalized CP symmetry (gCP)~\cite{Novichkov:2019sqv}. The gCP symmetry requires simultaneous transformation $ \tau \to -\tau^* $, $Y^{(k)}_{\mathbf{r}}(\tau) \to X_{\mathbf{r}}  Y^{(k)*}_{\mathbf{r}}(\tau) $, and $ \varphi_i \to X_{\mathbf{r}} \bar{\varphi} $ for fields $ \varphi $, where $ X $ is the $ A_4 $ CP matrix.  This symmetry ensures that, apart from the modulus $\tau$, which remains complex and the sole source of CP violation, the remaining five parameters are constrained to be real. As a result, the model becomes more predictive, with seven real free parameters while maintaining consistency with observed flavor structures and CP-violating phases in the lepton sector. 


