For each region $D_j$, denote the local particle ensemble at assimilation time $t_k$ by $\{u^{i,(j)}_{t_k}\}_{i=1}^N$, for all $k \ge 1$. In particular, given the global ensemble $\{u^i_{t_k}\}$, the local particles are defined by the restriction of the global particles to $D_j$, i.e.
\begin{equation}\label{eq:local_parts}
	u^{i,(j)}_{t_k} = u^{i}_{t_k} |_{D_j}, \quad \forall i = 1, \dots, N, \, \forall j = 1, \dots, N_{\mathrm{loc}}.
\end{equation}
\begin{rmk}
	The subregions $\{ D_j \}_{j=1}^{N_{\mathrm{loc}}}$ naturally inherit the same discretization of $D$, so the restriction of a numerical field $v$ on $D$ to a region $D_j$ (denoted by $v |_{D_j}$ as in \eqref{eq:local_parts}) can be understood as selecting the entries of the $\R^{N_u}$-dimensional vector $v$ corresponding to the grid-points in $D_j \subset D$. In particular, the number of grid-points in $D_j$ determines the dimension of the local numerical field $v |_{D_j}$. As before, the notation $v |_{D_j}(z)$ for $z \in D_j$ indicates the value of $v$ at grid-point $z$.
\end{rmk}
Finally, consider the observations $Y$ defined in \eqref{eq:discrete_obs}, so that at each assimilation time $t_k$ the observations $Y_k$ are found at the locations given by the grid-points $\{z^s_k\}_{s=1}^{N_{\mathrm{obs}_k}}, \, z^s_k \in D$. For all $k \ge 1$, we denote the set of indices of the observations belonging to region $D_j$ by $\mathcal{I}^j_{k}$, i.e.
\begin{equation}\label{eq:obs_indices_per_region}
	\mathcal{I}^j_{k} = \left\{ s \, : \, z^s_k \in D_j, \, s \in \{ 1, \dots, N_{\mathrm{obs}_k} \} \right\}.
\end{equation}
 Note that when $z^s_k$ belongs to an overlap region, $s$ belongs to $\mathcal{I}^j_k$ for more than one $j$. Thus, for all $k \ge 1$ and all $j = 1, \dots, N_{\mathrm{loc}}$, we also define the functions \[f^j_k: \{1, \dots, N_{\mathrm{obs}_k} \} \to \{1, \dots, N_{\mathrm{loc}} \}\] such that
 \begin{equation}\label{eq:selection_func}
 	f^j_k(s) =
 	\left\{  \begin{array}{ll}
 		 j & \quad \mathrm{if}\, s \in \mathcal{I}^j_k, \\
 		\min \{ r \, : \,  s \in \mathcal{I}^r_k \} &\quad \mathrm{if}\, s \notin \mathcal{I}^j_k,
 	 \end{array} \right.
 \end{equation}
 which assigns the index $r$ of a subregion $D_r$ to (the index $s$ of) each observation's location $z^s_k$. If $z^s_k \in D_j$, the index $j$ is always assigned (even when $z^s_k$ belongs to multiple regions).  If $z^s_k \notin D_j$, by convention we select the smallest among the indices of the subregions which $z^s_k$ belongs to.

 \subsection{Local likelihood}

We are now ready to introduce a local likelihood function for the computation of the (local) weights of the local ensembles. Let us start with a version of the Gaspari--Cohn localization function, as introduced in \cite{gaspari_cohn}.
\begin{defn}[Gaspari-Cohn localization function]\label{def:gaspari-cohn}
	Let $D_1, \dots, D_{N_{\mathrm{loc}}} \subset D$ be $N_{\mathrm{loc}}$ subregions of $D$,  let the observations $Y$ be defined as in \eqref{eq:discrete_obs}, so that at each assimilation time $t_k$ the observations $Y_k = (Y^1_k, \dots, Y^{N_{\mathrm{obs}_k}}_k)$ are located at the points $\{z^s_k\}_{s=1}^{N_{\mathrm{obs}_k}}$, $z^s_k \in D$. Let $\alpha \in \R^{+}$. For all $k \ge 1$, let $\rho^{\alpha}_k : \{ 1, \dots, N_{\mathrm{loc}}\} \times \{1, \dots, N_{\mathrm{obs}_k}\} \to [0,1] $ be the \textit{Gaspari--Cohn localization function}, defined by
	\begin{equation}\label{eq:gaspari-cohn}
		\rho_k^{\alpha}(j,s) = \left\{  \begin{array}{ll}
			1 & \quad \mathrm{if}\, z^s_k \in D_j, \\
			\exp\{ - \alpha d(D_j, z^s_k) \} &\quad \mathrm{if}\, z^s_k \notin D_j,
			\end{array}\right.
	\end{equation}
where $d(A, z)$ is a distance function between a convex region $A \subset D$ and a point $z \in D\setminus A$.
\end{defn}
\begin{defn}[Local likelihood function]\label{def:local_likelihood}
	Let $v$ be a numerical field on $D$, and let $D_1, \dots, D_{N_{\mathrm{loc}}}$, $Y$ and $\alpha$ be as in Definition~\ref{def:gaspari-cohn}. Recall the definitions of $\mathcal{I}^j_k$ and $f^j_k$ for $j = 1, \dots, N_{\mathrm{loc}}$ and $k \ge 1$ given in \eqref{eq:obs_indices_per_region} and \eqref{eq:selection_func}.
	For all $j = 1, \dots, N_{\mathrm{loc}}$ and all $k \ge 1$, denote by $g^{\alpha, j}_k : \R^{N_u} \to \R$ the \textit{local likelihood function} for region $D_j$, and let it be defined by
	\begin{align}\label{eq:loc_likelihood}
		g^{ \alpha, j}_k (v) \approx  \exp \Bigg\{
		&-\frac{1}{2}  \sum_{s = 1}^{N_{\mathrm{obs}_k}} \tilde g_{j, k , s} (v)^{\top} (\Sigma^{s}_k)^{-1} \tilde g_{j, k , s} (v) \rho_k^{\alpha}(j,s) \Bigg\},
	\end{align}
	where $\rho^{\alpha}_k$ is the Gaspari--Cohn localization function defined in \eqref{eq:gaspari-cohn}, and $\tilde g_{j, k , s} : \R^{N_u} \to \R^{\tilde{d_y}}$ is given by
	\begin{equation*}
		\tilde g_{j, k , s} (v) := Y^{s}_k - h^s_k(v|_{D_{f^j_k(s)}}(z^s_k)).
	\end{equation*}
\end{defn}
\begin{rmk}
	Note that if we evaluate \eqref{eq:loc_likelihood} at $u^{i}_{t_k}$, where $u^i$ is a particle of the (global) ensemble and $t_k$ is an assimilation time, we have
	\begin{align}\label{eq:loc_likelihood_loc_ensemble}
		g^{ \alpha, j}_k (u^i_{t_k}) 
%		&\approx  \exp \Bigg\{
%		-\frac{1}{2}  \sum_{s \in \mathcal{I}^j_k}  \big( Y^{s}_k - h^s_k(u^i_{t_k}|_{D_j}(z^s_k)) \big)^{\top} (\Sigma^{s}_k)^{-1} \big( Y^{s}_k - h^s_k(u^i_{t_k}|_{D_j}(z^s_k)) \big) \nonumber \\
%		&\qquad \quad -\frac{1}{2}  \sum_{s \notin \mathcal{I}^j_k}  \big( Y^{s}_k - h^s_k(u^i_{t_k}|_{D\setminus D_j}(z_k^s)) \big)^{\top} (\Sigma^{s}_k)^{-1}   \big( Y^{s}_k - h^s_k(u^i_{t_k}|_{D\setminus D_j}(z_k^s)) \big) \rho_k^{\alpha}(j,s) \Bigg\} \nonumber \\
		&\approx  \exp \Bigg\{
		-\frac{1}{2}  \sum_{s \in \mathcal{I}^j_k}  \big( Y^{s}_k - h^s_k(u^{i,(j)}_{t_k}(z^s_k)) \big)^{\top} (\Sigma^{s}_k)^{-1} \big( Y^{s}_k - h^s_k(u^{i,(j)}_{t_k}(z^s_k)) \big) \nonumber \\
		&\qquad \quad -\frac{1}{2}  \sum_{s \notin \mathcal{I}^j_k}  \big( Y^{s}_k - h^s_k(u^{i, (f^j_k(s))}_{t_k}(z_k^s)) \big)^{\top} (\Sigma^{s}_k)^{-1}   \big( Y^{s}_k - h^s_k(u^{i, (f^j_k(s))}_{t_k}(z_k^s)) \big) \rho_k^{\alpha}(j,s) \Bigg\},
	\end{align}
	where the function $f^j_k$ is defined in \eqref{eq:selection_func}, and we recognize the local particle $u^{i, (j)}$ for the computation of the part of the likelihood dealing with observations $Y^s_k$ located at grid-points $z^s_k \in D_j$, and the local particles $u^{i, (f^j_k(s))}$ for the observations $Y^s_k$ such that $z^s_k \notin D_j$ and $z^s_k \in D_{f^j_k(s)}$.
\end{rmk}

\begin{rmk}
	For simplicity, we took the observation noise in \eqref{eq:discrete_obs} to be Gaussian, but the definition of the local likelihood function \eqref{eq:loc_likelihood} can be adapted to any other noise distribution.
\end{rmk}

\begin{defn}[Local weights]\label{def:local_weights}
	Let $D_1, \dots, D_{N_{\mathrm{loc}}}$, $Y$, $\alpha$ and $\mathcal{I}^j_k$ for $j = 1, \dots, N_{\mathrm{loc}}$ be as in Definition~\ref{def:local_likelihood}. For all $j = 1, \dots, N_{\mathrm{loc}}$, $k \ge 1$, and $i = 1, \dots, N$, we denote by $w^{i, \alpha, (j)}_k$ the \textit{local weight} in subregion $D_j$ of particle $u^i$ at time $t_k$, and define it by
	\begin{equation}\label{eq:local_weights}
		w^{i, \alpha, (j)}_k = \frac{g^{\alpha, j}_k(u^i_{t_k})}{\sum_{j=1}^N g^{\alpha, j}_k(u^i_{t_k})},
	\end{equation}
	where $g^{\alpha, j}_k$ evaluated at particle $u^i_{t_k}$ is to be understood as a function of the local particles $u^{i, (l)}_{t_k}$ for $l = 1, \dots, N_{\mathrm{loc}}$ as in \eqref{eq:loc_likelihood_loc_ensemble}.
\end{defn}

We compute the weights of the local ensembles using Definition~\ref{def:local_weights}, and then proceed to apply tempering, jittering and resampling as in Algorithm~\ref{alg:tempering}, but now locally. However, because of the dependence of the local weights on the global particles (or, equivalently, the dependence of the local weights for region $D_j$ on all of the local ensembles $\{u^{i, (l)}\}_{i = 1}^N$, for $l = 1, \dots, N_{\mathrm{loc}}$), we come to an important choice in our implementation: whether or not to allow local updates of particles (due to tempering and jittering) outside of region $D_j$ to influence the local particle filter in region $D_j$. Let us expand briefly on this problem.

Assume that at time $t_{k-1}$ we have the usual global ensemble $\{u_{t_{k-1}}^i\}_{i=1}^N$, and that observation $Y_{k-1}$ has been assimilated. We evolve the ensemble forward according to \eqref{eq:SPDE_general} up to the next assimilation time $t_{k}$, and we split the resulting global ensemble $\{u_{t_{k}}^i\}_{i=1}^N$ in its local counterparts $\{u_{t_{k}}^{i, (j)}\}_{i=1}^N$ for $j = 1, \dots, N_{\mathrm{loc}}$. We now want to apply the tempering Algorithm~\ref{alg:tempering} in each subregion $D_j$ for $j = 1, \dots, N_{\mathrm{loc}}$. For the purpose of clarity, let us fix $j$ for the moment and focus on region $D_j$. At the start of the tempering iterations, the weights for the local ensemble $\{u^{i, (j)}_{t_{k}}\}$ computed using \eqref{eq:local_weights} are simply given by evaluating the global ensemble at the locations $z^s_k$ for $s = 1, \dots, N_{\mathrm{obs}_k}$ of the observations $Y_{k}$. At the end of the first tempering iteration, the local particles $\{u^{i, (j)}_{t_{k}}\}$ have been modified (due to resampling and jittering). For all subsequent tempering iterations, we have two choices:
\begin{enumerate}
	\item In \eqref{eq:local_weights}, only update the part of the likelihood function \eqref{eq:loc_likelihood} which deals with observations at locations $z^s_k \in D_j$, determined by the ensemble $\{u^{i, (j)}_{t_{k}}\}$, and consider the other local ensembles $\{u^{i, (l)}_{t_{k}}\}$ for $l \neq j$, which are needed to compute the part of the likelihood that deals with observations at $z^s_k \notin D_j$, as \textit{fixed}.
	\item Let the local ensembles $\{u^{i, (l)}_{t_{k}}\}$ for $l \neq j$ vary according to the tempering algorithm applied locally in each region: for example, before proceeding with the second tempering iteration in region $D_j$, wait until the first tempering iteration has completed in all the other regions as well, communicate the new local particles positions and update the likelihood accordingly for the computations of the local weights.
\end{enumerate}

\begin{rmk}
	Recall that we are looking for a localization algorithm which scales with the number of subdomains $N_{\mathrm{loc}}$: in other words, we want to be able to run the tempering algorithm in parallel in each region. If one is satisfied with running the data-assimilation sequentially, the issue raised here is not relevant, since in the computation of the weights for each subregion $D_j$ one should simply use the local ensembles, some of which will have already gone through the tempering procedure (those in $D_l$ for $l < j$), and some of which will only be updated after the data-assimilation in $D_j$ has been completed.
\end{rmk}

Clearly, from an algorithmic point of view, between the two options above the second one is the hardest to implement, since, when writing the parallelization scheme, the cores which deal with the computations in each subdomain need to be made to communicate information to each other throughout the data-assimilation process. The task is made more complex by the fact that the number of tempering iterations needn't be equal across the subdomains: in fact, they will most likely be different, since one of the advantages of localizing the data-assimilation procedure is that (almost) no update to the particles should be needed in the subregions where there are no observations to be found. The implementation of such an algorithm goes beyond the scope of this paper. In terms of performance of the particle filter, the choice between the first and second option matters only if $\alpha$ in \eqref{eq:gaspari-cohn} is small, or if the observations are located in neighbouring subregions. Operating under the assumption that the observations outside a subdomain $D_j$ should have very little impact on the weights of the local ensemble, the first option suggested above should yield acceptable results, and is the one that we choose to implement (see Algorithm~\ref{alg:loc_PF}).

\subsection{Merging the local particles and spatial interpolation}\label{sec:merging}
At the end of each assimilation step, once the tempering iterations have concluded in all the local subregions, we are left with $N_{\mathrm{loc}}$ local ensembles $\{u^{i, (j)}_{t_k}\}_{i=1}^N$ for $j = 1, \dots, N_{\mathrm{loc}}$ of $N$ local particles each. These local ensembles are generally \textit{discontinuous} at the subregions' boundaries. We briefly expand on this.

Fix an index $i$ (and a time-step $t_k$) and consider the local particles $\{u^{i, (j)}_{t_k}\}_{j=1}^{N_{\mathrm{loc}}}$. When we construct the local particles at the start of the assimilation step (line~\ref{line:local_ens_construction} of Algorithm~\ref{alg:loc_PF}), they coincide on all the overlap regions, i.e.~$u^{i, (e)}_{t_k}(F_{ew}) = u^{i, (w)}_{t_k}(F_{ew})$ for all EW-overlap regions $F_{ew}$, $u^{i, (s)}_{t_k}(G_{sn}) = u^{i, (n)}_{t_k}(G_{sn})$ for all SN-overlap regions $G_{sn}$, and $u^{i, (a)}_{t_k}(H_{abcd}) = u^{i, (b)}_{t_k}(H_{abcd}) = u^{i, (c)}_{t_k}(H_{abcd}) = u^{i, (d)}_{t_k}(H_{abcd})$ for all corner-overlap regions $H_{abcd}$. By the end of the local assimilation step, for each $j = 1, \dots, N_{\mathrm{loc}}$, the local particle $u^{i,(j)}_{t_k}$ has gone through independent tempering and jittering iterations: for the same index $i$, particle  $u^{i,(j)}_{t_k}$ might have been left invariant in some sub-regions $D_j$, while being resampled and modified in others. Since the algorithm operates independently in each subregion, the local particles $u^{i,(j)}_{t_k}$ do not necessarily agree on the overlap regions $F_{ew}, G_{sn}$ and $H_{abcd}$ any more. Thus, in order to reconstruct a global particle $u^i_{t_k}$ on the whole domain $D$, we need to take care of these spatial discontinuities.

\begin{rmk}
	The use of the Gaspari--Cohn function and the introduction of the overlap regions give us some hope that the local weights of particles $u^{i,(j)}_{t_k}$ (for a fixed index $i$) in neighbouring regions are not too dissimilar. However, while these features mitigate excessive local weights discontinuities across neighbouring regions, the tempering, resampling and jittering algorithms ultimately rely on the generation of random variables, so significant spatial discontinuities can still, in principle, happen.
\end{rmk}

The idea behind the algorithm for merging local particles back together is as follows. By defining the overlap regions, at the end of the local assimilation step we end up with two (in EW- and NS-overlap regions) or four (in corner-overlap regions) independent copies of each local particle $u^{i, (j)}_{t_k}$ in each overlap region. Define the following interpolation functions \footnote{Note that for simplicity we use linear interpolation, but other types of interpolation are equally suitable.}.
\begin{defn}[Interpolation functions]
	Let $u$ and $v$ be numerical fields defined on the same quadrilateral grid $L = [x_e, x_w] \times [y_s, y_n]$ consisting of $m_1 \times m_2$ grid-points $(x,y)$, where $x_e$ and $x_w$ are the $x$-coordinates of the eastern- and western-most grid points, and $y_s$ and $y_n$ are the $y$-coordinates of the southern- and northern-most grid-points. Define the \textit{horizontal} and \textit{vertical interpolation functions} $\mathrm{Interp}_{ew}, \mathrm{Interp}_{sn} : \R^{m_1 \times m_2} \times \R^{m_1 \times m_2} \to \R^{m_1 \times m_2}$ as
	\begin{align*}
		\mathrm{Interp}_{ew}(u,v)(x,y) &:= u(x,y) \frac{x_w - x}{x_w - x_e} + v(x,y) \frac{x - x_e}{x_w - x_e}, \quad \forall (x,y) \in L, \\
		\mathrm{Interp}_{sn}(u,v)(x,y) &:= u(x,y) \frac{y_n - y}{y_n - y_s} + v(x,y) \frac{y - y_s}{y_n - y_s}, \quad \forall (x,y) \in L.
	\end{align*}
\end{defn}

Using Figure~\ref{fig:center_region_overlap} for visual reference as needed, for each $i = 1, \dots, N$, we construct the global particle $u^i_{t_k}$ by merging the local particles $\{u^{i, (j)}_{t_k} \}_{j = 1}^{N_{\mathrm{loc}}}$ as follows:
\begin{itemize}
	\item For each $j$, on the subregion $\mathring{D}_{j} = D_j \setminus (F_{ej} \cup F_{jw} \cup G_{sj} \cup G_{jn})$, where $e, w, s$ and $n$ are the indices of the subregions neighbouring $D_j$ to the east, west, south and north respectively, we set $u^i_{t_k} |_{\mathring{D}_j} = u^{i, (j)}_{t_k} |_{\mathring{D}_j}$.
	\item On each EW-overlap region $F_{ew}$, we define $u^i_{t_k} |_{{F}_{ew}}$ as the (horizontal) interpolation of $u^{i, (e)}_{t_k} |_{{F}_{ew}}$ to the east and $u^{i, (w)}_{t_k} |_{{F}_{ew}}$ to the west, i.e.~$u^i_{t_k}(x,y) = \mathrm{Interp}_{ew}(u^{i, (e)}_{t_k}, u^{i, (w)}_{t_k} )(x,y)$ for all $(x,y) \in F_{ew}$.
	\item On each SN-overlap region $G_{sn}$, we define $u^i_{t_k} |_{{G}_{sn}}$ as the (vertical) interpolation of $u^{i, (s)}_{t_k} |_{{G}_{sn}}$ to the south and $u^{i, (n)}_{t_k} |_{{G}_{sn}}$ to the north, i.e.~$u^i_{t_k}(x,y) = \mathrm{Interp}_{sn}(u^{i, (s)}_{t_k}, u^{i, (n)}_{t_k} )(x,y)$ for all $(x,y) \in G_{sn}$ .
	\item On each corner-overlap region $H_{abcd}$, we define $u^i_{t_k} |_{H_{abcd}}$ by repeated interpolation of $u^{i, (a)}_{t_k} |_{H_{abcd}}$, $u^{i, (b)}_{t_k} |_{H_{abcd}}$, $u^{i, (c)}_{t_k} |_{H_{abcd}}$ and $u^{i, (d)}_{t_k} |_{H_{abcd}}$. We first interpolate horizontally $u^{i, (a)}_{t_k} |_{H_{abcd}}$ to the east and $u^{i, (b)}_{t_k} |_{H_{abcd}}$ to the west, and $u^{i, (d)}_{t_k} |_{H_{abcd}}$ to the east and $u^{i, (c)}_{t_k} |_{H_{abcd}}$ to the west, obtaining $\mathrm{Interp}_{ew}(u^{i, (a)}_{t_k}, u^{i, (b)}_{t_k} )$ and $\mathrm{Interp}_{ew}(u^{i, (d)}_{t_k}, u^{i, (c)}_{t_k} )$. We then interpolate the two resulting numerical fields vertically, the first to the north and the second to the south, and get, for all $(x,y) \in H_{abcd}$,
	\begin{equation*}
		u^{i}_{t_k}(x,y) =\mathrm{Interp}_{sn} \Big( \mathrm{Interp}_{ew}(u^{i, (d)}_{t_k}, u^{i, (c)}_{t_k} ), \mathrm{Interp}_{ew}(u^{i, (a)}_{t_k}, u^{i, (b)}_{t_k} ) \Big) (x,y).
	\end{equation*}
\end{itemize}

	\begin{rmk}
		For clarity of exposition, in this section we assumed the evaluation of the various numerical fields at \textit{fixed reference grid-points}, denoted by $(x,y)$ in $D$. In practice, since the local numerical fields are defined on different subregions, and they only overlap on subsets of these, when defining the interpolation algorithms one needs to pay close attention to matching the indices of the arrays correctly.
	\end{rmk}

\subsection{On the error due to localization}
In this section we briefly give a heuristic understanding of the error due to the localization procedure, in comparison to the PF with resampling, tempering and jittering of Algorithm~\ref{alg:PF}. There are two errors to consider: the first is due to the modification of the likelihood function, and the second is due to interpolation. 

The first error is somewhat easier to understand. Consider the local likelihood \eqref{eq:loc_likelihood}. Since taking the limit as $\alpha \to 0$ in the Gaspari--Cohn function \eqref{eq:gaspari-cohn} yields $\rho_k^{\alpha}(j,s) \to 1$ for all $k \ge 1$, $j \in \{1, \dots, N_{\mathrm{loc}}\}$ and $s \in \{1, \dots, N_{\mathrm{obs}_k}\}$, we have that the local likelihood $g^{ \alpha, j}_k$ converges to the likelihood function $g_k$ as $\alpha \to 0$. Thus, as $\alpha \to 0$, the local ensembles in each subregion $D_j$ are weighted equally: if one considers a specific particle $u^i_{t_k}$ at assimilation time $t_k$, its local weights $w^{i, \alpha, (j)}_k$ for all $j = 1, \dots, N_{\mathrm{loc}}$ computed according to \eqref{eq:local_weights} converge to its global weight $w^i_k$ computed using \eqref{eq:basic_PF_weights_rec}, as $\alpha \to 0$. Now, if one forgoes resampling, tempering and jittering, and proceeds with a basic PF (described in \eqref{eq:basic_PF_weights_rec}) in each subregion, there are no resulting discontinuities (so no interpolation is necessary). Thus, in this simple setting, the LPF coincides with the basic PF described by the recursive relation \eqref{eq:basic_PF_weights_rec} as $\alpha \to 0$ (and should similarly converge to the filtering distribution as $N \to \infty$). Intuitively, then, one could be tempted to claim that as $\alpha \to 0$, the LPF converges to the PF, and so the error between the two might be somewhat quantified by looking at the difference between the standard and local likelihood functions. However, already by introducing resampling (not to mention tempering and jittering), the matter becomes much more complicated. 

Consider the same situation as before, with $\alpha \to 0$ so the local and global weights agree, although this time we allow resampling: in effect, we want to compare a \textit{local bootstrap PF} and a \textit{boostrap PF}. Clearly, due to the randomness within the resampling algorithms, even if the weights agree across subregions, we cannot discard the possibility that local particles might differ on the overlap regions. This leads us necessarily to the error due to interpolation.

To shed some light on this, introduce notation $\pi^{N, PF}$ for the bootstrap PF and $\pi^{N,LPF}$ for the bootstrap LPF. Recall that $\{ \mathring{D}_j \}_j \cup \{ F_{ew} \}_{(e,w)} \cup \{ G_{sn}\}_{(s,n)} \cup \{ H_{abcd}\}_{(a,b,c,d)}$, where $\mathring{D}_j = D_j \setminus (F_{ej} \cup F_{jw} \cup G_{jn} \cup G_{sj})$, form a partition of $D$. As $D$ is discretized in $N_u$ grid-points, for $A \subset D$ let $X_A$ denote the subset of grid-points of $D$ also in $A$, and $|X_A|$ the number of grid-points in $X_A$, so in particular
\begin{equation*}
	\sum_j |X_{\mathring{D}_j} | + \sum_{(e,w)} |X_{F_{(ew)}}| + \sum_{(s,n)} |X_{G_{(sn)}}| + \sum_{(a,b,c,d)} |X_{H_{(abcd)}}| = N_u.
\end{equation*}
Then  $\{ X_{\mathring{D}_j} \}_j \cup \{ X_{F_{ew}} \}_{(e,w)} \cup \{ X_{G_{sn}}\}_{(s,n)} \cup \{ X_{H_{abcd}}\}_{(a,b,c,d)}$ is a partition of $\R^{N_u}$. In particular, any function $u$ on $D$ can be identified with a vector in $\R^{N_u}$, and we can decompose it as
\begin{equation}\label{eq:vector_decomp}
	u = (\dots, u|_{\mathring{D}_j}, \dots, u|_{F_{(ew)}}, \dots, u|_{G_{(sn)}}, \dots, u|_ {H_{(abcd)}}, \dots),
\end{equation}
where $u|_A \in X_{A}$ is the restriction of $u$ on $A \subset D$, discretized as a vector in $\R^{|X_A|}$. Similarly, given functions on $\mathring{D}_j, F_{(ew)}, G_{(sn)}$ and $H_{(abcd)}$, identified as vectors in $\R^{|X_{\mathring{D}_j}|}, \R^{|X_{F_{(ew)}}|}, \R^{|X_{G_{(sn)}}|}$ and $\R^{|X_{H_{(abcd)}}|}$ respectively, one can define an element of $\R^{N_u}$ by concatenating the vectors as in \eqref{eq:vector_decomp}.

Denote by $\pi^{N, D_j}_{k}$ the local empirical measures on $\mathring{D}_j$ at assimilation time $t_k$ given by the local ensembles $\{u^{i,(j)}_{t_k}\}_{i = 1}^N$, i.e.~after resampling,
\begin{equation*}
	\pi^{N, \mathring{D}_j}_{k} = \frac{1}{N} \sum_{i = 1}^N \delta_{u^{i, (j)}_{t_k}|_{\mathring{D}_j}}, \quad \forall j = 1, \dots, N_{\mathrm{loc}},
\end{equation*}
and by $\pi^{N, F_{ew}}_{k}$ the local empirical measures on the EW-overlap regions, i.e.
\begin{equation*}
	\pi^{N, F_{ew}}_{k} = \frac{1}{N} \sum_{i = 1}^N \delta_{ \mathrm{Interp}_{ew}(u^{i, (e)}_{t_k}|_{F_{(ew)}}, u^{i, (w)}_{t_k}|_{F_{(ew)}})}, \quad \forall (e,w) \in \{ (e,w) \, : \, F_{ew} \text{ is EW-overlap in }D\},
\end{equation*}
and similarly by $\pi^{N, G_{sn}}_{k}$ and $\pi^{N, H_{abcd}}_{k}$ the local empirical measures on the SN-overlap and corner-overlap regions. For all $S \in \mathcal{B}(\R^{N_u})$, the bootstrap LPF can be written as
\begin{align*}
	\pi^{N, LPF}_{k}(S) 
	&= \sum_{j = 1}^{N_{\mathrm{loc}}}  \omega_{\mathring{D}_j}	\pi^{N, \mathring{D}_j}_{k}(S \cap X_{\mathring{D}_j}) + \sum_{(e,w)} \omega_{F_{ew}} \pi^{N, F_{ew}}_{k}(S \cap X_{F_{ew}}) + \sum_{(s,n)}\omega_{G_{sn}} \pi^{N, G_{sn}}_{k}(S \cap X_{G_{sn}}) \\
	&\quad+ \sum_{(a,b,c,d)} \omega_{H_{abcd}} \pi^{N, H_{abcd}}_{k}(S \cap X_{H_{abcd}}),
\end{align*}
where $\omega_{A} = |X_A|/N_u$ for $A \subset D$.

Now, after the first assimilation step we can expect $\pi^{N, LPF}_{1}(S) \approx \pi^{N, PF}_{1}(S)$ for $S \in \mathcal{B}(\cup_j X_{\mathring{D}_j})$ since $\alpha = 0$ and global and local weights agree (and they should be equal if we let $N \to \infty$). This is of course not the case when $S \in \mathcal{B}(\R^{N_u} \setminus \cup_j X_{\mathring{D}_j})$, and quantifying the difference between $\pi^{N, LPF}_{1}(S)$ and $\pi^{N, PF}_{1}(S)$ remains problematic. However, if the overlap regions are small, and the weights are smooth enough across subregions, one can hope that the overall difference between $\pi^{N, LPF}_{1}$ and $\pi^{N, PF}_{1}$ is small too. Sadly, this reasoning only holds up to the first assimilation time $t_1$. As the system moves forward in time, the errors in the bootstrap LPF due to interpolation in the overlap-regions propagate in space according to the model dynamics \eqref{eq:SPDE_general}, which, in a geophysical setting, are most likely nonlinear. Thus, at later assimilation times, $\pi^{N, LPF}_{1k}(S)$ and $\pi^{N, PF}_{k}(S)$ might not agree even for $S \in \mathcal{B}(\cup_j X_{\mathring{D}_j})$.

All these considerations should not discourage us. When developing PF in practice, we already allow for an approximation error (compared to the optimal filtering distribution) due to the finite-ness of $N$. The further we modify the basic PF, the bigger the error we expect in our estimate: the resampling, jittering and tempering procedures all introduce further approximation errors, necessarily diverging further from the optimal filter. Following along this reasoning, we do not expect the added error due to localization to have significant repercussions. In fact, when working with small $N$, the greater flexibility allowed by the local tempering procedures (compared to a global one) can even improve on the performance of the filter. We plan to explore the theoretical aspects of the localization error in more detail in future works. For the moment, we present some numerical results comparing the PF of Algorithm~\ref{alg:PF} and the LPF of Algorithm~\ref{alg:loc_PF} which show that the difference in performance between the two, when the parameters are properly calibrated, is indeed small.

\section{Numerical results: data-assimilation for the (viscous) stochastic RSW equations}\label{sec:numerics}

In this section we test the particle filter with tempering and jittering (comparing results from both the localized version of Algorithm~\ref{alg:loc_PF} and the non-localized version of Algorithm~\ref{alg:PF}) on a geophysical model from the SALT (Stochastic Advection by Lie Transport) framework \cite{Holm_SALT_15}. We will perform what in the data-assimilation literature is often referred to as a ``twin experiment", which is in fact simply a filtering problem: the dynamics of the signal, the sensor function and the distribution of the noise are all known, thus errors due to the misspecification of model parameters are avoided. The data is generated by fixing a realization of an SPDE as the signal, and perturbing it to obtain the observations; the particles of the (L)PF are evolved forward with the same SPDE model used to generate the signal, and the distribution of the noise and the sensor functions are known and used in the computation of the likelihood weights.
\begin{notation}
	For the purpose of clarity, in what follows we identify vectors or vector-valued functions with boldface characters.
\end{notation}
We consider the 2-dimensional SALT (viscous) Rotating Shallow Water equations, given by
\begin{equation}\label{eq:SRSW}
\begin{aligned}
  \mathrm{d} \mathbf{u}
	 &+ \bigg[ (\mathbf{u} \cdot \nabla) \mathbf{u} + \frac{f}{\mathrm{Ro}} \hat{\mathbf{z}} \times \mathbf{u} \bigg] \dt \\
	 &\begin{aligned} \, + \sum_n \left[ \left(\boldsymbol{\xi}_n \cdot \nabla \right) \mathbf{u}  + \nabla \boldsymbol{\xi}_n \cdot \mathbf{u} +\frac{f}{\mathrm{Ro}} \hat{\mathbf{z}} \times \boldsymbol{\xi}_n \right] \circ \mathrm{d} W_t^n &= \nu \Delta \mathbf{u} - \frac{1}{\mathrm{Fr}^2} \nabla \eta \dt, \\
	 \di \eta + \nabla \cdot(\eta \mathbf{u}) \dt  +\sum_n \nabla \cdot\left(\eta \boldsymbol{\xi}_n \right) \circ \mathrm{d} W_t^n 
	 &=0,
	 \end{aligned}
\end{aligned}
\end{equation}
where $\mathbf{u}(t, \mathbf{x}) = (u(t,\mathbf{x}),v(t,\mathbf{x}))$ is the flow velocity field and $\eta(t,\mathbf{x})$ is the height of the fluid column, $\hat{\mathbf{z}}$ is the unit vector pointing outwards and $f$ is the Coriolis parameter. The equations are stated in non-dimensional form, with domain $D = [0,1]^{\times 2}$ and $\mathbf{x} \in D$, so that the typical velocity, length and height scales are encoded in the parameters $\mathrm{Ro}$ and $\mathrm{Fr}$. In particular, if $U$ is the typical velocity-scale, $L$ the length-scale and $H$ the height-scale, the \textit{Rossby number} is defined as $\mathrm{Ro} =  U/fL$ and the \textit{Froude number} as $\mathrm{Fr} = U/ \sqrt{gH}$, where $g$ is the gravitational acceleration constant. Finally, the driving noise is given by a spatial Gaussian noise of the form
\begin{equation}\label{eq:noise_SRSW}
	\sum_{n \ge 1} \boldsymbol{\xi}_n(\mathbf{x}) \di W_t^n 
	= \sum_{n \ge 1} \left( \begin{matrix}
		\xi_n^u(\mathbf{x}) \\
		\xi_n^v(\mathbf{x})
	\end{matrix} \right) \di W_t^n, 
\end{equation}
where $\boldsymbol{\xi}_n(\mathbf{x}) = (\xi_n^u(\mathbf{x}), \xi_n^v(\mathbf{x}))$, $n \ge 1$ is a smooth vector field defined on the domain $D$.

Note that, compared to our general setup in Section~\ref{sec:set-up}, the noise term in the SPDE \eqref{eq:SRSW} is expressed in Stratonovich form. One can recover the It\^o formulation by using the classical conversion formula. As regards the infinite-dimensional noise \eqref{eq:noise_SRSW} itself, this corresponds to  \eqref{eq:noise_SPDE} with $\mathcal{K}=L^2(D)$ in each of the two coordinates $u$ and $v$.

The well-posedness of the solution of equation \eqref{eq:SRSW} on the 2-dimensional torus $\mathbb{T}^2$ has been established, in the viscous case, in Crisan~and~Lang~\cite{crisan_lang_RSW}. In particular, the authors show that for initial data $u_0$, $v_0$ and $\eta_0$ in $W^{1,2}(\mathbb{T}^2)$, for all $t$ up to a positive stopping time there exists a unique strong solution to \eqref{eq:SRSW} with $u_t, v_t$ and $\eta_t$ continuous in $W^{1,2}(\mathbb{T}^2)$ and in $L^2([0,T], W^{2,2}(\mathbb{T}^2))$. For further details, we refer to \cite[Theorem~3.1]{crisan_lang_RSW}. Using the existence and pathwise uniqueness proved in \cite{crisan_lang_RSW}, the Markov property can also be derived, along the lines of Remark~4.2.11 and Proposition~4.3.3 in \cite{rockner_spdes}. Thus, the conditions for the signal we stated in Section~\ref{sec:set-up} are satisfied, and we can take the (numerical) solution to \eqref{eq:SRSW} driven by a realization of the noise \eqref{eq:noise_SRSW} to be our signal process.

\begin{rmk}
	In the numerical experiments in this section we set a very small viscosity coefficient $\nu \ll 1$, so our simulations are in fact closer to the inviscid setting. To the best of our knowledge, well-posedness of the the inviscid RSW equations (with or without transport noise) is still an open problem.
\end{rmk}

\subsection{Experiments set-up}
We start by discretizing space and time: we denote by $\delta x$ and $\delta t$ the units of space and time respectively. We discretize the domain $D = [0,1]^{\times 2}$ into a $d \times d$ grid (with $d = 1/\delta x$), and fix $\delta t \ll 1$, so that $t \in \{0, \delta t, 2\delta t, \dots, m \delta t, \dots \}$. We set up our filtering experiment as follows: let $(u_t, v_t, \eta_t)$ be a (fixed) numerical realization of the SRSW equations \eqref{eq:SRSW}. We take the signal to be given by the height of the fluid $\eta_t$; in other words, we do \textit{not} observe at all the velocities. Any numerical solution $(u_t, v_t, \eta_t)$ to \eqref{eq:SRSW} belongs to $(\R^{d\times d})^{\times 2} \times \R^{d \times d}_{+}$, so, in particular, the signal $\eta_t \in \R^{d\times d}_{+}$, and it is a $d^2$-dimensional vector. For the observations, let the assimilation times $t_k = k r \delta t$, for some fixed $r \in \N$ (we will experiment with different values of $r$ in what follows) and all $k \ge 1$ (we assume no observation at time $t=0$), and recall expression \eqref{eq:discrete_obs}.
%\begin{notation}
%	 Throughout this section, let the grid-points of the discretized domain be denoted by $x^s$ with $s = 1, \dots, d^2$, and similarly think of (numerical) solutions $(u_t, v_t, \eta_t)$ to \eqref{eq:SRSW} as vectors, with components $1, \dots, d^2$ denoted with a superscript, so that for all $s$, $(u^s_t, v^s_t, \eta^s_t)$ is the solution to \eqref{eq:SRSW} at grid-point $x^s$. 
%\end{notation}

 For a set of indices $\mathcal{J}$ with $|\mathcal{J}| = N_{\mathrm{obs}}$, let $h_{\mathcal{J}}: \R^{d^2} \to \R^{N_{\mathrm{obs}}}$ be the projection operator that takes a vector in $\R^{d^2}$ and returns a vector in $\R^{N_{\mathrm{obs}}}$ by selecting only the components corresponding the indices in $\mathcal{J}$. Define the observations $Y$ as
\begin{equation}\label{eq:obs_numerics_vec}
	Y_{k} = h_{\mathcal{J}}(\eta_{t_k}) + \sigma B_{k}, \quad \forall k \ge 1,
\end{equation}
where $B_k \iid N(0, \mathrm{Id})$ are independent $N_{\mathrm{obs}}$-dimensional scaled multivariate standard normal random variables, and $\sigma \in \R^+.$

\begin{rmk}
	One can write \eqref{eq:obs_numerics_vec} in the form of \eqref{eq:discrete_obs} as follows: for a collection of $N_{\mathrm{obs}}$ grid-points $ \{z^1, \dots, z^{ N_{\mathrm{obs}}} \} \in D$, take the observations $Y$ to be given by
	\begin{equation*}
		Y_{k} = 
		\left( \begin{array}{l}
			Y^1_k \\
			\vdots \\
			Y_k^{N_{\mathrm{obs}}}
		\end{array}
		\right)	
		=
		\left( \begin{array}{c}
			\eta_{t_k}(z^1) + \sigma B^1_{k} \\
			\vdots \\
			\eta_{t_k}(z^{N_{\mathrm{obs}}}) + \sigma B^{N_{\mathrm{obs}}}_{k}
		\end{array}
		\right),	
	\end{equation*}
	where by $\eta_{t_k}(z)$ we mean the value of the signal $\eta$ at time $t_k = k r \delta t$ and ``evaluated" at grid-point $z$, and $B^i_k$ are i.i.d. normal random variables (1-dimensional) for $i  = 1, \dots, N_{\mathrm{obs}}$ and all $k \ge 1$.
\end{rmk}
