  \draw[fill=white] (0.4,0) -- (0.8,0.4) -- (1.2,-0) -- (0.8,-0.4) -- cycle;
\end{tikzpicture}  
}$B$ means that $A$ has an unknown influence on $B$.

\end{eg}

\begin{eg}
\label{Eg:absorbing_element}
More generally, for any monoid $M$ we can form a new monoid $M \cup \{0\}$ where $0$ is a new absorbing element.   Thus, in $M \cup \{0\}$ the product of elements of $M$ is defined as before, but $m \cdot 0 = 0 \cdot m = 0$ for all $m \in M$, and $0 \cdot 0 = 0$.   This new monoid contains $M$ as a submonoid.   As before, there are at least three interpretations of the element $0$:
\begin{enumerate}
\item
We can use $0$ to denote an effect whose value varies depending on the circumstances.   In this case we can use the absence of an edge from a vertex $v$ to a vertex $w$ to indicate either:
\begin{itemize}
\item[(a)] there is \emph{no direct effect} of $v$ on $w$, or
\item[(b)] the effect of $v$ on $w$ is \emph{unknown}.
\end{itemize}
\item
We can use $0$ to denote an effect that we deem negligible.   In this case we can again use either interpretation (a) or (b) of the absence of an edge.
\item 
We can use $0$ to denote an unknown effect.   In this case we can use interpretation (a) of the absence of an edge, but interpretation (b) is awkward, because then the absence of an edge means the same thing as an edge labeled by $0$.
\end{enumerate}
\end{eg}

\begin{eg}
\label{Eg:necessary_stimulus}
