(F'''') edge node[right]{$\disc(g + g')$} (F''''')
(G'''') edge node[left]{$\alpha + \alpha'$} (G''''')
(E'''') edge node[above]{$i_1 + i_1'$} (G'''')
(E''''') edge node[below]{$i_2 + i_2'$} (G''''')
(F''''') edge node[below]{$o_2 + o_2'$} (G''''');
\end{tikzpicture}
\]
\end{thm}

\begin{proof}
The categories $\Set$ and $\Gph/G_L$ have finite colimits (see \cref{Prop:Set-labeled_graph}(a)) and $\disc \maps \Set \to \Gph/G_L$ preserves them, since it is a left adjoint.   The theorem thus follows from the theory of structured cospans: see   \cite[Sec. 6.1]{BaezCourser2020} and \cite[Sec. 6.2]{BaezCourserVasilakopoulou2022} for two different proofs.   Using the same assumptions,  Theorem 2.3 of \cite{Patterson2023} yields a stronger result: $\lOpen(\Gph/ G_L)$ is a cocartesian equipment, and thus a cocartesian double category.
\end{proof}

If $M$ is a monoid we can define open $M$-labeled graphs as in \cref{Defn:Open_set-labeled_graphs}, not using the monoid structure, only the underlying set of $M$.  However, we have the extra ability to convert any open $M$-labeled graph into an `open $M$-graded category', which we now define.   First, note that the categories of sets and $M$-labeled categories are related by a pair of adjoint functors
\[
\begin{tikzcd}
            \ \phantom{X} \Set\phantom{X} \arrow[r, bend left = 20, shift left=1ex, "{\Disc}"{name=G}] & \ \cat/\B M \arrow[l, bend left = 20, shift left=.5ex, pos = 0.4, "\mathrm{Vert}"{name=F}]
            \arrow[phantom, from=F, to=G, "\scriptstyle\boldsymbol{\bot}"].
        \end{tikzcd}
    \]
where
\begin{itemize}
\item $\Disc \maps \Set \to \cat/\B M$ takes a set $S$ to the unique $M$-graded category with object set $S$ and only identity morphisms;
\item $\mathrm{Vert} \maps \cat/\B M \to \Set$ takes an $M$-graded category to its set of objects.
\end{itemize}
We can apply the theory of structured cospans to the left adjoint $\Disc$, as follows. 

\begin{defn}
\label{Defn:Open_monoid-labeled_category}
Given a monoid $M$, an \define{open} $M$\define{-graded category} is a diagram in $\cat/\B M$ of the form
\[
\begin{tikzpicture}[scale=1.2]
\node (A) at (0,0) {$\Disc(A)$};
\node (B) at (1,1) {$X$};
\node (C) at (2,0) {$\Disc(B)$};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above, pos=0.3]{$i$} (B)
(C)edge node[above, pos=0.3]{$o$}(B);
\end{tikzpicture}
\]
for some sets $A$ and $B$.   We call this an open $M$-graded category \define{from} $A$ \define{to} $B$.
\end{defn}

\begin{thm}
\label{Thm:Open_monoid-labeled_categories}
For any monoid $M$, there is a symmetric monoidal double category of open $M$-labeled categories,
$\lOpen(\cat/\B M)$, in which
\begin{itemize}
\item an object is a set,
\item a vertical 1-morphism from $A$ to $B$ is a function $f \maps A \to B$,
\item a horizontal 1-cell from $A$ to $B$ is an open $M$-graded category  from $A$ to $B$:
\begin{displaymath}
\begin{tikzpicture}[scale=1.5]
\node (A) at (0,0) {$\Disc(A)$};
\node (B) at (1,0) {$X$};
\node (C) at (2,0) {$\Disc(B)$,};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above]{$i$} (B)
(C) edge node[above]{$o$} (B);
\end{tikzpicture}
\end{displaymath}
\item a 2-morphism is a \define{map of open} $M$\define{-graded categories}, that is, a commutative diagram in $\cat/\B M$ of the form
\begin{displaymath}
\begin{tikzpicture}[scale=1.5]
\node (A) at (-0.5,0) {$\Disc(A)$};
\node (B) at (1,0) {$X$};
\node (C) at (2.5,0) {$\Disc(B)$};
\node (A') at (-0.5,-1) {$\Disc(A')$};
\node (B') at (1,-1) {$X'$};
\node (C') at (2.5,-1) {$\Disc(B')$.};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above]{$i$} (B)
(C) edge node[above]{$o$} (B)
(A') edge node[below]{$i'$} (B')
(C') edge node[below]{$o'$} (B')
(A) edge node [left]{$\Disc(f)$} (A')
(B) edge node [left]{$\alpha$} (B')
(C) edge node [right]{$\Disc(g)$} (C');
\end{tikzpicture}
\end{displaymath}
\end{itemize}
Vertical composition is done using composition in $\Set$, while horizontal composition
is done using pushouts in $\cat/ \B M$. The tensor product of two horizontal 1-cells is
\[
\begin{tikzcd}[column sep={.4in,between origins}, row sep=.08in]
& X &&&& X' &&&& X+X' & \\
&&&\otimes&&&& = &&&& \\
\Disc(A)\ar[uur,"i" pos=0.3]&& \Disc(B)\ar[uul,"o"' pos=0.3] && \Disc(A')\ar[uur,"i'" pos=0.3] && \Disc(B')\ar[uul,"o'"' pos=0.3] && \Disc(A+A')\ar[uur,"i+i'" pos=0.3] && \Disc(B+B')\ar[uul,"o+o'"' pos=0.3]
\end{tikzcd}
\]
where $i + i'$ and $o + o'$ are defined using the fact that $\Disc$ preserves binary coproducts, and the tensor product of two 2-morphisms is given by:
\[
\begin{tikzpicture}[scale=1.5]
\node (E) at (2,0) {$\Disc(A_1)$};
\node (F) at (4,0) {$\Disc(B_1)$};
\node (G) at (3,0) {$X_1$};
\node (E') at (2,-1) {$\Disc(A_2)$};
\node (F') at (4,-1) {$\Disc(B_2)$};
\node (G') at (3,-1) {$X_2$};
\node (E'') at (6.5,0) {$\Disc(A_1')$};
\node (F'') at (8.5,0) {$\Disc(B_1')$};
\node (G'') at (7.5,0) {$X_1'$};
\node (E''') at (6.5,-1) {$\Disc(A_2')$};
\node (F''') at (8.5,-1) {$\Disc(B_2')$};
\node (G''') at (7.5,-1) {$X_2'$};
\node (X) at (5.25,-0.5) {$\otimes$};
\node (E'''') at (3.5,-2) {$\Disc(A_1 + A_1')$};
\node (F'''') at (7,-2) {$\Disc(B_1 + B_1')$};
\node (G'''') at (5.25,-2) {$X_1 + X_1'$};
\node (E''''') at (3.5,-3) {$\Disc(A_2 + A_2')$};
\node (F''''') at (7,-3) {$\Disc(B_2 + B_2').$};
\node (G''''') at (5.25,-3) {$X_2 + X_2'$};
\node (Y) at (2,-2.5) {$=$};
\path[->,font=\scriptsize,>=angle 90]
(F) edge node[above]{$o_1$} (G)
(E) edge node[left]{$\Disc(f)$} (E')
(F) edge node[right]{$\Disc(g)$} (F')
(G) edge node[left]{$\alpha$} (G')
(E) edge node[above]{$i_1$} (G)
(E') edge node[below]{$i_2$} (G')
(F') edge node[below]{$o_2$} (G')
(F'') edge node[above]{$o_1'$} (G'')
(E'') edge node[left]{$\Disc(f')$} (E''')
(F'') edge node[right]{$\Disc(g')$} (F''')
(G'') edge node[left]{$\alpha'$} (G''')
(E'') edge node[above]{$i_1'$} (G'')
(E''') edge node[below]{$i_2'$} (G''')
(F''') edge node[below]{$o_2'$} (G''')
(F'''') edge node[above]{$o_1 + o_1'$} (G'''')
(E'''') edge node[left]{$\Disc(f + f')$} (E''''')
(F'''') edge node[right]{$\Disc(g + g')$} (F''''')
(G'''') edge node[left]{$\alpha + \alpha'$} (G''''')
(E'''') edge node[above]{$i_1 + i_1'$} (G'''')
(E''''') edge node[below]{$i_2 + i_2'$} (G''''')
(F''''') edge node[below]{$o_2 + o_2'$} (G''''');
\end{tikzpicture}
\]
\end{thm}

\begin{proof}
The categories $\Set$ and $\Gph/\B M$ have finite colimits (see \cref{Prop:Monoid-labeled_category}(a)) and $\Disc \maps \Set \to \Gph/\B M$ preserves them, since it is a left adjoint.  The theory of structured cospans thus implies that $\lOpen(\Gph/G_L)$ is a symmetric monoidal double category as above.  In fact \cite[Thm.\ 2.3]{Patterson2023} implies that $\lOpen(\Gph/ G_L)$ is a cocartesian equipment.
\end{proof}

Now we construct a map that turns open $M$-labeled graphs into open $M$-graded categories.
To do this we use \cref{Lem:Free_monoid-labeled_category}, which says that there is an adjunction
\[
\begin{tikzcd}
            \ \Gph/G_M\arrow[r, bend left = 20, shift left=1ex, "\Free_M"{name=G}] & \ \cat/\B M \arrow[l, bend left = 20, shift left=.5ex, "\Und_M"{name=F}]
            \arrow[phantom, from=F, to=G, "\scriptstyle\boldsymbol{\bot}"].
        \end{tikzcd}
\]

\begin{thm}
\label{Thm:Converting_open_graphs_to_open_categories}
For any monoid $M$ there is a symmetric monoidal double functor 
\[     F_M \maps \lOpen(\Gph/G_M) \to \lOpen(\cat/\B M) \]
acting as follows:
\begin{itemize}
\item on objects, $F_M$ sends any set to itself,
\item on vertical 1-morphisms, $F_M$ sends any function to itself
\item on horizontal 1-cells, $F_M$ sends any open $M$-labeled graph
\begin{displaymath}
\begin{tikzpicture}[scale=1.5]
\node (A) at (0,0) {$\Disc(A)$};
\node (B) at (1,0) {$X$};
\node (C) at (2,0) {$\Disc(B)$,};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above]{$i$} (B)
(C) edge node[above]{$o$} (B);
\end{tikzpicture}
\end{displaymath}
to the open $M$-graded category
\begin{displaymath}
\begin{tikzpicture}[scale=1.5]
\node (A) at (0,0) {$\Disc(A)$};
\node (B) at (1.5,0) {$\Free_M(X)$};
\node (C) at (3,0) {$\Disc(B)$,};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above]{$i$} (B)
(C) edge node[above]{$o$} (B);
\end{tikzpicture}
\end{displaymath}
\item on 2-morphisms, $F_M$ sends any map of open $M$-labeled graphs
\begin{displaymath}
\begin{tikzpicture}[scale=1.5]
\node (A) at (-0.5,0) {$\Disc(A)$};
\node (B) at (1,0) {$X$};
\node (C) at (2.5,0) {$\Disc(B)$};
\node (A') at (-0.5,-1) {$\Disc(A')$};
\node (B') at (1,-1) {$X'$};
\node (C') at (2.5,-1) {$\Disc(B')$.};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above]{$i$} (B)
(C) edge node[above]{$o$} (B)
(A') edge node[below]{$i'$} (B')
(C') edge node[below]{$o'$} (B')
(A) edge node [left]{$\Disc(f)$} (A')
(B) edge node [left]{$\alpha$} (B')
(C) edge node [right]{$\Disc(g)$} (C');
\end{tikzpicture}
\end{displaymath}
to the map of open $M$-graded categories
\begin{displaymath}
\begin{tikzpicture}[scale=1.5]
\node (A) at (-0.5,0) {$\Disc(A)$};
\node (B) at (1,0) {$\Free_M(X)$};
\node (C) at (2.5,0) {$\Disc(B)$};
\node (A') at (-0.5,-1) {$\Disc(A')$};
\node (B') at (1,-1) {$\Free_M(X')$};
\node (C') at (2.5,-1) {$\Disc(B')$.};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above]{$i$} (B)
(C) edge node[above]{$o$} (B)
(A') edge node[below]{$i'$} (B')
(C') edge node[below]{$o'$} (B')
(A) edge node [left]{$\Disc(f)$} (A')
(B) edge node [left]{$\Free_M(\alpha)$} (B')
(C) edge node [right]{$\Disc(g)$} (C');
\end{tikzpicture}
\end{displaymath}
\end{itemize}
\end{thm}

\begin{proof} 
Theorems 4.2 and 4.3 of \cite{BaezCourser2020} give a general way to construct maps between structured cospan double categories.   The present theorem is a straightforward application of these, which only requires checking that the following diagram commutes up to natural isomorphism
\begin{displaymath}
\begin{tikzpicture}[scale=1]
\node (A) at (0,0) {$\Set$};
\node (B) at (2,0.8) {$\Gph/G_M$};
\node (C) at (2,-0.8) {$\Cat/\B M$};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above]{$\disc$} (B)
(A) edge node[below]{$\disc$} (C)
(B) edge node [right]{$\Free_M$} (C);
\end{tikzpicture}
\end{displaymath}
 and that all the arrows in this diagram preserve finite colimits (since they are left adjoints).  
 \end{proof}

Recall from \cref{Defn:Kleisli_category} that for any monoid $M$ there is a category $\K(\Gph/G_M)$ of $M$-labeled graphs and Kleisli morphisms between these, where a Kleisli morphism from $(G,\ell)$ to $(G',\ell')$ is defined to be a map between free $M$-graded categories
 \[   f \maps \Free_M(G,\ell) \to \Free_M(G',\ell')  .\]
We can use the theory of structured cospans to define a double category of \emph{open} $M$-labeled graphs and Kleisli morphisms.  To do this, we use the functor
\[    \Phi \maps \Set \to K(\Gph/G_M) \]
defined as follows:
\begin{itemize}
\item $\Phi$ sends any set $S$ to the unique $M$-graded category with object set $S$ and only identity morphisms.  Note that this $M$-graded category is $\Free_M(G,\ell)$ where $G$ is the graph with vertex set $S$ and no edges, and $\ell$ is the only possible $\ell$-labeling of $G$. 
\item $\Phi$ sends any function $f \maps S \to T$ to the unique map of $M$-graded categories acting as $f$ on objects.
\end{itemize}

 \begin{thm}
\label{Thm:Open_monoid-labeled_graphs}
For any monoid $M$, there is a symmetric monoidal double category of open $M$-labeled graphs and Kleisli
morphisms, $\lOpen(K(\Gph/G_M))$, in which
\begin{itemize}
\item an object is a set,
\item a vertical 1-morphism from $A$ to $B$ is a function $f \maps A \to B$,
\item a horizontal 1-cell from $A$ to $B$ is an open $M$-labeled graph from $A$ to $B$:
\begin{displaymath}
\begin{tikzpicture}[scale=1.5]
\node (A) at (0,0) {$\Phi(A)$};
\node (B) at (1,0) {$X$};
\node (C) at (2,0) {$\Phi(B)$,};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above]{$i$} (B)
(C) edge node[above]{$o$} (B);
\end{tikzpicture}
\end{displaymath}
\item a 2-morphism is a \define{Kleisli morphism of open $M$-labeled graphs}, that is, a commutative diagram in $\K(\Gph/G_M)$ of the form
\begin{displaymath}
\begin{tikzpicture}[scale=1.5]
\node (A) at (-0.5,0) {$\Phi(A)$};
\node (B) at (1,0) {$X$};
\node (C) at (2.5,0) {$\Phi(B)$};
\node (A') at (-0.5,-1) {$\Phi(A')$};
\node (B') at (1,-1) {$X'$};
\node (C') at (2.5,-1) {$\Phi(B')$.};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above]{$i$} (B)
(C) edge node[above]{$o$} (B)
(A') edge node[below]{$i'$} (B')
(C') edge node[below]{$o'$} (B')
(A) edge node [left]{$\Phi(f)$} (A')
(B) edge node [left]{$\alpha$} (B')
(C) edge node [right]{$\Phi(g)$} (C');
\end{tikzpicture}
\end{displaymath}
\end{itemize}
Vertical composition is done using composition in $\Set$, while horizontal composition
is done using pushouts in $\K(\Gph/G_M)$. The tensor product of two open $M$-labeled graphs is
\[
\begin{tikzcd}[column sep={.4in,between origins}, row sep=.08in]
& X &&&& X' &&&& X+X' & \\
&&&\otimes&&&& = &&&& \\
\Phi(A)\ar[uur,"i" pos=0.3]&& \Phi(B)\ar[uul,"o"' pos=0.3] && \Phi(A')\ar[uur,"i'" pos=0.3] && \Phi(B')\ar[uul,"o'"' pos=0.3] && \Phi(A+A')\ar[uur,"i+i'" pos=0.3] && \Phi(B+B')\ar[uul,"o+o'"' pos=0.3]
\end{tikzcd}
\]
where $i + i'$ and $o + o'$ are defined using the fact that $\Phi$ preserves binary coproducts, and the tensor product of two 2-morphisms is given by:
\[
\begin{tikzpicture}[scale=1.5]
\node (E) at (2,0) {$\Phi(A_1)$};
\node (F) at (4,0) {$\Phi(B_1)$};
\node (G) at (3,0) {$X_1$};
\node (E') at (2,-1) {$\Phi(A_2)$};
\node (F') at (4,-1) {$\Phi(B_2)$};
\node (G') at (3,-1) {$X_2$};
\node (E'') at (6.5,0) {$\Phi(A_1')$};
\node (F'') at (8.5,0) {$\Phi(B_1')$};
\node (G'') at (7.5,0) {$X_1'$};
\node (E''') at (6.5,-1) {$\Phi(A_2')$};
\node (F''') at (8.5,-1) {$\Phi(B_2')$};
\node (G''') at (7.5,-1) {$X_2'$};
\node (X) at (5.25,-0.5) {$\otimes$};
\node (E'''') at (3.5,-2) {$\Phi(A_1 + A_1')$};
\node (F'''') at (7,-2) {$\Phi(B_1 + B_1')$};
\node (G'''') at (5.25,-2) {$X_1 + X_1'$};
\node (E''''') at (3.5,-3) {$\Phi(A_2 + A_2')$};
\node (F''''') at (7,-3) {$\Phi(B_2 + B_2').$};
\node (G''''') at (5.25,-3) {$X_2 + X_2'$};
\node (Y) at (2,-2.5) {$=$};
\path[->,font=\scriptsize,>=angle 90]
(F) edge node[above]{$o_1$} (G)
(E) edge node[left]{$\Phi(f)$} (E')
(F) edge node[right]{$\Phi(g)$} (F')
(G) edge node[left]{$\alpha$} (G')
(E) edge node[above]{$i_1$} (G)
(E') edge node[below]{$i_2$} (G')
(F') edge node[below]{$o_2$} (G')
(F'') edge node[above]{$o_1'$} (G'')
(E'') edge node[left]{$\Phi(f')$} (E''')
(F'') edge node[right]{$\Phi(g')$} (F''')
(G'') edge node[left]{$\alpha'$} (G''')
(E'') edge node[above]{$i_1'$} (G'')
(E''') edge node[below]{$i_2'$} (G''')
(F''') edge node[below]{$o_2'$} (G''')
(F'''') edge node[above]{$o_1 + o_1'$} (G'''')
(E'''') edge node[left]{$\Phi(f + f')$} (E''''')
(F'''') edge node[right]{$\Phi(g + g')$} (F''''')
(G'''') edge node[left]{$\alpha + \alpha'$} (G''''')
(E'''') edge node[above]{$i_1 + i_1'$} (G'''')
(E''''') edge node[below]{$i_2 + i_2'$} (G''''')
(F''''') edge node[below]{$o_2 + o_2'$} (G''''');
\end{tikzpicture}
\]
\end{thm}

\begin{proof}
As mentioned in the proof of \cref{Thm:Open_set-labeled_graphs}, a commonly stated theorem for constructing a symmetric monoidal double category of $F$-structured cospans assumes that we have categories $\A$ and $\X$ with finite colimits and a functor $F \maps \A \to \X$ that preserves them.   We would like to apply this theorem to the functor $\Phi \maps  \Set \to \K(\Gph/G_M)$.  Unfortunately, while the category $\Set$ has finite colimits, $\Phi$ preserves them, and the Kleisli category $\K(\Gph/G_M)$ has finite coproducts, this Kleisli category does not have pushouts.  Luckily, if one examines the proof of the commonly stated theorem, it becomes clear that we only need pushouts at one point: to compose structured cospans.  In the case at hand, this means taking pushouts of this sort:
\[
\begin{tikzpicture}[scale=1]
\node (A) at (0,0) {$\Phi(A)$};
\node (B) at (1,1) {$X$};
\node (C) at (2,0) {$\Phi(B)$};
\node (D) at (3,1) {$Y$};
\node (E) at (4,0) {$\Phi(C)$};
\node (F) at (2,2) {$X +_{\Phi(B)} Y$};
\node (push) at (2,1.4) {\rotatebox{135}{$\ulcorner$}};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above, pos=0.3]{$i$} (B)
(C) edge node[above, pos=0.3]{$o$}(B)
(C) edge node[above, pos=0.3]{$i'$} (D)
(E) edge node[above, pos=0.3]{$o'$}(D)
(B) edge node[above, pos=0.3]{$$} (F)
(D) edge node[above, pos=0.3]{$$}(F);
\end{tikzpicture}
\]
where $X$ and $Y$ are free $M$-graded categories.   This pushout exists in $\cat/\B M$, and the result is a free $M$-graded category, because in forming the pushout we do not need to identify any morphisms, only objects.  It follows that this pushout also exists in $\K(\Gph/G_M)$.   
\end{proof}

Finally, given a commutative monoid $C$, we can define a symmetric monoidal double category of open $C$-labeled finite graphs and additive morphisms.  However,  we cannot do this using structured cospans and the left adjoint $\Fin\Set \to \C\Fin\Gph$ to the functor assigning any $C$-labeled finite graph its set of vertices, since $\C\Fin\Gph$ does not have finite coproducts or pushouts, not even the limited class of pushouts that would be used to compose structured cospans.  Thus, it seems we must  invoke the theory of \emph{decorated} cospans, introduced by Fong \cite{Fong2015,FongThesis} and later brought up to the level of double categories \cite{BaezCourserVasilakopoulou2022}.

In this approach we view an open $C$-labeled finite graph 
\[
\begin{tikzpicture}[scale=1.2]
\node (A) at (0,0) {$\disc(A)$};
\node (B) at (1,1) {$X$};
\node (C) at (2,0) {$\disc(B)$};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above, pos=0.3]{$i$} (B)
(C)edge node[above, pos=0.3]{$o$}(B);
\end{tikzpicture}
\]
in a new way.   We think of it as a cospan of finite sets
\[
\begin{tikzpicture}[scale=1.2]
\node (A) at (0,0) {$A$};
\node (B) at (1,1) {$V$};
\node (C) at (2,0) {$B$};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above, pos=0.3]{$i$} (B)
(C)edge node[above, pos=0.3]{$o$}(B);
\end{tikzpicture}
\]
where $V$ is `decorated' with some extra stuff: namely, a $C$-labeled finite graph $X$ having $V$ as its set of vertices.   We think of this `decoration' $X$ as an object of the category $F(V)$, where $F \maps \Fin\Set \to \Cat$ maps each finite set to the category of $C$-labeled finite graphs with that set of vertices, and additive morphisms between these.

In general, the theory of decorated cospans gives a symmetric monoidal double category  $F\lCsp$ from a category $\A$ with finite colimits and a symmetric lax monoidal pseudofunctor $F \maps (\A,+) \to (\Cat,\times)$.     In this double category $F\lCsp$:
\begin{itemize}
\item an object is an object of $\A$;
\item a vertical 1-morphism is a morphism of $\A$;
\item a horizontal 1-cell is an $F$\define{-decorated cospan}, that is,
a diagram in $\A$ of the form
\[
\begin{tikzpicture}[scale=1]
\node (A) at (0,0) {$A$};
\node (B) at (1,1) {$M$};
\node (C) at (2,0) {$B$};
%\node (D) at (2.6,0) {$x \in F(m))$};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above, pos = 0.25]{$i$} (B)
(C) edge node[above, pos = 0.25]{$o$} (B);
\end{tikzpicture}
\]
together with a \define{decoration} $d \in F(M)$;
\item a 2-morphism is a \define{map of} $F$\define{-decorated cospans}, that is,
a commutative diagram in $\A$ of the form
\[
\begin{tikzpicture}[scale=1.5,baseline=(current bounding box.center)]
\node (A) at (0,0.5) {$A$};
\node (A') at (0,-0.5) {$A'$};
\node (B) at (1,0.5) {$M$};
\node (C) at (2,0.5) {$B$};
\node (C') at (2,-0.5) {$B'$};
\node (D) at (1,-0.5) {$M'$};
\node (E) at (3,0.5) {$d \in F(M)$};
\node (F) at (3,-0.5) {$d' \in F(M')$};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above]{$i$} (B)
(C) edge node[above]{$o$} (B)
(A) edge node[left]{$f$} (A')
(C) edge node[right]{$g$} (C')
(A') edge node[below] {$i'$} (D)
(C') edge node[below] {$o'$} (D)
(B) edge node [left] {$h$} (D);
\end{tikzpicture}
\]
together with a \define{decoration morphism} $\tau \maps F(h)(d) \to d'$ in $F(M')$.
\end{itemize}
A key piece of the symmetric lax monoidal pseudofunctor $F$ is its `laxator', which gives for each pair of objects $M,M' \in \A$ a functor
\[   \phi_{M,M'} \maps F(M) \times F(M') \to F(M+M')  .\] 
This is used to compose $F$-decorated cospans, as follows.    Given a composable pair of $F$-decorated cospans
\[
\begin{tikzpicture}[scale=1]
\node (A) at (0,0) {$A$};
\node (B) at (1,1) {$M$};
\node (C) at (2,0) {$B$};
\node (D) at (3,1) {$d \in F(M)$};
\node (A') at (5,0) {$B$};
\node (B') at (6,1) {$N$};
\node (C') at (7,0) {$C$};
\node (D') at (8,1) {$d' \in F(M')$};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above, pos = 0.25]{$i$} (B)
(C) edge node[above, pos = 0.25]{$o$} (B)
(A') edge node[above, pos = 0.25]{$i'$} (B')
(C') edge node[above, pos = 0.25]{$o'$} (B');
\end{tikzpicture}
\]
we define their composite to be 
\[
\begin{tikzpicture}[scale=1]
\node (A) at (0,0) {$A$};
\node (B) at (1,1) {$M$};
\node (C) at (2,0) {$B$};
\node (B') at (3,1) {$M'$};
\node (C') at (4,0) {$C$.};
\node (D) at (2,2) {$M+_B M'$};
\node (E) at (7,2) { $F(j) \left( \phi_{M,M'} (d,d') \right) \in F(M +_B M') $};
\node (push) at (2,1.4) {\rotatebox{135}{$\ulcorner$}};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above, pos = 0.25]{$i$} (B)
(C) edge node[above, pos = 0.25]{$o$} (B)
(C) edge node[above, pos = 0.25]{$i'$} (B')
(C') edge node[above, pos = 0.25]{$o'$} (B')
(B) edge node[above, pos = 0.25]{} (D)
(B') edge node[above, pos = 0.25]{} (D);
\end{tikzpicture}
\]
Here the cospans are composed using a pushout in $\A$, while the decoration is defined using
the laxator and $j \maps M + M' \to M +_B M'$, the canonical map from the coproduct to the pushout.  For details see \cite[Sec.\ 2]{BaezCourserVasilakopoulou2022}.

To define the double category of $C$-labeled finite graphs using this machinery we take $\A = \Fin\Set$.  We want a decoration of $V \in \Fin\Set$ to be a $C$-labeled finite graph with $V$ as its set of vertices.   Thus we let $F \maps (\Fin\Set, +) \to (\Cat, \times)$ assign to $V$ the category $F(V)$ where:
\begin{itemize}
\item An object is a $C$-labeled finite graph with vertex set $V$, say $(V, E, s, t, \ell) $.
\item A morphism is an additive morphism of $C$-labeled graphs that is the identity on vertices.
\end{itemize}
We let $F$ assign to each function $g \maps V \to V'$ the functor $F(g) \maps F(V) \to F(V')$ where:
\begin{itemize}
\item $F(g)$ sends any object $(V, E, s, t, \ell)$ to $(V', E, g \circ s, g \circ t, \ell)$.
\item $F(g)$ sends any morphism $f \maps (V, E, s, t, \ell) \to (V, E', s', t', \ell') $ in $F(V)$, which is determined by a map of graphs $1_V \maps V \to V$, $f_1 \maps E \to E'$, to the morphism $F(g)(f) \maps (V, E, f_1 \circ s, f_1 \circ t, \ell) \to (V', E', f_1 \circ s, f_1 \circ t, \ell')$ in $F(V')$ determined  by the map of graphs $1_{V'} \maps V' \to V'$, $f_1 \maps E \to E'$.  
\end{itemize}
To parse this, it is useful to review the definition of `additive morphism', \cref{Defn:Morphism-of-commutative-monoid-labeled-graphs}.   

Next we must equip $F$ with the structure of a lax monoidal pseudofunctor \cite{BaezCourserVasilakopoulou2022}.  We omit some details here.  The most important structure is the laxator
\[   \phi_{V,V'} \maps F(V) \times F(V') \to F(V + V')  .\]
On objects, this takes a $C$-labeled finite graph with vertex set $V$, say $(V,E,s,t,\ell)$, and a $C$-labeled finite graph with vertex set $V'$, say $(V',E',s',t',\ell')$, and gives the $C$-labeled finite graph 
\[        (V+V', E+E', s+s', t+t', \langle \ell, \ell' \rangle) \]
with vertex set $V + V'$.  Here $\langle \ell, \ell'\rangle \maps E + E' \to C$ is defined to equal $\ell$ on $E$ and $\ell'$ on $E'$.

Given that $F \maps (\Fin\Set, +) \to (\Cat, \times)$ is a symmetric lax monoidal pseudofunctor, the 
theory of decorated cospans gives this result:

 \begin{thm}
\label{Thm:Open_commutative_monoid-labeled_graphs}
For any commutative monoid $C$, there is a symmetric monoidal double category of open $C$-labeled finite graphs and additive morphisms, $\lOpen(C\Fin\Gph)$, in which
\begin{itemize}
\item an object is a finite set;
\item a vertical 1-morphism from $A$ to $B$ is a function $f \maps A \to B$;
\item a horizontal 1-cell from $A$ to $B$ is an open $C$-labeled finite graph from $A$ to $B$:
\begin{displaymath}
\begin{tikzpicture}[scale=1.5]
\node (A) at (0,0) {$A$};
\node (B) at (1,0) {$M$};
\node (C) at (2,0) {$B$};
\node (D) at (3,0) {$d \in F(M);$};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above]{$i$} (B)
(C) edge node[above]{$o$} (B);
\end{tikzpicture}
\end{displaymath}
\item a 2-morphism is an \define{additive morphism of open} $C$\define{-labeled graphs}, that is, a commutative diagram in $C\Fin\Gph$ of the form
\begin{displaymath}
\begin{tikzpicture}[scale=1.5]
\node (A) at (-0.5,0) {$A$};
\node (B) at (1,0) {$M$};
\node (C) at (2.5,0) {$B$};
\node (D) at (4,0) {$d \in F(M)$};
\node (A') at (-0.5,-1) {$A'$};
\node (B') at (1,-1) {$M'$};
\node (C') at (2.5,-1) {$B'$};
\node (D') at (4,-1) {$d' \in F(M').$};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above]{$i$} (B)
(C) edge node[above]{$o$} (B)
(A') edge node[below]{$i'$} (B')
(C') edge node[below]{$o'$} (B')
(A) edge node [left]{$f$} (A')
(B) edge node [left]{$\alpha$} (B')
(C) edge node [right]{$g$} (C');
\end{tikzpicture}
\end{displaymath}
\end{itemize}
Vertical composition is done using composition in $\Fin\Set$, while horizontal composition
is done using composition of $F$-decorated cospans. 
\end{thm}

\begin{proof}
The double category structure follows from \cite[Thm. 2.1]{BaezCourserVasilakopoulou2022}.   
The symmetric monoidal structure, which we have not described here, follows from  \cite[Thm. 2.2]{BaezCourserVasilakopoulou2022}, and is detailed there.
\end{proof}

\section{Feedback loops and homology}
\label{Sec:Feedback_loops}

In system dynamics, graphs labeled by signs are often used to study feedback loops.  We can approach this systematically for graphs labeled by elements of a commutative monoid using homology theory.  Homology lets us detect cycles in a graph.  The homology of a graph with coefficients in an abelian group is well understood, and independent of the direction of the graph's edges, but in fact we can define the homology of a graph with coefficients in a commutative monoid, in a way that depends on the edge directions.  We are most interested in taking coefficients in $\N$, because this gives a way to study feedback loops.

Let $C$ be a commutative monoid.  In what follows we use $C[X]$ to stand for the set of formal finite linear combinations of elements of $X$, with coefficients in $C$.  Thus, 
\[   C[X] = \left\{ \sum_{x \in X} a_x x \; \Big{\vert} \; a_x \in C, \text{ all but finitely many } a_x \text{ are zero} \right\}.\]
This is a commutative monoid under addition.  In particular, if we make $\N$ into a commutative monoid with addition as the monoid operation, $\N[X]$ is the free commutative monoid on $X$.  

\begin{defn} 
Given a graph $G = (E,V,s,t)$ and a commutative monoid $C$, define
\[    C_0(G,C) = C[V] , \qquad     C_1(G,C) = C[E]  .\]
We call $C_0(G,C)$ (resp.\ $C_1(G,C)$) the commutative monoid of \define{$0$-chains} (resp.\ \define{$1$-chains}) on $G$ with coefficients in $C$.
\end{defn}

The source and target maps of the graph give two maps sending $1$-chains to $0$-chains.   Namely, 
starting from the maps $s,t \maps E \to V$ we can extend them by linearity to monoid homomorphisms 
\[    C[s], C[t] \maps C_1(G,C) \to C_0(G,C). \]
Indeed, there is a functor $C[-] \maps \Set \to \Comm\Mon$.  We have already defined this on objects, and given a map of sets $f \maps X \to Y$ we define $C[f] \maps C[X] \to C[Y]$ by
\[    C[f] \left( \sum_{x \in X} a_x x \right) = \sum_{x \in X} a_x f(x) .\]

When $C$ is an abelian group we can define a group homomorphism $d \maps C_1(G,C) \to C_0(G,C)$ by
\[   d = C[s] - C[t]. \]
In this context the usual expressions for homology groups as quotient groups simplify, and we can define
\[   H_1(G,C) = \ker d , \qquad H_0(G,C) = \coker \, d  .\]
But when working with commutative monoids that are not abelian groups, we cannot form the difference $C[s] - C[t]$, so we use the equalizer and coequalizer of $C[s]$ and $C[t]$ rather than the kernel and cokernel of their difference, defining
\[    H_1(G,C) = \Eq(C[s], C[t]), \qquad
      H_0(G,C) = \coeq(C[s], C[t]) .\]
More formally:

\begin{defn}
Given a graph $G$ and a commutative monoid $C$, we define $H_1(G,C)$, the \define{first homology} of $G$ with coefficients in $C$, to be the equalizer of the morphisms
\[  \begin{tikzcd}
C_1(G,C) \arrow[r, "C\lbrack s\rbrack", shift left = 1.5] \arrow[r, "C\lbrack t\rbrack", swap, shift right = 1.5]  &
C_0(G,C).
\end{tikzcd} 
\]
We call an element of $H_1(G,C)$ a \define{1-cycle} or simply a \define{cycle} with coefficients in $C$. 
We define $H_0(G,C)$, the \define{zeroth homology} of $G$ with coefficients in $C$, to be the coequalizer of $s$ and $t$. 
\end{defn}

We can fit everything into one diagram as follows:      
\[  \begin{tikzcd}
H_1(G,C) \arrow[r, "i"] & C_1(G,C) \arrow[r, "C\lbrack s \rbrack", shift left = 1.5] \arrow[r, "C \lbrack t \rbrack", swap, shift right = 1.5]  &
C_0(G,C)  \arrow[r,"p"]  & H_0(G,C).
\end{tikzcd} 
\]
where $i$ is the inclusion of the equalizer of $C[s]$ and $C[t]$ and $p$ is the projection onto their coequalizer.  When $C$ is an abelian group, we can rewrite this as an exact sequence
\[  0 \to H_1(G,C) \xrightarrow{i} C_1(G,C) \xrightarrow{d} C_0(G,C) \xrightarrow{p} H_0(G,C) \to 0. \]

\begin{eg}
\label{Eg:Homology_of_graphs}
This graph:
\[
G = \begin{tikzcd}
u  \arrow[r, bend left] & v \arrow[l, bend left]
\end{tikzcd}
\]
has $H_1(G,\N) \cong \N$, while this graph:
\[
G' = \begin{tikzcd}
u \arrow[r, bend left] \arrow[r, bend right] & v
\end{tikzcd}
\]
has $H_1(G',\N) \cong \{0\}$.  In simple terms, this says that the first graph offers the opportunity for a feedback loop, while the second does not.  On the other hand, we have $H_1(G,\Z) \cong H_1(G',\Z) \cong \Z$.   We have $H_0(G,\N) \cong H_0(G,\N') \cong \{0\}$ and similarly with $\Z$ coefficients, since both graphs are connected.
\end{eg}

The zeroth homology of a graph with coefficients in a commutative monoid is easily understood.  
There are various concepts of `connected component' for a graph, but define the set of \define{undirected components} of a graph $G$, $\pi_0(G)$, to be the coequalizer
\begin{equation}
\label{Eq:Pi_0_as_coequalizer}
 \begin{tikzcd}
 E \arrow[r, "s", shift left = 1.5] \arrow[r, "t", swap, shift right = 1.5]  & V \arrow[r, "p"] & \pi_0(G) .
\end{tikzcd} 
\end{equation}
Thus, two vertices $v, v'$ lie in the same undirected component iff there is an \define{undirected path} from $v$ to $v'$: a sequence of vertices $v = v_0, \dots, v_n = v'$ such that for each $i =1, \dots ,n$ there is either an edge $e \maps v_{i-1} \to v_i$ or an edge $e \maps v_i \to v_{i-1}$.

\begin{thm}
\label{Prop:Zeroth_homology}
Let $G$ be a graph and $C$ a commutative monoid.  Then $H_0(G,C) \cong C[\pi_0(G)]$.
\end{thm}

\begin{proof}
This can be shown directly, but we sketch a proof using some facts, well known for abelian groups, which have easy analogues for commutative monoids \cite{MeseguerMontanari1990} and even more general algebraic structures \cite{Kock1971}.  First, given $A, B \in \Comm\Mon$, the set of homomorphisms $A \to B$ can be made into a commutative monoid $[A,B]$ using pointwise operations:
\[    (f + g)(a) = f(a) + g(a)  ,  \qquad  \forall f,g \in [A,B], \; a \in A .\]
Second, we can define a tensor product $A \otimes B$ of commutative monoids such that homomorphisms $A \otimes B \to C$ correspond naturally to maps $A \times B \to C$ that are homomorphisms in each argument.    This tensor product obeys hom-tensor adjointness: that is, there is 
a natural isomorphism
\[    \Comm\Mon(A \otimes B, C) \cong \Comm\Mon(B, [A,C]) .\]

For any commutative monoid $C$ there is a natural isomorphism 
\[         C[-] \cong C \otimes \N[-]  \]
of functors from $\Comm\Mon$ to $\Set$.  The functor $\N[-]$ is a left adjoint to the forgetful functor from $\Comm\Mon$ to $\Set$, and the functor $C \otimes -$ is left adjoint to the functor $[C, -] $.  It follows that $C[-] \cong C \otimes \N[-] \maps \Set \to \Comm\Mon$ is a left adjoint, so it preserves colimits.  Applying this functor to the coequalizer diagram \eqref{Eq:Pi_0_as_coequalizer}, we get a coequalizer diagram
\[  \begin{tikzcd}
 C[E] \arrow[r, "C\lbrack s \rbrack", shift left = 1.5] \arrow[r, "C \lbrack t \rbrack", swap, shift right = 1.5]  & C[V] \arrow[r, "C \lbrack t \rbrack"] & C[\pi_0(G)].
\end{tikzcd} 
\]
On the other hand, we have defined $H_0(G,C)$ as the coequalizer
\[  \begin{tikzcd}
 C[E] \arrow[r, "C\lbrack s \rbrack", shift left = 1.5] \arrow[r, "C \lbrack t \rbrack", swap, shift right = 1.5]  & C[V] \arrow[r, "C \lbrack t \rbrack"] & H_0(G,C)
\end{tikzcd} 
\]
though we  have denoted $C[E]$ as $C_1(G,C)$ and $C[V]$ as $C_0(G,C)$.    It follows that $H_0(G) \cong C[\pi_0(G)]$.
\end{proof}

Now let us turn to the first homology of a graph $G$ with coefficients in a commutative monoid.  When $C$ is an abelian group, $H_1(G,C)$ is isomorphic to the homology of the graph $G$ viewed as a topological space, which is well  understood \cite[Sec.\ III.3]{Massey}.    For example,  $H_1(G,\Z)$ is a free abelian group whose rank is the genus of the graph.   More generally, whenever $C$ is an abelian group, the universal coefficient theorem implies
\[              H_1(G,C) \cong C \otimes_{\Z} H_1(G,\Z). \]
The novelty lies in the case when $C$ is \emph{not} a group, since then the directions of the edges matter, as in \cref{Eg:Homology_of_graphs}.   We are then doing a simple sort of `directed algebraic topology'.  We are mainly interested in the case $C = \N$, since this captures the structure of possible feedback loops in the graph.  We now turn toward analyzing the structure of $H_1(G,\N)$.  As we shall seein \cref{Eg:Nonfreely_generated_homology}, it is not always a free commutative monoid.

To begin, note that there is a canonical preorder on any commutative monoid $C$, given by
\[   x \le y \iff   x + a = y \text{ for some } a \in C.\]
If $C$ is an abelian group then $x \le y$ for all $x, y \in C$.  But for $C = \N$, the canonical preorder is the usual linear ordering on natural numbers.  More generally, in the free commutative monoid $\N[X]$ on any set $X$ the canonical preorder is given by
\[   \sum_{x \in X} a_x x \le \sum_{x \in X} B_x x  \iff a_x \le B_x \text{ for all } x \in X .\]

\begin{defn} Given a commutative monoid $C$, an element $x \in C$ is \define{minimal} if it is nonzero and $y \le x$ implies that $y = x$ or $y = 0$.
\end{defn}

Any free commutative monoid $\N[X]$ is freely generated by its minimal elements, which correspond to the elements of $X$.  A weaker statement holds for the first homology of a graph with coefficients in $\N$.

\begin{thm}
\label{Thm:generated_by_minimal_elements}
For any graph $G$, $H_1(G,\N)$ is generated by its minimal elements.
\end{thm}

\begin{proof}
First recall that $H_1(G,\N)$ is a submonoid of $C_1(G,\N) \cong \N[E]$ where $E$ is the set of edges of $G$.  The canonical preorder on $H_1(G,\N)$ is a restriction of that in $C_1(G,\N)$, since given $x,y \in H_1(G,\N)$ there exists $z \in C_1(G,\N)$ with $x + z = y$ if and only if
there exists $z \in H_1(G,\N)$ obeying this equation.  As a result, since there are no infinite descending chains of elements $c_1 > c_2 > c_3 > \cdots $ in $C_1(G,\N) \cong \N[E]$, there are no infinite descending chains in $H_1(G,\N)$.

Next we use this to show that any $c \in H_1(G,\N)$ is a sum of minimal elements.  If $c$ is minimal, we are done.  Otherwise we can write $c$ as a sum of two smaller but nonzero elements.  If these are both minimal then we are done; if not, we can express either one that is not minimal as a sum of two smaller nonzero elements.  If we could keep repeating the process of breaking each non-minimal element into a sum of two smaller nonzero elements forever, then $H_1(G,\N)$ would have an infinite descending chain.  But since this is impossible, the process must terminate, expressing $c$ as a finite sum of minimal elements.
\end{proof}

\begin{eg}
\label{Eg:Nonfreely_generated_homology}
Consider the graph
\[
Q = 
\begin{tikzcd}
u  \arrow[r, bend left = 80, "e_1"] 
\arrow[r, bend left = 20, "e_2"]  & 
v \arrow[l, bend left = 20, "e_3"] 
\arrow[l, bend left = 80, "e_4"]
\end{tikzcd}
\]
One can see that the minimal elements of $H_1(Q,\N)$ are the cycles 
\[   a = e_1 + e_3, \;\; 
     b = e_1 + e_4, \;\;
     c = e_2 + e_3, \;\;
     d = e_2 + e_4 . \]
Thus these generate $H_1(Q,\N)$, but not freely, since $a + c = b + d$.   Moreover, note that a free commutative monoid is always freely generated by its minimal elements, since for any set $S$, the minimal elements of the free commutative monoid $\N[S]$ are precisely the linear combinations of elements of $S$ where one coefficient equals $1$ and all the rest are zero.   Thus, $H_1(Q, \N)$ is not a free commutative monoid.
\end{eg}

We call the minimal elements of $H_1(G,\N)$ \define{minimal cycles}.  We are interested in them because they determine the feedback around all cycles in $G$.   Let us make this precise.  For any commutative monoid $C$ and any $C$-labeled graph $(G,\ell)$, there is a map
\[        C_1(G,\N) \to C \]
defined by
\[    \sum_{e \in E} n_e e  \mapsto \sum_{e \in E} n_e \ell(e) .\]
Indeed this is the unique homomorphism of commutative monoids extending $\ell$ from $E$ to the free commutative monoid on $E$, namely $C_1(G,\N)$.   If we restrict this map to cycles we get a homomorphism that we call 
\[   \tilde{\ell} \maps H_1(G,\N) \to C.\]
Given a cycle $c \in H_1(G,\N)$, we call $\tilde{\ell}(c)$ the \define{feedback} of $(G,\ell)$ around $c$.

\begin{cor}
\label{Cor:Feedback_around_minimal_cycles}
For any commutative monoid $C$ and any $C$-labeled graph $(G,\ell)$, the homomorphism $\tilde{\ell} \maps H_1(G,\N) \to C$ is determined by its values on minimal cycles.
\end{cor}

\begin{proof}
This follows from \cref{Thm:generated_by_minimal_elements}: minimal cycles generate $H_1(G,\N)$.  
\end{proof}

While they are defined in an order-theoretic way, minimal cycles have an appealing `geometrical' characterization as homology classes of certain `simple'  loops in $G$.

\begin{defn}
Let $G$ be a graph.  A \define{path} in $G$ is a finite sequence of edges $e_1, \dots e_n$ such that $t(e_i) = s(e_{i+1})$ for $i = 1, \dots, n-1$.   An \define{loop} is an path that ends where it starts, meaning $s(e_1) = t(e_n)$.
\end{defn}

We can denote any path in $G$ as follows:
\[  v_0 \xrightarrow{e_1} v_1 \xrightarrow{e_2} \cdots \xrightarrow{e_{n-1}} v_{n-1} \xrightarrow{e_n} v_n \]
and a loop as follows:
\[  v_0 \xrightarrow{e_1} v_1 \xrightarrow{e_2} \cdots \xrightarrow{e_{n-1}} v_{n-1} \xrightarrow{e_n} v_0 \]
Note from \cref{Sec:Motifs} that the paths in a graph $G$ are precisely the morphisms in the free category on $G$.

Any path $\gamma$ in $G$ gives an element of $[\gamma] \in C_1(G,\N)$, defined to be the sum of that path's edges.  That is, if
\[   \gamma = \left( v_0 \xrightarrow{e_1} v_1 \xrightarrow{e_2} \cdots \xrightarrow{e_{n-1}} v_{n-1} \xrightarrow{e_n} v_n \right)
\]
then we define
\[   [\gamma] = e_1 + \cdots + e_n .\]
If $\gamma$ is a loop then $[\gamma]$ is a cycle since then
\[  s(e_1) + \cdots + s(e_n) = t(e_1) + \cdots + t(e_n) .\]

\begin{defn}
Two loops $\gamma, \delta$ in a graph $G$ are \define{homologous} if $[\gamma] = [\delta]$.
\end{defn}

\begin{defn}
A loop 
\[  v_0 \xrightarrow{e_1} v_1 \xrightarrow{e_2} \cdots \xrightarrow{e_{n-1}} v_{n-1} \xrightarrow{e_n} v_0 \]
is \define{simple} if all the vertices $v_0, \dots, v_{n-1}$ are distinct.
\end{defn}

It is easy to see that if a loop $\gamma$ is not simple, we can chop it where it crosses itself, obtaining two loops $\delta$ and $\eta$ such that 
\[      [\gamma] = [\delta] + [\eta] \]
and $[\delta], [\eta] \ne 0$.  Thus, $[\gamma]$ cannot be minimal if $\gamma$ is not simple.  In fact a much stronger result holds:

\begin{thm}
\label{Thm:simple_loops_and_minimal_cycles}
For any graph $G$, there is a bijection between homology classes of simple loops in $G$ and minimal cycles in $G$, which sends all loops equivalent to the simple loop $\gamma$ to the cycle $[\gamma]$.
\end{thm}

\begin{proof}
This follows from Lemmas \ref{Lem:simple_loops_and_minimal_cycles_1} and \ref{Lem:simple_loops_and_minimal_cycles_2} below.
\end{proof}

\begin{lem}
\label{Lem:simple_loops_and_minimal_cycles_1}
If $\gamma$ is a simple loop in a graph $G$ then $[\gamma]$ is a minimal cycle.
\end{lem}

\begin{proof}
Consider a simple loop
\[  \gamma = \Big( v_0 \xrightarrow{e_1} v_1 \xrightarrow{e_2} \cdots \xrightarrow{e_n} v_0 \Big). \]
Then
\[  [\gamma] = \sum_{i=1}^n e_i .\]
Any cycle $c \le [\gamma] $ must be a chain less than or equal to $c$ in $C_1(G,\N)$, and since $C_1(G,\N)$ is the free commutative monoid on the set of edges of $G$, any chain $c \le [\gamma]$ must be of the form 
\[ c = \sum_{i \in S} e_i  .\]
where $S \subseteq \{1, \dots, n\} $.  We have 
\[ \N[s](c) = \sum_{i \in S} v_{i-1} , \quad \N[t](c) = \sum_{i \in S} v_i .\]
For $c$ to be a cycle we must have $\N[s](c) = \N[t](c)$.  But since all the vertices $v_1, \dots, v_n$ are distinct (while $v_0 = v_n$), the two sums above can only be equal if $S$ is all of $\{1, \dots, n\}$, in which case $c = [\gamma]$, or $S$ is empty, in which case $c = 0$.   (Note that since $C_0(G,\N)$ is free on the set of vertices of $G$, the two sums can only be equal if they are `visibly' equal: there are no extra relations.)  Thus $[\gamma]$ is minimal.  
\end{proof}

\begin{lem}
\label{Lem:simple_loops_and_minimal_cycles_2}
For each minimal cycle $c$ in a graph $G$ there exists a simple loop $\gamma$ in $G$ such that $[\gamma] = c$.
\end{lem}

\begin{proof}
Let $c$ be a minimal cycle.  It is nonzero, so choose an edge with $e_1 \le c$ in $C_1(G,\N)$.  Denote this edge as $v_0 \xrightarrow{e_1} v_1$.  If $v_1 = v_0$ the path $v_0 \xrightarrow{e_1} v_1$ is a loop, say $\gamma$, so $[\gamma] = e_1$ is a nonzero cycle, so by the minimality of $c$ we must have $c = [\gamma]$ and we are done. If on the other hand $v_1 \ne v_0$ then $e_1$ is not a cycle, so $c$ must be the sum of $e_1$ and one or more edges, and at least one of these edges must have source $v_1$, since otherwise it would be impossible to have $s(c) = t(c)$.    Choose one such edge and call it $v_1 \xrightarrow{e_2} v_2$.  We now have a path 
\[   \delta = \Big( v_0 \xrightarrow{e_1} v_1 \xrightarrow{e_2} v_2 \Big) \] 
with $\delta \le c$ and with $v_0, v_1$ distinct.

We continue along these lines by carrying out an inductive procedure.  Assume we have a path 
\[  \delta = \Big( v_0 \xrightarrow{e_1} \cdots \xrightarrow{e_n} v_n \Big) \]
with $[\delta] \le c$ and $v_0, \dots, v_{n-1}$ distinct.  If $v_n$ equals any of the previous vertices, say $v_n = v_i$ with $0 \le i < n$, then we obtain a simple loop 
\[  \gamma = \Big( v_i \xrightarrow{e_{i+1}} \cdots \xrightarrow{e_n} v_n \Big). \] 
Since $[\gamma]$ is a nonzero cycle less than or equal to $[\delta]$ and thus $c$, by the minimality of $c$ we must have $c = [\gamma]$ and we are done.   Otherwise all the vertices $v_0, \dots, v_n$ are distinct, so $[\delta]$ is not a cycle, so $c$ must be a sum of $[\delta]$ and one or more edges, and at least one of these edges must have source $v_n$, since otherwise it would be impossible to have $s(c) = t(c)$.   Choose one such edge and denote it by $v_n \xrightarrow{e_{n+1}} v_{n+1}$.  We now have a path
\[  \delta' = \Big( v_0 \xrightarrow{e_1} v_1 \xrightarrow{e_2} \cdots \xrightarrow{e_n} v_n \xrightarrow{e_{n+1}} v_{n+1} \Big) \]
with $[\delta'] \le c$ and $v_0, \dots , v_n$ distinct.

Since $c$ is a finite sum of edges this procedure must eventually terminate: i.e., eventually $v_k$ must equal one of the previous vertices $v_0, \dots, v_{k-1}$, which are themselves all distinct.  We thus obtain a simple loop $\gamma$ giving a nonzero cycle $[\gamma] \le c$, and by the minimality of $c$ we must have $[\gamma] = c$. 
\end{proof}

Having established a bijection between minimal cycles and homology classes of simple loops, we naturally want to know when two simple loops are homologous.  It turns out that the only way to obtain a loop homologous to a simple loop is to change where the loop starts.  More precisely:

\begin{prop}
\label{Lem:simple_loop_equivalence}
Every loop homologous to a simple loop
\[  v_0 \xrightarrow{e_1} v_1 \xrightarrow{e_2} \cdots \xrightarrow{e_{n-1}} v_{n-1} \xrightarrow{e_n} v_0 \]
is of the form
\[  v_k \xrightarrow{e_{k+1}} v_{k+1} \xrightarrow{e_{k+2}} \cdots \xrightarrow{e_{n+k-1}} v_{n+k-1} \xrightarrow{e_{n+k}} v_k  \]
where we treat the subscripts as elements of $\Z/n$ and do addition mod $n$.
\end{prop}

\begin{proof}
Suppose 
\[ \gamma = \Big( v_0 \xrightarrow{e_1} v_1 \xrightarrow{e_2} \cdots \xrightarrow{e_{n-1}} v_{n-1} \xrightarrow{e_n} v_0 \Big) \]
is a simple loop and 
\[ \delta = \Big( w_0 \xrightarrow{f_1} w_1 \xrightarrow{f_2} \cdots \xrightarrow{f_{m-1}} w_{m-1} \xrightarrow{f_m} w_0 \Big) \]
is a loop homologous to $\gamma$, so 
\[   e_1 + \cdots + e_n 
= f_1 + \cdots + f_m . \]
Since $\gamma$ is simple, all the vertices $v_0, \dots, v_{n-1}$ are distinct, so the edges $e_1, \dots, e_n$ are distinct.  We must thus have $m = n$, with the list of edges $f_1, \dots, f_n$ being some permutation of the list of edges $e_1, \dots, e_n$.  Since all the vertices $v_0, \dots, v_{n-1}$ are distinct, the only permutations that make $\delta$ into a loop are cyclic permutations.
\end{proof}

\section{Emergent feedback loops}
\label{Sec:Emergent_feedback_loops}

When we glue together two graphs, the resulting graph can have loops that are not contained in either of the original graphs.   These are called `emergent loops'.   In applications, these represent new possible feedback loops that arise when we combine two systems.  Since feedback loops are fundamental in system dynamics, it is important to pay close attention to this phenomenon.

There are several ways to study emergent loops.  The first is to study emergent paths in graphs formed by composing open graphs.  We described a double category $\lOpen(\Gph/G_L)$ of open $L$-labeled graphs in \cref{Thm:Open_set-labeled_graphs}, and we can define the double category of \define{open graphs},  $\lOpen(\Gph)$, to be the special case where $L$ is the one-element set, so the labeling becomes trivial.  To compose two open graphs:
