\node (D) at (4,0) {$\disc(B)$};
\node (E) at (5,1) {$Y$};
\node (F) at (6,0) {$\disc(C)$};
\path[->,font=\scriptsize,>=angle 90]
(A) edge node[above, pos=0.3]{$$} (B)
(C) edge node[above, pos=0.3]{$$}(B)
(D) edge node[above, pos=0.3]{$$} (E)
(F) edge node[above, pos=0.3]{$$}(E);
