\section{Perturbation Formula and Lipschitz Estimations}\label{sec:Perturbation Formula and Lipschitz Estimation}

\subsection{Perturbation Formula and Nilpotent Part Difference Characterization}\label{sec: Perturbation Formula and Nilpotant Part Difference Characterization}

In this section, the perturbation formula of GMOI is derived.  We begin by defining several new notations for later perturbation formula simpler presentation. We have 

\begin{eqnarray}\label{eq1: pert nimpler notation}
\bm{S}_{k_c,i_c}&=&\begin{cases}
\bm{P}_{k_c,i_c}\\
\bm{N}_{k_c,i_c}^{q_c}
\end{cases};\nonumber \\
\bm{S}_{k_d,i_d}&=&\begin{cases}
\bm{P}_{k_d,i_d}\\
\bm{N}_{k_d,i_d}^{q_d}
\end{cases}.
\end{eqnarray}
%
where $c,d$ are indices for the matrices $\bm{C}$ and $\bm{D}$. Also, we set 
%
\begin{eqnarray}\label{eq2: pert nimpler notation}
\bm{S}_{k_p,i_p}&=&\begin{cases}
\bm{P}_{k_p,i_p}\\
\bm{N}_{k_p,i_p}^{q_p}
\end{cases};\nonumber \\
\bm{S}_{k_{p'},i_{p'}}&=&\begin{cases}
\bm{P}_{k_{p'},i_{p'}}\\
\bm{N}_{k_{p'},i_{p'}}^{q_{p'}}
\end{cases},
\end{eqnarray}
%
where $p,p' \in \mathbb{N}$ are indices for the matrices $\bm{X}_p$ and $\bm{X}_{p'}$. We use the following summation notation:
%
\begin{eqnarray}\label{eq3: pert nimpler notation}
\sum\limits_{\bm{S}_{k_p,i_p}} &=&
\begin{cases}
\sum\limits_{k_p=1}^{K_p}\sum\limits_{i_p=1}^{\alpha_{k_p}^{(\mathrm{G})}}\bm{P}_{k_p,i_p}, \mbox{~~if $\bm{S}_{k_p,i_p}=\bm{P}_{k_p,i_p}$}, \\
\sum\limits_{k_p=1}^{K_p}\sum\limits_{i_p=1}^{\alpha_{k_p}^{(\mathrm{G})}}\sum\limits_{q_p=1}^{m_{k_p,i_p}}\bm{N}_{k_p,i_p}^{q_p}, \mbox{~~if $\bm{S}_{k_p,i_p}=\bm{N}_{k_p,i_p}^{q_p}$}, 
\end{cases}
\end{eqnarray}
%
therefore, if we write $\sum\limits_{\bm{S}_{k_p,i_p}, p \in [p_1, p_2]}$, which can be expressed by
%
\begin{eqnarray}\label{eq4: pert nimpler notation}
\sum\limits_{\bm{S}_{k_p,i_p}, p \in [p_1, p_2]} &=&
\sum\limits_{\bm{S}_{k_{p_1},i_{p_1}}}\sum\limits_{\bm{S}_{k_{p_2},i_{p_2}}}\ldots\sum\limits_{\bm{S}_{k_{p_2},i_{p_2}}}
\end{eqnarray}
%
where $[p_1, p_2]$ are positive integers from $p_1, p_1 + 1, \ldots, p_2$. Note that the expression given by Eq.~\eqref{eq4: pert nimpler notation} will include all summation results for all binary combinations of $\bm{S}_{k_p,i_p}$. Hence, there are $2^{p_2 - p_1 +1}$ summation results given by Eq.~\eqref{eq4: pert nimpler notation}.

Given any differentiable function $f: \mathbb{C}^{\zeta} \rightarrow \mathbb{C}$, we use the following notation to represent partial derivatives with respect to different arguments of the function $f$ and its normalization with respect to differentiation orders:
%
\begin{eqnarray}\label{eq5: pert nimpler notation}
\frac{f^{(q_1,q_2,\ldots,q_\zeta)}(\lambda_1, \lambda_2, \ldots, \lambda_{\zeta})}{q_1 ! q_2 ! \ldots,q_\zeta! }&=& \frac{f^{([q]_1^{q_\zeta})}([\lambda]_1^{\zeta})}{([q!]_1^{q_\zeta})}
\end{eqnarray}



The Lemma~\ref{lma:first-order divided difference identity} will be provided to show that the $k$-order divided difference identity will be valid for the function and its partial derivatives.
%
\begin{lemma}\label{lma:first-order divided difference identity}
Let \( f : \mathbb{C}^n \to \mathbb{C} \) be a function of class \( C^{k+1+r} \). Let
\[
D^{(r)} f = \frac{\partial^r f}{\partial x_{i_1} \cdots \partial x_{i_r}}
\]
be an \( r \)-th order partial derivative of \( f \). Then the divided difference identity
\[
D^{(r)} f^{[k]}(\dots, \lambda_{\alpha_j}, \dots) - D^{(r)} f^{[k]}(\dots, \mu_{\alpha_j}, \dots) = (\lambda_{\alpha_j} - \mu_{\alpha_j}) D^{(r)} f^{[k+1]}(\dots, \lambda_{\alpha_j}, \mu_{\alpha_j}, \dots)
\]
holds provided that the divided difference is taken with respect to a variable independent of \( x_{i_1}, \dots, x_{i_r} \).
\end{lemma}
%
\textbf{Proof:}
%
Assume \( f \in C^{k+1+r}(\mathbb{C}^n) \), so that all relevant derivatives and divided differences are well-defined and smooth.

Let \( g = D^{(r)} f = \frac{\partial^r f}{\partial x_{i_1} \cdots \partial x_{i_r}} \). Because differentiation and divided difference operators commute when they act on independent variables, we have:
\[
D^{(r)} f^{[k]}(\lambda_1, \dots, \lambda_k) = \left( D^{(r)} f \right)^{[k]}(\lambda_1, \dots, \lambda_k)
\]
Now, apply the standard first-order divided difference identity to the function \( g \):
\[
g^{[k]}(\dots, \lambda_{\alpha_j}, \dots) - g^{[k]}(\dots, \mu_{\alpha_j}, \dots)
= (\lambda_{\alpha_j} - \mu_{\alpha_j}) g^{[k+1]}(\dots, \lambda_{\alpha_j}, \mu_{\alpha_j}, \dots)
\]
Substituting back \( g = D^{(r)} f \), we obtain:
\[
D^{(r)} f^{[k]}(\dots, \lambda_{\alpha_j}, \dots) - D^{(r)} f^{[k]}(\dots, \mu_{\alpha_j}, \dots)
= (\lambda_{\alpha_j} - \mu_{\alpha_j}) D^{(r)} f^{[k+1]}(\dots, \lambda_{\alpha_j}, \mu_{\alpha_j}, \dots)
\]
which completes the proof.
%
$\hfill\Box$

We are ready to present Theorem~\ref{thm:GMOI Perturbation Formula} about GMOI perturbation formula. 
%
\begin{theorem}\label{thm:GMOI Perturbation Formula}
%
Given matrices $\bm{X}_p$ decomposed as:
%
\begin{eqnarray}\label{eq1:thm:GMOI Perturbation Formula}
\bm{X}_p&=&\sum\limits_{k_p=1}^{K_p}\sum\limits_{i_p=1}^{\alpha_{k_p}^{\mathrm{G}}} \lambda_{k_p} \bm{P}_{k_p,i_p}+
\sum\limits_{k_p=1}^{K_p}\sum\limits_{i_p=1}^{\alpha_{k_p}^{\mathrm{G}}} \bm{N}_{k_p,i_p},
