%
where $p=1,2,\ldots,\zeta$, and matrices $\bm{C}, \bm{D}$ decomposed as:
%
\begin{eqnarray}\label{eq1:thm:GMOI Perturbation Formula}
\bm{C}&=&\sum\limits_{k_c=1}^{K_c}\sum\limits_{i_c=1}^{\alpha_{k_c}^{\mathrm{G}}} \lambda_{k_c} \bm{P}_{k_c,i_c}+
\sum\limits_{k_c=1}^{K_c}\sum\limits_{i_c=1}^{\alpha_{k_c}^{\mathrm{G}}} \bm{N}_{k_c,i_c}, \nonumber \\ 
\bm{D}&=&\sum\limits_{k_d=1}^{K_d}\sum\limits_{i_d=1}^{\alpha_{k_d}^{\mathrm{G}}} \lambda_{k_d} \bm{P}_{k_d,i_d}+
\sum\limits_{k_d=1}^{K_d}\sum\limits_{i_d=1}^{\alpha_{k_d}^{\mathrm{G}}} \bm{N}_{k_d,i_d}.
\end{eqnarray}


