&-& T_{\beta^{[\zeta]}}^{[\bm{X}]_1^{j-2},\bm{X}_{j-1,N},\bm{D}_P,\bm{X}_{j,N},[\bm{X}]_{j+1}^{\zeta}}([\bm{Y}]_1^{j-1},[\bm{Y}]_j^{\zeta})\Bigg)_{VII} + \mathfrak{X}^{\bm{X}_{j-1,N},\bm{C}_P,\bm{D}_P,\bm{X}_{j,N}} \nonumber \\
