S_{k_{p'},i_{p'}}, p' \in [j+1,\zeta]}}\sum\limits_{\substack{k_{j-1},i_{j-1},\\k_c,i_c, k_d,i_d,q_d\\ k_{j},i_{j}}} \frac{(\beta^{[\zeta]}([\lambda_k]_1^{j-2},\lambda_{k_{j-1}},\lambda_{k_d},\lambda_{k_j},[\lambda_k]_{j+1}^{\zeta}))^{([q]_1^{j-2}[0,q_d,0][q]_{j+1}^{\zeta})}}{ ([q!]_1^{j-2}[0!,q_d!,0!][q!]_{j+1}^{\zeta})  } \nonumber \\
