\subsection{GMOI Lipschitz Estimations}\label{sec: GMOI Lipschitz Estimations}

In this section, we will apply Theorem~\ref{thm: GMOI norm Est} to determine GMOI Lipschitz estimations. The Lipschitz estimation for GMOI is to determine the norm for the difference between GMOI $T_{\beta}^{\bm{X}_1,\ldots,\bm{X}_{\zeta+1}}(\bm{Y}_1,\ldots,\bm{Y}_{\zeta})$ and  GMOI $T_{\beta}^{\bm{X}_1,\ldots,\bm{X}_{\zeta+1}}(\bm{Y}'_1,\ldots,\bm{Y}'_{\zeta})$ is terms of norms for the difference $\bm{Y}_i$ and $\bm{Y}'_i$.  Theorem~\ref{thm: GMOI Lip Est} below is provided to characterize GMOI Lipschitz estimations.


\begin{theorem}\label{thm: GMOI Lip Est}
%
We have Lipschitz estimation for the difference between  GMOI $T_{\beta}^{\bm{X}_1,\ldots,\bm{X}_{\zeta+1}}(\bm{Y}_1,\ldots,\bm{Y}_{\zeta})$ and GMOI $T_{\beta}^{\bm{X}_1,\ldots,\bm{X}_{\zeta+1}}(\bm{Y}'_1,\ldots,\bm{Y}'_{\zeta})$:
%
\begin{eqnarray}\label{eq0:  thm: GMOI Lip Est}
\lefteqn{\left\Vert T_{\beta}^{\bm{X}_1,\ldots,\bm{X}_{\zeta+1}}(\bm{Y}_1,\ldots,\bm{Y}_{\zeta}) - T_{\beta}^{\bm{X}_1,\ldots,\bm{X}_{\zeta+1}}(\bm{Y}'_1,\ldots,\bm{Y}'_{\zeta}) \right\Vert}\nonumber \\
&\leq& 
\sum\limits_{i=1}^{\zeta}\Upsilon_i (\bm{X}_1,\ldots,\bm{X}_{\zeta+1},\beta) \left(\prod\limits_{j=1}^{i-1}\left\Vert\bm{Y}'_{j}\right\Vert\right)\left\Vert \bm{Y}_i - \bm{Y}'_i \right\Vert \left(\prod\limits_{j=i+1}^{\zeta}\left\Vert\bm{Y}_{j}\right\Vert\right),
\end{eqnarray}
%
where $\Upsilon_i (\bm{X}_1,\ldots,\bm{X}_{\zeta+1},\beta)$ is the scalar component of the upper bound for the following GMOI expressed by 
%
\begin{eqnarray}\label{eq0-1:  thm: GMOI Lip Est}
\lefteqn{\left\Vert T_{\beta}^{\bm{X}_1,\ldots,\bm{X}_{\zeta+1}}([\bm{Y}']_1^{i-1},\bm{Y}_i - \bm{Y}'_i,[\bm{Y}]_{i+1}^\zeta)  \right\Vert}\nonumber \\
&\leq_1&\sum\limits_{i'=0}^{2^{\zeta+1}-1} \left\Vert \bm{A}_{i'} \right\Vert_{up} \nonumber \\
&=& 
\Upsilon_i (\bm{X}_1,\ldots,\bm{X}_{\zeta+1},\beta)\left(\prod\limits_{j=1}^{i-1}\left\Vert\bm{Y}'_{j}\right\Vert\right)\left\Vert \bm{Y}_i - \bm{Y}'_i \right\Vert \left(\prod\limits_{j=i+1}^{\zeta}\left\Vert\bm{Y}_{j}\right\Vert\right).
\end{eqnarray}
%
The inequality $\leq_1$ comes from Theorem~\ref{thm: GMOI norm Est}. 
%
\end{theorem}
%
\textbf{Proof:}
%
We can perform a telescoping decomposition for the L.H.S. of Eq.~\eqref{eq0:  thm: GMOI Lip Est} as
%
\begin{eqnarray}\label{eq2:  thm: GMOI Lip Est}
\lefteqn{\left\Vert T_{\beta}^{\bm{X}_1,\ldots,\bm{X}_{\zeta+1}}(\bm{Y}_1,\ldots,\bm{Y}_{\zeta}) - T_{\beta}^{\bm{X}_1,\ldots,\bm{X}_{\zeta+1}}(\bm{Y}'_1,\ldots,\bm{Y}'_{\zeta}) \right\Vert}\nonumber \\
&=& \left\Vert \sum\limits_{i=1}^{\zeta}\left(T_{\beta}^{\bm{X}_1,\ldots,\bm{X}_{\zeta+1}}([\bm{Y}']_1^{i-1},[\bm{Y}]_i^\zeta) - T_{\beta}^{\bm{X}_1,\ldots,\bm{X}_{\zeta+1}}([\bm{Y}']_1^{i},[\bm{Y}]_{i+1}^\zeta)\right)\right\Vert
\nonumber \\
&=& \left\Vert \sum\limits_{i=1}^{\zeta}T_{\beta}^{\bm{X}_1,\ldots,\bm{X}_{\zeta+1}}([\bm{Y}']_1^{i-1},\bm{Y}_i - \bm{Y}'_i,[\bm{Y}]_{i+1}^\zeta)\right\Vert.
\end{eqnarray}
%
Then, this theorem is proved by applying Theorem~\ref{thm: GMOI norm Est} to obtain $\Upsilon_i (\bm{X}_1,\ldots,\bm{X}_{\zeta+1},\beta)$ given by Eq.~\eqref{eq0-1:  thm: GMOI Lip Est}.
%
$\hfill\Box$

\section{GMOI Continuity}\label{sec: GMOI Continuity}

The purpose of this section is to establish the continuity property of GMOI, i.e., we will have
%
\begin{eqnarray}\label{eq1:sec: GMOI Continuity}
 T_{\beta}^{\bm{X}_{1, \ell_1},\ldots,\bm{X}_{\zeta+1,\ell_{\zeta+1}}}(\bm{Y}_1,\ldots,\bm{Y}_{\zeta})\rightarrow T_{\beta}^{\bm{X}_1,\ldots,\bm{X}_{\zeta+1}}(\bm{Y}_1,\ldots,\bm{Y}_{\zeta}),
\end{eqnarray}
%
given that 
%
\begin{eqnarray}\label{eq2:sec: GMOI Continuity}
\bm{X}_{i, \ell_i} \rightarrow \bm{X}_{i}.
\end{eqnarray}
%
Note that $\rightarrow$ is in the sense of Frobenius norm. 

The following Lemma~\ref{lma: bar mathfrak X zero} has to be built before GMOI continuity property establishment. 
%
\begin{lemma}\label{lma: bar mathfrak X zero}
%
Given $\bm{C} \rightarrow \bm{D}$, we have
%
\begin{eqnarray}
\bar{\mathfrak{X}}([\bm{X}]_1^{j-1},\bm{C}, \bm{D}, [\bm{X}]_j^{\zeta})&\rightarrow& \bm{O}, 
\end{eqnarray}
%
where $\bm{O}$ is a matrix with all entries as zeros. 
%
\end{lemma} 
%
\textbf{Proof:}
%
From Eq.~\eqref{eq2:thm:GMOI Perturbation Formula}, we have
%
\begin{eqnarray}
\bar{\mathfrak{X}}([\bm{X}]_1^{j-1},\bm{C},\bm{D},[\bm{X}]_j^{\zeta})&=& \mathfrak{X}^{\bm{X}_{j-1,P},\bm{C}_P,\bm{D}_P,\bm{X}_{j,P}} + \mathfrak{X}^{\bm{X}_{j-1,P},\bm{C}_N,\bm{D}_N,\bm{X}_{j,P}} \nonumber \\
&+& \mathfrak{X}^{\bm{X}_{j-1,P},\bm{C}_P,\bm{D}_P,\bm{X}_{j,N}} + \mathfrak{X}^{\bm{X}_{j-1,P},\bm{C}_N,\bm{D}_N,\bm{X}_{j,N}} \nonumber \\
&+&  \mathfrak{X}^{\bm{X}_{j-1,N},\bm{C}_P,\bm{D}_P,\bm{X}_{j,P}} + \mathfrak{X}^{\bm{X}_{j-1,N},\bm{C}_N,\bm{D}_N,\bm{X}_{j,P}} \nonumber \\
&+& \mathfrak{X}^{\bm{X}_{j-1,N},\bm{C}_P,\bm{D}_P,\bm{X}_{j,N}} + \mathfrak{X}^{\bm{X}_{j-1,N},\bm{C}_N,\bm{D}_N,\bm{X}_{j,N}}. 
\end{eqnarray}
%


\textbf{Claim 1: $\mathfrak{X}^{\bm{X}_{j-1,P},\bm{C}_P,\bm{D}_P,\bm{X}_{j,P}}  \rightarrow \bm{O}$}


Let $\bm{C} = \bm{D} + t\bm{V}$, where $t \in \mathbb{R}$ and $\bm{V}$ is a fixed perturbation matrix. Then under smooth variation of the Jordan decomposition (i.e., assuming stable geometric multiplicities), we have:
\[
\mathfrak{X}^{\bm{X}_{j-1,P},\bm{C}_P,\bm{D}_P,\bm{X}_{j,P}} = O(t)
\quad \text{as} \quad t \to 0.
\]

We recall the expression:
%
{\small
\begin{align}
\lefteqn{\mathfrak{X}^{\bm{X}_{j-1,P},\bm{C}_P,\bm{D}_P,\bm{X}_{j,P}}=}\nonumber \\
&& 
\sum_{\substack{S_{k_p,i_p}, p \in [1,j-2], \\
S_{k_{p'},i_{p'}}, p' \in [j+1,\zeta]}} \sum_{\substack{k_{j-1},i_{j-1},\\k_c, i_c,q_c,k_d,i_d,q_d\\ k_{j},i_{j}}}
\frac{
\left( \beta^{[\zeta+1]}([\lambda_k]_1^{j-2},\lambda_{k_{j-1}},\lambda_{k_c},\lambda_{k_d},\lambda_{k_j},[\lambda_k]_{j+1}^{\zeta}) \right)^{([q]_1^{j-2}[0,0,0,0][q]_{j+1}^{\zeta})}
}{
([q!]_1^{j-2}[0!,0!,0!,0!][q!]_{j+1}^{\zeta})
} \nonumber \\
&& \times \left( \prod_{p=1}^{j-2} S_{k_p,i_p} \bm{Y}_p \right)
\bm{P}_{k_{j-1},i_{j-1}} \bm{Y}_{j-1}
\bm{P}_{k_c,i_c}(\bm{N}_{k_c,i_c}^{q_c} - \bm{N}_{k_d,i_d}^{q_d}) \bm{P}_{k_d,i_d} \bm{Y}_j \bm{P}_{k_j,i_j}
\left( \prod_{p'=j+1}^{\zeta} \bm{Y}_{p'} S_{k_{p'},i_{p'}} \right). 
\end{align}
}

We now study the behavior of the central difference:
\[
\bm{N}_{k_c,i_c}^{q_c}(\bm{C}) - \bm{N}_{k_d,i_d}^{q_d}(\bm{D}),
\]
where $\bm{N}_{k_c,i_c}^{q_c}(\bm{C})$ denotes the nilpotent part of the matrix $\bm{C}$ corresponding to the $k_c$-th eigenvalue and the $i_c$-th geometric component, with exponent $q_c$. Similarly, $\bm{N}_{k_d,i_d}^{q_d}(\bm{D})$ denotes the nilpotent part of the matrix $\bm{D}$ corresponding to the $k_d$-th eigenvalue and the $i_d$-th geometric component, with exponent $q_d$.


Let $\bm{C} = \bm{D} + t \bm{V}$ and suppose the eigenvalues of $\bm{C}$ and $\bm{D}$ satisfy
\[
\lambda_{k_c} = \lambda_{k_d} + t\mu + o(t),
\]
with corresponding Jordan subspaces continuously varying. Then by perturbation theory for Jordan blocks:
\[
\bm{N}_{k_c,i_c}^{q_c}(\bm{C}) = \bm{N}_{k_d,i_d}^{q_d}(\bm{D}) + t \cdot \dot{\bm{N}}_{k_d,i_d}^{q_c} + o(t),
\]
and
\[
\bm{P}_{k_c,i_c}(\bm{C}) = \bm{P}_{k_d,i_d}(\bm{D}) + t \cdot \dot{\bm{P}}_{k_d,i_d} + o(t),
\]
where $\dot{\bm{N}}_{k_d,i_d}$ and $\dot{\bm{P}}_{k_d,i_d}$ are Fréchet derivatives with respect to $t$.

Thus, the difference term becomes:
\[
\bm{P}_{k_c,i_c}(\bm{N}_{k_c,i_c}^{q_c} - \bm{N}_{k_d,i_d}^{q_d})\bm{P}_{k_d,i_d}
= t \cdot \left( \bm{P}_{k_d,i_d} \dot{\bm{N}}_{k_d,i_d}^{q_c} \bm{P}_{k_d,i_d} \right) + o(t).
\]

Substituting this into the full sum, each term is of the form:
\[
t \cdot \left( \text{bounded coefficient involving } \beta^{[\zeta+1]} \text{ and } \bm{Y}_p, \bm{P}_{k,i}, \bm{S}_{k,i} \right) + o(t),
\]
which implies:
\[
\mathfrak{X}^{\bm{X}_{j-1,P},\bm{C}_P,\bm{D}_P,\bm{X}_{j,P}} = O(t) \quad \text{as } t \to 0.
\]

\textbf{Claim 2: $\mathfrak{X}^{\bm{X}_{j-1,P},\bm{C}_N,\bm{D}_N,\bm{X}_{j,P}}  \rightarrow \bm{O}$}

Let $\bm{C} = \bm{D} + t\bm{V}$ for small $t > 0$ and fixed matrix $\bm{V}$, and suppose the Jordan decomposition of $\bm{C}$ depends smoothly on $t$. Then:
\[
\mathfrak{X}^{\bm{X}_{j-1,P},\bm{C}_N,\bm{D}_N,\bm{X}_{j,P}} = O(t)
\quad \text{as} \quad t \to 0.
\]


The expression for $\mathfrak{X}$ consists of four multilinear terms in Eq.~\eqref{eq2:cross:thm:GMOI Perturbation Formula}, each involving differences between nilpotent components of $\bm{C}$ and $\bm{D}$. 

Again, by perturbation theory for Jordan blocks:
\[
\bm{N}_{k_c,i_c}^{q_c}(\bm{C}) = \bm{N}_{k_d,i_d}^{q_d}(\bm{D}) + t \cdot \dot{\bm{N}}_{k_d,i_d}^{q_c} + o(t),
\]
and
\[
\bm{P}_{k_c,i_c}(\bm{C}) = \bm{P}_{k_d,i_d}(\bm{D}) + t \cdot \dot{\bm{P}}_{k_d,i_d} + o(t),
\]
where $\dot{\bm{N}}_{k_d,i_d}$ and $\dot{\bm{P}}_{k_d,i_d}$ are Fréchet derivatives with respect to $t$.

Now analyze each of the four terms in Eq.~\eqref{eq2:cross:thm:GMOI Perturbation Formula}:

Term 1:
\[
\bm{P}_{k_c,i_c}(\bm{N}_{k_c,i_c}^{q_c} - \bm{N}_{k_d,i_d}^{q_d})\bm{N}_{k_d,i_d}^{q_d}
= O(t),
\]
since $(\bm{N}_{k_c,i_c}^{q_c} - \bm{N}_{k_d,i_d}^{q_d}) = O(t)$ and all other matrices (e.g., $\bm{Y}_j$) are fixed.

Term 2:
\[
\bm{N}_{k_c,i_c}^{q_c}(\bm{N}_{k_c,i_c}^{q_c} - \bm{N}_{k_d,i_d}^{q_d})\bm{P}_{k_d,i_d}
= O(t),
\]
because $(\bm{N}_{k_c,i_c}^{q_c} - \bm{N}_{k_d,i_d}^{q_d}) = O(t)$ is again an $O(t)$ difference.


We prove that the third and fourth terms in Eq.~\eqref{eq2:cross:thm:GMOI Perturbation Formula} cancel in the limit $\bm{C} \to \bm{D}$. Denote the third term as $T_3$ and the fourth term as $T_4$. Then, we have:
%
\begin{eqnarray}
T_3 &=& \sum\limits_{\substack{S_{k_p,i_p}, p \in [1,j-2], \\
S_{k_{p'},i_{p'}}, p' \in [j+1,\zeta]}}\sum\limits_{\substack{k_{j-1},i_{j-1},\\k_c,i_c, k_d,i_d,q_d\\ k_{j},i_{j}}} \frac{(\beta^{[\zeta]}([\lambda_k]_1^{j-2},\lambda_{k_{j-1}},\lambda_{k_c},\lambda_{k_j},[\lambda_k]_{j+1}^{\zeta}))^{([q]_1^{j-2}[0,q_d,0][q]_{j+1}^{\zeta})}}{ ([q!]_1^{j-2}[0!,q_d!,0!][q!]_{j+1}^{\zeta})  } \nonumber \\
&& \times \left(\prod\limits_{p=1}^{j-2}S_{k_p,i_p}\bm{Y}_p\right)\bm{P}_{k_{j-1},i_{j-1}}\bm{Y}_{j-1}\bm{P}_{k_c,i_c}\bm{N}_{k_d,i_d}^{q_d}\bm{Y}_j\bm{P}_{k_{j},i_{j}}\left(\prod\limits_{p'=j+1}^{\zeta}\bm{Y}_{p'}S_{k_{p'},i_{p'}}\right),
\end{eqnarray}

\begin{eqnarray}
T_4 &=& \sum\limits_{\substack{S_{k_p,i_p}, p \in [1,j-2], \\
S_{k_{p'},i_{p'}}, p' \in [j+1,\zeta]}}\sum\limits_{\substack{k_{j-1},i_{j-1},\\k_c, i_c, q_c, k_d,i_d\\ k_{j},i_{j}}} \frac{(\beta^{[\zeta]}([\lambda_k]_1^{j-2},\lambda_{k_{j-1}},\lambda_{k_d},\lambda_{k_j},[\lambda_k]_{j+1}^{\zeta}))^{([q]_1^{j-2}[0,q_c,0][q]_{j+1}^{\zeta})}}{ ([q!]_1^{j-2}[0!,q_c!,0!][q!]_{j+1}^{\zeta})  } \nonumber \\
&& \times \left(\prod\limits_{p=1}^{j-2}S_{k_p,i_p}\bm{Y}_p\right)\bm{P}_{k_{j-1},i_{j-1}}\bm{Y}_{j-1}\bm{N}_{k_c,i_c}^{q_c}\bm{P}_{k_d,i_d}\bm{Y}_j\bm{P}_{k_{j},i_{j}}\left(\prod\limits_{p'=j+1}^{\zeta}\bm{Y}_{p'}S_{k_{p'},i_{p'}}\right)
\end{eqnarray}

Now, observe the following:

\begin{enumerate}
    \item As $\bm{C} \to \bm{D}$, we have $\lambda_{k_c} \to \lambda_{k_d}$ and the generalized divided differences $\beta^{[\zeta]}$ converge:
    \[
    \beta^{[\zeta]}(\cdots, \lambda_{k_c}, \cdots) \to \beta^{[\zeta]}(\cdots, \lambda_{k_d}, \cdots).
    \]

    \item The projectors and nilpotents satisfy:
    \[
    \bm{P}_{k_c,i_c} \to \bm{P}_{k_d,i_d}, \quad \bm{N}_{k_c,i_c}^{q_c} \to \bm{N}_{k_d,i_d}^{q_d}.
    \]

    \item Furthermore, in the Jordan canonical basis, the nilpotent and projector commute:
    \[
    \bm{P}_{k_d,i_d} \bm{N}_{k_d,i_d}^{q_d} = \bm{N}_{k_d,i_d}^{q_d} \bm{P}_{k_d,i_d}.
    \]
\end{enumerate}

Combining these, we find that in the limit $\bm{C} \to \bm{D}$:

\[
T_3 \to \sum \beta(\cdots) \bm{P}_{k_d,i_d} \bm{N}_{k_d,i_d}^{q_d}, \qquad 
T_4 \to \sum \beta(\cdots) \bm{N}_{k_d,i_d}^{q_d} \bm{P}_{k_d,i_d}.
\]

Since these matrices commute in the limit and the coefficients match, we conclude:
\[
T_3 - T_4 \to \bm{0}.
\]

Therefore, combining the asymptotic bounds and noting all differences are \(O(t)\), we conclude:
\[
\mathfrak{X}^{\bm{X}_{j-1,P},\bm{C}_N,\bm{D}_N,\bm{X}_{j,P}} = O(t) \to \bm{O} \quad \text{as } \bm{C} \to \bm{D}.
\]

This lemma can be proved by using the same methods from proving Claim 1 and Claim 2 to show the following
%
\begin{eqnarray}
\mathfrak{X}^{\bm{X}_{j-1,P},\bm{C}_P,\bm{D}_P,\bm{X}_{j,N}}  \rightarrow \bm{O}, \nonumber \\
\mathfrak{X}^{\bm{X}_{j-1,P},\bm{C}_N,\bm{D}_N,\bm{X}_{j,N}} \rightarrow \bm{O}, \nonumber \\\mathfrak{X}^{\bm{X}_{j-1,N},\bm{C}_P,\bm{D}_P,\bm{X}_{j,P}} \rightarrow \bm{O}, \nonumber \\
\mathfrak{X}^{\bm{X}_{j-1,N},\bm{C}_N,\bm{D}_N,\bm{X}_{j,P}} \rightarrow \bm{O}, \nonumber \\\mathfrak{X}^{\bm{X}_{j-1,N},\bm{C}_P,\bm{D}_P,\bm{X}_{j,N}} \rightarrow \bm{O}, \nonumber \\ \mathfrak{X}^{\bm{X}_{j-1,N},\bm{C}_N,\bm{D}_N,\bm{X}_{j,N}} \rightarrow \bm{O}.
\end{eqnarray}
%
$\hfill\Box$

We are ready to present Theorem~\ref{thm:GMOI continuity}, which is used to establish the GMOI continuity property. 
%
\begin{theorem}\label{thm:GMOI continuity}
%
Suppose that
%
\begin{equation}\label{eq1:thm:GMOI continuity}
\bm{X}_{j, \ell_j} \rightarrow \bm{X}_{j},
\end{equation}
%
for all $j = 1, 2, \ldots, \zeta+1$, and assume that all partial derivatives of the function $\beta^{[\zeta+1]}$ up to any order are bounded. Then, it follows that
%
\begin{eqnarray}\label{eq2:thm:GMOI continuity}
 T_{\beta^{[\zeta]}}^{\bm{X}_{1, \ell_1},\ldots,\bm{X}_{\zeta+1,\ell_{\zeta+1}}}(\bm{Y}_1,\ldots,\bm{Y}_{\zeta})\rightarrow T_{\beta^{[\zeta]}}^{\bm{X}_1,\ldots,\bm{X}_{\zeta+1}}(\bm{Y}_1,\ldots,\bm{Y}_{\zeta}).
\end{eqnarray}
%
\end{theorem}
%
\textbf{Proof:}
%
By telescoping summation formula, we have
%
\begin{eqnarray}\label{eq3:thm:GMOI continuity}
\lefteqn{\left\Vert T_{\beta^{[\zeta]}}^{\bm{X}_{1, \ell_1},\ldots,\bm{X}_{\zeta+1,\ell_{\zeta+1}}}(\bm{Y}_1,\ldots,\bm{Y}_{\zeta}) - T_{\beta^{[\zeta]}}^{\bm{X}_1,\ldots,\bm{X}_{\zeta+1}}(\bm{Y}_1,\ldots,\bm{Y}_{\zeta}) \right\Vert}\nonumber \\ &=&  \left\Vert \sum\limits_{j=1}^{\zeta+1}\left(T_{\beta^{[\zeta]}}^{[\bm{X}]_1^{j-1},[\bm{X}_\ell]_j^{\zeta+1}}(\bm{Y}_1,\ldots,\bm{Y}_{\zeta}) - T_{\beta^{[\zeta]}}^{ [\bm{X}]_1^{j},[\bm{X}_\ell]_{j+1}^{\zeta+1} }(\bm{Y}_1,\ldots,\bm{Y}_{\zeta})\right)\right\Vert.
\end{eqnarray}
%
For each index $j$, by applying GMOI perturbation formula given by Theorem~\ref{thm:GMOI Perturbation Formula}, we have 
% C -> \bm{X}_{j, \ell_j}
% D -> \bm{X}_{j}
\begin{eqnarray}\label{eq4:thm:GMOI continuity}
\lefteqn{\left\Vert T_{\beta^{[\zeta]}}^{[\bm{X}]_1^{j-1},[\bm{X}_\ell]_j^{\zeta+1}}(\bm{Y}_1,\ldots,\bm{Y}_{\zeta}) - T_{\beta^{[\zeta]}}^{ [\bm{X}]_1^{j},[\bm{X}_\ell]_{j+1}^{\zeta+1} }(\bm{Y}_1,\ldots,\bm{Y}_{\zeta} \right\Vert}\nonumber \\ &=&  \left\Vert T_{\beta^{[\zeta+1]}}^{[\bm{X}]_1^{j-1},\bm{X}_{j, \ell_j},\bm{X}_{j},[\bm{X}_\ell]_{j+1}^{\zeta+1}}([\bm{Y}]_1^{j-1},\bm{X}_{j, \ell_j}-\bm{X}_{j},[\bm{Y}]_j^{\zeta}) -
\bar{\mathfrak{X}}([\bm{X}]_1^{j-1},\bm{X}_{j, \ell_j},\bm{X}_{j},[\bm{X}_\ell]_{j+1}^{\zeta+1}) \right. \nonumber \\
&& - \left. T_{\beta^{[\zeta+1]}}^{[\bm{X}]_1^{j-2},\bm{X}_{j-1,P},\bm{X}_{j, \ell_{j},N},\bm{X}_{j,N},\bm{X}_{j+1,\ell_{j+1}, P},[\bm{X}_\ell]_{j+2}^{\zeta+1}}([\bm{Y}]_1^{j-1},\bm{X}_{j, \ell_j}-\bm{X}_{j},[\bm{Y}]_j^{\zeta}) \right. \nonumber \\
&& - \left. T_{\beta^{[\zeta+1]}}^{[\bm{X}]_1^{j-2},\bm{X}_{j-1,P},\bm{X}_{j, \ell_{j}, N},\bm{X}_{j,N},\bm{X}_{j+1,\ell_{j+1},N},[\bm{X}]_{j+2}^{\zeta+1}}([\bm{Y}]_1^{j-1},\bm{X}_{j, \ell_j}-\bm{X}_{j},[\bm{Y}]_j^{\zeta}) \right. \nonumber \\
&& - \left. T_{\beta^{[\zeta+1]}}^{[\bm{X}]_1^{j-2},\bm{X}_{j-1,N},\bm{X}_{j, \ell_{j},N},\bm{X}_{j,N},\bm{X}_{j+1,\ell_{j+1}, P},[\bm{X}_\ell]_{j+2}^{\zeta+1}}([\bm{Y}]_1^{j-1},\bm{X}_{j, \ell_j}-\bm{X}_{j},[\bm{Y}]_j^{\zeta}) \right. \nonumber \\
&& - \left. T_{\beta^{[\zeta+1]}}^{[\bm{X}]_1^{j-2},\bm{X}_{j-1,N},\bm{X}_{j, \ell_{j}, N},\bm{X}_{j,N},\bm{X}_{j+1,\ell_{j+1},N},[\bm{X}]_{j+2}^{\zeta+1}}([\bm{Y}]_1^{j-1},\bm{X}_{j, \ell_j}-\bm{X}_{j},[\bm{Y}]_j^{\zeta})   \right\Vert  \nonumber \\
&\leq& \left\Vert T_{\beta^{[\zeta+1]}}^{[\bm{X}]_1^{j-1},\bm{X}_{j, \ell_j},\bm{X}_{j},[\bm{X}_\ell]_{j+1}^{\zeta}}([\bm{Y}]_1^{j-1},\bm{X}_{j, \ell_j}-\bm{X}_{j},[\bm{Y}]_j^{\zeta}) \right\Vert + \nonumber \\ 
&& + \left\Vert \bar{\mathfrak{X}}([\bm{X}]_1^{j-1},\bm{X}_{j, \ell_j},\bm{X}_{j},[\bm{X}_\ell]_{j+1}^{\zeta+1}) \right\Vert  \nonumber \\
&& + \left\Vert T_{\beta^{[\zeta+1]}}^{[\bm{X}]_1^{j-2},\bm{X}_{j-1,P},\bm{X}_{j, \ell_{j},N},\bm{X}_{j,N},\bm{X}_{j+1,\ell_{j+1}, P},[\bm{X}_\ell]_{j+2}^{\zeta}}([\bm{Y}]_1^{j-1},\bm{X}_{j, \ell_j}-\bm{X}_{j},[\bm{Y}]_j^{\zeta}) \right\Vert \nonumber \\
&& + \left\Vert T_{\beta^{[\zeta+1]}}^{[\bm{X}]_1^{j-2},\bm{X}_{j-1,P},\bm{X}_{j, \ell_{j}, N},\bm{X}_{j,N},\bm{X}_{j+1,\ell_{j+1},N},[\bm{X}]_{j+2}^{\zeta}}([\bm{Y}]_1^{j-1},\bm{X}_{j, \ell_j}-\bm{X}_{j},[\bm{Y}]_j^{\zeta}) \right\Vert \nonumber \\ 
&& + \left\Vert T_{\beta^{[\zeta+1]}}^{[\bm{X}]_1^{j-2},\bm{X}_{j-1,N},\bm{X}_{j, \ell_{j}, N},\bm{X}_{j,N},\bm{X}_{j+1,\ell_{j+1},P},[\bm{X}]_{j+2}^{\zeta}}([\bm{Y}]_1^{j-1},\bm{X}_{j, \ell_j}-\bm{X}_{j},[\bm{Y}]_j^{\zeta}) \right\Vert \nonumber \\ 
&& + \left\Vert T_{\beta^{[\zeta+1]}}^{[\bm{X}]_1^{j-2},\bm{X}_{j-1,N},\bm{X}_{j, \ell_{j}, N},\bm{X}_{j,N},\bm{X}_{j+1,\ell_{j+1},N},[\bm{X}]_{j+2}^{\zeta}}([\bm{Y}]_1^{j-1},\bm{X}_{j, \ell_j}-\bm{X}_{j},[\bm{Y}]_j^{\zeta}) \right\Vert \nonumber \\ 
&\leq_1& \frac{\epsilon}{6}+ \left(\frac{\epsilon}{6}\right)_\star +  \frac{\epsilon}{6}+ \frac{\epsilon}{6} +  \frac{\epsilon}{6}+ \frac{\epsilon}{6}=\epsilon,
\end{eqnarray}
%
where each $\frac{\epsilon}{6}$ without $\star$ comes from Theorem~\ref{thm: GMOI norm Est} and the assumption that all partial derivatives of the function $\beta^{[\zeta+1]}$ up to any order are bounded. Besides, the term $ (\frac{\epsilon}{6})_\star$ comes from Lemma~\ref{lma: bar mathfrak X zero}.

Then, this theorem is proved because each summand in Eq.~\eqref{eq3:thm:GMOI continuity} approaches to  zero from Eq.~\eqref{eq4:thm:GMOI continuity}.
%
$\hfill\Box$


\section{Applications: Differentiation of Matrix Functions}\label{sec: Applications: Differentiation of Matrix Functions}

The purpose of this section is to apply previous GMOI theory to study the differentiation of a matrix function.  The goal is to obtain 
%
\begin{eqnarray}\label{eq:n-th derivative}
\frac{ d^n f (\bm{X}+t \bm{Y})}{d t^n},
\end{eqnarray}
%
where $n \in \mathbb{N}$. Recall Theorem 11~\cite{chang2025GDOICont}, we have
%
\begin{theorem}\label{thm:d f X dt}
%
Let $f$ be a complex-valued and differentiable function, we have 
%
\begin{eqnarray}\label{eq1:thm:d f X dt}
\frac{df(\bm{X} + t \bm{Y})}{dt}&=&T_{f^{[1]}}^{\bm{X} + t \bm{Y},\bm{X} + t \bm{Y}}\left(\bm{Y}\right),
\end{eqnarray}
%
where $T_{f^{[1]}}^{\bm{X} + t \bm{Y},\bm{X} + t \bm{Y}}\left(\bm{Y}\right)$ is the GDOI with matrices $\bm{X}$ and $\bm{Y}$.   
%
\end{theorem}

Before presenting the main theorem in this section, we have to introduce the following lemmas. Lemma~\ref{lma:diff of GMOI with all para matrices are nilpotent}  shows tha the differentiation of a GMOI will be a zero matrix if all parameter matrices are nilpotent parts of the original parameter matrices. 

\begin{lemma}\label{lma:diff of GMOI with all para matrices are nilpotent} 
%
Given a GMOI with the following format:
%
\begin{eqnarray}\label{eq1:lma:diff of GMOI with all para matrices are nilpotent} 
T_{\beta^{[\zeta]}}^{[\bm{X}_N]_{1}^{\zeta+1}}([\bm{Y}]_1^{\zeta}), 
\end{eqnarray}
%
we have
%
\begin{eqnarray}\label{eq2:lma:diff of GMOI with all para matrices are nilpotent} 
\left.\frac{d T_{\beta^{[\zeta]}}^{[(\bm{X}+t\bm{Y})_N]_{1}^{\zeta+1}}([\bm{Y}]_1^{\zeta})}{dt}\right\vert_{t=0} = \bm{O}. 
\end{eqnarray}
%
\end{lemma}
%
\textbf{Proof:}
%
By derivative definition and telescoping summation relation, we have
%
\begin{eqnarray}\label{eq3:lma:diff of GMOI with all para matrices are nilpotent} 
\lefteqn{\lim\limits_{t \rightarrow 0} \frac{ T_{\beta^{[\zeta]}}^{[(\bm{X}+t\bm{Y})_N]_{1}^{\zeta+1}}([\bm{Y}]_1^{\zeta}) - T_{\beta^{[\zeta]}}^{[\bm{X}_N]_{1}^{\zeta+1}}([\bm{Y}]_1^{\zeta}) }{t}=}\nonumber \\
&& \lim\limits_{t \rightarrow 0} \frac{\sum\limits_{j=1}^{\zeta+1}\left(T_{\beta^{[\zeta]}}^{[\bm{X}_N]_{1}^{j-1},[(\bm{X}+t\bm{Y})_N]_{j}^{\zeta+1}}([\bm{Y}]_1^{\zeta}) - T_{\beta^{[\zeta]}}^{[\bm{X}_N]_{1}^{j},[(\bm{X}+t\bm{Y})_N]_{j+1}^{\zeta+1}}([\bm{Y}]_1^{\zeta})\right)}{t}.
\end{eqnarray}
%
Then, for each $j$ in the summand of the numerator of Eq.~\eqref{eq3:lma:diff of GMOI with all para matrices are nilpotent}, we have
%
\begin{eqnarray}\label{eq4:lma:diff of GMOI with all para matrices are nilpotent} 
\lefteqn{T_{\beta^{[\zeta]}}^{[\bm{X}_N]_{1}^{j-1},[(\bm{X}+t\bm{Y})_N]_{j}^{\zeta+1}}([\bm{Y}]_1^{\zeta}) - T_{\beta^{[\zeta]}}^{[\bm{X}_N]_{1}^{j},[(\bm{X}+t\bm{Y})_N]_{j+1}^{\zeta+1}}([\bm{Y}]_1^{\zeta})}\nonumber \\
&=_1& T_{\beta^{[\zeta+1]}}^{[\bm{X}_N]_{1}^{j-1},(\bm{X}+t\bm{Y})_N,\bm{X}_N,[(\bm{X}+t\bm{Y})_N]_{j}^{\zeta+1}}([\bm{Y}]_1^{j-1},t\bm{Y},[\bm{Y}]_{j}^{\zeta}) \nonumber \\
&& - T_{\beta^{[\zeta+1]}}^{[\bm{X}_N]_{1}^{j-1},(\bm{X}+t\bm{Y})_N,\bm{X}_N,[(\bm{X}+t\bm{Y})_N]_{j}^{\zeta+1}}([\bm{Y}]_1^{j-1},t\bm{Y},[\bm{Y}]_{j}^{\zeta}) \nonumber \\
&& -  \overline{\mathfrak{X}}([\bm{X}_N]_{1}^{j-1},(\bm{X}+t\bm{Y})_N,\bm{X}_N,[(\bm{X}+t\bm{Y})_N]_{j}^{\zeta+1})\nonumber \\
&=_2&\bm{O},
\end{eqnarray}
%
where the perturbation formula given by Theorem~\ref{thm:GMOI Perturbation Formula} is applied to get $=_1$, and Eq.~\eqref{eq2:thm:GMOI Perturbation Formula} is used to get $=_2$ since $ \overline{\mathfrak{X}}([\bm{X}_N]_{1}^{j-1},(\bm{X}+t\bm{Y})_N,\bm{X}_N,[(\bm{X}+t\bm{Y})_N]_{j}^{\zeta+1}) = \bm{O}$ by setting $\bm{C} = (\bm{X}+t\bm{Y})_N$ and $\bm{D}=\bm{X}_N$, respectively. 
%
$\hfill\Box$

Lemma~\ref{lma:diff of GMOI with para matrices having some org matrices} will study the the differentiation of a GMOI given that not all parameter matrices are nilpotent parts of the original parameter matrices. 

\begin{lemma}\label{lma:diff of GMOI with para matrices having some org matrices}
%
Given a GMOI with the following format:
%
\begin{eqnarray}\label{eq1:lma:diff of GMOI with para matrices having some org matrices}
T_{\beta^{[\zeta]}}^{\underline{[\bm{X},\bm{X}_N]}_\ell}([\bm{Y}]_1^{\zeta}), 
\end{eqnarray}
%
where $\underline{[\bm{X},\bm{X}_N]}_\ell$ is an array of parameter matrices with $\zeta+1$ matrices composed by at least one matrix $\bm{X}$ and at least one matrix $\bm{X}_N$, and the subscript $\ell$ is used to index those many possible arrays of parameter matrices with $\zeta+1$ matrices composed by at least one matrix $\bm{X}$ and at least one matrix $\bm{X}_N$.  We define the mapping function $\vartheta_\ell(j)$ as the position of the $j$-th paramter matrix $\bm{X}$ in the array $\underline{[\bm{X},\bm{X}_N]}_\ell$,  where $j=1,2,\ldots, \left\vert\underline{[\bm{X},\bm{X}_N]}_\ell\right\vert_{\bm{X}}$ and $\left\vert\underline{[\bm{X},\bm{X}_N]}_\ell\right\vert_{\bm{X}}$ represents the number of $\bm{X}$ in the array of parameter matrices $\underline{[\bm{X},\bm{X}_N]}_\ell$. 
%
Let $[\underline{[\bm{X},\bm{X}_N]}_\ell]_1^{\vartheta_\ell(j) -1}$ represents the first $\vartheta_\ell(j) -1$ parameter matrices of the array $\underline{[\bm{X},\bm{X}_N]}_\ell$, and $[\underline{[\bm{X},\bm{X}_N]}_\ell]_{\vartheta_\ell(j)+1}^{\zeta+1}$ represents the last $\zeta-\vartheta_\ell(j) +1$ parameter matrices of the array $\underline{[\bm{X},\bm{X}_N]}_\ell$. We also use $\tilde{\bm{X}} = \bm{X}+ t \bm{Y}$ for later notations simplification.

Then, we have
%
\begin{eqnarray}\label{eq2:lma:diff of GMOI with para matrices having some org matrices}
\lefteqn{\left.\frac{d T_{\beta^{[\zeta]}}^{\underline{[\bm{X}+t\bm{Y},(\bm{X}+t\bm{Y})_N]}_\ell}([\bm{Y}]_1^{\zeta})}{dt}\right\vert_{t=0}}\nonumber \\
&=& \sum\limits_{j=1}^{\left\vert\underline{[\bm{X},\bm{X}_N]}_\ell\right\vert_{\bm{X}}}\Bigg[T_{\beta^{[\zeta+1]}}^{
[\underline{[\bm{X},\bm{X}_N]}_\ell]_1^{\vartheta_\ell(j) -1},\bm{X},\bm{X},
[\underline{[\bm{X},\bm{X}_N]}_\ell]_{\vartheta_\ell(j)+1}^{\zeta+1}
}([\bm{Y}]_1^{\vartheta_\ell(j)-1}, \bm{Y}, [\bm{Y}]_{\vartheta_\ell(j)}^{\zeta}) \nonumber \\
&& -  T_{\beta^{[\zeta+1]}}^{
[\underline{[\bm{X},\bm{X}_N]}_\ell]_1^{\vartheta_\ell(j) -1},\bm{X}_N,\bm{X}_N,
[\underline{[\bm{X},\bm{X}_N]}_\ell]_{\vartheta_\ell(j)+1}^{\zeta+1}
}([\bm{Y}]_1^{\vartheta_\ell(j)-1}, \bm{Y}, [\bm{Y}]_{\vartheta_\ell(j)}^{\zeta}) \nonumber \\
&& - \left.\mathfrak{X}^{(1)}\left(
[\underline{[\bm{X},\bm{X}_N]}_\ell]_1^{\vartheta_\ell(j) -1},\tilde{\bm{X}},\bm{X},
[\underline{[\tilde{\bm{X}},\tilde{\bm{X}}_N]}_\ell]_{\vartheta_\ell(j)+1}^{\zeta+1}
\right)\right\vert_{t=0} \Bigg]
\end{eqnarray}
%
where $ \left.\mathfrak{X}^{(1)}\left(
[\underline{[\bm{X},\bm{X}_N]}_\ell]_1^{\vartheta_\ell(j) -1},\tilde{\bm{X}},\bm{X},
[\underline{[\tilde{\bm{X}},\tilde{\bm{X}}_N]}_\ell]_{\vartheta_\ell(j)+1}^{\zeta+1}
\right)\right\vert_{t=0}$ is obtained by
%
\begin{eqnarray}\label{eq3:lma:diff of GMOI with para matrices having some org matrices}
\lefteqn{\left.\mathfrak{X}^{(1)}\left([\underline{[\bm{X},\bm{X}_N]}_\ell]_1^{\vartheta_\ell(j) -1},\tilde{\bm{X}},\bm{X},
[\underline{[\tilde{\bm{X}},\tilde{\bm{X}}_N]}_\ell]_{\vartheta_\ell(j)+1}^{\zeta+1}\right)\right\vert_{t=0}}\nonumber \\
&=&
\left.\frac{d \mathfrak{X}\left( [\underline{[\bm{X},\bm{X}_N]}_\ell]_1^{\vartheta_\ell(j) -1},\tilde{\bm{X}},\bm{X},
[\underline{[\tilde{\bm{X}},\tilde{\bm{X}}_N]}_\ell]_{\vartheta_\ell(j)+1}^{\zeta+1} \right)}{dt} \right\vert_{t=0}
\end{eqnarray}
%
\end{lemma}
%
\textbf{Proof:}
%
From Lemma~\ref{lma:diff of GMOI with all para matrices are nilpotent}, we only need to consider those terms involving $\bm{X}$ in the telescoping summation decomposition for $ T_{\beta^{[\zeta]}}^{\underline{[\bm{X}+t\bm{Y},(\bm{X}+t\bm{Y})_N]}_\ell}([\bm{Y}]_1^{\zeta}) -  T_{\beta^{[\zeta]}}^{\underline{[\bm{X},\bm{X}_N]}_\ell}([\bm{Y}]_1^{\zeta})$. As derivative for GMOIs involving $\bm{X}_N$ will be zero matrices. 

Therefore, we have
%
\begin{eqnarray}\label{eq4:lma:diff of GMOI with para matrices having some org matrices}
\lefteqn{\lim\limits_{t \rightarrow 0} \frac{T_{\beta^{[\zeta]}}^{\underline{[\bm{X}+t\bm{Y},(\bm{X}+t\bm{Y})_N]}_\ell}([\bm{Y}]_1^{\zeta}) -  T_{\beta^{[\zeta]}}^{\underline{[\bm{X},\bm{X}_N]}_\ell}([\bm{Y}]_1^{\zeta})}{t}=}\nonumber \\
&& \lim\limits_{t \rightarrow 0} \frac{1}{t}
\sum\limits_{j=1}^{\left\vert\underline{[\bm{X},\bm{X}_N]}_\ell\right\vert_{\bm{X}}}
\Bigg[T_{\beta^{[\zeta]}}^{
[\underline{[\bm{X},\bm{X}_N]}_\ell]_1^{\vartheta_\ell(j) -1},\tilde{\bm{X}},
[\underline{[\tilde{\bm{X}},\tilde{\bm{X}}_N]}_\ell]_{\vartheta_\ell(j)+1}^{\zeta+1}
}([\bm{Y}]_1^{\vartheta_\ell(j)-1}, [\bm{Y}]_{\vartheta_\ell(j)}^{\zeta}) \nonumber \\
&& -  T_{\beta^{[\zeta]}}^{
[\underline{[\bm{X},\bm{X}_N]}_\ell]_1^{\vartheta_\ell(j) -1},\bm{X},
[\underline{[\tilde{\bm{X}},\tilde{\bm{X}}_N]}_\ell]_{\vartheta_\ell(j)+1}^{\zeta+1}
}([\bm{Y}]_1^{\vartheta_\ell(j)-1}, [\bm{Y}]_{\vartheta_\ell(j)}^{\zeta})\Bigg].
\end{eqnarray}

Again, by the perturbation formula given by Theorem~\ref{thm:GMOI Perturbation Formula}, we obtain
%
\begin{eqnarray}\label{eq5:lma:diff of GMOI with para matrices having some org matrices}
\lefteqn{\mbox{R.H.S. of Eq.~\eqref{eq4:lma:diff of GMOI with para matrices having some org matrices}}}\nonumber \\
&=&\lim\limits_{t \rightarrow 0} \frac{1}{t}  \sum\limits_{j=1}^{\left\vert\underline{[\bm{X},\bm{X}_N]}_\ell\right\vert_{\bm{X}}}\Bigg[
T_{\beta^{[\zeta+1]}}^{
[\underline{[\bm{X},\bm{X}_N]}_\ell]_1^{\vartheta_\ell(j) -1},\tilde{\bm{X}},\bm{X},
[\underline{[\tilde{\bm{X}},\tilde{\bm{X}}_N]}_\ell]_{\vartheta_\ell(j)+1}^{\zeta+1}
}([\bm{Y}]_1^{\vartheta_\ell(j)-1}, t\bm{Y}, [\bm{Y}]_{\vartheta_\ell(j)}^{\zeta}) \nonumber \\
&& -  T_{\beta^{[\zeta+1]}}^{
[\underline{[\bm{X},\bm{X}_N]}_\ell]_1^{\vartheta_\ell(j) -1},\tilde{\bm{X}}_N,\bm{X}_N,
[\underline{[\tilde{\bm{X}},\tilde{\bm{X}}_N]}_\ell]_{\vartheta_\ell(j)+1}^{\zeta+1}
}([\bm{Y}]_1^{\vartheta_\ell(j)-1}, t\bm{Y}, [\bm{Y}]_{\vartheta_\ell(j)}^{\zeta}) \nonumber \\
&& - \mathfrak{X}\left(
[\underline{[\bm{X},\bm{X}_N]}_\ell]_1^{\vartheta_\ell(j) -1},\tilde{\bm{X}},\bm{X},
[\underline{[\tilde{\bm{X}},\tilde{\bm{X}}_N]}_\ell]_{\vartheta_\ell(j)+1}^{\zeta+1}
\right)\Bigg].
\end{eqnarray}
%
This lemma is proved by setting $t=0$ in Eq.~\eqref{eq5:lma:diff of GMOI with para matrices having some org matrices}.
%
$\hfill\Box$

The exact computation of $ \left.\mathfrak{X}^{(1)}\left(
[\underline{[\bm{X},\bm{X}_N]}_\ell]_1^{\vartheta_\ell(j) -1},\tilde{\bm{X}},\bm{X},
[\underline{[\tilde{\bm{X}},\tilde{\bm{X}}_N]}_\ell]_{\vartheta_\ell(j)+1}^{\zeta+1}
\right)\right\vert_{t=0}$ is tedious and there is no simple formula to express this exactly due to various combination of entries in the array $[\bm{X},\bm{X}_N]_\ell$. But, we will provide an example to show how to calculate this. 

We are ready to present the main Theorem~\ref{thm:n-th der by GMOI} in this section about the representing $n$-th derivative of a matrix-valued function in terms of GMOIs.
%
\begin{theorem}\label{thm:n-th der by GMOI}
% 
Given any matrices $\bm{X}$ and $\bm{Y}$, we have
%
\begin{eqnarray}\label{eq1:thm:n-th der by GMOI}
\left.\frac{d^n f (\bm{X}+t \bm{Y})}{d t^n}\right\vert_{t=0}&=&n! T^{[\bm{X}]_1^{n+1}}_{f^{[n]}}([\bm{Y}]_1^n)-
(n-1)!\sum\limits_{j=1}^n T_{f^{[n]}}^{[\bm{X}]_1^{j-1},\bm{X}_N,\bm{X}_N,[\bm{X}]_{j+1}^{n}}([\bm{Y}]_1^n) \nonumber \\
&&-\sum\limits_{i=1}^{n-1}(n-i)!\left.\sum\limits_{j=1}^{n-i+1} \mathfrak{X}^{(i)}([\bm{X}]_1^{j-1},\tilde{\bm{X}}, \bm{X},[\tilde{\bm{X}}]_{j+1}^{n-i+1})\right\vert_{t=0} \nonumber \\
&&- \sum\limits_{\ell_{n-1}=1}^{\left(\sum\limits_{k=1}^{\lceil\frac{n-1}{2}\rceil}\frac{(n-k)!}{k!(n-2k)!}\right)- 1(\mbox{~if $n$ is even})} a_{\ell_{n-1}}\left.\frac{d T_{f^{[n-1]}}^{\underline{[\tilde{\bm{X}},\tilde{\bm{X}}_N]}_{\ell_{n-1}}}([\bm{Y}]_1^{n-1})}{dt}\right\vert_{t=0} \nonumber \\
&&+ \left[ \sum\limits_{\rho=4}^n\sum\limits_{i_\rho=1}^{\gamma(\rho)} b_{i_\rho}\left.\mathfrak{X}^{(n+2-\rho)}([\tilde{\bm{X}},\bm{X},\bm{X}_N]_{i_\rho})\right\vert_{t=0}\right]\bm{1}(\mbox{if $n \geq 4$}),
\end{eqnarray}
%
where $n \geq 2$, $a_{\ell_{n-1}}$ are coefficients for those GMOIs with parameters matrices containing both $\bm{X}$ and $\bm{X}_N$ from $\frac{d^{n-1} f (\bm{X}+t \bm{Y})}{d t^{n-1}}$, $b_{i_\rho}$ are coefficients for those $\mathfrak{X}^{(k)}([\tilde{\bm{X}},\bm{X},\bm{X}_N]_{i_\rho})$ from  $\frac{d^{n-1} f (\bm{X}+t \bm{Y})}{d t^{n-1}}$ with $k=1,2,\ldots,n-3$, and $[\tilde{\bm{X}},\bm{X},\bm{X}_N]_{i_\rho}$ is the array indexed by $i_\rho$ composed by $\tilde{\bm{X}}, \bm{X}$ and $\bm{X}_N$, respectively with length $\rho$. The term $\gamma(\rho)$ is determined by
%
\begin{eqnarray}\label{eq2:thm:n-th der by GMOI}
\gamma(\rho)&=&  \left[\frac{(\rho-2)!}{1!(\rho-3)!},  \frac{(\rho-3)!}{2!(\rho-5)!}, \ldots, 1 \right] \cdot [\rho-3, \rho-5, \ldots,0],
\end{eqnarray}
%
where $\cdot$ is the inner product operation. Note that $\bm{1}(\mbox{if $n \geq 4$})$ is the indicator condition function.
%
\end{theorem}
%
\textbf{Proof:}
%
Becuase we have
%
\begin{eqnarray}\label{eq2:thm:n-th der by GMOI}
\left.\frac{d f (\bm{X}+t \bm{Y})}{d t}\right\vert_{t=0}&=&T^{[\bm{X}]_1^{2}}_{f^{[1]}}([\bm{Y}]), 
\end{eqnarray}
%
by applying Theorem~\ref{thm:GMOI Perturbation Formula} to Eq.~\ref{eq2:thm:n-th der by GMOI}, we obtain
%
\begin{eqnarray}\label{eq3:thm:n-th der by GMOI}
\left.\frac{d^2 f (\bm{X}+t \bm{Y})}{d^2 t}\right\vert_{t=0}&=&\lim\limits_{t\rightarrow 0}\frac{ T^{[\bm{X}+t\bm{Y}]_1^{2}}_{f^{[1]}}([\bm{Y}])  - T^{[\bm{X}]_1^{2}}_{f^{[1]}}([\bm{Y}])}{t}\nonumber \\
&=&2 T^{[\bm{X}]_1^{3}}_{f^{[2]}}([\bm{Y}]_1^2) - T^{\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[2]}}([\bm{Y}]_1^2) - T^{\bm{X}_N,\bm{X}_N,\bm{X}}_{f^{[2]}}([\bm{Y}]_1^2) \nonumber \\
&&-\left.\mathfrak{X}^{(1)}(\tilde{\bm{X}}, \bm{X}, \tilde{\bm{X}})\right\vert_{t=0} -  \left.\mathfrak{X}^{(1)}(\bm{X}, \tilde{\bm{X}}, \bm{X})\right\vert_{t=0}.
\end{eqnarray}

By taking the derivative of $f(\bm{X}+t\bm{Y})$ repeatdely and applying Theorem~\ref{thm:GMOI Perturbation Formula} to every terms except those GMOIs with parameter matrices conposed by $\bm{X}$ and $\bm{X}_N$ jointly, we have
%
\begin{eqnarray}\label{eq4:thm:n-th der by GMOI}
\lefteqn{\left.\frac{d^n f (\bm{X}+t \bm{Y})}{d t^n}\right\vert_{t=0}, \mbox{without $T^{\underline{[\bm{X}, \bm{X}_N]}}$ derivatives}}\nonumber \\
&=& n! T^{[\bm{X}]_1^{n+1}}_{f^{[n]}}([\bm{Y}]_1^n)-
(n-1)!\sum\limits_{j=1}^n T_{f^{[n]}}^{[\bm{X}]_1^{j-1},\bm{X}_N,\bm{X}_N,[\bm{X}]_{j+1}^{n}}([\bm{Y}]_1^n) \nonumber \\
&&-\sum\limits_{i=1}^{n-1}(n-i)!\left.\sum\limits_{j=1}^{n-i+1} \mathfrak{X}^{(i)}([\bm{X}]_1^{j-1},\tilde{\bm{X}}, \bm{X},[\tilde{\bm{X}}]_{j+1}^{n-i+1})\right\vert_{t=0}.
\end{eqnarray}

For those derivatives of GMOIs involving  $T^{[\bm{X}, \bm{X}_N]}$, there are $\left(\sum\limits_{k=1}^{\lceil\frac{n-1}{2}\rceil}\frac{(n-k)!}{k!(n-2k)!}\right)$ terms of GMOIs with parameter matrices having $\bm{X}_N$. However, from Lemma~\ref{lma:diff of GMOI with all para matrices are nilpotent}, we only need to consider GMOIs with parameter matrices composed by $\bm{X}$ and $\bm{X}_N$ jointly. Therefore, we need to reduce one in the total number of $\ell_{n-1}$. By Lemma~\ref{lma:diff of GMOI with para matrices having some org matrices}, we can evaluate each term of $\left.\frac{d T_{f^{[n-1]}}^{\underline{[\tilde{\bm{X}},\tilde{\bm{X}}_N]}_{\ell_{n-1}}}([\bm{Y}]_1^{n-1})}{dt}\right\vert_{t=0}$. Because there are $\gamma(\rho)$ terms for each $i_\rho$ to form $\mathfrak{X}^{(n+2-\rho)}([\tilde{\bm{X}},\bm{X},\bm{X}_N]_{i_\rho})$ when we apply perturbation formula from Theorem~\ref{thm:GMOI Perturbation Formula} in evaluating $\frac{d T_{f^{[n-1]}}^{\underline{[\tilde{\bm{X}},\tilde{\bm{X}}_N]}_{\ell_{n-1}}}([\bm{Y}]_1^{n-1})}{dt}$. 

Let us explain why the value $\gamma(\rho)$ can be expressed by
%
\begin{eqnarray}\label{eq4-1:thm:n-th der by GMOI}
\gamma(\rho)&=&  \left[\frac{(\rho-2)!}{1!(\rho-3)!},  \frac{(\rho-3)!}{2!(\rho-5)!}, \ldots, 1 \right] \cdot [\rho-3, \rho-5, \ldots,0].
\end{eqnarray}

We obtain
\[
\frac{(\rho - k - 1)!}{k! (\rho - 2k - 1)!}
\]
GMOIs of parameter matrices with the length \( \rho - 1 \) from the derivative
\[
\frac{d^{n-2}}{dt^{n-2}} f(\bm{X} + t \bm{Y}),
\]
since we begin considering the operator derivative structure of
\(\mathfrak{X}([\tilde{\bm{X}}, \bm{X}, \bm{X}_N]_{i_\rho})\)
from order 2. Moreover, each such GMOI includes \( \rho - 2k - 1 \) instances of \( \tilde{\bm{X}} \). As a result, we have
\[
\frac{(\rho - k - 1)!}{k! (\rho - 2k - 1)!} \times (\rho - 2k - 1)
\]
terms of the form
\(\mathfrak{X}([\tilde{\bm{X}}, \bm{X}, \bm{X}_N])\),
where the total array length is \( \rho \), and there are exactly \( k \) pairs of \( \tilde{\bm{X}}_N \). The total count
\(\gamma(\rho)\) is then obtained by summing over all admissible values of \( k \).

Therefore, we have
%
\begin{eqnarray}\label{eq5:thm:n-th der by GMOI}
\lefteqn{\left.\frac{d^n f (\bm{X}+t \bm{Y})}{d t^n}\right\vert_{t=0}, \mbox{with $T^{\underline{[\bm{X}, \bm{X}_N]}}$ derivatives}}\nonumber \\
&=& - \sum\limits_{\ell_{n-1}=1}^{\left(\sum\limits_{k=1}^{\lceil\frac{n-1}{2}\rceil}\frac{(n-k)!}{k!(n-2k)!}\right)- 1(\mbox{~if $n$ is even})} a_{\ell_{n-1}}\left.\frac{d T_{f^{[n-1]}}^{\underline{[\tilde{\bm{X}},\tilde{\bm{X}}_N]}_{\ell_{n-1}}}([\bm{Y}]_1^{n-1})}{dt}\right\vert_{t=0} \nonumber \\
&&+  \sum\limits_{\rho=4}^n\sum\limits_{i_\rho=1}^{\gamma(\rho)} b_{i_\rho}\left.\mathfrak{X}^{(n+2-\rho)}([\tilde{\bm{X}},\bm{X},\bm{X}_N]_{i_\rho})\right\vert_{t=0}.
\end{eqnarray}
%
This theorem is proved by combing Eq.~\eqref{eq4:thm:n-th der by GMOI} and Eq.~\eqref{eq5:thm:n-th der by GMOI}
%
$\hfill\Box$

Below, we will present examples to illustrate $\left.\frac{d^3 f (\bm{X}+t \bm{Y})}{d^3 t}\right\vert_{t=0}$ and $\left.\frac{d^4 f (\bm{X}+t \bm{Y})}{d^4 t}\right\vert_{t=0}$. 
%
\begin{example}\label{exp: der order 3 and 4}
%
Since we have
%
\begin{eqnarray}\label{eq1:exp: der order 3 and 4}
\left.\frac{d^2 f (\bm{X}+t \bm{Y})}{d^2 t}\right\vert_{t=0}&=&\lim\limits_{t\rightarrow 0}\frac{ T^{[\bm{X}+t\bm{Y}]_1^{2}}_{f^{[1]}}([\bm{Y}])  - T^{[\bm{X}]_1^{2}}_{f^{[1]}}([\bm{Y}])}{t}\nonumber \\
&=&2 T^{[\bm{X}]_1^{3}}_{f^{[2]}}([\bm{Y}]_1^2) - T^{\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[2]}}([\bm{Y}]_1^2) - T^{\bm{X}_N,\bm{X}_N,\bm{X}}_{f^{[2]}}([\bm{Y}]_1^2) \nonumber \\
&&-\left.\mathfrak{X}^{(1)}(\tilde{\bm{X}}, \bm{X}, \tilde{\bm{X}})\right\vert_{t=0} -  \left.\mathfrak{X}^{(1)}(\bm{X}, \tilde{\bm{X}}, \bm{X})\right\vert_{t=0},
\end{eqnarray}
%
by the telescoping summation and the perturbation formula given by Theorem~\ref{thm:GMOI Perturbation Formula}, we have 
%
\begin{eqnarray}\label{eq2:exp: der order 3 and 4}
\left.\frac{d 2 T^{[\bm{X}]_1^{3}}_{f^{[2]}}([\bm{Y}]_1^2)}{d t}\right\vert_{t=0}&=& 3! T^{[\bm{X}]_1^{4}}_{f^{[3]}}([\bm{Y}]_1^3) - 2 T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X}}_{f^{[3]}}([\bm{Y}]_1^3) \nonumber \\
&& - 2 T^{\bm{X}, \bm{X}_N,\bm{X}_N,\bm{X}}_{f^{[3]}}([\bm{Y}]_1^3) - 2 T^{\bm{X},\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[3]}}([\bm{Y}]_1^3)\nonumber \\
&& - 2 \mathfrak{X}^{(1)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}},\tilde{\bm{X}}) - 2 \mathfrak{X}^{(1)}(\bm{X}, \tilde{\bm{X}},\bm{X},\tilde{\bm{X}}) \nonumber \\
&& - 2 \mathfrak{X}^{(1)}(\bm{X},\bm{X},\tilde{\bm{X}},\bm{X}).
\end{eqnarray}
%
By applying Lemma~\ref{lma:diff of GMOI with para matrices having some org matrices} to $T^{\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[2]}}([\bm{Y}]_1^2)$ and $T^{\bm{X}_N,\bm{X}_N,\bm{X}}_{f^{[2]}}([\bm{Y}]_1^2)$, we have 
%
\begin{eqnarray}\label{eq3:exp: der order 3 and 4}
\left.\frac{d T^{\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[2]}}([\bm{Y}]_1^2)}{d t}\right\vert_{t=0}&=& T^{\bm{X},\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[3]}}([\bm{Y}]_1^3) - T^{\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}_N}_{f^{[3]}}([\bm{Y}]_1^3) \nonumber \\
&&-\mathfrak{X}^{(1)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}}_N,\tilde{\bm{X}}_N),
\end{eqnarray}
%
and
%
\begin{eqnarray}\label{eq4:exp: der order 3 and 4}
\left.\frac{d T^{\bm{X}_N,\bm{X}_N,\bm{X}}_{f^{[2]}}([\bm{Y}]_1^2)}{d t}\right\vert_{t=0}&=& T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X}}_{f^{[3]}}([\bm{Y}]_1^3) - T^{\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}_N}_{f^{[3]}}([\bm{Y}]_1^3) \nonumber \\
&&-\mathfrak{X}^{(1)}(\bm{X}_N,\bm{X}_N,\tilde{\bm{X}},\bm{X}).
\end{eqnarray}
%
By combining Eq.~\eqref{eq2:exp: der order 3 and 4} to Eq.~\eqref{eq4:exp: der order 3 and 4}, we have
%
\begin{eqnarray}\label{eq5:exp: der order 3 and 4}
\left.\frac{d^3 f (\bm{X}+t \bm{Y})}{d^3 t}\right\vert_{t=0}&=& 3! T^{[\bm{X}]_1^{4}}_{f^{[3]}}([\bm{Y}]_1^3) - 3 T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X}}_{f^{[3]}}([\bm{Y}]_1^3) \nonumber \\
&& - 2 T^{\bm{X}, \bm{X}_N,\bm{X}_N,\bm{X}}_{f^{[3]}}([\bm{Y}]_1^3) - 3 T^{\bm{X},\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[3]}}([\bm{Y}]_1^3)\nonumber \\
&& - 2 \left.\mathfrak{X}^{(1)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}},\tilde{\bm{X}})\right\vert_{t=0} - 2\left. \mathfrak{X}^{(1)}(\bm{X}, \tilde{\bm{X}},\bm{X},\tilde{\bm{X}})\right\vert_{t=0} \nonumber \\
&& - 2 \left.\mathfrak{X}^{(1)}(\bm{X},\bm{X},\tilde{\bm{X}},\bm{X})\right\vert_{t=0} + 2T^{\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}_N}_{f^{[3]}}([\bm{Y}]_1^3) \nonumber \\
&&-\left.\mathfrak{X}^{(2)}(\tilde{\bm{X}}, \bm{X}, \tilde{\bm{X}})\right\vert_{t=0} -  \left.\mathfrak{X}^{(2)}(\bm{X}, \tilde{\bm{X}}, \bm{X})\right\vert_{t=0}\nonumber \\
&&+\left.\mathfrak{X}^{(1)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}}_N,\tilde{\bm{X}}_N)\right\vert_{t=0} +\left.\mathfrak{X}^{(1)}(\bm{X}_N,\bm{X}_N,\tilde{\bm{X}},\bm{X})\right\vert_{t=0} \nonumber \\
\end{eqnarray}

For the evaluation of $\left.\frac{d^4 f (\bm{X}+t \bm{Y})}{d^4 t}\right\vert_{t=0}$, we first derive
%
\begin{eqnarray}\label{eq5:exp: der order 3 and 4}
 3! \frac{d T^{[\bm{X}]_1^{4}}_{f^{[3]}}([\bm{Y}]_1^3)}{d t}&=&  4! T^{[\bm{X}]_1^{5}}_{f^{[4]}}([\bm{Y}]_1^4) - 3! T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X},\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&& - 3! T^{\bm{X}, \bm{X}_N,\bm{X}_N,\bm{X},\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) - 3! T^{\bm{X},\bm{X},\bm{X}_N,\bm{X}_N, \bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) - 3! T^{\bm{X},\bm{X},\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4)  \nonumber \\
&& - 3!  \mathfrak{X}^{(1)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}},\tilde{\bm{X}},\tilde{\bm{X}}) - 3! \mathfrak{X}^{(1)}(\bm{X}, \tilde{\bm{X}},\bm{X},\tilde{\bm{X}},\tilde{\bm{X}}) \nonumber \\
&& - 3!  \mathfrak{X}^{(1)}(\bm{X},\bm{X},\tilde{\bm{X}},\bm{X},\tilde{\bm{X}})- 3!  \mathfrak{X}^{(1)}(\bm{X},\bm{X},\bm{X},\tilde{\bm{X}},\bm{X}).
\end{eqnarray}
%
by the telescoping summation and the perturbation formula given by Theorem~\ref{thm:GMOI Perturbation Formula}.

We also have
%
\begin{eqnarray}\label{eq6-1:exp: der order 3 and 4}
\left.\frac{d T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X}}_{f^{[3]}}([\bm{Y}]_1^3)}{d t}\right\vert_{t=0}&=& T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X},\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) - T^{\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&&-\left.\mathfrak{X}^{(1)}(\bm{X}_N,\bm{X}_N,\tilde{\bm{X}},\bm{X},\tilde{\bm{X}})\right\vert_{t=0}\nonumber \\
&& +  T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X},\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) - T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&&-\left.\mathfrak{X}^{(1)}(\bm{X}_N,\bm{X}_N,\bm{X},\tilde{\bm{X}},\bm{X})\right\vert_{t=0},
\end{eqnarray}
%
\begin{eqnarray}\label{eq6-2:exp: der order 3 and 4}
\left.\frac{d T^{\bm{X},\bm{X}_N,\bm{X}_N,\bm{X}}_{f^{[3]}}([\bm{Y}]_1^3)}{d t}\right\vert_{t=0}&=& T^{\bm{X},\bm{X},\bm{X}_N,\bm{X}_N,\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) - T^{\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&&-\left.\mathfrak{X}^{(1)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}}_N,\tilde{\bm{X}}_N,\tilde{\bm{X}})\right\vert_{t=0} \nonumber \\
&& +  T^{\bm{X},\bm{X}_N,\bm{X}_N,\bm{X},\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) - T^{\bm{X},\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&&-\left.\mathfrak{X}^{(1)}(\bm{X},\bm{X}_N,\bm{X}_N,\tilde{\bm{X}},\bm{X})\right\vert_{t=0},
\end{eqnarray}
%
and
%
\begin{eqnarray}\label{eq6-3:exp: der order 3 and 4}
\left.\frac{d T^{\bm{X},\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[3]}}([\bm{Y}]_1^3)}{d t}\right\vert_{t=0}&=& T^{\bm{X},\bm{X},\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4) - T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&&-\left.\mathfrak{X}^{(1)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}},\tilde{\bm{X}}_N,\tilde{\bm{X}}_N)\right\vert_{t=0} \nonumber \\
&& +  T^{\bm{X},\bm{X},\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4) - T^{\bm{X},\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&&-\left.\mathfrak{X}^{(1)}(\bm{X},\tilde{\bm{X}},\bm{X},\tilde{\bm{X}}_N,\tilde{\bm{X}}_N)\right\vert_{}.
\end{eqnarray}

By combining Eq.~\eqref{eq5:exp: der order 3 and 4} to Eq.~\eqref{eq6-3:exp: der order 3 and 4}, we have
%
\begin{eqnarray}\label{eq7:exp: der order 3 and 4}
\lefteqn{\left.\frac{d^4 f (\bm{X}+t \bm{Y})}{d^4 t}\right\vert_{t=0}}\nonumber\\
&=& 4! T^{[\bm{X}]_1^{5}}_{f^{[4]}}([\bm{Y}]_1^4) - 3! T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X},\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&& - 3! T^{\bm{X}, \bm{X}_N,\bm{X}_N,\bm{X},\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) - 3! T^{\bm{X},\bm{X},\bm{X}_N,\bm{X}_N, \bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) - 3! T^{\bm{X},\bm{X},\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4)  \nonumber \\
&& - 3!  \left.\mathfrak{X}^{(1)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}},\tilde{\bm{X}},\tilde{\bm{X}})\right\vert_{t=0} - 3! \left.\mathfrak{X}^{(1)}(\bm{X}, \tilde{\bm{X}},\bm{X},\tilde{\bm{X}},\tilde{\bm{X}})\right\vert_{t=0} \nonumber \\
&& - 3!  \left.\mathfrak{X}^{(1)}(\bm{X},\bm{X},\tilde{\bm{X}},\bm{X},\tilde{\bm{X}})\right\vert_{t=0} - 3!  \left.\mathfrak{X}^{(1)}(\bm{X},\bm{X},\bm{X},\tilde{\bm{X}},\bm{X})\right\vert_{t=0} \nonumber \\
&&-3\Bigg(T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X},\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) - T^{\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&&-\left.\mathfrak{X}^{(1)}(\bm{X}_N,\bm{X}_N,\tilde{\bm{X}},\bm{X},\tilde{\bm{X}})\right\vert_{t=0} \nonumber \\
&& +  T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X},\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) - T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&&-\left.\mathfrak{X}^{(1)}(\bm{X}_N,\bm{X}_N,\bm{X},\tilde{\bm{X}},\bm{X})\right\vert_{t=0} \Bigg)\nonumber \\
&&-2\Bigg(T^{\bm{X},\bm{X},\bm{X}_N,\bm{X}_N,\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) - T^{\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&&-\left.\mathfrak{X}^{(1)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}}_N,\tilde{\bm{X}}_N,\tilde{\bm{X}})\right\vert_{t=0} \nonumber \\
&& +  T^{\bm{X},\bm{X}_N,\bm{X}_N,\bm{X},\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) - T^{\bm{X},\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&&-\left.\mathfrak{X}^{(1)}(\bm{X},\bm{X}_N,\bm{X}_N,\tilde{\bm{X}},\bm{X})\right\vert_{t=0} \Bigg)\nonumber \\
&&-3\Bigg(T^{\bm{X},\bm{X},\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4) - T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&&- \left.\mathfrak{X}^{(1)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}}_N,\tilde{\bm{X}}_N,\tilde{\bm{X}})\right\vert_{t=0} \nonumber \\
&& +  T^{\bm{X},\bm{X},\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4) - T^{\bm{X},\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&&- \left.\mathfrak{X}^{(1)}(\bm{X},\tilde{\bm{X}},\bm{X},\tilde{\bm{X}}_N,\tilde{\bm{X}}_N)\right\vert_{t=0} \Bigg)\nonumber \\
&&  -2 \left.\mathfrak{X}^{(2)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}},\tilde{\bm{X}})\right\vert_{t=0} - 2\left. \mathfrak{X}^{(2)}(\bm{X}, \tilde{\bm{X}},\bm{X},\tilde{\bm{X}})\right\vert_{t=0} \nonumber \\
&& - 2 \left.\mathfrak{X}^{(2)}(\bm{X},\bm{X},\tilde{\bm{X}},\bm{X})\right\vert_{t=0} \nonumber \\
&&-\left.\mathfrak{X}^{(3)}(\tilde{\bm{X}}, \bm{X}, \tilde{\bm{X}})\right\vert_{t=0} -  \left.\mathfrak{X}^{(3)}(\bm{X}, \tilde{\bm{X}}, \bm{X})\right\vert_{t=0}\nonumber \\
&&+\left.\mathfrak{X}^{(2)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}}_N,\tilde{\bm{X}}_N)\right\vert_{t=0} +\left.\mathfrak{X}^{(2)}(\bm{X}_N,\bm{X}_N,\tilde{\bm{X}},\bm{X})\right\vert_{t=0}.
\end{eqnarray}
%
After arranging terms, we have
%
\begin{eqnarray}\label{eq7:exp: der order 3 and 4}
\lefteqn{\left.\frac{d^4 f (\bm{X}+t \bm{Y})}{d^4 t}\right\vert_{t=0}}\nonumber\\
&=& 4! T^{[\bm{X}]_1^{5}}_{f^{[4]}}([\bm{Y}]_1^4) - 12 T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X},\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&& - 8 T^{\bm{X}, \bm{X}_N,\bm{X}_N,\bm{X},\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) - 8 T^{\bm{X},\bm{X},\bm{X}_N,\bm{X}_N, \bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) - 12 T^{\bm{X},\bm{X},\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4)  \nonumber \\
&& - 3! \left.\mathfrak{X}^{(1)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}},\tilde{\bm{X}},\tilde{\bm{X}})\right\vert_{t=0}  - 3! \left.\mathfrak{X}^{(1)}(\bm{X}, \tilde{\bm{X}},\bm{X},\tilde{\bm{X}},\tilde{\bm{X}})\right\vert_{t=0} \nonumber \\
&& - 3!  \left.\mathfrak{X}^{(1)}(\bm{X},\bm{X},\tilde{\bm{X}},\bm{X},\tilde{\bm{X}})\right\vert_{t=0} - 3!  \left.\mathfrak{X}^{(1)}(\bm{X},\bm{X},\bm{X},\tilde{\bm{X}},\bm{X})\right\vert_{t=0}   \nonumber \\
&&  -2 \left.\mathfrak{X}^{(2)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}},\tilde{\bm{X}})\right\vert_{t=0} - 2\left. \mathfrak{X}^{(2)}(\bm{X}, \tilde{\bm{X}},\bm{X},\tilde{\bm{X}})\right\vert_{t=0} \nonumber \\
&& - 2 \left.\mathfrak{X}^{(2)}(\bm{X},\bm{X},\tilde{\bm{X}},\bm{X})\right\vert_{t=0} -\left.\mathfrak{X}^{(3)}(\tilde{\bm{X}}, \bm{X}, \tilde{\bm{X}})\right\vert_{t=0} -  \left.\mathfrak{X}^{(3)}(\bm{X}, \tilde{\bm{X}}, \bm{X})\right\vert_{t=0}\nonumber \\
&&  +3 \left.\mathfrak{X}^{(1)}(\bm{X}_N,\bm{X}_N,\tilde{\bm{X}},\bm{X},\tilde{\bm{X}})\right\vert_{t=0}   +3 \left.\mathfrak{X}^{(1)}(\bm{X}_N,\bm{X}_N,\bm{X},\tilde{\bm{X}},\bm{X})\right\vert_{t=0} + 5 T^{\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}}_{f^{[4]}}([\bm{Y}]_1^4) \nonumber \\
&&  +  2 \left.\mathfrak{X}^{(1)}(\bm{X},\bm{X}_N,\bm{X}_N,\tilde{\bm{X}},\bm{X})\right\vert_{t=0} + 6T^{\bm{X}_N,\bm{X}_N,\bm{X},\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4)+ 5\left.\mathfrak{X}^{(1)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}}_N,\tilde{\bm{X}}_N,\tilde{\bm{X}})\right\vert_{t=0}  \nonumber \\
&&  +5 T^{\bm{X},\bm{X}_N,\bm{X}_N,\bm{X}_N,\bm{X}_N}_{f^{[4]}}([\bm{Y}]_1^4)  +3 \left.\mathfrak{X}^{(1)}(\bm{X},\tilde{\bm{X}},\bm{X},\tilde{\bm{X}}_N,\tilde{\bm{X}}_N)\right\vert_{t=0}  \nonumber \\
&&+\left.\mathfrak{X}^{(2)}(\tilde{\bm{X}},\bm{X},\tilde{\bm{X}}_N,\tilde{\bm{X}}_N)\right\vert_{t=0} +\left.\mathfrak{X}^{(2)}(\bm{X}_N,\bm{X}_N,\tilde{\bm{X}},\bm{X})\right\vert_{t=0}.
\end{eqnarray}
%
\end{example}

From Example~\ref{exp: der order 3 and 4}, we need to evaluate high-order derivatives of terms involving $\mathfrak{X}$. In following Example~\ref{exp: higher order derivative of mathfrak X}, we will try to evaluate any $n$-th order derivative of $\mathfrak{X}(\bm{X}, \tilde{\bm{X}}, \bm{X})$. For other evaluation of high-order derivatives of terms involving $\mathfrak{X}$, they can be calculated similarly although more complicated. 


\begin{example}\label{exp: higher order derivative of mathfrak X}


By Eq.~\eqref{eq2:exp:GMOI Perturbation Formula}, the term $\mathfrak{X}(\bm{X}, \tilde{\bm{X}}, \bm{X})$ can be expressed by
%
\begin{eqnarray}\label{eq1:exp: higher order derivative of mathfrak X}
\bar{\mathfrak{X}}(\bm{C},\bm{D},\bm{X}_1)&=&  \mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,P}} +  \mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,N}} \nonumber \\
&&+ \mathfrak{X}^{\bm{C}_N,\bm{D}_N,\bm{X}_{1,P}} + \mathfrak{X}^{\bm{C}_N,\bm{D}_N,\bm{X}_{1,N}},
\end{eqnarray}
%
where $\bm{C}=\bm{X}, \bm{D}=\bm{X}+t\bm{Y}$ and $\bm{X}_1=\bm{X}$. Then, the $n$-th derivative of  $\mathfrak{X}(\bm{X}, \tilde{\bm{X}}, \bm{X})$ can be expressed by
%
\begin{eqnarray}\label{eq1:exp: higher order derivative of mathfrak X}
\frac{d^n}{dt^n}\bar{\mathfrak{X}}(\bm{C},\bm{D},\bm{X}_1)&=&\frac{d^n}{dt^n}\mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,P}} + \frac{d^n}{dt^n}\mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,N}} \nonumber \\
&&+\frac{d^n}{dt^n}\mathfrak{X}^{\bm{C}_N,\bm{D}_N,\bm{X}_{1,P}} + \frac{d^n}{dt^n}\mathfrak{X}^{\bm{C}_N,\bm{D}_N,\bm{X}_{1,N}}.
\end{eqnarray}
%
In the following, we will evaluate $\frac{d^n}{dt^n}\mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,P}}$, $\frac{d^n}{dt^n}\mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,N}}$, $\frac{d^n}{dt^n}\mathfrak{X}^{\bm{C}_N,\bm{D}_N,\bm{X}_{1,P}}$ and $\frac{d^n}{dt^n}\mathfrak{X}^{\bm{C}_N,\bm{D}_N,\bm{X}_{1,N}}$, respectively.

\textbf{The Evaluation of $\frac{d^n}{dt^n} \mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,P}}$}

Because we have
%
\begin{eqnarray}\label{e3-1:exp: higher order derivative of mathfrak X}
\lefteqn{\mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,P}}= }\nonumber \\
&&\sum\limits_{\substack{k_c, i_c,q_c,k_d,i_d,q_d\\ k_{1},i_{1}}}\frac{(\beta^{[2]}(\lambda_{k_c},\lambda_{k_d},\lambda_{k_1}))^{([0,0,0])}}{ ([0!,0!,0!])} \times \bm{P}_{k_c,i_c}(\bm{N}_{k_c,i_c}^{q_c}-\bm{N}_{k_d,i_d}^{q_d})\bm{P}_{k_d,i_d}\bm{Y}\bm{P}_{k_{1},i_{1}},
\end{eqnarray}
%
to derive the $n$-th derivative of the operator-valued expression
\[
\mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,P}}
\]
with respect to $t$, from Eq.~\eqref{e3-1:exp: higher order derivative of mathfrak X}, we need to analyze how each term behaves under differentiation when the matrix $\bm{X}+t\bm{Y}$ appears implicitly in the spectral data ($\lambda_{k_d}$, $\bm{P}_{k_d,i_d}$, and $\bm{N}_{k_d,i_d}$). 

Differentiating $\mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,P}}(t)$ with respect to $t$, the only $t$-dependence comes from:
%
\begin{itemize}
  \item $\lambda_{k_d}(t)$,
  \item $\bm{P}_{k_d,i_d}(t)$,
  \item $\bm{N}_{k_d,i_d}^{q_d}(t)$.
\end{itemize}

Then, the $n$-th derivative becomes:
%
\begin{eqnarray}
\lefteqn{\frac{d^n}{dt^n}\mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,P}}(t)\bigg|_{t=0}}\nonumber \\
&=& \sum_{\substack{k_c, i_c,q_c,k_d,i_d,q_d\\ k_{1},i_{1}}}
\left.\frac{\partial^n}{\partial t^n}
\left[
\beta^{[2]}(\lambda_{k_c},\lambda_{k_d}(t),\lambda_{k_1})
\cdot 
\bm{P}_{k_c,i_c}(\bm{N}_{k_c,i_c}^{q_c} - \bm{N}_{k_d,i_d}^{q_d}(t))\bm{P}_{k_d,i_d}(t)\bm{Y}\bm{P}_{k_1,i_1}
\right]\right|_{t=0}
\end{eqnarray}
%

Since $\lambda_{k_c}, \lambda_{k_1}$ are independent of $t$, by applying multivariate Faà di Bruno formula for $\beta^{[2]}$, we have
%
\[
\frac{\partial^n}{\partial t^n}\beta^{[2]}(\lambda_{k_c},\lambda_{k_d}(t),\lambda_{k_1}) = \sum_{\pi \in \mathcal{P}(n)}
\frac{n!}{\prod_{j=1}^n b_j! \cdot j!^{b_j}}
\cdot \partial_{\lambda_{k_d}}^{|\pi|} \beta^{[2]}(\lambda_{k_c}, \lambda_{k_d}(t), \lambda_{k_1})
\cdot \prod_{j=1}^n \left( \lambda_{k_d}^{(j)}(t) \right)^{b_j},
\]
%
where $\mathcal{P}(n)$ denote the set of all integer partitions $\pi = (b_1, b_2, \dots, b_m)$ such that $\sum_{j=1}^n j \cdot b_j = n$. 


Similarly,  by applying chain rule of derivative to projectors and nilpotents, we also have
%
\[
\frac{d^n}{dt^n} \left[
(\bm{N}_{k_c,i_c}^{q_c} - \bm{N}_{k_d,i_d}^{q_d}(t)) \cdot \bm{P}_{k_d,i_d}(t)
\right]
= \sum_{j=0}^n \binom{n}{j} 
\left( - \frac{d^j}{dt^j} \bm{N}_{k_d,i_d}^{q_d}(t) \right) 
\cdot \frac{d^{n-j}}{dt^{n-j}} \bm{P}_{k_d,i_d}(t).
\]
%
By defining 
%
\[
\bm{N}_{k_d,i_d}^{q_d,(j)} \define \left. \frac{d^j}{dt^j} \bm{N}_{k_d,i_d}^{q_d}(t) \right|_{t=0}, \quad
\bm{P}_{k_d,i_d}^{(n-j)} \define  \left.\frac{d^{n-j}}{dt^{n-j}} \bm{P}_{k_d,i_d}(t) \right|_{t=0},
\]
finally, we have
%
\begin{eqnarray}
\frac{d^n}{dt^n}\mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,P}}(t)\bigg|_{t=0}
&=&
\sum_{\substack{k_c, i_c, q_c, k_d, i_d, q_d \\ k_1, i_1}}
\sum_{\substack{m + \ell = n}}
\sum_{\pi \in \mathcal{P}(m)}
\frac{1}{\ell!}
\cdot \frac{m!}{\prod_{j=1}^m b_j! j!^{b_j}} \nonumber \\
&& \cdot \left(\partial_{\lambda_{k_d}}^{|\pi|} \beta^{[2]}\right)(\lambda_{k_c}, \lambda_{k_d}, \lambda_{k_1})
\cdot \prod_{j=1}^m \left( \lambda_{k_d}^{(j)} \right)^{b_j} \nonumber \\
&& \cdot \bm{P}_{k_c,i_c}
\cdot \left[
\sum_{j=0}^{\ell} \binom{\ell}{j}
\left( - \bm{N}_{k_d,i_d}^{q_d,(j)} \right)
\cdot \bm{P}_{k_d,i_d}^{(\ell - j)}
\right]
\cdot \bm{Y}
\cdot \bm{P}_{k_1,i_1},
\end{eqnarray}
%
where $\lambda_{k_d}^{(j)} := \left. \frac{d^j}{dt^j} \lambda_{k_d}(t) \right|_{t=0}$. 

This formula computes how the generalized interpolation kernel operator $\mathfrak{X}$ changes under perturbations of the form $\bm{X} + t\bm{Y}$, taking into account the full Jordan structure and the role of divided differences in the operator function calculus.

\textbf{The evaluation of $\frac{d^n}{dt^n}  \mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,N}}$}

Since we have
%
\begin{eqnarray}\label{e3-2:exp: higher order derivative of mathfrak X}
\lefteqn{ \mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,N}} = }\nonumber \\
&&\sum\limits_{\substack{k_c, i_c,q_c,k_d,i_d,q_d,\\ k_{1},i_{1},q_1}}\frac{(\beta^{[2]}(\lambda_{k_c},\lambda_{k_d},\lambda_{k_1}))^{([0,0,q_1])}}{ ([0!,0!,q_1!])} \times \bm{P}_{k_c,i_c}(\bm{N}_{k_c,i_c}^{q_c}-\bm{N}_{k_d,i_d}^{q_d})\bm{P}_{k_d,i_d}\bm{Y}\bm{N}_{k_{1},i_{1}}^{q_1},
\end{eqnarray}
%
to derive the $n$-th derivative of the operator-valued expression

\[
\mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,N}},
\]
%
with respect to $t$ based on Eq.~\eqref{e3-2:exp: higher order derivative of mathfrak X}, we must again analyze the impact of differentiating the terms where $\bm{X} + t\bm{Y}$ enters implicitly via the spectral data: $\lambda_{k_d}(t)$, $\bm{P}_{k_d,i_d}(t)$, and $\bm{N}_{k_d,i_d}(t)$. Finally, we have
%
\begin{eqnarray}
\frac{d^n}{dt^n} \mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,N}}(t)\Big|_{t=0}
&= &\sum_{\substack{k_c, i_c,q_c,k_d,i_d,q_d,\\ k_{1},i_{1},q_1}}
\sum_{\substack{m + \ell = n}} 
\sum_{\pi \in \mathcal{P}(m)} 
\frac{1}{q_1! \cdot \ell!} 
\cdot \frac{m!}{\prod_{j=1}^m b_j! \cdot j!^{b_j}} \nonumber \\
&& \cdot \left(\partial_{\lambda_{k_d}}^{|\pi|} (\beta^{[2]})^{([0,0,q_1])}\right)(\lambda_{k_c}, \lambda_{k_d}, \lambda_{k_1})
\cdot \prod_{j=1}^m \left( \lambda_{k_d}^{(j)} \right)^{b_j} \nonumber \\
&& \cdot \bm{P}_{k_c,i_c}
\cdot \left[
\sum_{j=0}^{\ell} \binom{\ell}{j}
\left( - \bm{N}_{k_d,i_d}^{q_d,(j)} \right)
\cdot \bm{P}_{k_d,i_d}^{(\ell - j)}
\right]
\cdot \bm{Y}
\cdot \bm{N}_{k_1,i_1}^{q_1}.
\end{eqnarray}

\textbf{The Evaluation of $\frac{d^n}{dt^n} \mathfrak{X}^{\bm{C}_N,\bm{D}_N,\bm{X}_{1,P}}$}

Since we have
%
\begin{eqnarray}\label{e3-3:exp: higher order derivative of mathfrak X}
\lefteqn{ \mathfrak{X}^{\bm{C}_N,\bm{D}_N,\bm{X}_{1,P}} = }\nonumber \\
&&\sum\limits_{\substack{k_c, i_c,q_c,k_d,i_d,q_d,\\ k_{1},i_{1}}}\frac{(\beta^{[2]}(\lambda_{k_c},\lambda_{k_d},\lambda_{k_1}))^{([0,q_d,0])}}{ ([0!,q_d!,0!])} \times \bm{P}_{k_c,i_c}(\bm{N}_{k_c,i_c}^{q_c}-\bm{N}_{k_d,i_d}^{q_d})\bm{N}_{k_d,i_d}^{q_d}\bm{Y}\bm{P}_{k_{1},i_{1}}\nonumber \\
&+&\sum\limits_{\substack{k_c, i_c,q_c,k_d,i_d,q_d,\\ k_{1},i_{1}}}\frac{(\beta^{[2]}(\lambda_{k_c},\lambda_{k_d},\lambda_{k_1}))^{([q_c,0,0])}}{ ([q_c!,0!,0!])} \times \bm{N}_{k_c,i_c}^{q_c}(\bm{N}_{k_c,i_c}^{q_c}-\bm{N}_{k_d,i_d}^{q_d})\bm{P}_{k_d,i_d}\bm{Y}\bm{P}_{k_{1},i_{1}}\nonumber \\
&+&\sum\limits_{\substack{k_c, i_c,k_d,i_d,q_d,\\ k_{1},i_{1}}}\frac{(\beta^{[1]}(\lambda_{k_c},\lambda_{k_1}))^{([q_d,0])}}{ ([q_d!,0!])} \times \bm{P}_{k_c,i_c}\bm{N}_{k_d,i_d}^{q_d}\bm{Y}\bm{P}_{k_{1},i_{1}}\nonumber \\
&-&\sum\limits_{\substack{k_c, i_c,q_c,k_d,i_d,\\ k_{1},i_{1}}}\frac{(\beta^{[1]}(\lambda_{k_d},\lambda_{k_1}))^{([q_c,0])}}{ ([q_c!,0!])} \times \bm{N}_{k_c,i_c}^{q_c}\bm{P}_{k_d,i_d}\bm{Y}\bm{P}_{k_{1},i_{1}},
\end{eqnarray}
%
to derive the $n$-th derivative of the operator-valued expression
%
\[
\mathfrak{X}^{\bm{C}_N,\bm{D}_N,\bm{X}_{1,P}}(t),
\]
%
with respect to \( t \), based on Eq.~\eqref{e3-3:exp: higher order derivative of mathfrak X}, we have to analyze the impact of differentiating terms where \( \bm{X} + t\bm{Y} \) enters implicitly via the spectral data: \( \lambda_{k_d}(t) \), \( \bm{P}_{k_d,i_d}(t) \), and \( \bm{N}_{k_d,i_d}(t) \).

By applying same techniques, Faà di Bruno formula and the chain rule of derivatives, as the evaluation of $\frac{d^n}{dt^n} \mathfrak{X}^{\bm{C}_P,\bm{D}_P,\bm{X}_{1,P}}$, we have the final $n$-th derivative results:
%
\begin{eqnarray}
\frac{d^n}{dt^n} \mathfrak{X}^{\bm{C}_N,\bm{D}_N,\bm{X}_{1,P}}(t)\Big|_{t=0}
&=& 
\sum_{\substack{k_c, i_c,q_c,k_d,i_d,q_d,\\ k_{1},i_{1}}}
\sum_{\substack{m + j_1 + j_2 = n}} 
\sum_{\pi \in \mathcal{P}(m)} 
\frac{1}{q_d!} \cdot 
\frac{m!}{\prod_{j=1}^m b_j! j!^{b_j}} 
\cdot \frac{1}{j_1! j_2!} \nonumber \\
&&\cdot \left( \partial_{\lambda_{k_d}}^{|\pi|} (\beta^{[2]})^{([0,q_d,0])} \right)(\lambda_{k_c}, \lambda_{k_d}, \lambda_{k_1})
\cdot \prod_{j=1}^m \left( \lambda_{k_d}^{(j)} \right)^{b_j} \nonumber \\
&&\cdot \bm{P}_{k_c,i_c}
\cdot \left( - \bm{N}_{k_d,i_d}^{q_d,(j_1)} \right)
\cdot \bm{N}_{k_d,i_d}^{q_d,(j_2)}
\cdot \bm{Y}
\cdot \bm{P}_{k_1,i_1} \nonumber \\
%
&+& 
\sum_{\substack{k_c, i_c,q_c,k_d,i_d,q_d,\\ k_{1},i_{1}}}
\sum_{\substack{m + j_1 + j_2 = n}} 
\sum_{\pi \in \mathcal{P}(m)} 
\frac{1}{q_c!} \cdot 
\frac{m!}{\prod_{j=1}^m b_j! j!^{b_j}} 
\cdot \frac{1}{j_1! j_2!} \nonumber \\
&&\cdot \left( \partial_{\lambda_{k_d}}^{|\pi|} (\beta^{[2]})^{([q_c,0,0])} \right)(\lambda_{k_c}, \lambda_{k_d}, \lambda_{k_1})
\cdot \prod_{j=1}^m \left( \lambda_{k_d}^{(j)} \right)^{b_j} \nonumber \\
&&\cdot \bm{N}_{k_c,i_c}^{q_c}
\cdot \left( - \bm{N}_{k_d,i_d}^{q_d,(j_1)} \right)
\cdot \bm{P}_{k_d,i_d}^{(j_2)}
\cdot \bm{Y}
\cdot \bm{P}_{k_1,i_1} \nonumber \\
%
&+& 
\sum_{\substack{k_c, i_c, k_d, i_d, q_d,\\ k_1, i_1}}
\frac{(\beta^{[1]}(\lambda_{k_c}, \lambda_{k_1}))^{([q_d, 0])}}{q_d!}
\cdot \bm{P}_{k_c,i_c}
\cdot \bm{N}_{k_d,i_d}^{q_d,(n)}
\cdot \bm{Y}
\cdot \bm{P}_{k_1,i_1} \nonumber \\
%
&-& 
\sum_{\substack{k_c, i_c,q_c,k_d,i_d,\\ k_{1},i_{1}}}
\sum_{\substack{m + j_1 = n}} 
\sum_{\pi \in \mathcal{P}(m)} 
\frac{1}{q_c!} \cdot 
\frac{m!}{\prod_{j=1}^m b_j! j!^{b_j}} 
\cdot \frac{1}{j_1!} \nonumber \\
&&\cdot \left( \partial_{\lambda_{k_d}}^{|\pi|} (\beta^{[1]})^{([q_c,0])} \right)(\lambda_{k_d}, \lambda_{k_1})
\cdot \prod_{j=1}^m \left( \lambda_{k_d}^{(j)} \right)^{b_j} \nonumber \\
&&\cdot \bm{N}_{k_c,i_c}^{q_c}
\cdot \bm{P}_{k_d,i_d}^{(j_1)}
\cdot \bm{Y}
\cdot \bm{P}_{k_1,i_1}.
\end{eqnarray}


