\subsection{From PrEDS to particle dynamics}

We first explicitly write out the components of each vector in  eq.~\eqref{eq:PrEDS_dynamics}, which reads
\begin{equation}
    \frac{d \vec{X}_{i,\beta}}{dt} = \sum_{\theta=1}^{N} \frac{1}{N} f_i(X_{1,\theta},X_{2,\theta} ... X_{m,\theta}) - \alpha \sum_{\theta=1}^{N} (\delta_{\beta \theta} - \frac{1}{N}) X_{i,\theta}
\end{equation}
where $X_{i,\beta}$ is the $\beta$-th component of vector $\vec{X}_{i}$, we substitute the definition of particle position $\vec{r}_{\beta} = [X_{1,\beta},X_{2,\beta},...X_{m,\beta}]^T $ and get
\begin{align}
    \frac{d \vec{r}_{\beta,i}}{dt} &= \sum_{\theta=1}^{N} \frac{1}{N} f_i(\vec{r}_\beta) - \alpha\left(r_{\beta,i} -\frac{1}{N} \sum_\theta r_{\theta,i}\right) \\
    &= \frac{1}{N} \sum_{\theta=1}^{N}  f_i(\vec{r}_\beta) - \frac{\alpha}{N} \sum_\theta (r_{\beta,i}  - r_{\theta,i})
\end{align}
where $r_{\beta,i}$ is the i-th component of the position for particle number $\beta$, $\vec{r}_{\beta}$. By using $\vec{f}(\vec{r}_\beta) = -\nabla_{\vec{r}_\beta} V(\vec{r}_\beta)$ and $\vec{r}_\beta - \vec{r}_\theta = - \nabla_{\vec{r}_\beta} (|\vec{r}_\beta - \vec{r}_\theta|^2)$, we obtain eq.~\eqref{eq:PrEDS_particle_dynamics} in the main text.
\subsection{Coarse-grained continuum equation}
We first use the chain rule to calculate the time derivative,
\begin{align}
    \frac{d}{dt}f(\Vec{r}_\beta(t)) 
    &= \nabla_{\vec{r}_\beta} f(\Vec{r}_\beta(t))  \cdot \frac{d \Vec{r}_\beta(t) }{dt} 
    = \int d\vec{r} \ \delta(\vec{r} - \vec{r}_\beta) \nabla_{\vec{r}}f(\vec{r}) \cdot \frac{d \Vec{r}_\beta(t) }{dt}\\
    &= -\int d \vec{r} \ \rho_\beta (\Vec{r},t) \nabla_{\vec{r}} f(\vec{r}) \cdot \left(\frac{1}{N} \sum_{\theta}  \nabla_{\theta} V(\vec{r}_\theta) + \frac{\alpha}{N}\sum_{\theta} \nabla_{\vec{r}} U_H(\vec{r} - \vec{r}_{\theta})\right).
\end{align}
We then perform integration by parts to finally get eq.~\eqref{eq:dt_f}. 
After summing over the particle number, $\beta$, in eq.~\eqref{eq:dt_f}, we obtain the form
\begin{align}
    \partial_t \rho(\Vec{r},t)
    &=\nabla_{\vec{r}}  \cdot \left[\rho (\Vec{r},t)\left(\frac{1}{N} \sum_{\theta}  \nabla_{\vec{r}_\theta} V(\vec{r}_\theta) + \frac{\alpha}{N}\sum_{\theta} \nabla_{\vec{r}} U_H(\vec{r} - \vec{r}_{\theta})\right)\right] .
\end{align}
Using the properties of delta functions, we rewrite this equation as
\begin{align}
