    &= \nabla_{\vec{r}}  \cdot \left[ \rho (\Vec{r},t)\left( \frac{1}{N}  \int d\vec{y}\  \nabla_{\Vec{y}}  V(\vec{y}) \rho(\vec{y},t) + \frac{\alpha}{N} \nabla_{\vec{r}} \int d\vec{y} \  U_H(\vec{r} - \vec{y}) \rho (\vec{y},t)\right) \right]
\end{align}     






