\section{Perturbative solution of the replicated Schr\"odinger equation}
\label{sec:a}
Let us now address the question of a randomly measured particle with the replica approach which allows to compute products of quantum mechanical averages, subsequently averaged over measurements.  We would like to solve the equations \rf{eq:schr3} and \rf{eq:schr4}. Here we present their perturbative solution for $\lambda$ small. 
\subsection{Higher order correlators: replicas}
We begin by writing down again the equation we would like to solve. Here and below we change notations from $x_{\alpha}^\sigma$ to $x_{\alpha, \sigma}$. 
\begin{eqnarray} \label{eq:eqw} i \frac{\d \rho}{d t} + \frac{1}{2m} \sum_{\alpha=1}^n \left( \frac{\d^2\rho}{\d x_{\alpha,+}^2} -  \frac{\d^2\rho}{\d x_{\alpha,-}^2} \right) = && \cr
 i \frac{\lambda}{2} \sum_{\alpha=1}^n \sum_{\beta=1}^n \sum_{\sigma,\sigma'=\pm}
W \left( x_{\alpha, \sigma} - x_{\beta, \sigma'} \right) \rho. &&
\end{eqnarray}
This needs to be solved with the initial condition, set at $t=0$,
\be \rho(0) = \frac{1}{\left( 2 \pi \Delta^2\right)^{n/2}  }  \exp \left\{ - \frac m 2 \sum_{\alpha=1}^n \left( \frac{x_{\alpha,+}^2}{2 \Delta^2 m } +  \frac{x_{\alpha,-}^2}{2 \Delta^2 m }   
\right)    \right\}. 
\ee
This choice of the function $W(x)$ simplifies the calculations,
\be W(x) = \frac{1}{\sqrt{2 \pi} \ell} e^{-\frac{x^2}{2 \ell^2}}.
\ee
If $\lambda=0$, then the following function solves this equation
%\be \rho_0 = \frac{1}{\left( 2 \pi \Delta^2+ \frac{\pi t^2}{2 \Delta^2 m^2} \right)^{n/2}  }  \exp \left( -  \frac{m \sum_{\alpha=1}^n \left( \left( 2 \Delta^2 m - i t \right)  x_{\alpha,+}^2 + \left( 2 \Delta^2 m + i t \right) x_{\alpha,-}^2 \right)  }{2 \left( 4 \Delta^4 m^2 + t^2 \right)} \right). 
%\ee
\begin{eqnarray} \rho_0 = \frac{1}{\left( 2 \pi \Delta^2+ \frac{\pi t^2}{2 \Delta^2 m^2} \right)^{n/2}  } \times && \cr \exp \left\{ - \frac m 2 \sum_{\alpha=1}^n \left( \frac{x_{\alpha,+}^2}{2 \Delta^2 m + i t} +  \frac{x_{\alpha,-}^2}{2 \Delta^2 m - i t}   
\right)    \right\}. &&
\end{eqnarray}
We write $\rho\approx \rho_0 + \rho_1$, where $\rho_1$ satisfies
\begin{eqnarray} i \frac{\d \rho_1}{\d t} +\frac{1}{2m} \sum_{\alpha=1}^n \left( \frac{\d^2\rho_1}{\d x_{\alpha,+}^2} -  \frac{\d^2\rho_1}{\d x_{\alpha,-}^2} \right) = 
&& \cr
\frac{i \lambda}{2} \sum_{\alpha=1}^n \sum_{\beta=1}^n \sum_{\sigma,\sigma'=\pm}
W \left( x_{\alpha, \sigma} - x_{\beta, \sigma'} \right) \rho_0.&&
\end{eqnarray}
At $t=0$, $\rho_1=0$. 
To solve this we Fourier transform both sides. We arrive at
\be i \frac{\d \rho_1}{\d t} - \frac{1}{2m} \sum_{\alpha=1}^n \left( k_{\alpha,+}^2 - k_{\alpha_-}^2 \right) \rho_1 = \frac{i \lambda}{2} X(t).
\ee Here $X(t)$ will be determined below.
We solve this by writing
\be \rho_1 = C(t) \exp \left\{ {-i t \sum_{\alpha=1}^n \frac{k_{\alpha,+}^2-k_{\alpha,-}^2}{2m}} \right\}.
\ee
Here
\be C(t) = \frac{\lambda}{2} \int_0^t d\tau \, X(\tau) \exp \left\{ {i \tau \sum_{\alpha=1}^n \frac{k_{\alpha,+}^2-k_{\alpha,-}^2}{2m}} \right\},
\ee
thus
\begin{eqnarray} \label{eq:rho1} \rho_1 =\frac{ \lambda }{2}  \exp \left\{ {-i t \sum_{\alpha=1}^n \frac{k_{\alpha,+}^2-k_{\alpha,-}^2}{2m}} \right\} \times && \cr
\int_0^t d\tau \, X(\tau) \exp \left\{ {i \tau \sum_{\alpha=1}^n \frac{k_{\alpha,+}^2-k_{\alpha,-}^2}{2m}} \right\}. &&
\end{eqnarray}
Let us figure out $X$. It is given by the sum of the terms $X_{\alpha,\beta}^{\sigma,\sigma'}$ defined by
\begin{eqnarray}  X_{\alpha,\beta}^{\sigma,\sigma'} = \int dx_1 \dots dx_n \, \rho_0 \, W\left(x_{\alpha,\sigma}-x_{\beta,\sigma'} \right) \times && \cr
e^{-i \sum_{\alpha=1}^n \left( x_{\alpha,+} k _{\alpha,+} + x_{\alpha, -} k_{\alpha,-} \right) } .&&
\end{eqnarray}
Substituting and carrying out Gaussian integration, we find terms of three types. 
\begin{widetext}
\be X^{+-}_{\alpha,\beta}= \frac{\left( 8 \pi \Delta^2 \right)^{n/2}}{\sqrt{2 \pi} \sqrt{\ell^2+ 4 \Delta^2}} \exp \left\{-\frac{ \left( k_{\alpha,+} + k_{\beta,-} \right)^2 \left( \tau^2  + 4 m^2 \Delta^4  \right) +
2 m^2 \Delta^2 \ell^2 \left(k_{\alpha,+}^2+k_{\beta,-}^2\right)+
i m \ell^2 \tau \left(k_{\alpha,+}^2-k_{\beta,-}^2\right)  }{2 m^2 \left( 4 \Delta^2 +\ell^2 \right)}
\right\}  \times
\ee
$$ \prod_{\substack{ \gamma\not = \alpha \\ \delta \not = \beta} } \exp \left\{ - \frac{k_{\gamma,+}^2 \left( 2 m \Delta^2 + i \tau \right) + k_{\delta, -}^2 \left( 2 m \Delta^2 - i \tau \right)}{2 m} \right\},
$$
\be X^{++}_{\alpha, \beta} =\frac{\left(8 \pi \Delta^2 \right)^{n/2}}{ \sqrt{2 \pi} \sqrt{\ell^2+\frac{2 i \tau}{m}+4  \Delta^2  }}
\exp\left\{  -\frac{(k_{\alpha,+} + k_{\beta,+})^2 \left( 2 m \Delta^2 + i \tau \right)^2 + m \ell^2\left(2 m \Delta^2 + i \tau \right) (k_{\alpha,+}^2+k_{\beta,+}^2) }{2m (2 i\tau + m (4 \Delta^2 + \ell^2 ))}
\right\} \times 
\ee 
$$\prod_{\substack{ \gamma\not = \alpha \\ \gamma \not = \beta} } \exp \left\{ - \frac{k_{\gamma,+}^2 \left( 2 m \Delta^2 + i \tau \right) }{2 m} \right\}
\prod_\gamma \exp \left\{ - \frac{k_{\gamma,-}^2 \left( 2 m \Delta^2 - i \tau \right) }{2 m} \right\},
$$
\be X^{--}_{\alpha, \beta} =\frac{\left(8 \pi \Delta^2 \right)^{n/2}}{ \sqrt{2\pi} \sqrt{\ell^2-\frac{2 i \tau}{m}+4  \Delta^2  }}
\exp\left\{  -\frac{(k_{\alpha,-} + k_{\beta,-})^2 \left( 2 m \Delta^2 - i \tau \right)^2 + m \ell^2\left(2 m \Delta^2 - i \tau \right) (k_{\alpha,-}^2+k_{\beta,-}^2) }{2m (-2 i\tau + m (4 \Delta^2 + \ell^2 ))}
\right\} \times 
\ee 
$$\prod_{\substack{ \gamma\not = \alpha \\ \gamma \not = \beta} } \exp \left\{ - \frac{k_{\gamma,-}^2 \left( 2 m \Delta^2 - i \tau \right) }{2 m} \right\}
\prod_\gamma \exp \left\{ - \frac{k_{\gamma,+}^2 \left( 2 m \Delta^2 + i \tau \right) }{2 m} \right\}.
$$
Now for the purpose of calculating $\rho_1$, we need to conjugate $X$ with the appropriate factors, as in \rf{eq:rho1}. Defining
\be Y =   \exp \left\{ {-i t \sum_{\alpha=1}^n \frac{k_{\alpha,+}^2-k_{\alpha,-}^2}{2m}} \right\}X(\tau) \exp \left\{ {i \tau \sum_{\alpha=1}^n \frac{k_{\alpha,+}^2-k_{\alpha,-}^2}{2m}} \right\}
\ee
we find
\be Y^{+-}_{\alpha,\beta}  = \frac{\left( 8 \pi \Delta^2 \right)^{n/2}}{\sqrt{2 \pi} \sqrt{\ell^2+ 4 \Delta^2}} \exp \left\{-\frac{ \left( k_{\alpha,+} + k_{\beta,-} \right)^2 \left( \tau^2  + 4 m^2 \Delta^4  \right) +
2 m^2 \Delta^2 \ell^2 \left(k_{\alpha,+}^2+k_{\beta,-}^2\right)  }{2 m^2 \left( 4 \Delta^2 +\ell^2 \right)}
\right\}  \times
\ee
$$ \exp \left\{ \left( \frac{2 i \Delta^2 \tau}{4 m \Delta^2 + m \ell^2} - \frac{i t}{2m} \right) \left(k_{\alpha,+}^2- k_{\beta,-}^2 \right) \right\} \times \prod_{\substack{ \gamma\not = \alpha \\ \delta \not = \beta} } \exp \left\{ - \frac{k_{\gamma,+}^2 \left( 2 m \Delta^2 + i t \right) + k_{\delta, -}^2 \left( 2 m \Delta^2 - i t \right)}{2 m} \right\},
$$
\be Y^{++}_{\alpha, \beta} =\frac{\left(8 \pi \Delta^2 \right)^{n/2}}{ \sqrt{2 \pi} \sqrt{\ell^2+\frac{2 i \tau}{m}+4  \Delta^2  }}
\exp\left\{  -\frac{ \left(4 m^2 \Delta^4+\tau^2 + 2 m^2 \ell^2 \Delta^2 \right)(k_{\alpha,+}^2+k_{\beta,+}^2) + 2 k_{\alpha,+} k_{\beta,+} \left( 2 m \Delta^2 + i \tau \right)^2}{2m (2 i\tau + m (4 \Delta^2 + \ell^2 ))}
\right\} \times 
\ee 
$$\exp \left\{ -i t \frac{k_{\alpha,+}^2 + k_{\beta,+}^2}{2m} \right\} \prod_{\substack{ \gamma\not = \alpha \\ \gamma \not = \beta} } \exp \left\{ - \frac{k_{\gamma,+}^2 \left( 2 m \Delta^2 + i t \right) }{2 m} \right\}
\prod_\gamma \exp \left\{ - \frac{k_{\gamma,-}^2 \left( 2 m \Delta^2 - i t \right) }{2 m} \right\},
$$
\be Y^{--}_{\alpha, \beta} =\frac{\left(8 \pi \Delta^2 \right)^{n/2}}{ \sqrt{2 \pi} \sqrt{\ell^2-\frac{2 i \tau}{m}+4  \Delta^2  }}
\exp\left\{  -\frac{ \left(4 m^2 \Delta^4+\tau^2 + 2 m^2 \ell^2 \Delta^2 \right)(k_{\alpha,-}^2+k_{\beta,-}^2) + 2 k_{\alpha,-} k_{\beta,-} \left( 2 m \Delta^2 - i \tau \right)^2}{2m (-2 i\tau + m (4 \Delta^2 + \ell^2 ))}
\right\} \times 
\ee 
$$\exp \left\{ i t \frac{k_{\alpha,-}^2 + k_{\beta,-}^2}{2m} \right\} \prod_{\substack{ \gamma\not = \alpha \\ \gamma \not = \beta} } \exp \left\{ - \frac{k_{\gamma,-}^2 \left( 2 m \Delta^2 - i t \right) }{2 m} \right\}
\prod_\gamma \exp \left\{ - \frac{k_{\gamma,+}^2 \left( 2 m \Delta^2 + i t \right) }{2 m} \right\}.
$$
\end{widetext}
In terms of these, the correction to the density matrix reads
\begin{eqnarray} \rho_1 &=&
\lambda \left[ \int_0^t d\tau \, \sum_{\alpha < \beta} \left( Y^{+-}_{\alpha \beta} + Y^{+-}_{\beta \alpha}  +Y^{++}_{\alpha \beta} + Y^{--}_{\alpha \beta} \right)+ \right.  \cr && \left. \sum_{\alpha} Y^{+-}_{\alpha \alpha} \right]. 
\end{eqnarray}

Now we introduce classical and quantum coordinates,  with symmetric normalization
\be x_{cl} = \frac{x_++x_-}{\sqrt{2}}, \ x_q = \frac{x_+-x_-}{\sqrt{2}}, 
\ee
\be k_{cl} = \frac{k_++k_-}{\sqrt{2}}, \ k_q = \frac{k_+-k_-}{\sqrt{2}} 
\ee
Importantly,
\be x_+ k_+ + x_- k_- = x_{cl} k_{cl}+ x_q k_q, 
\ee
\be k_+ = \frac{k_{cl}+k_q}{\sqrt{2}}, \ k_- = \frac{k_{cl}- k_q }{\sqrt{2}}.
\ee
\subsection{Nomalizing the density matrix}
We would now like to normalize the density matrix. To do that, we set $k_{cl}=0$ and integrate over $k_q/(2 \pi)$. This is equivalent to setting $k_{\alpha,+}=-k_{\alpha,-}=k_\alpha/\sqrt{2}$ and integrating over $k_\alpha/(2\pi)$. After that we still need to normalize by dividing by $2^{n/2}$. 

Let us see that in more detail. Normalizing the density matrix means computing
\be {\cal N} = \int dx \, \rho(x,x).
\ee
The norm of the density matrix is supposed to be $1$, but the solutions of the equation \rf{eq:eqw} is not automatically normalized, so the density matrix inferred from that equation must be normalized by dividing by ${\cal N}$. Technically this is because we have not normalized the probability distribution for $V$ and ignored factors such as $W(0)$ (self interactions among the replicas) which violates the conservation of the norm of $\rho$. Diving by ${\cal N}$ fixes this issue.  
We have defined
\begin{eqnarray} \rho(k_+, k_-) = \int dx_- dx_+ \, \rho(x_+, x_-) e^{-i k_- x_- - i k_+ x_+} =&& \cr
 \int dx_{cl} dx_q \, \rho((x_{cl}+x_q)/\sqrt{2}, (x_{cl}- x_q)/\sqrt{2}) e^{-i k_{cl} x_{cl}- i k_q x_q}. && \cr &&
\end{eqnarray}
Setting $k_{cl}=0$ and integrating over $k_q$ gives
\begin{eqnarray} \int \frac{dx_{cl} dx_q dk_{q}}{2\pi} \, \rho((x_{cl}+x_q)/\sqrt{2}, (x_{cl}- x_q)/\sqrt{2}) \, e^{-i k_q x_q} = && \cr
 \int dx_+ dx_- \, \rho(x_+,x_-) \,\sqrt{2} \delta(x_+-x_-) = \sqrt{2} {\cal N}.  && \cr && 
\end{eqnarray}



Applied to the coefficients $Y$ above, 
with the definition
\be Z = \frac{1}{2^{n/2}} \lim_{k_{cl} \rightarrow 0} \int \prod_{\alpha=1}^n \frac{d k_{\alpha,q}}{(2\pi)^n} Y,
\ee
this procedure gives
\be Z^{+-}_{\alpha, \beta} = \frac{m \Delta}{\sqrt{\pi}} \frac{1}{\sqrt{2 m^2 \Delta^2 ( 2 \Delta^2 + \ell^2) + \tau^2}}, \ \alpha < \beta,
\ee
\be Z^{+-}_{\alpha, \alpha} =  \frac{1}{\sqrt{2 \pi} \ell},
\ee
\be Z^{++}_{\alpha,\beta} = Z^{--}_{\alpha, \beta} = \frac{m \Delta}{\sqrt{\pi}} \frac{1}{\sqrt{2 m^2 \Delta^2 ( 2 \Delta^2 + \ell^2) + \tau^2}}.
\ee
Thus we find
\begin{eqnarray}  {\rm tr} \, \rho_1 & = & 2 n(n-1) \lambda \int_0^t d\tau \frac{m \Delta}{\sqrt{\pi}} \frac{1}{\sqrt{2 m^2 \Delta^2 ( 2 \Delta^2 + \ell^2) + \tau^2}} \cr
&& + \frac{n \lambda t}{\sqrt{2\pi} \ell}.
\end{eqnarray}
\subsection{Computing the relevant correlator}
We would now like to compute the correlator. To do that, we differentiate over $k_{cl,1}$ and $k_{cl,2}$, and then set all $k_{cl}$ to zero. After that we integrate over each $k_q/(2 \pi)$ and multiply by $-1/(2 \cdot 2^{n/2})$. Here is a check that this is the right procedure:
\be \int \frac{dk_q}{(2\pi)}  \left. \frac{\partial }{\partial k_{cl}} \rho \right|_{k_{cl}=0} = 
\ee
$$ \frac{\partial }{\partial k_{cl}}   \int \frac{ dx_+ dx_- dk_q}{2\pi}  \rho(x_+, x_-) e^{-i k_{cl} \frac{x_+ + x_-}{\sqrt{2}} - i k_q \frac{x_+-x_-}{\sqrt{2}} } = $$
$$ - \int dx_+ dx_- \rho(x_+, x_-) \sqrt{2} \delta(x_+ - x_-) \frac{x_+ + x_- }{\sqrt{2}} = 
$$
$$- \int dx \rho(x,x) \sqrt{2} \cdot \sqrt{2} x.
$$
We see a factor of $\sqrt{2}$ per correlator (hence, division by $2$) and a factor of $\sqrt{2}$ per a pair of degrees of freedom, hence division by $2^{n/2}$. 

We see that the only nonzero contribution comes from the terms where $\alpha=1$, $\beta=2$. If this is not so, suppose $\beta=3$. Then the derivative over $k_{3,cl}$ followed by setting it to zero brings down $k_{3,q}$. Integrating over $k_{3,q}$ is then zero as the exponent is symmetric under the change of sign of $k_{3,q}$. 

The exception is the $\alpha=1$, $\beta=2$ terms. To compute $S^{+-}_{12}$ use the following formula
$$ \frac 1 Z \int \frac{dk_{1,q} d k_{2,q}}{(2\pi)^2}  \frac{\d^2} {\d k_{1,cl} \d k_{2,cl}} \exp\left(-\frac 1 2 \left( a k_{1,+}^2 + \right. \right.
$$
$$ \left. \left.   b k_{2,-}^2+2 c k_{1,+} k_{2,-} + d k_{1,-}^2+f k_{2,+}^2 \right) \bigg) \right|_{k_{1,cl}, k_{2,cl}=0}
= $$
\be \label{eq:ans1} \frac{2 c d f}{c^2-(a+d)(b+f)},
\ee
where
$$ Z =  \int \frac{dk_{1,q} d k_{2,q}}{(2\pi)^2} \exp\left(-\frac 1 2 \left( a k_{1,+}^2 +  \right. \right. 
$$ $$ \left.  b k_{2,-}^2+2 c k_{1,+} k_{2,-} +d k_{1,-}^2+f k_{2,+}^2 \right) \bigg).
$$
 We find
 \begin{eqnarray} S^{+-}_{1,2}& =& \frac 1 2 Z^{+-}_{1,2} \frac{\left( t^2+4 m^2 \Delta^4\right) \left( \tau^2+4 m^2 \Delta^4 \right)}{4 m^2 \Delta^2 \left( 2 m^2 \Delta^2 (2 \Delta^2+\ell^2) + \tau^2 \right)}= \cr
&& \frac{\left( t^2+4 m^2 \Delta^4\right) \left( \tau^2+4 m^2 \Delta^4 \right)}{8\sqrt{\pi}  m \Delta \left( 2 m^2 \Delta^2 (2 \Delta^2+\ell^2) + \tau^2 \right)^{3/2}}. 
 \end{eqnarray}
 Now to compute $S^{++}_{1,2}$ we use 
$$  \frac 1 Z \int \frac{dk_{1,q} d k_{2,q}}{(2\pi)^2}  \frac{\d^2} {\d k_{1,cl} \d k_{2,cl}} \exp\left(-\frac 1 2 \left( a k_{1,+}^2 +  \right. \right.
$$
$$ \left. \left.  b k_{2,+}^2+2 c k_{1,+} k_{2,+} + d k_{1,-}^2+f k_{2,-} ^2\right) \bigg) \right|_{k_{1,cl}, k_{2,cl}=0}
= $$
$$ \frac{2 c d f}{c^2-(a+d)(b+f)},
$$
where
$$ Z =  \int \frac{dk_{1,q} d k_{2,q}}{(2\pi)^2} \exp\left(-\frac 1 2 \left( a k_{1,+}^2 +  \right. \right. 
$$
$$ \left. b k_{2,+}^2+2 c k_{1,+} k_{2,+} + d k_{1,-}^2+f k_{2,-}^2 \right) \bigg).
$$
That is, this is explicitly the same expression as \rf{eq:ans1}. 

 This gives
$$  S^{++}_{1,2}= \frac 1 2 Z^{++}_{1,2} \frac{\left( it+2  m \Delta^2 \right)^2 \left( 2m \Delta^2 + i \tau\right)^2}{4 m^2 \Delta^2 \left( 2 m^2 \Delta^2 \left( 2 \Delta^2+\ell^2 \right) + \tau^2 \right)} =
$$
$$
 \frac{\left( it+2  m \Delta^2 \right)^2 \left( 2m \Delta^2 + i \tau\right)^2}{8\sqrt{\pi} m \Delta \left( 2 m^2 \Delta^2 \left( 2 \Delta^2+\ell^2 \right) + \tau^2 \right)^{3/2}} 
 $$ 
 This gives the answer for the quantity we are trying to compute
$$  \overline{ \VEV{x}^2} =   \lambda \int_0^t d\tau \left( 2S^{+-}+S^{++}+{S^*}^{++} \right) = $$
$$\frac{ \lambda }{2} \int_0^t d\tau \frac{ \left(t \tau -4 \Delta ^4 m^2\right)^2}{\sqrt{\pi } \Delta  m \left(2 \Delta ^2
   m^2 \left(2 \Delta ^2+\ell ^2\right)+\tau ^2\right)^{3/2}}.
  $$


 %This gives the final answer for the quantity
 %\be \overline{ \VEV{x}^2} = \frac \lambda 2 \int_0^t d\tau \frac{ \left(t \tau -4 \Delta ^4 m^2\right)^2}{\sqrt{\pi } \Delta  m \left(2 \Delta ^2
  % m^2 \left(2 \Delta ^2+\ell ^2\right)+\tau ^2\right)^{3/2}}.
 %\ee   
 This integral is not very instructive. Let us rescale $\tau = t x$ to find
 \begin{eqnarray} \overline{ \VEV{x}^2} & =&  \frac{ \lambda t^2}{2 \sqrt{\pi } \Delta  m} \int_0^1 dx \frac{ \left(x -\frac{4 \Delta ^4 m^2}{t^2} \right)^2}{ \left(\frac{2 \Delta^2
   m^2 \left(2 \Delta ^2+\ell ^2\right)}{t^2} +x^2\right)^{3/2}} \cr & \approx & \frac{\lambda t^2}{2 \sqrt{\pi} \Delta m} \ln \left( \frac {t\sqrt{2} } {\sqrt{\Delta^2
   m^2 \left(2 \Delta ^2+\ell ^2\right)} } \right).
 \end{eqnarray}
 The last approximate equality works for large $t$.  Units: given that $\lambda$ has units of $\left[ \lambda \right] = {\rm kg}^2 \cdot {\rm m}^5 \cdot {\rm s}^{-3}$, restoring the Planck constant gives
 \be \overline{ \VEV{x}^2} = \frac{\lambda t^2}{2 \sqrt{\pi} \Delta m \hbar} \ln \left( \frac {\hbar t\sqrt{2} } {\sqrt{\Delta^2
   m^2 \left(2 \Delta ^2+\ell ^2\right)} } \right).
   \ee

 Let us now evaluate this at small $t$. We find
 \be \overline{ \VEV{x}^2 } \approx \frac{2 \sqrt{2} \Delta^4 \lambda t}{\hbar^2 \sqrt{\pi} \left( 2 \Delta^2+ \ell^2 \right)^{3/2}}.
 \ee


 \subsection{Now the case of random noise}

 If instead of random measurements we simply have a random potential, then we need to compute
$$   \lambda \int_0^t d\tau \left( 2S^{+-}-S^{++}-{S^*}^{++} \right) =  $$
$$\lambda \int_0^t d \tau \frac{4 \Delta ^3 m (t+\tau )^2}{2 \sqrt{\pi } \left(2 \Delta ^2 m^2 \left(2 \Delta
   ^2+\ell ^2\right)+\tau ^2\right)^{3/2}}.
  $$
       Changing variables in the same way $\tau = t x$, we find
       \begin{eqnarray} \overline{ \VEV{x}^2} & = & \frac{2 \lambda  \Delta^3 m}{\sqrt{\pi} } \int_0^1 dx \frac{(1+x)^2}{ \left( \frac{2 \Delta^2
   m^2 \left(2 \Delta ^2+\ell ^2\right)}{t^2} +x^2\right)^{3/2}}  \cr & \approx & \frac{ \lambda  \Delta }{\hbar \sqrt{\pi} m }  \frac{t^2}{  2 \Delta
   ^2+\ell ^2 }.
   \end{eqnarray}
   The last approximate equality is valid at large $t$, and $\hbar$ in it is again inserted as appropriate. 

   At small $t$ we find
   \be \overline{ \VEV{x}^2} \approx \frac{7  \lambda t^3}{3\sqrt{2 \pi}  m^2 \left(2 \Delta^2 + \ell^2 \right)^{3/2}}.
   \ee
   Here there is no $\hbar$, so the result is classical.


 \subsection{Computing the linear correlator}

For completeness, let's compute the linear correlator $\VEV{x^2}$. The only term that contributes is  $Y^{+-}_{11}$. We differentiate it over $k_{cl,1}$ twice, set $k_{cl,1}$ to zero, and integrate over $k_{q,1}/(2\pi)$, multiplying by a factor of $-1/(2\cdot2^{n/2})$. Other terms will go to zero as $n \rightarrow 1$ for combinatorial reasons, so there are not needed. 

Carrying out this procedure gives
\be  \int_0^t d \tau \,  \lambda \frac{t^2 \left(4
   \Delta ^2+\ell ^2\right) +4 \Delta ^2 \left(\Delta ^2 m^2 \ell ^2+\tau ^2\right)-8 \Delta ^2 \tau  t}{4 \sqrt{2\pi}  \Delta ^2 m^2
   \ell ^3}.
   \ee
Changing variables as always gives
$$ \frac{\lambda t^3}{4 \sqrt{2\pi} \Delta^2 m^2 \ell^3} \int_0^1 dx \, \left( 4
   \Delta ^2+\ell ^2 + 4 \Delta ^2 \left(\frac{\Delta ^2 m^2 \ell ^2}{t^2} +x^2 \right) \right.$$
   $$ -8 \Delta ^2 x \bigg) = \frac{ \Delta^2 \lambda t}{\sqrt{2 \pi} \ell} + \frac{\lambda t^3 \left(4 \Delta^2+3 \ell^2 \right)}{12 m^2 \sqrt{2 \pi} \Delta^2 \ell^3}.
   $$
Finally, the correlator is given by
\begin{eqnarray} \VEV{x^2} & =& \left( \Delta^2 + \frac{t^2}{4 m^2 \Delta^2} \right) \left(1- \frac{ \lambda t}{\sqrt{2\pi} \ell} \right)+\frac{ \Delta^2 \lambda t}{\sqrt{2 \pi} \ell} +
\cr && \frac{\lambda t^3 \left(4 \Delta^2+3 \ell^2 \right)}{12 m^2 \sqrt{2 \pi} \Delta^2 \ell^3} = \frac{\lambda  t^3}{3 \sqrt{2 \pi} m^2 \ell^3}.
\end{eqnarray}
This matches \rf{eq:res}.


