\begin{abstract}
We prove that certain functions involving ratios of Gamma functions and the Psi-function belong to generalized Bernstein classes and new properties of generalized Bernstein functions are given. 
\end{abstract}
\noindent {\em \small 2020 Mathematics Subject Classification: Primary: 44A10. Secondary: 26A48, 33B15, 33C05.}

\noindent {\em \small Keywords:  Ratios of Gamma functions}


\section{Introduction}
The behaviour of ratios of Gamma and related functions has attracted the attention of several authors over the years, see e.g.\ \cite{AP,BK, BKP,ism}. In this paper we investigate properties of the family of functions 
\begin{equation}
    \label{eq:def-mst}
    M_{a,b}(x)=x^{a-b}\frac{\Gamma(x+b)}{\Gamma(x+a)}, \;\; x>0,
\end{equation}
for positive parameters $a$ and $b$. 
This family was studied in \cite{KL}. 
We shall, in particular, relate these functions to classes of higher order Thorin-Bernstein functions and classes of generalized Stieltjes functions of positive order. We generalize results for the function $g_{\lambda}(x)=x^{\lambda}\Gamma(x)/\Gamma(x+\lambda)=M_{\lambda,1}(x)$, investigated in connection with sharp inequalities involving the incomplete Beta and Gamma functions, see \cite{KP5}.

Because of the symmetry $M_{a,b}=1/M_{b,a}$ we shall assume that
$0<b<a$
throughout the paper.

For the reader's convenience we give some fundamental definitions. A function $f:(0,\infty)\to \mathbb R$ is called completely monotonic if $f$ is infinitely often differentiable and $(-1)^nf^{(n)}(x)\geq 0$ for $n=0,1,\ldots$ and $x>0$. A $C^{\infty}$-function $f:(0,\infty)\to (0,\infty)$ belongs to the class $\bl$ of generalized Bernstein functions of order $\lambda>0$ if $x^{1-\lambda}f'(x)$ is completely monotonic. This class was investigated in \cite{KP1} where it was shown that $f$ belongs to $\mathcal B_{\lambda}$ if and only if it admits a representation 
\begin{equation}
\label{eq:bl}
f(x)=ax^{\lambda}+b+\int_0^{\infty}\gamma(\lambda,xt)\, \frac{d\mu(t)}{t^{\lambda}},
\end{equation}
where $a,b\geq 0$ and $\mu$ is a positive measure on $[0,\infty)$ making the integral converge. Here $\gamma$ denotes the incomplete Gamma function 
$$
\gamma(\lambda,x)=\int_0^{x}t^{\lambda-1}e^{-t}\, dt.
$$
Notice also that $\mu$ in \eqref{eq:bl} is the restriction to $(0,\infty)$ of the measure $\tilde{\mu}$ given in Bernstein's representation of the completely monotonic function $f'(x)x^{1-\lambda}$, i.e.\ by $\mathcal L(\tilde{\mu})(x)=f'(x)x^{1-\lambda}$, where $\mathcal L$ denotes the Laplace transform.

We remark that when $\lambda=1$ the class of functions, denoted by $\mathcal{B}$, is the so-called Bernstein functions appearing in probability theory. See \cite{S}. 

The class $\mathcal T_{\lambda,\alpha}$ (where $\lambda>0$ and $\alpha<\lambda+1$) of higher order Thorin-Bernstein functions is the subclass of $\mathcal B_{\lambda}$ defined as follows: $f\in \mathcal T_{\lambda,\alpha}$ if 
$$
f(x)=ax^{\lambda}+b+\int_0^{\infty}\gamma(\lambda,xt)\varphi(t)\, dt,
$$
where $\varphi$ is a completely monotonic function of order $\alpha$ (meaning that $t^{\alpha}\varphi(t)$ is completely monotonic) such that the integral converges.

A function $g:(0,\infty)\to \mathbb R$ belongs to the class $\mathcal S_{\lambda}$ of generalized Stieltjes functions of order $\lambda>0$ if 
$$
g(x)=\int_0^{\infty}\frac{d\mu(t)}{(x+t)^{\lambda}}+c
$$
for some positive measure $\mu$ on $[0,\infty)$ and some $c\geq 0$. An equivalent formulation is that $g$ admits the representation
\begin{equation}
\label{eq:alt-stieltjes}
g(x)=\int_0^{\infty}e^{-xt}t^{\lambda-1}\varphi(t)\, dt+c,
\end{equation}
where $\varphi$ is completely monotonic. Let us also mention that products of generalized Stieltjes functions are again generalized Stieltjes functions in the sense that 
$$
\mathcal S_{\lambda_1}\mathcal S_{\lambda_2}\subset \mathcal S_{\lambda_1+\lambda_2},
$$
see \cite{HW}.


There is a close relation between the higher order Thorin-Bernstein functions and the generalized Stieltjes functions of positive order. Indeed, according to  \cite[Theorem 2.14]{KP4} we have
 $$ f\in \tla \ \Leftrightarrow \ x^{1-\lambda}f'(x)\in \mathcal S_{\lambda+1-\alpha}.
 $$


 We give conditions on the parameters $a$ and $b$ so that the function $M_{a,b}$ belongs to $\mathcal T_{a-b,-3}$ and in addition, the function $L_{a,b}(x)=x(1-M_{a,b}(x))$ is shown to be a generalized Bernstein function of order $a-b$ for $a-b>1$. In the final section we present new properties on generalized Bernstein functions.

\section{Preliminary results}
Our results are based on integral representations of $\log M_{a,b}$ and its derivative in terms of the function function $\Phi_{a,b}$ defined as
$$
\Phi_{a,b}(t)=(b-a)+\frac{e^{-bt}-e^{-at}}{1-e^{-t}}.
$$
We begin by giving representations of $\Phi_{a,b}$ and its derivative. 

The point mass at the point $c$ is denoted  by $\epsilon_c$ and the indicator function of a set $A$ by $1_A$. With this notation we may now state and prove the first lemma.

\begin{lemma}
\label{lemma:Phi} The representation
\begin{align*}
    -\frac{\Phi_{a,b}(t)}{t^2}&=\mathcal L\left(\xi\right)(t)
\end{align*}
holds with
$$
 \xi(s)=(a-b)s+\sum_{k=0}^{\infty}\left( 1_{[k+a,\infty)}(s)(s-k-a)-1_{[k+b,\infty)}(s)(s-k-b)\right).
 $$
 Furthermore, 
 \begin{align*}
    -\frac{\Phi_{a,b}'(t)}{t^2}&=\mathcal L\left(\eta\right)(t)
\end{align*}
holds with
$$
 \eta(s)=\sum_{k=0}^{\infty}\left( (b+k)1_{[k+b,\infty)}(s)(s-k-b)-(a+k)1_{[k+a,\infty)}(s)(s-k-a)\right).
 $$
\end{lemma}
{\it Proof.}
Since
$$
\frac{1}{1-e^{-t}}=\mathcal L\left(\sum_{k=0}^{\infty}\epsilon_k\right)(t)
$$
we see that 
\begin{align}
 -\Phi_{a,b}(t)&=
 \mathcal L\left((a-b)\epsilon_0+\sum_{k=0}^{\infty}(\epsilon_{k+a}-\epsilon_{k+b})\right)(t).
 \label{eq:Phi}
 \end{align}
 Therefore (using $sds\ast\epsilon_c=1_{[c,\infty)}(s)(s-c)$),
\begin{align*}
 -\frac{\Phi_{a,b}(t)}{t^2}&=\mathcal L \left(sds\right)(t)
 \mathcal L\left((a-b)\epsilon_0+\sum_{k=0}^{\infty}(\epsilon_{k+a}-\epsilon_{k+b})\right)(t)\\
 &=\mathcal L\left(sds\ast \left((a-b)\epsilon_0+\sum_{k=0}^{\infty}(\epsilon_{k+a}-\epsilon_{k+b})\right)\right)(t)
=\mathcal L \left(\xi\right)(t),
 \end{align*}
 with $\xi$ as in the statement of the lemma. 

 To prove the second assertion we differentiate in \eqref{eq:Phi} and obtain
 \begin{align*}
 -\Phi_{a,b}'(t)&=
 \mathcal L\left(\sum_{k=0}^{\infty}((k+b)\epsilon_{k+b}-(k+a)\epsilon_{k+a})\right)(t).
 \end{align*}
 Hence
  \begin{align*}
    -\frac{\Phi_{a,b}'(t)}{t^2}&=\mathcal L \left(sds\ast \sum_{k=0}^{\infty}((k+b)\epsilon_{k+b}-(k+a)\epsilon_{k+a})\right)(t)=\mathcal L(\eta)(t).
\end{align*}
This completes the proof.\hfill$\square$

We define the domain $\Omega$ (sketched in Figure \ref{fig:omega}) as
$$
\Omega=\{(a,b)\in \mathbb R^2\, |\, 0<b<a,\ a>1\}.
$$
\begin{figure}
\begin{center}
       \includegraphics[width=0.5\textwidth]{omega.eps}
 \end{center}  
 \caption{The parameter domain $\Omega$}
 \label{fig:omega}
\end{figure}

\begin{lemma}
    \label{lem:xi}
    When $(a,b)\in \Omega$, $\xi(t)\geq 0$ for $t\geq 0$.
\end{lemma}
{\it Proof}. It is easy to see that $\xi$ is a continuous and piecewise linear function. Furthermore, a computation shows that
 $$
 \xi(s+1)=\xi(s)+\Theta(s)
 $$
 with $\Theta(s)=(a-b)+1_{[a-1,\infty)}(s)(s+1-a)-1_{[b-1,\infty)}(s)(s+1-b)$. The function $\Theta$ is easily seen to be non-negative, and thus we need only to check that $\xi $ is non-negative on $[0,1]$. Since $a>1$ we have 
 $\xi(s)=(a-b)s-1_{[b,\infty)}(s)(s-b)$ for $s\in [0,1]$ which indeed is non-negative. \hfill $\square$
\begin{lemma}
    \label{lem:eta}
    When $(a,b)\in \Omega$, $\eta(t)\geq 0$ for $t\geq 0$.
\end{lemma}
{\it Proof}. 
If $a=b+k_0$ for some $k_0\in \{1,2,\ldots\}$ then $\eta$ is clearly non-negative on $[0,\infty)$. Otherwise, we choose $k_0\in \{1,2,\ldots\}$ such that
 $$
 b+k_0-1<a<b+k_0
 $$
 and let $b_0=b+k_0-1$. This gives
 \begin{align*}
 \lefteqn{\eta(s)=\sum_{k=0}^{k_0-2}(b+k)1_{[b+k,\infty)}(s)(s-b-k)+}\\
 &\sum_{k=0}^{\infty}\left( (b_0+k)1_{[k+b_0,\infty)}(s)(s-k-b_0)-(a+k)1_{[k+a,\infty)}(s)(s-k-a)\right).
 \end{align*}
 The first sum is clearly non-negative and the second infinite sum is a function of the same form as $\eta$, only this time with parameters $b_0, a$ such that $0<b_0<a<b_0+1$. 

 It follows that it is enough to prove $\eta\geq 0$ when the parameters $a$ and $b$ satisfy $b<a<b+1$. 

 Since $\eta$ is continuous, piecewise linear and $\eta(0)=0$,  
$\eta$ is non-negative provided $\eta(a+l)\geq$ and $\eta(b+l)\geq 0$ for all $l=0,1,\ldots$ (these being the points of discontinuity of the derivative). We get
\begin{align*}
    \eta(b+l)&=\sum_{k=0}^{l-1}\left((b+k)(b+l-b-k)-(a+k)(b+l-a-k)\right)\\
    &=(a-b)\sum_{k=0}^{l-1}(2k+a-l)= (a-b)l(a-1)\geq 0
\end{align*}
since $a>1$.
Similarly,
\begin{align*}
    \eta(a+l)&=\sum_{k=0}^{l}\left((b+k)(b+l-b-k)-(a+k)(b+l-a-k)\right)\\
    &=(a-b)\sum_{k=0}^{l}(2k+b-l)= (a-b)b(l+1)\geq 0.
\end{align*}
This completes the proof.
 \hfill$\square$

 Plots of $\xi$ and $\eta$ are included in Figure \ref{fig:xi+eta}. Notice that $\xi$ is periodic for large values of the variable, since the function $\Theta$ in the proof of Lemma \ref{lem:xi} equals zero on $[a-1,\infty)$.
