\section{Main results}
The integral representation of the logarithmic derivative of the Gamma function
$$
\psi(x)=(\log \Gamma)'(x)=\int_0^{\infty}\left(\frac{e^{-t}}{t}-\frac{e^{-xt}}{1-e^{-t}}\right)\, dt
$$
(see \cite{as,aar}) is used in the proof of the next lemma.
\begin{lemma}
\label{lemma:prelim}
    The following representations hold.
   \begin{align*}
     -(\log M_{a,b})'(x)&=\int_0^{\infty}e^{-xu}\Phi_{a,b}(u)\, du,\\
    -x(\log M_{a,b})'(x)&=\int_0^{\infty}e^{-xu}\Phi_{a,b}'(u)\, du,
    \\
    \log M_{a,b}(x)&=\int_0^{\infty}e^{-xu}(\Phi_{a,b}(u)/u)\, du.
   \end{align*}
\end{lemma}
{\it Proof.}
By definition we have
$$
\log M_{a,b}(x)=(a-b)\log x+\log \Gamma (x+b)-\log \Gamma(x+a),
$$
so that, using the representation of $\psi$, 
\begin{align*}
-(\log M_{a,b})'(x)&=\frac{b-a}{x}-\psi(x+b)+\psi(x+a)
% &=(b-a)\int_0^{\infty}e^{-xt}\, dt+\int_0^{\infty}e^{-xt}\frac{e^{-bt}-e^{-at}}{1-e^{-t}}\, dt\\
=\int_0^{\infty}e^{-xt}\Phi_{a,b}(t)\, dt.
\end{align*}
Thus the first assertion holds. (This is also contained in \cite[(6.10)]{KL}, but for the reader's convenience we have included the derivation here.)  By partial integration the second assertion follows. Using Fubini's theorem and the relation $\lim_{u\to \infty}M_{a,b}(u)=1$ we obtain the third assertion 
    % $$
    % \log M_{a,b}(x)=\int_0^{\infty}e^{-xu}(\Phi_{a,b}(u)/u)\, du
    % $$
    by integrating the first one (from $x$ to $\infty$) and this proves the lemma.\hfill$\square$




\begin{prop}
\label{prop:log-mst-in-s2}
 The function $-\log M_{a,b}$ belongs to $\mathcal S_2$ for $(a,b)\in \Omega$. \end{prop}
 {\it Proof.}
 In view of the third relation in Lemma \ref{lemma:prelim} and \eqref{eq:alt-stieltjes} we need to show that $-\Phi_{a,b}(t)/t^2$ is completely monotonic. This follows by combining Lemma \ref{lemma:Phi} and Lemma \ref{lem:xi}.
 \hfill$\square$

 \begin{rem}
 Kristiansen's theorem (see \cite{kristiansen} and \cite{BKP}) states that any function $f$ from $\mathcal S_2\setminus \{0\}$ is logarithmically completely monotonic (meaning that $-f'/f$ is completely monotonic). A function is called infinitely divisible if its Laplace transform is logarithmically completely monotonic. Combining Krisitansen's theorem with the first formula of Lemma \ref{lemma:prelim} we see that $-\Phi_{a,b}(t)/t$ is infinitely divisible. 
 \end{rem}


 \begin{prop}
     \label{prop:xlogMprime}
     The function $x(\log M_{a,b})'(x)$ belongs to $\mathcal S_3$ for $(a,b)\in \Omega$, and
     $$
     x(\log M_{a,b})'(x)=2\int_0^{\infty}\frac{\eta(t)}{(x+t)^3}\, dt.
     $$
 \end{prop}
 {\it Proof.} Using the second relation in Lemma \ref{lemma:prelim} and again \eqref{eq:alt-stieltjes} it follows that $x(\log M_{a,b})'(x)$ belongs to $\mathcal S_3$ exactly when $-\Phi_{a,b}'(t)/t^2$ is completely monotonic. This follows from Lemma \ref{lemma:Phi} and Lemma \ref{lem:eta}, and we also obtain the representation in terms of $\eta$.\hfill $\square$


 \begin{rem}
    As we have seen, the function $-\Phi_{a,b}'(t)/t^2$ is completely monotonic, and since also $-\Phi_{a,b}>0$ it follows that $-\Phi_{a,b}\in \mathcal B_{3}$. Using Lemma \ref{lemma:prelim} and \cite[Theorem 3.1]{KP1} we obtain $x(\log M_{a,b})'(x)=x\mathcal L(-\Phi_{a,b})(x)\in \mathcal S_3$. This gives another proof of Proposition \ref{prop:xlogMprime}. 

    Since the function $-\Phi_{a,b}$ is also bounded it has a representation 
    $$
    -\Phi_{a,b}(x)=2q(\infty)-x^3\int_0^{\infty}q(v)v^2e^{-xv}\, dv,
    $$
    where $q$ given by 
    $$
    q(t)=\int_0^t\frac{\eta(s)}{s^3}\, ds.
    $$
    is positive, increasing and bounded. (See \cite[Proposition 3.9]{KP1}.)
\end{rem}


 \begin{thm}
 \label{thm:MinT}
     For $(a,b)\in \Omega$ we have $M_{a,b}\in \mathcal T_{a-b,-3}$.
 \end{thm}
    {\it Proof.} As mentioned in the introduction it is equivalent to show that $x^{1-a+b}M_{a,b}'(x)$ belongs to $\mathcal S_{a-b+4}$. Writing $a-b=[a-b]+s$, with $s\in [0,1)$ (the square brackets denote integer part) and $t=x+b$ we obtain from  \cite[Proposition 4.6]{BKP}
$$
\frac{\Gamma(x+b)}{\Gamma(x+a)}=\frac{\Gamma(t)}{\Gamma(t+[a-b]+s)}\in \mathcal S_{[a-b]+1}.
$$
    Therefore
    \begin{align*}
      x^{1-a+b}M_{a,b}'(x)&=x^{1-a+b}M_{a,b}(x)\left(\log M_{a,b}\right)'(x)\\
      &=\frac{\Gamma(x+b)}{\Gamma(x+a)}\, x(\log M_{a,b})'(x)\in \mathcal S_{[a-b]+1}\mathcal S_3.
    \end{align*}
    Since $S_{[a-b]+1}\mathcal S_3\subseteq \mathcal S_{[a-b]+4}\subseteq\mathcal S_{a-b+4}$
    the result is proved.
     \hfill $\square$

Theorem \ref{thm:MinT} yields the representation 
     $$
     M_{a,b}(x)=\alpha x^{a-b}+\beta+\int_0^{\infty}\gamma(a-b,xt)t^3\varphi(t)\, dt,
     $$
     for some completely monotonic function $\varphi$. Since $M_{a,b}$ is a bounded function from $\mathcal B_{a-b}$, $\lim_{x\to \infty}M_{a,b}=1$ and $M_{a,b}(0)=0$ it thus admits the representation
     \begin{equation}
         \label{eq:Mbdd}
      M_{a,b}(x)=1-x^{a-b}\int_0^{\infty}p(t)t^{a-b-1}e^{-xt}\, dt,
     \end{equation}
     with $p(t)=\int_0^tu^3\varphi(u)\, du$ being bounded. (See \cite[Proposition 22 and 3.9]{KP1}.)     



\begin{rem}
    In  \cite{KL} the family of functions $M_{a,b}$ was also investigated outside the domain $\Omega$, namely for $(a,b)$ inside the triangle with corners $(1,0)$, $(1,1)$ and $(1/2,1/2)$: for these values of the parameters we have 
