    \section{A related function}
    In the paper \cite{KL} the function $L_{a,b}$ given by 
    $$
    L_{a,b}(x)=x(1-M_{a,b}(x))
    $$
    was investigated. 
    % Clearly, $L_{a,b}$ is a positive function, 
    % Since $M_{a,b}$ increases from $0$ to $1$ on $(0,\infty)$, $L_{a,b}$ is a positive function. 
    % But of course much more can be said.  
    According to \cite[(2.10) and (2.11)]{KL} we have the concrete representation 
    \begin{equation}
    \label{eq:L}
      L_{a,b}(x)=\frac{1}{\Gamma(a-b)}x^{a-b+1}\int_0^{\infty}t^{a-b-1}(1-w(t))e^{-xt}\, dt,
    \end{equation}
    where 
    $$
    w(t)=\left(\frac{1-e^{-t}}{t}\right)^{a-b-1}e^{-bt}.
    $$
     If we compare this with \eqref{eq:Mbdd} it follows that
     $$
     \frac{1-w(t)}{\Gamma(a-b)}= \int_0^tu^3\varphi(u)\, du,
     $$
     so $-w'(t)/t^3$ is completely monotonic. (This does not seem to be obvious from the definition of $w$.)
     Furthermore we obtain the representation
     $$
     M_{a,b}(x)=-\frac{1}{\Gamma(a-b)}\int_0^{\infty}\gamma(a-b,xt)w'(t)\, dt.
     $$
    \begin{prop}
    \label{prop:L}
        For $(a,b)\in \Omega$ with $a-b>1$ we have $L_{a,b}\in \mathcal B_{a-b}\setminus \mathcal B_1$.
    \end{prop}
    {\it Proof.} From \cite[Theorem 3.1]{KL} we have $L_{a,b}\notin \mathcal B_1$ and hence we concentrate on proving $L_{a,b}\in \mathcal B_{a-b}$. 
    To ease notation let $\lambda=a-b$ and notice that $\lambda >1$.  
    Differentiation in \eqref{eq:L} and partial integration shows
    \begin{equation}
        \label{eq:Lprime}
    \Gamma(\lambda)L_{a,b}'(x)x^{1-\lambda}= x\int_0^{\infty}t^{\lambda-1}(1-w(t)+tw'(t))e^{-xt}\, dt.
    \end{equation}
    Hence $L_{a,b}'(x)x^{1-\lambda}$ is completely monotonic provided $t^{\lambda-1}(1-w(t)+tw'(t))$ is a non-negative and increasing function on $(0,\infty)$. See \cite{KP0}. In the lemma below it is proved that $w$ is  logarithmically convex. It is thus also convex and hence 
    $$
    (1-w(t)+tw'(t))'=tw''(t)>0.
    $$
    It is elementary to see that $\lim_{t\to 0}(1-w(t)+tw'(t))=0$ and therefore the function $1-w(t)+tw'(t)$ is both increasing and non-negative.\hfill$\square$


    \begin{lemma}
    The function $w$ 
    % $$
    % w(t)=e^{-bt}\left(\frac{1-e^{-t}}{t}\right)^{a-b-1}
    % $$
    is decreasing and logarithmically convex on $(0,\infty)$ for $(a,b)\in \Omega$ with $a-b>1$.
    \end{lemma}
    {\it Proof.} Elementary calculations show that
    $$
    (\log w)''(t)=(a-b -1)\left(\frac{1}{t^2}-\frac{e^t}{(e^t-1)^2}\right).
    $$
    This expression is positive since 
    $$
    t^2<2(\cosh t-1)=e^t+e^{-t}-2=(e^t-1)(1-e^{-t})=\frac{(e^t-1)^2}{e^t},
    $$
    and the proof is complete.\hfill $\square$


\section{Additional results and comments}
% For a generalized Bernstein function $g$ of order $\lambda$ it is known that $g(x)/x^{\lambda}$ is completely monotonic. 
We begin by a simple result about products of generalized Bernstein functions. A counterpart for higher order Thorin-Bernstein functions is proved in Corollary \ref{cor:product-higher-order}.
\begin{prop}
\label{prop:product-bernstein}
    If $f_1\in \mathcal B_{\lambda_1}$ and $f_2\in \mathcal B_{\lambda_2}$ then $f_1f_2$ belongs to $\mathcal B_{\lambda_1+\lambda_2}$.
\end{prop}
{\it Proof.} By definition,  $f_j'(x)/x^{\lambda_j-1}$ is a completely monotonic function, and so is $f_j(x)/x^{\lambda_j}$. (See \cite[Corollary 2.1]{KP1}.) The elementary relation 
$$
\frac{(f_1f_2)'(x)}{x^{\lambda_!+\lambda_2-1}}=
\frac{f_1'(x)}{x^{\lambda_1-1}}\frac{f_2(x)}{x^{\lambda_2}}+
\frac{f_1(x)}{x^{\lambda_1}}\frac{f_2'(x)}{x^{\lambda_2-1}}$$
yields that $(f_1f_2)'(x)/x^{\lambda_!+\lambda_2-1}$ is again completely monotonic and this concludes the proof.\hfill $\square$



As mentioned in the introduction, a function $f$ belong to $\mathcal T_{\lambda,\alpha}$ if and only if $f'(x)/x^{\lambda-1}$ belongs to $\mathcal S_{\lambda+1-\alpha}$. We show that also $f(x)/x^{\lambda}$ is a generalized Stieltjes function of positive order:
\begin{prop}
    Let $f\in \mathcal T_{\lambda,\alpha}$. Then $(f(x)-f(0))/x^{\lambda}$ belongs to $\mathcal S_{\lambda+1-\alpha}$.
\end{prop}
{\it Proof.} Since $f'(x)/x^{\lambda-1}$ belongs to $\mathcal S_{\lambda+1-\alpha}$ we have, for some completely monotonic function $\varphi$, 
$$
f'(s)=cs^{\lambda-1}+s^{\lambda-1}\int_0^{\infty}t^{\lambda-\alpha}\varphi(t)e^{-st}\, dt.
$$
Integration of this relation between $0$ and $x$ yields, after changing the order of integration and a change of variable ($u=ts/x$),
\begin{align*}
f(x)-f(0)&=cx^{\lambda}/\lambda+\int_0^{\infty}\int_0^xe^{-st}s^{\lambda-1}\, ds\, t^{\lambda-\alpha}\varphi(t)\, dt\\
&=cx^{\lambda}/\lambda+x^{\lambda}\int_0^{\infty}\int_0^te^{-xu}u^{\lambda-1}\, du\, t^{-\alpha}\varphi(t)\, dt.
\end{align*}
This gives
$$
(f(x)-f(0))/x^\lambda=
c/\lambda+\int_0^{\infty}\sigma(u)u^{\lambda-\alpha}e^{-xu}\, du,
$$
where the function $\sigma$ is given by 
$$\sigma(u)=\int_1^{\infty}v^{-\alpha}\varphi(uv)\, dv.
$$
It is immediate that $\sigma$ is completely monotonic, and thus the proposition is proved.\hfill $\square$

As an application of this result we notice the following corollary.
\begin{cor}
\label{cor:product-higher-order}
    If $f_1\in \mathcal T_{\lambda_1,\alpha_1}$ and $f_2\in \mathcal T_{\lambda_2,\alpha_2}$ then $(f_1-f_1(0))(f_2-f_2(0))$   belongs to $\mathcal T_{\lambda_1+\lambda_2,\alpha_1+\alpha_2-1}$.
\end{cor}
{\it Proof.} We may assume that the functions are zero at the origin. Thus $f_j(x)/x^{\lambda_j}$ and $f_j'(x)/x^{\lambda_j-1}$ belong to $\mathcal S_{\lambda_j+1-\alpha_j}$. The elementary relation 
$$
\frac{(f_1f_2)'(x)}{x^{\lambda_!+\lambda_2-1}}=
\frac{f_1'(x)}{x^{\lambda_!-1}}\frac{f_2(x)}{x^{\lambda_2}}+
\frac{f_1(x)}{x^{\lambda_!}}\frac{f_2'(x)}{x^{\lambda_2-1}}$$
yields that $(f_1f_2)'(x)/x^{\lambda_!+\lambda_2-1}\in \mathcal S_{\lambda_1+1-\alpha_1}\mathcal S_{\lambda_2+1-\alpha_2}\subseteq \mathcal S_{\lambda_1+\lambda_2+1-(\alpha_1+\alpha_2-1)}$. This concludes the proof.\hfill $\square$


