Let us mention an example related to the incomplete Beta function.
\begin{cor}
    Assume $0<b<a$. The function $B(b,a-b)-B(b,a-b,e^{-x})$ belongs to $\mathcal B_{[a-b]+1}$.
\end{cor}
{\it Proof.} 
Denote the function by $f$. By definition, 
$$
f(x)=\int_{e^{-x}}^1t^{b-1}(1-t)^{a-b-1}\, dt=\int_0^xe^{-bt}(1-e^{-t})^{a-b-1}\, dt,
$$
so that 
$$
x^{-[a-b]}f'(x)=e^{-bx}\left(\frac{1-e^{-x}}{x}\right)^{[a-b]}(1-e^{-x})^{a-b-[a-b]-1}.
$$
The function $1/(1-e^{-x})$ is logarithmically completely monotonic. Indeed,
$$
-\left(\log \frac{1}{1-e^{-x}}\right)'=\frac{e^{-x}}{1-e^{-x}}=\sum_{k=0}^{\infty}e^{-(k+1)x}.
$$
Therefore any positive power of it is completely monotonic. In particular $(1-e^{-x})^{a-b-[a-b]-1}$ is completely monotonic, and so $x^{-[a-b]}f'(x)$ is also completely monotonic. This completes the proof.
\hfill $\square$



\begin{rem}
 The function from the corollary above does not belong to any of the classes $\mathcal T_{[a-b]+1,\alpha}$, where $\alpha<[a-b]+2$. Indeed if it did belong to $\mathcal T_{[a-b]+1,\alpha}$ then the function $x^{-[a-b]}e^{-bx}(1-e^{-x})^{a-b-1}$ would be a generalized Stieltjes function of some positive order $\mu$, and consequently, 
$$
x^{\mu-[a-b]}e^{-bx}(1-e^{-x})^{a-b-1}
$$
would be increasing. This is a contradiction since the limit of the expression above as $x$ tends to infinity is $0$.   
\end{rem}

\begin{prop} 
    If $f\in \mathcal B_1$ and $f(x)/x$ is logarithmically completely monotonic then $f^{\lambda}\in \mathcal B_{\lambda}$ for any $\lambda\geq 1$.
\end{prop}
{\it Proof.} We have 
$x^{1-\lambda}\left(f(x)^\lambda\right)'=\lambda(f(x)/x)^{\lambda-1}f'(x)$,
which is completely monotonic since it is a product of completely monotonic functions.\hfill $\square$
