\begin{defn}
Let $\alpha\geq 0$. A function $f:(0,\infty)\to (0,\infty)$ belongs to the class $\mathcal C_\alpha$ if $x^\alpha f(x)$ is the Laplace transform of a decreasing and logarithmically convex function $u$. 
\end{defn}
We remark that for a positive and decreasing function $u$, $\mathcal L(u)$ is defined if and only if $\int_0^1u(t)\, dt<\infty$.


\begin{prop}
    \label{prop:stamatis-1}
    If $f\in \mathcal C_{\alpha}$ then 
    \begin{enumerate}[(a)]
        \item $x^{\alpha+1}f(x)\in \mathcal B_1$;
        \item $1/f(x)\in \mathcal B_{\alpha+1}$;
        \item $1/(x^{\alpha+1}fx))$ is completely monotonic.
    \end{enumerate}
\end{prop}
\noindent {\it Proof.} By definition $x^{\alpha}f(x)=\mathcal L(u)(x)$, where $u$ is decreasing and logarithmically convex. Since $u$ is decreasing, it follows that $x^{\alpha+1}f(x)=x\mathcal L(u)(x)$ is a Bernstein function (see e.g.\ the remark below). This proves (a). According to \cite[Theorem 11.11]{S}, $x\mathcal L(u)(x)$ is actually a so-called special Bernstein function. Therefore also the function $1/\mathcal L(u)$ is a Bernstein function.  From Proposition \ref{prop:product-bernstein} it now follows that
$$
\frac{1}{f(x)}=x^{\alpha}\, \frac{1}{\mathcal L(u)(x)}\in \mathcal B_{\alpha+1},$$
and this proves (b). Item (c) follows from (b) and \cite[Corollary 2.1]{KP1}, and this concludes the proof. \hfill $\square$
\begin{rem}
    Suppose that $u(t)=\int_t^{\infty}d\mu(s)$. Then by Fubini's theorem, 
    $$
    x\mathcal L(u)(x)= \int_0^{\infty}\left(1-e^{-xs}\right)\, d\mu(s),
    $$
    showing that $x\mathcal L(u)(x)$ is a Bernstein function.

\end{rem}
