We end this paper by applying Proposition \ref{prop:stamatis-1} to the $\psi$-function. 

\begin{cor}
    For $0<b<a-1$ the function $F_{a,b}$ defined as
    $$
    F_{a,b}(x)=\frac{x^{a-b-1}}{\psi(x+a)-\psi(x+b)}
    $$
    belongs to $\mathcal B_{a-b}$.
\end{cor}
\noindent {\it Proof.} 
 Notice that $\psi(x+a)-\psi(x+b)=\mathcal L(\varphi_{a,b})(x)$, where $\varphi_{a,b}$ is the decreasing and logarithmically convex function in the lemma below. Hence, $\mathcal L(\varphi_{a,b})(x)/x^{a-b-1}$ belongs to $\mathcal C_{a-b-1}$, and thus by Proposition \ref{prop:stamatis-1}, its reciprocal $x^{a-b-1}/\mathcal L(\varphi_{a,b})(x)$ belongs to $\mathcal B_{a-b}$. The proof is complete.\hfill $\square$

\begin{lemma}
    \label{lemma:logconv}
    For $0<b<a-1$ the function $\varphi_{a,b}(t)=(e^{-bt}-e^{-at})/(1-e^{-t})$ is decreasing and logarithmically convex.
\end{lemma}
\noindent {\it Proof.} Since $\varphi_{a,b}(t)=\Phi_{a,b}(t)-(b-a)$ it is clear from Lemma \ref{lemma:Phi} and Lemma \ref{lem:eta} that it decreases. The logarithmic convexity can be seen as follows. Letting $\lambda=a-b$, a standard computation shows that logarithmic convexity holds if and only if 
$$
\frac{e^{-t}}{(1-e^{-t})^2}>\frac{\lambda^2 e^{-\lambda t}}{(1-e^{-\lambda t})^2}.
$$
Rearranging the terms this is equivalent to 
\begin{equation}
\label{eq:ineq}
\left(\frac{\sinh (\lambda t/2)}{\sinh (t/2)}\right)^2>\lambda^2.
\end{equation}
However, by comparing coefficients in the Taylor series it easily follows that $\sinh (\lambda t/2)/\sinh (t/2)>\lambda$, and therefore \eqref{eq:ineq} holds.\hfill $\square$ 
