\subsection{Loss functions}
In our modeling of evolutionary training we employed two different loss functions, one of which is the "contrast" loss  introduced by Eq.(\ref{eq:loss_log1}) in the main text, the other is the 
standard Mean Square Error (MSE) between the desired and observed output fugacities:
\begin{eqnarray}
\Lambda_{\rm contrast}& = \max_{i \in \rm out} \left[ \ln \left(\frac{\langle (1-\phi_i^\alpha) f^{\alpha}_i \rangle_\alpha}{1-\langle \phi_i^\alpha \rangle_\alpha}\right) - \frac{\left\langle \phi_i^\alpha \ln f^{\alpha}_i \right\rangle_\alpha}{\langle \phi_i^\alpha \rangle_\alpha} \right]
\label{loss:contrast}
\\
\Lambda_{\rm mse} &= \left\langle \left(f_{i}^\alpha- \phi_i^\alpha\right)^2\right\rangle_{\alpha, i} \label{eq:MSE_loss}
\label{loss:mse}
\end{eqnarray}
\subsection{Performance metrics} The performance of the chemical classified was characterized by using the Mutual Information, Eq. \ref{eq:MI}, and on/off Contrast:
\begin{align}
D_x=\langle\log_{10}f_x |\mathcal{X}\rangle -\max\left[\langle\log_{10}f_x |\mathcal{Y}\rangle, \langle\log_{10}f_x |\mathcal{Z}\rangle\right] 
\end{align}
Here $\mathcal{X}$, $\mathcal{Y}$, $\mathcal{Z}$ are binary variables that indicate that the input belongs to a specific class. The contrast measures for $y$ and $z$ outputs are defined analogously.  


\subsection{Evolutionary Training}
At each iteration step, we begin with the current best-performing system and generate $M = 49$ of its mutants by evolving the association matrix $K_{ij}$ according to Eq.\ (\ref{eq:mut}), with $\sigma_{\text{mut}} = 0.5$. For each of these $M$ mutants, as well as for the original system, we generate three variants by scaling the concentrations of the hidden layer components by factors $1$, $1 + \Delta$, and $1/(1 + \Delta)$, with $\Delta=0.015$. To ensure physical plausibility, the evolving association constants and concentrations are constrained by caps: $c_{\min} \leq c \leq c_{\max}$ ($c_{\min}=0.2$, $c_{\max}=5.0$), and $K_{ij} \leq K_{\max} = 10^4 / c_0$.

Our procedure results in a total of $3(1 + M) = 150$ variants that are then evaluated against batches of 48 input cocktails, consisting of 16 cocktails for each of the $n_{\text{out}} = 3$ output classes. The input concentrations are perturbed by multiplicative log-normal noise: $c_i \, e^{\mathcal{N}(0, (\nu \sigma)^2)}$. The variant that minimizes the chosen loss function is selected as the new best-performing system, and the procedure is repeated.



\subsection{Gradient Descent}
We start by rewriting Eq.(\ref{eq:f}) in terms of free concentrations (activities) of the components, $x_i=c_if_i$:
\begin{equation}
x_i=\frac{c_i}{1+\sum_jK_{ij}x_j}
\end{equation}
To evaluate gradients of $\Lambda$ with respect to the model parameters, we expand this equation in terms of small increaments of concentrations, activities and association constants: 
\begin{equation}
\delta x_i=\frac{x_i\delta c_i}{c_i} - \frac{x_i^2}{c_i}\sum_j\left(K_{ij} \delta x_j + x_j\delta K_{ij}\right)
\end{equation}
This set of  equations can be rewritten as
\begin{equation}
\left(\widehat K +\widehat T^{-1}\right)\delta {\bf x}= \left({\widehat X}^{-1} \delta {\bf c}-\delta {\widehat K}{\bf x}  \right)
\end{equation}
Here  $T_{ij}=\delta_{ij}x_i^2/c_i$ and $X_{ij}= \delta_{ij}x_i$ 
 This result allows one to calculate the gradients of the loss functions, Eqs.\ (\ref{loss:contrast}), (\ref{loss:mse}), in the space of  model parameters, ${\widehat K}$ and $\bf c$:  
\begin{align}
\frac{\partial \Lambda}{\partial c_i } &=\left\langle\frac{\partial \Lambda}{ \partial {\bf x}^{\alpha}_{\rm out}}\frac{\partial {\bf x}^\alpha_{\rm out}}{\partial c_i} \right\rangle_\alpha =\left\langle\frac{F_i^\alpha}{x_i^\alpha}\right\rangle_\alpha \\
\frac{\partial \Lambda}{\partial{\widehat K} }&=-\left\langle {\bf F}^\alpha\otimes {\bf x}^\alpha +{\bf x}^\alpha\otimes {\bf F}^\alpha -\widehat X^\alpha\widehat \Phi^\alpha\right\rangle_\alpha \label{eq:derivL}
\end{align}
Here :
\begin{equation}
{\bf F}^\alpha= \left(\widehat K +\widehat T^{-1}\left ({\bf x}^\alpha\right )\right)^{-1}  \frac{\partial \Lambda}{ \partial {\bf x}^{\alpha}_{\rm out}} \label{eq:y}
\end{equation}
and   $\Phi_{ij}^\alpha= \delta_{ij}F_i^{\alpha}$.
The set of vectors $\bf F^\alpha$  given by Eq. \ref{eq:y} can also be evaluated recursively, to avoid  inverting matrix $\widehat K +\widehat T^{-1}$ at each step, in combination with the recursive solution of Eqs. (\ref{eq:X}): 
\begin{align}
x_i^\alpha&\leftarrow\frac{c_i}{1+\sum_j K_{ij}x_j^\alpha} \label{eq:recurs1}\\
{\bf F}^\alpha&\leftarrow \widehat T ({\bf x}^\alpha) \left( \frac{\partial \Lambda}{ \partial {\bf x}^\alpha_{\it out}}-\widehat K {\bf F}^\alpha\right )\label{eq:recurs2}
\end{align}

We implemented  the gradient descent evolution in terms of concentration of the hidden layer $c_{\rm hid}$, and affinity parameters  $\tau_{ij}\equiv \ln \left(c_0K_{ij}\right)=\exp(\tau_{ij})$, that are directly related to the corresponding binding free energies: $\tau_{ij}=-\Delta G_{ij}/RT$. The  two loss functions were  additionally amended by the regularization term:
\begin{equation}
    \widetilde{\Lambda}=\Lambda+\mu \sum_{i,j} \tau_{ij}
\end{equation}
The resulting evolution for the GD evolution of the hidden concentration and the affinity parameters could thus be obtained as
\begin{align}
c_{\rm hid} & \leftarrow  c_{\rm hid} - \epsilon_{c}\frac{\partial \widetilde{\Lambda} }{\partial c_{\rm hid}}= c_{\rm hid} -\epsilon_{c}\sum_{i\in {\rm hidden}} \left\langle\frac{F_i^\alpha}{x_i^\alpha}\right\rangle_\alpha\\
    \tau_{ij} & \leftarrow \tau_{ij} -\epsilon_\tau \frac{\partial \widetilde{\Lambda}}{\partial \tau_{ij}} = \tau_{ij} -\epsilon_\tau\left( K_{ij}\frac{\partial \Lambda }{\partial K_{ij}} + \mu\right)
\end{align}

Here $\partial \Lambda /\partial \widehat K$ and $F$ are determined  by Eqs.(\ref{eq:derivL}),(\ref{eq:recurs1}), (\ref{eq:recurs2}), which  in turn depend on computing the loss function  derivatives  $\frac{\partial \Lambda}{ \partial {\bf x}_{\it out}}$:
\begin{align}
    \frac{\partial \Lambda_{\it contrast}}{ \partial x^{\alpha}_i} =& \frac{\delta_{ij}}{N_Bc_i} \left(
    \frac{1-\phi^\beta_j}{\langle (1-\phi^\alpha_j) f^\alpha_j \rangle_\alpha} - 3 \frac{\phi^\beta_j}{f^\beta_j}
    \right),  \\
    & \nonumber  j=\mathrm{argmax} \{ \Lambda_{{\it contrast},j} \}\\
    \frac{\partial \Lambda_{\rm mse}}{\partial x^{\alpha}_i} =&\frac{2( f^\alpha_i - \phi^\alpha_i)} { N_Bc_i} 
\end{align}
In practice, instead of employing this iterative scheme, we use the adaptive learning rate algorithm from Ref. \cite{Adam}.






