\begin{corollary}[Recognizable identity implies decidability]\label{CorollPropos2}\hfill


\noindent Let ${\cal A}$ be in $ {\sf Struc}_{c_1,c_2}$, ${\rm id}_{U_{\cal A}}\in {\rm SDEC}_{\cal A}$, and $P\subseteq U_{\cal A}^\infty$. 

Then, the computability of $\chi_P$ by a BSS RAM in ${\sf M}_{\cal A}$ implies $P\in {\rm DEC}_{\cal A}$. 
\end{corollary}

