\vspace{0.2cm}\noindent If we replace the program segment \fbox{{\sf $\ell_7: \, \,$ stop.}} in ${\cal P}_{\cal M}$ by 

\hspace{1.7cm }{\sf $\ell_7: \, \, Z_2:=c_2^0;$ if $r_1^{2}(Z_1,Z_2)$ then goto $\ell_8$ else goto $\ell_7;$ 

\hspace{1.7cm}$\ell_8:\,\,$ stop.}

\noindent then the resulting program allows to semi-decide the complement of $\,{\rm id}_{U_{{\cal A}_1}}$.
\end{example}

\begin{example}[A structure with $(d)$ in which $(c)$ does not hold]\label{CounterEx2}\hfill 

\noindent Let ${\cal A}_2$ be the finite structure $(\{a,b,c,d\} ;a,b ;; r_a,r_b)$ of signature $(2;;1,1)$ in ${\sf Struc}_{a,b}$ that contains four elements, the constants $a$ and $b$, and two unary relations $r_a$ and $r_b$ given by $r_a=\{a\}$ and $ r_b= \{b\}$.
 The semi-decidability of $\{a\}$ over ${\cal A}_2$ (i.e., the semi-decidability of $\{a\}$ by a machine in ${\sf M}_{{\cal A}_2}$) results from the execution of a program such as

\vspace{0.1cm}

{\sf 
\begin{tabular}{ll}
\quad\qquad $1: \,\,\,$ if $I_1=I_2$ then goto $2$ else goto $1;$\\
\quad\qquad $2 : \,\,\,$ if $r_1^{1}(Z_1)$ then goto $3$ else goto $2;$ \\
\quad\qquad$3:\,\,\,$ stop. \\
\end{tabular}}

\vspace{0.1cm}

\noindent If the literal \fbox{$r_1^{1}(Z_1)$} is replaced by $r_2^{1}(Z_1)$, then the new program can be used for semi-deciding $\{b\}$.
The semi-decidability of the complement $U_{{\cal A}_2}^\infty\setminus\{a\}$ results from changing some of the labels in the {\sf goto}-commands.

\vspace{0.1cm}

{\sf 
\begin{tabular}{ll}
\quad\qquad $1: \,\,\,$ if $I_1=I_2$ then goto $2$ else goto $3;$\\
\quad\qquad $2 : \,\,\,$ if $r_1^{1}(Z_1)$ then goto $2$ else goto $3;$ \\
\quad\qquad$3:\,\,\,$ stop. \\
\end{tabular}}

\vspace{0.1cm}

\noindent If the literal \fbox{$r_1^{1}(Z_1)$} is replaced by $r_2^{1}(Z_1)$, then the new program can be used for semi-deciding $U_{{\cal A}_2}^\infty\setminus\{b\}$.
 Moreover, $\chi_{\{a\}}$ can be computed by the BSS RAM in $ {\sf M}_{{\cal A}_2}$ using the following program.

{\sf 
\begin{tabular}{ll}
\quad\qquad $\ell_1: \,\,$ if $I_1=I_2$ then goto $\ell_2$ else goto $\ell_3;$\\
\quad\qquad $\ell_2 : \,\,$ if $r_1^{1}(Z_1)$ then goto $\ell_4$ else goto $\ell_3;$ \\
\quad\qquad$\ell_3: \, \, I_1:=1; \, \, Z_1:=c_2^0;$ \\ 
\quad\qquad$\ell_4: \,\,$ stop. \\
\end{tabular}}

\vspace{0.1cm}

\noindent $\chi_{\{b\}}$ can be computed by the BSS RAM in $ {\sf M}_{{\cal A}_2}$ using the following program.

\vspace{0.1cm}

{\sf 
\begin{tabular}{ll}
\quad\qquad $\ell_1: \, \, I_2:=I_2+1;$ \,\, $Z_{I_2}:=Z_{I_1};$ \,\, $Z_1:=c_2^0;$ \\ 
\quad\qquad $\ell_2: \,\,$ if $I_1=I_3$ then goto $\ell_3$ else goto $\ell_5;$\\
\quad\qquad $\ell_3 : \,\,$ if $r_2^{1}(Z_2)$ then goto $\ell_4$ else goto $\ell_5;$ \\
\quad\qquad$\ell_4: \, \, Z_1:=c_1^0;$ \\ 
\quad\qquad$\ell_5: \, \,I_1:=1;$ stop. \\
\end{tabular}}

\vspace{0.4cm}

\noindent {\bf Why is $(c)$ not true in ${\cal A}_2$?} Let us assume that there is an ${\cal M}\in {\sf M}_{{\cal A}_2}$ that does not halt on input $(d,c)\not\in {\rm id}_{U_{{\cal A}_2}}$ and that halts on input $(c,c)\in {\rm id}_{U_{{\cal A}_2}}$. For these inputs, the initial configurations $con_{1}$ and $con'_{1}$ of ${\cal M}$ are given by 

\vspace{0.1cm}

\qquad $con_{1} =(1\,.\,(2,1,\ldots,1)\,.\,(d,c,c,\ldots))$, 

\qquad $con'_{1} =(1\,.\,(2,1,\ldots,1)\,.\,(c,c,c,\ldots))$.

\vspace{0.2cm}

\noindent For both resulting sequences  $(con_{t})_{t\geq 1}\in {\sf Con}_{{\cal M},(d,c)}$ and $(con'_{t})_{t\geq 1}\in {\sf Con}_{{\cal M},(c,c)}$ given by 

\vspace{0.1cm}

\qquad $con_{t}= (\ell_t\,.\,\vec\nu^{(t)}\,.\,\bar u^{(t)})$ \hfill \textcolor{gray}{\small ($\ell_t\in {\cal L}_{\cal M}$, $\vec\nu^{(t)}\in \bbbn_+^{k_{\cal M}}$, $\bar u^{(t)}\in U_{{\cal A}_2}^{\omega}$)}, 

\qquad $con'_{t}= (\ell'_t\,.\,\vec\mu^{(t)}\,.\,\bar z^{(t)})$ \hfill \textcolor{gray}{\small($\ell_t'\in {\cal L}_{\cal M}$, $\vec\mu^{(t)}\in \bbbn_+^{k_{\cal M}}$, $\bar z^{(t)}\in U_{{\cal A}_2}^{\omega}$)}, 

\vspace{0.2cm}

\noindent and $\bar u^{(t)}=( u_{t,1}, u_{t,2},\ldots)$ and $\bar z^{(t)}=( z_{t,1}, z_{t,2},\ldots)$ for all $t\geq 1$, we can prove the following properties $(i)$ to $(iii)$ by induction on $t$. 

\vspace{0.1cm}

 \hspace*{0.36cm}$\begin{array}{lclllcllc} 
 \ell'_{t}&=&\ell_{t}, \hspace*{1.2cm}&&\vec\mu^{(t)}&=&\vec\nu^{(t)}, &&(i)\\
 u_{t,j}&\in& \{a,b,c\} &\Rightarrow \hspace*{0.6cm} & z_{t,j}&=&u_{t,j}
 &(\mbox{\rm for all }j\geq 1),&(ii)\\
 u_{t,j}&=&d & \Rightarrow & z_{t,j}&=&c &(\mbox{\rm for all }j\geq 1).\hspace*{0.4cm}&(iii)\\
\end{array}$

\vspace{0.2cm}

\noindent Note, that the symbol $\Rightarrow$ is here used to denote an implication in our metatheory. For the initial configurations, these relationships hold if we assume that $t=1$ is valid in this case. Therefore, the assumption holds for the base case $t=1$. If, for a $t\geq 1$, the relationships $(i)$ to $(iii)$ and, thus,

\vspace{0.2cm}

 \noindent\quad$\!z_{t,j}\in r_a$ \, $\Leftrightarrow$ \, $u_{t,j}\in r_a$ \,\,\,\,{\em and} \,\, $z_{t,j}\in r_b$ \, $\Leftrightarrow$ \, $u_{t,j}\in r_b$ 

\vspace{0.2cm}

\noindent hold (where $\Leftrightarrow$ refers to an equivalence), then a further step of the execution of ${\cal M}$ leads to the relationships 

\vspace{0.1cm}

$\begin{array}{lclllcll} 
 \ell'_{t+1}&=&\ell_{t+1}, \hspace*{0.86cm} &&\vec\mu^{( t+1)}&=&\vec\nu^{( t+1)}, \\
 u_{t+1,j}&\in& \{a,b,c\} &\Rightarrow \hspace*{0.6cm} & z_{t+1,j}&=&u_{t+1,j}
 &(\mbox{\rm for all }j\geq 1),\\
 u_{t+1,j}&=&d & \Rightarrow & z_{t+1,j}&=&c &(\mbox{\rm for all }j\geq 1).\\
\end{array}$
\vspace{0.2cm}

 \noindent This means by induction that there holds $\ell_{t}=\ell'_{t}$ for any $t\geq 1$ which implies that both resulting computation paths are finite or both paths are infinite. Because this contradicts our assumption, ${\rm id}_{U_{{\cal A}_2}}$ is not in ${\rm SDEC}_{{\cal A}_2}$.
\end{example}

\begin{example}[A structure with $(e)$ in which $(d)$ does not hold]\label{CounterEx3}\hfill 

\noindent Let ${\cal A}_3$ be the finite structure $(\{a,b,c,d\} ;c,d ;; r_a,r_b)$ of signature $(2;\!;1,1)$ in ${\sf Struc}_{c,d}$ that contains four elements, the constants $c$ and $d$, and two unary relations $r_a$ and $r_b$ given by $r_a=\{a\}$ and $ r_b= \{b\}$. $\{c,d\}$ is semi-decidable by a BSS RAM ${\cal M}_{c,d}\in {\sf M}_{{\cal A}_3}$ using the following program ${\cal P}_{{\cal M}_{c,d}}$.

\vspace{0.1cm}

{\sf 
\begin{tabular}{ll}
\qquad\quad $\ell_1: \, \, I_2:=I_2+1;$ \, $\ell_1+1:$\, if $I_1=I_2$ then goto $\ell_2$ else goto $\ell_1+1;$\\
\qquad\quad $\ell_2 : \,\,$ if $r_1^{1}(Z_2)$ then goto $\ell_2$ else goto $\ell_3;$ \\
\qquad\quad $\ell_3 : \,\,$ if $r_2^{1}(Z_2)$ then goto $\ell_3$ else goto $\ell_4;$ \\
\qquad\quad$\ell_4: \, \, $ stop. \\
\end{tabular}}

\vspace{0.1cm}

\noindent Note, that $U_{{\cal A}_3}^\infty\setminus \{c,d\}$ is also semi-decidable by a BSS RAM. ${\cal M}_{a,b}^*\in {\sf M}_{{\cal A}_3}$ semi-decides $\{a,b\}\cup (U_{{\cal A}_3}^\infty\setminus U_{{\cal A}_3})$ by using the following program ${\cal P}_{{\cal M}_{a,b}^*}$.

\vspace{0.1cm}

{\sf 
\begin{tabular}{ll}
\qquad\quad $\ell_1: \, \, I_2:=I_2+1;$ \, \, if $I_1=I_2$ then goto $\ell_2$ else goto $\ell_4;$\\
\qquad\quad $\ell_2 : \,\,$ if $r_1^{1}(Z_2)$ then goto $\ell_4$ else goto $\ell_3;$ \\
\qquad\quad $\ell_3 : \,\,$ if $r_2^{1}(Z_2)$ then goto $\ell_4$ else goto $\ell_3;$ \\
\qquad\quad$\ell_4: \, \, $ stop. \\
\end{tabular}}

\vspace{0.4cm}

\noindent {\bf Why is $(d)$ not true in ${\cal A}_3$?} Let us assume that there is a machine ${\cal M}\in {\sf M}_{{\cal A}_3}$ that halts for input $c\in \{c\}$ and that does not halt for the input $d\not\in \{c\}$. For the constant $c$ and the constant $d$ as inputs, the corresponding initial configurations $con_{1}$ and $con'_{1}$ are given by $con_{1}=(1\,.\,(1,1,\ldots,1)\,.\,(c,c,c,\ldots))$ and $con'_{1}=(1\,.\,(1,1,\ldots,1)\,.\,(d,c,c,\ldots))$, respectively. For these initial configurations and both resulting sequences  $(con_t)_{t\geq 1} \in {\sf Con}_{{\cal M},c}$ and  $(con_t')_{t\geq 1} \in  {\sf Con}_{{\cal M},d}$  given, for $t\geq 2$, by the configurations $con_{t}$ and $con'_{t}$ with 
 $con_{t}= (\ell_{t}\,.\,\vec\nu^{(t)}\,.\,\bar u^{(t)})$ and $con'_{t}= (\ell'_{t}\,.\,\vec\mu^{(t)}\,.\,\bar z^{(t)})$, we have $\ell_t=\ell_t'$, $\vec\nu^{(t)}=\vec\mu^{(t)}$, and

\vspace{0.1cm}

 \hspace*{0.53cm}$u_{t,j}\not \in r_a$ \, {\rm and} \, $z_{t,j}\not \in r_a$ \, {\rm and} \,
$u_{t,j}\not \in r_b$ \, {\rm and} \, $z_{t,j}\not \in r_b$ 

\vspace{0.1cm}

\noindent for all $j\geq 1$ and all $t\geq 1$ which implies, among others, $\ell_{t+1}=\ell'_{t+1}$ for any $t\geq 1$ and, consequently, the result is again that both corresponding computation paths end with $\ell_{{\cal P}_{\cal M}} $ or both paths are infinite. Because this is a contradiction to our assumption, the set $\{c\}$ is not in ${\rm SDEC}_{{\cal A}_3}$.
\end{example}
\subsubsection{The decidability of semi-decidable single-element sets}\label{FromSemiToDecSecI} 
The structure ${\cal A}_2$ (in Example \ref{CounterEx2}) was in particular considered to give an example for single-element sets containing one constant and being semi-decidable. However, it is also easy to see that the sets of this kind are even decidable. The next proposition states that this is no coincidence and holds for any single-element set. Statements such as the following can be proved by using basic knowledge of classical first-order logic. For more theoretical details, see our {\sf special part on program and computation paths}.

\begin{proposition}[Recognizing an individual implies decidability]\label{SemiDeci}\hfill 

\noindent Let ${\cal A}$ be a structure in $ {\sf Struc}$ and $x_0\in U_{\cal A}$.

 The semi-decidability of $\{x_0\}$ by a BSS RAM in ${\sf M}_{\cal A}$ implies the semi-decidability of the complement of $\{x_0\}$  over ${\cal A}$ and thus  $\{x_0\}\in {\rm DEC}_{\cal A}$. 
\end{proposition}
{\bf Proof.} Let ${\cal M}$ be a BSS RAM in ${\sf M}_{\cal A}$ that semi-decides $\{x_0\}$ which means that $H_{\cal M}=\{x_0\}$ holds. Then, ${\cal M}$ goes, for input $x_0\in U_{\cal A}$ and only for $x_0$, through a finite computation path $(\ell_{x_0,t})_{t=1..s} $ which means that $\ell_{x_0,t}\in \{1,\ldots, \ell_{{\cal P}_{\cal M}}\}$ and $\ell_{x_0,s}=\ell_{{\cal P}_{\cal M}}$ hold. Let this path be determined by the sequence $(con_{x_0,t})_{t\geq 1} \in {\sf Con}_{{\cal M},x_0}$ given by  $con_{x_0,t}= (\ell_{x_0,t}\,.\,\vec\nu^{(x_0,t)}\,.\,\bar u^{(x_0,t)})$ and $\vec\nu^{(x_0,t)} \in \bbbn_+^{k_{\cal M}}$ for all $t\geq 1$. Consequently, there holds $con_{x_0,1}=(1\,.\,(1,\ldots,1)\,.\,(x_0,x_0,\ldots))$ where $(1,\ldots,1)$ stands for $\vec\nu^{(x_0,1)} \in \{1\}^{k_{\cal M}}$. For all other inputs $\vec x\in U_{\cal A}^\infty$ (which means $\vec x\not =x_0$), ${\cal M}$ does not halt and $\vec x$ thus traverses an infinite computation path $(\ell_{\vec x,t})_{t\geq 1} $ determined by $(con_{\vec x,t})_{t\geq 1} \in {\sf Con}_{{\cal M},\vec x}$ with $con_{\vec x,t}= (\ell_{\vec x,t}\,.\,\vec\nu^{(\vec x,t)}\,.\,\bar u^{(\vec x,t)})$ and $\ell_{x_0,t}\not=\ell_{{\cal P}_{\cal M}}$ for all $t\geq 1$. This means that there is a $t$ with $\ell_{\vec x,t}\not = \ell_{x_0,t}$. Let $t_{\vec x}$ be the smallest integer $t$ of this kind. Consequently, $\ell_{\vec x,t_{\vec x}-1} = \ell_{x_0,t_{\vec x}-1}$ holds and $\ell_{x_0,t_{\vec x}-1}$ is the label of an instruction in ${\cal P}_{\cal M}$ that is of type (4) or (5). This implies that the complement $U_{\cal A}^\infty \setminus\{x_0\}$ can be semi-decided by using a BSS RAM ${\cal M}^{\rm c}_{x_0}\in {\sf M}_{\cal A}$ whose program is given in Overview \ref{SemiOver1} and includes the program segment ${\cal P}_{(s+1)}$ defined in Overview \ref{SemiOver0}. For the use of $ {\cal L}_{{\cal M},{\rm T}}, {\cal L}_{{\cal M},{\rm H}_{\rm T}}, \ldots$ consisting of all the labels for instructions of type $(4), (5), \ldots$ , see \cite{GASS20} and \cite{GASS25A}.
\begin{overview}
[From $\{x_0\}\in {\rm SDEC}_{\cal A}$ to segments ${\cal P}_{(s+1)}$ and ${\cal P}_{(s+2)}$]\label{SemiOver0}

\hfill

\nopagebreak 

\noindent \fbox{\parbox{11.8cm}{

Let the program ${\cal P}_{\cal M}$ of ${\cal M}$ semi-deciding $\{x_0\}$ be of the form \textcolor{blue}{$(*)$} and let

\vspace{0.1cm}

\quad $\ell_{x_0,1}:$ {\sf instruction}$_{\ell_{x_0,1}}; \,\ldots;\quad \ell_{x_0,s-1}:$ {\sf instruction}$_{\ell_{x_0,s-1}}; \,\,\textcolor{red}{\ell_{x_0,s}}\,: {\sf stop}.$ \,\,$\textcolor{blue}{(*_{x_0})}$

\vspace{0.1cm}

be the sequence of labeled instruction resulting from 
 $(\ell_{x_0,t}) _{t=1.. s}$ and 
 ${\cal P}_{\cal M}$. 

\vspace{0.1cm}

Let, for $i \in \{1,2\}$, ${\cal P}_{(s+i)}$ be the program segment

\vspace{0.1cm}

\hspace{1.19cm} $1:$ {\sf instruction}$_{1}'; \quad \ldots;\quad s-1:$ {\sf instruction}$_{s-1}';$

\vspace{0.1cm}

derived from $\textcolor{blue}{(*_{x_0})}$ such that each of the new labeled instructions

\vspace{0.1cm}

\hspace{1.19cm} $t:$ {\sf instruction}$_{t}'$ \hfill (for $t\in \{ 1,\ldots, s-1\}$)\, 

\vspace{0.05cm}

results

\vspace{0.1cm}

