\subsection{Different non-determinisms and relationships}\label{SecDifferent}

 We will see that ${\rm SDEC}_{\cal A} \subseteq ({\rm SDEC}_{\cal A}^\nu)^Q={\rm SDEC}_{\cal A}^{\rm DND}\subseteq{\rm SDEC}_{\cal A}^{\rm ND}$ is valid if one of the properties $(a)$ to $(e)$ in Proposition \ref{BasicProp} and $Q=\{c_1,c_2\}^\infty$ or $Q=\{c_1,c_2\}^2$ hold.  It is, for example, easy to show that $({\rm SDEC}_{\cal A}^\nu)^Q={\rm SDEC}_{\cal A}^{\rm NDB}$ holds if ${\cal A}\in{\sf Struc}_{c_1,c_2}$ contains the identity relation. 
\begin{proposition}[Basic properties: Semi-decidable problems]\label{BasicPropSemiD}
\hfill 


\noindent Let ${\cal A}$ $\in{\sf Struc}_{c_1,c_2}$, $\{c_1,c_2\}\in {\rm SDEC}_{\cal A}$, $Q=\{c_1,c_2\}^\infty$ or $Q=\{c_1,c_2\}^2$, $P\subseteq U_{\cal A}^\infty$, and 

\vspace{0.2cm}
\qquad \begin{tabular}{lcllcl}
 \quad &{\rm (i)}& $P\in {\rm SDEC}_{\cal A}$,
& {\rm (iii)}& $ P\in {\rm SDEC}_{\cal A}^{\rm DND}$, \\ 
& {\rm (ii)}& $P\in ({\rm SDEC}_{\cal A}^\nu)^Q$, \hspace{0.7cm}
& {\rm (iv)}& $ P\in {\rm SDEC}_{\cal A}^{\rm ND}$.
\end{tabular} 

\vspace{0.3cm}

 Then, \quad {\rm (i)} implies {\rm (ii)}, \quad {\rm (ii)} implies {\rm (iii)}, \quad and \quad {\rm (iii)} implies {\rm (iv)}.
\end{proposition}

Instead of proving this proposition directly, we compare the classes of result functions for the machines in ${\sf M}_{\cal A}^{\rm NDB}$, ${\sf M}_{\cal A}^{\nu}(Q)$, $ {\sf M}_{\cal A}^{{\rm DND}}, \ldots$ for structures ${\cal A}\in{\sf Struc}_{c_1,c_2}$. In this way, we also provide the proofs for \cite[Theorem 2.8]{GASS25A} and \cite[Theorem 2.10]{GASS25A} and characterize in particular Moschovakis' operator applied to oracle sets $Q=\{c_1,c_2\}^\infty$ or $Q=\{c_1,c_2\}^2$.
\begin{theorem}[Digitally non-deterministic computability]\label{TheoDigitOracle}\hfill

\noindent Let ${\cal A}$ be a structure in ${\sf Struc}_{c_1,c_2}$, let  $Q=\{c_1,c_2\}^\infty$, and let $Q\in {\rm SDEC}_{\cal A}$. Then, there holds

\vspace{0.3cm}

 \quad  $\{{\rm Res}_{\cal M}\mid {\cal M}\in {\sf M}_{\cal A}^\nu(Q)\}=\{{\rm Res}_{\cal M}\mid {\cal M}\in {\sf M}_{\cal A}^{\rm DND}\}$.
\end{theorem}
{\bf Proof.} This equation can be derived analogously to the equation in Theorem 4.7 in Part II\,a\, by using the ideas of the proofs of Theorems 4.4 and 4.6. \qed

\vspace{0.3cm}

Since $\{c_1,c_2\}^\infty\in {\rm SDEC}_{\cal A}$ is valid if and only if $\{c_1,c_2\}\in {\rm SDEC}_{\cal A}$ is valid, we have the following. 

\begin{corollary} [Digitally non-deterministic computability]\label{CoroDigitOracle} \hfill 

\noindent  Let ${\cal A}$ be  in $ {\sf Struc}_{c_1,c_2}$, $Q_0=\{c_1,c_2\}^2$, and $\{c_1,c_2\}\in {\rm SDEC}_{\cal A}$. Then, there holds

\vspace{0.2cm}

 \quad $\{{\rm Res}_{\cal M}\mid {\cal M}\in {\sf M}_{\cal A}^\nu(Q_0)\}=\{{\rm Res}_{\cal M}\mid {\cal M}\in {\sf M}_{\cal A}^{\rm DND}\}$.
\end{corollary}

\begin{theorem}[Restriction of guesses]\label{TheoDND_ND}\hfill


\noindent Let ${\cal A}\in {\sf Struc}_{c_1,c_2}$ and $\{c_1,c_2\}\!\in {\rm SDEC}_{\cal A}$. Then, there holds


\vspace{0.3cm}

 \quad $\{{\rm Res}_{\cal M}\mid {\cal M}\in {\sf M}_{\cal A}^{\rm DND}\}\subseteq \{{\rm Res}_{\cal M}\mid {\cal M}\in {\sf M}_{\cal A}^{\rm ND}\}$. 
\end{theorem}
{\bf Proof.} Any ${\cal M}\in {\sf M}_{\cal A}^{\rm DND}$ can be simulated by a machine ${\cal N}_{\cal M}\in {\sf M}_{\cal A}^{\rm ND}$ that executes a subprogram for recognizing whether a value is in $\{c_1,c_2\}$ before one of the guesses is used. ${\cal N}_{\cal M}$ loops forever if such a guessed value does not belong to $\{c_1,c_2\}$.\qed

\begin{corollary}\label{CoroDND_ND} Let ${\cal A}\in {\sf Struc}_{c_1,c_2}$ and let one of the properties $(a)$ to $(e)$ in Proposition \ref{BasicProp} hold. Then, there holds

\vspace{0.3cm}

 \quad ${\rm SDEC }_{\cal A}^{\rm DND}\subseteq {\rm SDEC }_{\cal A}^{\rm ND}$. 
\end{corollary}

\begin{theorem}[Binary non-deterministic computability]\label{BinaryOracle}\hfill 


\noindent Let ${\cal A}$ be in ${\sf Struc}_{c_1,c_2}$ and $Q=\{c_1,c_2\}^\infty$. Then, there holds

\vspace{0.3cm}

 \quad  $\{{\rm Res}_{\cal M}\mid {\cal M}\in {\sf M}_{\cal A}^\nu(Q)\}\subseteq \{{\rm Res}_{\cal M}\mid {\cal M}\in {\sf M}_{\cal A}^{\rm NDB}\}$. 
\end{theorem}
{\bf Proof.} Any ${\cal M}\in {\sf M}_{\cal A}^\nu(Q) $ can be simulated by an ${\cal N}_{\cal M}$ in ${\sf M}_{\cal A}^{\rm NDB}$ that simulates the execution of each program segment \fbox{$\ell_i:\,\, Z_j:=\nu[{\cal O}](Z_1,\ldots,Z_{I_1})$;} in ${\cal P}_{\cal M}$ (with $1\leq i\leq s<\ell_{{\cal P}_{\cal M}}$)
by executing 

\vspace{0.2cm}

{\sf \hspace{0.3cm} $\ell_i:\, $ {\sf goto $\ell_i'$ or goto $\ell_i'';$}

\hspace{0.3cm} $ \ell_i':\, Z_j:= c_1^0;$ goto $\ell_i+1$ or goto $\ell_i+1; $ 

\hspace{0.24cm} $ \ell_i'':\, Z_j:= c_2^0;$ goto $\ell_i+1$ or goto $\ell_i+1;$}

\vspace{0.3cm}

\noindent where we again assume that $\ell_i'$ and  $\ell_i''$ are new labels for all $i\in \{1,\ldots, s\}$ such that $\bigcap_{i=1}^{s}\{\ell_i',\ell_i''\}\cap {\cal L}_{\cal M}=\emptyset$ holds. 
\qed

\begin{theorem}[Identity and oracle instructions]\label{IdentBinary} \hfill

\noindent Let ${\cal A}\in {\sf Struc}_{c_1,c_2}$, let ${\cal A}$ contain ${\rm id}_{\cal A}$, and let $Q=\{c_1,c_2\}^\infty$. Then, there holds

\vspace{0.3cm}

\quad $\{{\rm Res}_{\cal M}\mid {\cal M}\in {\sf M}_{\cal A}^{\rm NDB}\} \subseteq \{{\rm Res}_{\cal M}\mid {\cal M}\in {\sf M}_{\cal A}^\nu(Q)\}$. 
\end{theorem}
