\title[]{The effect of doping layers position on the heterojunction sharpness in (In,Al)As/AlAs quantum dots}
% Force line breaks with \\

\author{T. S. Shamirzaev}
\email{tim@isp.nsc.ru}
\affiliation{Rzhanov Institute of Semiconductor Physics\unskip, Siberian Branch of the Russian Academy of Sciences\unskip, 630090\unskip, Novosibirsk\unskip, Russia}
\author{D. R. Yakovlev}
